    public sealed class PackTextureAtlasBatchService
    {
        private const string AtlasDirectory = @"textures\asset_editor\atlases";
        private const string AtlasProfilingEnvironmentVariable = "ASSET_EDITOR_ATLAS_PROFILING";
        private const int PackAtlasMaxSize = 4096;
        private const double TexelDensityReferencePercentile = 0.75;
        private const double TexelDensityOutlierMultiplier = 1.5;
        private const double MinAtlasResolutionScale = 0.25;
        private const int MinAtlasResolutionScaleDimension = 256;
        // Calibrated from the !ak_teb3 value curve: preserve almost all expected
        // battle draw savings while rejecting expensive low-value atlas batches.
        private const long MaxNetBcnBytesPerExpectedArmyDraw = 256L * 1024; // 0.25 MiB
        private const long MaxNetBcnBytesPerFallbackDraw = 8L * 1024 * 1024;
        // A texture-only atlas has no geometry-merge draw credit. Permit it only when it
        // retires multiple source textures from the source pack's references and its net
        // payload growth is small per retired texture (or meaningfully displaces modeled
        // battle residency).
        private const long MaxNetBcnBytesPerRetiredSourceTexture = 512L * 1024; // 0.5 MiB
        private const int MinimumRetiredSourceTexturesForTextureOnlyAtlas = 2;
        // A prospective texture merge does eliminate a real geometry draw, even when the
        // original source textures remain reachable through other materials. Give that
        // structural draw a bounded floor plus scenario-proportional credit, while keeping
        // the cumulative pack-growth cap below.
        private const long MaxNetBcnBytesPerTextureOnlyMergeDraw = 4L * 1024 * 1024; // 4 MiB
        private const long MaxNetBcnBytesPerTextureOnlyMergeExpectedArmyDraw =
            768L * 1024; // 0.75 MiB
        // A texture-consolidation atlas keeps geometry and draw credit unchanged. Permit it
        // only when it replaces multiple real texture assignments at a tighter payload cost.
        private const long MaxNetBcnBytesPerConsolidatedTextureAssignment = 256L * 1024; // 0.25 MiB
        private const int MinimumConsolidatedTextureAssignmentsForAtlas = 2;
        // Large planner batches can force a power-of-two atlas allocation for unrelated
        // texture assignments. Start texture-consolidation scoring in small cohorts and
        // recursively split cohorts whose marginal residency is still too expensive.
        private const int TextureConsolidationInitialCohortCandidateLimit = 8;
        // Prospective texture-merge groups can contain unrelated large placements. Search
        // bounded pairs/triples/four-way subsets before giving up on the whole group.
        private const int TextureOnlyMergeSubsetCandidateLimit = 10;
        private const int TextureOnlyMergeSubsetOptionLimit = 128;
        // Reserve part of the subset budget for four-way combinations. Pair/triple options
        // remain the broad first pass; four-way options are most useful when the full group
        // is too expensive but a compact four-mesh subset can still pass the value gate.
        private const int TextureOnlyMergeFourWaySubsetOptionReserve = 32;
        private const int TextureOnlyMergeNearMissLimit = 24;
        private const double AtlasValueGateExpectedDrawEpsilon = 0.000001;
        private const double MaxReachableBcnGrowthRatio = 0.50;
        // Cross-rigid generated assets are selected independently from atlas BCn. Runtime
        // residency and physical pack growth are constrained across the selected portfolio,
        // so cheap payloads can create headroom for individually more expensive payloads
        // without relaxing the final per-benefit limits. A hard cumulative growth cap still
        // bounds absolute pack expansion. Multi-VMD payload reuse is rewarded naturally
        // because all rewrite-plan benefit is aggregated before geometry is charged once.
        private const long MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw =
            512L * 1024; // 0.5 MiB
        private const long MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw =
            16L * 1024 * 1024; // 16 MiB
        private const long MaxCrossRigidGeneratedGeometryGrowthBytes =
            256L * 1024 * 1024; // 256 MiB
        private const double MinimumCrossRigidSingleVmdExpectedArmyDraw = 0.02;
        // Limit exact generated joint appearance states, not probability precision.
        // Large VMDs need more room than 512 combinations, while the
        // portfolio's geometry and residency budgets still cap output cost.
        private const int MaxCrossRigidJointStateCombinations = 1024;
        // When a full co-rendering group is too complex to rewrite jointly,
        // smaller cross-rigid pairs can retain independent visual choices.
        private const int MaxCrossRigidPairFallbacksPerGroup = 24;
        // A bounded three-rigid alternative can recover savings from a
        // full group whose Cartesian appearance space is too large.
        private const int MaxCrossRigidTripleFallbacksPerGroup = 32;
        // Four components can recover merges from otherwise unwritable five+
        // component groups without expanding the global Cartesian writer.
        private const int MaxCrossRigidQuadrupleFallbacksPerGroup = 24;
        // Small five-component subsets can recover four draws when the full
        // appearance group is too large to rewrite as one Cartesian state.
        private const int MaxCrossRigidQuintupleFallbacksPerGroup = 12;
        private const int MaxCrossRigidGeneratedLodCount = 5;
        private const float CrossRigidLodDistanceEpsilon = 0.01f;
        private static readonly bool AtlasProfilingEnabled =
            IsEnabledEnvironmentVariable(AtlasProfilingEnvironmentVariable);

        private static readonly (string Slot, TextureType Type, string Suffix)[] AtlasChannels =
        [
            ("t_xml_base_colour", TextureType.BaseColour, "base_colour"),
            ("t_xml_material_map", TextureType.MaterialMap, "material_map"),
            ("t_xml_normal", TextureType.Normal, "normal"),
            ("t_xml_mask", TextureType.Mask, "mask"),
        ];

        private const long MaxAutomaticCommonTextureConstantProbePixels = 4096;
        private const string CanonicalBlackMaskTexturePath =
            @"commontextures\default_black.dds";
        private const string CanonicalFaction3MaskChannelValue = "0,0,1,0";
        private static readonly TextureAtlasConstantColor ZeroMaskColor =
            new(0, 0, 0, 0);

        private static readonly HashSet<string> KnownConstantTexturePaths =
        [
            CanonicalBlackMaskTexturePath,
            @"commontextures\default_white.dds",
            @"commontextures\default_normal.dds",
        ];

        private readonly IPackFileService _packFileService;
        private readonly IPackFileContainerLoader _packFileContainerLoader;
        private readonly ApplicationSettingsService _settingsService;
        private readonly IStandardDialogs _standardDialogs;

        public PackTextureAtlasBatchService(
            IPackFileService packFileService,
            IPackFileContainerLoader packFileContainerLoader,
            ApplicationSettingsService settingsService,
            IStandardDialogs standardDialogs)
        {
            _packFileService = packFileService;
            _packFileContainerLoader = packFileContainerLoader;
            _settingsService = settingsService;
            _standardDialogs = standardDialogs;
        }

        public void Run()
        {
            if (_settingsService.CurrentSettings.CurrentGame != GameTypeEnum.Warhammer3)
            {
                _standardDialogs.ShowDialogBox(
                    "Pack texture atlasing currently supports Warhammer 3 packs only.",
                    "Texture Atlas Pack");
                return;
            }

            var browse = _standardDialogs.ShowSystemOpenFileDialog(false, "Pack files|*.pack");
            if (!browse.Result || browse.FilePaths.Count == 0)
                return;

            var sourcePath = browse.FilePaths[0];
            var outputPath = BuildOutputPath(sourcePath);

            BatchResult? result = null;
            var progressWindow = new TextureAtlasProgressWindow((
                mergeCompatibleMeshes,
                shareAtlasesAcrossVmds,
                optimizeGeometry,
                atlasAllVmds,
                scoreAllGameUnits,
                crossRigidOnly,
                cancellationToken,
                progress) =>
            {
                result = Process(
                    sourcePath,
                    outputPath,
                    atlasMeshesWithMissingTextures: null,
                    cancellationToken: cancellationToken,
                    progress: progress,
                    mergeCompatibleMeshes: mergeCompatibleMeshes,
                    shareAtlasesAcrossVmds: shareAtlasesAcrossVmds,
                    optimizeGeometry: optimizeGeometry,
                    atlasAllVmds: atlasAllVmds,
                    scoreAllGameUnits: scoreAllGameUnits,
                    crossRigidOnly: crossRigidOnly);
            });

            if (System.Windows.Application.Current?.MainWindow != null)
                progressWindow.Owner = System.Windows.Application.Current.MainWindow;

            progressWindow.ShowDialog();

            if (progressWindow.Failure != null)
            {
                _standardDialogs.ShowExceptionWindow(
                    progressWindow.Failure,
                    "Failed to create texture atlas pack.");
                return;
            }

            if (progressWindow.WasCancelled || result == null)
                return;

            _standardDialogs.ShowDialogBox(
                $"Texture atlas pack created successfully.\n\n" +
                $"Output: {outputPath}\n" +
                $"Atlas VMD roots: {result.VmdCount}\n" +
                $"Mesh parts atlased: {result.AtlasedMeshCount}\n" +
                $"Atlas textures generated: {result.GeneratedTextureCount}\n" +
                $"Unused asset files removed: {result.RemovedFileCount}\n" +
                $"Mesh parts skipped: {result.SkippedMeshCount}\n" +
                $"Report: {result.ReportPath}",
                "Texture Atlas Pack");
        }

        public BatchResult Process(
            string sourcePath,
            string outputPath,
            bool? atlasMeshesWithMissingTextures = false,
            CancellationToken cancellationToken = default,
            IProgress<TextureAtlasPackProgress>? progress = null,
            bool mergeCompatibleMeshes = false,
            bool shareAtlasesAcrossVmds = true,
            bool optimizeGeometry = false,
            bool atlasAllVmds = false,
            bool scoreAllGameUnits = false,
            bool lodAwareAtlasPlanning = true,
            bool crossRigidOnly = false)
        {
            // Kept for API compatibility with existing callers. Atlasing meshes with genuine
            // unresolved secondary textures is no longer allowed because UV0 is shared.
            _ = atlasMeshesWithMissingTextures;

            var reportPath = BuildReportPath(outputPath);
            var totalStopwatch = Stopwatch.StartNew();
            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(progress, "Loading source pack", item: Path.GetFileName(sourcePath));
            IPackFileContainer? output = null;
            BatchState? state = null;
            List<string> vmdRoots = [];
            List<MalformedVmdEntry> malformedVmdRoots = [];

            try
            {
                var source = _packFileContainerLoader.CreateFromPackFile(
                    PackFileContainerType.Normal,
                    sourcePath,
                    loadAsReadOnly: true);
                cancellationToken.ThrowIfCancellationRequested();

                var sourcePaths = source.GetAllFiles().Keys.ToList();

                var outputName = Path.GetFileNameWithoutExtension(outputPath);
                output = _packFileService.CreateNewPackFileContainer(
                    outputName,
                    PackFileVersion.PFH5,
                    PackFileCAType.MOD,
                    setEditablePack: false);
                state = new BatchState(
                    source,
                    output,
                    _packFileService,
                    sourcePath,
                    outputPath,
                    reportPath,
                    mergeCompatibleMeshes,
                    shareAtlasesAcrossVmds,
                    optimizeGeometry);
                state.LodAwareAtlasPlanningEnabled = lodAwareAtlasPlanning;
                state.CrossRigidOnly = crossRigidOnly;
                state.CancellationToken = cancellationToken;
                state.Progress = progress;
                var gameplayContainerSnapshot =
                    _packFileService.GetAllPackfileContainers().ToList();
                state.GameplayTraversalContainers = gameplayContainerSnapshot;
                state.VanillaAtlasConsumerCache =
                    Wh3VanillaAtlasConsumerCache.Load(
                        _settingsService,
                        gameplayContainerSnapshot);
                state.ExistingAtlasOutputDetected = HasGeneratedAtlasOutput(source);

                var allVmdPaths = sourcePaths
                    .Where(x => Path.GetExtension(x).Equals(".variantmeshdefinition", StringComparison.OrdinalIgnoreCase))
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToList();

                if (allVmdPaths.Count == 0)
                    throw new InvalidOperationException("The selected pack contains no .variantmeshdefinition files.");

                ReportProgress(
                    progress,
                    "Validating VMD roots",
                    item: $"{allVmdPaths.Count} VMD file(s)");
                var phaseStopwatch = Stopwatch.StartNew();
                (vmdRoots, malformedVmdRoots) = ValidateVmdRoots(
                    state,
                    source,
                    allVmdPaths,
                    cancellationToken,
                    progress);
                state.PhaseDurations["Validate VMD roots"] = phaseStopwatch.Elapsed;

                if (vmdRoots.Count == 0)
                {
                    throw new InvalidOperationException(
                        $"The selected pack contains {allVmdPaths.Count} .variantmeshdefinition file(s), " +
                        "but none could be parsed.");
                }

                ReportProgress(
                    progress,
                    "Resolving unit categories",
                    item: $"{vmdRoots.Count} VMD root(s)");
                phaseStopwatch.Restart();
                var childVmdsByVmd = BuildChildVmdDependencyMap(
                    state,
                    source,
                    vmdRoots,
                    cancellationToken);
                // Residency accounting always needs the complete game roster. Mutation is
                // still restricted to the selected pack; culture scoping happens inside the
                // residency model so vanilla units can remain read-only consumers without
                // polluting a single mixed-culture army denominator.
                state.UnitCategoryResolution = Wh3UnitCategoryResolver.ResolveAgainstContainers(
                    source,
                    vmdRoots,
                    childVmdsByVmd,
                    cancellationToken,
                    Wh3ArmyVisualScenario.Default,
                    gameplayContainerSnapshot);
                if (!state.UnitCategoryResolution.IsGameplayResolutionHealthy)
                {
                    throw new InvalidOperationException(
                        "Atlas processing could not be resolved safely because gameplay " +
                        "mesh-consumer discovery requires a healthy WH3 DB/schema resolution: " +
                        state.UnitCategoryResolution.GameplayResolutionHealthMessage +
                        " Fix the WH3 DB/schema resolution problem before running atlas " +
                        "processing; pack-wide mode cannot bypass this safety gate.");
                }

                state.ArmyResidencyModel =
                    state.UnitCategoryResolution.IsGameplayResolutionHealthy
                        ? BuildArmyResidencyModel(
                            state,
                            state.UnitCategoryResolution,
                            includeAllGameCultures: scoreAllGameUnits)
                        : null;
                state.PhaseDurations["Resolve unit categories"] = phaseStopwatch.Elapsed;

                var gameplayEligibleVmdRoots = state.UnitCategoryResolution.UsagesByVmd.Keys
                    .Where(state.UnitCategoryResolution.IsVmdUsageComplete);
                var atlasVmdRoots = SelectAtlasVmdRoots(
                    vmdRoots,
                    gameplayEligibleVmdRoots,
                    atlasAllVmds);
                state.AtlasAllVmdsEnabled = atlasAllVmds;
                state.SourceVmdRootCount = vmdRoots.Count;
                state.AtlasVmdRootCount = atlasVmdRoots.Count;
                ReportProgress(
                    progress,
                    "Selecting atlas VMD population",
                    atlasVmdRoots.Count,
                    vmdRoots.Count,
                    atlasAllVmds
                        ? $"Pack-wide: {atlasVmdRoots.Count:N0} / {vmdRoots.Count:N0} VMD root(s)"
                        : $"Gameplay-used: {atlasVmdRoots.Count:N0} / {vmdRoots.Count:N0} VMD root(s)");

                ReportProgress(
                    progress,
                    "Scanning source dependencies",
                    item: malformedVmdRoots.Count == 0
                        ? $"{vmdRoots.Count} VMD root(s)"
                        : $"{vmdRoots.Count} valid VMD root(s), {malformedVmdRoots.Count} malformed file(s) ignored");
                phaseStopwatch.Restart();
                var assetDependencyRoots = vmdRoots
                    .Concat(
                        state.UnitCategoryResolution?.DirectAssetUsagesByPath.Keys ??
                        Array.Empty<string>())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var originalReachable = CollectReachableAssetFiles(
                    state,
                    source,
                    assetDependencyRoots,
                    cancellationToken,
                    progress,
                    "Scanning source dependencies");
                // The value gate must account for every source-root consumer, including
                // roots that are intentionally outside the atlas population. Otherwise a
                // texture shared by an atlased root and a non-atlased root can be credited as
                // retired even though the latter still keeps it reachable in the output.
                state.SourceReachableAssetFiles.UnionWith(originalReachable);
                state.PhaseDurations["Scan source dependencies"] = phaseStopwatch.Elapsed;

                phaseStopwatch.Restart();
                ReportProgress(
                    progress,
                    "Copying source pack",
                    0,
                    sourcePaths.Count,
                    $"{sourcePaths.Count:N0} files");

                var sourceFiles = source.GetAllFiles();
                var bulkCopyEntries = new List<NewPackFileEntry>(sourcePaths.Count);
                foreach (var sourcePathEntry in sourcePaths)
                {
                    cancellationToken.ThrowIfCancellationRequested();

                    if (!sourceFiles.TryGetValue(sourcePathEntry, out var sourceFile))
                        continue;

                    // Keep unchanged files backed by the source IDataSource until the final save.
                    // This avoids eagerly reading/copying every file into a new MemorySource and
                    // also avoids the per-file logging/event overhead of CopyFileFromOtherPackFile.
                    var directory = Path.GetDirectoryName(sourcePathEntry) ?? string.Empty;
                    var fileName = Path.GetFileName(sourcePathEntry);
                    bulkCopyEntries.Add(new NewPackFileEntry(
                        directory,
                        new PackFile(fileName, sourceFile.DataSource)));
                }

                cancellationToken.ThrowIfCancellationRequested();
                _packFileService.AddFilesToPack(output, bulkCopyEntries);
                ReportProgress(
                    progress,
                    "Copying source pack",
                    sourcePaths.Count,
                    sourcePaths.Count,
                    $"{bulkCopyEntries.Count:N0} files copied");
                state.PhaseDurations["Copy source pack"] = phaseStopwatch.Elapsed;

                state.MalformedVmdRoots.AddRange(malformedVmdRoots);
                phaseStopwatch.Restart();
                if (crossRigidOnly)
                {
                    ReportProgress(
                        progress,
                        "Indexing gameplay mesh consumers",
                        item: "Cross-rigid-only mode");
                    IndexImmutableMeshMergeConsumers(
                        state,
                        vmdRoots,
                        cancellationToken);
                    state.PhaseDurations["Index gameplay mesh consumers"] =
                        phaseStopwatch.Elapsed;
                }
                else
                {
                    BuildWsUsageIndex(state, cancellationToken, progress);
                    IndexTaintedGameplayWsModels(state, cancellationToken);
                    // Direct rigid consumers constrain atlas rewrites as well as structural
                    // mesh merging. Discover them before atlas candidates even when the
                    // optional structural merge pass is disabled.
                    IndexImmutableMeshMergeConsumers(
                        state,
                        vmdRoots,
                        cancellationToken);
                    state.PhaseDurations["Index WSModels"] =
                        phaseStopwatch.Elapsed;

                    phaseStopwatch.Restart();
                    ReportProgress(progress, "Estimating source BCn residency");
                    state.SourceBcnResidency = CalculateBcnTextureResidency(
                        state,
                        source,
                        originalReachable,
                        cancellationToken);
                    state.PhaseDurations["Estimate source BCn residency"] =
                        phaseStopwatch.Elapsed;

                    phaseStopwatch.Restart();
                    var candidateDiscovery = DiscoverAtlasCandidates(
                        state,
                        atlasVmdRoots,
                        shareAtlasesAcrossVmds,
                        cancellationToken,
                        progress);

                    // UV0 is shared by every material texture channel. If any real
                    // secondary texture is unresolved, remapping UV0 while preserving that old
                    // texture path would make it sample with atlas UVs and corrupt rendering.
                    // Such meshes are therefore always skipped. The only unresolved sentinel
                    // normalized to "absent" earlier is t_xml_mask/test_mask.dds.
                    var discoveredCandidates = ApplyMissingTextureDecision(
                        state,
                        candidateDiscovery.Candidates);
                    state.AtlasValueGateCandidateTexturePaths.Clear();
                    state.AtlasValueGateCandidateTexturePaths.UnionWith(
                        GetAtlasValueGateCandidateTexturePaths(discoveredCandidates));
                    state.AtlasValueGateCandidateTexturePathsInitialized = true;
                    state.PhaseDurations["Discover atlas candidates"] =
                        phaseStopwatch.Elapsed;

                    if (mergeCompatibleMeshes)
                    {
                        phaseStopwatch.Restart();
                        AnalyzeCompatibleMeshMerges(
                            state,
                            cancellationToken,
                            progress);
                        state.PhaseDurations["Analyze structural mesh merges"] =
                            phaseStopwatch.Elapsed;
                    }

                    phaseStopwatch.Restart();
                    if (shareAtlasesAcrossVmds)
                    {
                        ProcessPackWideAtlases(
                            state,
                            discoveredCandidates,
                            cancellationToken,
                            progress);
                    }
                    else
                    {
                        for (var i = 0; i < atlasVmdRoots.Count; i++)
                        {
                            cancellationToken.ThrowIfCancellationRequested();
                            var rootCandidates = discoveredCandidates
                                .Where(x =>
                                    x.RootVmdPath.Equals(
                                        atlasVmdRoots[i],
                                        StringComparison.OrdinalIgnoreCase))
                                .ToList();
                            ProcessVmd(
                                state,
                                atlasVmdRoots[i],
                                rootCandidates,
                                cancellationToken,
                                progress);
                        }

                        ProcessDirectAssetAtlases(
                            state,
                            discoveredCandidates
                                .Where(IsDirectAssetCandidate)
                                .ToList(),
                            cancellationToken,
                            progress);
                    }

                    state.PhaseDurations["Plan and build atlases"] =
                        phaseStopwatch.Elapsed;
                }

                if (mergeCompatibleMeshes || crossRigidOnly)
                {
                    phaseStopwatch.Restart();
                    AnalyzeCrossRigidMergeOpportunities(
                        state,
                        atlasVmdRoots,
                        cancellationToken,
                        progress);
                    state.PhaseDurations["Analyze cross-rigid merges"] =
                        phaseStopwatch.Elapsed;

                    phaseStopwatch.Restart();
                    EmitSelectedCrossRigidMerges(
                        state,
                        cancellationToken,
                        progress);
                    state.PhaseDurations["Emit cross-rigid merges"] =
                        phaseStopwatch.Elapsed;

                    if (!crossRigidOnly)
                    {
                        phaseStopwatch.Restart();
                        MergeCompatibleMeshes(
                            state,
                            cancellationToken,
                            progress);
                        state.PhaseDurations["Merge compatible meshes"] =
                            phaseStopwatch.Elapsed;
                    }
                }

                if (optimizeGeometry && !crossRigidOnly)
                {
                    phaseStopwatch.Restart();
                    OptimizeGeometry(state, cancellationToken, progress);
                    state.PhaseDurations["Optimize geometry"] = phaseStopwatch.Elapsed;
                }

                phaseStopwatch.Restart();
                SaveModifiedDocuments(state, cancellationToken, progress);
                state.PhaseDurations["Write modified assets"] = phaseStopwatch.Elapsed;

                if (!crossRigidOnly)
                {
                    ReportProgress(progress, "Scanning rewritten dependencies");
                    phaseStopwatch.Restart();
                    var currentReachable = CollectReachableAssetFiles(
                        state,
                        output,
                        assetDependencyRoots,
                        cancellationToken,
                        progress,
                        "Scanning rewritten dependencies");
                    state.PhaseDurations["Scan rewritten dependencies"] =
                        phaseStopwatch.Elapsed;

                    phaseStopwatch.Restart();
                    PruneUnusedAssetFiles(
                        state,
                        originalReachable,
                        currentReachable,
                        cancellationToken,
                        progress);
                    state.PhaseDurations["Prune unused assets"] =
                        phaseStopwatch.Elapsed;

                    // The pre-prune dependency scan is needed to decide what to remove, but it
                    // still contains superseded source textures. Re-scan after pruning so the
                    // reported output residency and source-retirement accounting describe the
                    // pack that will actually be saved.
                    ReportProgress(progress, "Scanning final dependencies");
                    phaseStopwatch.Restart();
                    var finalReachable = CollectReachableAssetFiles(
                        state,
                        output,
                        assetDependencyRoots,
                        cancellationToken,
                        progress,
                        "Scanning final dependencies");
                    state.PhaseDurations["Scan final dependencies"] =
                        phaseStopwatch.Elapsed;

                    phaseStopwatch.Restart();
                    ReportProgress(progress, "Estimating output BCn residency");
                    state.OutputBcnResidency = CalculateBcnTextureResidency(
                        state,
                        output,
                        finalReachable,
                        cancellationToken);
                    state.PhaseDurations["Estimate output BCn residency"] =
                        phaseStopwatch.Elapsed;
                }

                phaseStopwatch.Restart();
                ValidateOutput(state, vmdRoots, cancellationToken, progress);
                state.PhaseDurations["Validate output"] = phaseStopwatch.Elapsed;

                cancellationToken.ThrowIfCancellationRequested();
                ReportProgress(progress, "Saving output pack", item: Path.GetFileName(outputPath));
                phaseStopwatch.Restart();
                var game = GameInformationDatabase.GetGameById(GameTypeEnum.Warhammer3);
                _packFileService.SavePackContainer(output, outputPath, false, game);
                state.PhaseDurations["Save output pack"] = phaseStopwatch.Elapsed;
                state.TotalElapsed = totalStopwatch.Elapsed;

                WriteReport(state, vmdRoots, succeeded: true, failure: null);

                return new BatchResult(
                    atlasVmdRoots.Count,
                    state.ProcessedMeshes.Count,
                    state.GeneratedTexturePaths.Count,
                    state.RemovedFiles.Count,
                    GetEffectiveSkippedMeshCount(state),
                    reportPath);
            }
            catch (OperationCanceledException)
            {
                throw;
            }
            catch (Exception ex)
            {
                if (state != null)
                {
                    state.TotalElapsed = totalStopwatch.Elapsed;
                    try
                    {
                        WriteReport(state, vmdRoots, succeeded: false, failure: ex);
                    }
                    catch
                    {
                        // Keep the original conversion/validation exception.
                    }
                }

                throw;
            }
            finally
            {
                state?.VanillaAtlasConsumerCache?.Save();
                if (output != null)
                    _packFileService.UnloadPackContainer(output, force: true);
            }
        }

        public static string BuildOutputPath(string sourcePath)
        {
            var directory = Path.GetDirectoryName(sourcePath) ?? string.Empty;
            var stem = Path.GetFileNameWithoutExtension(sourcePath);
            return Path.Combine(directory, stem + "_atlas.pack");
        }

        public static string BuildReportPath(string outputPath)
        {
            var directory = Path.GetDirectoryName(outputPath) ?? string.Empty;
            var stem = Path.GetFileNameWithoutExtension(outputPath);
            return Path.Combine(directory, stem + "_report.txt");
        }

        private static List<string> SelectAtlasVmdRoots(
            IReadOnlyList<string> validatedVmdRoots,
            IEnumerable<string> gameplayUsedVmds,
            bool atlasAllVmds)
        {
            if (atlasAllVmds)
                return validatedVmdRoots.ToList();

            var used = gameplayUsedVmds
                .Select(Normalize)
                .Where(path => path.Length != 0)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            return validatedVmdRoots
                .Where(path => used.Contains(Normalize(path)))
                .ToList();
        }

        private static (List<string> ValidRoots, List<MalformedVmdEntry> MalformedRoots) ValidateVmdRoots(
            BatchState state,
            IPackFileContainer source,
            IReadOnlyList<string> vmdPaths,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var validRoots = new List<string>(vmdPaths.Count);
            var malformedRoots = new List<MalformedVmdEntry>();

            for (var i = 0; i < vmdPaths.Count; i++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var path = Normalize(vmdPaths[i]);
                if (i == 0 || i == vmdPaths.Count - 1 || i % 25 == 0)
                {
                    ReportProgress(
                        progress,
                        "Validating VMD roots",
                        i + 1,
                        vmdPaths.Count,
                        path);
                }

                var file = source.FindFile(path);
                if (file == null)
                    continue;

                try
                {
                    _ = GetVmd(state, source, path, file);
                    validRoots.Add(path);
                }
                catch (Exception ex) when (
                    ex is InvalidOperationException or
                    XmlException or
                    FormatException or
                    ArgumentException)
                {
                    malformedRoots.Add(new MalformedVmdEntry(
                        path,
                        ex.Message.Replace("\r", " ").Replace("\n", " ")));
                }
            }

            return (validRoots, malformedRoots);
        }

        private void BuildWsUsageIndex(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var wsPaths = state.Source.GetAllFiles().Keys
                .Where(x => Path.GetExtension(x).Equals(".wsmodel", StringComparison.OrdinalIgnoreCase))
                .ToList();

            for (var wsIndex = 0; wsIndex < wsPaths.Count; wsIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var wsPath = wsPaths[wsIndex];
                if (wsIndex == 0 || wsIndex == wsPaths.Count - 1 || wsIndex % 10 == 0)
                {
                    ReportProgress(
                        progress,
                        "Indexing WSModels",
                        wsIndex + 1,
                        wsPaths.Count,
                        wsPath);
                }

                XmlDocument? doc;
                try
                {
                    doc = GetWsDocument(state, wsPath);
                }
                catch (Exception ex) when (
                    ex is InvalidOperationException or
                    XmlException or
                    FormatException or
                    ArgumentException)
                {
                    RecordMalformedWsModel(state, wsPath, ex);
                    continue;
                }

                if (doc == null)
                    continue;

                var geometryPath = Normalize(doc.SelectSingleNode("/model/geometry")?.InnerText);
                if (string.IsNullOrWhiteSpace(geometryPath) || state.Source.FindFile(geometryPath) == null)
                    continue;

                var materialNodes = doc.SelectNodes("/model/materials/material");
                if (materialNodes == null)
                    continue;

                foreach (XmlNode node in materialNodes)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!TryParseIndex(node, "lod_index", out var lodIndex) ||
                        !TryParseIndex(node, "part_index", out var partIndex))
                        continue;

                    var materialPath = Normalize(node.InnerText);
                    var key = new MeshKey(geometryPath, lodIndex, partIndex);
                    if (!state.Usages.TryGetValue(key, out var usages))
                    {
                        usages = [];
                        state.Usages[key] = usages;
                    }

                    usages.Add(new WsUsage(wsPath, doc, node, materialPath));
                }
            }
        }

        private static void IndexImmutableMeshMergeConsumers(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            CancellationToken cancellationToken)
        {
            var resolution = state.UnitCategoryResolution;
            var dependencyIndex = BuildGameplayMeshDependencyIndex(
                state,
                vmdRoots,
                cancellationToken);
            state.GameplayMeshDependencyIndex = dependencyIndex;

            state.ImmutableMeshMergeConsumersByRigid.Clear();
            state.DirectRigidMeshMergeConsumersByRigid.Clear();
            state.StructuralMergeConsumerDiscoveryFailures.Clear();
            state.ConsumerDiscoveryBlocks.Clear();
            foreach (var failure in dependencyIndex.BlockingFailureDetails)
            {
                state.StructuralMergeConsumerDiscoveryFailures.Add(
                    FormatGameplayMeshDependencyFailure(failure));
            }

            state.StructuralMergeConsumerDiscoveryComplete =
                resolution != null &&
                resolution.IsGameplayResolutionHealthy &&
                dependencyIndex.IsComplete;

            // These two dictionaries are retained as compact reporting/test views. The
            // dependency index is the authoritative topology and safety source.
            foreach (var (rigidPath, wsModelPaths) in dependencyIndex.WsModelConsumersByRigid)
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (!state.Source.ContainsFile(rigidPath))
                    continue;

                var immutableConsumers = wsModelPaths
                    .Where(path => !state.Source.ContainsFile(path))
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);
                if (immutableConsumers.Count != 0)
                {
                    state.ImmutableMeshMergeConsumersByRigid[rigidPath] =
                        immutableConsumers;
                }
            }

            foreach (var (rigidPath, rootConsumers) in dependencyIndex.DirectConsumersByRigid)
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (!state.Source.ContainsFile(rigidPath) || rootConsumers.Count == 0)
                    continue;

                state.DirectRigidMeshMergeConsumersByRigid[rigidPath] =
                    new HashSet<string>(
                        rootConsumers,
                        StringComparer.OrdinalIgnoreCase);
            }
        }

        private static GameplayMeshDependencyIndex BuildGameplayMeshDependencyIndex(
            BatchState state,
            IReadOnlyList<string> sourceVmdRoots,
            CancellationToken cancellationToken)
        {
            var resolution = state.UnitCategoryResolution;

            // bc8b75c9's UnitIdsByAssetPath is intentionally an army-planning index: units
            // outside the slot template or modeled cultures may be absent. Reuse that fast
            // population, but never treat it as the complete mutation-safety authority.
            var indexedGameplayAssets = state.ArmyResidencyModel?.UnitIdsByAssetPath.Keys
                .Where(IsMeshConsumerAssetPath)
                ?? Array.Empty<string>();

            // The resolver roster is the complete DB-derived visual population before the
            // residency model applies army/category/culture filters. Every resolved VMD
            // component remains a safety root because an excluded unit can still reference
            // an immutable CA WSModel sharing a source-owned rigid.
            var safetyRosterVmdRoots = resolution?.RosterUnits
                .SelectMany(unit => unit.Components)
                .Where(component => component.IsVariantMeshDefinition)
                .Select(component => component.AssetPath)
                .Where(path => !string.IsNullOrWhiteSpace(path))
                ?? Array.Empty<string>();

            var rootKindsByPath =
                new Dictionary<string, HashSet<GameplayMeshDependencyRootKind>>(
                    StringComparer.OrdinalIgnoreCase);

            void AddRoot(
                string pathValue,
                GameplayMeshDependencyRootKind rootKind)
            {
                var path = Normalize(pathValue);
                if (path.Length == 0)
                    return;

                if (!rootKindsByPath.TryGetValue(path, out var kinds))
                {
                    kinds = [];
                    rootKindsByPath[path] = kinds;
                }

                kinds.Add(rootKind);
            }

            foreach (var path in sourceVmdRoots)
                AddRoot(path, GameplayMeshDependencyRootKind.SourcePackVmd);
            foreach (var path in indexedGameplayAssets)
                AddRoot(path, GameplayMeshDependencyRootKind.ResidencyAsset);
            foreach (var path in safetyRosterVmdRoots)
                AddRoot(path, GameplayMeshDependencyRootKind.ResolvedRosterVmd);
            foreach (var path in resolution?.UnresolvedConsumersByVmd.Keys ??
                         Array.Empty<string>())
            {
                AddRoot(path, GameplayMeshDependencyRootKind.UnresolvedResolverVmd);
            }

            foreach (var path in resolution?.DirectAssetUsagesByPath.Keys
                         .Where(IsMeshConsumerAssetPath) ?? Array.Empty<string>())
            {
                AddRoot(path, GameplayMeshDependencyRootKind.DirectGameplayAsset);
            }

            var roots = rootKindsByPath.Keys
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();

            var index = new GameplayMeshDependencyIndex(
                CanClassifyVerifiedMissingDependencies(state));
            foreach (var (rootPath, rootKinds) in rootKindsByPath)
            {
                foreach (var rootKind in rootKinds)
                    index.RegisterRoot(rootPath, rootKind);
            }

            var wsModels = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var rootAssetPath in roots)
            {
                cancellationToken.ThrowIfCancellationRequested();

                var traversal = CollectGameplayMeshConsumers(
                    state,
                    rootAssetPath,
                    cancellationToken,
                    index);
                if (!traversal.IsComplete)
                {
                    foreach (var failure in traversal.Failures)
                    {
                        index.RecordFailure(
                            rootAssetPath,
                            failure.AssetPath,
                            failure.Reason,
                            failure.FailureKind,
                            failure.AssetScope);
                    }
                }

                foreach (var wsModelPath in traversal.WsModelPaths)
                    wsModels.Add(Normalize(wsModelPath));

                foreach (var rigidPath in traversal.DirectRigidPaths)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    index.AddDirectConsumer(rigidPath, rootAssetPath);
                }
            }

            // Parse each WSModel once, after every gameplay root has been traversed. This
            // ensures a shared malformed/missing WSModel is attributed to every root that
            // references it, rather than only to the first root encountered.
            foreach (var wsModelPath in wsModels.OrderBy(path => path, StringComparer.OrdinalIgnoreCase))
            {
                cancellationToken.ThrowIfCancellationRequested();
                var referencingRoots = index.GetRootsForAsset(wsModelPath).ToArray();
                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    wsModelPath);
                var file = container?.FindFile(wsModelPath);
                if (container == null || file == null)
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        wsModelPath,
                        "WSModel could not be resolved",
                        GameplayMeshDependencyFailureKind.MissingReference,
                        GetGameplayMeshDependencyAssetScope(
                            state,
                            wsModelPath,
                            container));
                    continue;
                }

                // BuildWsUsageIndex deliberately excludes malformed source WSModels. They
                // still consume the rigid topology, so consumer safety must fail closed.
                if (state.Source.ContainsFile(wsModelPath) &&
                    state.MalformedWsModelsIgnored.Any(entry =>
                        entry.Path.Equals(
                            wsModelPath,
                            StringComparison.OrdinalIgnoreCase)))
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        wsModelPath,
                        "source WSModel is malformed and its geometry consumer cannot be established",
                        GameplayMeshDependencyFailureKind.ParseFailure,
                        GameplayMeshDependencyAssetScope.SourcePack);
                    continue;
                }

                // Reuse the compact effective WSModel entry used by atlas value
                // accounting. Source XML is already memoized in BatchState; for a
                // vanilla CA container this also populates the persistent consumer
                // cache, so the later value-gate pass does not parse the same WSModel
                // again.
                if (!TryGetWsModelConsumerEntry(
                        state,
                        container,
                        wsModelPath,
                        file,
                        out var wsModelEntry))
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        wsModelPath,
                        "WSModel could not be parsed",
                        GameplayMeshDependencyFailureKind.ParseFailure,
                        GetGameplayMeshDependencyAssetScope(
                            state,
                            wsModelPath,
                            container));
                    continue;
                }

                var geometryPath = wsModelEntry.GeometryPath;
                if (geometryPath.Length == 0)
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        wsModelPath,
                        "WSModel has no geometry path",
                        GameplayMeshDependencyFailureKind.InvalidReference,
                        GetGameplayMeshDependencyAssetScope(
                            state,
                            wsModelPath,
                            container));
                    continue;
                }

                if (!Path.GetExtension(geometryPath).Equals(
                        ".rigid_model_v2",
                        StringComparison.OrdinalIgnoreCase))
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        geometryPath,
                        "WSModel geometry reference has an unknown asset type",
                        GameplayMeshDependencyFailureKind.UnknownType,
                        GetGameplayMeshDependencyAssetScope(
                            state,
                            geometryPath));
                    continue;
                }

                index.AddDependency(wsModelPath, geometryPath);
                foreach (var root in referencingRoots)
                    index.AddRootReference(geometryPath, root);

                var geometryContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    geometryPath);
                if (geometryContainer == null || geometryContainer.FindFile(geometryPath) == null)
                {
                    RecordFailureForRoots(
                        index,
                        referencingRoots,
                        geometryPath,
                        "WSModel geometry dependency could not be resolved",
                        GameplayMeshDependencyFailureKind.MissingReference,
                        GetGameplayMeshDependencyAssetScope(
                            state,
                            geometryPath,
                            geometryContainer));
                    continue;
                }

                index.AddWsModelConsumer(geometryPath, wsModelPath);
            }

            // A WSModel can be reached from several gameplay roots. Some roots are
            // processed before the WSModel is parsed and some after it, so the one-time
            // consumer indexing above cannot reliably propagate every root to the
            // geometry. Finish that propagation once all root traversals are known; this
            // lets the safety gate reject only rigids in an incomplete dependency graph
            // instead of poisoning unrelated atlas candidates in the pack.
            index.PropagateRootReferences();

            return index;
        }

        private static IReadOnlyCollection<string> GetImmutableGameplayWsModelConsumersForRigid(
            BatchState state,
            string rigidPath)
        {
            rigidPath = Normalize(rigidPath);
            if (state.GameplayMeshDependencyIndex != null &&
                state.GameplayMeshDependencyIndex.WsModelConsumersByRigid.TryGetValue(
                    rigidPath,
                    out var indexedConsumers))
            {
                return indexedConsumers
                    .Where(path => !state.Source.ContainsFile(path))
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray();
            }

            return state.ImmutableMeshMergeConsumersByRigid.TryGetValue(
                    rigidPath,
                    out var consumers)
                ? consumers
                : Array.Empty<string>();
        }

        private static bool HasDirectGameplayRigidConsumer(
            BatchState state,
            string rigidPath)
        {
            rigidPath = Normalize(rigidPath);
            if (state.GameplayMeshDependencyIndex != null)
            {
                return state.GameplayMeshDependencyIndex.DirectConsumersByRigid
                    .TryGetValue(rigidPath, out var indexedConsumers) &&
                    indexedConsumers.Count != 0;
            }

            return state.DirectRigidMeshMergeConsumersByRigid.TryGetValue(
                       rigidPath,
                       out var consumers) &&
                   consumers.Count != 0;
        }

        private static bool IsGameplayConsumerDiscoverySafeForAsset(
            BatchState state,
            string assetPath)
        {
            if (state.StructuralMergeConsumerDiscoveryComplete)
                return true;

            // A resolver/schema failure is a pack-wide safety failure. When the resolver
            // is healthy, however, an incomplete traversal only invalidates the assets
            // that are actually reachable from one of the failed roots.
            if (state.UnitCategoryResolution == null ||
                !state.UnitCategoryResolution.IsGameplayResolutionHealthy ||
                state.GameplayMeshDependencyIndex == null)
            {
                return false;
            }

            return !state.GameplayMeshDependencyIndex.IsAssetAffectedByIncompleteRoot(
                assetPath);
        }

        private static bool IsAtlasCandidateGameplayDiscoverySafe(
            BatchState state,
            AtlasCandidate candidate)
        {
            if (state.StructuralMergeConsumerDiscoveryComplete)
                return true;

            if (state.UnitCategoryResolution == null ||
                !state.UnitCategoryResolution.IsGameplayResolutionHealthy ||
                state.GameplayMeshDependencyIndex == null)
            {
                return false;
            }

            var paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
            {
                candidate.RootVmdPath,
                candidate.Key.GeometryPath,
            };
            foreach (var usage in candidate.Usages)
            {
                if (!string.IsNullOrWhiteSpace(usage.WsModelPath))
                    paths.Add(usage.WsModelPath);
            }

            return paths.All(
                path => !state.GameplayMeshDependencyIndex.IsAssetAffectedByIncompleteRoot(
                    path));
        }

        private static void RecordStructuralMergeConsumerDiscoveryFailure(
            BatchState state,
            string path,
            string reason)
        {
            state.StructuralMergeConsumerDiscoveryComplete = false;
            state.StructuralMergeConsumerDiscoveryFailures.Add(
                $"{Normalize(path)}: {reason}");
        }

        private static bool IsMeshConsumerAssetPath(string path)
        {
            var extension = Path.GetExtension(Normalize(path));
            return extension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) ||
                   extension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase) ||
                   extension.Equals(
                       ".variantmeshdefinition",
                       StringComparison.OrdinalIgnoreCase);
        }

        private static GameplayMeshDependencyAssetScope
            GetGameplayMeshDependencyAssetScope(
                BatchState state,
                string assetPathValue,
                IPackFileContainer? resolvedContainer = null)
        {
            var assetPath = Normalize(assetPathValue);
            if (resolvedContainer != null)
            {
                return ReferenceEquals(resolvedContainer, state.Source)
                    ? GameplayMeshDependencyAssetScope.SourcePack
                    : GameplayMeshDependencyAssetScope.CaPack;
            }

            if (assetPath.Length != 0 && state.Source.ContainsFile(assetPath))
                return GameplayMeshDependencyAssetScope.SourcePack;

            return assetPath.Length != 0 &&
                   FindGameplayTraversalContainer(
                       state,
                       state.Source,
                       GetGameplayTraversalContainers(state),
                       assetPath) != null
                ? GameplayMeshDependencyAssetScope.CaPack
                : GameplayMeshDependencyAssetScope.Missing;
        }

        private static bool CanClassifyVerifiedMissingDependencies(BatchState state)
        {
            var containers = state.GameplayTraversalContainers;
            return state.UnitCategoryResolution?.IsGameplayResolutionHealthy == true &&
                   containers != null &&
                   containers.Any(container => container.IsCaPackFile);
        }

        private static void RecordFailureForRoots(
            GameplayMeshDependencyIndex index,
            IEnumerable<string> rootPaths,
            string assetPath,
            string reason,
            GameplayMeshDependencyFailureKind failureKind,
            GameplayMeshDependencyAssetScope assetScope)
        {
            var roots = rootPaths
                .Select(Normalize)
                .Where(path => path.Length != 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
            if (roots.Length == 0)
            {
                index.RecordFailure(
                    string.Empty,
                    assetPath,
                    reason,
                    failureKind,
                    assetScope);
                return;
            }

            foreach (var rootPath in roots)
            {
                index.RecordFailure(
                    rootPath,
                    assetPath,
                    reason,
                    failureKind,
                    assetScope);
            }
        }

        private static GameplayMeshConsumerTraversal CollectGameplayMeshConsumers(
            BatchState state,
            string rootAssetPath,
            CancellationToken cancellationToken,
            GameplayMeshDependencyIndex? dependencyIndex = null)
        {
            var result = new GameplayMeshConsumerTraversal();
            var queue = new Queue<string>();
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var rootPath = Normalize(rootAssetPath);
            if (rootPath.Length == 0)
            {
                result.IsComplete = false;
                result.Failures.Add(
                    new GameplayMeshTraversalFailure(
                        "<empty root>",
                        "empty root",
                        GameplayMeshDependencyFailureKind.InvalidReference,
                        GameplayMeshDependencyAssetScope.Missing));
                return result;
            }

            dependencyIndex?.GameplayRoots.Add(rootPath);
            queue.Enqueue(rootPath);
            while (queue.Count != 0)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var assetPath = queue.Dequeue();
                if (!visited.Add(assetPath))
                    continue;

                dependencyIndex?.AddRootReference(assetPath, rootPath);

                var extension = Path.GetExtension(assetPath);
                if (extension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase))
                {
                    result.WsModelPaths.Add(assetPath);
                    continue;
                }

                if (extension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase))
                {
                    var rigidContainer = FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        GetGameplayTraversalContainers(state),
                        assetPath);
                    if (rigidContainer == null || rigidContainer.FindFile(assetPath) == null)
                    {
                        result.IsComplete = false;
                        result.Failures.Add(
                            new GameplayMeshTraversalFailure(
                                assetPath,
                                "rigid model could not be resolved",
                                GameplayMeshDependencyFailureKind.MissingReference,
                                GetGameplayMeshDependencyAssetScope(
                                    state,
                                    assetPath,
                                    rigidContainer)));
                    }
                    else
                    {
                        result.DirectRigidPaths.Add(assetPath);
                    }
                    continue;
                }

                if (!extension.Equals(
                        ".variantmeshdefinition",
                        StringComparison.OrdinalIgnoreCase))
                {
                    // A gameplay root/reference without a recognized extension cannot be
                    // classified safely, regardless of whether a file happens to exist at
                    // that path. Validate the type before treating absence as verified.
                    result.IsComplete = false;
                    result.Failures.Add(
                        new GameplayMeshTraversalFailure(
                            assetPath,
                            "unrecognized asset type",
                            GameplayMeshDependencyFailureKind.UnknownType,
                            GetGameplayMeshDependencyAssetScope(
                                state,
                                assetPath)));

                    continue;
                }

                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    assetPath);
                var file = container?.FindFile(assetPath);
                if (container == null ||
                    file == null ||
                    !TryGetVmdForTraversal(
                        state,
                        container,
                        assetPath,
                        file,
                        out var vmd))
                {
                    result.IsComplete = false;
                    result.Failures.Add(
                        new GameplayMeshTraversalFailure(
                            assetPath,
                            container == null || file == null
                                ? "VMD could not be resolved"
                                : "VMD could not be parsed",
                            container == null || file == null
                                ? GameplayMeshDependencyFailureKind.MissingReference
                                : GameplayMeshDependencyFailureKind.ParseFailure,
                            GetGameplayMeshDependencyAssetScope(
                                state,
                                assetPath,
                                container)));
                    continue;
                }

                var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var children = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                CollectVmdReferences(vmd, models, children, textures);

                foreach (var modelValue in models)
                {
                    var modelPath = Normalize(modelValue);
                    if (modelPath.Length == 0)
                        continue;

                    var modelExtension = Path.GetExtension(modelPath);
                    var isWsModel = modelExtension.Equals(
                        ".wsmodel",
                        StringComparison.OrdinalIgnoreCase);
                    var isRigidModel = modelExtension.Equals(
                        ".rigid_model_v2",
                        StringComparison.OrdinalIgnoreCase);
                    var isVariantMeshDefinition = modelExtension.Equals(
                        ".variantmeshdefinition",
                        StringComparison.OrdinalIgnoreCase);
                    if (!isWsModel && !isRigidModel && !isVariantMeshDefinition)
                    {
                        result.IsComplete = false;
                        result.Failures.Add(
                            new GameplayMeshTraversalFailure(
                                modelPath,
                                "unrecognized model reference",
                                GameplayMeshDependencyFailureKind.UnknownType,
                                GetGameplayMeshDependencyAssetScope(
                                    state,
                                    modelPath)));
                        continue;
                    }

                    dependencyIndex?.AddDependency(assetPath, modelPath);
                    dependencyIndex?.AddRootReference(modelPath, rootPath);

                    var modelContainer = FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        GetGameplayTraversalContainers(state),
                        modelPath);
                    if (modelContainer == null)
                    {
                        result.IsComplete = false;
                        result.Failures.Add(
                            new GameplayMeshTraversalFailure(
                                modelPath,
                                "model dependency could not be resolved",
                                GameplayMeshDependencyFailureKind.MissingReference,
                                GameplayMeshDependencyAssetScope.Missing));
                        continue;
                    }

                    if (isWsModel)
                    {
                        result.WsModelPaths.Add(modelPath);
                    }
                    else if (isRigidModel)
                    {
                        result.DirectRigidPaths.Add(modelPath);
                    }
                    else if (isVariantMeshDefinition)
                    {
                        queue.Enqueue(modelPath);
                    }
                }

                foreach (var childValue in children)
                {
                    var childPath = Normalize(childValue);
                    if (childPath.Length == 0)
                        continue;

                    if (!Path.GetExtension(childPath).Equals(
                            ".variantmeshdefinition",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        result.IsComplete = false;
                        result.Failures.Add(
                            new GameplayMeshTraversalFailure(
                                childPath,
                                "unrecognized child VMD reference",
                                GameplayMeshDependencyFailureKind.UnknownType,
                                GetGameplayMeshDependencyAssetScope(
                                    state,
                                    childPath)));
                        continue;
                    }

                    dependencyIndex?.AddDependency(assetPath, childPath);
                    dependencyIndex?.AddRootReference(childPath, rootPath);

                    if (FindGameplayTraversalContainer(
                            state,
                            state.Source,
                            GetGameplayTraversalContainers(state),
                            childPath) == null)
                    {
                        result.IsComplete = false;
                        result.Failures.Add(
                            new GameplayMeshTraversalFailure(
                                childPath,
                                "child VMD dependency could not be resolved",
                                GameplayMeshDependencyFailureKind.MissingReference,
                                GetGameplayMeshDependencyAssetScope(
                                    state,
                                    childPath)));
                        continue;
                    }

                    queue.Enqueue(childPath);
                }
            }

            return result;
        }

        private HashSet<string> LoadStructuralMergeRigidModels(
            BatchState state,
            CancellationToken cancellationToken)
        {
            var rigidPaths = new HashSet<string>(
                state.RigidModels.Keys.Select(Normalize),
                StringComparer.OrdinalIgnoreCase);

            foreach (var document in state.WsDocuments.Values)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var geometryPath = Normalize(
                    document.SelectSingleNode("/model/geometry")?.InnerText);
                if (geometryPath.Length != 0 && state.Source.ContainsFile(geometryPath))
                    rigidPaths.Add(geometryPath);
            }

            foreach (var assetPath in state.SourceReachableAssetFiles)
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (Path.GetExtension(assetPath).Equals(
                        ".rigid_model_v2",
                        StringComparison.OrdinalIgnoreCase) &&
                    state.Source.ContainsFile(assetPath))
                {
                    rigidPaths.Add(Normalize(assetPath));
                }
            }

            foreach (var rigidPath in rigidPaths.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (!state.Source.ContainsFile(rigidPath) ||
                    state.RigidModels.ContainsKey(rigidPath))
                {
                    continue;
                }

                try
                {
                    _ = GetRmv(state, rigidPath);
                }
                catch (Exception ex) when (
                    ex is InvalidDataException or
                    InvalidOperationException or
                    ArgumentException or
                    FormatException)
                {
                    RecordStructuralMergeSkip(
                        state,
                        rigidPath,
                        $"rigid model could not be loaded for structural merge analysis: {ex.Message}");
                }
            }

            return state.RigidModels.Keys
                .Where(path => state.Source.ContainsFile(path))
                .Select(Normalize)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
        }

        private void AnalyzeCompatibleMeshMerges(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var rigidPaths = LoadStructuralMergeRigidModels(state, cancellationToken)
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToList();

            for (var rigidIndex = 0; rigidIndex < rigidPaths.Count; rigidIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var rigidPath = rigidPaths[rigidIndex];
                ReportProgress(
                    progress,
                    "Analyzing structural mesh merges",
                    rigidIndex + 1,
                    rigidPaths.Count,
                    rigidPath);

                if (!TryGetStructuralMergeBlockReason(state, rigidPath, out _))
                    AnalyzeCompatibleMeshMergesForRigid(state, rigidPath, cancellationToken);
            }
        }

        private static void AnalyzeCrossRigidMergeOpportunities(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            state.CrossRigidMergeAnalysisEntries.Clear();
            state.CrossRigidGeneratedPayloadAnalysisEntries.Clear();
            state.CrossRigidAnalysisBlockerCounts.Clear();
            state.CrossRigidAnalysisBlockerExamples.Clear();
            state.CrossRigidRigidHeaderBlockerCounts.Clear();
            state.CrossRigidRigidHeaderBlockerRigidCombinations.Clear();
            state.CrossRigidRigidHeaderBlockerVmdRoots.Clear();
            state.CrossRigidRigidHeaderQualityProfiles.Clear();
            state.CrossRigidRigidHeaderFullLodProfiles.Clear();
            state.CrossRigidAnalysisDiagnosticCounts.Clear();
            state.CrossRigidAnalysisDiagnosticExamples.Clear();
            state.CrossRigidJointStateCapExclusionsByVmd.Clear();
            state.CrossRigidActivationRewriteOccurrenceSetCounts.Clear();
            state.CrossRigidActivationRewritePlanCounts.Clear();
            state.CrossRigidActivationRewriteExpectedDrawCalls.Clear();
            state.CrossRigidModifierProfileOccurrenceSetCounts.Clear();
            state.CrossRigidModifierProfilePlanCounts.Clear();
            state.CrossRigidModifierProfileExpectedDrawCalls.Clear();
            state.CrossRigidWsModelOccurrenceProbabilities.Clear();
            state.CrossRigidDisplacedSourceGeometryEntries.Clear();
            state.CrossRigidAnalysisVmdCount = 0;
            state.CrossRigidAnalysisDirectWsModelCount = 0;
            state.CrossRigidAnalysisConfigurationCount = 0;
            state.CrossRigidAnalysisOpportunityObservationCount = 0;
            state.CrossRigidPairFallbackSubgroupObservations = 0;
            state.CrossRigidTripleFallbackSubgroupObservations = 0;
            state.CrossRigidQuadrupleFallbackSubgroupObservations = 0;
            state.CrossRigidQuintupleFallbackSubgroupObservations = 0;
            state.CrossRigidMiddleTripleFallbackSubgroupObservations = 0;
            state.CrossRigidMiddleQuadrupleFallbackSubgroupObservations = 0;
            state.CrossRigidPairFallbackPlansCompetingWithSafeFullGroups = 0;
            state.CrossRigidPreviouslySuppressedPairFallbackPlanIds.Clear();
            state.CrossRigidLegacyEligiblePayloadIds.Clear();
            state.CrossRigidPairFallbackPlansEvaluated = 0;
            state.CrossRigidTimingDetails.Clear();
            state.CrossRigidSourceMeshMergeIdentityCache.Clear();
            state.CrossRigidMaterialMergeIdentityCache.Clear();
            var crossRigidAnalysisStage = Stopwatch.StartNew();

            var rigidCache = new Dictionary<string, RmvFile>(
                state.RigidModels,
                StringComparer.OrdinalIgnoreCase);
            var traversalContainers = GetGameplayTraversalContainers(state);
            var visualConfigurationCache =
                new Dictionary<string, CrossRigidAttachmentLocalExpansionResult>(
                    StringComparer.OrdinalIgnoreCase);
            var rewritePlanAccumulators =
                new Dictionary<string, CrossRigidMergePlanAccumulator>(
                    StringComparer.Ordinal);
            var rejectedPlanKeys = new HashSet<string>(StringComparer.Ordinal);
            var fullGroupPlanKeys = new HashSet<string>(StringComparer.Ordinal);
            var fallbackParentPlanKeys =
                new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            var activationClassificationVmdDocuments =
                new Dictionary<string, XmlDocument>(
                    StringComparer.OrdinalIgnoreCase);

            for (var vmdIndex = 0; vmdIndex < vmdRoots.Count; vmdIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var vmdPath = Normalize(vmdRoots[vmdIndex]);
                ReportProgress(
                    progress,
                    "Analyzing cross-rigid merges",
                    vmdIndex + 1,
                    vmdRoots.Count,
                    vmdPath);

                var expansion = GetCrossRigidAttachmentLocalConfigurationsForVmd(
                    state,
                    vmdPath,
                    visualConfigurationCache,
                    new HashSet<string>(StringComparer.OrdinalIgnoreCase));
                if (expansion.FailureReason != null)
                {
                    RecordCrossRigidAnalysisBlocker(
                        state,
                        expansion.FailureReason,
                        vmdPath);
                    continue;
                }

                RecordCrossRigidWsModelOccurrenceProbabilities(
                    state,
                    vmdPath,
                    expansion);
                var configurations = expansion.ConfigurationsByAttachment
                    .Values
                    .SelectMany(items => items)
                    .ToArray();
                var allWsModels = configurations
                    .SelectMany(configuration => configuration.Instances)
                    .Select(instance => instance.WsModelPath)
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                if (allWsModels.Length < 2)
                    continue;

                state.CrossRigidAnalysisVmdCount++;
                state.CrossRigidAnalysisDirectWsModelCount += allWsModels.Length;
                state.CrossRigidAnalysisConfigurationCount += configurations.Length;

                var componentsByWsModel =
                    new Dictionary<string, CrossRigidAnalysisComponent>(
                        StringComparer.OrdinalIgnoreCase);
                foreach (var wsModelPath in allWsModels)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!TryBuildCrossRigidAnalysisComponent(
                            state,
                            vmdPath,
                            wsModelPath,
                            traversalContainers,
                            rigidCache,
                            out var component,
                            out var reason))
                    {
                        RecordCrossRigidAnalysisBlocker(
                            state,
                            reason,
                            $"{vmdPath}: {wsModelPath}");
                        continue;
                    }

                    componentsByWsModel[wsModelPath] = component;
                }

                foreach (var configuration in configurations
                             .Where(configuration =>
                                 configuration.Probability > 0 &&
                                 configuration.Instances.Count >= 2))
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var attachmentComponents =
                        new List<CrossRigidAnalysisInstanceComponent>();
                    foreach (var instance in configuration.Instances)
                    {
                        if (!componentsByWsModel.TryGetValue(
                                instance.WsModelPath,
                                out var component))
                        {
                            continue;
                        }

                        attachmentComponents.Add(
                            new CrossRigidAnalysisInstanceComponent(
                                instance,
                                component));
                    }

                    if (attachmentComponents
                            .Select(item => item.Component.RigidPath)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count() < 2)
                    {
                        continue;
                    }

                    // A generated WSModel can be built explicitly, but keep non-material
                    // WSModel state strict in the analysis. This prevents the report from
                    // claiming opportunities that would require unrelated WSModel runtime
                    // fields to be reconciled by the writer.
                    var topologyGroups = attachmentComponents
                        .GroupBy(
                            item => item.Component.TopologyIdentity,
                            StringComparer.Ordinal)
                        .Select(group => group
                            .OrderBy(
                                item => item.Component.WsModelPath,
                                StringComparer.OrdinalIgnoreCase)
                            .ToArray())
                        .Where(group => group
                            .Select(item => item.Component.RigidPath)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count() >= 2)
                        .ToArray();

                    if (topologyGroups.Length == 0)
                    {
                        RecordCrossRigidAnalysisBlocker(
                            state,
                            "WSModel non-material topology differs",
                            $"{vmdPath} [{configuration.AttachmentIdentity}]: " +
                            $"{attachmentComponents.Count} co-rendered component instance(s)");
                        continue;
                    }

                    foreach (var (group, isSubgroupFallback, fallbackSize, fullGroup) in
                             EnumerateCrossRigidCandidateGroups(
                                 topologyGroups, state))
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                        if (isSubgroupFallback)
                            state.CrossRigidPairFallbackSubgroupObservations++;
                        if (fallbackSize == 3)
                            state.CrossRigidTripleFallbackSubgroupObservations++;
                        if (fallbackSize == 4)
                            state.CrossRigidQuadrupleFallbackSubgroupObservations++;
                        if (fallbackSize == 5)
                            state.CrossRigidQuintupleFallbackSubgroupObservations++;
                        var rewritePlanKey = BuildCrossRigidRewritePlanKey(
                            vmdPath,
                            configuration.AttachmentIdentity,
                            group);
                        if (!isSubgroupFallback)
                        {
                            fullGroupPlanKeys.Add(rewritePlanKey);
                        }
                        else
                        {
                            if (!fallbackParentPlanKeys.TryGetValue(
                                    rewritePlanKey, out var parentKeys))
                            {
                                parentKeys = new HashSet<string>(
                                    StringComparer.Ordinal);
                                fallbackParentPlanKeys.Add(
                                    rewritePlanKey, parentKeys);
                            }

                            parentKeys.Add(BuildCrossRigidRewritePlanKey(
                                vmdPath,
                                configuration.AttachmentIdentity,
                                fullGroup));
                        }

                        if (rewritePlanAccumulators.TryGetValue(
                                rewritePlanKey,
                                out var existingPlan))
                        {
                            existingPlan.AggregatedConfigurationProbability +=
                                configuration.Probability;
                            existingPlan.ContributingConfigurationCount++;
                            existingPlan.RewriteOccurrenceSets.AddRange(
                                BuildCrossRigidRewriteOccurrenceSets(
                                    configuration,
                                    group));
                            state.CrossRigidAnalysisOpportunityObservationCount++;
                            continue;
                        }

                        if (rejectedPlanKeys.Contains(rewritePlanKey))
                            continue;

                        var distinctComponents = group
                            .Select(item => item.Component)
                            .GroupBy(
                                component => component.WsModelPath,
                                StringComparer.OrdinalIgnoreCase)
                            .Select(items => items.First())
                            .ToArray();
                        if (!AreCrossRigidRigidHeadersCompatible(
                                distinctComponents,
                                out var rigidHeaderReason))
                        {
                            rejectedPlanKeys.Add(rewritePlanKey);
                            RecordCrossRigidRigidHeaderBlocker(
                                state,
                                vmdPath,
                                configuration.AttachmentIdentity,
                                distinctComponents,
                                rigidHeaderReason);
                            continue;
                        }

                        var sourceLodCounts =
                            distinctComponents
                                .Select(component =>
                                    component.Rigid.ModelList.Length)
                                .Distinct()
                                .OrderBy(count => count)
                                .ToArray();
                        var sourceVersions =
                            distinctComponents
                                .Select(component =>
                                    component.Rigid.Header.Version)
                                .Distinct()
                                .ToArray();
                        if (sourceVersions.Length > 1)
                        {
                            RecordCrossRigidAnalysisDiagnostic(
                                state,
                                "Cross-rigid source RMV versions normalized",
                                $"{vmdPath} [{configuration.AttachmentIdentity}]: " +
                                $"{string.Join(", ", sourceVersions.OrderBy(version => version))} -> " +
                                $"{sourceVersions.Max()}");
                        }

                        var lodAnalyses =
                            BuildCrossRigidLodAnalyses(
                                state,
                                group,
                                cancellationToken);
                        if (sourceLodCounts.Length > 1)
                        {
                            RecordCrossRigidAnalysisDiagnostic(
                                state,
                                "Cross-rigid source LOD counts reconciled",
                                $"{vmdPath} [{configuration.AttachmentIdentity}]: " +
                                $"sourceCounts=[{string.Join(",", sourceLodCounts)}] -> " +
                                $"generated={lodAnalyses.Count}");
                        }

                        var qualityProfiles = distinctComponents
                            .Select(component =>
                                BuildCrossRigidQualityProfile(component.Rigid))
                            .Distinct(StringComparer.Ordinal)
                            .OrderBy(profile => profile, StringComparer.Ordinal)
                            .ToArray();
                        var distanceProfiles = distinctComponents
                            .Select(component =>
                                BuildCrossRigidDistanceProfile(component.Rigid))
                            .Distinct(StringComparer.Ordinal)
                            .OrderBy(profile => profile, StringComparer.Ordinal)
                            .ToArray();
                        if (qualityProfiles.Length > 1 ||
                            distanceProfiles.Length > 1)
                        {
                            RecordCrossRigidAnalysisDiagnostic(
                                state,
                                "Cross-rigid source LOD headers reconciled",
                                $"{vmdPath} [{configuration.AttachmentIdentity}]: " +
                                $"sourceQ={string.Join(" <> ", qualityProfiles)}, " +
                                $"sourceD={string.Join(" <> ", distanceProfiles)} -> " +
                                $"Q=[{string.Join(",", lodAnalyses.Select(lod => lod.QualityLevel))}], " +
                                $"D=[{string.Join(",", lodAnalyses.Select(lod => lod.CameraDistance.ToString("0.###", CultureInfo.InvariantCulture)))}]");
                        }

                        if (lodAnalyses.Count == 0 ||
                            lodAnalyses.All(lod => lod.DrawsSaved <= 0))
                        {
                            rejectedPlanKeys.Add(rewritePlanKey);
                            RecordCrossRigidAnalysisBlocker(
                                state,
                                "No actual cross-rigid draw saving",
                                $"{vmdPath} [{configuration.AttachmentIdentity}]: " +
                                $"{string.Join(", ", group.Select(item => item.Component.RigidPath).Distinct(StringComparer.OrdinalIgnoreCase))}");
                            continue;
                        }

                        var sourceGeometry = group
                            .Select(item =>
                                BuildCrossRigidSourceGeometryComponent(item))
                            .ToArray();
                        var sourceInstances = group
                            .Select(item => item.Instance)
                            .OrderBy(
                                instance => instance.WsModelPath,
                                StringComparer.OrdinalIgnoreCase)
                            .ToArray();
                        var rewriteOccurrenceSets =
                            BuildCrossRigidRewriteOccurrenceSets(
                                configuration,
                                group);
                        if (rewriteOccurrenceSets.Count == 0)
                        {
                            rejectedPlanKeys.Add(rewritePlanKey);
                            RecordCrossRigidAnalysisBlocker(
                                state,
                                "Cross-rigid rewrite provenance could not be retained",
                                $"{vmdPath} [{configuration.AttachmentIdentity}]");
                            continue;
                        }

                        var generatedPayloadKey =
                            BuildCrossRigidGeneratedPayloadKey(
                                sourceInstances,
                                lodAnalyses);
                        var rewritePlanId = ContentHash(string.Join(
                            "\u001f",
                            rewritePlanKey,
                            generatedPayloadKey));
                        var generatedPayloadId =
                            ContentHash(generatedPayloadKey);

                        rewritePlanAccumulators[rewritePlanKey] =
                            new CrossRigidMergePlanAccumulator(
                                rewritePlanId,
                                generatedPayloadId,
                                generatedPayloadKey,
                                vmdPath,
                                configuration.AttachmentIdentity,
                                sourceInstances,
                                sourceGeometry,
                                group.Select(item => item.Component.RigidPath)
                                    .Distinct(StringComparer.OrdinalIgnoreCase)
                                    .OrderBy(
                                        path => path,
                                        StringComparer.OrdinalIgnoreCase)
                                    .ToArray(),
                                lodAnalyses.ToArray(),
                                rewriteOccurrenceSets.ToList(),
                                configuration.Probability,
                                1);
                        state.CrossRigidAnalysisOpportunityObservationCount++;
                    }
                }
            }

            state.CrossRigidTimingDetails["Analyze: enumerate candidates"] =
                crossRigidAnalysisStage.Elapsed;
            crossRigidAnalysisStage.Restart();
            ExpandCrossRigidRewriteCoverageAcrossConfigurations(
                state,
                rewritePlanAccumulators.Values,
                visualConfigurationCache);
            state.CrossRigidTimingDetails["Analyze: expand occurrence coverage"] =
                crossRigidAnalysisStage.Elapsed;
            crossRigidAnalysisStage.Restart();

            // Analyze full groups first so we can identify the fallback
            // alternatives which *would previously* have been suppressed.
            // A writable full-group plan is not necessarily selected by
            // the portfolio or compatible with every other winning rewrite.
            // Keep its pairs as genuine alternatives: conflict-state checks
            // and the portfolio budgets will decide which can be emitted.
            var safeFullGroupPlanKeys = new HashSet<string>(
                StringComparer.Ordinal);
            foreach (var (planKey, plan) in rewritePlanAccumulators
                         .OrderBy(entry =>
                             fullGroupPlanKeys.Contains(entry.Key) ? 0 : 1)
                         .ThenBy(entry => entry.Key, StringComparer.Ordinal))
            {
                if (!fullGroupPlanKeys.Contains(planKey) &&
                    fallbackParentPlanKeys.TryGetValue(
                        planKey, out var fallbackParents))
                {
                    if (fallbackParents.Any(
                            safeFullGroupPlanKeys.Contains))
                    {
                        state.CrossRigidPairFallbackPlansCompetingWithSafeFullGroups++;
                    }

                    state.CrossRigidPairFallbackPlansEvaluated++;
                }

                var allRewriteOccurrenceSets =
                    MergeCrossRigidRewriteOccurrenceSets(
                        plan.RewriteOccurrenceSets);
                var classifiedOccurrenceSets =
                    new List<(
                        CrossRigidRewriteOccurrenceSet OccurrenceSet,
                        CrossRigidActivationRewriteClass RewriteClass,
                        string Detail)>();
                foreach (var occurrenceSet in allRewriteOccurrenceSets)
                {
                    var rewriteClass =
                        ClassifyCrossRigidRewriteOccurrenceSet(
                            state,
                            occurrenceSet,
                            activationClassificationVmdDocuments,
                            out var classificationDetail);
                    classifiedOccurrenceSets.Add(
                        (occurrenceSet, rewriteClass, classificationDetail));
                }

                var modifierProfiledOccurrenceSets =
                    classifiedOccurrenceSets
                        .Select(item =>
                        {
                            var topologyClass =
                                ClassifyCrossRigidRewriteOccurrenceSetTopology(
                                    state,
                                    item.OccurrenceSet,
                                    activationClassificationVmdDocuments,
                                    out _);
                            var modifierProfile =
                                BuildCrossRigidModifierProfile(
                                    item.OccurrenceSet,
                                    plan.SourceGeometry);
                            return (
                                item.OccurrenceSet,
                                TopologyClass: topologyClass,
                                ModifierProfile: modifierProfile);
                        })
                        .ToArray();

                foreach (var modifierGroup in
                         modifierProfiledOccurrenceSets
                             .Where(item =>
                                 !item.ModifierProfile.Equals(
                                     "none",
                                     StringComparison.Ordinal))
                             .GroupBy(item => string.Join(
                                 " | ",
                                 GetCrossRigidActivationRewriteClassLabel(
                                     item.TopologyClass),
                                 item.ModifierProfile),
                                 StringComparer.Ordinal))
                {
                    var profileItems = modifierGroup.ToArray();
                    var profileProbability = Math.Clamp(
                        profileItems.Sum(item =>
                            item.OccurrenceSet.Probability),
                        0.0,
                        1.0);
                    state.CrossRigidModifierProfileOccurrenceSetCounts[
                        modifierGroup.Key] =
                        state.CrossRigidModifierProfileOccurrenceSetCounts
                            .GetValueOrDefault(modifierGroup.Key) +
                        profileItems.Length;
                    state.CrossRigidModifierProfilePlanCounts[
                        modifierGroup.Key] =
                        state.CrossRigidModifierProfilePlanCounts
                            .GetValueOrDefault(modifierGroup.Key) +
                        1;
                    state.CrossRigidModifierProfileExpectedDrawCalls[
                        modifierGroup.Key] =
                        state.CrossRigidModifierProfileExpectedDrawCalls
                            .GetValueOrDefault(modifierGroup.Key) +
                        CalculateExpectedCrossRigidArmyDrawSavings(
                            state,
                            plan.VmdPath,
                            profileProbability,
                            plan.Lods);
                }

                var rewriteableOccurrenceSets =
                    new List<CrossRigidRewriteOccurrenceSet>();
                foreach (var classified in classifiedOccurrenceSets)
                {
                    if (classified.RewriteClass ==
                        CrossRigidActivationRewriteClass.ExactActivationSafe)
                    {
                        rewriteableOccurrenceSets.Add(
                            classified.OccurrenceSet);
                        continue;
                    }

                    if (classified.RewriteClass !=
                            CrossRigidActivationRewriteClass.JointAlwaysPresentSlots &&
                        classified.RewriteClass !=
                            CrossRigidActivationRewriteClass.JointOptionalSlots)
                    {
                        continue;
                    }

                    if (TryDescribeCrossRigidJointAlwaysPresentRewrite(
                            state,
                            classified.OccurrenceSet,
                            activationClassificationVmdDocuments,
                            out _,
                            out var jointReason))
                    {
                        rewriteableOccurrenceSets.Add(
                            classified.OccurrenceSet);
                    }
                    else
                    {
                        RecordCrossRigidAnalysisDiagnostic(
                            state,
                            "Joint activation rewrite state is outside conservative writer",
                            $"{plan.VmdPath} [{plan.AttachmentIdentity}]: " +
                            $"{jointReason}; sources=[" +
                            $"{string.Join(", ", classified.OccurrenceSet.SourceInstances.Select(instance => instance.WsModelPath))}]");
                        // Keep per-root, per-plan accounting of the
                        // state-cap failures. Observation counts alone
                        // exaggerate opportunities repeated across visual
                        // alternatives and competing subgroup plans.
                        if (jointReason.Contains(
                                "Cartesian product exceeds",
                                StringComparison.Ordinal))
                        {
                            var rootPath = Normalize(plan.VmdPath);
                            if (!state.CrossRigidJointStateCapExclusionsByVmd
                                    .TryGetValue(rootPath, out var excluded))
                            {
                                excluded =
                                    new CrossRigidJointStateCapExclusionAggregate();
                                state.CrossRigidJointStateCapExclusionsByVmd.Add(
                                    rootPath, excluded);
                            }

                            excluded.OccurrenceSetCount++;
                            excluded.RewritePlanIds.Add(plan.RewritePlanId);
                            if (classified.OccurrenceSet.SourceInstances.Length == 2)
                                excluded.TwoSourceOccurrenceSetCount++;
                            else
                                excluded.OtherSourceOccurrenceSetCount++;
                            if (jointReason.StartsWith(
                                    "common-ancestor Cartesian product",
                                    StringComparison.Ordinal))
                            {
                                excluded.CommonAncestorOccurrenceSetCount++;
                            }
                            else if (jointReason.StartsWith(
                                         "joint Cartesian product",
                                         StringComparison.Ordinal))
                            {
                                excluded.DirectJointOccurrenceSetCount++;
                            }
                            else
                            {
                                excluded.OtherCapOccurrenceSetCount++;
                            }

                            // Deliberately overlap-inclusive: different
                            // candidate merges can compete for the same
                            // occurrence and must not be summed as
                            // independently realizable savings.
                            excluded.OverlapInclusiveExpectedDraws +=
                                CalculateExpectedCrossRigidArmyDrawSavings(
                                    state,
                                    plan.VmdPath,
                                    classified.OccurrenceSet.Probability,
                                    plan.Lods);
                        }

                        // Aggregate the actual reason separately rather
                        // than showing only the first few examples from a
                        // large, undifferentiated rejection category.
                        RecordCrossRigidAnalysisDiagnostic(
                            state,
                            $"Joint writer exclusion: {jointReason}",
                            $"{plan.VmdPath} [{plan.AttachmentIdentity}]");
                    }
                }

                var rewriteableOccurrenceSetArray =
                    rewriteableOccurrenceSets.ToArray();
                var aggregatedProbability = Math.Clamp(
                    rewriteableOccurrenceSetArray.Sum(set =>
                        set.Probability),
                    0.0,
                    1.0);

                foreach (var classificationGroup in
                         classifiedOccurrenceSets.GroupBy(item =>
                             item.RewriteClass))
                {
                    var rewriteClass = classificationGroup.Key;
                    var classItems = classificationGroup.ToArray();
                    var classProbability = Math.Clamp(
                        classItems.Sum(item =>
                            item.OccurrenceSet.Probability),
                        0.0,
                        1.0);
                    state.CrossRigidActivationRewriteOccurrenceSetCounts[
                        rewriteClass] =
                        state.CrossRigidActivationRewriteOccurrenceSetCounts
                            .GetValueOrDefault(rewriteClass) +
                        classItems.Length;
                    state.CrossRigidActivationRewritePlanCounts[
                        rewriteClass] =
                        state.CrossRigidActivationRewritePlanCounts
                            .GetValueOrDefault(rewriteClass) +
                        1;
                    state.CrossRigidActivationRewriteExpectedDrawCalls[
                        rewriteClass] =
                        state.CrossRigidActivationRewriteExpectedDrawCalls
                            .GetValueOrDefault(rewriteClass) +
                        CalculateExpectedCrossRigidArmyDrawSavings(
                            state,
                            plan.VmdPath,
                            classProbability,
                            plan.Lods);

                    if (rewriteClass !=
                        CrossRigidActivationRewriteClass.ExactActivationSafe)
                    {
                        var detail = classItems
                            .Select(item => item.Detail)
                            .FirstOrDefault(value =>
                                !string.IsNullOrWhiteSpace(value));
                        RecordCrossRigidAnalysisDiagnostic(
                            state,
                            $"Activation rewrite class: " +
                            $"{GetCrossRigidActivationRewriteClassLabel(rewriteClass)}",
                            $"{plan.VmdPath} [{plan.AttachmentIdentity}]: " +
                            $"{classItems.Length}/{allRewriteOccurrenceSets.Length} state(s), " +
                            $"probability={classProbability:0.######}" +
                            (string.IsNullOrWhiteSpace(detail)
                                ? string.Empty
                                : $"; {detail}"));
                    }
                }

                var excludedOccurrenceSetCount =
                    allRewriteOccurrenceSets.Length -
                    rewriteableOccurrenceSetArray.Length;
                if (excludedOccurrenceSetCount != 0)
                {
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Activation-unsafe rewrite states excluded before value gate",
                        $"{plan.VmdPath} [{plan.AttachmentIdentity}]: " +
                        $"{excludedOccurrenceSetCount}/{allRewriteOccurrenceSets.Length} state(s)");
                }

                if (aggregatedProbability <=
                    AtlasValueGateExpectedDrawEpsilon)
                {
                    RecordCrossRigidAnalysisBlocker(
                        state,
                        "No copy-on-write-safe activation state",
                        $"{plan.VmdPath} [{plan.AttachmentIdentity}]");
                    continue;
                }

                if (fullGroupPlanKeys.Contains(planKey))
                {
                    safeFullGroupPlanKeys.Add(planKey);
                }

                // Track provenance at plan granularity: generated geometry
                // can be shared by both existing full-group plans and newly
                // admitted fallback pairs across different VMDs.
                var newlyAdmittedPairFallback =
                    !fullGroupPlanKeys.Contains(planKey) &&
                    fallbackParentPlanKeys.TryGetValue(
                        planKey, out var parentPlanKeys) &&
                    parentPlanKeys.Any(safeFullGroupPlanKeys.Contains);
                if (newlyAdmittedPairFallback)
                {
                    state.CrossRigidPreviouslySuppressedPairFallbackPlanIds.Add(
                        plan.RewritePlanId);
                }
                else
                {
                    state.CrossRigidLegacyEligiblePayloadIds.Add(
                        plan.GeneratedPayloadId);
                }

                state.CrossRigidMergeAnalysisEntries.Add(
                    new CrossRigidMergeAnalysisEntry(
                        plan.RewritePlanId,
                        plan.GeneratedPayloadId,
                        plan.VmdPath,
                        aggregatedProbability,
                        rewriteableOccurrenceSetArray.Length,
                        plan.AttachmentIdentity,
                        plan.SourceInstances,
                        rewriteableOccurrenceSetArray,
                        plan.SourceGeometry,
                        plan.RigidPaths,
                        plan.Lods,
                        CalculateExpectedCrossRigidArmyDrawSavings(
                            state,
                            plan.VmdPath,
                            aggregatedProbability,
                            plan.Lods)));
            }

            state.CrossRigidTimingDetails["Analyze: classify rewrite states"] =
                crossRigidAnalysisStage.Elapsed;
            crossRigidAnalysisStage.Restart();
            BuildCrossRigidGeneratedPayloadAnalysis(state);
            state.CrossRigidTimingDetails["Analyze: build payload estimates"] =
                crossRigidAnalysisStage.Elapsed;
            crossRigidAnalysisStage.Restart();
            SelectCrossRigidGeneratedPayloads(state);
            state.CrossRigidTimingDetails["Analyze: select payload portfolio"] =
                crossRigidAnalysisStage.Elapsed;
        }

        private static void
            ExpandCrossRigidRewriteCoverageAcrossConfigurations(
                BatchState state,
                IEnumerable<CrossRigidMergePlanAccumulator> plans,
                IReadOnlyDictionary<
                    string,
                    CrossRigidAttachmentLocalExpansionResult>
                    visualConfigurationCache)
        {
            foreach (var plan in plans)
            {
                if (!visualConfigurationCache.TryGetValue(
                        Normalize(plan.VmdPath),
                        out var expansion) ||
                    expansion.FailureReason != null ||
                    !expansion.ConfigurationsByAttachment.TryGetValue(
                        plan.AttachmentIdentity,
                        out var configurations))
                {
                    continue;
                }

                var beforeProbability =
                    Math.Clamp(
                        MergeCrossRigidRewriteOccurrenceSets(
                                plan.RewriteOccurrenceSets)
                            .Sum(set => set.Probability),
                        0.0,
                        1.0);
                var expectedCounts =
                    BuildCrossRigidWsModelMultiplicity(
                        plan.SourceInstances);
                var projectedSets =
                    configurations
                        .Where(configuration =>
                            configuration.Probability > 0)
                        .SelectMany(configuration =>
                            BuildCrossRigidRewriteOccurrenceSets(
                                configuration,
                                expectedCounts))
                        .ToArray();
                if (projectedSets.Length == 0)
                    continue;

                var merged =
                    MergeCrossRigidRewriteOccurrenceSets(
                        projectedSets);
                plan.RewriteOccurrenceSets.Clear();
                plan.RewriteOccurrenceSets.AddRange(merged);

                var afterProbability =
                    Math.Clamp(
                        merged.Sum(set => set.Probability),
                        0.0,
                        1.0);
                if (afterProbability >
                    beforeProbability +
                    AtlasValueGateExpectedDrawEpsilon)
                {
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Cross-rigid merge coverage expanded across co-render states",
                        $"{plan.VmdPath} " +
                        $"[{plan.AttachmentIdentity}]: " +
                        $"{plan.SourceInstances.Length} source(s), " +
                        $"probability {beforeProbability:0.######} -> " +
                        $"{afterProbability:0.######}");
                }
            }
        }

        private static Dictionary<string, int>
            BuildCrossRigidWsModelMultiplicity(
                IEnumerable<CrossRigidVisualInstance> instances)
            => instances
                .Select(instance =>
                    Normalize(instance.WsModelPath))
                .GroupBy(
                    path => path,
                    StringComparer.OrdinalIgnoreCase)
                .ToDictionary(
                    group => group.Key,
                    group => group.Count(),
                    StringComparer.OrdinalIgnoreCase);

        private static IEnumerable<(
                CrossRigidAnalysisInstanceComponent[] Group,
                bool IsSubgroupFallback,
                int FallbackSize,
                CrossRigidAnalysisInstanceComponent[] FullGroup)>
            EnumerateCrossRigidCandidateGroups(
                CrossRigidAnalysisInstanceComponent[][] topologyGroups,
                BatchState state)
        {
            foreach (var group in topologyGroups)
            {
                // Keep the original complete merge candidate. Pairwise
                // alternatives are strictly additional choices for the
                // existing provenance validator and value/conflict gates.
                yield return (group, false, 0, group);
                if (group.Length < 3)
                    continue;

                var uniquePairs = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);
                var emitted = 0;
                for (var firstIndex = 0;
                     firstIndex < group.Length &&
                     emitted < MaxCrossRigidPairFallbacksPerGroup;
                     firstIndex++)
                {
                    for (var secondIndex = firstIndex + 1;
                         secondIndex < group.Length &&
                         emitted < MaxCrossRigidPairFallbacksPerGroup;
                         secondIndex++)
                    {
                        var first = group[firstIndex];
                        var second = group[secondIndex];
                        if (first.Component.RigidPath.Equals(
                                second.Component.RigidPath,
                                StringComparison.OrdinalIgnoreCase) ||
                            first.Instance.WsModelPath.Equals(
                                second.Instance.WsModelPath,
                                StringComparison.OrdinalIgnoreCase))
                            continue;

                        var paths = new[]
                        {
                            Normalize(first.Instance.WsModelPath),
                            Normalize(second.Instance.WsModelPath)
                        };
                        Array.Sort(
                            paths,
                            StringComparer.OrdinalIgnoreCase);
                        var pairKey = string.Join("\u001f", paths);
                        if (!uniquePairs.Add(pairKey))
                            continue;

                        emitted++;
                        yield return (
                            new[] { first, second },
                            true,
                            2,
                            group);
                    }
                }

                // The complete three-component case has already been
                // yielded above. For larger groups, fall back to a bounded
                // three-component merge, including combinations of different
                // WSModels which share a rigid path. Two distinct rigids are
                // still required to provide an actual cross-rigid merge.
                if (group.Length >= 4)
                {
                    var uniqueTriples = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    var emittedTriples = 0;
                    // Preserve the previously considered sixteen distinct-
                    // rigid triples exactly. Then examine eight additional
                    // combinations from the opposite end, including separate
                    // WSModels that reuse one of the selected rigid paths.
                    foreach (var scanForward in new[] { true, false })
                    {
                        var candidates = scanForward
                            ? group
                            : group.Reverse().ToArray();
                        // Preserve the original 16 forward and 8 reverse
                        // candidates. The expanded total reserves eight
                        // genuinely new choices for middle-out sampling.
                        var stageLimit = scanForward
                            ? 16
                            : MaxCrossRigidTripleFallbacksPerGroup - 8;
                        for (var firstIndex = 0;
                             firstIndex < candidates.Length &&
                             emittedTriples < stageLimit;
                             firstIndex++)
                        {
                            for (var secondIndex = firstIndex + 1;
                                 secondIndex < candidates.Length &&
                                 emittedTriples < stageLimit;
                                 secondIndex++)
                            {
                                for (var thirdIndex = secondIndex + 1;
                                     thirdIndex < candidates.Length &&
                                     emittedTriples < stageLimit;
                                     thirdIndex++)
                                {
                                    var items = new[]
                                    {
                                        candidates[firstIndex],
                                        candidates[secondIndex],
                                        candidates[thirdIndex],
                                    };
                                    if (items.Select(item =>
                                            item.Component.RigidPath)
                                        .Distinct(
                                            StringComparer.OrdinalIgnoreCase)
                                        .Count() < (scanForward ? 3 : 2))
                                        continue;

                                    var paths = items.Select(item =>
                                            Normalize(item.Instance.WsModelPath))
                                        .ToArray();
                                    if (paths.Distinct(
                                            StringComparer.OrdinalIgnoreCase)
                                        .Count() != 3)
                                        continue;

                                    Array.Sort(
                                        paths,
                                        StringComparer.OrdinalIgnoreCase);
                                    if (!uniqueTriples.Add(
                                            string.Join("\u001f", paths)))
                                        continue;

                                    emittedTriples++;
                                    yield return (
                                        items,
                                        true,
                                        3,
                                        group);
                                }
                            }
                        }
                    }
                    // The original first sixteen forward and eight reverse
                    // candidates remain unchanged. Examine a small third
                    // cohort around the middle, where large appearance groups
                    // otherwise never reach the fallback enumerator.
                    foreach (var items in
                             EnumerateCrossRigidDistinctFallbackSubsets(
                                     BuildCrossRigidMiddleOutFallbackOrder(group),
                                     3,
                                     uniqueTriples)
                                 .Take(MaxCrossRigidTripleFallbacksPerGroup -
                                       emittedTriples))
                    {
                        emittedTriples++;
                        state.CrossRigidMiddleTripleFallbackSubgroupObservations++;
                        yield return (items, true, 3, group);
                    }
                }

                // A full group with exactly four components is already
                // represented by its original candidate. Only groups with
                // at least five members can have a true four-way fallback.
                // All WSModel paths must be different, but source rigid paths
                // may repeat because distinct WSModels are distinct render
                // occurrences. Require two different rigids and pass every
                // candidate through the existing provenance/value gates.
                if (group.Length >= 5 &&
                    group.Select(item => item.Component.RigidPath)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .Count() >= 2)
                {
                    var uniqueQuadruples = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    var emittedQuadruples = 0;
                    // Preserve the original eight distinct-rigid candidates
                    // before adding up to eight more from the opposite end,
                    // including WSModels backed by repeated rigid sources.
                    foreach (var scanForward in new[] { true, false })
                    {
                        var candidates = scanForward
                            ? group
                            : group.Reverse().ToArray();
                        // Preserve the original 8 forward and 8 reverse
                        // candidates; reserve the last 8 for middle-out
                        // groups rather than letting reverse exhaust them.
                        var stageLimit = scanForward
                            ? 8
                            : MaxCrossRigidQuadrupleFallbacksPerGroup - 8;
                        for (var firstIndex = 0;
                             firstIndex < candidates.Length &&
                             emittedQuadruples < stageLimit;
                             firstIndex++)
                        {
                            for (var secondIndex = firstIndex + 1;
                                 secondIndex < candidates.Length &&
                                 emittedQuadruples < stageLimit;
                                 secondIndex++)
                            {
                                for (var thirdIndex = secondIndex + 1;
                                     thirdIndex < candidates.Length &&
                                     emittedQuadruples < stageLimit;
                                     thirdIndex++)
                                {
                                    for (var fourthIndex = thirdIndex + 1;
                                         fourthIndex < candidates.Length &&
                                         emittedQuadruples < stageLimit;
                                         fourthIndex++)
                                    {
                                        var items = new[]
                                        {
                                            candidates[firstIndex],
                                            candidates[secondIndex],
                                            candidates[thirdIndex],
                                            candidates[fourthIndex],
                                        };
                                        if (items.Select(item =>
                                                item.Component.RigidPath)
                                            .Distinct(
                                                StringComparer.OrdinalIgnoreCase)
                                            .Count() < (scanForward ? 4 : 2))
                                            continue;

                                        var paths = items.Select(item =>
                                                Normalize(item.Instance.WsModelPath))
                                            .ToArray();
                                        if (paths.Distinct(
                                                StringComparer.OrdinalIgnoreCase)
                                            .Count() != 4)
                                            continue;

                                        Array.Sort(
                                            paths,
                                            StringComparer.OrdinalIgnoreCase);
                                        if (!uniqueQuadruples.Add(
                                                string.Join("\u001f", paths)))
                                            continue;

                                        emittedQuadruples++;
                                        yield return (
                                            items,
                                            true,
                                            4,
                                            group);
                                    }
                                }
                            }
                        }
                    }
                    // Preserve the original eight forward and eight reverse
                    // quadruples, then look at the middle of long groups.
                    foreach (var items in
                             EnumerateCrossRigidDistinctFallbackSubsets(
                                     BuildCrossRigidMiddleOutFallbackOrder(group),
                                     4,
                                     uniqueQuadruples)
                                 .Take(MaxCrossRigidQuadrupleFallbacksPerGroup -
                                       emittedQuadruples))
                    {
                        emittedQuadruples++;
                        state.CrossRigidMiddleQuadrupleFallbackSubgroupObservations++;
                        yield return (items, true, 4, group);
                    }
                }

                // When a six-or-larger full group exceeds the rewrite state
                // budget, a bounded five-way subset may recover four draws.
                // Only genuinely distinct WSModel occurrences are combined;
                // repeated rigid paths are fine if at least two remain.
                if (group.Length >= 6 &&
                    group.Select(item => item.Component.RigidPath)
                        .Distinct(StringComparer.OrdinalIgnoreCase).Count() >= 2 &&
                    group.Select(item => Normalize(item.Instance.WsModelPath))
                        .Distinct(StringComparer.OrdinalIgnoreCase).Count() >= 5)
                {
                    var seen = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    var emittedQuintuples = 0;
                    var orders = new[]
                    {
                        group,
                        group.Reverse().ToArray(),
                        BuildCrossRigidMiddleOutFallbackOrder(group)
                    };
                    for (var pass = 0; pass < orders.Length; pass++)
                    {
                        var stageLimit =
                            (pass + 1) * MaxCrossRigidQuintupleFallbacksPerGroup /
                            orders.Length;
                        foreach (var items in
                                 EnumerateCrossRigidDistinctFallbackSubsets(
                                         orders[pass], 5, seen)
                                     .Take(stageLimit - emittedQuintuples))
                        {
                            emittedQuintuples++;
                            yield return (items, true, 5, group);
                        }
                    }
                }
            }
        }

        // A third sampling order prevents lexicographic prefix/suffix caps
        // from excluding all components near the middle of long groups.
        private static CrossRigidAnalysisInstanceComponent[]
            BuildCrossRigidMiddleOutFallbackOrder(
                CrossRigidAnalysisInstanceComponent[] group)
            => group.Select((item, index) => (Item: item, Index: index))
                .OrderBy(item => Math.Abs(
                    2 * item.Index - (group.Length - 1)))
                .ThenBy(item => item.Index)
                .Select(item => item.Item)
                .ToArray();

        // All new subsets remain subject to the same topology, provenance,
        // state-budget, generated-geometry and value gates as full groups.
        // Limit the search effort as well as the number of emitted subsets.
        private static IEnumerable<CrossRigidAnalysisInstanceComponent[]>
            EnumerateCrossRigidDistinctFallbackSubsets(
                CrossRigidAnalysisInstanceComponent[] candidates,
                int size,
                HashSet<string> seen)
        {
            const int maxInspectedCombinations = 512;
            var selected = new CrossRigidAnalysisInstanceComponent[size];
            var inspected = 0;
            return Enumerate(0, 0);

            IEnumerable<CrossRigidAnalysisInstanceComponent[]> Enumerate(
                int nextIndex, int depth)
            {
                if (inspected >= maxInspectedCombinations)
                    yield break;
                if (depth == size)
                {
                    inspected++;
                    if (selected.Select(item => item.Component.RigidPath)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count() < 2)
                        yield break;

                    var paths = selected.Select(item =>
                            Normalize(item.Instance.WsModelPath))
                        .ToArray();
                    if (paths.Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count() != size)
                        yield break;

                    Array.Sort(paths, StringComparer.OrdinalIgnoreCase);
                    if (seen.Add(string.Join("\u001f", paths)))
                        yield return selected.ToArray();
                    yield break;
                }

                for (var index = nextIndex;
                     index <= candidates.Length - (size - depth) &&
                     inspected < maxInspectedCombinations;
                     index++)
                {
                    selected[depth] = candidates[index];
                    foreach (var subset in Enumerate(index + 1, depth + 1))
                        yield return subset;
                }
            }
        }

        private static string BuildCrossRigidRewritePlanKey(
            string vmdPath,
            string attachmentIdentity,
            IReadOnlyList<CrossRigidAnalysisInstanceComponent> group)
            => string.Join(
                "\u001f",
                Normalize(vmdPath),
                attachmentIdentity,
                string.Join(
                    "\u001e",
                    group
                        .Select(item => item.Instance.WsModelPath)
                        .OrderBy(
                            path => path,
                            StringComparer.OrdinalIgnoreCase)));

        private enum CrossRigidActivationRewriteClass
        {
            ExactActivationSafe,
            JointAlwaysPresentSlots,
            JointOptionalSlots,
            LocalModelModifiers,
            Unclassifiable,
        }

        private static bool
            IsCrossRigidRewriteOccurrenceSetActivationSafe(
                CrossRigidRewriteOccurrenceSet occurrenceSet)
            => occurrenceSet.SourceInstances.Length >= 2 &&
               occurrenceSet.SourceInstances
                   .Select(instance => instance.ActivationSignature)
                   .Distinct(StringComparer.Ordinal)
                   .Count() == 1 &&
               occurrenceSet.SourceInstances.All(instance =>
                   !instance.HasRewriteBlockingModifiers);

        private static CrossRigidActivationRewriteClass
            ClassifyCrossRigidRewriteOccurrenceSet(
                BatchState state,
                CrossRigidRewriteOccurrenceSet occurrenceSet,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out string detail)
        {
            if (occurrenceSet.SourceInstances.Any(instance =>
                    instance.HasRewriteBlockingModifiers))
            {
                detail =
                    BuildCrossRigidModifierProfile(
                        occurrenceSet,
                        []);
                return CrossRigidActivationRewriteClass.LocalModelModifiers;
            }

            return ClassifyCrossRigidRewriteOccurrenceSetTopology(
                state,
                occurrenceSet,
                sourceVmdDocuments,
                out detail);
        }

        private static CrossRigidActivationRewriteClass
            ClassifyCrossRigidRewriteOccurrenceSetTopology(
                BatchState state,
                CrossRigidRewriteOccurrenceSet occurrenceSet,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out string detail)
        {
            detail = string.Empty;
            if (occurrenceSet.SourceInstances.Length < 2)
            {
                detail = "fewer than two source model occurrences";
                return CrossRigidActivationRewriteClass.Unclassifiable;
            }

            var activationSignatures =
                occurrenceSet.SourceInstances
                    .Select(instance => instance.ActivationSignature)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray();
            if (activationSignatures.Length == 1)
            {
                return CrossRigidActivationRewriteClass.ExactActivationSafe;
            }

            var tokenSets = occurrenceSet.SourceInstances
                .Select(instance =>
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? new HashSet<string>(StringComparer.Ordinal)
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .ToHashSet(StringComparer.Ordinal))
                .ToArray();
            if (tokenSets.Length == 0)
            {
                detail = "activation signature set is empty";
                return CrossRigidActivationRewriteClass.Unclassifiable;
            }

            var commonTokens = new HashSet<string>(
                tokenSets[0],
                StringComparer.Ordinal);
            foreach (var tokenSet in tokenSets.Skip(1))
                commonTokens.IntersectWith(tokenSet);

            var differingTokens = tokenSets
                .SelectMany(tokens => tokens)
                .Where(token => !commonTokens.Contains(token))
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            if (differingTokens.Length == 0)
            {
                detail =
                    "activation signatures differ only by token ordering";
                return CrossRigidActivationRewriteClass.Unclassifiable;
            }

            var hasOptionalSlot = false;
            foreach (var token in differingTokens)
            {
                if (!TryClassifyCrossRigidActivationToken(
                        state,
                        token,
                        sourceVmdDocuments,
                        out var optionalSlot,
                        out var tokenReason))
                {
                    detail = tokenReason;
                    return CrossRigidActivationRewriteClass.Unclassifiable;
                }

                hasOptionalSlot |= optionalSlot;
            }

            detail =
                $"{differingTokens.Length} differing activation token(s)";
            return hasOptionalSlot
                ? CrossRigidActivationRewriteClass.JointOptionalSlots
                : CrossRigidActivationRewriteClass.JointAlwaysPresentSlots;
        }

        private static string BuildCrossRigidModifierProfile(
            CrossRigidRewriteOccurrenceSet occurrenceSet,
            IReadOnlyList<CrossRigidSourceGeometryComponent>
                sourceGeometry)
        {
            var rigidByWsModel = sourceGeometry
                .GroupBy(
                    source => source.WsModelPath,
                    StringComparer.OrdinalIgnoreCase)
                .ToDictionary(
                    group => group.Key,
                    group => group.First().RigidPath,
                    StringComparer.OrdinalIgnoreCase);

            var imposterInstances = occurrenceSet.SourceInstances
                .Where(instance =>
                    !string.IsNullOrWhiteSpace(
                        instance.ImposterModelPath))
                .ToArray();
            var hasMirroredImposter = false;
            var hasIndependentImposter = false;
            foreach (var instance in imposterInstances)
            {
                if (rigidByWsModel.TryGetValue(
                        instance.WsModelPath,
                        out var rigidPath) &&
                    Normalize(instance.ImposterModelPath).Equals(
                        Normalize(rigidPath),
                        StringComparison.OrdinalIgnoreCase))
                {
                    hasMirroredImposter = true;
                }
                else
                {
                    hasIndependentImposter = true;
                }
            }

            var parts = new List<string>();
            if (hasMirroredImposter)
                parts.Add("imposter mirrors source rigid");
            if (hasIndependentImposter)
                parts.Add("independent imposter geometry");
            if (occurrenceSet.SourceInstances.Any(instance =>
                    instance.HasDecalDiffuse ||
                    instance.HasDecalNormal))
            {
                var hasDiffuse = occurrenceSet.SourceInstances.Any(
                    instance => instance.HasDecalDiffuse);
                var hasNormal = occurrenceSet.SourceInstances.Any(
                    instance => instance.HasDecalNormal);
                parts.Add(
                    hasDiffuse && hasNormal
                        ? "diffuse+normal decal"
                        : hasDiffuse
                            ? "diffuse decal"
                            : "normal decal");
            }

            if (occurrenceSet.SourceInstances.Any(instance =>
                    instance.HasMetadata))
            {
                parts.Add("metadata");
            }

            // When source geometry is unavailable (for the broad diagnostic
            // emitted before a plan is materialized), retain imposter presence
            // instead of incorrectly classifying it as independent geometry.
            if (imposterInstances.Length != 0 &&
                sourceGeometry.Count == 0)
            {
                parts.Remove("independent imposter geometry");
                parts.Remove("imposter mirrors source rigid");
                parts.Insert(0, "imposter_model");
            }

            return parts.Count == 0
                ? "none"
                : string.Join(" + ", parts);
        }

        private static bool TryDescribeCrossRigidJointAlwaysPresentRewrite(
            BatchState state,
            CrossRigidRewriteOccurrenceSet occurrenceSet,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
            out string reason)
        {
            descriptor = null!;
            reason = string.Empty;
            if (occurrenceSet.SourceInstances.Length < 2)
            {
                reason = "fewer than two source model occurrences";
                return false;
            }

            if (occurrenceSet.SourceInstances.Any(instance =>
                    instance.HasRewriteBlockingModifiers))
            {
                reason =
                    "source occurrence has imposter or decal state";
                return false;
            }

            var tokenSets = occurrenceSet.SourceInstances
                .Select(instance =>
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? new HashSet<string>(StringComparer.Ordinal)
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .ToHashSet(StringComparer.Ordinal))
                .ToArray();
            if (tokenSets.Length == 0)
            {
                reason = "activation signature set is empty";
                return false;
            }

            var commonTokens = new HashSet<string>(
                tokenSets[0],
                StringComparer.Ordinal);
            foreach (var tokenSet in tokenSets.Skip(1))
                commonTokens.IntersectWith(tokenSet);

            var candidates =
                new List<CrossRigidJointSourceSelectionCandidate>();
            var candidateFailureReasons =
                new List<string>();
            var requiredOptionalDimensionKeys =
                new HashSet<string>(
                    StringComparer.Ordinal);
            foreach (var differingToken in
                     tokenSets
                         .SelectMany(tokens => tokens)
                         .Where(token =>
                             !commonTokens.Contains(token))
                         .Distinct(StringComparer.Ordinal))
            {
                if (!TryParseCrossRigidActivationToken(
                        state,
                        differingToken,
                        sourceVmdDocuments,
                        out var differingSelection,
                        out var differingReason))
                {
                    candidateFailureReasons.Add(
                        differingReason);
                    continue;
                }

                if (!differingSelection.OptionalSlot)
                    continue;

                // Every differing optional slot must remain explicit even
                // when its probability/topology is not yet supported. That
                // prevents a deeper terminal selection from bypassing an
                // unsupported optional ancestor.
                requiredOptionalDimensionKeys.Add(
                    BuildCrossRigidJointSelectionDimensionKey(
                        differingSelection.OwnerVmdPath,
                        differingSelection.ParentXmlPath,
                        differingSelection.SlotIndex));

                if (!TryValidateCrossRigidOptionalJointSelection(
                        state,
                        differingSelection,
                        sourceVmdDocuments,
                        out var optionalReason))
                {
                    candidateFailureReasons.Add(
                        optionalReason);
                    continue;
                }
            }

            for (var instanceIndex = 0;
                 instanceIndex < occurrenceSet.SourceInstances.Length;
                 instanceIndex++)
            {
                var instance =
                    occurrenceSet.SourceInstances[instanceIndex];
                var orderedDifferingTokens =
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? Array.Empty<string>()
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .Where(token =>
                                !commonTokens.Contains(token))
                            .ToArray();
                if (orderedDifferingTokens.Length == 0)
                    continue;

                // Only the terminal varying selection fully determines this
                // source occurrence. Anchoring at an outer token while a
                // deeper alternative still varies would remove geometry from
                // sibling descendant states that are not part of this merge.
                var token =
                    orderedDifferingTokens[^1];
                if (!TryParseCrossRigidActivationToken(
                        state,
                        token,
                        sourceVmdDocuments,
                        out var tokenSelection,
                        out var tokenReason))
                {
                    candidateFailureReasons.Add(tokenReason);
                    continue;
                }

                if (tokenSelection.OptionalSlot &&
                    !TryValidateCrossRigidOptionalJointSelection(
                        state,
                        tokenSelection,
                        sourceVmdDocuments,
                        out var optionalSelectionReason))
                {
                    candidateFailureReasons.Add(
                        optionalSelectionReason);
                    continue;
                }

                if (!TryGetCrossRigidReferenceChainPrefixToVmd(
                        instance,
                        tokenSelection.OwnerVmdPath,
                        out var anchorReferenceChain))
                {
                    candidateFailureReasons.Add(
                        "selection owner is not on the source model VMD provenance chain");
                    continue;
                }

                if (!TryBuildCrossRigidJointSourceSelection(
                        instance,
                        tokenSelection,
                        anchorReferenceChain,
                        out var sourceSelection,
                        out var selectionReason))
                {
                    candidateFailureReasons.Add(selectionReason);
                    continue;
                }

                candidates.Add(
                    new CrossRigidJointSourceSelectionCandidate(
                        instanceIndex,
                        tokenSelection.OwnerVmdPath,
                        tokenSelection.ParentXmlPath,
                        anchorReferenceChain,
                        sourceSelection));
            }

            var candidateGroups = candidates
                .GroupBy(candidate => string.Join(
                    "\u001f",
                    BuildCrossRigidReferenceChainSignature(
                        candidate.AnchorReferenceChain),
                    candidate.AnchorVmdPath,
                    candidate.ParentXmlPath),
                    StringComparer.Ordinal)
                .Where(group =>
                    group
                        .Select(candidate =>
                            candidate.InstanceIndex)
                        .Distinct()
                        .Count() ==
                    occurrenceSet.SourceInstances.Length)
                .Select(group =>
                {
                    var perInstance = group
                        .GroupBy(candidate =>
                            candidate.InstanceIndex)
                        .OrderBy(instanceGroup =>
                            instanceGroup.Key)
                        .Select(instanceGroup =>
                            instanceGroup
                                .OrderBy(candidate =>
                                    candidate.SourceSelection.SlotIndex)
                                .ThenBy(candidate =>
                                    candidate.SourceSelection.AlternativeIndex)
                                .First())
                        .ToArray();
                    return new
                    {
                        Candidates = perInstance,
                        AnchorDepth =
                            perInstance[0].AnchorReferenceChain.Length,
                        ParentDepth =
                            perInstance[0].ParentXmlPath.Count(
                                character => character == '/'),
                    };
                })
                .OrderBy(group => group.AnchorDepth)
                .ThenBy(group => group.ParentDepth)
                .ThenBy(group =>
                    group.Candidates[0].AnchorVmdPath,
                    StringComparer.OrdinalIgnoreCase)
                .ThenBy(group =>
                    group.Candidates[0].ParentXmlPath,
                    StringComparer.Ordinal)
                .ToArray();

            foreach (var candidateGroup in candidateGroups)
            {
                var selectedCandidates =
                    candidateGroup.Candidates;
                var sourceSelections =
                    selectedCandidates
                        .Select(candidate =>
                            candidate.SourceSelection)
                        .ToArray();

                var incompatibleSharedSlot =
                    sourceSelections
                        .GroupBy(selection =>
                            selection.SlotIndex)
                        .Any(slotGroup =>
                            slotGroup
                                .Select(selection =>
                                    string.Join(
                                        ":",
                                        selection.IsReference
                                            ? "r"
                                            : "m",
                                        selection.AlternativeIndex))
                                .Distinct(StringComparer.Ordinal)
                                .Count() != 1);
                if (incompatibleSharedSlot)
                    continue;

                var selectedDimensionKeys =
                    sourceSelections
                        .Select(
                            BuildCrossRigidJointSourceSelectionDimensionKey)
                        .ToHashSet(
                            StringComparer.Ordinal);
                if (!requiredOptionalDimensionKeys.IsSubsetOf(
                        selectedDimensionKeys))
                {
                    candidateFailureReasons.Add(
                        "same-parent optional writer requires every differing optional slot to be an explicit Cartesian dimension");
                    continue;
                }

                var anchorVmdPath =
                    selectedCandidates[0].AnchorVmdPath;
                var parentXmlPath =
                    selectedCandidates[0].ParentXmlPath;
                var anchorReferenceChain =
                    selectedCandidates[0].AnchorReferenceChain;

                if (!TryGetCrossRigidSourceVmdDocument(
                        state,
                        anchorVmdPath,
                        sourceVmdDocuments,
                        out var anchorDocument,
                        out var anchorReason) ||
                    anchorDocument.SelectSingleNode(
                        parentXmlPath) is not XmlElement parentElement)
                {
                    candidateFailureReasons.Add(
                        string.IsNullOrWhiteSpace(anchorReason)
                            ? "joint parent VARIANT_MESH could not be resolved"
                            : anchorReason);
                    continue;
                }

                var slotIndices =
                    sourceSelections
                        .Select(selection =>
                            selection.SlotIndex)
                        .Distinct()
                        .OrderBy(index => index)
                        .ToArray();
                long combinationCount = 1;
                var valid = true;
                foreach (var slotIndex in slotIndices)
                {
                    if (parentElement.SelectSingleNode(
                            $"SLOT[{slotIndex}]") is
                        not XmlElement slotElement)
                    {
                        valid = false;
                        candidateFailureReasons.Add(
                            $"joint source slot {slotIndex} no longer resolves");
                        break;
                    }

                    var probability =
                        ParseVmdSlotProbability(
                            slotElement.GetAttribute("probability"));
                    if (probability <
                            1.0 - AtlasValueGateExpectedDrawEpsilon &&
                        !IsSupportedCrossRigidOptionalJointSlot(
                            slotElement))
                    {
                        valid = false;
                        candidateFailureReasons.Add(
                            $"joint source slot {slotIndex} has an unsupported optional probability/topology");
                        break;
                    }

                    var alternatives =
                        GetCrossRigidJointAlternatives(
                            slotElement,
                            slotIndex);
                    if (alternatives.Length <= 1)
                    {
                        valid = false;
                        candidateFailureReasons.Add(
                            $"joint source slot {slotIndex} is not an alternative slot");
                        break;
                    }

                    combinationCount *=
                        alternatives.Sum(alternative =>
                            alternative.Multiplicity);
                    if (combinationCount >
                        MaxCrossRigidJointStateCombinations)
                    {
                        valid = false;
                        candidateFailureReasons.Add(
                            $"joint Cartesian product exceeds " +
                            $"{MaxCrossRigidJointStateCombinations:N0} combinations");
                        break;
                    }
                }

                if (!valid)
                    continue;

                descriptor =
                    new CrossRigidJointAlwaysPresentRewriteDescriptor(
                        anchorVmdPath,
                        parentXmlPath,
                        anchorReferenceChain,
                        sourceSelections
                            .OrderBy(selection =>
                                selection.SlotIndex)
                            .ThenBy(selection =>
                                BuildCrossRigidOccurrenceProvenanceSignature(
                                    [selection.Instance]),
                                StringComparer.Ordinal)
                            .ToArray(),
                        slotIndices,
                        (int)combinationCount,
                        []);
                return true;
            }

            if (TryDescribeCrossRigidFixedReferenceCommonAncestorRewrite(
                    state,
                    occurrenceSet,
                    sourceVmdDocuments,
                    out descriptor,
                    out var commonAncestorReason))
            {
                return true;
            }

            if (TryDescribeCrossRigidFixedLocalCommonAncestorRewrite(
                    state,
                    occurrenceSet,
                    sourceVmdDocuments,
                    out descriptor,
                    out var localCommonAncestorReason))
            {
                return true;
            }

            // Prefer the general cross-VMD common-ancestor explanation.
            // The fixed-local fallback reports a generic "different
            // defining VMDs" for any mixed-source case, masking the
            // specific reference-carrier or optional-topology constraint.
            reason =
                candidateGroups.Length == 0
                    ? new[]
                        {
                            commonAncestorReason,
                            localCommonAncestorReason,
                        }
                        .FirstOrDefault(value =>
                            !string.IsNullOrWhiteSpace(value)) ??
                      "shared structural parent could not be materialized safely"
                    : candidateFailureReasons
                        .Append(commonAncestorReason)
                        .Append(localCommonAncestorReason)
                        .FirstOrDefault(value =>
                            !string.IsNullOrWhiteSpace(value)) ??
                      "shared structural parent could not be materialized safely";
            return false;
        }

        private static bool
            TryDescribeCrossRigidFixedReferenceCommonAncestorRewrite(
                BatchState state,
                CrossRigidRewriteOccurrenceSet occurrenceSet,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
                out string reason)
        {
            descriptor = null!;
            reason = string.Empty;

            var instances = occurrenceSet.SourceInstances;
            if (instances.Length < 2)
            {
                reason =
                    "common-ancestor joint has fewer than two source occurrences";
                return false;
            }

            var tokenSets = instances
                .Select(instance =>
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? new HashSet<string>(StringComparer.Ordinal)
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .ToHashSet(StringComparer.Ordinal))
                .ToArray();
            var commonTokens = new HashSet<string>(
                tokenSets[0],
                StringComparer.Ordinal);
            foreach (var tokenSet in tokenSets.Skip(1))
                commonTokens.IntersectWith(tokenSet);

            var commonReferenceChain =
                GetCrossRigidCommonReferenceChainPrefix(instances);
            string anchorVmdPath;
            if (commonReferenceChain.Length != 0)
            {
                anchorVmdPath =
                    Normalize(
                        commonReferenceChain[^1].ReferencedVmdPath);
            }
            else
            {
                var rootVmdPaths = instances
                    .Select(instance =>
                        instance.ReferenceChain.Length == 0
                            ? Normalize(instance.DefiningVmdPath)
                            : Normalize(
                                instance.ReferenceChain[0].OwnerVmdPath))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                if (rootVmdPaths.Length != 1)
                {
                    reason =
                        "source selections do not share one structural root VMD";
                    return false;
                }

                anchorVmdPath = rootVmdPaths[0];
            }

            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    anchorVmdPath,
                    sourceVmdDocuments,
                    out var anchorDocument,
                    out reason))
            {
                return false;
            }

            string? anchorParentXmlPath = null;
            var sourceSelections =
                new List<CrossRigidJointSourceSelection>();
            var fixedSourceInstances =
                new List<CrossRigidVisualInstance>();
            var fixedCarrierSlotIndices =
                new HashSet<int>();
            var dimensionsByKey =
                new Dictionary<
                    string,
                    CrossRigidJointSelectionDimension>(
                    StringComparer.Ordinal);

            for (var instanceIndex = 0;
                 instanceIndex < instances.Length;
                 instanceIndex++)
            {
                var instance = instances[instanceIndex];
                var orderedDifferingTokens =
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? Array.Empty<string>()
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .Where(token =>
                                !commonTokens.Contains(token))
                            .ToArray();
                if (orderedDifferingTokens.Length == 0)
                {
                    if (!TryValidateCrossRigidFixedCommonAncestorSourceInstance(
                            state,
                            instance,
                            sourceVmdDocuments,
                            out reason))
                    {
                        return false;
                    }

                    fixedSourceInstances.Add(instance);
                    continue;
                }

                var dependencySelections =
                    new List<CrossRigidActivationTokenSelection>();
                var conditionalChildSelections =
                    new List<CrossRigidActivationTokenSelection>();
                foreach (var differingToken in
                         orderedDifferingTokens)
                {
                    if (!TryParseCrossRigidActivationToken(
                            state,
                            differingToken,
                            sourceVmdDocuments,
                            out var dependencySelection,
                            out reason))
                    {
                        return false;
                    }

                    // Optional dimensions are admitted only when their
                    // probability has an exact bounded representation.
                    // Parent/child dependence is resolved after collecting
                    // the entire ordered activation chain, rather than
                    // assuming the optional token must be its root.
                    if (dependencySelection.OptionalSlot &&
                        !TryValidateCrossRigidOptionalJointSelection(
                            state,
                            dependencySelection,
                            sourceVmdDocuments,
                            out reason))
                    {
                        return false;
                    }

                    if (!TryGetCrossRigidReferenceChainPrefixToVmd(
                            instance,
                            dependencySelection.OwnerVmdPath,
                            out var dependencyReferenceChain) ||
                        !TryBuildCrossRigidJointSourceSelection(
                            instance,
                            dependencySelection,
                            dependencyReferenceChain,
                            out _,
                            out reason))
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                        {
                            reason =
                                "dependency selection is not on the source provenance chain";
                        }

                        return false;
                    }

                    dependencySelections.Add(
                        dependencySelection);
                }

                // Fixed single-reference prefixes are provenance, not
                // independent appearance choices. Keeping them as the
                // dependency root incorrectly excludes independent child-VMD
                // slots such as teb_billmen -> teb_militia_base -> torso.
                // Preserve the reference hop in the instance's chain so the
                // generated VMD is still cloned copy-on-write.
                while (dependencySelections.Count > 1 &&
                       dependencySelections[0].IsReference)
                {
                    var fixedPrefix = dependencySelections[0];
                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            fixedPrefix.OwnerVmdPath,
                            sourceVmdDocuments,
                            out var prefixDocument,
                            out reason) ||
                        prefixDocument.SelectSingleNode(
                            $"{fixedPrefix.ParentXmlPath}/SLOT[{fixedPrefix.SlotIndex}]") is
                            not XmlElement prefixSlot)
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                            reason = "Fixed reference prefix slot is missing";
                        return false;
                    }

                    if (ParseVmdSlotProbability(
                            prefixSlot.GetAttribute("probability")) <
                            1.0 - AtlasValueGateExpectedDrawEpsilon ||
                        (prefixSlot.SelectNodes("VARIANT_MESH")?.Count ?? 0) != 0 ||
                        (prefixSlot.SelectNodes("VARIANT_MESH_REFERENCE")?.Count ?? 0) != 1 ||
                        fixedPrefix.AlternativeIndex != 1)
                    {
                        break;
                    }

                    dependencySelections.RemoveAt(0);
                    orderedDifferingTokens =
                        orderedDifferingTokens.Skip(1).ToArray();
                }

                // Each varying child must exist only under its exact parent
                // alternative. Preserve the full conditional chain rather
                // than treating a grandchild as an independent Cartesian
                // dimension. Deterministic intermediate selections are
                // included to preserve the parent/child provenance, but a
                // deterministic terminal suffix needs no extra dimension.
                var tokenSelection = dependencySelections[0];
                var lastVaryingSelectionIndex = 0;
                for (var selectionIndex = 1;
                     selectionIndex < dependencySelections.Count;
                     selectionIndex++)
                {
                    var descendant = dependencySelections[selectionIndex];
                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            descendant.OwnerVmdPath,
                            sourceVmdDocuments,
                            out var descendantDocument,
                            out reason) ||
                        descendantDocument.SelectSingleNode(
                            $"{descendant.ParentXmlPath}/SLOT[{descendant.SlotIndex}]") is
                            not XmlElement descendantSlot)
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                            reason = "Nested conditional selection slot is missing";
                        return false;
                    }

                    if (GetCrossRigidJointAlternatives(
                            descendantSlot,
                            descendant.SlotIndex).Length > 1)
                    {
                        lastVaryingSelectionIndex = selectionIndex;
                    }
                }

                if (lastVaryingSelectionIndex != 0)
                {
                    for (var selectionIndex = 1;
                         selectionIndex <= lastVaryingSelectionIndex;
                         selectionIndex++)
                    {
                        var parentSelection =
                            dependencySelections[selectionIndex - 1];
                        var childSelection =
                            dependencySelections[selectionIndex];
                        var expectedChildParent =
                            $"{parentSelection.ParentXmlPath}/" +
                            $"SLOT[{parentSelection.SlotIndex}]/" +
                            $"VARIANT_MESH[{parentSelection.AlternativeIndex}]";
                        var isDirectReferencedChild = false;
                        if (parentSelection.IsReference &&
                            Normalize(parentSelection.OwnerVmdPath).Equals(
                                anchorVmdPath,
                                StringComparison.OrdinalIgnoreCase) &&
                            TryGetCrossRigidReferenceChainPrefixToVmd(
                                instance,
                                childSelection.OwnerVmdPath,
                                out var childReferenceChain) &&
                            childReferenceChain.Length ==
                                commonReferenceChain.Length + 1)
                        {
                            var referenceHop = childReferenceChain[^1];
                            var expectedReferencePath =
                                $"{parentSelection.ParentXmlPath}/" +
                                $"SLOT[{parentSelection.SlotIndex}]/" +
                                $"VARIANT_MESH_REFERENCE[{parentSelection.AlternativeIndex}]";
                            isDirectReferencedChild =
                                Normalize(referenceHop.OwnerVmdPath).Equals(
                                    Normalize(parentSelection.OwnerVmdPath),
                                    StringComparison.OrdinalIgnoreCase) &&
                                Normalize(referenceHop.ReferencedVmdPath).Equals(
                                    Normalize(childSelection.OwnerVmdPath),
                                    StringComparison.OrdinalIgnoreCase) &&
                                referenceHop.ReferenceXmlPath.Equals(
                                    expectedReferencePath,
                                    StringComparison.Ordinal) &&
                                childSelection.ParentXmlPath.StartsWith(
                                    "/VARIANT_MESH",
                                    StringComparison.Ordinal);
                        }

                        var isLocalChild =
                            !parentSelection.IsReference &&
                            Normalize(childSelection.OwnerVmdPath).Equals(
                                Normalize(parentSelection.OwnerVmdPath),
                                StringComparison.OrdinalIgnoreCase) &&
                            childSelection.ParentXmlPath.Equals(
                                expectedChildParent,
                                StringComparison.Ordinal);
                        if (!isLocalChild &&
                            !isDirectReferencedChild)
                        {
                            reason =
                                "common-ancestor optional dependency has nested varying selections";
                            return false;
                        }

                        conditionalChildSelections.Add(childSelection);
                    }
                }

                if (!TryValidateCrossRigidDeterministicJointSuffix(
                        state,
                        orderedDifferingTokens.Skip(
                            lastVaryingSelectionIndex + 1),
                        sourceVmdDocuments,
                        out reason))
                {
                    return false;
                }

                var sourceTokenSelection =
                    conditionalChildSelections.Count == 0
                        ? tokenSelection
                        : conditionalChildSelections[^1];

                if (!TryGetCrossRigidReferenceChainPrefixToVmd(
                        instance,
                        tokenSelection.OwnerVmdPath,
                        out var ownerReferenceChain))
                {
                    reason =
                        "dependency-root selection owner is not on the source provenance chain";
                    return false;
                }

                if (ownerReferenceChain.Length <
                    commonReferenceChain.Length)
                {
                    reason =
                        "terminal selection precedes the common structural anchor";
                    return false;
                }

                for (var hopIndex = 0;
                     hopIndex < commonReferenceChain.Length;
                     hopIndex++)
                {
                    if (!AreCrossRigidReferenceHopsEqual(
                            ownerReferenceChain[hopIndex],
                            commonReferenceChain[hopIndex]))
                    {
                        reason =
                            "terminal selection provenance diverges before the common structural anchor";
                        return false;
                    }
                }

                if (!TryGetCrossRigidReferenceChainPrefixToVmd(
                        instance,
                        sourceTokenSelection.OwnerVmdPath,
                        out var sourceReferenceChain) ||
                    !TryBuildCrossRigidJointSourceSelection(
                        instance,
                        sourceTokenSelection,
                        sourceReferenceChain,
                        out var sourceSelection,
                        out reason))
                {
                    return false;
                }

                int carrierSlotIndex;
                string currentAnchorParentXmlPath;
                var relativeReferenceChain =
                    ownerReferenceChain
                        .Skip(commonReferenceChain.Length)
                        .ToArray();

                if (Normalize(tokenSelection.OwnerVmdPath).Equals(
                        anchorVmdPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    currentAnchorParentXmlPath =
                        tokenSelection.ParentXmlPath;
                    carrierSlotIndex =
                        tokenSelection.SlotIndex;
                    if (relativeReferenceChain.Length != 0)
                    {
                        reason =
                            "direct anchor selection unexpectedly retains descendant reference hops";
                        return false;
                    }
                }
                else
                {
                    if (relativeReferenceChain.Length == 0 ||
                        !Normalize(
                                relativeReferenceChain[0].OwnerVmdPath)
                            .Equals(
                                anchorVmdPath,
                                StringComparison.OrdinalIgnoreCase) ||
                        !TryParseCrossRigidReferenceSlotLocation(
                            relativeReferenceChain[0].ReferenceXmlPath,
                            out currentAnchorParentXmlPath,
                            out carrierSlotIndex,
                            out _))
                    {
                        reason =
                            "common-ancestor carrier slot could not be identified";
                        return false;
                    }

                    foreach (var hop in relativeReferenceChain)
                    {
                        if (!TryParseCrossRigidReferenceSlotLocation(
                                hop.ReferenceXmlPath,
                                out var hopParentXmlPath,
                                out var hopSlotIndex,
                                out var hopReferenceIndex) ||
                            !TryGetCrossRigidSourceVmdDocument(
                                state,
                                hop.OwnerVmdPath,
                                sourceVmdDocuments,
                                out var hopOwnerDocument,
                                out reason) ||
                            hopOwnerDocument.SelectSingleNode(
                                $"{hopParentXmlPath}/SLOT[{hopSlotIndex}]") is
                                not XmlElement hopSlotElement)
                        {
                            if (string.IsNullOrWhiteSpace(reason))
                            {
                                reason =
                                    "fixed reference carrier could not be resolved";
                            }

                            return false;
                        }

                        var hopProbability =
                            ParseVmdSlotProbability(
                                hopSlotElement.GetAttribute(
                                    "probability"));
                        var hopMeshCount =
                            hopSlotElement.SelectNodes(
                                "VARIANT_MESH")?.Count ?? 0;
                        var hopReferenceCount =
                            hopSlotElement.SelectNodes(
                                "VARIANT_MESH_REFERENCE")?.Count ?? 0;
                        if (hopProbability <
                                1.0 -
                                AtlasValueGateExpectedDrawEpsilon ||
                            hopMeshCount != 0 ||
                            hopReferenceCount != 1 ||
                            hopReferenceIndex != 1)
                        {
                            reason =
                                "common-ancestor descendant selection crosses a non-fixed reference carrier";
                            return false;
                        }
                    }
                }

                anchorParentXmlPath ??=
                    currentAnchorParentXmlPath;
                if (!currentAnchorParentXmlPath.Equals(
                        anchorParentXmlPath,
                        StringComparison.Ordinal))
                {
                    reason =
                        "source selections do not share one common-ancestor VARIANT_MESH parent";
                    return false;
                }

                if (anchorDocument.SelectSingleNode(
                        $"{anchorParentXmlPath}/SLOT[{carrierSlotIndex}]") is
                    not XmlElement carrierSlotElement)
                {
                    reason =
                        "common-ancestor carrier slot is missing";
                    return false;
                }

                // The direct optional slot is itself the Cartesian
                // dimension: its absent/present alternatives already have
                // exact integer weights. Optional ancestors of deeper
                // dimensions still require conditional enumeration.
                var directOptionalCarrier =
                    tokenSelection.OptionalSlot &&
                    tokenSelection.SlotIndex == carrierSlotIndex &&
                    Normalize(tokenSelection.OwnerVmdPath).Equals(
                        anchorVmdPath,
                        StringComparison.OrdinalIgnoreCase) &&
                    tokenSelection.ParentXmlPath.Equals(
                        anchorParentXmlPath,
                        StringComparison.Ordinal) &&
                    IsSupportedCrossRigidOptionalJointSlot(
                        carrierSlotElement);
                if (ParseVmdSlotProbability(
                        carrierSlotElement.GetAttribute(
                            "probability")) <
                        1.0 -
                        AtlasValueGateExpectedDrawEpsilon &&
                    !directOptionalCarrier)
                {
                    reason =
                        "common-ancestor optional carrier requires a direct Cartesian dimension";
                    return false;
                }

                if (!TryGetCrossRigidSourceVmdDocument(
                        state,
                        tokenSelection.OwnerVmdPath,
                        sourceVmdDocuments,
                        out var dimensionOwnerDocument,
                        out reason) ||
                    dimensionOwnerDocument.SelectSingleNode(
                        $"{tokenSelection.ParentXmlPath}/SLOT[{tokenSelection.SlotIndex}]") is
                    not XmlElement dimensionSlotElement)
                {
                    if (string.IsNullOrWhiteSpace(reason))
                    {
                        reason =
                            "terminal selection slot could not be resolved";
                    }

                    return false;
                }

                var dimensionAlternatives =
                    GetCrossRigidJointAlternatives(
                            dimensionSlotElement,
                            tokenSelection.SlotIndex)
                        .Select(alternative =>
                            new CrossRigidJointDimensionAlternative(
                                BuildCrossRigidJointSelectionDimensionKey(
                                    tokenSelection.OwnerVmdPath,
                                    tokenSelection.ParentXmlPath,
                                    tokenSelection.SlotIndex),
                                alternative.IsReference,
                                alternative.AlternativeIndex,
                                alternative.Multiplicity))
                        .ToArray();
                if (dimensionAlternatives.Length <= 1)
                {
                    reason =
                        "terminal common-ancestor selection is not an alternative dimension";
                    return false;
                }

                var dimensionKey =
                    BuildCrossRigidJointSelectionDimensionKey(
                        tokenSelection.OwnerVmdPath,
                        tokenSelection.ParentXmlPath,
                        tokenSelection.SlotIndex);
                var dimension =
                    new CrossRigidJointSelectionDimension(
                        dimensionKey,
                        tokenSelection.OwnerVmdPath,
                        tokenSelection.ParentXmlPath,
                        tokenSelection.SlotIndex,
                        carrierSlotIndex,
                        null,
                        relativeReferenceChain,
                        dimensionAlternatives);

                if (dimensionsByKey.TryGetValue(
                        dimensionKey,
                        out var existingDimension))
                {
                    if (existingDimension.CarrierSlotIndex !=
                            carrierSlotIndex ||
                        !BuildCrossRigidReferenceChainSignature(
                                existingDimension
                                    .ReferenceChainFromAnchor)
                            .Equals(
                                BuildCrossRigidReferenceChainSignature(
                                    relativeReferenceChain),
                                StringComparison.Ordinal))
                    {
                        reason =
                            "one selection dimension resolves through incompatible common-ancestor carriers";
                        return false;
                    }
                }
                else
                {
                    dimensionsByKey[dimensionKey] =
                        dimension;
                }

                var conditionalParentSelection = tokenSelection;
                foreach (var childSelection in conditionalChildSelections)
                {
                    var childKey =
                        BuildCrossRigidJointSelectionDimensionKey(
                            childSelection.OwnerVmdPath,
                            childSelection.ParentXmlPath,
                            childSelection.SlotIndex);
                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            childSelection.OwnerVmdPath,
                            sourceVmdDocuments,
                            out var childDocument,
                            out reason) ||
                        childDocument.SelectSingleNode(
                            $"{childSelection.ParentXmlPath}/SLOT[{childSelection.SlotIndex}]") is
                            not XmlElement childSlot)
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                            reason = "Conditional nested child slot is missing";
                        return false;
                    }

                    if (!TryGetCrossRigidReferenceChainPrefixToVmd(
                            instance,
                            childSelection.OwnerVmdPath,
                            out var childOwnerReferenceChain) ||
                        childOwnerReferenceChain.Length <
                            commonReferenceChain.Length)
                    {
                        reason = "Conditional child reference provenance is missing";
                        return false;
                    }

                    var childRelativeReferenceChain =
                        childOwnerReferenceChain
                            .Skip(commonReferenceChain.Length)
                            .ToArray();
                    string? childRelativeSlotPath = null;
                    if (childRelativeReferenceChain.Length == 0)
                    {
                        if (!TryGetCrossRigidRelativeXmlPath(
                                $"{anchorParentXmlPath}/SLOT[{carrierSlotIndex}]",
                                $"{childSelection.ParentXmlPath}/SLOT[{childSelection.SlotIndex}]",
                                out var relativeSlotPath))
                        {
                            reason = "Conditional nested child is outside carrier";
                            return false;
                        }

                        childRelativeSlotPath = relativeSlotPath;
                    }

                    var childAlternatives =
                        GetCrossRigidJointAlternatives(
                                childSlot,
                                childSelection.SlotIndex)
                            .Select(alternative =>
                                new CrossRigidJointDimensionAlternative(
                                    childKey,
                                    alternative.IsReference,
                                    alternative.AlternativeIndex,
                                    alternative.Multiplicity))
                            .ToArray();
                    // A deterministic intermediate ancestor has exactly one
                    // alternative. It still needs a conditional dimension so
                    // that deeper children do not escape their selected branch.
                    if (childAlternatives.Length == 0)
                    {
                        reason = "Conditional nested child has no alternatives";
                        return false;
                    }

                    var parentKey =
                        BuildCrossRigidJointSelectionDimensionKey(
                            conditionalParentSelection.OwnerVmdPath,
                            conditionalParentSelection.ParentXmlPath,
                            conditionalParentSelection.SlotIndex);
                    var childDimension =
                        new CrossRigidJointSelectionDimension(
                            childKey,
                            childSelection.OwnerVmdPath,
                            childSelection.ParentXmlPath,
                            childSelection.SlotIndex,
                            carrierSlotIndex,
                            childRelativeSlotPath,
                            childRelativeReferenceChain,
                            childAlternatives,
                            parentKey,
                            conditionalParentSelection.IsReference,
                            conditionalParentSelection.AlternativeIndex);
                    if (dimensionsByKey.TryGetValue(
                            childKey,
                            out var existingChild))
                    {
                        if (!AreEquivalentCrossRigidJointDimensions(
                                existingChild,
                                childDimension))
                        {
                            reason = "Conditional nested child has incompatible provenance";
                            return false;
                        }
                    }
                    else
                    {
                        dimensionsByKey[childKey] = childDimension;
                    }

                    conditionalParentSelection = childSelection;
                }

                sourceSelections.Add(sourceSelection);
            }

            if (string.IsNullOrWhiteSpace(
                    anchorParentXmlPath) ||
                dimensionsByKey.Count == 0)
            {
                reason =
                    "common-ancestor writer could not identify a probability-1 dependency-root dimension";
                return false;
            }

            foreach (var fixedSourceInstance in
                     fixedSourceInstances)
            {
                if (!TryBuildCrossRigidFixedCommonAncestorSourceSelection(
                        fixedSourceInstance,
                        anchorVmdPath,
                        anchorParentXmlPath,
                        commonReferenceChain,
                        anchorDocument,
                        out var fixedSourceSelection,
                        out var fixedCarrierSlotIndex,
                        out reason))
                {
                    return false;
                }

                sourceSelections.Add(fixedSourceSelection);
                fixedCarrierSlotIndices.Add(
                    fixedCarrierSlotIndex);
            }

            foreach (var dimensionGroup in sourceSelections
                         .GroupBy(
                             BuildCrossRigidJointSourceSelectionDimensionKey,
                             StringComparer.Ordinal))
            {
                if (dimensionGroup
                        .Select(selection =>
                            $"{(selection.IsReference ? "r" : "m")}:" +
                            selection.AlternativeIndex)
                        .Distinct(StringComparer.Ordinal)
                        .Count() != 1)
                {
                    reason =
                        "co-render state selects incompatible alternatives from one common-ancestor dimension";
                    return false;
                }
            }

            // Optional dimensions may only be materialized independently
            // when their absent branch cannot remove another Cartesian
            // dimension's containing subtree. The source-level
            // differing-token check does not detect dependence between
            // dimensions contributed by *different* source instances.
            // Such nested optional domains require conditional rather
            // than independent Cartesian enumeration.
            foreach (var optionalDimension in
                     dimensionsByKey.Values.Where(dimension =>
                         dimension.Alternatives.Any(alternative =>
                             alternative.AlternativeIndex == 0)))
            {
                var optionalSlotXmlPath =
                    $"{optionalDimension.ParentXmlPath}/" +
                    $"SLOT[{optionalDimension.SlotIndex}]";
                foreach (var otherDimension in
                         dimensionsByKey.Values.Where(dimension =>
                             !dimension.DimensionKey.Equals(
                                 optionalDimension.DimensionKey,
                                 StringComparison.Ordinal)))
                {
                    var sameDocumentDescendant =
                        Normalize(otherDimension.OwnerVmdPath)
                            .Equals(
                                Normalize(optionalDimension.OwnerVmdPath),
                                StringComparison.OrdinalIgnoreCase) &&
                        otherDimension.ParentXmlPath.StartsWith(
                            optionalSlotXmlPath + "/",
                            StringComparison.Ordinal);
                    var descendantReference =
                        otherDimension.ReferenceChainFromAnchor.Any(hop =>
                            Normalize(hop.OwnerVmdPath).Equals(
                                Normalize(optionalDimension.OwnerVmdPath),
                                StringComparison.OrdinalIgnoreCase) &&
                            hop.ReferenceXmlPath.StartsWith(
                                optionalSlotXmlPath + "/",
                                StringComparison.Ordinal));
                    if (!sameDocumentDescendant &&
                        !descendantReference)
                    {
                        continue;
                    }

                    // Nested conditional descendants remain safe even when
                    // the optional ancestor is more than one level above the
                    // dependent dimension.
                    var ancestorKey = otherDimension.ParentDimensionKey;
                    var visitedAncestorKeys =
                        new HashSet<string>(StringComparer.Ordinal);
                    var coveredByConditionalParent = false;
                    while (ancestorKey != null &&
                           visitedAncestorKeys.Add(ancestorKey))
                    {
                        if (ancestorKey.Equals(
                                optionalDimension.DimensionKey,
                                StringComparison.Ordinal))
                        {
                            coveredByConditionalParent = true;
                            break;
                        }

                        ancestorKey =
                            dimensionsByKey.TryGetValue(
                                ancestorKey,
                                out var ancestorDimension)
                                ? ancestorDimension.ParentDimensionKey
                                : null;
                    }

                    if (coveredByConditionalParent)
                        continue;

                    reason =
                        "common-ancestor optional slot contains another " +
                        "Cartesian dependency dimension; conditional " +
                        $"rewriting is required ({optionalDimension.DimensionKey} " +
                        $"> {otherDimension.DimensionKey})";
                    return false;
                }
            }

            long combinationCount = 1;
            foreach (var dimension in dimensionsByKey.Values)
            {
                combinationCount *=
                    dimension.Alternatives.Sum(alternative =>
                        alternative.Multiplicity);
                if (combinationCount >
                    MaxCrossRigidJointStateCombinations)
                {
                    reason =
                        $"common-ancestor Cartesian product exceeds " +
                        $"{MaxCrossRigidJointStateCombinations:N0} combinations";
                    return false;
                }
            }

            descriptor =
                new CrossRigidJointAlwaysPresentRewriteDescriptor(
                    anchorVmdPath,
                    anchorParentXmlPath,
                    commonReferenceChain,
                    sourceSelections
                        .OrderBy(
                            BuildCrossRigidJointSourceSelectionDimensionKey,
                            StringComparer.Ordinal)
                        .ThenBy(selection =>
                            BuildCrossRigidOccurrenceProvenanceSignature(
                                [selection.Instance]),
                            StringComparer.Ordinal)
                        .ToArray(),
                    dimensionsByKey.Values
                        .Select(dimension =>
                            dimension.CarrierSlotIndex)
                        .Concat(fixedCarrierSlotIndices)
                        .Distinct()
                        .OrderBy(index => index)
                        .ToArray(),
                    (int)combinationCount,
                    dimensionsByKey.Values
                        .OrderBy(
                            dimension =>
                                dimension.DimensionKey,
                            StringComparer.Ordinal)
                        .ToArray());
            return true;
        }

        private static bool
            TryDescribeCrossRigidFixedLocalCommonAncestorRewrite(
                BatchState state,
                CrossRigidRewriteOccurrenceSet occurrenceSet,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
                out string reason)
        {
            descriptor = null!;
            reason = string.Empty;
            var instances =
                occurrenceSet.SourceInstances;
            if (instances.Length < 2)
            {
                reason =
                    "fixed-local common-ancestor joint has fewer than two source occurrences";
                return false;
            }

            var anchorVmdPaths =
                instances
                    .Select(instance =>
                        Normalize(instance.DefiningVmdPath))
                    .Distinct(
                        StringComparer.OrdinalIgnoreCase)
                    .ToArray();
            if (anchorVmdPaths.Length != 1)
            {
                reason =
                    "fixed-local common-ancestor sources belong to different defining VMDs";
                return false;
            }

            var anchorVmdPath =
                anchorVmdPaths[0];
            // All source models must reach the same defining VMD via the
            // same *complete* reference chain. Merely sharing a prefix
            // would allow a rewrite to leak into distinct child branches.
            // The joint writer already clones this anchor chain copy-on-write.
            var commonReferenceChain =
                GetCrossRigidCommonReferenceChainPrefix(instances);
            if (instances.Any(instance =>
                    instance.ReferenceChain.Length !=
                    commonReferenceChain.Length) ||
                (commonReferenceChain.Length != 0 &&
                 !Normalize(
                         commonReferenceChain[^1].ReferencedVmdPath)
                     .Equals(
                         anchorVmdPath,
                         StringComparison.OrdinalIgnoreCase)))
            {
                reason =
                    "fixed-local common-ancestor sources do not share a complete child-VMD reference chain";
                return false;
            }
            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    anchorVmdPath,
                    sourceVmdDocuments,
                    out var anchorDocument,
                    out reason))
            {
                return false;
            }

            var tokenSets =
                instances
                    .Select(instance =>
                        instance.ActivationSignature.Equals(
                            "<always>",
                            StringComparison.Ordinal)
                            ? new HashSet<string>(
                                StringComparer.Ordinal)
                            : instance.ActivationSignature
                                .Split(
                                    '\u001f',
                                    StringSplitOptions.RemoveEmptyEntries)
                                .ToHashSet(
                                    StringComparer.Ordinal))
                    .ToArray();
            var commonTokens =
                new HashSet<string>(
                    tokenSets[0],
                    StringComparer.Ordinal);
            foreach (var tokenSet in
                     tokenSets.Skip(1))
            {
                commonTokens.IntersectWith(
                    tokenSet);
            }

            var fixedSourceInstances =
                new List<CrossRigidVisualInstance>();
            var pendingDimensions =
                new List<(
                    CrossRigidActivationTokenSelection TokenSelection,
                    CrossRigidJointSourceSelection SourceSelection)>();
            var anchorParentCandidates =
                new List<string>();

            foreach (var instance in instances)
            {
                var orderedDifferingTokens =
                    instance.ActivationSignature.Equals(
                        "<always>",
                        StringComparison.Ordinal)
                        ? Array.Empty<string>()
                        : instance.ActivationSignature
                            .Split(
                                '\u001f',
                                StringSplitOptions.RemoveEmptyEntries)
                            .Where(token =>
                                !commonTokens.Contains(token))
                            .ToArray();

                if (orderedDifferingTokens.Length == 0)
                {
                    if (!TryValidateCrossRigidFixedCommonAncestorSourceInstance(
                            state,
                            instance,
                            sourceVmdDocuments,
                            out reason) ||
                        !TryGetCrossRigidSelectionParentXmlPath(
                            instance.ModelXmlPath,
                            out var fixedParentXmlPath))
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                        {
                            reason =
                                "fixed-local source parent could not be identified";
                        }

                        return false;
                    }

                    fixedSourceInstances.Add(
                        instance);
                    anchorParentCandidates.Add(
                        fixedParentXmlPath);
                    continue;
                }

                var dependencySelections =
                    new List<CrossRigidActivationTokenSelection>();
                foreach (var differingToken in
                         orderedDifferingTokens)
                {
                    if (!TryParseCrossRigidActivationToken(
                            state,
                            differingToken,
                            sourceVmdDocuments,
                            out var dependencySelection,
                            out reason))
                    {
                        return false;
                    }

                    if (dependencySelection.OptionalSlot)
                    {
                        if (orderedDifferingTokens.Length != 1)
                        {
                            reason =
                                "fixed-local optional dependency has nested varying selections";
                            return false;
                        }

                        if (!TryValidateCrossRigidOptionalJointSelection(
                                state,
                                dependencySelection,
                                sourceVmdDocuments,
                                out reason))
                        {
                            return false;
                        }
                    }

                    if (!Normalize(
                            dependencySelection.OwnerVmdPath)
                        .Equals(
                            anchorVmdPath,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "fixed-local dependency selection belongs to another VMD";
                        return false;
                    }

                    dependencySelections.Add(
                        dependencySelection);
                }

                var tokenSelection =
                    dependencySelections[0];
                if (!TryBuildCrossRigidJointSourceSelection(
                        instance,
                        tokenSelection,
                        commonReferenceChain,
                        out var sourceSelection,
                        out reason))
                {
                    return false;
                }

                anchorParentCandidates.Add(
                    tokenSelection.ParentXmlPath);
                pendingDimensions.Add(
                    (
                        tokenSelection,
                        sourceSelection));
            }

            if (pendingDimensions.Count == 0 ||
                !TryGetDeepestCommonCrossRigidVariantMeshParentPath(
                    anchorParentCandidates,
                    out var anchorParentXmlPath) ||
                anchorDocument.SelectSingleNode(
                    anchorParentXmlPath) is
                not XmlElement)
            {
                reason =
                    "fixed-local common structural parent could not be identified";
                return false;
            }

            var sourceSelections =
                new List<CrossRigidJointSourceSelection>();
            var fixedCarrierSlotIndices =
                new HashSet<int>();
            var dimensionsByKey =
                new Dictionary<
                    string,
                    CrossRigidJointSelectionDimension>(
                    StringComparer.Ordinal);

            foreach (var pending in
                     pendingDimensions)
            {
                var tokenSelection =
                    pending.TokenSelection;
                int carrierSlotIndex;
                string? localDimensionSlotRelativeXmlPath =
                    null;

                if (tokenSelection.ParentXmlPath.Equals(
                        anchorParentXmlPath,
                        StringComparison.Ordinal))
                {
                    carrierSlotIndex =
                        tokenSelection.SlotIndex;
                }
                else
                {
                    if (!TryParseCrossRigidImmediateSelectionLocation(
                            anchorParentXmlPath,
                            tokenSelection.ParentXmlPath,
                            out carrierSlotIndex,
                            out _,
                            out _) ||
                        !TryValidateCrossRigidFixedLocalCarrierPath(
                            anchorDocument,
                            anchorParentXmlPath,
                            tokenSelection.ParentXmlPath,
                            out reason))
                    {
                        if (string.IsNullOrWhiteSpace(reason))
                        {
                            reason =
                                "fixed local wrapper could not be lifted to the common parent";
                        }

                        return false;
                    }

                    var carrierSlotXmlPath =
                        $"{anchorParentXmlPath}/" +
                        $"SLOT[{carrierSlotIndex}]";
                    var dimensionSlotXmlPath =
                        $"{tokenSelection.ParentXmlPath}/" +
                        $"SLOT[{tokenSelection.SlotIndex}]";
                    if (!TryGetCrossRigidRelativeXmlPath(
                            carrierSlotXmlPath,
                            dimensionSlotXmlPath,
                            out localDimensionSlotRelativeXmlPath))
                    {
                        reason =
                            "nested local dimension is outside its fixed carrier slot";
                        return false;
                    }
                }

                if (anchorDocument.SelectSingleNode(
                        $"{anchorParentXmlPath}/SLOT[{carrierSlotIndex}]") is
                    not XmlElement carrierSlotElement)
                {
                    reason =
                        "fixed-local common-ancestor carrier slot is missing";
                    return false;
                }

                // Never lift through an optional wrapper unless that
                // wrapper is exactly the enumerated absent/present slot.
                var directOptionalCarrier =
                    tokenSelection.OptionalSlot &&
                    tokenSelection.SlotIndex == carrierSlotIndex &&
                    tokenSelection.ParentXmlPath.Equals(
                        anchorParentXmlPath,
                        StringComparison.Ordinal) &&
                    IsSupportedCrossRigidOptionalJointSlot(
                        carrierSlotElement);
                if (ParseVmdSlotProbability(
                        carrierSlotElement.GetAttribute(
                            "probability")) <
                        1.0 -
                        AtlasValueGateExpectedDrawEpsilon &&
                    !directOptionalCarrier)
                {
                    reason =
                        "fixed-local optional carrier requires a direct Cartesian dimension";
                    return false;
                }

                if (anchorDocument.SelectSingleNode(
                        $"{tokenSelection.ParentXmlPath}/SLOT[{tokenSelection.SlotIndex}]") is
                    not XmlElement dimensionSlotElement)
                {
                    reason =
                        "fixed-local terminal dimension slot could not be resolved";
                    return false;
                }

                var dimensionKey =
                    BuildCrossRigidJointSelectionDimensionKey(
                        tokenSelection.OwnerVmdPath,
                        tokenSelection.ParentXmlPath,
                        tokenSelection.SlotIndex);
                var alternatives =
                    GetCrossRigidJointAlternatives(
                            dimensionSlotElement,
                            tokenSelection.SlotIndex)
                        .Select(alternative =>
                            new CrossRigidJointDimensionAlternative(
                                dimensionKey,
                                alternative.IsReference,
                                alternative.AlternativeIndex,
                                alternative.Multiplicity))
                        .ToArray();
                if (alternatives.Length <= 1)
                {
                    reason =
                        "fixed-local terminal selection is not an alternative dimension";
                    return false;
                }

                var dimension =
                    new CrossRigidJointSelectionDimension(
                        dimensionKey,
                        tokenSelection.OwnerVmdPath,
                        tokenSelection.ParentXmlPath,
                        tokenSelection.SlotIndex,
                        carrierSlotIndex,
                        localDimensionSlotRelativeXmlPath,
                        Array.Empty<
                            CrossRigidVmdReferenceHop>(),
                        alternatives);

                if (dimensionsByKey.TryGetValue(
                        dimensionKey,
                        out var existingDimension))
                {
                    if (existingDimension.CarrierSlotIndex !=
                            carrierSlotIndex ||
                        !string.Equals(
                            existingDimension
                                .LocalDimensionSlotRelativeXmlPath,
                            localDimensionSlotRelativeXmlPath,
                            StringComparison.Ordinal))
                    {
                        reason =
                            "one fixed-local dimension resolves through incompatible carriers";
                        return false;
                    }
                }
                else
                {
                    dimensionsByKey[
                        dimensionKey] =
                        dimension;
                }

                sourceSelections.Add(
                    pending.SourceSelection);
            }

            foreach (var fixedSourceInstance in
                     fixedSourceInstances)
            {
                if (!TryBuildCrossRigidFixedCommonAncestorSourceSelection(
                        fixedSourceInstance,
                        anchorVmdPath,
                        anchorParentXmlPath,
                        commonReferenceChain,
                        anchorDocument,
                        out var fixedSourceSelection,
                        out var fixedCarrierSlotIndex,
                        out reason))
                {
                    return false;
                }

                sourceSelections.Add(
                    fixedSourceSelection);
                fixedCarrierSlotIndices.Add(
                    fixedCarrierSlotIndex);
            }

            foreach (var dimensionGroup in
                     sourceSelections.GroupBy(
                         BuildCrossRigidJointSourceSelectionDimensionKey,
                         StringComparer.Ordinal))
            {
                if (dimensionGroup
                        .Select(selection =>
                            $"{(selection.IsReference ? "r" : "m")}:" +
                            selection.AlternativeIndex)
                        .Distinct(
                            StringComparer.Ordinal)
                        .Count() != 1)
                {
                    reason =
                        "co-render state selects incompatible alternatives from one fixed-local dimension";
                    return false;
                }
            }

            // Optional direct dimensions are independent only when no
            // other dimension lives inside their selected subtree.
            // Otherwise absent/present states must be enumerated
            // conditionally rather than as a plain Cartesian product.
            foreach (var optionalDimension in dimensionsByKey.Values
                         .Where(dimension => dimension.Alternatives.Any(
                             alternative => alternative.AlternativeIndex == 0)))
            {
                var optionalSlotPath =
                    $"{optionalDimension.ParentXmlPath}/SLOT[{optionalDimension.SlotIndex}]";
                foreach (var otherDimension in dimensionsByKey.Values)
                {
                    if (otherDimension.DimensionKey.Equals(
                            optionalDimension.DimensionKey,
                            StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (Normalize(otherDimension.OwnerVmdPath).Equals(
                            Normalize(optionalDimension.OwnerVmdPath),
                            StringComparison.OrdinalIgnoreCase) &&
                        otherDimension.ParentXmlPath.StartsWith(
                            optionalSlotPath + "/",
                            StringComparison.Ordinal))
                    {
                        reason =
                            "fixed-local optional Cartesian dimension contains a nested varying dimension";
                        return false;
                    }
                }
            }

            long combinationCount = 1;
            foreach (var dimension in
                     dimensionsByKey.Values)
            {
                combinationCount *=
                    dimension.Alternatives.Sum(alternative =>
                        alternative.Multiplicity);
                if (combinationCount >
                    MaxCrossRigidJointStateCombinations)
                {
                    reason =
                        $"fixed-local Cartesian product exceeds " +
                        $"{MaxCrossRigidJointStateCombinations:N0} combinations";
                    return false;
                }
            }

            descriptor =
                new CrossRigidJointAlwaysPresentRewriteDescriptor(
                    anchorVmdPath,
                    anchorParentXmlPath,
                    commonReferenceChain,
                    sourceSelections
                        .OrderBy(
                            BuildCrossRigidJointSourceSelectionDimensionKey,
                            StringComparer.Ordinal)
                        .ThenBy(selection =>
                            BuildCrossRigidOccurrenceProvenanceSignature(
                                [selection.Instance]),
                            StringComparer.Ordinal)
                        .ToArray(),
                    dimensionsByKey.Values
                        .Select(dimension =>
                            dimension.CarrierSlotIndex)
                        .Concat(
                            fixedCarrierSlotIndices)
                        .Distinct()
                        .OrderBy(index => index)
                        .ToArray(),
                    (int)combinationCount,
                    dimensionsByKey.Values
                        .OrderBy(
                            dimension =>
                                dimension.DimensionKey,
                            StringComparer.Ordinal)
                        .ToArray());
            return true;
        }

        private static bool
            TryGetCrossRigidSelectionParentXmlPath(
                string selectionXmlPath,
                out string parentXmlPath)
        {
            parentXmlPath =
                string.Empty;
            const string slotMarker =
                "/SLOT[";
            var slotMarkerIndex =
                selectionXmlPath.LastIndexOf(
                    slotMarker,
                    StringComparison.Ordinal);
            if (slotMarkerIndex <= 0)
                return false;

            parentXmlPath =
                selectionXmlPath[
                    ..slotMarkerIndex];
            return parentXmlPath.Length != 0;
        }

        private static bool
            TryGetDeepestCommonCrossRigidVariantMeshParentPath(
                IReadOnlyList<string> parentXmlPaths,
                out string commonParentXmlPath)
        {
            commonParentXmlPath =
                string.Empty;
            if (parentXmlPaths.Count == 0)
                return false;

            var splitPaths =
                parentXmlPaths
                    .Select(path =>
                        path.Split(
                            '/',
                            StringSplitOptions
                                .RemoveEmptyEntries))
                    .ToArray();
            var commonLength =
                splitPaths.Min(parts =>
                    parts.Length);

            for (var partIndex = 0;
                 partIndex < commonLength;
                 partIndex++)
            {
                var candidate =
                    splitPaths[0][partIndex];
                if (splitPaths
                    .Skip(1)
                    .Any(parts =>
                        !parts[partIndex].Equals(
                            candidate,
                            StringComparison.Ordinal)))
                {
                    commonLength =
                        partIndex;
                    break;
                }
            }

            while (commonLength > 0 &&
                   splitPaths[0][commonLength - 1]
                       .StartsWith(
                           "SLOT[",
                           StringComparison.Ordinal))
            {
                commonLength--;
            }

            if (commonLength == 0)
                return false;

            var terminalPart =
                splitPaths[0][commonLength - 1];
            // Traversal records the document root as /VARIANT_MESH,
            // while nested model alternatives use VARIANT_MESH[n].
            // Both forms are valid structural parents for a joint that
            // spans sibling top-level slots.
            if (!terminalPart.Equals(
                    "<root>",
                    StringComparison.Ordinal) &&
                !terminalPart.Equals(
                    "VARIANT_MESH",
                    StringComparison.Ordinal) &&
                !terminalPart.StartsWith(
                    "VARIANT_MESH[",
                    StringComparison.Ordinal))
            {
                return false;
            }

            commonParentXmlPath =
                (parentXmlPaths[0].StartsWith(
                    "/",
                    StringComparison.Ordinal)
                    ? "/"
                    : string.Empty) +
                string.Join(
                    "/",
                    splitPaths[0]
                        .Take(commonLength));
            return commonParentXmlPath.Length !=
                   0;
        }

        private static bool
            TryValidateCrossRigidFixedLocalCarrierPath(
                XmlDocument document,
                string ancestorParentXmlPath,
                string descendantXmlPath,
                out string reason)
        {
            reason =
                string.Empty;
            if (document.SelectSingleNode(
                    ancestorParentXmlPath) is
                not XmlElement ancestorElement ||
                document.SelectSingleNode(
                    descendantXmlPath) is
                not XmlElement descendantElement)
            {
                reason =
                    "fixed local carrier path could not be resolved";
                return false;
            }

            XmlElement? current =
                descendantElement;
            while (current != null &&
                   !ReferenceEquals(
                       current,
                       ancestorElement))
            {
                if (current.ParentNode is
                    XmlElement slotElement &&
                    slotElement.Name.Equals(
                        "SLOT",
                        StringComparison.Ordinal))
                {
                    var probability =
                        ParseVmdSlotProbability(
                            slotElement.GetAttribute(
                                "probability"));
                    if (probability <
                        1.0 -
                        AtlasValueGateExpectedDrawEpsilon)
                    {
                        reason =
                            "common-ancestor descendant selection crosses an optional local carrier";
                        return false;
                    }

                    // The local carrier itself does not have to be a
                    // single-alternative slot. It is cloned intact into
                    // every outer Cartesian wrapper, so its own
                    // probability-1 alternative distribution is preserved.
                    // Only the nested dependency dimension is reduced in
                    // the branch where it exists. Sibling carrier
                    // alternatives therefore retain exactly their original
                    // aggregate probability across the wrappers.

                    current =
                        slotElement.ParentNode as
                            XmlElement;
                    continue;
                }

                current =
                    current.ParentNode as
                        XmlElement;
            }

            if (!ReferenceEquals(
                    current,
                    ancestorElement))
            {
                reason =
                    "fixed local carrier path does not descend from the common structural parent";
                return false;
            }

            return true;
        }

        private static bool
            TryValidateCrossRigidFixedCommonAncestorSourceInstance(
                BatchState state,
                CrossRigidVisualInstance instance,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out string reason)
        {
            reason = string.Empty;
            if (instance.ActivationSignature.Equals(
                    "<always>",
                    StringComparison.Ordinal))
            {
                return true;
            }

            foreach (var token in
                     instance.ActivationSignature.Split(
                         '\u001f',
                         StringSplitOptions.RemoveEmptyEntries))
            {
                if (!TryParseCrossRigidActivationToken(
                        state,
                        token,
                        sourceVmdDocuments,
                        out var selection,
                        out reason))
                {
                    return false;
                }

                if (selection.OptionalSlot)
                {
                    reason =
                        "common-ancestor fixed source crosses an optional slot";
                    return false;
                }
            }

            return true;
        }

        private static bool
            TryBuildCrossRigidFixedCommonAncestorSourceSelection(
                CrossRigidVisualInstance instance,
                string anchorVmdPath,
                string anchorParentXmlPath,
                IReadOnlyList<CrossRigidVmdReferenceHop>
                    commonReferenceChain,
                XmlDocument anchorDocument,
                out CrossRigidJointSourceSelection sourceSelection,
                out int carrierSlotIndex,
                out string reason)
        {
            sourceSelection = null!;
            carrierSlotIndex = 0;
            reason = string.Empty;

            string provenanceXmlPath;
            if (instance.ReferenceChain.Length >
                commonReferenceChain.Count)
            {
                var firstDescendantHop =
                    instance.ReferenceChain[
                        commonReferenceChain.Count];
                if (!Normalize(
                        firstDescendantHop.OwnerVmdPath)
                    .Equals(
                        Normalize(anchorVmdPath),
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "fixed source provenance does not descend from the common structural anchor";
                    return false;
                }

                provenanceXmlPath =
                    firstDescendantHop.ReferenceXmlPath;
            }
            else
            {
                if (!Normalize(instance.DefiningVmdPath)
                    .Equals(
                        Normalize(anchorVmdPath),
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "fixed source defining VMD does not match the common structural anchor";
                    return false;
                }

                provenanceXmlPath =
                    instance.ModelXmlPath;
            }

            if (!TryParseCrossRigidImmediateSelectionLocation(
                    anchorParentXmlPath,
                    provenanceXmlPath,
                    out carrierSlotIndex,
                    out var isReference,
                    out var alternativeIndex))
            {
                reason =
                    "fixed source carrier selection could not be identified under the common structural parent";
                return false;
            }

            if (anchorDocument.SelectSingleNode(
                    $"{anchorParentXmlPath}/SLOT[{carrierSlotIndex}]") is
                not XmlElement carrierSlotElement)
            {
                reason =
                    $"fixed source carrier slot {carrierSlotIndex} could not be resolved";
                return false;
            }

            var carrierProbability =
                ParseVmdSlotProbability(
                    carrierSlotElement.GetAttribute(
                        "probability"));
            if (carrierProbability <
                1.0 - AtlasValueGateExpectedDrawEpsilon)
            {
                reason =
                    $"fixed source carrier slot {carrierSlotIndex} is optional";
                return false;
            }

            var tokenSelection =
                new CrossRigidActivationTokenSelection(
                    Normalize(anchorVmdPath),
                    anchorParentXmlPath,
                    carrierSlotIndex,
                    isReference,
                    alternativeIndex,
                    OptionalSlot: false);
            return TryBuildCrossRigidJointSourceSelection(
                instance,
                tokenSelection,
                commonReferenceChain,
                out sourceSelection,
                out reason);
        }

        private static bool
            TryParseCrossRigidImmediateSelectionLocation(
                string parentXmlPath,
                string provenanceXmlPath,
                out int slotIndex,
                out bool isReference,
                out int alternativeIndex)
        {
            slotIndex = 0;
            isReference = false;
            alternativeIndex = 0;

            var prefix =
                $"{parentXmlPath}/SLOT[";
            if (!provenanceXmlPath.StartsWith(
                    prefix,
                    StringComparison.Ordinal))
            {
                return false;
            }

            var slotIndexStart =
                prefix.Length;
            var slotIndexEnd =
                provenanceXmlPath.IndexOf(
                    ']',
                    slotIndexStart);
            if (slotIndexEnd <= slotIndexStart ||
                !int.TryParse(
                    provenanceXmlPath[
                        slotIndexStart..
                        slotIndexEnd],
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out slotIndex) ||
                slotIndex <= 0 ||
                slotIndexEnd + 2 >
                    provenanceXmlPath.Length ||
                provenanceXmlPath[
                    slotIndexEnd + 1] != '/')
            {
                slotIndex = 0;
                return false;
            }

            var selectionStart =
                slotIndexEnd + 2;
            const string referencePrefix =
                "VARIANT_MESH_REFERENCE[";
            const string meshPrefix =
                "VARIANT_MESH[";
            string selectionPrefix;
            if (provenanceXmlPath.AsSpan(
                    selectionStart)
                .StartsWith(
                    referencePrefix.AsSpan(),
                    StringComparison.Ordinal))
            {
                isReference = true;
                selectionPrefix =
                    referencePrefix;
            }
            else if (provenanceXmlPath.AsSpan(
                         selectionStart)
                     .StartsWith(
                         meshPrefix.AsSpan(),
                         StringComparison.Ordinal))
            {
                selectionPrefix =
                    meshPrefix;
            }
            else
            {
                slotIndex = 0;
                return false;
            }

            var alternativeIndexStart =
                selectionStart +
                selectionPrefix.Length;
            var alternativeIndexEnd =
                provenanceXmlPath.IndexOf(
                    ']',
                    alternativeIndexStart);
            if (alternativeIndexEnd <=
                    alternativeIndexStart ||
                !int.TryParse(
                    provenanceXmlPath[
                        alternativeIndexStart..
                        alternativeIndexEnd],
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out alternativeIndex) ||
                alternativeIndex <= 0)
            {
                slotIndex = 0;
                alternativeIndex = 0;
                return false;
            }

            return true;
        }

        private static CrossRigidVmdReferenceHop[]
            GetCrossRigidCommonReferenceChainPrefix(
                IReadOnlyList<CrossRigidVisualInstance> instances)
        {
            if (instances.Count == 0)
                return [];

            var minimumLength =
                instances.Min(instance =>
                    instance.ReferenceChain.Length);
            var commonLength = 0;
            while (commonLength < minimumLength)
            {
                var candidate =
                    instances[0].ReferenceChain[commonLength];
                if (instances.Skip(1).Any(instance =>
                        !AreCrossRigidReferenceHopsEqual(
                            candidate,
                            instance.ReferenceChain[commonLength])))
                {
                    break;
                }

                commonLength++;
            }

            return instances[0]
                .ReferenceChain
                .Take(commonLength)
                .ToArray();
        }

        private static bool
            TryParseCrossRigidReferenceSlotLocation(
                string referenceXmlPath,
                out string parentXmlPath,
                out int slotIndex,
                out int referenceIndex)
        {
            parentXmlPath = string.Empty;
            slotIndex = 0;
            referenceIndex = 0;

            const string slotMarker = "/SLOT[";
            const string referenceMarker =
                "]/VARIANT_MESH_REFERENCE[";
            var slotMarkerIndex =
                referenceXmlPath.LastIndexOf(
                    slotMarker,
                    StringComparison.Ordinal);
            var referenceMarkerIndex =
                referenceXmlPath.LastIndexOf(
                    referenceMarker,
                    StringComparison.Ordinal);
            if (slotMarkerIndex <= 0 ||
                referenceMarkerIndex <=
                    slotMarkerIndex + slotMarker.Length)
            {
                return false;
            }

            var slotText = referenceXmlPath[
                (slotMarkerIndex + slotMarker.Length)..
                referenceMarkerIndex];
            var referenceIndexStart =
                referenceMarkerIndex +
                referenceMarker.Length;
            var referenceIndexEnd =
                referenceXmlPath.IndexOf(
                    ']',
                    referenceIndexStart);
            if (referenceIndexEnd <= referenceIndexStart ||
                !int.TryParse(
                    slotText,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out slotIndex) ||
                !int.TryParse(
                    referenceXmlPath[
                        referenceIndexStart..
                        referenceIndexEnd],
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out referenceIndex) ||
                slotIndex <= 0 ||
                referenceIndex <= 0)
            {
                slotIndex = 0;
                referenceIndex = 0;
                return false;
            }

            parentXmlPath =
                referenceXmlPath[..slotMarkerIndex];
            return !string.IsNullOrWhiteSpace(
                parentXmlPath);
        }

        private static string
            BuildCrossRigidJointSelectionDimensionKey(
                string ownerVmdPath,
                string parentXmlPath,
                int slotIndex)
            => string.Join(
                "\u001f",
                Normalize(ownerVmdPath),
                parentXmlPath,
                slotIndex.ToString(
                    CultureInfo.InvariantCulture));

        private static string
            BuildCrossRigidJointSourceSelectionDimensionKey(
                CrossRigidJointSourceSelection selection)
            => BuildCrossRigidJointSelectionDimensionKey(
                selection.SelectionOwnerVmdPath,
                selection.SelectionParentXmlPath,
                selection.SlotIndex);

        private static bool TryGetCrossRigidReferenceChainPrefixToVmd(
            CrossRigidVisualInstance instance,
            string targetVmdPathValue,
            out CrossRigidVmdReferenceHop[] prefix)
        {
            var targetVmdPath =
                Normalize(targetVmdPathValue);
            var referenceChain =
                instance.ReferenceChain;
            if (referenceChain.Length == 0)
            {
                prefix = [];
                return Normalize(instance.DefiningVmdPath).Equals(
                    targetVmdPath,
                    StringComparison.OrdinalIgnoreCase);
            }

            if (Normalize(referenceChain[0].OwnerVmdPath).Equals(
                    targetVmdPath,
                    StringComparison.OrdinalIgnoreCase))
            {
                prefix = [];
                return true;
            }

            for (var hopIndex = 0;
                 hopIndex < referenceChain.Length;
                 hopIndex++)
            {
                if (!Normalize(
                        referenceChain[hopIndex].ReferencedVmdPath)
                    .Equals(
                        targetVmdPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                prefix =
                    referenceChain
                        .Take(hopIndex + 1)
                        .ToArray();
                return true;
            }

            prefix = [];
            return false;
        }

        private static bool TryBuildCrossRigidJointSourceSelection(
            CrossRigidVisualInstance instance,
            CrossRigidActivationTokenSelection tokenSelection,
            IReadOnlyList<CrossRigidVmdReferenceHop>
                anchorReferenceChain,
            out CrossRigidJointSourceSelection sourceSelection,
            out string reason)
        {
            sourceSelection = null!;
            reason = string.Empty;
            var anchorReferenceHopIndex = -1;
            string? directModelRelativeXmlPath = null;
            string? directFirstReferenceRelativeXmlPath = null;
            var parentXmlPath =
                tokenSelection.ParentXmlPath;

            if (instance.ReferenceChain.Length <
                anchorReferenceChain.Count)
            {
                reason =
                    "source reference chain is shorter than the structural anchor chain";
                return false;
            }

            for (var hopIndex = 0;
                 hopIndex < anchorReferenceChain.Count;
                 hopIndex++)
            {
                if (!AreCrossRigidReferenceHopsEqual(
                        instance.ReferenceChain[hopIndex],
                        anchorReferenceChain[hopIndex]))
                {
                    reason =
                        "source reference chain no longer matches the structural anchor";
                    return false;
                }
            }

            if (tokenSelection.IsReference)
            {
                if (instance.ReferenceChain.Length <=
                    anchorReferenceChain.Count)
                {
                    reason =
                        "selected reference branch has no recorded child-VMD hop";
                    return false;
                }

                var expectedReferenceXmlPath =
                    $"{parentXmlPath}/SLOT[{tokenSelection.SlotIndex}]/" +
                    $"VARIANT_MESH_REFERENCE[{tokenSelection.AlternativeIndex}]";
                var anchorHop =
                    instance.ReferenceChain[
                        anchorReferenceChain.Count];
                if (!Normalize(anchorHop.OwnerVmdPath).Equals(
                        tokenSelection.OwnerVmdPath,
                        StringComparison.OrdinalIgnoreCase) ||
                    !anchorHop.ReferenceXmlPath.Equals(
                        expectedReferenceXmlPath,
                        StringComparison.Ordinal))
                {
                    reason =
                        "selected reference alternative does not contain the source provenance";
                    return false;
                }

                anchorReferenceHopIndex =
                    anchorReferenceChain.Count;
            }
            else
            {
                var expectedModelXmlPath =
                    $"{parentXmlPath}/SLOT[{tokenSelection.SlotIndex}]/" +
                    $"VARIANT_MESH[{tokenSelection.AlternativeIndex}]";

                if (instance.ReferenceChain.Length ==
                    anchorReferenceChain.Count)
                {
                    if (!Normalize(instance.DefiningVmdPath).Equals(
                            tokenSelection.OwnerVmdPath,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "direct structural selection does not own the source model";
                        return false;
                    }

                    if (!instance.ModelXmlPath.Equals(
                            expectedModelXmlPath,
                            StringComparison.Ordinal) &&
                        !TryGetCrossRigidRelativeXmlPath(
                            expectedModelXmlPath,
                            instance.ModelXmlPath,
                            out directModelRelativeXmlPath))
                    {
                        reason =
                            "source model is outside the selected structural subtree";
                        return false;
                    }
                }
                else
                {
                    anchorReferenceHopIndex =
                        anchorReferenceChain.Count;
                    var firstNestedHop =
                        instance.ReferenceChain[
                            anchorReferenceHopIndex];
                    if (!Normalize(firstNestedHop.OwnerVmdPath).Equals(
                            tokenSelection.OwnerVmdPath,
                            StringComparison.OrdinalIgnoreCase) ||
                        !TryGetCrossRigidRelativeXmlPath(
                            expectedModelXmlPath,
                            firstNestedHop.ReferenceXmlPath,
                            out directFirstReferenceRelativeXmlPath))
                    {
                        reason =
                            "source child-VMD provenance is outside the selected structural subtree";
                        return false;
                    }
                }
            }

            sourceSelection =
                new CrossRigidJointSourceSelection(
                    instance,
                    tokenSelection.OwnerVmdPath,
                    tokenSelection.ParentXmlPath,
                    tokenSelection.SlotIndex,
                    tokenSelection.IsReference,
                    tokenSelection.AlternativeIndex,
                    anchorReferenceHopIndex,
                    directModelRelativeXmlPath,
                    directFirstReferenceRelativeXmlPath);
            return true;
        }

        private static bool TryGetCrossRigidRelativeXmlPath(
            string ancestorXmlPath,
            string descendantXmlPath,
            out string relativeXmlPath)
        {
            relativeXmlPath = string.Empty;
            if (string.IsNullOrWhiteSpace(ancestorXmlPath) ||
                string.IsNullOrWhiteSpace(descendantXmlPath) ||
                descendantXmlPath.Length <= ancestorXmlPath.Length ||
                !descendantXmlPath.StartsWith(
                    ancestorXmlPath,
                    StringComparison.Ordinal) ||
                descendantXmlPath[ancestorXmlPath.Length] != '/')
            {
                return false;
            }

            relativeXmlPath =
                descendantXmlPath[(ancestorXmlPath.Length + 1)..];
            return relativeXmlPath.Length != 0;
        }

        private static bool AreCrossRigidReferenceHopsEqual(
            CrossRigidVmdReferenceHop left,
            CrossRigidVmdReferenceHop right)
            => Normalize(left.OwnerVmdPath).Equals(
                   Normalize(right.OwnerVmdPath),
                   StringComparison.OrdinalIgnoreCase) &&
               left.ReferenceXmlPath.Equals(
                   right.ReferenceXmlPath,
                   StringComparison.Ordinal) &&
               Normalize(left.ReferencedVmdPath).Equals(
                   Normalize(right.ReferencedVmdPath),
                   StringComparison.OrdinalIgnoreCase);

        private static string BuildCrossRigidReferenceChainSignature(
            IEnumerable<CrossRigidVmdReferenceHop> referenceChain)
            => string.Join(
                "\u001e",
                referenceChain.Select(hop => string.Join(
                    "|",
                    Normalize(hop.OwnerVmdPath),
                    hop.ReferenceXmlPath,
                    Normalize(hop.ReferencedVmdPath))));

        private static bool TryParseCrossRigidActivationToken(
            BatchState state,
            string token,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidActivationTokenSelection selection,
            out string reason)
        {
            selection = null!;
            reason = string.Empty;

            var ownerSeparator = token.IndexOf(
                ":",
                StringComparison.Ordinal);
            var slotMarker = token.LastIndexOf(
                "/slot=",
                StringComparison.Ordinal);
            var meshMarker = token.LastIndexOf(
                "/mesh=",
                StringComparison.Ordinal);
            var referenceMarker = token.LastIndexOf(
                "/ref=",
                StringComparison.Ordinal);
            var branchMarker = Math.Max(
                meshMarker,
                referenceMarker);
            if (ownerSeparator <= 0 ||
                slotMarker <= ownerSeparator ||
                branchMarker <= slotMarker)
            {
                reason =
                    $"activation token could not be parsed: {token}";
                return false;
            }

            var slotIndexStart =
                slotMarker + "/slot=".Length;
            var slotIndexText = token[
                slotIndexStart..branchMarker];
            if (!int.TryParse(
                    slotIndexText,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var slotIndex) ||
                slotIndex <= 0)
            {
                reason =
                    $"activation token has invalid slot index: {token}";
                return false;
            }

            var isReference = referenceMarker == branchMarker;
            var alternativeMarker =
                isReference ? "/ref=" : "/mesh=";
            var alternativeIndexText = token[
                (branchMarker + alternativeMarker.Length)..];
            if (!int.TryParse(
                    alternativeIndexText,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var alternativeIndex) ||
                alternativeIndex <= 0)
            {
                reason =
                    $"activation token has invalid alternative index: {token}";
                return false;
            }

            var ownerVmdPath = Normalize(
                token[..ownerSeparator]);
            var parentXmlPath = token[
                (ownerSeparator + 1)..slotMarker];
            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    ownerVmdPath,
                    sourceVmdDocuments,
                    out var ownerDocument,
                    out reason))
            {
                return false;
            }

            if (ownerDocument.SelectSingleNode(
                    $"{parentXmlPath}/SLOT[{slotIndex}]") is
                not XmlElement slotElement)
            {
                reason =
                    $"activation token slot no longer resolves in source VMD: {token}";
                return false;
            }

            var slotProbability =
                ParseVmdSlotProbability(
                    slotElement.GetAttribute("probability"));
            selection =
                new CrossRigidActivationTokenSelection(
                    ownerVmdPath,
                    parentXmlPath,
                    slotIndex,
                    isReference,
                    alternativeIndex,
                    slotProbability <
                        1.0 - AtlasValueGateExpectedDrawEpsilon);
            return true;
        }

        private static bool
            TryValidateCrossRigidDeterministicJointSuffix(
                BatchState state,
                IEnumerable<string> descendantTokens,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out string reason)
        {
            reason = string.Empty;
            foreach (var descendantToken in descendantTokens)
            {
                if (!TryParseCrossRigidActivationToken(
                        state,
                        descendantToken,
                        sourceVmdDocuments,
                        out var selection,
                        out reason) ||
                    !TryGetCrossRigidSourceVmdDocument(
                        state,
                        selection.OwnerVmdPath,
                        sourceVmdDocuments,
                        out var ownerDocument,
                        out reason))
                {
                    return false;
                }

                if (ownerDocument.SelectSingleNode(
                        $"{selection.ParentXmlPath}/SLOT[{selection.SlotIndex}]") is
                    not XmlElement slotElement)
                {
                    reason =
                        "nested optional dependency's descendant slot is missing";
                    return false;
                }

                var alternativeCount =
                    (slotElement.SelectNodes("VARIANT_MESH")?.Count ?? 0) +
                    (slotElement.SelectNodes("VARIANT_MESH_REFERENCE")?.Count ?? 0);
                if (selection.OptionalSlot || alternativeCount != 1)
                {
                    reason =
                        "common-ancestor optional dependency has nested varying selections";
                    return false;
                }
            }

            return true;
        }

        private static bool
            TryValidateCrossRigidOptionalJointSelection(
                BatchState state,
                CrossRigidActivationTokenSelection selection,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out string reason)
        {
            reason = string.Empty;
            if (!selection.OptionalSlot)
                return true;

            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    selection.OwnerVmdPath,
                    sourceVmdDocuments,
                    out var ownerDocument,
                    out reason))
            {
                return false;
            }

            if (ownerDocument.SelectSingleNode(
                    $"{selection.ParentXmlPath}/SLOT[{selection.SlotIndex}]") is
                not XmlElement slotElement)
            {
                reason =
                    "optional joint slot no longer resolves in source VMD";
                return false;
            }

            if (!IsSupportedCrossRigidOptionalJointSlot(
                    slotElement))
            {
                reason =
                    "optional joint writer requires a nonempty slot, a bounded exact rational probability, and a bounded weighted alternative expansion";
                return false;
            }

            return true;
        }

        private static bool
            IsSupportedCrossRigidOptionalJointSlot(
                XmlElement slotElement)
            => TryGetCrossRigidOptionalJointMultiplicities(
                slotElement,
                out _,
                out _);

        private static bool
            TryGetCrossRigidOptionalJointMultiplicities(
                XmlElement slotElement,
                out int absentMultiplicity,
                out int presentMultiplicity)
        {
            absentMultiplicity = 0;
            presentMultiplicity = 0;
            var alternativeCount =
                (slotElement.SelectNodes(
                    "VARIANT_MESH")?.Count ?? 0) +
                (slotElement.SelectNodes(
                    "VARIANT_MESH_REFERENCE")?.Count ?? 0);
            if (alternativeCount == 0)
                return false;

            var probabilityText =
                slotElement.GetAttribute("probability");
            if (!decimal.TryParse(
                    probabilityText,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out var probability) ||
                probability <= 0 ||
                probability >= 1)
            {
                return false;
            }

            const int maxExactDenominator = 32;
            for (var denominator = 2;
                 denominator <= maxExactDenominator;
                 denominator++)
            {
                var scaled =
                    probability * denominator;
                if (scaled != decimal.Truncate(scaled))
                    continue;

                var numerator =
                    decimal.ToInt32(scaled);
                if (numerator <= 0 ||
                    numerator >= denominator)
                {
                    continue;
                }

                // With k equally likely present alternatives and
                // probability n/d, the absent weight is (d - n) * k
                // and each present alternative has weight n. Divide
                // every weight by their common divisor before counting
                // emitted wrappers. The distribution remains *exact*:
                // P(absent) = (d - n) / d and
                // P(each present alternative) = n / (d * k).
                //
                // This matters when k and n share a factor: an optional
                // 90% slot with three alternatives needs only 10
                // equally likely wrappers (1 absent, 3 per present
                // alternative), not the unreduced 30.
                var absentWeight =
                    (long)(denominator - numerator) * alternativeCount;
                long divisor = numerator;
                var remainder = absentWeight;
                while (remainder != 0)
                {
                    var next = divisor % remainder;
                    divisor = remainder;
                    remainder = next;
                }

                var reducedAbsent = absentWeight / divisor;
                var reducedPresent = numerator / divisor;
                var weightedCount =
                    reducedAbsent + reducedPresent * alternativeCount;
                if (weightedCount > MaxCrossRigidJointStateCombinations)
                    return false;

                absentMultiplicity = (int)reducedAbsent;
                presentMultiplicity = (int)reducedPresent;
                return true;
            }

            return false;
        }

        private static bool TryClassifyCrossRigidActivationToken(
            BatchState state,
            string token,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out bool optionalSlot,
            out string reason)
        {
            if (!TryParseCrossRigidActivationToken(
                    state,
                    token,
                    sourceVmdDocuments,
                    out var selection,
                    out reason))
            {
                optionalSlot = false;
                return false;
            }

            optionalSlot = selection.OptionalSlot;
            return true;
        }

        private static string GetCrossRigidActivationRewriteClassLabel(
            CrossRigidActivationRewriteClass rewriteClass)
            => rewriteClass switch
            {
                CrossRigidActivationRewriteClass.ExactActivationSafe =>
                    "exact activation (current writer)",
                CrossRigidActivationRewriteClass.JointAlwaysPresentSlots =>
                    "joint state across probability-1 slots/alternatives",
                CrossRigidActivationRewriteClass.JointOptionalSlots =>
                    "joint state involving an optional slot",
                CrossRigidActivationRewriteClass.LocalModelModifiers =>
                    "local model modifiers require preservation",
                _ => "unclassifiable activation topology",
            };

        private static IReadOnlyList<CrossRigidRewriteOccurrenceSet>
            BuildCrossRigidRewriteOccurrenceSets(
                CrossRigidVisualConfiguration configuration,
                IReadOnlyList<CrossRigidAnalysisInstanceComponent> group)
            => BuildCrossRigidRewriteOccurrenceSets(
                configuration,
                group
                    .Select(item => item.Instance)
                    .ToArray());

        private static IReadOnlyList<CrossRigidRewriteOccurrenceSet>
            BuildCrossRigidRewriteOccurrenceSets(
                CrossRigidVisualConfiguration configuration,
                IReadOnlyList<CrossRigidVisualInstance> sourceInstances)
            => BuildCrossRigidRewriteOccurrenceSets(
                configuration,
                BuildCrossRigidWsModelMultiplicity(
                    sourceInstances));

        private static IReadOnlyList<CrossRigidRewriteOccurrenceSet>
            BuildCrossRigidRewriteOccurrenceSets(
                CrossRigidVisualConfiguration configuration,
                IReadOnlyDictionary<string, int> expectedCounts)
        {
            var result = new List<CrossRigidRewriteOccurrenceSet>();

            foreach (var occurrenceSet in configuration.OccurrenceSets)
            {
                var selected = occurrenceSet.Instances
                    .Where(instance =>
                        expectedCounts.ContainsKey(
                            Normalize(instance.WsModelPath)))
                    .ToArray();
                var actualCounts =
                    BuildCrossRigidWsModelMultiplicity(
                        selected);
                if (actualCounts.Count != expectedCounts.Count ||
                    expectedCounts.Any(entry =>
                        !actualCounts.TryGetValue(
                            entry.Key,
                            out var actualCount) ||
                        actualCount != entry.Value))
                {
                    continue;
                }

                result.Add(
                    new CrossRigidRewriteOccurrenceSet(
                        occurrenceSet.Probability,
                        selected
                            .OrderBy(
                                instance =>
                                    BuildCrossRigidOccurrenceProvenanceSignature(
                                        [instance]),
                                StringComparer.Ordinal)
                            .ToArray()));
            }

            return MergeCrossRigidRewriteOccurrenceSets(result);
        }

        private static CrossRigidRewriteOccurrenceSet[]
            MergeCrossRigidRewriteOccurrenceSets(
                IEnumerable<CrossRigidRewriteOccurrenceSet> occurrenceSets)
        {
            var merged = new Dictionary<
                string,
                CrossRigidRewriteOccurrenceSet>(
                StringComparer.Ordinal);
            foreach (var occurrenceSet in occurrenceSets)
            {
                if (occurrenceSet.Probability <= 0)
                    continue;

                var key =
                    BuildCrossRigidOccurrenceProvenanceSignature(
                        occurrenceSet.SourceInstances);
                if (merged.TryGetValue(key, out var existing))
                {
                    merged[key] = existing with
                    {
                        Probability =
                            existing.Probability +
                            occurrenceSet.Probability,
                    };
                }
                else
                {
                    merged[key] = occurrenceSet;
                }
            }

            return merged
                .OrderBy(entry => entry.Key, StringComparer.Ordinal)
                .Select(entry => entry.Value)
                .ToArray();
        }

        private static string BuildCrossRigidGeneratedPayloadKey(
            IReadOnlyList<CrossRigidVisualInstance> sourceInstances,
            IReadOnlyList<CrossRigidLodAnalysis> lodAnalyses)
            => string.Join(
                "\u001f",
                string.Join(
                    "\u001e",
                    sourceInstances
                        .Select(instance => instance.WsModelPath)
                        .OrderBy(
                            path => path,
                            StringComparer.OrdinalIgnoreCase)),
                BuildCrossRigidLodLayoutSignature(lodAnalyses));

        private static string BuildCrossRigidLodLayoutSignature(
            IReadOnlyList<CrossRigidLodAnalysis> lodAnalyses)
            => string.Join(
                "\u001e",
                lodAnalyses
                    .OrderBy(lod => lod.LodIndex)
                    .Select(lod =>
                        string.Join(
                            ":",
                            lod.LodIndex,
                            lod.ScenarioLodIndex,
                            lod.QualityLevel,
                            lod.CameraDistance.ToString(
                                "R",
                                CultureInfo.InvariantCulture),
                            lod.IsScenarioRepresentativeState ? 1 : 0,
                            string.Join(
                                ",",
                                lod.SourceLodSelections
                                    .OrderBy(
                                        selection => selection.WsModelPath,
                                        StringComparer.OrdinalIgnoreCase)
                                    .Select(selection =>
                                        $"{Normalize(selection.WsModelPath)}={selection.SourceLodIndex}")),
                            lod.OutputLayoutSignature)));

        private static CrossRigidSourceGeometryComponent
            BuildCrossRigidSourceGeometryComponent(
                CrossRigidAnalysisInstanceComponent item)
        {
            long vertices = 0;
            long geometryBytes = 0;
            var vertexFactory = VertexFactory.Create();
            foreach (var model in item.Component.Rigid.ModelList.SelectMany(
                         lod => lod))
            {
                vertices += model.Mesh.VertexList.Length;
                var vertexSize = vertexFactory.GetVertexSize(
                    model.Material.BinaryVertexFormat,
                    item.Component.Rigid.Header.Version);
                geometryBytes +=
                    checked((long)vertexSize *
                            model.Mesh.VertexList.Length);
                geometryBytes +=
                    checked((long)sizeof(ushort) *
                            model.Mesh.IndexList.Length);
            }

            return new CrossRigidSourceGeometryComponent(
                item.Component.WsModelPath,
                item.Component.RigidPath,
                vertices,
                geometryBytes);
        }

        private static void RecordCrossRigidWsModelOccurrenceProbabilities(
            BatchState state,
            string vmdPath,
            CrossRigidAttachmentLocalExpansionResult expansion)
        {
            foreach (var (attachmentIdentity, configurations) in
                     expansion.ConfigurationsByAttachment)
            {
                var wsModels = configurations
                    .SelectMany(configuration => configuration.Instances)
                    .Select(instance => instance.WsModelPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                foreach (var wsModelPath in wsModels)
                {
                    var occurrenceProbability = Math.Clamp(
                        configurations
                            .Where(configuration =>
                                configuration.Instances.Any(instance =>
                                    instance.WsModelPath.Equals(
                                        wsModelPath,
                                        StringComparison.OrdinalIgnoreCase)))
                            .Sum(configuration => configuration.Probability),
                        0.0,
                        1.0);
                    if (occurrenceProbability <= 0)
                        continue;

                    state.CrossRigidWsModelOccurrenceProbabilities[
                        new CrossRigidWsModelOccurrenceKey(
                            Normalize(vmdPath),
                            attachmentIdentity,
                            Normalize(wsModelPath))] =
                        occurrenceProbability;
                }
            }
        }

        private static void BuildCrossRigidGeneratedPayloadAnalysis(
            BatchState state)
        {
            var dependencyIndex = state.GameplayMeshDependencyIndex;
            var rewriteCoverage =
                BuildCrossRigidRewriteCoverageByOccurrence(state);
            var sourceGeometryByRigid =
                state.CrossRigidMergeAnalysisEntries
                    .SelectMany(entry => entry.SourceGeometry)
                    .GroupBy(
                        source => source.RigidPath,
                        StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        group => group.Key,
                        group => group.First(),
                        StringComparer.OrdinalIgnoreCase);

            var fullyDisplacedRigids =
                new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (dependencyIndex != null)
            {
                foreach (var (rigidPath, sourceGeometry) in
                         sourceGeometryByRigid)
                {
                    if (!IsCrossRigidSourceRigidFullyCovered(
                            state,
                            dependencyIndex,
                            rigidPath,
                            rewriteCoverage,
                            out var wsConsumers))
                    {
                        continue;
                    }

                    var residentProbability =
                        GetExpectedArmyResidentProbability(
                            state,
                            wsConsumers,
                            Array.Empty<string>());
                    var expectedResidentBytes =
                        sourceGeometry.GeometryBytes *
                        residentProbability;
                    fullyDisplacedRigids.Add(rigidPath);
                    state.CrossRigidDisplacedSourceGeometryEntries.Add(
                        new CrossRigidDisplacedSourceGeometryEntry(
                            rigidPath,
                            sourceGeometry.GeometryBytes,
                            residentProbability,
                            expectedResidentBytes));
                }
            }

            var payloadGroups = state.CrossRigidMergeAnalysisEntries
                .GroupBy(
                    entry => entry.GeneratedPayloadId,
                    StringComparer.Ordinal)
                .Select(group => group.ToArray())
                .ToArray();
            var canonicalPayloadByDisplacedRigid =
                new Dictionary<string, string>(
                    StringComparer.OrdinalIgnoreCase);
            foreach (var rigidPath in fullyDisplacedRigids)
            {
                var canonicalPayloadId = payloadGroups
                    .Where(plans =>
                        plans[0].SourceGeometry.Any(source =>
                            source.RigidPath.Equals(
                                rigidPath,
                                StringComparison.OrdinalIgnoreCase)))
                    .Select(plans => plans[0].GeneratedPayloadId)
                    .OrderBy(id => id, StringComparer.Ordinal)
                    .FirstOrDefault();
                if (canonicalPayloadId != null)
                {
                    canonicalPayloadByDisplacedRigid[rigidPath] =
                        canonicalPayloadId;
                }
            }

            foreach (var plans in payloadGroups)
            {
                var representative = plans[0];
                var consumerDiscoveryComplete =
                    dependencyIndex != null &&
                    representative.SourceGeometry.All(source =>
                        !dependencyIndex.IsAssetAffectedByIncompleteRoot(
                            source.WsModelPath) &&
                        !dependencyIndex.IsAssetAffectedByIncompleteRoot(
                            source.RigidPath));
                var externalConsumers = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);
                long potentiallyDuplicatedGeometryBytes = 0;

                foreach (var source in representative.SourceGeometry)
                {
                    if (!fullyDisplacedRigids.Contains(source.RigidPath))
                    {
                        potentiallyDuplicatedGeometryBytes +=
                            source.GeometryBytes;
                    }

                    if (dependencyIndex == null)
                        continue;

                    if (dependencyIndex.WsModelConsumersByRigid.TryGetValue(
                            source.RigidPath,
                            out var wsConsumers))
                    {
                        foreach (var consumer in wsConsumers)
                        {
                            if (!IsCrossRigidWsModelFullyCovered(
                                    state,
                                    dependencyIndex,
                                    consumer,
                                    rewriteCoverage))
                            {
                                externalConsumers.Add(consumer);
                            }
                        }
                    }

                    if (dependencyIndex.DirectConsumersByRigid.TryGetValue(
                            source.RigidPath,
                            out var directConsumers))
                    {
                        externalConsumers.UnionWith(directConsumers);
                    }

                    if (dependencyIndex.IsAssetAffectedByIncompleteRoot(
                            source.RigidPath))
                    {
                        externalConsumers.UnionWith(
                            dependencyIndex.GetIncompleteRootsForAsset(
                                source.RigidPath));
                    }
                }

                var generatedVertices =
                    representative.Lods.Sum(
                        lod => lod.GeneratedVertexCount);
                var generatedGeometryBytes =
                    representative.Lods.Sum(
                        lod => lod.GeneratedGeometryBytes);
                var residentProbability =
                    CalculateExpectedCrossRigidPayloadResidentProbability(
                        state,
                        plans);
                var expectedResidentGeneratedBytes =
                    generatedGeometryBytes * residentProbability;
                var expectedResidentDisplacedBytes =
                    representative.SourceGeometry
                        .Select(source => source.RigidPath)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .Where(rigidPath =>
                            canonicalPayloadByDisplacedRigid
                                .TryGetValue(
                                    rigidPath,
                                    out var payloadId) &&
                            payloadId.Equals(
                                representative.GeneratedPayloadId,
                                StringComparison.Ordinal))
                        .Sum(rigidPath =>
                            state.CrossRigidDisplacedSourceGeometryEntries
                                .First(entry =>
                                    entry.RigidPath.Equals(
                                        rigidPath,
                                        StringComparison.OrdinalIgnoreCase))
                                .ExpectedResidentGeometryBytes);

                if (!consumerDiscoveryComplete)
                {
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Incomplete gameplay consumer discovery (non-blocking)",
                        $"payload {representative.GeneratedPayloadId}: " +
                        $"{string.Join(", ", representative.RigidPaths)}");
                }

                state.CrossRigidGeneratedPayloadAnalysisEntries.Add(
                    new CrossRigidGeneratedPayloadAnalysisEntry(
                        representative.GeneratedPayloadId,
                        plans.Length,
                        plans.Select(plan => plan.VmdPath)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count(),
                        representative.SourceInstances
                            .Select(instance => instance.WsModelPath)
                            .OrderBy(
                                path => path,
                                StringComparer.OrdinalIgnoreCase)
                            .ToArray(),
                        representative.RigidPaths,
                        representative.Lods,
                        generatedVertices,
                        generatedGeometryBytes,
                        potentiallyDuplicatedGeometryBytes,
                        residentProbability,
                        expectedResidentGeneratedBytes,
                        expectedResidentDisplacedBytes,
                        externalConsumers
                            .OrderBy(
                                path => path,
                                StringComparer.OrdinalIgnoreCase)
                            .ToArray(),
                        consumerDiscoveryComplete));
            }
        }


        private static void BuildCrossRigidCanonicalJointContexts(
            BatchState state,
            Dictionary<string, XmlDocument> sourceVmdDocuments)
        {
            state.CrossRigidCanonicalJointDescriptorByParentLocation.Clear();
            state.CrossRigidFactoredJointDescriptorsByParentLocation.Clear();
            state.CrossRigidFactoredJointParentCount = 0;
            state.CrossRigidFactoredJointGroupCount = 0;
            state.CrossRigidFactoredConditionalGroupCount = 0;
            state.CrossRigidFactoredSingleCarrierGroupCount = 0;
            state.CrossRigidFactoredPackingSearchImprovements = 0;
            state.CrossRigidFactoredPairLookaheadSeeds = 0;
            state.CrossRigidPartialCanonicalBeamImprovements = 0;
            state.CrossRigidPartialCanonicalBeamUnionCandidates = 0;
            state.CrossRigidCanonicalJointParentCount = 0;
            state.CrossRigidCanonicalJointContextsFolded = 0;
            state.CrossRigidCanonicalJointParentConflictCount = 0;

            var candidatesByParent =
                new Dictionary<
                    string,
                    List<(
                        string RootVmdPath,
                        CrossRigidJointAlwaysPresentRewriteDescriptor Descriptor,
                        string ContextKey)>>(
                    StringComparer.Ordinal);
            var benefitByContextKey =
                new Dictionary<string, double>(StringComparer.Ordinal);

            foreach (var plan in state.CrossRigidMergeAnalysisEntries)
            {
                // Pair-only fallback plans must not change the canonical
                // Cartesian context used by the old full-group portfolio.
                // They can project into a compatible context at selection
                // time or use an independent parent when safe.
                if (state.CrossRigidPreviouslySuppressedPairFallbackPlanIds
                        .Contains(plan.RewritePlanId))
                    continue;

                foreach (var occurrenceSet in plan.RewriteOccurrenceSets)
                {
                    if (occurrenceSet.SourceInstances
                            .Select(instance =>
                                instance.ActivationSignature)
                            .Distinct(StringComparer.Ordinal)
                            .Count() == 1)
                    {
                        continue;
                    }

                    if (!TryDescribeCrossRigidJointAlwaysPresentRewrite(
                            state,
                            occurrenceSet,
                            sourceVmdDocuments,
                            out var descriptor,
                            out _))
                    {
                        continue;
                    }

                    var parentLocationKey =
                        BuildCrossRigidJointParentLocationKey(
                            plan.VmdPath,
                            descriptor);
                    var contextKey =
                        BuildCrossRigidJointContextKey(
                            plan.VmdPath,
                            descriptor);
                    benefitByContextKey[contextKey] =
                        benefitByContextKey.GetValueOrDefault(contextKey) +
                        plan.ExpectedArmyDrawCallsEliminated *
                        occurrenceSet.Probability /
                        Math.Max(
                            plan.AggregatedConfigurationProbability,
                            AtlasValueGateExpectedDrawEpsilon);
                    if (!candidatesByParent.TryGetValue(
                            parentLocationKey,
                            out var candidates))
                    {
                        candidates = [];
                        candidatesByParent[parentLocationKey] =
                            candidates;
                    }

                    if (!candidates.Any(candidate =>
                            candidate.ContextKey.Equals(
                                contextKey,
                                StringComparison.Ordinal)))
                    {
                        candidates.Add(
                            (
                                plan.VmdPath,
                                descriptor,
                                contextKey));
                    }
                }
            }

            foreach (var (parentLocationKey, candidates) in
                     candidatesByParent)
            {
                CrossRigidJointAlwaysPresentRewriteDescriptor?
                    canonicalDescriptor = null;
                foreach (var candidate in
                         candidates
                             .OrderByDescending(item =>
                                 item.Descriptor.CombinationCount)
                             .ThenByDescending(item =>
                                 item.Descriptor
                                     .CommonAncestorDimensions
                                     .Length)
                             .ThenByDescending(item =>
                                 item.Descriptor.SlotIndices.Length)
                             .ThenBy(
                                 item => item.ContextKey,
                                 StringComparer.Ordinal))
                {
                    if (!candidates.All(other =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                candidate.Descriptor,
                                other.Descriptor)))
                    {
                        continue;
                    }

                    canonicalDescriptor =
                        candidate.Descriptor;
                    break;
                }

                // Distinct same-parent slot sets can be independently
                // correct without any existing candidate containing every
                // slot. Synthesize the full sibling-slot product when it
                // remains within the exact-state budget. Nested dimensions
                // are deliberately excluded: their dependencies must not
                // be flattened by a union.
                if (canonicalDescriptor == null &&
                    TryBuildCrossRigidCanonicalSiblingSlotUnion(
                        state,
                        candidates.Select(candidate =>
                            candidate.Descriptor),
                        sourceVmdDocuments,
                        out var siblingUnion))
                {
                    canonicalDescriptor = siblingUnion;
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Canonical sibling-slot union synthesized",
                        $"{candidates[0].RootVmdPath} / " +
                        $"{siblingUnion.ParentXmlPath}: " +
                        $"slots={string.Join(",", siblingUnion.SlotIndices)}, " +
                        $"weightedStates={siblingUnion.CombinationCount}");
                }

                if (canonicalDescriptor == null &&
                    TryBuildCrossRigidCanonicalConditionalDimensionUnion(
                        state,
                        candidates.Select(candidate =>
                            candidate.Descriptor),
                        sourceVmdDocuments,
                        out var conditionalUnion))
                {
                    canonicalDescriptor = conditionalUnion;
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Canonical conditional-dimension union synthesized",
                        $"{candidates[0].RootVmdPath} / " +
                        $"{conditionalUnion.ParentXmlPath}: " +
                        $"slots={string.Join(",", conditionalUnion.SlotIndices)}, " +
                        $"dimensions={conditionalUnion.CommonAncestorDimensions.Length}, " +
                        $"weightedStates={conditionalUnion.CombinationCount}");
                }

                if (canonicalDescriptor == null &&
                    TryBuildCrossRigidCanonicalMixedDimensionUnion(
                        state,
                        candidates.Select(candidate => candidate.Descriptor),
                        sourceVmdDocuments,
                        out var mixedUnion))
                {
                    canonicalDescriptor = mixedUnion;
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Canonical independent sibling/conditional union synthesized",
                        candidates[0].RootVmdPath + " / " +
                        mixedUnion.ParentXmlPath + ": slots=" +
                        string.Join(",", mixedUnion.SlotIndices) +
                        ", dimensions=" +
                        mixedUnion.CommonAncestorDimensions.Length +
                        ", weightedStates=" +
                        mixedUnion.CombinationCount);
                }

                // Disjoint direct root slot sets can remain separate joint
                // slots. Their runtime random choices preserve the original
                // product distribution without expanding the global product.
                if (canonicalDescriptor == null &&
                    TryBuildCrossRigidFactoredRootJointContexts(
                        state,
                        candidates,
                        benefitByContextKey,
                        sourceVmdDocuments,
                        out var factors))
                {
                    state.CrossRigidFactoredJointDescriptorsByParentLocation[
                        parentLocationKey] = factors;
                    state.CrossRigidFactoredJointParentCount++;
                    state.CrossRigidFactoredJointGroupCount += factors.Length;
                    state.CrossRigidFactoredConditionalGroupCount +=
                        factors.Count(factor =>
                            factor.CommonAncestorDimensions.Length != 0);
                    state.CrossRigidFactoredSingleCarrierGroupCount +=
                        factors.Count(factor => factor.SlotIndices.Length == 1);
                    var coveredContexts = candidates.Count(candidate =>
                        factors.Any(factor =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                factor, candidate.Descriptor)));
                    if (coveredContexts < candidates.Count)
                        state.CrossRigidCanonicalJointParentConflictCount++;
                    var synthesizedFactors = factors.Count(factor =>
                        !candidates.Any(candidate =>
                            BuildCrossRigidJointContextKey(
                                    candidate.RootVmdPath, factor)
                                .Equals(
                                    candidate.ContextKey,
                                    StringComparison.Ordinal)));
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Factored root Cartesian contexts synthesized",
                        candidates[0].RootVmdPath +
                        $": covered={coveredContexts}/{candidates.Count}, " +
                        $"synthetic={synthesizedFactors}; " +
                        string.Join(" | ", factors.Select(factor =>
                            $"slots={string.Join(",", factor.SlotIndices)} " +
                            $"weightedStates={factor.CombinationCount}")));
                    continue;
                }

                // A single parent may have several incompatible contexts
                // even though a useful subset can be represented exactly.
                // Do not discard compatible smaller cohorts merely because
                // the union of every observed context exceeds the state cap.
                if (canonicalDescriptor == null &&
                    TryBuildCrossRigidBestPartialCanonicalJointContext(
                        state,
                        candidates.Select(candidate => candidate.Descriptor)
                            .ToArray(),
                        candidates[0].RootVmdPath,
                        benefitByContextKey,
                        sourceVmdDocuments,
                        out var partialDescriptor,
                        out var partialContextCount))
                {
                    canonicalDescriptor = partialDescriptor;
                    var coveredBenefit = candidates
                        .Where(candidate =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                partialDescriptor, candidate.Descriptor))
                        .Sum(candidate =>
                            benefitByContextKey.GetValueOrDefault(
                                candidate.ContextKey));
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Partial canonical joint context synthesized",
                        $"{candidates[0].RootVmdPath} / " +
                        $"{partialDescriptor.ParentXmlPath}: " +
                        $"covered={partialContextCount}/{candidates.Count}, " +
                        $"benefit={coveredBenefit:0.###} expectedDraws, " +
                        $"slots={string.Join(",", partialDescriptor.SlotIndices)}, " +
                        $"dimensions={partialDescriptor.CommonAncestorDimensions.Length}, " +
                        $"weightedStates={partialDescriptor.CombinationCount}");
                }

                if (canonicalDescriptor == null)
                {
                    if (candidates.Count > 1)
                    {
                        state.CrossRigidCanonicalJointParentConflictCount++;
                    }

                    continue;
                }

                var coveredContextCount = candidates.Count(candidate =>
                    IsCrossRigidJointDescriptorStructuralSuperset(
                        canonicalDescriptor,
                        candidate.Descriptor));
                if (coveredContextCount < candidates.Count)
                {
                    // The remaining contexts continue to compete through
                    // their normal parent-location conflict keys.
                    state.CrossRigidCanonicalJointParentConflictCount++;
                }

                state.CrossRigidCanonicalJointDescriptorByParentLocation[
                    parentLocationKey] =
                    canonicalDescriptor;
                if (coveredContextCount > 1)
                {
                    state.CrossRigidCanonicalJointParentCount++;
                    state.CrossRigidCanonicalJointContextsFolded +=
                        coveredContextCount - 1;
                }
            }
        }

        // Root-level carrier slots are independent random choices even when
        // a carrier contains conditional local or child-VMD selections. An
        // incompatible context must not disable factoring unrelated carriers:
        // it can still compete against the factored context at selection time.
        // Never factor overlapping carriers or non-root structural parents.
        private static bool TryBuildCrossRigidFactoredRootJointContexts(
            BatchState state,
            IReadOnlyList<(
                string RootVmdPath,
                CrossRigidJointAlwaysPresentRewriteDescriptor Descriptor,
                string ContextKey)> candidates,
            IReadOnlyDictionary<string, double> benefitByContextKey,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointAlwaysPresentRewriteDescriptor[] factors)
        {
            factors = [];
            if (candidates.Count < 2)
                return false;

            // A single root carrier can contain several co-rendered
            // descendants with conditional choices. Such a joint context
            // can coexist with disjoint root carriers without multiplying
            // its Cartesian states into the other contexts.
            // Keep every existing anchor, dimension and disjointness check.
            var ranked = candidates
                .Where(item =>
                    item.Descriptor.SlotIndices.Length >= 1 &&
                    item.Descriptor.AnchorReferenceChain.Length == 0 &&
                    item.Descriptor.ParentXmlPath == "/VARIANT_MESH" &&
                    Normalize(item.Descriptor.AnchorVmdPath).Equals(
                        Normalize(item.RootVmdPath),
                        StringComparison.OrdinalIgnoreCase) &&
                    item.Descriptor.CommonAncestorDimensions.All(dimension =>
                        item.Descriptor.SlotIndices.Contains(
                            dimension.CarrierSlotIndex)))
                .OrderByDescending(item =>
                    benefitByContextKey.GetValueOrDefault(item.ContextKey))
                .ThenBy(item => item.Descriptor.CombinationCount)
                .ThenBy(item => item.ContextKey, StringComparer.Ordinal)
                .ToArray();
            if (ranked.Length < 2)
                return false;

            // Overlapping root carriers must form one factor, not two
            // independent SLOTs. An exact bounded union can cover several
            // overlapping candidate contexts, leaving other disjoint carrier
            // groups free to become separate factors. Only combine through
            // the same state/probability/dependency validator used for
            // ordinary canonical joint contexts.
            var possibleFactors = ranked
                .Select(item => item.Descriptor)
                .ToList();
            // Greedy expansion from one candidate can skip a smaller
            // overlapping-carrier union which leaves room for another
            // independent factor. Generate bounded pair seeds through the
            // same exact-state and dependency validators as ordinary unions.
            const int maxPairLookaheadSources = 32;
            const int maxPairLookaheadSeeds = 96;
            var expansionSeeds = ranked.Take(24)
                .Select(item => item.Descriptor)
                .ToList();
            var pairSeedOptions = new Dictionary<
                string,
                (CrossRigidJointAlwaysPresentRewriteDescriptor Descriptor,
                    double Benefit)>(StringComparer.Ordinal);
            var lookaheadCandidates = ranked
                .Take(maxPairLookaheadSources)
                .ToArray();
            for (var leftIndex = 0;
                 leftIndex < lookaheadCandidates.Length;
                 leftIndex++)
            {
                var left = lookaheadCandidates[leftIndex].Descriptor;
                for (var rightIndex = leftIndex + 1;
                     rightIndex < lookaheadCandidates.Length;
                     rightIndex++)
                {
                    var right = lookaheadCandidates[rightIndex].Descriptor;
                    if (!left.SlotIndices.Intersect(
                            right.SlotIndices).Any() ||
                        !TryCombineCrossRigidCanonicalJointContexts(
                            state,
                            left,
                            right,
                            sourceVmdDocuments,
                            out var union) ||
                        union.CommonAncestorDimensions.Any(dimension =>
                            !union.SlotIndices.Contains(
                                dimension.CarrierSlotIndex)))
                    {
                        continue;
                    }

                    var key = BuildCrossRigidJointContextKey(
                        ranked[0].RootVmdPath, union);
                    if (pairSeedOptions.ContainsKey(key))
                        continue;

                    var benefit = ranked
                        .Where(item =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                union, item.Descriptor))
                        .Sum(item =>
                            benefitByContextKey.GetValueOrDefault(
                                item.ContextKey));
                    pairSeedOptions.Add(key, (union, benefit));
                }
            }

            var pairSeeds = pairSeedOptions
                .OrderByDescending(item => item.Value.Benefit)
                .ThenBy(item => item.Value.Descriptor.CombinationCount)
                .ThenBy(item => item.Key, StringComparer.Ordinal)
                .Take(maxPairLookaheadSeeds)
                .Select(item => item.Value.Descriptor)
                .ToArray();
            state.CrossRigidFactoredPairLookaheadSeeds += pairSeeds.Length;
            expansionSeeds.AddRange(pairSeeds);

            foreach (var seedDescriptor in expansionSeeds)
            {
                var current = seedDescriptor;
                // Retain the unexpanded pair: its smaller carrier set may
                // fit beside a better disjoint group than its greedy closure.
                possibleFactors.Add(current);
                while (true)
                {
                    CrossRigidJointAlwaysPresentRewriteDescriptor?
                        bestExpansion = null;
                    var currentCoverage = ranked
                        .Where(item =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                current, item.Descriptor))
                        .Sum(item =>
                            benefitByContextKey.GetValueOrDefault(
                                item.ContextKey));
                    var bestGain = 0.0;
                    foreach (var candidate in ranked.Take(48))
                    {
                        if (IsCrossRigidJointDescriptorStructuralSuperset(
                                current, candidate.Descriptor) ||
                            !current.SlotIndices.Intersect(
                                candidate.Descriptor.SlotIndices).Any() ||
                            !TryCombineCrossRigidCanonicalJointContexts(
                                state,
                                current,
                                candidate.Descriptor,
                                sourceVmdDocuments,
                                out var expansion) ||
                            expansion.CommonAncestorDimensions.Any(dimension =>
                                !expansion.SlotIndices.Contains(
                                    dimension.CarrierSlotIndex)))
                        {
                            continue;
                        }

                        var expandedCoverage = ranked
                            .Where(item =>
                                IsCrossRigidJointDescriptorStructuralSuperset(
                                    expansion, item.Descriptor))
                            .Sum(item =>
                                benefitByContextKey.GetValueOrDefault(
                                    item.ContextKey));
                        var gain = expandedCoverage - currentCoverage;
                        if (gain <= AtlasValueGateExpectedDrawEpsilon ||
                            gain < bestGain -
                                AtlasValueGateExpectedDrawEpsilon ||
                            (Math.Abs(gain - bestGain) <=
                                 AtlasValueGateExpectedDrawEpsilon &&
                             bestExpansion != null &&
                             expansion.CombinationCount >=
                             bestExpansion.CombinationCount))
                        {
                            continue;
                        }

                        bestExpansion = expansion;
                        bestGain = gain;
                    }

                    if (bestExpansion == null)
                        break;
                    current = bestExpansion;
                }

                possibleFactors.Add(current);
            }

            var options = possibleFactors
                .Select(descriptor => new
                {
                    Descriptor = descriptor,
                    Benefit = ranked
                        .Where(item =>
                            IsCrossRigidJointDescriptorStructuralSuperset(
                                descriptor, item.Descriptor))
                        .Sum(item =>
                            benefitByContextKey.GetValueOrDefault(
                                item.ContextKey)),
                    Key = BuildCrossRigidJointContextKey(
                        ranked[0].RootVmdPath, descriptor),
                })
                .GroupBy(option => option.Key, StringComparer.Ordinal)
                .Select(group => group.First())
                .OrderByDescending(option => option.Benefit)
                .ThenBy(option => option.Descriptor.CombinationCount)
                .ThenBy(option => option.Key, StringComparer.Ordinal)
                .Take(96)
                .ToArray();

            // A single greedy largest-benefit factor can block two disjoint
            // smaller groups (AB versus AC+BD). Compare bounded alternatives
            // from each promising seed, including synthesized union factors.
            var bestBenefit = double.NegativeInfinity;
            var bestStateCount = long.MaxValue;
            CrossRigidJointAlwaysPresentRewriteDescriptor[] best = [];
            foreach (var seed in options.Take(64))
            {
                var chosen =
                    new List<CrossRigidJointAlwaysPresentRewriteDescriptor>();
                var usedSlots = new HashSet<int>();
                var benefit = 0.0;
                long stateCount = 0;
                foreach (var option in new[] { seed }
                             .Concat(options.Where(option =>
                                 !option.Key.Equals(
                                     seed.Key, StringComparison.Ordinal))))
                {
                    if (option.Descriptor.SlotIndices.Any(
                            usedSlots.Contains))
                        continue;

                    chosen.Add(option.Descriptor);
                    usedSlots.UnionWith(option.Descriptor.SlotIndices);
                    benefit += option.Benefit;
                    stateCount += option.Descriptor.CombinationCount;
                }

                if (chosen.Count < 2 ||
                    benefit < bestBenefit -
                        AtlasValueGateExpectedDrawEpsilon ||
                    (Math.Abs(benefit - bestBenefit) <=
                         AtlasValueGateExpectedDrawEpsilon &&
                     stateCount >= bestStateCount))
                    continue;

                bestBenefit = benefit;
                bestStateCount = stateCount;
                best = chosen.ToArray();
            }

            // The seeded greedy pass above is a safe baseline, but one
            // high-benefit factor can mask two smaller disjoint factors.
            // Search exact disjoint root-slot sets with bounded states.
            // Only change the factoring if this strictly improves covered
            // candidate benefit (or ties at fewer weighted states).
            const int maxPackingStates = 4096;
            var packingStates = new Dictionary<
                (ulong Slots, int FactorCount),
                (double Benefit, long StateCount, int[] OptionIndices)>
            {
                [(0UL, 0)] = (0, 0, []),
            };
            for (var optionIndex = 0; optionIndex < options.Length;
                 optionIndex++)
            {
                var option = options[optionIndex];
                ulong mask = 0;
                var representable = true;
                foreach (var slot in option.Descriptor.SlotIndices)
                {
                    if (slot < 1 || slot > 63)
                    {
                        representable = false;
                        break;
                    }

                    mask |= 1UL << (slot - 1);
                }

                if (!representable || mask == 0)
                    continue;

                var nextStates = new Dictionary<
                    (ulong Slots, int FactorCount),
                    (double Benefit, long StateCount, int[] OptionIndices)>(
                        packingStates);
                foreach (var (used, selection) in packingStates)
                {
                    if ((used.Slots & mask) != 0)
                        continue;

                    var newKey = (
                        Slots: used.Slots | mask,
                        FactorCount: Math.Min(2, used.FactorCount + 1));
                    var newBenefit = selection.Benefit + option.Benefit;
                    var newStateCount =
                        selection.StateCount +
                        option.Descriptor.CombinationCount;
                    if (nextStates.TryGetValue(newKey, out var previous) &&
                        (previous.Benefit >
                             newBenefit + AtlasValueGateExpectedDrawEpsilon ||
                         (Math.Abs(previous.Benefit - newBenefit) <=
                              AtlasValueGateExpectedDrawEpsilon &&
                          previous.StateCount <= newStateCount)))
                    {
                        continue;
                    }

                    nextStates[newKey] = (
                        newBenefit,
                        newStateCount,
                        selection.OptionIndices.Append(optionIndex).ToArray());
                }

                if (nextStates.Count > maxPackingStates)
                {
                    // Keep promising packings and always retain the empty
                    // starting point for later disjoint alternatives.
                    var reduced = nextStates
                        .OrderByDescending(item => item.Value.Benefit)
                        .ThenBy(item => item.Value.StateCount)
                        .Take(maxPackingStates - 1)
                        .ToDictionary(item => item.Key, item => item.Value);
                    reduced.TryAdd((0UL, 0), (0, 0, []));
                    nextStates = reduced;
                }

                packingStates = nextStates;
            }

            var packingImproved = false;
            foreach (var (key, selection) in packingStates)
            {
                if (key.FactorCount < 2 ||
                    selection.Benefit < bestBenefit -
                        AtlasValueGateExpectedDrawEpsilon ||
                    (Math.Abs(selection.Benefit - bestBenefit) <=
                         AtlasValueGateExpectedDrawEpsilon &&
                     selection.StateCount >= bestStateCount))
                {
                    continue;
                }

                bestBenefit = selection.Benefit;
                bestStateCount = selection.StateCount;
                best = selection.OptionIndices
                    .Select(index => options[index].Descriptor)
                    .ToArray();
                packingImproved = true;
            }

            if (best.Length < 2)
                return false;
            if (packingImproved)
                state.CrossRigidFactoredPackingSearchImprovements++;
            factors = best;
            return true;
        }

        private const string CrossRigidFactoredParentMarker =
            "factored-independent-root-slots";

        private static bool TryGetCrossRigidFactoredDescriptor(
            BatchState state,
            string originalParentKey,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
            out CrossRigidJointAlwaysPresentRewriteDescriptor factor)
        {
            if (state.CrossRigidFactoredJointDescriptorsByParentLocation
                    .TryGetValue(originalParentKey, out var factors))
            {
                foreach (var candidate in factors)
                {
                    if (IsCrossRigidJointDescriptorStructuralSuperset(
                            candidate, descriptor))
                    {
                        factor = candidate;
                        return true;
                    }
                }
            }
            factor = null!;
            return false;
        }

        private static string GetCrossRigidEffectiveJointParentKey(
            BatchState state,
            string rootVmdPath,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            var originalKey = BuildCrossRigidJointParentLocationKey(
                rootVmdPath, descriptor);
            return TryGetCrossRigidFactoredDescriptor(
                    state, originalKey, descriptor, out var factor)
                ? originalKey + "\u001ffactor-slots=" +
                  string.Join(",", factor.SlotIndices)
                : originalKey;
        }

        // The standard writer uses one Cartesian context at a structural
        // parent. When the entire union is too large, find the most
        // valuable compatible subset and leave other contexts competing
        // through their original structural-parent keys. Benefit comes from
        // the same per-context scenario draw estimates used by the
        // generated-payload portfolio; raw context count is only a tie-break.
        // No new states are admitted without the existing exact-probability,
        // dependency and 1,024-state union validators.
        private static bool
            TryBuildCrossRigidBestPartialCanonicalJointContext(
                BatchState state,
                IReadOnlyList<CrossRigidJointAlwaysPresentRewriteDescriptor>
                    candidates,
                string rootVmdPath,
                IReadOnlyDictionary<string, double> benefitByContextKey,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
                out int coveredContextCount)
        {
            descriptor = null!;
            coveredContextCount = 0;
            if (candidates.Count < 3)
                return false;

            var weightedCandidates = candidates
                .Select(candidate => (
                    Descriptor: candidate,
                    Benefit: benefitByContextKey.GetValueOrDefault(
                        BuildCrossRigidJointContextKey(
                            rootVmdPath, candidate))))
                .ToArray();

            (double Benefit, int Count) Score(
                CrossRigidJointAlwaysPresentRewriteDescriptor context)
            {
                var benefit = 0.0;
                var count = 0;
                foreach (var item in weightedCandidates)
                {
                    if (!IsCrossRigidJointDescriptorStructuralSuperset(
                            context, item.Descriptor))
                        continue;

                    benefit += item.Benefit;
                    count++;
                }

                return (benefit, count);
            }

            var bestBenefit = double.NegativeInfinity;
            for (var seedIndex = 0;
                 seedIndex < candidates.Count;
                 seedIndex++)
            {
                var current = candidates[seedIndex];
                var (currentBenefit, currentCoverage) = Score(current);

                // Try all seeds: the highest-count cohort may exclude a
                // more valuable compatible cohort that fits the same cap.
                while (true)
                {
                    CrossRigidJointAlwaysPresentRewriteDescriptor?
                        bestExpansion = null;
                    var bestExpansionBenefit = currentBenefit;
                    var bestExpansionCoverage = currentCoverage;
                    foreach (var candidate in candidates)
                    {
                        if (IsCrossRigidJointDescriptorStructuralSuperset(
                                current, candidate) ||
                            !TryCombineCrossRigidCanonicalJointContexts(
                                state,
                                current,
                                candidate,
                                sourceVmdDocuments,
                                out var expansion))
                        {
                            continue;
                        }

                        var (expansionBenefit, expansionCoverage) =
                            Score(expansion);
                        if (expansionBenefit >
                                bestExpansionBenefit +
                                AtlasValueGateExpectedDrawEpsilon ||
                            (Math.Abs(
                                 expansionBenefit -
                                 bestExpansionBenefit) <=
                             AtlasValueGateExpectedDrawEpsilon &&
                             (expansionCoverage > bestExpansionCoverage ||
                              (expansionCoverage == bestExpansionCoverage &&
                               bestExpansion != null &&
                               expansion.CombinationCount <
                               bestExpansion.CombinationCount))))
                        {
                            bestExpansion = expansion;
                            bestExpansionBenefit = expansionBenefit;
                            bestExpansionCoverage = expansionCoverage;
                        }
                    }

                    if (bestExpansion == null)
                        break;

                    current = bestExpansion;
                    currentBenefit = bestExpansionBenefit;
                    currentCoverage = bestExpansionCoverage;
                }

                if (currentCoverage <= 1 ||
                    currentBenefit <
                        bestBenefit -
                        AtlasValueGateExpectedDrawEpsilon ||
                    (Math.Abs(
                         currentBenefit -
                         bestBenefit) <=
                     AtlasValueGateExpectedDrawEpsilon &&
                     (currentCoverage < coveredContextCount ||
                      (currentCoverage == coveredContextCount &&
                       descriptor != null &&
                       current.CombinationCount >=
                       descriptor.CombinationCount))))
                {
                    continue;
                }

                descriptor = current;
                bestBenefit = currentBenefit;
                coveredContextCount = currentCoverage;
            }

            // A greedy expansion can spend the remaining weighted-state
            // budget on the wrong overlapping context. Keep a bounded
            // frontier of alternative unions instead of committing to only
            // the locally highest-benefit expansion. The existing union
            // validator still enforces dependency structure, exact weights,
            // and the 1,024-state cap for every candidate.
            const int maxPartialCanonicalBeamWidth = 64;
            const int maxPartialCanonicalBeamDepth = 3;
            var greedyDescriptor = descriptor;
            var greedyBenefit = bestBenefit;
            var greedyCoveredCount = coveredContextCount;
            var beam = candidates
                .Select(candidate =>
                {
                    var (benefit, count) = Score(candidate);
                    return (
                        Descriptor: candidate,
                        Benefit: benefit,
                        Count: count);
                })
                .OrderByDescending(item => item.Benefit)
                .ThenByDescending(item => item.Count)
                .ThenBy(item => item.Descriptor.CombinationCount)
                .Take(maxPartialCanonicalBeamWidth)
                .ToArray();
            var visited = new HashSet<string>(
                beam.Select(item => BuildCrossRigidJointContextKey(
                    rootVmdPath, item.Descriptor)),
                StringComparer.Ordinal);
            for (var depth = 0;
                 depth < maxPartialCanonicalBeamDepth && beam.Length != 0;
                 depth++)
            {
                var next = new List<(
                    CrossRigidJointAlwaysPresentRewriteDescriptor Descriptor,
                    double Benefit,
                    int Count)>();
                foreach (var partial in beam)
                {
                    foreach (var candidate in candidates)
                    {
                        if (IsCrossRigidJointDescriptorStructuralSuperset(
                                partial.Descriptor, candidate) ||
                            !TryCombineCrossRigidCanonicalJointContexts(
                                state,
                                partial.Descriptor,
                                candidate,
                                sourceVmdDocuments,
                                out var expansion))
                        {
                            continue;
                        }

                        var (benefit, count) = Score(expansion);
                        if (count <= partial.Count ||
                            !visited.Add(BuildCrossRigidJointContextKey(
                                rootVmdPath, expansion)))
                        {
                            continue;
                        }

                        next.Add((expansion, benefit, count));
                        if (count <= 1 ||
                            benefit < bestBenefit -
                                AtlasValueGateExpectedDrawEpsilon ||
                            (Math.Abs(benefit - bestBenefit) <=
                                 AtlasValueGateExpectedDrawEpsilon &&
                             (count < coveredContextCount ||
                              (count == coveredContextCount &&
                               descriptor != null &&
                               expansion.CombinationCount >=
                                   descriptor.CombinationCount))))
                        {
                            continue;
                        }

                        descriptor = expansion;
                        bestBenefit = benefit;
                        coveredContextCount = count;
                    }
                }

                state.CrossRigidPartialCanonicalBeamUnionCandidates +=
                    next.Count;
                beam = next
                    .OrderByDescending(item => item.Benefit)
                    .ThenByDescending(item => item.Count)
                    .ThenBy(item => item.Descriptor.CombinationCount)
                    .Take(maxPartialCanonicalBeamWidth)
                    .ToArray();
            }

            if (coveredContextCount > 1 &&
                (bestBenefit > greedyBenefit +
                     AtlasValueGateExpectedDrawEpsilon ||
                 (Math.Abs(bestBenefit - greedyBenefit) <=
                      AtlasValueGateExpectedDrawEpsilon &&
                  (coveredContextCount > greedyCoveredCount ||
                   (coveredContextCount == greedyCoveredCount &&
                    greedyDescriptor != null &&
                    descriptor.CombinationCount <
                        greedyDescriptor.CombinationCount)))))
            {
                state.CrossRigidPartialCanonicalBeamImprovements++;
            }

            return coveredContextCount > 1;
        }

        private static bool TryCombineCrossRigidCanonicalJointContexts(
            BatchState state,
            CrossRigidJointAlwaysPresentRewriteDescriptor left,
            CrossRigidJointAlwaysPresentRewriteDescriptor right,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            if (IsCrossRigidJointDescriptorStructuralSuperset(
                    left, right))
            {
                descriptor = left;
                return true;
            }

            if (IsCrossRigidJointDescriptorStructuralSuperset(
                    right, left))
            {
                descriptor = right;
                return true;
            }

            if (left.CommonAncestorDimensions.Length == 0 &&
                right.CommonAncestorDimensions.Length == 0)
            {
                return TryBuildCrossRigidCanonicalSiblingSlotUnion(
                    state,
                    [left, right],
                    sourceVmdDocuments,
                    out descriptor);
            }

            if (left.CommonAncestorDimensions.Length != 0 &&
                right.CommonAncestorDimensions.Length != 0)
            {
                return TryBuildCrossRigidCanonicalConditionalDimensionUnion(
                    state,
                    [left, right],
                    sourceVmdDocuments,
                    out descriptor);
            }

            // Independent sibling choices can coexist with conditional
            // dimensions only when they do not share a carrier slot.
            return TryBuildCrossRigidCanonicalMixedDimensionUnion(
                state,
                [left, right],
                sourceVmdDocuments,
                out descriptor);
        }

        private static bool TryBuildCrossRigidCanonicalSiblingSlotUnion(
            BatchState state,
            IEnumerable<CrossRigidJointAlwaysPresentRewriteDescriptor>
                candidateDescriptors,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            descriptor = null!;
            var candidates = candidateDescriptors.ToArray();
            if (candidates.Length < 2 ||
                candidates.Any(candidate =>
                    candidate.CommonAncestorDimensions.Length != 0))
            {
                return false;
            }

            var first = candidates[0];
            if (candidates.Skip(1).Any(candidate =>
                    !Normalize(candidate.AnchorVmdPath).Equals(
                        Normalize(first.AnchorVmdPath),
                        StringComparison.OrdinalIgnoreCase) ||
                    !candidate.ParentXmlPath.Equals(
                        first.ParentXmlPath,
                        StringComparison.Ordinal) ||
                    !BuildCrossRigidReferenceChainSignature(
                        candidate.AnchorReferenceChain).Equals(
                        BuildCrossRigidReferenceChainSignature(
                            first.AnchorReferenceChain),
                        StringComparison.Ordinal)))
            {
                return false;
            }

            var slotIndices = candidates
                .SelectMany(candidate => candidate.SlotIndices)
                .Distinct()
                .OrderBy(index => index)
                .ToArray();

            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    first.AnchorVmdPath,
                    sourceVmdDocuments,
                    out var anchorDocument,
                    out _) ||
                anchorDocument.SelectSingleNode(
                    first.ParentXmlPath) is not XmlElement parentElement)
            {
                return false;
            }

            long weightedStates = 1;
            foreach (var slotIndex in slotIndices)
            {
                if (parentElement.SelectSingleNode(
                        $"SLOT[{slotIndex}]") is not XmlElement slotElement)
                {
                    return false;
                }

                var optional = ParseVmdSlotProbability(
                    slotElement.GetAttribute("probability")) <
                    1.0 - AtlasValueGateExpectedDrawEpsilon;
                if (optional &&
                    !IsSupportedCrossRigidOptionalJointSlot(slotElement))
                {
                    return false;
                }

                var alternatives = GetCrossRigidJointAlternatives(
                    slotElement,
                    slotIndex);
                if (alternatives.Length <= 1)
                    return false;

                var factor = alternatives.Sum(alternative =>
                    (long)alternative.Multiplicity);
                if (factor <= 1 ||
                    weightedStates >
                    MaxCrossRigidJointStateCombinations / factor)
                {
                    return false;
                }

                weightedStates *= factor;
            }

            // The canonical descriptor is only the joint context's shape.
            // Each emitted occurrence retains its own source selections
            // and is projected onto every matching union state.
            var canonicalDescriptor = first with
            {
                SlotIndices = slotIndices,
                CombinationCount = (int)weightedStates,
            };
            descriptor = canonicalDescriptor;
            return candidates.All(candidate =>
                IsCrossRigidJointDescriptorStructuralSuperset(
                    canonicalDescriptor,
                    candidate));
        }

        // Lift independent sibling alternatives to root dimensions beside
        // conditional dimensions. A conditional carrier (even when fixed)
        // must remain under its original dependency graph.
        private static bool TryBuildCrossRigidCanonicalMixedDimensionUnion(
            BatchState state,
            IEnumerable<CrossRigidJointAlwaysPresentRewriteDescriptor>
                candidateDescriptors,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            descriptor = null!;
            var candidates = candidateDescriptors.ToArray();
            var direct = candidates.Where(candidate =>
                candidate.CommonAncestorDimensions.Length == 0).ToArray();
            var conditional = candidates.Where(candidate =>
                candidate.CommonAncestorDimensions.Length != 0).ToArray();
            if (direct.Length == 0 || conditional.Length == 0)
                return false;

            var first = candidates[0];
            if (candidates.Skip(1).Any(candidate =>
                    !Normalize(candidate.AnchorVmdPath).Equals(
                        Normalize(first.AnchorVmdPath),
                        StringComparison.OrdinalIgnoreCase) ||
                    !candidate.ParentXmlPath.Equals(
                        first.ParentXmlPath,
                        StringComparison.Ordinal) ||
                    !BuildCrossRigidReferenceChainSignature(
                        candidate.AnchorReferenceChain).Equals(
                        BuildCrossRigidReferenceChainSignature(
                            first.AnchorReferenceChain),
                        StringComparison.Ordinal)))
            {
                return false;
            }

            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    first.AnchorVmdPath,
                    sourceVmdDocuments,
                    out var anchorDocument,
                    out _) ||
                anchorDocument.SelectSingleNode(
                    first.ParentXmlPath) is not XmlElement parentElement)
            {
                return false;
            }

            var directSlots = direct
                .SelectMany(candidate => candidate.SlotIndices)
                .Distinct()
                .OrderBy(index => index)
                .ToArray();
            var conditionalCarrierSlots = conditional
                .SelectMany(candidate => candidate.SlotIndices)
                .ToHashSet();
            if (directSlots.Any(conditionalCarrierSlots.Contains))
                return false;

            var rootDimensions =
                new Dictionary<int, CrossRigidJointSelectionDimension>();
            foreach (var slotIndex in directSlots)
            {
                if (parentElement.SelectSingleNode(
                        "SLOT[" + slotIndex + "]") is not XmlElement slot)
                    return false;
                if (ParseVmdSlotProbability(
                        slot.GetAttribute("probability")) <
                        1.0 - AtlasValueGateExpectedDrawEpsilon &&
                    !IsSupportedCrossRigidOptionalJointSlot(slot))
                {
                    return false;
                }

                var key = BuildCrossRigidJointSelectionDimensionKey(
                    first.AnchorVmdPath,
                    first.ParentXmlPath,
                    slotIndex);
                var alternatives =
                    GetCrossRigidJointAlternatives(slot, slotIndex)
                        .Select(alternative =>
                            new CrossRigidJointDimensionAlternative(
                                key,
                                alternative.IsReference,
                                alternative.AlternativeIndex,
                                alternative.Multiplicity))
                        .ToArray();
                if (alternatives.Length <= 1)
                    return false;

                rootDimensions[slotIndex] =
                    new CrossRigidJointSelectionDimension(
                        key,
                        first.AnchorVmdPath,
                        first.ParentXmlPath,
                        slotIndex,
                        slotIndex,
                        null,
                        Array.Empty<CrossRigidVmdReferenceHop>(),
                        alternatives);
            }

            // The original occurrence descriptors are retained for matching.
            // Only the canonical context shapes are lifted to dimensions.
            var lifted = candidates.Select(candidate =>
                candidate.CommonAncestorDimensions.Length != 0
                    ? candidate
                    : candidate with
                    {
                        CommonAncestorDimensions = candidate.SlotIndices
                            .Select(index => rootDimensions[index])
                            .ToArray(),
                    }).ToArray();
            if (!TryBuildCrossRigidCanonicalConditionalDimensionUnion(
                    state,
                    lifted,
                    sourceVmdDocuments,
                    out var union) ||
                !candidates.All(candidate =>
                    IsCrossRigidJointDescriptorStructuralSuperset(
                        union, candidate)))
            {
                return false;
            }

            descriptor = union;
            return true;
        }

        private static bool IsCrossRigidIndependentRootDimension(
            CrossRigidJointSelectionDimension dimension,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
            int slotIndex)
            => dimension.SlotIndex == slotIndex &&
               dimension.CarrierSlotIndex == slotIndex &&
               dimension.ParentDimensionKey == null &&
               dimension.ReferenceChainFromAnchor.Length == 0 &&
               string.IsNullOrWhiteSpace(
                   dimension.LocalDimensionSlotRelativeXmlPath) &&
               Normalize(dimension.OwnerVmdPath).Equals(
                   Normalize(descriptor.AnchorVmdPath),
                   StringComparison.OrdinalIgnoreCase) &&
               dimension.ParentXmlPath.Equals(
                   descriptor.ParentXmlPath,
                   StringComparison.Ordinal);

        // Reconcile compatible, overlapping nested choice graphs at the
        // same parent. Every candidate describes a valid subset of the
        // source VMD's structural dependencies; combining their dimensions
        // must preserve the exact parent-child conditions, not flatten them
        // into independent optional appearances.
        private static bool
            TryBuildCrossRigidCanonicalConditionalDimensionUnion(
                BatchState state,
                IEnumerable<CrossRigidJointAlwaysPresentRewriteDescriptor>
                    candidateDescriptors,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            descriptor = null!;
            var candidates = candidateDescriptors.ToArray();
            if (candidates.Length < 2 ||
                candidates.Any(candidate =>
                    candidate.CommonAncestorDimensions.Length == 0))
            {
                return false;
            }

            var first = candidates[0];
            if (candidates.Skip(1).Any(candidate =>
                    !Normalize(candidate.AnchorVmdPath).Equals(
                        Normalize(first.AnchorVmdPath),
                        StringComparison.OrdinalIgnoreCase) ||
                    !candidate.ParentXmlPath.Equals(
                        first.ParentXmlPath,
                        StringComparison.Ordinal) ||
                    !BuildCrossRigidReferenceChainSignature(
                        candidate.AnchorReferenceChain).Equals(
                        BuildCrossRigidReferenceChainSignature(
                            first.AnchorReferenceChain),
                        StringComparison.Ordinal)))
            {
                return false;
            }

            var byDimensionKey =
                new Dictionary<string, CrossRigidJointSelectionDimension>(
                    StringComparer.Ordinal);
            foreach (var dimension in candidates.SelectMany(candidate =>
                         candidate.CommonAncestorDimensions))
            {
                if (byDimensionKey.TryGetValue(
                        dimension.DimensionKey, out var existing))
                {
                    if (!AreEquivalentCrossRigidJointDimensions(
                            existing, dimension))
                    {
                        return false;
                    }
                }
                else
                {
                    byDimensionKey.Add(dimension.DimensionKey, dimension);
                }
            }

            if (byDimensionKey.Values.Any(dimension =>
                    dimension.ParentDimensionKey != null &&
                    !byDimensionKey.ContainsKey(
                        dimension.ParentDimensionKey)))
            {
                return false;
            }

            var slotIndices = candidates
                .SelectMany(candidate => candidate.SlotIndices)
                .Distinct()
                .OrderBy(index => index)
                .ToArray();
            if (!TryGetCrossRigidSourceVmdDocument(
                    state,
                    first.AnchorVmdPath,
                    sourceVmdDocuments,
                    out var anchorDocument,
                    out _) ||
                anchorDocument.SelectSingleNode(
                    first.ParentXmlPath) is not XmlElement parentElement)
            {
                return false;
            }

            // Match the materializer's carrier-slot restrictions. A
            // probability-less-than-one carrier must be modeled as an
            // explicit direct optional dimension, otherwise cloning it
            // inside a probability-one wrapper would change activation.
            foreach (var slotIndex in slotIndices)
            {
                if (parentElement.SelectSingleNode(
                        $"SLOT[{slotIndex}]") is not XmlElement slot)
                {
                    return false;
                }

                if (ParseVmdSlotProbability(
                        slot.GetAttribute("probability")) >=
                    1.0 - AtlasValueGateExpectedDrawEpsilon)
                {
                    continue;
                }

                if (!IsSupportedCrossRigidOptionalJointSlot(slot) ||
                    !byDimensionKey.Values.Any(dimension =>
                        dimension.CarrierSlotIndex == slotIndex &&
                        dimension.SlotIndex == slotIndex &&
                        Normalize(dimension.OwnerVmdPath).Equals(
                            Normalize(first.AnchorVmdPath),
                            StringComparison.OrdinalIgnoreCase) &&
                        dimension.ParentXmlPath.Equals(
                            first.ParentXmlPath,
                            StringComparison.Ordinal) &&
                        dimension.ReferenceChainFromAnchor.Length == 0 &&
                        string.IsNullOrWhiteSpace(
                            dimension.LocalDimensionSlotRelativeXmlPath) &&
                        dimension.Alternatives.Any(alternative =>
                            alternative.AlternativeIndex == 0)))
                {
                    return false;
                }
            }

            var dimensions = byDimensionKey.Values
                .OrderBy(dimension =>
                    dimension.DimensionKey,
                    StringComparer.Ordinal)
                .ToArray();
            if (!TryEnumerateCrossRigidConditionalJointStates(
                    dimensions,
                    out var combinations,
                    out _))
            {
                return false;
            }

            long weightedStates = 0;
            foreach (var combination in combinations)
            {
                long multiplicity = 1;
                foreach (var alternative in combination)
                {
                    var factor = Math.Max(1, alternative.Multiplicity);
                    if (multiplicity >
                        MaxCrossRigidJointStateCombinations / factor)
                    {
                        return false;
                    }

                    multiplicity *= factor;
                }

                weightedStates += multiplicity;
                if (weightedStates >
                    MaxCrossRigidJointStateCombinations)
                {
                    return false;
                }
            }

            if (weightedStates <= 0)
                return false;

            var union = first with
            {
                SlotIndices = slotIndices,
                CombinationCount = (int)weightedStates,
                CommonAncestorDimensions = dimensions,
            };
            if (!candidates.All(candidate =>
                    IsCrossRigidJointDescriptorStructuralSuperset(
                        union,
                        candidate)))
            {
                return false;
            }

            descriptor = union;
            return true;
        }

        private static bool
            IsCrossRigidJointDescriptorStructuralSuperset(
                CrossRigidJointAlwaysPresentRewriteDescriptor candidate,
                CrossRigidJointAlwaysPresentRewriteDescriptor other)
        {
            if (!Normalize(candidate.AnchorVmdPath).Equals(
                    Normalize(other.AnchorVmdPath),
                    StringComparison.OrdinalIgnoreCase) ||
                !candidate.ParentXmlPath.Equals(
                    other.ParentXmlPath,
                    StringComparison.Ordinal) ||
                !BuildCrossRigidReferenceChainSignature(
                        candidate.AnchorReferenceChain)
                    .Equals(
                        BuildCrossRigidReferenceChainSignature(
                            other.AnchorReferenceChain),
                        StringComparison.Ordinal))
            {
                return false;
            }

            var candidateUsesDimensions =
                candidate.CommonAncestorDimensions.Length != 0;
            var otherUsesDimensions =
                other.CommonAncestorDimensions.Length != 0;
            if (candidateUsesDimensions != otherUsesDimensions)
            {
                // A direct context projects onto conditional states only
                // when every source selection is an independent root choice.
                if (!candidateUsesDimensions ||
                    other.SlotIndices.Any(slotIndex =>
                        !candidate.CommonAncestorDimensions.Any(dimension =>
                            IsCrossRigidIndependentRootDimension(
                                dimension, candidate, slotIndex))) ||
                    other.SourceSelections.Any(selection =>
                        !candidate.CommonAncestorDimensions.Any(dimension =>
                            dimension.DimensionKey.Equals(
                                BuildCrossRigidJointSourceSelectionDimensionKey(
                                    selection),
                                StringComparison.Ordinal) &&
                            IsCrossRigidIndependentRootDimension(
                                dimension, candidate, selection.SlotIndex))))
                {
                    return false;
                }
            }

            var candidateSlots =
                candidate.SlotIndices.ToHashSet();
            if (other.SlotIndices.Any(slotIndex =>
                    !candidateSlots.Contains(slotIndex)))
            {
                return false;
            }

            if (!candidateUsesDimensions)
                return true;

            var candidateDimensions =
                candidate.CommonAncestorDimensions.ToDictionary(
                    dimension => dimension.DimensionKey,
                    StringComparer.Ordinal);
            foreach (var otherDimension in
                     other.CommonAncestorDimensions)
            {
                if (!candidateDimensions.TryGetValue(
                        otherDimension.DimensionKey,
                        out var candidateDimension) ||
                    !AreEquivalentCrossRigidJointDimensions(
                        candidateDimension,
                        otherDimension))
                {
                    return false;
                }
            }

            return true;
        }

        private static bool AreEquivalentCrossRigidJointDimensions(
            CrossRigidJointSelectionDimension left,
            CrossRigidJointSelectionDimension right)
        {
            if (!Normalize(left.OwnerVmdPath).Equals(
                    Normalize(right.OwnerVmdPath),
                    StringComparison.OrdinalIgnoreCase) ||
                !left.ParentXmlPath.Equals(
                    right.ParentXmlPath,
                    StringComparison.Ordinal) ||
                left.SlotIndex != right.SlotIndex ||
                left.CarrierSlotIndex != right.CarrierSlotIndex ||
                !string.Equals(
                    left.ParentDimensionKey,
                    right.ParentDimensionKey,
                    StringComparison.Ordinal) ||
                left.ParentIsReference != right.ParentIsReference ||
                left.ParentAlternativeIndex != right.ParentAlternativeIndex ||
                !string.Equals(
                    left.LocalDimensionSlotRelativeXmlPath,
                    right.LocalDimensionSlotRelativeXmlPath,
                    StringComparison.Ordinal) ||
                !BuildCrossRigidReferenceChainSignature(
                        left.ReferenceChainFromAnchor)
                    .Equals(
                        BuildCrossRigidReferenceChainSignature(
                            right.ReferenceChainFromAnchor),
                        StringComparison.Ordinal))
            {
                return false;
            }

            var leftAlternatives =
                left.Alternatives
                    .OrderBy(alternative =>
                        alternative.IsReference)
                    .ThenBy(alternative =>
                        alternative.AlternativeIndex)
                    .ThenBy(alternative =>
                        alternative.Multiplicity)
                    .Select(alternative =>
                        $"{(alternative.IsReference ? "r" : "m")}:" +
                        $"{alternative.AlternativeIndex}:" +
                        $"{alternative.Multiplicity}")
                    .ToArray();
            var rightAlternatives =
                right.Alternatives
                    .OrderBy(alternative =>
                        alternative.IsReference)
                    .ThenBy(alternative =>
                        alternative.AlternativeIndex)
                    .ThenBy(alternative =>
                        alternative.Multiplicity)
                    .Select(alternative =>
                        $"{(alternative.IsReference ? "r" : "m")}:" +
                        $"{alternative.AlternativeIndex}:" +
                        $"{alternative.Multiplicity}")
                    .ToArray();
            return leftAlternatives.SequenceEqual(
                rightAlternatives,
                StringComparer.Ordinal);
        }

        private static CrossRigidJointAlwaysPresentRewriteDescriptor
            GetCrossRigidEffectiveJointDescriptor(
                BatchState state,
                string rootVmdPath,
                CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            var parentLocationKey =
                BuildCrossRigidJointParentLocationKey(
                    rootVmdPath,
                    descriptor);
            if (TryGetCrossRigidFactoredDescriptor(
                    state, parentLocationKey, descriptor,
                    out var factoredDescriptor))
                return factoredDescriptor;

            if (state.CrossRigidCanonicalJointDescriptorByParentLocation
                    .TryGetValue(
                        parentLocationKey,
                        out var canonicalDescriptor) &&
                IsCrossRigidJointDescriptorStructuralSuperset(
                    canonicalDescriptor,
                    descriptor))
            {
                return canonicalDescriptor;
            }

            return descriptor;
        }

        private static bool TryEnumerateCrossRigidConditionalJointStates(
            IReadOnlyList<CrossRigidJointSelectionDimension> dimensions,
            out CrossRigidJointDimensionAlternative[][] states,
            out string reason)
        {
            states = [];
            reason = string.Empty;

            // Resolve dependency parents before children, regardless of
            // chain depth. A missing parent or cycle is rejected rather than
            // ever enumerating a conditional child independently.
            var knownKeys = dimensions
                .Select(dimension => dimension.DimensionKey)
                .ToHashSet(StringComparer.Ordinal);
            var pending = dimensions
                .OrderBy(dimension => dimension.DimensionKey,
                    StringComparer.Ordinal)
                .ToList();
            var orderedDimensions =
                new List<CrossRigidJointSelectionDimension>();
            var resolvedKeys =
                new HashSet<string>(StringComparer.Ordinal);
            while (pending.Count != 0)
            {
                var nextIndex = pending.FindIndex(dimension =>
                    dimension.ParentDimensionKey == null ||
                    resolvedKeys.Contains(dimension.ParentDimensionKey));
                if (nextIndex < 0)
                {
                    reason =
                        "Conditional Cartesian dimension graph has an " +
                        "unresolved or cyclic parent";
                    return false;
                }

                var nextDimension = pending[nextIndex];
                pending.RemoveAt(nextIndex);
                orderedDimensions.Add(nextDimension);
                resolvedKeys.Add(nextDimension.DimensionKey);
            }

            var combinations =
                new List<CrossRigidJointDimensionAlternative[]>
                {
                    Array.Empty<CrossRigidJointDimensionAlternative>(),
                };
            foreach (var dimension in orderedDimensions)
            {
                if (dimension.ParentDimensionKey != null &&
                    !knownKeys.Contains(dimension.ParentDimensionKey))
                {
                    reason = "Conditional Cartesian dimension has no parent";
                    return false;
                }

                var expanded =
                    new List<CrossRigidJointDimensionAlternative[]>();
                foreach (var prefix in combinations)
                {
                    var active =
                        dimension.ParentDimensionKey == null ||
                        prefix.Any(alternative =>
                            alternative.DimensionKey.Equals(
                                dimension.ParentDimensionKey,
                                StringComparison.Ordinal) &&
                            alternative.IsReference ==
                                dimension.ParentIsReference &&
                            alternative.AlternativeIndex ==
                                dimension.ParentAlternativeIndex);
                    if (active)
                    {
                        foreach (var alternative in dimension.Alternatives)
                        {
                            expanded.Add(prefix.Append(alternative).ToArray());
                        }
                    }
                    else
                    {
                        // An inactive child has no appearance selection.
                        // Preserve the exact parent probability by folding
                        // the full child alternative weight into one
                        // synthetic state rather than multiplying variants
                        // that cannot exist under this parent selection.
                        expanded.Add(prefix.Append(
                            new CrossRigidJointDimensionAlternative(
                                dimension.DimensionKey,
                                false,
                                -1,
                                dimension.Alternatives.Sum(alternative =>
                                    alternative.Multiplicity))).ToArray());
                    }

                    if (expanded.Count >
                        MaxCrossRigidJointStateCombinations)
                    {
                        reason =
                            $"Conditional Cartesian state count exceeds " +
                            $"{MaxCrossRigidJointStateCombinations:N0}";
                        return false;
                    }
                }

                combinations = expanded;
            }

            states = combinations.ToArray();
            return true;
        }

        private static bool TryGetCrossRigidMatchingJointCombinations(
            BatchState state,
            CrossRigidJointAlwaysPresentRewriteDescriptor occurrenceDescriptor,
            CrossRigidJointAlwaysPresentRewriteDescriptor contextDescriptor,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointMatchingCombination[] matchingCombinations,
            out string reason)
        {
            matchingCombinations = [];
            reason = string.Empty;
            if (!IsCrossRigidJointDescriptorStructuralSuperset(
                    contextDescriptor,
                    occurrenceDescriptor))
            {
                reason =
                    "Canonical joint context is not a structural superset of the analyzed occurrence";
                return false;
            }

            if (contextDescriptor.CommonAncestorDimensions.Length == 0)
            {
                if (!TryGetCrossRigidSourceVmdDocument(
                        state,
                        contextDescriptor.AnchorVmdPath,
                        sourceVmdDocuments,
                        out var anchorDocument,
                        out reason) ||
                    anchorDocument.SelectSingleNode(
                        contextDescriptor.ParentXmlPath) is
                    not XmlElement parentElement)
                {
                    if (string.IsNullOrWhiteSpace(reason))
                    {
                        reason =
                            "Canonical joint parent could not be resolved";
                    }

                    return false;
                }

                var constraints =
                    new Dictionary<
                        int,
                        (bool IsReference, int AlternativeIndex)>();
                foreach (var selection in
                         occurrenceDescriptor.SourceSelections)
                {
                    if (!contextDescriptor.SlotIndices.Contains(
                            selection.SlotIndex))
                    {
                        continue;
                    }

                    var value =
                        (
                            selection.IsReference,
                            selection.AlternativeIndex);
                    if (constraints.TryGetValue(
                            selection.SlotIndex,
                            out var existing) &&
                        existing != value)
                    {
                        reason =
                            "Analyzed occurrence requires incompatible alternatives in one canonical joint slot";
                        return false;
                    }

                    constraints[selection.SlotIndex] =
                        value;
                }

                var combinations =
                    new List<CrossRigidJointAlternative[]>
                    {
                        Array.Empty<CrossRigidJointAlternative>(),
                    };
                foreach (var slotIndex in
                         contextDescriptor.SlotIndices)
                {
                    if (parentElement.SelectSingleNode(
                            $"SLOT[{slotIndex}]") is
                        not XmlElement slotElement)
                    {
                        reason =
                            $"Canonical joint source slot {slotIndex} could not be resolved";
                        return false;
                    }

                    var alternatives =
                        GetCrossRigidJointAlternatives(
                            slotElement,
                            slotIndex);
                    if (alternatives.Length <= 1)
                    {
                        reason =
                            $"Canonical joint source slot {slotIndex} no longer has alternatives";
                        return false;
                    }

                    var expanded =
                        new List<CrossRigidJointAlternative[]>();
                    foreach (var prefix in combinations)
                    {
                        foreach (var alternative in alternatives)
                        {
                            expanded.Add(
                                prefix
                                    .Append(alternative)
                                    .ToArray());
                            if (expanded.Count >
                                MaxCrossRigidJointStateCombinations)
                            {
                                reason =
                                    $"Canonical joint Cartesian product exceeds " +
                                    $"{MaxCrossRigidJointStateCombinations:N0} combinations";
                                return false;
                            }
                        }
                    }

                    combinations = expanded;
                }

                var weightedCombinationCount =
                    combinations.Sum(alternatives =>
                        GetCrossRigidJointCombinationMultiplicity(
                            alternatives));
                if (weightedCombinationCount !=
                    contextDescriptor.CombinationCount)
                {
                    reason =
                        "Canonical joint weighted Cartesian product changed since analysis";
                    return false;
                }

                matchingCombinations =
                    combinations
                        .Where(alternatives =>
                            constraints.All(constraint =>
                                alternatives.Any(alternative =>
                                    alternative.SlotIndex ==
                                        constraint.Key &&
                                    alternative.IsReference ==
                                        constraint.Value.IsReference &&
                                    alternative.AlternativeIndex ==
                                        constraint.Value.AlternativeIndex)))
                        .Select(alternatives =>
                            new CrossRigidJointMatchingCombination(
                                BuildCrossRigidJointCombinationKey(
                                    alternatives),
                                GetCrossRigidJointCombinationMultiplicity(
                                    alternatives)))
                        .GroupBy(
                            combination =>
                                combination.CombinationKey,
                            StringComparer.Ordinal)
                        .Select(group =>
                            new CrossRigidJointMatchingCombination(
                                group.Key,
                                group.Sum(item =>
                                    item.Multiplicity)))
                        .OrderBy(
                            combination =>
                                combination.CombinationKey,
                            StringComparer.Ordinal)
                        .ToArray();
            }
            else
            {
                var contextDimensionsByKey =
                    contextDescriptor.CommonAncestorDimensions
                        .ToDictionary(
                            dimension =>
                                dimension.DimensionKey,
                            StringComparer.Ordinal);
                var constraints =
                    new Dictionary<
                        string,
                        (bool IsReference, int AlternativeIndex)>(
                        StringComparer.Ordinal);
                foreach (var selection in
                         occurrenceDescriptor.SourceSelections)
                {
                    var dimensionKey =
                        BuildCrossRigidJointSourceSelectionDimensionKey(
                            selection);
                    if (!contextDimensionsByKey.ContainsKey(
                            dimensionKey))
                    {
                        continue;
                    }

                    var value =
                        (
                            selection.IsReference,
                            selection.AlternativeIndex);
                    if (constraints.TryGetValue(
                            dimensionKey,
                            out var existing) &&
                        existing != value)
                    {
                        reason =
                            "Analyzed occurrence requires incompatible alternatives in one canonical joint dimension";
                        return false;
                    }

                    constraints[dimensionKey] =
                        value;
                }

                if (!TryEnumerateCrossRigidConditionalJointStates(
                        contextDescriptor.CommonAncestorDimensions,
                        out var combinations,
                        out reason))
                {
                    return false;
                }

                var weightedCombinationCount =
                    combinations.Sum(alternatives =>
                        GetCrossRigidJointCombinationMultiplicity(
                            alternatives));
                if (weightedCombinationCount !=
                    contextDescriptor.CombinationCount)
                {
                    reason =
                        "Canonical common-ancestor weighted Cartesian product changed since analysis";
                    return false;
                }

                matchingCombinations =
                    combinations
                        .Where(alternatives =>
                            constraints.All(constraint =>
                                alternatives.Any(alternative =>
                                    alternative.DimensionKey.Equals(
                                        constraint.Key,
                                        StringComparison.Ordinal) &&
                                    alternative.IsReference ==
                                        constraint.Value.IsReference &&
                                    alternative.AlternativeIndex ==
                                        constraint.Value.AlternativeIndex)))
                        .Select(alternatives =>
                            new CrossRigidJointMatchingCombination(
                                BuildCrossRigidCommonAncestorCombinationKey(
                                    alternatives),
                                GetCrossRigidJointCombinationMultiplicity(
                                    alternatives)))
                        .GroupBy(
                            combination =>
                                combination.CombinationKey,
                            StringComparer.Ordinal)
                        .Select(group =>
                            new CrossRigidJointMatchingCombination(
                                group.Key,
                                group.Sum(item =>
                                    item.Multiplicity)))
                        .OrderBy(
                            combination =>
                                combination.CombinationKey,
                            StringComparer.Ordinal)
                        .ToArray();
            }

            if (matchingCombinations.Length == 0)
            {
                reason =
                    "Analyzed occurrence does not match any canonical Cartesian state";
                return false;
            }

            return true;
        }

        private static CrossRigidJointMatchingCombination[]
            FilterCrossRigidSelectedJointCombinations(
                IReadOnlyList<CrossRigidJointMatchingCombination>
                    matchingCombinations,
                IReadOnlySet<string>? selectedCombinationKeys)
        {
            if (selectedCombinationKeys == null)
                return matchingCombinations.ToArray();

            return matchingCombinations
                .Where(combination =>
                    selectedCombinationKeys.Contains(
                        combination.CombinationKey))
                .ToArray();
        }


        private static void SelectCrossRigidGeneratedPayloads(
            BatchState state)
        {
            state.CrossRigidPayloadSelectionEntries.Clear();
            state.CrossRigidSelectedPayloadIds.Clear();
            state.CrossRigidSelectedRewriteOccurrenceKeys.Clear();
            state.CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey.Clear();
            state.CrossRigidRewriteConflictReasonCounts.Clear();
            state.CrossRigidRewriteConflictExpectedDraws.Clear();
            state.CrossRigidRewriteConflictExamples.Clear();
            state.CrossRigidCanonicalJointDescriptorByParentLocation.Clear();
            state.CrossRigidCanonicalJointParentCount = 0;
            state.CrossRigidCanonicalJointContextsFolded = 0;
            state.CrossRigidCanonicalJointParentConflictCount = 0;
            state.CrossRigidPortfolioOrderingsEvaluated = 0;
            state.CrossRigidRawGreedyExpectedDraws = 0;
            state.CrossRigidBestPortfolioExpectedDraws = 0;
            state.CrossRigidPortfolioPairTrials = 0;
            state.CrossRigidPortfolioContextCohortTrials = 0;
            state.CrossRigidPortfolioLocalInsertionTrials = 0;
            state.CrossRigidPortfolioLocalInsertionImprovements = 0;
            state.CrossRigidSharedPayloadFallbackCandidatePlans = 0;
            state.CrossRigidSharedPayloadFallbackCompatibleStates = 0;
            state.CrossRigidSharedPayloadFallbackAcceptedStates = 0;
            state.CrossRigidSharedPayloadFallbackExpectedDraws = 0;
            state.CrossRigidSharedPayloadFallbackResidentBytes = 0;
            state.CrossRigidSharedPayloadFallbackBudgetRejections = 0;
            state.CrossRigidSharedPayloadFallbackAdmittedPlanIds.Clear();

            var plansByPayload =
                state.CrossRigidMergeAnalysisEntries
                    .GroupBy(
                        entry => entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToDictionary(
                        group => group.Key,
                        group => group.ToArray(),
                        StringComparer.Ordinal);

            // Supplemental pairwise plans may reuse geometry from an older
            // full-group payload. Scoring by the entire shared payload would
            // quietly introduce those pairs into the protected baseline.
            // Use only originally eligible *rewrite plans* for primary
            // benefit, VMD coverage and residency; full-payload analysis
            // remains available for diagnostics and fallback-only payloads.
            var primaryPlansByPayload = plansByPayload
                .ToDictionary(
                    group => group.Key,
                    group => group.Value
                        .Where(plan =>
                            !state.CrossRigidPreviouslySuppressedPairFallbackPlanIds
                                .Contains(plan.RewritePlanId))
                        .ToArray(),
                    StringComparer.Ordinal);

            var selectionCandidates =
                new List<CrossRigidPayloadSelectionEntry>();

            foreach (var payload in
                     state.CrossRigidGeneratedPayloadAnalysisEntries)
            {
                var primaryPlans =
                    primaryPlansByPayload[payload.GeneratedPayloadId];
                var isPrimary = primaryPlans.Length != 0;
                var relevantPlans = isPrimary
                    ? primaryPlans
                    : plansByPayload[payload.GeneratedPayloadId];
                var expectedDraws = relevantPlans.Sum(plan =>
                    plan.ExpectedArmyDrawCallsEliminated);
                var generatedGeometryBytes =
                    (double)payload.GeneratedGeometryBytes;
                var expectedResidentBytes = isPrimary
                    ? generatedGeometryBytes *
                      CalculateExpectedCrossRigidPayloadResidentProbability(
                          state,
                          primaryPlans)
                    : payload.ExpectedResidentGeneratedGeometryBytes;
                var relevantVmdCount = isPrimary
                    ? primaryPlans.Select(plan => plan.VmdPath)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .Count()
                    : payload.VmdCount;
                var physicalBytesPerExpectedDraw =
                    expectedDraws > AtlasValueGateExpectedDrawEpsilon
                        ? generatedGeometryBytes / expectedDraws
                        : double.PositiveInfinity;
                var residentBytesPerExpectedDraw =
                    expectedDraws > AtlasValueGateExpectedDrawEpsilon
                        ? expectedResidentBytes / expectedDraws
                        : double.PositiveInfinity;

                var decision =
                    CrossRigidPayloadSelectionDecision.Accept;
                if (expectedDraws <= AtlasValueGateExpectedDrawEpsilon)
                {
                    decision =
                        CrossRigidPayloadSelectionDecision
                            .ScenarioResolvedZeroBenefit;
                }
                else if (relevantVmdCount == 1 &&
                         expectedDraws <
                         MinimumCrossRigidSingleVmdExpectedArmyDraw)
                {
                    decision =
                        CrossRigidPayloadSelectionDecision
                            .SingleVmdBenefitTooSmall;
                }

                var maxRawDrawsSavedPerState =
                    payload.Lods
                        .Where(lod =>
                            lod.IsScenarioRepresentativeState)
                        .Select(lod =>
                            lod.DrawsSaved)
                        .DefaultIfEmpty(0)
                        .Max();
                var entry = new CrossRigidPayloadSelectionEntry(
                    payload.GeneratedPayloadId,
                    decision,
                    expectedDraws,
                    expectedDraws,
                    maxRawDrawsSavedPerState,
                    relevantPlans.Length,
                    relevantVmdCount,
                    payload.GeneratedGeometryBytes,
                    expectedResidentBytes,
                    physicalBytesPerExpectedDraw,
                    residentBytesPerExpectedDraw,
                    0);

                if (decision ==
                    CrossRigidPayloadSelectionDecision.Accept)
                {
                    selectionCandidates.Add(entry);
                }
                else
                {
                    state.CrossRigidPayloadSelectionEntries.Add(entry);
                }
            }

            var orderedCandidates =
                selectionCandidates
                    // Optimize the expected benefit of the competing rewrite
                    // portfolio, not the largest single rendered-state reduction.
                    // A large raw-draw merge may occupy the same Cartesian states
                    // as several cheaper, more valuable merges. Normalize physical
                    // and resident payload costs by their respective budgets before
                    // comparing the benefit of mutually competing payloads.
                    .OrderByDescending(entry =>
                        entry.ExpectedArmyDrawCallsEliminated /
                        Math.Max(
                            1.0,
                            Math.Max(
                                (double)entry.GeneratedGeometryBytes /
                                MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw,
                                entry.ExpectedResidentGeneratedGeometryBytes /
                                MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw)))
                    .ThenByDescending(entry =>
                        entry.ExpectedArmyDrawCallsEliminated)
                    .ThenBy(entry =>
                        Math.Max(
                            entry.ResidentBytesPerExpectedDraw /
                            MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw,
                            entry.PhysicalBytesPerExpectedDraw /
                            MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw))
                    .ThenByDescending(entry =>
                        entry.MaxRawDrawsSavedPerState)
                    .ThenByDescending(entry =>
                        entry.RewritePlanCount)
                    .ThenBy(
                        entry => entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .Select((entry, index) =>
                        entry with
                        {
                            SelectionRank = index + 1,
                        })
                    .ToList();

            var conflictProfileVmdDocuments =
                new Dictionary<string, XmlDocument>(
                    StringComparer.OrdinalIgnoreCase);
            BuildCrossRigidCanonicalJointContexts(
                state,
                conflictProfileVmdDocuments);
            var conflictProfiles =
                new Dictionary<
                    string,
                    CrossRigidPayloadRewriteConflictProfile>(
                    StringComparer.Ordinal);
            var selectedRewriteConflictKeys =
                new HashSet<string>(StringComparer.Ordinal);
            var selectedRewriteConflictOwnerByKey =
                new Dictionary<
                    string,
                    CrossRigidSelectedRewriteConflictOwner>(
                    StringComparer.Ordinal);
            var selectedJointContextKeyByParentLocation =
                new Dictionary<string, string>(
                    StringComparer.Ordinal);
            var selectedJointContextOwnerByParentLocation =
                new Dictionary<
                    string,
                    CrossRigidSelectedRewriteConflictOwner>(
                    StringComparer.Ordinal);

            // Compare whole portfolios before committing any rewrites. Each
            // candidate is replayed through the same exact-occurrence and
            // nested-context conflict rules used by the final writer.
            var portfolioSearchTimer = Stopwatch.StartNew();
            orderedCandidates =
                OptimizeCrossRigidPayloadCandidateOrdering(
                    state,
                    orderedCandidates,
                    conflictProfiles,
                    conflictProfileVmdDocuments);
            state.CrossRigidTimingDetails["Analyze: portfolio ordering search"] =
                portfolioSearchTimer.Elapsed;

            var acceptedGeneratedGeometryBytes = 0L;
            var acceptedExpectedResidentGeometryBytes = 0.0;
            var acceptedExpectedDraws = 0.0;
            var pendingCandidates =
                new List<CrossRigidPayloadSelectionEntry>(
                    orderedCandidates);
            var deferredBudgetDecisionByPayload =
                new Dictionary<
                    string,
                    CrossRigidPayloadSelectionDecision>(
                    StringComparer.Ordinal);
            var admittingSupplementaryPairs = false;

            while (pendingCandidates.Count != 0)
            {
                var acceptedThisPass = false;

                for (var candidateIndex = 0;
                     candidateIndex < pendingCandidates.Count;)
                {
                    var candidate =
                        pendingCandidates[candidateIndex];

                    // Retry all budget-deferred primary candidates before
                    // any supplementary pair can occupy their structural
                    // states. The fallback stage begins only after the
                    // protected primary portfolio stops making progress.
                    if (!admittingSupplementaryPairs &&
                        !state.CrossRigidLegacyEligiblePayloadIds.Contains(
                            candidate.GeneratedPayloadId))
                    {
                        candidateIndex++;
                        continue;
                    }

                    if (!conflictProfiles.TryGetValue(
                            candidate.GeneratedPayloadId,
                            out var conflictProfile))
                    {
                        if (!TryBuildCrossRigidPayloadRewriteConflictProfile(
                                state,
                                candidate.GeneratedPayloadId,
                                conflictProfileVmdDocuments,
                                !state.CrossRigidLegacyEligiblePayloadIds.Contains(
                                    candidate.GeneratedPayloadId),
                                out conflictProfile,
                                out var conflictBuildReason))
                        {
                            RecordCrossRigidRewriteConflict(
                                state,
                                "Conflict profile could not be built",
                                candidate,
                                string.IsNullOrWhiteSpace(
                                    conflictBuildReason)
                                    ? $"payload={candidate.GeneratedPayloadId}"
                                    : $"payload={candidate.GeneratedPayloadId}: " +
                                      conflictBuildReason);
                            state.CrossRigidPayloadSelectionEntries.Add(
                                candidate with
                                {
                                    Decision =
                                        CrossRigidPayloadSelectionDecision
                                            .RewriteOccurrenceConflict,
                                    MarginalExpectedArmyDrawCallsEliminated =
                                        0,
                                    PhysicalBytesPerExpectedDraw =
                                        double.PositiveInfinity,
                                    ResidentBytesPerExpectedDraw =
                                        double.PositiveInfinity,
                                });
                            pendingCandidates.RemoveAt(
                                candidateIndex);
                            deferredBudgetDecisionByPayload.Remove(
                                candidate.GeneratedPayloadId);
                            continue;
                        }

                        conflictProfiles[
                            candidate.GeneratedPayloadId] =
                            conflictProfile;
                    }

                    var compatibleOccurrences =
                        SelectCrossRigidCompatibleRewriteOccurrences(
                            conflictProfile,
                            selectedRewriteConflictKeys,
                            selectedJointContextKeyByParentLocation);
                    var marginalExpectedDraws =
                        compatibleOccurrences.Sum(occurrence =>
                            occurrence.ExpectedArmyDrawCallsEliminated);
                    var effectiveCandidate =
                        candidate with
                        {
                            MarginalExpectedArmyDrawCallsEliminated =
                                marginalExpectedDraws,
                            PhysicalBytesPerExpectedDraw =
                                marginalExpectedDraws >
                                AtlasValueGateExpectedDrawEpsilon
                                    ? candidate.GeneratedGeometryBytes /
                                      marginalExpectedDraws
                                    : double.PositiveInfinity,
                            ResidentBytesPerExpectedDraw =
                                marginalExpectedDraws >
                                AtlasValueGateExpectedDrawEpsilon
                                    ? candidate
                                          .ExpectedResidentGeneratedGeometryBytes /
                                      marginalExpectedDraws
                                    : double.PositiveInfinity,
                        };

                    if (marginalExpectedDraws <=
                        AtlasValueGateExpectedDrawEpsilon)
                    {
                        var (conflictReason, conflictDetail) =
                            ClassifyCrossRigidRewriteOccurrenceConflict(
                                conflictProfile,
                                selectedRewriteConflictKeys,
                                selectedRewriteConflictOwnerByKey,
                                selectedJointContextKeyByParentLocation,
                                selectedJointContextOwnerByParentLocation);
                        RecordCrossRigidRewriteConflict(
                            state,
                            conflictReason,
                            effectiveCandidate,
                            $"payload={candidate.GeneratedPayloadId}: " +
                            conflictDetail);
                        state.CrossRigidPayloadSelectionEntries.Add(
                            effectiveCandidate with
                            {
                                Decision =
                                    CrossRigidPayloadSelectionDecision
                                        .RewriteOccurrenceConflict,
                            });
                        pendingCandidates.RemoveAt(
                            candidateIndex);
                        deferredBudgetDecisionByPayload.Remove(
                            candidate.GeneratedPayloadId);
                        continue;
                    }

                    if (candidate.VmdCount == 1 &&
                        marginalExpectedDraws <
                        MinimumCrossRigidSingleVmdExpectedArmyDraw)
                    {
                        state.CrossRigidPayloadSelectionEntries.Add(
                            effectiveCandidate with
                            {
                                Decision =
                                    CrossRigidPayloadSelectionDecision
                                        .SingleVmdBenefitTooSmall,
                            });
                        pendingCandidates.RemoveAt(
                            candidateIndex);
                        deferredBudgetDecisionByPayload.Remove(
                            candidate.GeneratedPayloadId);
                        continue;
                    }

                    var projectedExpectedDraws =
                        acceptedExpectedDraws +
                        marginalExpectedDraws;
                    var projectedExpectedResidentGeometryBytes =
                        acceptedExpectedResidentGeometryBytes +
                        candidate.ExpectedResidentGeneratedGeometryBytes;
                    if (projectedExpectedResidentGeometryBytes >
                        projectedExpectedDraws *
                        MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw)
                    {
                        deferredBudgetDecisionByPayload[
                            candidate.GeneratedPayloadId] =
                            CrossRigidPayloadSelectionDecision
                                .ScenarioResidencyBudgetExceeded;
                        candidateIndex++;
                        continue;
                    }

                    var projectedGeneratedGeometryBytes =
                        acceptedGeneratedGeometryBytes +
                        candidate.GeneratedGeometryBytes;
                    if (projectedGeneratedGeometryBytes >
                        projectedExpectedDraws *
                        MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw)
                    {
                        deferredBudgetDecisionByPayload[
                            candidate.GeneratedPayloadId] =
                            CrossRigidPayloadSelectionDecision
                                .PhysicalPerDrawBudgetExceeded;
                        candidateIndex++;
                        continue;
                    }

                    if (projectedGeneratedGeometryBytes >
                        MaxCrossRigidGeneratedGeometryGrowthBytes)
                    {
                        state.CrossRigidPayloadSelectionEntries.Add(
                            effectiveCandidate with
                            {
                                Decision =
                                    CrossRigidPayloadSelectionDecision
                                        .GlobalGrowthCapExceeded,
                            });
                        pendingCandidates.RemoveAt(
                            candidateIndex);
                        deferredBudgetDecisionByPayload.Remove(
                            candidate.GeneratedPayloadId);
                        continue;
                    }

                    acceptedGeneratedGeometryBytes =
                        projectedGeneratedGeometryBytes;
                    acceptedExpectedResidentGeometryBytes =
                        projectedExpectedResidentGeometryBytes;
                    acceptedExpectedDraws =
                        projectedExpectedDraws;

                    foreach (var occurrence in
                             compatibleOccurrences)
                    {
                        var conflictOwner =
                            new CrossRigidSelectedRewriteConflictOwner(
                                candidate.GeneratedPayloadId,
                                occurrence.SelectionKey,
                                occurrence.ExpectedArmyDrawCallsEliminated,
                                candidate.MaxRawDrawsSavedPerState,
                                candidate.GeneratedGeometryBytes,
                                candidate.SelectionRank);
                        foreach (var rewriteConflictKey in
                                 occurrence.RewriteConflictKeys)
                        {
                            selectedRewriteConflictKeys.Add(
                                rewriteConflictKey);
                            selectedRewriteConflictOwnerByKey.TryAdd(
                                rewriteConflictKey,
                                conflictOwner);
                        }

                        foreach (var pair in
                                 occurrence
                                     .JointContextKeyByParentLocation)
                        {
                            selectedJointContextKeyByParentLocation[
                                pair.Key] =
                                pair.Value;
                            selectedJointContextOwnerByParentLocation[
                                pair.Key] =
                                conflictOwner;
                        }

                        state.CrossRigidSelectedRewriteOccurrenceKeys.Add(
                            occurrence.RewriteOccurrenceKey);
                        if (!string.IsNullOrWhiteSpace(
                                occurrence.JointCombinationKey))
                        {
                            if (!state
                                    .CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey
                                    .TryGetValue(
                                        occurrence.RewriteOccurrenceKey,
                                        out var selectedCombinationKeys))
                            {
                                selectedCombinationKeys =
                                    new HashSet<string>(
                                        StringComparer.Ordinal);
                                state
                                    .CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey[
                                        occurrence.RewriteOccurrenceKey] =
                                    selectedCombinationKeys;
                            }

                            selectedCombinationKeys.Add(
                                occurrence.JointCombinationKey);
                        }
                    }

                    state.CrossRigidSelectedPayloadIds.Add(
                        candidate.GeneratedPayloadId);
                    state.CrossRigidPayloadSelectionEntries.Add(
                        effectiveCandidate with
                        {
                            Decision =
                                CrossRigidPayloadSelectionDecision.Accept,
                        });
                    pendingCandidates.RemoveAt(
                        candidateIndex);
                    deferredBudgetDecisionByPayload.Remove(
                        candidate.GeneratedPayloadId);
                    acceptedThisPass = true;
                }

                if (!acceptedThisPass)
                {
                    if (!admittingSupplementaryPairs)
                    {
                        admittingSupplementaryPairs = true;
                        continue;
                    }

                    break;
                }
            }

            foreach (var candidate in pendingCandidates)
            {
                var marginalExpectedDraws =
                    conflictProfiles.TryGetValue(
                        candidate.GeneratedPayloadId,
                        out var conflictProfile)
                        ? SelectCrossRigidCompatibleRewriteOccurrences(
                                conflictProfile,
                                selectedRewriteConflictKeys,
                                selectedJointContextKeyByParentLocation)
                            .Sum(occurrence =>
                                occurrence.ExpectedArmyDrawCallsEliminated)
                        : candidate
                            .MarginalExpectedArmyDrawCallsEliminated;
                state.CrossRigidPayloadSelectionEntries.Add(
                    candidate with
                    {
                        Decision =
                            deferredBudgetDecisionByPayload.GetValueOrDefault(
                                candidate.GeneratedPayloadId,
                                CrossRigidPayloadSelectionDecision
                                    .ScenarioResidencyBudgetExceeded),
                        MarginalExpectedArmyDrawCallsEliminated =
                            marginalExpectedDraws,
                        PhysicalBytesPerExpectedDraw =
                            marginalExpectedDraws >
                            AtlasValueGateExpectedDrawEpsilon
                                ? candidate.GeneratedGeometryBytes /
                                  marginalExpectedDraws
                                : double.PositiveInfinity,
                        ResidentBytesPerExpectedDraw =
                            marginalExpectedDraws >
                            AtlasValueGateExpectedDrawEpsilon
                                ? candidate
                                      .ExpectedResidentGeneratedGeometryBytes /
                                  marginalExpectedDraws
                                : double.PositiveInfinity,
                    });
            }

            // Reuse selected primary geometry only after both primary and
            // normal fallback-only payload portfolios have been finalized.
            AdmitCrossRigidSharedPayloadFallbacks(
                state,
                primaryPlansByPayload,
                plansByPayload,
                selectedRewriteConflictKeys,
                selectedRewriteConflictOwnerByKey,
                selectedJointContextKeyByParentLocation,
                selectedJointContextOwnerByParentLocation,
                conflictProfileVmdDocuments,
                ref acceptedExpectedDraws,
                ref acceptedExpectedResidentGeometryBytes);
        }

        private static void AdmitCrossRigidSharedPayloadFallbacks(
            BatchState state,
            IReadOnlyDictionary<string, CrossRigidMergeAnalysisEntry[]>
                primaryPlansByPayload,
            IReadOnlyDictionary<string, CrossRigidMergeAnalysisEntry[]>
                plansByPayload,
            HashSet<string> selectedRewriteConflictKeys,
            Dictionary<string, CrossRigidSelectedRewriteConflictOwner>
                selectedRewriteConflictOwnerByKey,
            Dictionary<string, string>
                selectedJointContextKeyByParentLocation,
            Dictionary<string, CrossRigidSelectedRewriteConflictOwner>
                selectedJointContextOwnerByParentLocation,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            ref double acceptedExpectedDraws,
            ref double acceptedExpectedResidentGeometryBytes)
        {
            // A payload with no accepted primary still has to pay for its
            // geometry through the existing fallback-only selection stage.
            // This pass never adds a new payload or evicts a selected rewrite.
            var selectedPrimaryPayloads =
                state.CrossRigidPayloadSelectionEntries
                    .Where(entry =>
                        entry.Accepted &&
                        state.CrossRigidLegacyEligiblePayloadIds.Contains(
                            entry.GeneratedPayloadId))
                    .OrderBy(entry => entry.SelectionRank)
                    .ToArray();

            foreach (var primary in selectedPrimaryPayloads)
            {
                var payloadId = primary.GeneratedPayloadId;
                var fallbackPlans = plansByPayload[payloadId]
                    .Where(plan =>
                        state.CrossRigidPreviouslySuppressedPairFallbackPlanIds
                            .Contains(plan.RewritePlanId))
                    .ToArray();
                if (fallbackPlans.Length == 0)
                    continue;

                state.CrossRigidSharedPayloadFallbackCandidatePlans +=
                    fallbackPlans.Length;
                if (!TryBuildCrossRigidPayloadRewriteConflictProfile(
                        state,
                        payloadId,
                        sourceVmdDocuments,
                        true,
                        out var fallbackProfile,
                        out var profileReason,
                        onlySupplementaryPairFallbackPlans: true))
                {
                    RecordCrossRigidAnalysisDiagnostic(
                        state,
                        "Shared-payload fallback profile unavailable",
                        $"payload={payloadId}: {profileReason}");
                    continue;
                }

                // Exact occurrences, structural slots, and canonical joint
                // contexts must all remain compatible with existing winners.
                var compatible = SelectCrossRigidCompatibleRewriteOccurrences(
                    fallbackProfile,
                    selectedRewriteConflictKeys,
                    selectedJointContextKeyByParentLocation);
                state.CrossRigidSharedPayloadFallbackCompatibleStates +=
                    compatible.Length;
                var marginalDraws = compatible.Sum(occurrence =>
                    occurrence.ExpectedArmyDrawCallsEliminated);
                if (marginalDraws <= AtlasValueGateExpectedDrawEpsilon)
                    continue;

                var selectedOccurrenceKeys = compatible
                    .Select(occurrence => occurrence.RewriteOccurrenceKey)
                    .ToHashSet(StringComparer.Ordinal);
                var admittedPlans = fallbackPlans
                    .Where(plan =>
                        plan.RewriteOccurrenceSets.Any(set =>
                            selectedOccurrenceKeys.Contains(
                                BuildCrossRigidSelectedRewriteOccurrenceKey(
                                    plan, set))))
                    .ToArray();
                if (admittedPlans.Length == 0)
                    continue;

                // Generated physical bytes were paid by the primary. Reaching
                // more units can still make that geometry resident more often;
                // charge the conservative upper-bound residency increment.
                var primaryPlans = primaryPlansByPayload[payloadId];
                var primaryResidency =
                    CalculateExpectedCrossRigidPayloadResidentProbability(
                        state, primaryPlans);
                var expandedResidency =
                    CalculateExpectedCrossRigidPayloadResidentProbability(
                        state,
                        primaryPlans.Concat(admittedPlans).ToArray());
                var incrementalResidentBytes =
                    primary.GeneratedGeometryBytes *
                    Math.Max(0.0, expandedResidency - primaryResidency);
                var projectedDraws = acceptedExpectedDraws + marginalDraws;
                if (acceptedExpectedResidentGeometryBytes +
                        incrementalResidentBytes >
                    projectedDraws *
                    MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw)
                {
                    state.CrossRigidSharedPayloadFallbackBudgetRejections++;
                    continue;
                }

                // Commit the same selection keys the writer and original
                // portfolio use. A joint rewrite may accept only a subset of
                // its Cartesian states, so retain those combination keys.
                foreach (var occurrence in compatible)
                {
                    var owner = new CrossRigidSelectedRewriteConflictOwner(
                        payloadId,
                        occurrence.SelectionKey,
                        occurrence.ExpectedArmyDrawCallsEliminated,
                        primary.MaxRawDrawsSavedPerState,
                        primary.GeneratedGeometryBytes,
                        primary.SelectionRank);
                    foreach (var key in occurrence.RewriteConflictKeys)
                    {
                        selectedRewriteConflictKeys.Add(key);
                        selectedRewriteConflictOwnerByKey.TryAdd(key, owner);
                    }

                    foreach (var context in
                             occurrence.JointContextKeyByParentLocation)
                    {
                        selectedJointContextKeyByParentLocation[context.Key] =
                            context.Value;
                        selectedJointContextOwnerByParentLocation[context.Key] =
                            owner;
                    }

                    state.CrossRigidSelectedRewriteOccurrenceKeys.Add(
                        occurrence.RewriteOccurrenceKey);
                    if (string.IsNullOrWhiteSpace(
                            occurrence.JointCombinationKey))
                    {
                        continue;
                    }

                    if (!state
                            .CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey
                            .TryGetValue(
                                occurrence.RewriteOccurrenceKey,
                                out var combinationKeys))
                    {
                        combinationKeys =
                            new HashSet<string>(StringComparer.Ordinal);
                        state
                            .CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey[
                                occurrence.RewriteOccurrenceKey] =
                            combinationKeys;
                    }

                    combinationKeys.Add(occurrence.JointCombinationKey);
                }

                acceptedExpectedDraws = projectedDraws;
                acceptedExpectedResidentGeometryBytes +=
                    incrementalResidentBytes;
                state.CrossRigidSharedPayloadFallbackAcceptedStates +=
                    compatible.Length;
                state.CrossRigidSharedPayloadFallbackExpectedDraws +=
                    marginalDraws;
                state.CrossRigidSharedPayloadFallbackResidentBytes +=
                    incrementalResidentBytes;
                foreach (var plan in admittedPlans)
                {
                    state.CrossRigidSharedPayloadFallbackAdmittedPlanIds.Add(
                        plan.RewritePlanId);
                }

                // Update the accepted payload's accounting, not the physical
                // payload count. Small one-VMD additions do not need to meet
                // the standalone minimum when geometry is already selected.
                var updatedMarginal =
                    primary.MarginalExpectedArmyDrawCallsEliminated +
                    marginalDraws;
                var updatedResident =
                    primary.ExpectedResidentGeneratedGeometryBytes +
                    incrementalResidentBytes;
                var acceptedIndex =
                    state.CrossRigidPayloadSelectionEntries.FindIndex(
                        entry =>
                            entry.Accepted &&
                            entry.GeneratedPayloadId.Equals(
                                payloadId, StringComparison.Ordinal));
                state.CrossRigidPayloadSelectionEntries[acceptedIndex] =
                    primary with
                    {
                        ExpectedArmyDrawCallsEliminated =
                            primary.ExpectedArmyDrawCallsEliminated +
                            marginalDraws,
                        MarginalExpectedArmyDrawCallsEliminated =
                            updatedMarginal,
                        RewritePlanCount =
                            primary.RewritePlanCount + admittedPlans.Length,
                        VmdCount = primaryPlans.Concat(admittedPlans)
                            .Select(plan => plan.VmdPath)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Count(),
                        ExpectedResidentGeneratedGeometryBytes =
                            updatedResident,
                        PhysicalBytesPerExpectedDraw =
                            primary.GeneratedGeometryBytes / updatedMarginal,
                        ResidentBytesPerExpectedDraw =
                            updatedResident / updatedMarginal,
                    };
            }
        }

        private static List<CrossRigidPayloadSelectionEntry>
            OptimizeCrossRigidPayloadCandidateOrdering(
                BatchState state,
                IReadOnlyList<CrossRigidPayloadSelectionEntry> candidates,
                Dictionary<string, CrossRigidPayloadRewriteConflictProfile>
                    conflictProfiles,
                Dictionary<string, XmlDocument> sourceVmdDocuments)
        {
            // Keep the original full-group portfolio intact before
            // evaluating newly admitted pairs as supplementary rewrites.
            // A small pair's high scenario benefit must not displace many
            // otherwise writable full-group states just by changing order.
            var primaryCandidates = candidates
                .Where(entry =>
                    state.CrossRigidLegacyEligiblePayloadIds.Contains(
                        entry.GeneratedPayloadId))
                .ToArray();
            var fallbackOnlyCandidates = candidates
                .Where(entry =>
                    !state.CrossRigidLegacyEligiblePayloadIds.Contains(
                        entry.GeneratedPayloadId))
                .OrderByDescending(entry =>
                    entry.ExpectedArmyDrawCallsEliminated)
                .ThenBy(entry =>
                    entry.GeneratedPayloadId,
                    StringComparer.Ordinal)
                .ToArray();

            // A generated payload shared with any legacy rewrite remains
            // in the primary portfolio, so its geometry is charged once.
            var rawDrawOrder =
                primaryCandidates
                    .OrderByDescending(entry =>
                        entry.MaxRawDrawsSavedPerState)
                    .ThenBy(entry =>
                        Math.Max(
                            entry.ResidentBytesPerExpectedDraw /
                            MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw,
                            entry.PhysicalBytesPerExpectedDraw /
                            MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw))
                    .ThenBy(entry =>
                        entry.ResidentBytesPerExpectedDraw /
                        MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw +
                        entry.PhysicalBytesPerExpectedDraw /
                        MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw)
                    .ThenByDescending(entry =>
                        entry.RewritePlanCount)
                    .ThenByDescending(entry =>
                        entry.ExpectedArmyDrawCallsEliminated)
                    .ThenBy(entry =>
                        entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToArray();
            var scenarioBenefitOrder =
                primaryCandidates
                    .OrderByDescending(entry =>
                        entry.ExpectedArmyDrawCallsEliminated)
                    .ThenBy(entry =>
                        Math.Max(
                            entry.ResidentBytesPerExpectedDraw /
                            MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw,
                            entry.PhysicalBytesPerExpectedDraw /
                            MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw))
                    .ThenBy(entry =>
                        entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToArray();

            var invalidProfiles =
                new HashSet<string>(StringComparer.Ordinal);
            var bestOrder = rawDrawOrder;
            var best =
                EvaluateCrossRigidPayloadPortfolio(
                    state,
                    bestOrder,
                    conflictProfiles,
                    invalidProfiles,
                    sourceVmdDocuments);
            var evaluated = 1;
            state.CrossRigidRawGreedyExpectedDraws =
                best.ExpectedDraws;

            foreach (var alternative in
                     new IReadOnlyList<CrossRigidPayloadSelectionEntry>[]
                     {
                         primaryCandidates,
                         scenarioBenefitOrder,
                     })
            {
                var trial =
                    EvaluateCrossRigidPayloadPortfolio(
                        state,
                        alternative,
                        conflictProfiles,
                        invalidProfiles,
                        sourceVmdDocuments);
                evaluated++;
                if (IsBetterCrossRigidPayloadPortfolio(
                        trial,
                        best))
                {
                    best = trial;
                    bestOrder = alternative.ToArray();
                }
            }

            // A rejected payload may replace several overlapping winners.
            // Preserve the best global contenders but include representative
            // alternatives from other VMD roots. Otherwise the seed budget
            // tends to be monopolized by one large Cartesian family.
            const int maxGlobalSeeds = 16;
            const int maxDiverseSeeds = 8;
            var primaryVmdByPayload =
                state.CrossRigidMergeAnalysisEntries
                    .GroupBy(
                        entry => entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToDictionary(
                        group => group.Key,
                        group => group.First().VmdPath,
                        StringComparer.Ordinal);
            var rejectedCandidates =
                primaryCandidates
                    .Where(entry =>
                        !best.SelectedPayloadIds.Contains(
                            entry.GeneratedPayloadId))
                    .OrderByDescending(entry =>
                        entry.ExpectedArmyDrawCallsEliminated)
                    .ThenBy(entry =>
                        entry.PhysicalBytesPerExpectedDraw)
                    .ThenBy(entry =>
                        entry.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToArray();
            var globalSeeds =
                rejectedCandidates
                    .Take(maxGlobalSeeds)
                    .ToArray();
            var globalSeedIds =
                globalSeeds
                    .Select(entry =>
                        entry.GeneratedPayloadId)
                    .ToHashSet(StringComparer.Ordinal);
            var diverseSeeds =
                rejectedCandidates
                    .GroupBy(
                        entry =>
                            primaryVmdByPayload.TryGetValue(
                                entry.GeneratedPayloadId,
                                out var vmdPath)
                                ? vmdPath
                                : entry.GeneratedPayloadId,
                        StringComparer.OrdinalIgnoreCase)
                    .Select(group => group.First())
                    .Where(entry =>
                        !globalSeedIds.Contains(
                            entry.GeneratedPayloadId))
                    .Take(maxDiverseSeeds)
                    .ToArray();
            // A VMD can contain several mutually incompatible joint
            // Cartesian contexts. Sampling only globally expensive payloads
            // and one rejected payload per VMD misses alternatives from a
            // *different structural parent or slot set* in the same VMD.
            // Sample those contexts independently, but always evaluate each
            // ordering against the exact same occurrence conflicts and
            // selected-portfolio geometry/residency budgets.
            var contextSeedObservations =
                new List<(
                    string ParentLocation,
                    string ContextKey,
                    CrossRigidPayloadSelectionEntry Candidate)>();
            foreach (var candidate in rejectedCandidates)
            {
                if (!conflictProfiles.TryGetValue(
                        candidate.GeneratedPayloadId,
                        out var profile))
                {
                    if (!TryBuildCrossRigidPayloadRewriteConflictProfile(
                            state,
                            candidate.GeneratedPayloadId,
                            sourceVmdDocuments,
                            !state.CrossRigidLegacyEligiblePayloadIds.Contains(
                                candidate.GeneratedPayloadId),
                            out profile,
                            out _))
                    {
                        invalidProfiles.Add(candidate.GeneratedPayloadId);
                        continue;
                    }

                    conflictProfiles[candidate.GeneratedPayloadId] =
                        profile;
                }

                foreach (var context in
                         profile.Occurrences
                             .SelectMany(occurrence =>
                                 occurrence.JointContextKeyByParentLocation)
                             .GroupBy(pair =>
                                 pair.Key + "\u001f" + pair.Value,
                                 StringComparer.Ordinal)
                             .Select(group => group.First()))
                {
                    contextSeedObservations.Add(
                        (context.Key, context.Value, candidate));
                }
            }

            // Prefer breadth across distinct parents, then a second
            // competing context under each parent. This specifically
            // exposes slot-set choices such as the independent optional
            // alternatives in teb_roc_estragon that global benefit
            // ranking alone may never try.
            var contextOptionsByParent =
                contextSeedObservations
                    .GroupBy(
                        observation => observation.ParentLocation,
                        StringComparer.Ordinal)
                    .Select(parentGroup =>
                        parentGroup
                            .GroupBy(
                                observation => observation.ContextKey,
                                StringComparer.Ordinal)
                            .Select(contextGroup =>
                                contextGroup
                                    .OrderByDescending(observation =>
                                        observation.Candidate
                                            .ExpectedArmyDrawCallsEliminated)
                                    .ThenBy(observation =>
                                        observation.Candidate.GeneratedPayloadId,
                                        StringComparer.Ordinal)
                                    .First()
                                    .Candidate)
                            .OrderByDescending(candidate =>
                                candidate.ExpectedArmyDrawCallsEliminated)
                            .ThenBy(candidate =>
                                candidate.GeneratedPayloadId,
                                StringComparer.Ordinal)
                            .ToArray())
                    .OrderByDescending(options =>
                        options[0].ExpectedArmyDrawCallsEliminated)
                    .ThenBy(options =>
                        options[0].GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ToArray();
            const int maxContextSeeds = 24;
            var contextSeedIds =
                globalSeeds.Concat(diverseSeeds)
                    .Select(candidate => candidate.GeneratedPayloadId)
                    .ToHashSet(StringComparer.Ordinal);
            var contextSeeds =
                contextOptionsByParent
                    .Select(options => options[0])
                    .Concat(contextOptionsByParent
                        .Where(options => options.Length > 1)
                        .Select(options => options[1]))
                    .Where(candidate =>
                        contextSeedIds.Add(candidate.GeneratedPayloadId))
                    .Take(maxContextSeeds)
                    .ToArray();
            var alternativeSeeds =
                globalSeeds.Concat(diverseSeeds).Concat(contextSeeds)
                    .ToArray();

            foreach (var seed in alternativeSeeds)
            {
                var trialOrder =
                    new[] { seed }
                        .Concat(bestOrder.Where(entry =>
                            !entry.GeneratedPayloadId.Equals(
                                seed.GeneratedPayloadId,
                                StringComparison.Ordinal)))
                        .ToArray();
                var trial =
                    EvaluateCrossRigidPayloadPortfolio(
                        state,
                        trialOrder,
                        conflictProfiles,
                        invalidProfiles,
                        sourceVmdDocuments);
                evaluated++;
                if (IsBetterCrossRigidPayloadPortfolio(
                        trial,
                        best))
                {
                    best = trial;
                    bestOrder = trialOrder;
                }
            }

            // A competing Cartesian context can require several payloads
            // to replace existing joint-state owners. Promoting one or two
            // candidates cannot expose their combined benefit. Evaluate
            // bounded cohorts sharing an exact parent/context; the existing
            // occurrence conflicts and portfolio budgets still gate each
            // candidate in the ordinary replay.
            var contextCohorts =
                contextSeedObservations
                    .GroupBy(
                        item => item.ParentLocation + "\u001e" +
                                item.ContextKey,
                        StringComparer.Ordinal)
                    .Select(group => new
                    {
                        group.First().ParentLocation,
                        group.First().ContextKey,
                        Candidates = group
                            .Select(item => item.Candidate)
                            .GroupBy(item => item.GeneratedPayloadId,
                                StringComparer.Ordinal)
                            .Select(items => items.First())
                            .OrderByDescending(item =>
                                item.ExpectedArmyDrawCallsEliminated)
                            .ThenBy(item => item.GeneratedPayloadId,
                                StringComparer.Ordinal)
                            .Take(16)
                            .ToArray(),
                    })
                    .Where(cohort => cohort.Candidates.Length >= 2)
                    .OrderByDescending(cohort =>
                        cohort.Candidates.Sum(item =>
                            item.ExpectedArmyDrawCallsEliminated))
                    .ThenBy(cohort => cohort.ParentLocation,
                        StringComparer.Ordinal)
                    .ThenBy(cohort => cohort.ContextKey,
                        StringComparer.Ordinal)
                    .ToArray();
            // Reserve trials for distinct structural parents as well as
            // globally strong cohorts, rather than letting one VMD family
            // consume the entire bounded search budget.
            var cohortsToEvaluate =
                contextCohorts.Take(8)
                    .Concat(contextCohorts
                        .GroupBy(cohort => cohort.ParentLocation,
                            StringComparer.Ordinal)
                        .Select(group => group.First()))
                    .GroupBy(
                        cohort => cohort.ParentLocation + "\u001e" +
                                  cohort.ContextKey,
                        StringComparer.Ordinal)
                    .Select(group => group.First())
                    .Take(16)
                    .ToArray();
            foreach (var cohort in cohortsToEvaluate)
            {
                var promotedIds =
                    cohort.Candidates
                        .Select(entry => entry.GeneratedPayloadId)
                        .ToHashSet(StringComparer.Ordinal);
                var trialOrder =
                    cohort.Candidates
                        .Concat(bestOrder.Where(entry =>
                            !promotedIds.Contains(
                                entry.GeneratedPayloadId)))
                        .ToArray();
                var trial =
                    EvaluateCrossRigidPayloadPortfolio(
                        state,
                        trialOrder,
                        conflictProfiles,
                        invalidProfiles,
                        sourceVmdDocuments);
                evaluated++;
                if (IsBetterCrossRigidPayloadPortfolio(trial, best))
                {
                    best = trial;
                    bestOrder = trialOrder;
                }
            }

            state.CrossRigidPortfolioContextCohortTrials =
                cohortsToEvaluate.Length;

            // One-for-many substitutions are not sufficient when two cheaper
            // payloads jointly replace a large merge. Search a bounded number
            // of pairs within the same visual root and across roots. Each
            // ordering is replayed from scratch with exact Cartesian-state
            // occurrence conflicts, nested-path compatibility, and both
            // selected-portfolio budgets. Never bypass the writer's safety
            // rules or accept an ordering worse than the raw-draw baseline.
            var pairSeeds =
                alternativeSeeds
                    .Where(entry =>
                        !best.SelectedPayloadIds.Contains(
                            entry.GeneratedPayloadId))
                    .ToArray();
            var pairOptions =
                pairSeeds
                    .SelectMany((first, index) =>
                        pairSeeds.Skip(index + 1).Select(second =>
                            new
                            {
                                First = first,
                                Second = second,
                                SameRoot =
                                    primaryVmdByPayload.TryGetValue(
                                        first.GeneratedPayloadId,
                                        out var firstVmd) &&
                                    primaryVmdByPayload.TryGetValue(
                                        second.GeneratedPayloadId,
                                        out var secondVmd) &&
                                    firstVmd.Equals(
                                        secondVmd,
                                        StringComparison.OrdinalIgnoreCase),
                                CombinedBenefit =
                                    first.ExpectedArmyDrawCallsEliminated +
                                    second.ExpectedArmyDrawCallsEliminated,
                            }))
                    .ToArray();
            const int maxSameRootPairs = 16;
            const int maxCrossRootPairs = 8;
            var pairsToEvaluate =
                pairOptions
                    .Where(pair => pair.SameRoot)
                    .OrderByDescending(pair =>
                        pair.CombinedBenefit)
                    .ThenBy(pair =>
                        pair.First.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .ThenBy(pair =>
                        pair.Second.GeneratedPayloadId,
                        StringComparer.Ordinal)
                    .Take(maxSameRootPairs)
                    .Concat(
                        pairOptions
                            .Where(pair => !pair.SameRoot)
                            .OrderByDescending(pair =>
                                pair.CombinedBenefit)
                            .ThenBy(pair =>
                                pair.First.GeneratedPayloadId,
                                StringComparer.Ordinal)
                            .ThenBy(pair =>
                                pair.Second.GeneratedPayloadId,
                                StringComparer.Ordinal)
                            .Take(maxCrossRootPairs))
                    .ToArray();
            foreach (var pair in pairsToEvaluate)
            {
                // The first candidate may block some of the second's
                // concrete Cartesian states, so try both precedences.
                foreach (var front in
                         new[]
                         {
                             new[] { pair.First, pair.Second },
                             new[] { pair.Second, pair.First },
                         })
                {
                    var frontIds =
                        front
                            .Select(entry => entry.GeneratedPayloadId)
                            .ToHashSet(StringComparer.Ordinal);
                    var trialOrder =
                        front
                            .Concat(bestOrder.Where(entry =>
                                !frontIds.Contains(
                                    entry.GeneratedPayloadId)))
                            .ToArray();
                    var trial =
                        EvaluateCrossRigidPayloadPortfolio(
                            state,
                            trialOrder,
                            conflictProfiles,
                            invalidProfiles,
                            sourceVmdDocuments);
                    evaluated++;
                    if (IsBetterCrossRigidPayloadPortfolio(
                            trial,
                            best))
                    {
                        best = trial;
                        bestOrder = trialOrder;
                    }
                }
            }

            // Promoting a candidate to the front can displace unrelated
            // winners before reaching its actual conflicting occurrence.
            // Try bounded insertions before the first selected conflicting
            // owners. The complete portfolio replay remains authoritative.
            // Each category gets its own allowance. Appending contextSeeds
            // after rejectedCandidates and then taking a global prefix
            // starves them completely whenever there are 24+ rejects.
            // Prefer structural context alternatives, then supplement with
            // the strongest global and different-VMD rejected candidates.
            const int maxLocalInsertionContextSeeds = 16;
            const int maxLocalInsertionGlobalSeeds = 8;
            const int maxLocalInsertionDiverseSeeds = 8;
            const int maxLocalInsertionOwnersPerSeed = 2;
            var localInsertionTrials = 0;
            var localInsertionImprovements = 0;
            var localSeeds = contextSeeds
                .Take(maxLocalInsertionContextSeeds)
                .Concat(globalSeeds.Take(maxLocalInsertionGlobalSeeds))
                .Concat(diverseSeeds.Take(maxLocalInsertionDiverseSeeds))
                .GroupBy(entry => entry.GeneratedPayloadId,
                    StringComparer.Ordinal)
                .Select(group => group.First())
                .ToArray();
            foreach (var contender in localSeeds)
            {
                if (best.SelectedPayloadIds.Contains(
                        contender.GeneratedPayloadId) ||
                    !conflictProfiles.TryGetValue(
                        contender.GeneratedPayloadId,
                        out var contenderProfile))
                {
                    continue;
                }

                var conflictingOwners = bestOrder
                    .Where(entry =>
                        best.SelectedPayloadIds.Contains(
                            entry.GeneratedPayloadId) &&
                        conflictProfiles.TryGetValue(
                            entry.GeneratedPayloadId, out var winnerProfile) &&
                        MayCrossRigidPayloadProfilesCompete(
                            contenderProfile, winnerProfile))
                    .Take(maxLocalInsertionOwnersPerSeed)
                    .ToArray();
                foreach (var owner in conflictingOwners)
                {
                    var trialOrder = bestOrder
                        .Where(entry => !entry.GeneratedPayloadId.Equals(
                            contender.GeneratedPayloadId,
                            StringComparison.Ordinal))
                        .ToList();
                    var ownerIndex = trialOrder.FindIndex(entry =>
                        entry.GeneratedPayloadId.Equals(
                            owner.GeneratedPayloadId,
                            StringComparison.Ordinal));
                    if (ownerIndex < 0)
                        continue;

                    trialOrder.Insert(ownerIndex, contender);
                    var trial = EvaluateCrossRigidPayloadPortfolio(
                        state,
                        trialOrder,
                        conflictProfiles,
                        invalidProfiles,
                        sourceVmdDocuments);
                    localInsertionTrials++;
                    evaluated++;
                    if (IsBetterCrossRigidPayloadPortfolio(trial, best))
                    {
                        best = trial;
                        bestOrder = trialOrder.ToArray();
                        localInsertionImprovements++;
                    }
                }
            }

            state.CrossRigidPortfolioLocalInsertionTrials =
                localInsertionTrials;
            state.CrossRigidPortfolioLocalInsertionImprovements =
                localInsertionImprovements;
            state.CrossRigidPortfolioOrderingsEvaluated = evaluated;
            state.CrossRigidPortfolioPairTrials = pairsToEvaluate.Length * 2;
            state.CrossRigidBestPortfolioExpectedDraws =
                best.ExpectedDraws;
            // The final greedy replay applies the same conflict keys,
            // exact Cartesian matching, per-payload benefit floor, geometry
            // and residency budgets to pair-only additions, after the best
            // original portfolio has occupied its writable states.
            return bestOrder
                .Concat(fallbackOnlyCandidates)
                .Select((entry, index) =>
                    entry with { SelectionRank = index + 1 })
                .ToList();
        }

        // Conservative trial prefilter: even an overlap involving an
        // unselected state only schedules another ordering; it never grants
        // rewrite compatibility or bypasses the exact conflict evaluator.
        private static bool MayCrossRigidPayloadProfilesCompete(
            CrossRigidPayloadRewriteConflictProfile contender,
            CrossRigidPayloadRewriteConflictProfile selected)
        {
            var selectedKeys = selected.Occurrences
                .SelectMany(occurrence => occurrence.RewriteConflictKeys)
                .ToHashSet(StringComparer.Ordinal);
            var selectedContexts = selected.Occurrences
                .SelectMany(occurrence =>
                    occurrence.JointContextKeyByParentLocation)
                .GroupBy(pair => pair.Key, StringComparer.Ordinal)
                .ToDictionary(
                    group => group.Key,
                    group => group.Select(pair => pair.Value)
                        .ToHashSet(StringComparer.Ordinal),
                    StringComparer.Ordinal);
            return contender.Occurrences.Any(occurrence =>
                HasCrossRigidRewriteConflict(
                    occurrence.RewriteConflictKeys, selectedKeys) ||
                occurrence.JointContextKeyByParentLocation.Any(pair =>
                    selectedContexts.TryGetValue(
                        pair.Key, out var contexts) &&
                    contexts.Any(context =>
                        !context.Equals(pair.Value,
                            StringComparison.Ordinal))));
        }

        private static bool IsBetterCrossRigidPayloadPortfolio(
            (double ExpectedDraws, long GeometryBytes,
                double ResidentBytes, HashSet<string> SelectedPayloadIds)
                candidate,
            (double ExpectedDraws, long GeometryBytes,
                double ResidentBytes, HashSet<string> SelectedPayloadIds)
                current)
        {
            if (candidate.ExpectedDraws >
                current.ExpectedDraws +
                AtlasValueGateExpectedDrawEpsilon)
            {
                return true;
            }

            if (Math.Abs(
                    candidate.ExpectedDraws -
                    current.ExpectedDraws) >
                AtlasValueGateExpectedDrawEpsilon)
            {
                return false;
            }

            return candidate.ResidentBytes <
                       current.ResidentBytes -
                       AtlasValueGateExpectedDrawEpsilon ||
                   (Math.Abs(
                        candidate.ResidentBytes -
                        current.ResidentBytes) <=
                    AtlasValueGateExpectedDrawEpsilon &&
                    candidate.GeometryBytes <
                    current.GeometryBytes);
        }

        private static (
            double ExpectedDraws,
            long GeometryBytes,
            double ResidentBytes,
            HashSet<string> SelectedPayloadIds)
            EvaluateCrossRigidPayloadPortfolio(
                BatchState state,
                IReadOnlyList<CrossRigidPayloadSelectionEntry>
                    orderedCandidates,
                Dictionary<string, CrossRigidPayloadRewriteConflictProfile>
                    conflictProfiles,
                HashSet<string> invalidProfiles,
                Dictionary<string, XmlDocument> sourceVmdDocuments)
        {
            var selectedKeys =
                new HashSet<string>(StringComparer.Ordinal);
            var selectedContexts =
                new Dictionary<string, string>(
                    StringComparer.Ordinal);
            var selectedIds =
                new HashSet<string>(StringComparer.Ordinal);
            var pending =
                new List<CrossRigidPayloadSelectionEntry>(
                    orderedCandidates);
            var physicalBytes = 0L;
            var residentBytes = 0.0;
            var expectedDraws = 0.0;

            // Match the final greedy writer, including budget deferrals.
            // The evaluator mutates only local selection sets and caches
            // read-only conflict profiles; it never marks rewrites for output.
            while (pending.Count != 0)
            {
                var acceptedThisPass = false;
                for (var index = 0; index < pending.Count;)
                {
                    var candidate = pending[index];
                    if (invalidProfiles.Contains(
                            candidate.GeneratedPayloadId))
                    {
                        pending.RemoveAt(index);
                        continue;
                    }

                    if (!conflictProfiles.TryGetValue(
                            candidate.GeneratedPayloadId,
                            out var profile))
                    {
                        if (!TryBuildCrossRigidPayloadRewriteConflictProfile(
                                state,
                                candidate.GeneratedPayloadId,
                                sourceVmdDocuments,
                                !state.CrossRigidLegacyEligiblePayloadIds.Contains(
                                    candidate.GeneratedPayloadId),
                                out profile,
                                out _))
                        {
                            invalidProfiles.Add(
                                candidate.GeneratedPayloadId);
                            pending.RemoveAt(index);
                            continue;
                        }

                        conflictProfiles[
                            candidate.GeneratedPayloadId] = profile;
                    }

                    var occurrences =
                        SelectCrossRigidCompatibleRewriteOccurrences(
                            profile,
                            selectedKeys,
                            selectedContexts);
                    var marginalDraws =
                        occurrences.Sum(occurrence =>
                            occurrence.ExpectedArmyDrawCallsEliminated);
                    if (marginalDraws <=
                            AtlasValueGateExpectedDrawEpsilon ||
                        (candidate.VmdCount == 1 &&
                         marginalDraws <
                         MinimumCrossRigidSingleVmdExpectedArmyDraw))
                    {
                        pending.RemoveAt(index);
                        continue;
                    }

                    var projectedDraws =
                        expectedDraws + marginalDraws;
                    var projectedResident =
                        residentBytes +
                        candidate.ExpectedResidentGeneratedGeometryBytes;
                    if (projectedResident >
                        projectedDraws *
                        MaxCrossRigidExpectedResidentGeometryBytesPerExpectedArmyDraw)
                    {
                        index++;
                        continue;
                    }

                    var projectedPhysical =
                        physicalBytes +
                        candidate.GeneratedGeometryBytes;
                    if (projectedPhysical >
                        projectedDraws *
                        MaxCrossRigidGeneratedGeometryBytesPerExpectedArmyDraw)
                    {
                        index++;
                        continue;
                    }

                    if (projectedPhysical >
                        MaxCrossRigidGeneratedGeometryGrowthBytes)
                    {
                        pending.RemoveAt(index);
                        continue;
                    }

                    physicalBytes = projectedPhysical;
                    residentBytes = projectedResident;
                    expectedDraws = projectedDraws;
                    selectedIds.Add(
                        candidate.GeneratedPayloadId);
                    foreach (var occurrence in occurrences)
                    {
                        selectedKeys.UnionWith(
                            occurrence.RewriteConflictKeys);
                        foreach (var context in
                                 occurrence.JointContextKeyByParentLocation)
                        {
                            selectedContexts[context.Key] =
                                context.Value;
                        }
                    }

                    pending.RemoveAt(index);
                    acceptedThisPass = true;
                }

                if (!acceptedThisPass)
                    break;
            }

            return (
                expectedDraws,
                physicalBytes,
                residentBytes,
                selectedIds);
        }

        private static CrossRigidRewriteConflictOccurrence[]
            SelectCrossRigidCompatibleRewriteOccurrences(
                CrossRigidPayloadRewriteConflictProfile profile,
                IReadOnlySet<string> selectedRewriteConflictKeys,
                IReadOnlyDictionary<string, string>
                    selectedJointContextKeyByParentLocation)
        {
            // The caller's selected keys/contexts are immutable for this
            // evaluation. Only track additions made by *this* payload.
            // Copying the whole selected portfolio here was quadratic across
            // candidates, multiplied again by each portfolio-ordering trial.
            var localRewriteConflictKeys =
                new HashSet<string>(StringComparer.Ordinal);
            var localJointContextKeyByParentLocation =
                new Dictionary<string, string>(StringComparer.Ordinal);
            var selected =
                new List<CrossRigidRewriteConflictOccurrence>();

            // Profile occurrences are already sorted by expected draw benefit,
            // then by selection key, when the conflict profile is constructed.
            foreach (var occurrence in profile.Occurrences)
            {
                if (HasCrossRigidRewriteConflict(
                        occurrence.RewriteConflictKeys,
                        selectedRewriteConflictKeys) ||
                    HasCrossRigidRewriteConflict(
                        occurrence.RewriteConflictKeys,
                        localRewriteConflictKeys) ||
                    occurrence.JointContextKeyByParentLocation.Any(
                        pair =>
                            (selectedJointContextKeyByParentLocation
                                 .TryGetValue(
                                     pair.Key,
                                     out var existingContextKey) &&
                             !existingContextKey.Equals(
                                 pair.Value,
                                 StringComparison.Ordinal)) ||
                            (localJointContextKeyByParentLocation
                                 .TryGetValue(
                                     pair.Key,
                                     out var localContextKey) &&
                             !localContextKey.Equals(
                                 pair.Value,
                                 StringComparison.Ordinal))))
                {
                    continue;
                }

                selected.Add(occurrence);
                localRewriteConflictKeys.UnionWith(
                    occurrence.RewriteConflictKeys);
                foreach (var pair in
                         occurrence.JointContextKeyByParentLocation)
                {
                    localJointContextKeyByParentLocation[
                        pair.Key] =
                        pair.Value;
                }
            }

            return selected.ToArray();
        }

        private static bool HasCrossRigidRewriteConflict(
            IReadOnlySet<string> candidateKeys,
            IReadOnlySet<string> selectedKeys)
        {
            const string exactStructuralPrefix =
                "exact-structural-slot\u001f";
            const string jointStructuralPrefix =
                "joint-structural-slot\u001f";
            const string jointTraversalPrefix =
                "joint-traversal-slot\u001f";

            foreach (var key in candidateKeys)
            {
                if (key.StartsWith(
                        exactStructuralPrefix,
                        StringComparison.Ordinal))
                {
                    if (selectedKeys.Contains(
                            jointStructuralPrefix +
                            key[exactStructuralPrefix.Length..]))
                    {
                        return true;
                    }

                    continue;
                }

                if (key.StartsWith(
                        jointStructuralPrefix,
                        StringComparison.Ordinal))
                {
                    var suffix =
                        key[jointStructuralPrefix.Length..];
                    if (selectedKeys.Contains(
                            exactStructuralPrefix +
                            suffix) ||
                        selectedKeys.Contains(
                            jointTraversalPrefix +
                            suffix))
                    {
                        return true;
                    }

                    continue;
                }

                if (key.StartsWith(
                        jointTraversalPrefix,
                        StringComparison.Ordinal))
                {
                    if (selectedKeys.Contains(
                            jointStructuralPrefix +
                            key[jointTraversalPrefix.Length..]))
                    {
                        return true;
                    }

                    continue;
                }

                if (selectedKeys.Contains(key))
                    return true;
            }

            return false;
        }

        private static (string Reason, string Detail)
            ClassifyCrossRigidRewriteOccurrenceConflict(
                CrossRigidPayloadRewriteConflictProfile profile,
                IReadOnlySet<string> selectedRewriteConflictKeys,
                IReadOnlyDictionary<
                    string,
                    CrossRigidSelectedRewriteConflictOwner>
                    selectedRewriteConflictOwnerByKey,
                IReadOnlyDictionary<string, string>
                    selectedJointContextKeyByParentLocation,
                IReadOnlyDictionary<
                    string,
                    CrossRigidSelectedRewriteConflictOwner>
                    selectedJointContextOwnerByParentLocation)
        {
            const string exactStructuralPrefix =
                "exact-structural-slot\u001f";
            const string jointStructuralPrefix =
                "joint-structural-slot\u001f";
            const string jointTraversalPrefix =
                "joint-traversal-slot\u001f";

            foreach (var occurrence in profile.Occurrences)
            {
                foreach (var pair in
                         occurrence.JointContextKeyByParentLocation)
                {
                    if (!selectedJointContextKeyByParentLocation.TryGetValue(
                            pair.Key,
                            out var selectedContextKey) ||
                        selectedContextKey.Equals(
                            pair.Value,
                            StringComparison.Ordinal))
                    {
                        continue;
                    }

                    var selectedSuffix =
                        selectedContextKey.StartsWith(
                            pair.Key + "\u001f",
                            StringComparison.Ordinal)
                            ? selectedContextKey[
                                (pair.Key.Length + 1)..]
                            : selectedContextKey;
                    var candidateSuffix =
                        pair.Value.StartsWith(
                            pair.Key + "\u001f",
                            StringComparison.Ordinal)
                            ? pair.Value[
                                (pair.Key.Length + 1)..]
                            : pair.Value;
                    var ownerDetail =
                        selectedJointContextOwnerByParentLocation
                            .TryGetValue(
                                pair.Key,
                                out var contextOwner)
                            ? DescribeCrossRigidSelectedConflictOwner(
                                contextOwner)
                            : string.Empty;
                    return (
                        "Different joint slot/dimension set under one structural parent",
                        $"parent={pair.Key}; selected={selectedSuffix}; " +
                        $"candidate={candidateSuffix}{ownerDetail}");
                }

                foreach (var key in occurrence.RewriteConflictKeys)
                {
                    if (key.StartsWith(
                            exactStructuralPrefix,
                            StringComparison.Ordinal))
                    {
                        var counterpart =
                            jointStructuralPrefix +
                            key[exactStructuralPrefix.Length..];
                        if (selectedRewriteConflictKeys.Contains(
                                counterpart))
                        {
                            return (
                                "Exact rewrite overlaps a selected joint structural slot",
                                key +
                                DescribeCrossRigidSelectedConflictOwner(
                                    selectedRewriteConflictOwnerByKey,
                                    counterpart));
                        }

                        continue;
                    }

                    if (key.StartsWith(
                            jointStructuralPrefix,
                            StringComparison.Ordinal))
                    {
                        var suffix =
                            key[jointStructuralPrefix.Length..];
                        if (selectedRewriteConflictKeys.Contains(
                                exactStructuralPrefix + suffix))
                        {
                            return (
                                "Joint rewrite overlaps a selected exact structural slot",
                                key +
                                DescribeCrossRigidSelectedConflictOwner(
                                    selectedRewriteConflictOwnerByKey,
                                    exactStructuralPrefix + suffix));
                        }

                        if (selectedRewriteConflictKeys.Contains(
                                jointTraversalPrefix + suffix))
                        {
                            return (
                                "Joint rewrite would invalidate a selected nested joint path",
                                key +
                                DescribeCrossRigidSelectedConflictOwner(
                                    selectedRewriteConflictOwnerByKey,
                                    jointTraversalPrefix + suffix));
                        }

                        continue;
                    }

                    if (key.StartsWith(
                            jointTraversalPrefix,
                            StringComparison.Ordinal))
                    {
                        var counterpart =
                            jointStructuralPrefix +
                            key[jointTraversalPrefix.Length..];
                        if (selectedRewriteConflictKeys.Contains(
                                counterpart))
                        {
                            return (
                                "Joint traversal passes through a selected rewritten slot",
                                key +
                                DescribeCrossRigidSelectedConflictOwner(
                                    selectedRewriteConflictOwnerByKey,
                                    counterpart));
                        }

                        continue;
                    }

                    if (!selectedRewriteConflictKeys.Contains(key))
                        continue;

                    if (key.StartsWith(
                            "exact\u001f",
                            StringComparison.Ordinal))
                    {
                        return (
                            "Exact source model occurrence already selected",
                            key +
                            DescribeCrossRigidSelectedConflictOwner(
                                selectedRewriteConflictOwnerByKey,
                                key));
                    }

                    if (key.StartsWith(
                            "joint\u001f",
                            StringComparison.Ordinal))
                    {
                        return (
                            "Joint Cartesian source occurrence already selected",
                            key +
                            DescribeCrossRigidSelectedConflictOwner(
                                selectedRewriteConflictOwnerByKey,
                                key));
                    }

                    return (
                        "Rewrite conflict key already selected",
                        key +
                        DescribeCrossRigidSelectedConflictOwner(
                            selectedRewriteConflictOwnerByKey,
                            key));
                }
            }

            return (
                "Rewrite conflict could not be classified",
                "all occurrence states were incompatible but no specific key was identified");
        }

        private static string DescribeCrossRigidSelectedConflictOwner(
            IReadOnlyDictionary<
                string,
                CrossRigidSelectedRewriteConflictOwner>
                ownerByConflictKey,
            string conflictKey)
            => ownerByConflictKey.TryGetValue(
                    conflictKey,
                    out var owner)
                ? DescribeCrossRigidSelectedConflictOwner(
                    owner)
                : string.Empty;

        private static string DescribeCrossRigidSelectedConflictOwner(
            CrossRigidSelectedRewriteConflictOwner owner)
            => $"; ownerPayload={owner.GeneratedPayloadId}, " +
               $"ownerStateExpectedDraws=" +
               $"{owner.OccurrenceExpectedArmyDrawCallsEliminated:0.######}, " +
               $"ownerMaxRawDraws={owner.MaxRawDrawsSavedPerState}, " +
               $"ownerGeometry={FormatMiB(owner.GeneratedGeometryBytes, 2)}, " +
               $"ownerRank={owner.SelectionRank}";

        private static void RecordCrossRigidRewriteConflict(
            BatchState state,
            string reason,
            CrossRigidPayloadSelectionEntry candidate,
            string example)
        {
            state.CrossRigidRewriteConflictReasonCounts[reason] =
                state.CrossRigidRewriteConflictReasonCounts
                    .GetValueOrDefault(reason) + 1;
            state.CrossRigidRewriteConflictExpectedDraws[reason] =
                state.CrossRigidRewriteConflictExpectedDraws
                    .GetValueOrDefault(reason) +
                candidate.ExpectedArmyDrawCallsEliminated;

            if (!state.CrossRigidRewriteConflictExamples.TryGetValue(
                    reason,
                    out var examples))
            {
                examples = [];
                state.CrossRigidRewriteConflictExamples[reason] =
                    examples;
            }

            const int maxExamplesPerReason = 8;
            if (examples.Count < maxExamplesPerReason &&
                !examples.Contains(
                    example,
                    StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private static void AddCrossRigidStructuralSlotConflictKeys(
            HashSet<string> conflictKeys,
            string rootVmdPath,
            CrossRigidVisualInstance instance)
        {
            for (var hopIndex = 0;
                 hopIndex < instance.ReferenceChain.Length;
                 hopIndex++)
            {
                var hop =
                    instance.ReferenceChain[hopIndex];
                AddCrossRigidStructuralSlotConflictKeysForXmlPath(
                    conflictKeys,
                    "exact-structural-slot",
                    rootVmdPath,
                    instance.ReferenceChain.Take(
                        hopIndex),
                    hop.OwnerVmdPath,
                    hop.ReferenceXmlPath);
            }

            AddCrossRigidStructuralSlotConflictKeysForXmlPath(
                conflictKeys,
                "exact-structural-slot",
                rootVmdPath,
                instance.ReferenceChain,
                instance.DefiningVmdPath,
                instance.ModelXmlPath);
        }

        private static void
            AddCrossRigidJointTraversalStructuralSlotConflictKeys(
                HashSet<string> conflictKeys,
                string rootVmdPath,
                CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            for (var hopIndex = 0;
                 hopIndex < descriptor.AnchorReferenceChain.Length;
                 hopIndex++)
            {
                var hop =
                    descriptor.AnchorReferenceChain[hopIndex];
                AddCrossRigidStructuralSlotConflictKeysForXmlPath(
                    conflictKeys,
                    "joint-traversal-slot",
                    rootVmdPath,
                    descriptor.AnchorReferenceChain.Take(
                        hopIndex),
                    hop.OwnerVmdPath,
                    hop.ReferenceXmlPath);
            }

            AddCrossRigidStructuralSlotConflictKeysForXmlPath(
                conflictKeys,
                "joint-traversal-slot",
                rootVmdPath,
                descriptor.AnchorReferenceChain,
                descriptor.AnchorVmdPath,
                descriptor.ParentXmlPath);
        }

        private static void
            AddCrossRigidStructuralSlotConflictKeysForXmlPath(
                HashSet<string> conflictKeys,
                string conflictKind,
                string rootVmdPath,
                IEnumerable<CrossRigidVmdReferenceHop>
                    anchorReferenceChain,
                string ownerVmdPath,
                string xmlPath)
        {
            const string slotMarker = "/SLOT[";
            var searchIndex = 0;
            while (searchIndex < xmlPath.Length)
            {
                var slotMarkerIndex =
                    xmlPath.IndexOf(
                        slotMarker,
                        searchIndex,
                        StringComparison.Ordinal);
                if (slotMarkerIndex < 0)
                    break;

                var slotIndexStart =
                    slotMarkerIndex +
                    slotMarker.Length;
                var slotIndexEnd =
                    xmlPath.IndexOf(
                        ']',
                        slotIndexStart);
                if (slotIndexEnd <= slotIndexStart ||
                    !int.TryParse(
                        xmlPath[
                            slotIndexStart..
                            slotIndexEnd],
                        NumberStyles.None,
                        CultureInfo.InvariantCulture,
                        out var slotIndex) ||
                    slotIndex <= 0)
                {
                    searchIndex =
                        slotIndexStart;
                    continue;
                }

                conflictKeys.Add(
                    BuildCrossRigidStructuralSlotConflictKey(
                        conflictKind,
                        rootVmdPath,
                        anchorReferenceChain,
                        ownerVmdPath,
                        xmlPath[..slotMarkerIndex],
                        slotIndex));
                searchIndex =
                    slotIndexEnd + 1;
            }
        }

        private static string
            BuildCrossRigidStructuralSlotConflictKey(
                string conflictKind,
                string rootVmdPath,
                IEnumerable<CrossRigidVmdReferenceHop>
                    anchorReferenceChain,
                string ownerVmdPath,
                string parentXmlPath,
                int slotIndex)
            => string.Join(
                "\u001f",
                conflictKind,
                Normalize(rootVmdPath),
                BuildCrossRigidReferenceChainSignature(
                    anchorReferenceChain),
                Normalize(ownerVmdPath),
                parentXmlPath,
                slotIndex.ToString(
                    CultureInfo.InvariantCulture));

        private static string BuildCrossRigidSelectedRewriteOccurrenceKey(
            CrossRigidMergeAnalysisEntry plan,
            CrossRigidRewriteOccurrenceSet occurrenceSet)
            => string.Join(
                "\u001f",
                plan.RewritePlanId,
                BuildCrossRigidOccurrenceProvenanceSignature(
                    occurrenceSet.SourceInstances));

        private static string
            BuildCrossRigidSelectedRewriteCombinationKey(
                string rewriteOccurrenceKey,
                string combinationKey)
            => string.Join(
                "\u001f",
                rewriteOccurrenceKey,
                "canonical-joint-state",
                combinationKey);

        private static bool
            TryBuildCrossRigidPayloadRewriteConflictProfile(
                BatchState state,
                string generatedPayloadId,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                bool includeSupplementaryPairFallbackPlans,
                out CrossRigidPayloadRewriteConflictProfile profile,
                out string reason,
                bool onlySupplementaryPairFallbackPlans = false)
        {
            reason = string.Empty;
            var occurrences =
                new List<CrossRigidRewriteConflictOccurrence>();

            foreach (var plan in
                     state.CrossRigidMergeAnalysisEntries.Where(
                         entry =>
                             entry.GeneratedPayloadId.Equals(
                                 generatedPayloadId,
                                 StringComparison.Ordinal) &&
                             (onlySupplementaryPairFallbackPlans
                                  ? state.CrossRigidPreviouslySuppressedPairFallbackPlanIds
                                      .Contains(entry.RewritePlanId)
                                  : includeSupplementaryPairFallbackPlans ||
                                    !state.CrossRigidPreviouslySuppressedPairFallbackPlanIds
                                        .Contains(entry.RewritePlanId))))
            {
                foreach (var occurrenceSet in
                         plan.RewriteOccurrenceSets)
                {
                    var rewriteOccurrenceKey =
                        BuildCrossRigidSelectedRewriteOccurrenceKey(
                            plan,
                            occurrenceSet);
                    var expectedDraws =
                        CalculateExpectedCrossRigidArmyDrawSavings(
                            state,
                            plan.VmdPath,
                            occurrenceSet.Probability,
                            plan.Lods);
                    var rewriteConflictKeys =
                        new HashSet<string>(
                            StringComparer.Ordinal);
                    var jointContextKeyByParentLocation =
                        new Dictionary<string, string>(
                            StringComparer.Ordinal);
                    var activationSignatureCount =
                        occurrenceSet.SourceInstances
                            .Select(instance =>
                                instance.ActivationSignature)
                            .Distinct(StringComparer.Ordinal)
                            .Count();
                    if (activationSignatureCount == 1)
                    {
                        foreach (var instance in
                                 occurrenceSet.SourceInstances)
                        {
                            rewriteConflictKeys.Add(
                                string.Join(
                                    "\u001f",
                                    "exact",
                                    BuildCrossRigidConsumedOccurrenceKey(
                                        plan.VmdPath,
                                        instance)));
                            AddCrossRigidStructuralSlotConflictKeys(
                                rewriteConflictKeys,
                                plan.VmdPath,
                                instance);
                        }

                        occurrences.Add(
                            new CrossRigidRewriteConflictOccurrence(
                                rewriteOccurrenceKey,
                                rewriteOccurrenceKey,
                                null,
                                expectedDraws,
                                rewriteConflictKeys,
                                jointContextKeyByParentLocation));
                        continue;
                    }

                    if (!TryDescribeCrossRigidJointAlwaysPresentRewrite(
                            state,
                            occurrenceSet,
                            sourceVmdDocuments,
                            out var descriptor,
                            out reason))
                    {
                        profile = null!;
                        return false;
                    }

                    var originalParentKey =
                        BuildCrossRigidJointParentLocationKey(
                            plan.VmdPath, descriptor);
                    var parentLocationKey =
                        GetCrossRigidEffectiveJointParentKey(
                            state, plan.VmdPath, descriptor);
                    var contextDescriptor =
                        GetCrossRigidEffectiveJointDescriptor(
                            state,
                            plan.VmdPath,
                            descriptor);
                    var contextKey =
                        BuildCrossRigidJointContextKey(
                            plan.VmdPath,
                            contextDescriptor);
                    jointContextKeyByParentLocation[
                        parentLocationKey] = contextKey;
                    if (!parentLocationKey.Equals(
                            originalParentKey, StringComparison.Ordinal))
                    {
                        // Ordinary contexts conflict with this marker;
                        // disjoint factors all share the same marker.
                        jointContextKeyByParentLocation[
                            originalParentKey] =
                            CrossRigidFactoredParentMarker;
                    }
                    AddCrossRigidJointTraversalStructuralSlotConflictKeys(
                        rewriteConflictKeys,
                        plan.VmdPath,
                        contextDescriptor);
                    foreach (var slotIndex in
                             contextDescriptor.SlotIndices)
                    {
                        rewriteConflictKeys.Add(
                            BuildCrossRigidStructuralSlotConflictKey(
                                "joint-structural-slot",
                                plan.VmdPath,
                                contextDescriptor.AnchorReferenceChain,
                                contextDescriptor.AnchorVmdPath,
                                contextDescriptor.ParentXmlPath,
                                slotIndex));
                    }

                    if (!TryGetCrossRigidMatchingJointCombinations(
                            state,
                            descriptor,
                            contextDescriptor,
                            sourceVmdDocuments,
                            out var matchingCombinations,
                            out reason))
                    {
                        profile = null!;
                        return false;
                    }

                    var totalMatchingMultiplicity =
                        matchingCombinations.Sum(combination =>
                            combination.Multiplicity);
                    if (totalMatchingMultiplicity <= 0)
                    {
                        reason =
                            "Canonical joint state projection has zero total multiplicity";
                        profile = null!;
                        return false;
                    }

                    foreach (var matchingCombination in
                             matchingCombinations)
                    {
                        var combinationConflictKeys =
                            new HashSet<string>(
                                rewriteConflictKeys,
                                StringComparer.Ordinal);
                        foreach (var selection in
                                 descriptor.SourceSelections)
                        {
                            combinationConflictKeys.Add(
                                string.Join(
                                    "\u001f",
                                    "joint",
                                    contextKey,
                                    matchingCombination.CombinationKey,
                                    BuildCrossRigidOccurrenceProvenanceSignature(
                                        [selection.Instance])));
                        }

                        occurrences.Add(
                            new CrossRigidRewriteConflictOccurrence(
                                BuildCrossRigidSelectedRewriteCombinationKey(
                                    rewriteOccurrenceKey,
                                    matchingCombination.CombinationKey),
                                rewriteOccurrenceKey,
                                matchingCombination.CombinationKey,
                                expectedDraws *
                                matchingCombination.Multiplicity /
                                totalMatchingMultiplicity,
                                combinationConflictKeys,
                                new Dictionary<string, string>(
                                    jointContextKeyByParentLocation,
                                    StringComparer.Ordinal)));
                    }
                }
            }

            profile =
                new CrossRigidPayloadRewriteConflictProfile(
                    occurrences
                        .OrderByDescending(occurrence =>
                            occurrence.ExpectedArmyDrawCallsEliminated)
                        .ThenBy(
                            occurrence =>
                                occurrence.SelectionKey,
                            StringComparer.Ordinal)
                        .ToArray());
            return true;
        }

        private static void EmitSelectedCrossRigidMerges(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            state.CrossRigidGeneratedPayloadIds.Clear();
            state.CrossRigidGeneratedRigidPaths.Clear();
            state.CrossRigidGeneratedWsModelPaths.Clear();
            state.CrossRigidGeneratedVmdPaths.Clear();
            state.CrossRigidGeneratedVmdFilesDeduplicated = 0;
            state.CrossRigidRewrittenRootVmdPaths.Clear();
            state.CrossRigidRetainedSourceAssetPaths.Clear();
            state.CrossRigidEmissionSkipCounts.Clear();
            state.CrossRigidEmissionSkipExamples.Clear();
            state.CrossRigidRewritePlansApplied = 0;
            state.CrossRigidRewriteOccurrenceSetsApplied = 0;
            state.CrossRigidExpectedArmyDrawCallsEmitted = 0;
            state.CrossRigidRawLodDrawsBefore = 0;
            state.CrossRigidRawLodDrawsAfter = 0;
            state.CrossRigidOriginalRootSlotsByVmd.Clear();
            var emissionTimer = Stopwatch.StartNew();
            var validationElapsed = TimeSpan.Zero;
            var geometryBuildElapsed = TimeSpan.Zero;
            var copyOnWriteElapsed = TimeSpan.Zero;

            var selectedPlans = state.CrossRigidMergeAnalysisEntries
                .Where(plan =>
                    plan.RewriteOccurrenceSets.Any(
                        occurrenceSet =>
                            state.CrossRigidSelectedRewriteOccurrenceKeys
                                .Contains(
                                    BuildCrossRigidSelectedRewriteOccurrenceKey(
                                        plan,
                                        occurrenceSet))))
                .OrderBy(plan =>
                    state.CrossRigidSharedPayloadFallbackAdmittedPlanIds
                        .Contains(plan.RewritePlanId))
                .ThenByDescending(plan =>
                    plan.ExpectedArmyDrawCallsEliminated)
                .ThenBy(plan => plan.RewritePlanId, StringComparer.Ordinal)
                .ToArray();
            if (selectedPlans.Length == 0)
                return;

            var traversalContainers = GetGameplayTraversalContainers(state);
            var rigidCache = new Dictionary<string, RmvFile>(
                state.RigidModels,
                StringComparer.OrdinalIgnoreCase);
            var sourceComponentCache =
                new Dictionary<string, CrossRigidAnalysisComponent>(
                    StringComparer.OrdinalIgnoreCase);
            var payloadBuildFailures = new Dictionary<string, string>(
                StringComparer.Ordinal);
            var sourceVmdDocuments = new Dictionary<string, XmlDocument>(
                StringComparer.OrdinalIgnoreCase);
            var generatedClonePathByBranchKey =
                new Dictionary<string, string>(StringComparer.Ordinal);
            var consumedModelOccurrences =
                new HashSet<string>(StringComparer.Ordinal);
            var jointRewriteContexts =
                new Dictionary<string, CrossRigidJointRewriteContext>(
                    StringComparer.Ordinal);
            var jointContextKeyByParentLocation =
                new Dictionary<string, string>(
                    StringComparer.Ordinal);

            var planGroups = selectedPlans
                .GroupBy(
                    plan => Normalize(plan.VmdPath),
                    StringComparer.OrdinalIgnoreCase)
                .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                .ToArray();

            for (var vmdIndex = 0; vmdIndex < planGroups.Length; vmdIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var vmdPath = planGroups[vmdIndex].Key;
                var plans = planGroups[vmdIndex]
                    .OrderBy(plan =>
                        state.CrossRigidSharedPayloadFallbackAdmittedPlanIds
                            .Contains(plan.RewritePlanId))
                    .ThenByDescending(plan =>
                        plan.ExpectedArmyDrawCallsEliminated)
                    .ThenBy(plan => plan.RewritePlanId, StringComparer.Ordinal)
                    .ToArray();

                ReportProgress(
                    progress,
                    "Emitting cross-rigid merges",
                    vmdIndex + 1,
                    planGroups.Length,
                    vmdPath);

                var vmdFile = state.Source.FindFile(vmdPath);
                if (vmdFile == null)
                {
                    foreach (var plan in plans)
                    {
                        RecordCrossRigidEmissionSkip(
                            state,
                            "VMD is not writable in the source pack",
                            $"{vmdPath}: {plan.RewritePlanId}");
                    }

                    continue;
                }

                XmlDocument rootDocument;
                try
                {
                    rootDocument = LoadXml(vmdFile);
                    sourceVmdDocuments[vmdPath] =
                        CloneXmlDocument(rootDocument);
                    state.CrossRigidOriginalRootSlotsByVmd[vmdPath] =
                        rootDocument.DocumentElement?
                            .SelectNodes("SLOT")
                            ?.OfType<XmlElement>().ToArray() ?? [];
                }
                catch (Exception ex) when (
                    ex is InvalidOperationException or
                    XmlException or
                    FormatException or
                    ArgumentException)
                {
                    foreach (var plan in plans)
                    {
                        RecordCrossRigidEmissionSkip(
                            state,
                            "VMD could not be loaded for rewrite",
                            $"{vmdPath}: {ex.Message}");
                    }

                    continue;
                }

                var rootModified = false;
                foreach (var plan in plans)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var emittedOccurrenceProbability = 0.0;
                    var emittedOccurrenceSetCount = 0;

                    foreach (var occurrenceSet in
                             plan.RewriteOccurrenceSets
                                 .Where(set =>
                                     state.CrossRigidSelectedRewriteOccurrenceKeys
                                         .Contains(
                                             BuildCrossRigidSelectedRewriteOccurrenceKey(
                                                 plan,
                                                 set)))
                                 .OrderByDescending(set =>
                                     set.Probability)
                                 .ThenBy(
                                     set =>
                                         BuildCrossRigidOccurrenceProvenanceSignature(
                                             set.SourceInstances),
                                     StringComparer.Ordinal))
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                        var rewriteOccurrenceKey =
                            BuildCrossRigidSelectedRewriteOccurrenceKey(
                                plan,
                                occurrenceSet);
                        IReadOnlySet<string>? selectedJointCombinationKeys =
                            null;
                        if (state
                                .CrossRigidSelectedJointCombinationKeysByRewriteOccurrenceKey
                                .TryGetValue(
                                    rewriteOccurrenceKey,
                                    out var selectedCombinationKeys))
                        {
                            selectedJointCombinationKeys =
                                selectedCombinationKeys;
                        }

                        var validationStarted = Stopwatch.GetTimestamp();
                        var validationSucceeded =
                            TryValidateCrossRigidRewriteOccurrenceSet(
                                state,
                                vmdPath,
                                plan,
                                occurrenceSet,
                                sourceVmdDocuments,
                                generatedClonePathByBranchKey,
                                consumedModelOccurrences,
                                jointRewriteContexts,
                                jointContextKeyByParentLocation,
                                selectedJointCombinationKeys,
                                out var validationReason);
                        validationElapsed +=
                            Stopwatch.GetElapsedTime(validationStarted);
                        if (!validationSucceeded)
                        {
                            RecordCrossRigidEmissionSkip(
                                state,
                                validationReason,
                                $"{vmdPath} [{plan.AttachmentIdentity}] " +
                                $"payload={plan.GeneratedPayloadId}");
                            continue;
                        }

                        if (payloadBuildFailures.TryGetValue(
                                plan.GeneratedPayloadId,
                                out var priorPayloadFailure))
                        {
                            RecordCrossRigidEmissionSkip(
                                state,
                                "Generated payload could not be built",
                                $"payload {plan.GeneratedPayloadId}: " +
                                priorPayloadFailure);
                            continue;
                        }

                        if (!state.CrossRigidGeneratedPayloadIds.Contains(
                                plan.GeneratedPayloadId))
                        {
                            var geometryBuildStarted = Stopwatch.GetTimestamp();
                            var geometryBuildSucceeded =
                                TryBuildCrossRigidGeneratedPayload(
                                    state,
                                    plan,
                                    traversalContainers,
                                    rigidCache,
                                    sourceComponentCache,
                                    out var payloadFailure);
                            geometryBuildElapsed +=
                                Stopwatch.GetElapsedTime(geometryBuildStarted);
                            if (!geometryBuildSucceeded)
                            {
                                payloadBuildFailures[
                                    plan.GeneratedPayloadId] =
                                    payloadFailure;
                                RecordCrossRigidEmissionSkip(
                                    state,
                                    "Generated payload could not be built",
                                    $"payload {plan.GeneratedPayloadId}: " +
                                    payloadFailure);
                                continue;
                            }
                        }

                        var generatedWsModelPath =
                            BuildCrossRigidGeneratedWsModelPath(
                                plan.GeneratedPayloadId);
                        var copyOnWriteStarted = Stopwatch.GetTimestamp();
                        var copyOnWriteSucceeded =
                            TryApplyCrossRigidRewriteOccurrenceSet(
                                state,
                                vmdPath,
                                rootDocument,
                                occurrenceSet,
                                generatedWsModelPath,
                                sourceVmdDocuments,
                                generatedClonePathByBranchKey,
                                consumedModelOccurrences,
                                jointRewriteContexts,
                                jointContextKeyByParentLocation,
                                selectedJointCombinationKeys,
                                out var appliedProbabilityFraction,
                                out var applyReason);
                        copyOnWriteElapsed +=
                            Stopwatch.GetElapsedTime(copyOnWriteStarted);
                        if (!copyOnWriteSucceeded)
                        {
                            RecordCrossRigidEmissionSkip(
                                state,
                                "Rewrite provenance could not be applied",
                                $"{vmdPath} [{plan.AttachmentIdentity}] " +
                                $"payload={plan.GeneratedPayloadId}: " +
                                applyReason);
                            continue;
                        }

                        emittedOccurrenceProbability +=
                            occurrenceSet.Probability *
                            appliedProbabilityFraction;
                        emittedOccurrenceSetCount++;
                        rootModified = true;
                    }

                    if (emittedOccurrenceSetCount == 0)
                        continue;

                    state.CrossRigidRewritePlansApplied++;
                    state.CrossRigidRewriteOccurrenceSetsApplied +=
                        emittedOccurrenceSetCount;
                    var emittedFraction =
                        plan.AggregatedConfigurationProbability >
                        AtlasValueGateExpectedDrawEpsilon
                            ? Math.Clamp(
                                emittedOccurrenceProbability /
                                plan.AggregatedConfigurationProbability,
                                0.0,
                                1.0)
                            : 0.0;
                    state.CrossRigidExpectedArmyDrawCallsEmitted +=
                        plan.ExpectedArmyDrawCallsEliminated *
                        emittedFraction;
                    state.CrossRigidRawLodDrawsBefore +=
                        plan.Lods
                            .Where(lod =>
                                lod.IsScenarioRepresentativeState)
                            .Sum(lod =>
                                (long)lod.InputDrawsAfterSameRigidMerge);
                    state.CrossRigidRawLodDrawsAfter +=
                        plan.Lods
                            .Where(lod =>
                                lod.IsScenarioRepresentativeState)
                            .Sum(lod =>
                                (long)lod.OutputDrawsAfterCrossRigidMerge);

                    foreach (var instance in plan.SourceInstances)
                    {
                        state.CrossRigidRetainedSourceAssetPaths.Add(
                            Normalize(instance.WsModelPath));
                    }

                    foreach (var source in plan.SourceGeometry)
                    {
                        state.CrossRigidRetainedSourceAssetPaths.Add(
                            Normalize(source.RigidPath));
                    }
                }

                if (rootModified)
                {
                    state.ModifiedVmdDocuments[vmdPath] =
                        rootDocument;
                    state.CrossRigidRewrittenRootVmdPaths.Add(vmdPath);
                    state.CrossRigidRetainedSourceAssetPaths.Add(vmdPath);
                }
            }

            // Emission is the last source of truth for structural savings.
            // A rejected selected occurrence can leave generated RMVs/WSModels
            // in the output without any corresponding draw elimination, and
            // an incomplete joint branch may have partially mutated cloned
            // documents. Do not save such a pack as a successful conversion.
            if (state.CrossRigidEmissionSkipCounts.Count != 0 ||
                state.CrossRigidRewritePlansApplied != selectedPlans.Length ||
                state.CrossRigidRewriteOccurrenceSetsApplied !=
                    state.CrossRigidSelectedRewriteOccurrenceKeys.Count)
            {
                throw new InvalidOperationException(
                    "Cross-rigid emission did not apply every selected " +
                    "copy-on-write rewrite; refusing to save a partial " +
                    $"topology (plans={state.CrossRigidRewritePlansApplied}/" +
                    $"{selectedPlans.Length}, occurrences=" +
                    $"{state.CrossRigidRewriteOccurrenceSetsApplied}/" +
                    $"{state.CrossRigidSelectedRewriteOccurrenceKeys.Count}, " +
                    $"skip reasons={string.Join(", ", state.CrossRigidEmissionSkipCounts.Select(entry => $"{entry.Key}: {entry.Value}"))}). " +
                    "See cross-rigid emission skip diagnostics in the report.");
            }

            var finalizationTimer = Stopwatch.StartNew();
            FinalizeCrossRigidJointProbabilityMultiplicities(
                jointRewriteContexts.Values);
            DeduplicateCrossRigidGeneratedVmdDocuments(state);

            if (state.ModifiedVmdDocuments.Count != 0)
            {
                foreach (var (path, document) in
                         state.ModifiedVmdDocuments)
                {
                    state.VmdDocuments[path] =
                        VariantMeshDefinitionLoader.Load(
                            document.OuterXml);
                }

                state.ReachableWsModelsByRoot.Clear();
                state.ReachableWsModelsByRootVersion++;
            }

            state.CrossRigidTimingDetails["Emit: validate occurrences"] =
                validationElapsed;
            state.CrossRigidTimingDetails["Emit: construct RMV/WSModel payloads"] =
                geometryBuildElapsed;
            state.CrossRigidTimingDetails["Emit: apply copy-on-write rewrites"] =
                copyOnWriteElapsed;
            state.CrossRigidTimingDetails["Emit: finalize and load VMDs"] =
                finalizationTimer.Elapsed;
            state.CrossRigidTimingDetails["Emit: remaining orchestration"] =
                emissionTimer.Elapsed -
                (validationElapsed + geometryBuildElapsed +
                 copyOnWriteElapsed + finalizationTimer.Elapsed);
        }

        // Finalized copies are no longer mutated by the Cartesian writer.
        // Equivalent child VMDs can be shared across otherwise unrelated
        // appearance combinations, provided their referenced child VMDs are
        // canonicalized first. Do not alter source VMD identities.
        private static void DeduplicateCrossRigidGeneratedVmdDocuments(
            BatchState state)
        {
            if (state.CrossRigidGeneratedVmdPaths.Count < 2)
                return;

            var generatedPaths = state.CrossRigidGeneratedVmdPaths
                .Select(Normalize)
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            var generatedPathSet = generatedPaths.ToHashSet(
                StringComparer.OrdinalIgnoreCase);
            var canonicalByPath = new Dictionary<string, string>(
                StringComparer.OrdinalIgnoreCase);
            var canonicalByXml = new Dictionary<string, string>(
                StringComparer.Ordinal);
            var processing = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);

            string Canonicalize(string generatedPath)
            {
                generatedPath = Normalize(generatedPath);
                if (canonicalByPath.TryGetValue(
                        generatedPath, out var existingPath))
                    return existingPath;

                // A cyclic generated reference cannot be normalized by
                // bottom-up structural sharing. Refuse to change that graph
                // rather than accidentally redirecting its self references.
                if (!processing.Add(generatedPath))
                {
                    throw new InvalidOperationException(
                        "Cross-rigid generated child VMD references contain a cycle: " +
                        generatedPath);
                }

                if (!state.ModifiedVmdDocuments.TryGetValue(
                        generatedPath, out var document))
                {
                    throw new InvalidOperationException(
                        "Cross-rigid generated child VMD document is missing: " +
                        generatedPath);
                }

                var references = document.SelectNodes(
                    "//VARIANT_MESH_REFERENCE");
                if (references != null)
                {
                    foreach (XmlNode node in references)
                    {
                        if (node is not XmlElement reference)
                            continue;

                        var childPath = Normalize(
                            reference.GetAttribute("definition"));
                        if (!generatedPathSet.Contains(childPath))
                            continue;

                        var canonicalChildPath = Canonicalize(childPath);
                        if (!canonicalChildPath.Equals(
                                childPath,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            reference.SetAttribute(
                                "definition", canonicalChildPath);
                        }
                    }
                }

                // OuterXml preserves all slot probabilities, selection
                // order, metadata, model paths, and attachment semantics.
                var xml = document.OuterXml;
                if (!canonicalByXml.TryGetValue(xml, out var canonicalPath))
                {
                    canonicalPath = generatedPath;
                    canonicalByXml.Add(xml, canonicalPath);
                }

                processing.Remove(generatedPath);
                canonicalByPath.Add(generatedPath, canonicalPath);
                return canonicalPath;
            }

            foreach (var generatedPath in generatedPaths)
                Canonicalize(generatedPath);

            // Rewrite both generated and root VMD references only once
            // all content identities are established. Duplicate generated
            // documents are discarded before serialization and validation.
            foreach (var document in state.ModifiedVmdDocuments.Values)
            {
                var references = document.SelectNodes(
                    "//VARIANT_MESH_REFERENCE");
                if (references == null)
                    continue;

                foreach (XmlNode node in references)
                {
                    if (node is not XmlElement reference)
                        continue;

                    var childPath = Normalize(
                        reference.GetAttribute("definition"));
                    if (!canonicalByPath.TryGetValue(
                            childPath, out var canonicalPath) ||
                        childPath.Equals(
                            canonicalPath,
                            StringComparison.OrdinalIgnoreCase))
                        continue;

                    reference.SetAttribute("definition", canonicalPath);
                }
            }

            foreach (var (generatedPath, canonicalPath) in canonicalByPath)
            {
                if (generatedPath.Equals(
                        canonicalPath,
                        StringComparison.OrdinalIgnoreCase))
                    continue;

                state.ModifiedVmdDocuments.Remove(generatedPath);
                state.CrossRigidGeneratedVmdPaths.Remove(generatedPath);
                state.CrossRigidGeneratedVmdFilesDeduplicated++;
            }
        }

        private static void
            FinalizeCrossRigidJointProbabilityMultiplicities(
                IEnumerable<CrossRigidJointRewriteContext> contexts)
        {
            // Inner weighted joints must be finalized before outer wrappers
            // are cloned, so every outer clone captures the already-finalized
            // probability distribution of its descendant joints.
            var combinations =
                contexts
                    .SelectMany(context =>
                        context.Combinations.Values)
                    .Distinct()
                    .OrderByDescending(combination =>
                        GetCrossRigidXmlNodeDepth(
                            combination.WrapperElement))
                    .ToArray();

            foreach (var combination in combinations)
            {
                if (combination.ProbabilityMultiplicityFinalized ||
                    combination.ProbabilityMultiplicity <= 1)
                {
                    combination.ProbabilityMultiplicityFinalized = true;
                    continue;
                }

                XmlNode insertionPoint =
                    combination.WrapperElement;
                var parent =
                    combination.WrapperElement.ParentNode;
                if (parent == null)
                    continue;

                for (var copyIndex = 1;
                     copyIndex <
                     combination.ProbabilityMultiplicity;
                     copyIndex++)
                {
                    var clone =
                        combination.WrapperElement.CloneNode(
                            deep: true);
                    parent.InsertAfter(
                        clone,
                        insertionPoint);
                    insertionPoint =
                        clone;
                }

                combination.ProbabilityMultiplicityFinalized = true;
            }
        }

        private static int GetCrossRigidXmlNodeDepth(
            XmlNode node)
        {
            var depth = 0;
            for (var current = node.ParentNode;
                 current != null;
                 current = current.ParentNode)
            {
                depth++;
            }

            return depth;
        }

        private static bool TryValidateCrossRigidRewriteOccurrenceSet(
            BatchState state,
            string rootVmdPath,
            CrossRigidMergeAnalysisEntry plan,
            CrossRigidRewriteOccurrenceSet occurrenceSet,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            IReadOnlyDictionary<string, string> generatedClonePathByBranchKey,
            IReadOnlySet<string> consumedModelOccurrences,
            IReadOnlyDictionary<string, CrossRigidJointRewriteContext>
                jointRewriteContexts,
            IReadOnlyDictionary<string, string>
                jointContextKeyByParentLocation,
            IReadOnlySet<string>? selectedJointCombinationKeys,
            out string reason)
        {
            reason = string.Empty;
            if (occurrenceSet.SourceInstances.Length < 2)
            {
                reason = "Rewrite occurrence has fewer than two source models";
                return false;
            }

            var activationSignatures = occurrenceSet.SourceInstances
                .Select(instance => instance.ActivationSignature)
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            var exactActivation = activationSignatures.Length == 1;
            CrossRigidJointAlwaysPresentRewriteDescriptor? jointDescriptor =
                null;
            if (!exactActivation)
            {
                if (!TryDescribeCrossRigidJointAlwaysPresentRewrite(
                        state,
                        occurrenceSet,
                        sourceVmdDocuments,
                        out jointDescriptor,
                        out reason))
                {
                    return false;
                }

                var originalParentKey =
                    BuildCrossRigidJointParentLocationKey(
                        rootVmdPath, jointDescriptor);
                var parentLocationKey =
                    GetCrossRigidEffectiveJointParentKey(
                        state, rootVmdPath, jointDescriptor);
                var contextDescriptor =
                    GetCrossRigidEffectiveJointDescriptor(
                        state,
                        rootVmdPath,
                        jointDescriptor);
                var contextKey =
                    BuildCrossRigidJointContextKey(
                        rootVmdPath,
                        contextDescriptor);
                if (!TryGetCrossRigidMatchingJointCombinations(
                        state,
                        jointDescriptor,
                        contextDescriptor,
                        sourceVmdDocuments,
                        out var matchingCombinations,
                        out reason))
                {
                    return false;
                }

                var selectedCombinations =
                    FilterCrossRigidSelectedJointCombinations(
                        matchingCombinations,
                        selectedJointCombinationKeys);
                if (selectedCombinations.Length == 0)
                {
                    reason =
                        "No selected canonical Cartesian state remains for this rewrite occurrence";
                    return false;
                }

                if (!IsCrossRigidWriterFactorCompatible(
                        jointContextKeyByParentLocation,
                        originalParentKey,
                        parentLocationKey,
                        contextKey))
                {
                    reason =
                        "Joint writer already materialized an incompatible slot factor";
                    return false;
                }

                if (jointRewriteContexts.TryGetValue(
                        contextKey,
                        out var existingContext))
                {
                    foreach (var selectedCombination in
                             selectedCombinations)
                    {
                        if (!existingContext.Combinations.TryGetValue(
                                selectedCombination.CombinationKey,
                                out var combination))
                        {
                            reason =
                                "Joint writer could not locate a matching canonical Cartesian combination";
                            return false;
                        }

                        foreach (var selection in
                                 jointDescriptor.SourceSelections)
                        {
                            var occurrenceKey =
                                BuildCrossRigidOccurrenceProvenanceSignature(
                                    [selection.Instance]);
                            if (combination.ConsumedOccurrenceKeys.Contains(
                                    occurrenceKey))
                            {
                                reason =
                                    "Rewrite occurrence overlaps an already emitted joint-state plan";
                                return false;
                            }
                        }
                    }
                }
            }

            if (occurrenceSet.SourceInstances.Any(instance =>
                    instance.HasRewriteBlockingModifiers))
            {
                reason =
                    "VMD model occurrence has local decal or imposter state";
                return false;
            }

            foreach (var instance in occurrenceSet.SourceInstances)
            {
                if (!instance.AttachmentIdentity.Equals(
                        plan.AttachmentIdentity,
                        StringComparison.Ordinal))
                {
                    reason =
                        "Rewrite occurrence attachment identity no longer matches the analyzed plan";
                    return false;
                }

                if (exactActivation)
                {
                    var occurrenceKey =
                        BuildCrossRigidConsumedOccurrenceKey(
                            rootVmdPath,
                            instance);
                    if (consumedModelOccurrences.Contains(
                            occurrenceKey))
                    {
                        reason =
                            "Rewrite occurrence overlaps an already emitted plan";
                        return false;
                    }
                }

                var currentSourceVmdPath =
                    Normalize(rootVmdPath);
                var prefixHops =
                    new List<CrossRigidVmdReferenceHop>();
                foreach (var hop in instance.ReferenceChain)
                {
                    if (!Normalize(hop.OwnerVmdPath).Equals(
                            currentSourceVmdPath,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "Recorded VMD reference provenance is discontinuous";
                        return false;
                    }

                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            currentSourceVmdPath,
                            sourceVmdDocuments,
                            out var ownerDocument,
                            out reason))
                    {
                        return false;
                    }

                    if (ownerDocument.SelectSingleNode(
                            hop.ReferenceXmlPath) is
                            not XmlElement referenceElement ||
                        !Normalize(
                                referenceElement.GetAttribute(
                                    "definition"))
                            .Equals(
                                Normalize(hop.ReferencedVmdPath),
                                StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "Recorded child-VMD reference no longer matches source XML";
                        return false;
                    }

                    prefixHops.Add(hop);
                    var branchKey =
                        BuildCrossRigidGeneratedVmdBranchKey(
                            rootVmdPath,
                            prefixHops);
                    var clonePath =
                        BuildCrossRigidGeneratedVmdPath(
                            branchKey);
                    if (!generatedClonePathByBranchKey.ContainsKey(
                            branchKey) &&
                        (state.Source.ContainsFile(clonePath) ||
                         state.Output.ContainsFile(clonePath)))
                    {
                        reason =
                            "Deterministic generated VMD path already exists";
                        return false;
                    }

                    currentSourceVmdPath =
                        Normalize(hop.ReferencedVmdPath);
                }

                if (!currentSourceVmdPath.Equals(
                        Normalize(instance.DefiningVmdPath),
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "Recorded model-defining VMD does not match the reference chain";
                    return false;
                }

                if (!TryGetCrossRigidSourceVmdDocument(
                        state,
                        currentSourceVmdPath,
                        sourceVmdDocuments,
                        out var definingDocument,
                        out reason))
                {
                    return false;
                }

                if (definingDocument.SelectSingleNode(
                        instance.ModelXmlPath) is
                        not XmlElement modelElement ||
                    !Normalize(modelElement.GetAttribute("model"))
                        .Equals(
                            Normalize(instance.WsModelPath),
                            StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "Recorded model occurrence no longer matches source XML";
                    return false;
                }
            }

            return true;
        }


        private static bool TryApplyCrossRigidRewriteOccurrenceSet(
            BatchState state,
            string rootVmdPath,
            XmlDocument rootDocument,
            CrossRigidRewriteOccurrenceSet occurrenceSet,
            string generatedWsModelPath,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            Dictionary<string, string> generatedClonePathByBranchKey,
            HashSet<string> consumedModelOccurrences,
            Dictionary<string, CrossRigidJointRewriteContext>
                jointRewriteContexts,
            Dictionary<string, string>
                jointContextKeyByParentLocation,
            IReadOnlySet<string>? selectedJointCombinationKeys,
            out double appliedProbabilityFraction,
            out string reason)
        {
            appliedProbabilityFraction = 0;
            reason = string.Empty;
            var exactActivation =
                occurrenceSet.SourceInstances
                    .Select(instance => instance.ActivationSignature)
                    .Distinct(StringComparer.Ordinal)
                    .Count() == 1;
            if (!exactActivation)
            {
                return TryApplyCrossRigidJointAlwaysPresentRewriteOccurrenceSet(
                    state,
                    rootVmdPath,
                    rootDocument,
                    occurrenceSet,
                    generatedWsModelPath,
                    sourceVmdDocuments,
                    generatedClonePathByBranchKey,
                    jointRewriteContexts,
                    jointContextKeyByParentLocation,
                    selectedJointCombinationKeys,
                    out appliedProbabilityFraction,
                    out reason);
            }

            var orderedInstances = occurrenceSet.SourceInstances
                .OrderBy(
                    instance =>
                        BuildCrossRigidOccurrenceProvenanceSignature(
                            [instance]),
                    StringComparer.Ordinal)
                .ToArray();

            for (var instanceIndex = 0;
                 instanceIndex < orderedInstances.Length;
                 instanceIndex++)
            {
                var instance = orderedInstances[instanceIndex];
                if (!TryResolveCrossRigidMutableDefiningDocument(
                        state,
                        rootVmdPath,
                        rootDocument,
                        instance.ReferenceChain,
                        sourceVmdDocuments,
                        generatedClonePathByBranchKey,
                        out var currentDocument,
                        out reason))
                {
                    return false;
                }

                if (currentDocument.SelectSingleNode(
                        instance.ModelXmlPath) is
                        not XmlElement modelElement)
                {
                    reason =
                        $"Could not locate model occurrence at " +
                        instance.ModelXmlPath;
                    return false;
                }

                if (instanceIndex == 0)
                {
                    modelElement.SetAttribute(
                        "model",
                        generatedWsModelPath);
                }
                else
                {
                    modelElement.RemoveAttribute("model");
                }

                consumedModelOccurrences.Add(
                    BuildCrossRigidConsumedOccurrenceKey(
                        rootVmdPath,
                        instance));
                if (state.Source.ContainsFile(
                        Normalize(instance.DefiningVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(instance.DefiningVmdPath));
                }
            }

            appliedProbabilityFraction = 1;
            return true;
        }

        private static bool
            TryApplyCrossRigidJointAlwaysPresentRewriteOccurrenceSet(
                BatchState state,
                string rootVmdPath,
                XmlDocument rootDocument,
                CrossRigidRewriteOccurrenceSet occurrenceSet,
                string generatedWsModelPath,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                Dictionary<string, string> generatedClonePathByBranchKey,
                Dictionary<string, CrossRigidJointRewriteContext>
                    jointRewriteContexts,
                Dictionary<string, string>
                    jointContextKeyByParentLocation,
                IReadOnlySet<string>? selectedJointCombinationKeys,
                out double appliedProbabilityFraction,
                out string reason)
        {
            appliedProbabilityFraction = 0;
            if (!TryDescribeCrossRigidJointAlwaysPresentRewrite(
                    state,
                    occurrenceSet,
                    sourceVmdDocuments,
                    out var descriptor,
                    out reason))
            {
                return false;
            }

            var originalParentKey =
                BuildCrossRigidJointParentLocationKey(
                    rootVmdPath, descriptor);
            var parentLocationKey =
                GetCrossRigidEffectiveJointParentKey(
                    state, rootVmdPath, descriptor);
            var contextDescriptor =
                GetCrossRigidEffectiveJointDescriptor(
                    state,
                    rootVmdPath,
                    descriptor);
            var contextKey =
                BuildCrossRigidJointContextKey(
                    rootVmdPath,
                    contextDescriptor);
            if (!TryGetCrossRigidMatchingJointCombinations(
                    state,
                    descriptor,
                    contextDescriptor,
                    sourceVmdDocuments,
                    out var matchingCombinations,
                    out reason))
            {
                return false;
            }

            var selectedCombinations =
                FilterCrossRigidSelectedJointCombinations(
                    matchingCombinations,
                    selectedJointCombinationKeys);
            if (selectedCombinations.Length == 0)
            {
                reason =
                    "No selected canonical Cartesian state remains for this rewrite occurrence";
                return false;
            }

            var totalMatchingMultiplicity =
                matchingCombinations.Sum(combination =>
                    combination.Multiplicity);
            var selectedMultiplicity =
                selectedCombinations.Sum(combination =>
                    combination.Multiplicity);
            if (totalMatchingMultiplicity <= 0 ||
                selectedMultiplicity <= 0)
            {
                reason =
                    "Selected canonical Cartesian state has invalid multiplicity";
                return false;
            }

            appliedProbabilityFraction =
                (double)selectedMultiplicity /
                totalMatchingMultiplicity;

            if (!IsCrossRigidWriterFactorCompatible(
                    jointContextKeyByParentLocation,
                    originalParentKey,
                    parentLocationKey,
                    contextKey))
            {
                reason =
                    "Joint writer already materialized an incompatible slot factor";
                return false;
            }

            if (!jointRewriteContexts.TryGetValue(
                    contextKey,
                    out var context))
            {
                if (!TryResolveCrossRigidMutableDefiningDocument(
                        state,
                        rootVmdPath,
                        rootDocument,
                        contextDescriptor.AnchorReferenceChain,
                        sourceVmdDocuments,
                        generatedClonePathByBranchKey,
                        out var definingDocument,
                        out reason) ||
                    !TryCreateCrossRigidJointRewriteContext(
                        state,
                        definingDocument,
                        contextKey,
                        parentLocationKey,
                        contextDescriptor,
                        sourceVmdDocuments,
                        out context,
                        out reason))
                {
                    return false;
                }

                jointRewriteContexts[contextKey] = context;
                jointContextKeyByParentLocation[parentLocationKey] =
                    contextKey;
                jointContextKeyByParentLocation[originalParentKey] =
                    parentLocationKey.Equals(
                        originalParentKey, StringComparison.Ordinal)
                        ? contextKey
                        : CrossRigidFactoredParentMarker;
            }

            var orderedSelections = descriptor.SourceSelections
                .OrderBy(
                    selection =>
                        BuildCrossRigidOccurrenceProvenanceSignature(
                            [selection.Instance]),
                    StringComparer.Ordinal)
                .ToArray();
            var resolvedApplications =
                new List<(
                    CrossRigidJointCombinationRewriteState Combination,
                    List<(
                        CrossRigidJointSourceSelection Selection,
                        XmlElement ModelElement)> ModelElements)>();

            foreach (var selectedCombination in
                     selectedCombinations)
            {
                var combinationKey =
                    selectedCombination.CombinationKey;
                if (!context.Combinations.TryGetValue(
                        combinationKey,
                        out var combination))
                {
                    reason =
                        "Matching canonical joint Cartesian combination no longer resolves";
                    return false;
                }

                var resolvedModelElements =
                    new List<(
                        CrossRigidJointSourceSelection Selection,
                        XmlElement ModelElement)>();
                foreach (var selection in orderedSelections)
                {
                    var occurrenceKey =
                        BuildCrossRigidOccurrenceProvenanceSignature(
                            [selection.Instance]);
                    if (combination.ConsumedOccurrenceKeys.Contains(
                            occurrenceKey))
                    {
                        reason =
                            "Joint Cartesian model occurrence was already consumed";
                        return false;
                    }

                    if (!TryResolveCrossRigidJointSelectionModelElement(
                            state,
                            contextKey,
                            combinationKey,
                            combination,
                            selection,
                            sourceVmdDocuments,
                            out var modelElement,
                            out reason))
                    {
                        return false;
                    }

                    if (!Normalize(modelElement.GetAttribute("model"))
                            .Equals(
                                Normalize(selection.Instance.WsModelPath),
                                StringComparison.OrdinalIgnoreCase))
                    {
                        reason =
                            "Joint Cartesian model occurrence no longer matches the analyzed source";
                        return false;
                    }

                    resolvedModelElements.Add(
                        (selection, modelElement));
                }

                resolvedApplications.Add(
                    (
                        combination,
                        resolvedModelElements));
            }

            foreach (var application in
                     resolvedApplications)
            {
                for (var selectionIndex = 0;
                     selectionIndex <
                     application.ModelElements.Count;
                     selectionIndex++)
                {
                    var (selection, modelElement) =
                        application.ModelElements[
                            selectionIndex];
                    if (selectionIndex == 0)
                    {
                        modelElement.SetAttribute(
                            "model",
                            generatedWsModelPath);
                    }
                    else
                    {
                        // Keep META_DATA and all child slots on the selected branch.
                        // Only geometry is displaced by the generated merged WSModel.
                        modelElement.RemoveAttribute("model");
                    }

                    application.Combination.ConsumedOccurrenceKeys.Add(
                        BuildCrossRigidOccurrenceProvenanceSignature(
                            [selection.Instance]));
                    if (state.Source.ContainsFile(
                            Normalize(selection.Instance.DefiningVmdPath)))
                    {
                        state.CrossRigidRetainedSourceAssetPaths.Add(
                            Normalize(selection.Instance.DefiningVmdPath));
                    }
                }
            }

            return true;
        }

        private static bool TryResolveCrossRigidMutableDefiningDocument(
            BatchState state,
            string rootVmdPath,
            XmlDocument rootDocument,
            IReadOnlyList<CrossRigidVmdReferenceHop> referenceChain,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            Dictionary<string, string> generatedClonePathByBranchKey,
            out XmlDocument currentDocument,
            out string reason)
        {
            reason = string.Empty;
            currentDocument = rootDocument;
            var prefixHops =
                new List<CrossRigidVmdReferenceHop>();

            foreach (var hop in referenceChain)
            {
                prefixHops.Add(hop);
                var branchKey =
                    BuildCrossRigidGeneratedVmdBranchKey(
                        rootVmdPath,
                        prefixHops);
                if (!generatedClonePathByBranchKey.TryGetValue(
                        branchKey,
                        out var generatedVmdPath))
                {
                    generatedVmdPath =
                        BuildCrossRigidGeneratedVmdPath(
                            branchKey);
                    if (state.Source.ContainsFile(generatedVmdPath) ||
                        state.Output.ContainsFile(generatedVmdPath))
                    {
                        reason =
                            "Deterministic generated VMD path already exists";
                        return false;
                    }

                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            hop.ReferencedVmdPath,
                            sourceVmdDocuments,
                            out var sourceChildDocument,
                            out reason))
                    {
                        return false;
                    }

                    var generatedDocument =
                        CloneXmlDocument(
                            sourceChildDocument);
                    state.ModifiedVmdDocuments[
                        generatedVmdPath] =
                        generatedDocument;
                    state.CrossRigidGeneratedVmdPaths.Add(
                        generatedVmdPath);
                    generatedClonePathByBranchKey[
                        branchKey] =
                        generatedVmdPath;
                }

                if (currentDocument.SelectSingleNode(
                        hop.ReferenceXmlPath) is
                    not XmlElement referenceElement)
                {
                    reason =
                        $"Could not locate child VMD reference at " +
                        hop.ReferenceXmlPath;
                    return false;
                }

                referenceElement.SetAttribute(
                    "definition",
                    generatedVmdPath);
                currentDocument =
                    state.ModifiedVmdDocuments[
                        generatedVmdPath];

                if (state.Source.ContainsFile(
                        Normalize(hop.OwnerVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.OwnerVmdPath));
                }

                if (state.Source.ContainsFile(
                        Normalize(hop.ReferencedVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.ReferencedVmdPath));
                }
            }

            return true;
        }

        private static bool IsCrossRigidWriterFactorCompatible(
            IReadOnlyDictionary<string, string> occupied,
            string originalParentKey,
            string effectiveParentKey,
            string contextKey)
        {
            var expectedParent = effectiveParentKey.Equals(
                    originalParentKey, StringComparison.Ordinal)
                ? contextKey
                : CrossRigidFactoredParentMarker;
            return (!occupied.TryGetValue(
                        originalParentKey, out var previousParent) ||
                    previousParent.Equals(expectedParent,
                        StringComparison.Ordinal)) &&
                   (!occupied.TryGetValue(
                        effectiveParentKey, out var previousFactor) ||
                    previousFactor.Equals(contextKey,
                        StringComparison.Ordinal));
        }

        private static XmlElement? ResolveCrossRigidFactoredRootSlot(
            BatchState state,
            string parentLocationKey,
            XmlElement parentElement,
            int slotIndex)
        {
            if (!parentLocationKey.Contains(
                    "\u001ffactor-slots=", StringComparison.Ordinal))
                return parentElement.SelectSingleNode(
                    $"SLOT[{slotIndex}]") as XmlElement;

            var rootPath = parentLocationKey.Split('\u001f')[0];
            if (!state.CrossRigidOriginalRootSlotsByVmd.TryGetValue(
                    rootPath, out var originalSlots) ||
                slotIndex < 1 || slotIndex > originalSlots.Length ||
                originalSlots[slotIndex - 1].ParentNode != parentElement)
                return null;

            return originalSlots[slotIndex - 1];
        }

        private static bool TryCreateCrossRigidJointRewriteContext(
            BatchState state,
            XmlDocument definingDocument,
            string contextKey,
            string parentLocationKey,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out CrossRigidJointRewriteContext context,
            out string reason)
        {
            context = null!;
            reason = string.Empty;
            if (descriptor.CommonAncestorDimensions.Length != 0)
            {
                return TryCreateCrossRigidCommonAncestorJointRewriteContext(
                    state,
                    definingDocument,
                    contextKey,
                    parentLocationKey,
                    descriptor,
                    sourceVmdDocuments,
                    out context,
                    out reason);
            }

            if (definingDocument.SelectSingleNode(
                    descriptor.ParentXmlPath) is
                not XmlElement parentElement)
            {
                reason =
                    "Joint parent VARIANT_MESH could not be resolved in mutable VMD";
                return false;
            }

            var slotDefinitions =
                new List<CrossRigidJointSlotDefinition>();
            foreach (var slotIndex in descriptor.SlotIndices)
            {
                if (ResolveCrossRigidFactoredRootSlot(
                        state, parentLocationKey, parentElement,
                        slotIndex) is not XmlElement slotElement)
                {
                    reason =
                        $"Joint source slot {slotIndex} could not be resolved in mutable VMD";
                    return false;
                }

                var probability =
                    ParseVmdSlotProbability(
                        slotElement.GetAttribute("probability"));
                if (probability <
                        1.0 - AtlasValueGateExpectedDrawEpsilon &&
                    !IsSupportedCrossRigidOptionalJointSlot(
                        slotElement))
                {
                    reason =
                        $"Joint source slot {slotIndex} became an unsupported optional slot";
                    return false;
                }

                var alternatives =
                    GetCrossRigidJointAlternatives(
                        slotElement,
                        slotIndex);
                if (alternatives.Length <= 1)
                {
                    reason =
                        $"Joint source slot {slotIndex} no longer has alternatives";
                    return false;
                }

                slotDefinitions.Add(
                    new CrossRigidJointSlotDefinition(
                        slotIndex,
                        slotElement,
                        alternatives));
            }

            var combinationAlternatives =
                new List<CrossRigidJointAlternative[]>
                {
                    Array.Empty<CrossRigidJointAlternative>(),
                };
            foreach (var slotDefinition in slotDefinitions)
            {
                var expanded =
                    new List<CrossRigidJointAlternative[]>();
                foreach (var prefix in combinationAlternatives)
                {
                    foreach (var alternative in
                             slotDefinition.Alternatives)
                    {
                        expanded.Add(
                            prefix
                                .Append(alternative)
                                .ToArray());
                        if (expanded.Count >
                            MaxCrossRigidJointStateCombinations)
                        {
                            reason =
                                $"Joint Cartesian product exceeds " +
                                $"{MaxCrossRigidJointStateCombinations:N0} combinations";
                            return false;
                        }
                    }
                }

                combinationAlternatives = expanded;
            }

            var expandedCombinationCount =
                combinationAlternatives.Sum(alternatives =>
                    GetCrossRigidJointCombinationMultiplicity(
                        alternatives));
            if (expandedCombinationCount !=
                descriptor.CombinationCount)
            {
                reason =
                    "Joint weighted Cartesian product changed since analysis";
                return false;
            }

            var jointSlot =
                definingDocument.CreateElement("SLOT");
            jointSlot.SetAttribute("probability", "1");
            var combinations =
                new Dictionary<
                    string,
                    CrossRigidJointCombinationRewriteState>(
                    StringComparer.Ordinal);

            foreach (var alternatives in combinationAlternatives)
            {
                var wrapper =
                    definingDocument.CreateElement(
                        "VARIANT_MESH");
                if (parentElement.HasAttribute(
                        "use_different_attach_point_parts"))
                {
                    wrapper.SetAttribute(
                        "use_different_attach_point_parts",
                        parentElement.GetAttribute(
                            "use_different_attach_point_parts"));
                }

                var selectedElementsBySlotIndex =
                    new Dictionary<int, XmlElement>();
                foreach (var alternative in alternatives)
                {
                    var slotDefinition =
                        slotDefinitions.First(definition =>
                            definition.SlotIndex ==
                            alternative.SlotIndex);
                    if (alternative.AlternativeIndex == 0)
                    {
                        if (!IsSupportedCrossRigidOptionalJointSlot(
                                slotDefinition.SlotElement))
                        {
                            reason =
                                "Synthetic absent joint alternative belongs to a non-supported optional slot";
                            return false;
                        }

                        // Absence is materialized by omitting this slot from
                        // the deterministic wrapper. Probability is preserved
                        // by the wrapper's final integer multiplicity.
                        continue;
                    }

                    var deterministicSlot =
                        (XmlElement)slotDefinition.SlotElement
                            .CloneNode(deep: true);
                    if (ParseVmdSlotProbability(
                            deterministicSlot.GetAttribute(
                                "probability")) <
                        1.0 - AtlasValueGateExpectedDrawEpsilon)
                    {
                        deterministicSlot.SetAttribute(
                            "probability",
                            "1");
                    }

                    if (!TryReduceCrossRigidJointSlotToAlternative(
                            deterministicSlot,
                            alternative,
                            out var selectedElement,
                            out reason))
                    {
                        return false;
                    }

                    wrapper.AppendChild(
                        deterministicSlot);
                    selectedElementsBySlotIndex[
                        alternative.SlotIndex] =
                        selectedElement;
                }

                jointSlot.AppendChild(wrapper);
                var combinationKey =
                    BuildCrossRigidJointCombinationKey(
                        alternatives);
                combinations[combinationKey] =
                    new CrossRigidJointCombinationRewriteState(
                        selectedElementsBySlotIndex,
                        wrapperElement: wrapper,
                        probabilityMultiplicity:
                            GetCrossRigidJointCombinationMultiplicity(
                                alternatives));
            }

            var firstSlot =
                slotDefinitions
                    .OrderBy(definition =>
                        definition.SlotIndex)
                    .First()
                    .SlotElement;
            parentElement.InsertBefore(
                jointSlot,
                firstSlot);
            foreach (var slotDefinition in slotDefinitions)
            {
                parentElement.RemoveChild(
                    slotDefinition.SlotElement);
            }

            context =
                new CrossRigidJointRewriteContext(
                    contextKey,
                    parentLocationKey,
                    combinations);
            return true;
        }

        private static bool
            TryCreateCrossRigidCommonAncestorJointRewriteContext(
                BatchState state,
                XmlDocument definingDocument,
                string contextKey,
                string parentLocationKey,
                CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out CrossRigidJointRewriteContext context,
                out string reason)
        {
            context = null!;
            reason = string.Empty;
            if (definingDocument.SelectSingleNode(
                    descriptor.ParentXmlPath) is
                not XmlElement parentElement)
            {
                reason =
                    "Common-ancestor joint parent could not be resolved in mutable VMD";
                return false;
            }

            var carrierSlots =
                new Dictionary<int, XmlElement>();
            foreach (var carrierSlotIndex in
                     descriptor.SlotIndices)
            {
                if (ResolveCrossRigidFactoredRootSlot(
                        state, parentLocationKey, parentElement,
                        carrierSlotIndex) is not XmlElement carrierSlotElement)
                {
                    reason =
                        $"Common-ancestor carrier slot {carrierSlotIndex} could not be resolved";
                    return false;
                }

                var probability =
                    ParseVmdSlotProbability(
                        carrierSlotElement.GetAttribute(
                            "probability"));
                if (probability <
                    1.0 - AtlasValueGateExpectedDrawEpsilon)
                {
                    // Only direct optional dimensions may serve as
                    // carrier slots. Every emitted branch explicitly
                    // materializes their absent or probability-1 state.
                    var explicitOptionalDimension =
                        descriptor.CommonAncestorDimensions.Any(dimension =>
                            dimension.CarrierSlotIndex == carrierSlotIndex &&
                            dimension.SlotIndex == carrierSlotIndex &&
                            Normalize(dimension.OwnerVmdPath).Equals(
                                Normalize(descriptor.AnchorVmdPath),
                                StringComparison.OrdinalIgnoreCase) &&
                            dimension.ParentXmlPath.Equals(
                                descriptor.ParentXmlPath,
                                StringComparison.Ordinal) &&
                            dimension.ReferenceChainFromAnchor.Length == 0 &&
                            string.IsNullOrWhiteSpace(
                                dimension.LocalDimensionSlotRelativeXmlPath) &&
                            dimension.Alternatives.Any(alternative =>
                                alternative.AlternativeIndex == 0)) &&
                        IsSupportedCrossRigidOptionalJointSlot(
                            carrierSlotElement);
                    if (!explicitOptionalDimension)
                    {
                        reason =
                            $"Common-ancestor carrier slot {carrierSlotIndex} became an unsupported optional carrier";
                        return false;
                    }
                }

                carrierSlots[carrierSlotIndex] =
                    carrierSlotElement;
            }

            if (!TryEnumerateCrossRigidConditionalJointStates(
                    descriptor.CommonAncestorDimensions,
                    out var combinationAlternatives,
                    out reason))
            {
                return false;
            }

            var expandedCombinationCount =
                combinationAlternatives.Sum(alternatives =>
                    GetCrossRigidJointCombinationMultiplicity(
                        alternatives));
            if (expandedCombinationCount !=
                descriptor.CombinationCount)
            {
                reason =
                    "Common-ancestor weighted Cartesian product changed since analysis";
                return false;
            }

            var generatedVmdPathsBefore =
                state.CrossRigidGeneratedVmdPaths
                    .ToHashSet(
                        StringComparer.OrdinalIgnoreCase);

            var jointSlot =
                definingDocument.CreateElement("SLOT");
            jointSlot.SetAttribute("probability", "1");
            var combinations =
                new Dictionary<
                    string,
                    CrossRigidJointCombinationRewriteState>(
                    StringComparer.Ordinal);

            foreach (var alternatives in
                     combinationAlternatives)
            {
                var wrapper =
                    definingDocument.CreateElement(
                        "VARIANT_MESH");
                if (parentElement.HasAttribute(
                        "use_different_attach_point_parts"))
                {
                    wrapper.SetAttribute(
                        "use_different_attach_point_parts",
                        parentElement.GetAttribute(
                            "use_different_attach_point_parts"));
                }

                var clonedCarrierSlots =
                    new Dictionary<int, XmlElement>();
                foreach (var carrierSlotIndex in
                         descriptor.SlotIndices)
                {
                    var clonedCarrierSlot =
                        (XmlElement)carrierSlots[
                            carrierSlotIndex]
                            .CloneNode(deep: true);
                    wrapper.AppendChild(
                        clonedCarrierSlot);
                    clonedCarrierSlots[
                        carrierSlotIndex] =
                        clonedCarrierSlot;
                }

                var selectedElementsByDimensionKey =
                    new Dictionary<string, XmlElement>(
                        StringComparer.Ordinal);
                var combination =
                    new CrossRigidJointCombinationRewriteState(
                        clonedCarrierSlots,
                        selectedElementsByDimensionKey,
                        wrapper,
                        GetCrossRigidJointCombinationMultiplicity(
                            alternatives));
                var combinationKey =
                    BuildCrossRigidCommonAncestorCombinationKey(
                        alternatives);

                // The source XML locations are positional XPath indices.
                // Removing an absent optional SLOT[1] shifts a later SLOT[2]
                // to position 1 in that same parent. Materialize deeper
                // dimensions first, then sibling slots in descending index
                // order, while keeping combination identity/probability in
                // its original canonical dimension order.
                var materializationOrder =
                    alternatives
                        .Select(alternative =>
                            (
                                Alternative: alternative,
                                Dimension:
                                    descriptor.CommonAncestorDimensions
                                        .First(item =>
                                            item.DimensionKey.Equals(
                                                alternative.DimensionKey,
                                                StringComparison.Ordinal))
                            ))
                        .OrderByDescending(item =>
                            item.Dimension.ReferenceChainFromAnchor.Length)
                        .ThenByDescending(item =>
                            item.Dimension.ParentXmlPath.Length)
                        .ThenByDescending(item =>
                            item.Dimension.SlotIndex)
                        .ThenBy(item =>
                            item.Dimension.DimensionKey,
                            StringComparer.Ordinal)
                        .ToArray();
                foreach (var entry in materializationOrder)
                {
                    var alternative = entry.Alternative;
                    var dimension = entry.Dimension;
                    if (alternative.AlternativeIndex == -1)
                    {
                        // This child does not exist under the selected
                        // parent branch; no subtree is materialized.
                        continue;
                    }

                    if (!TryMaterializeCrossRigidCommonAncestorDimension(
                            state,
                            contextKey,
                            combinationKey,
                            combination,
                            descriptor,
                            dimension,
                            alternative,
                            sourceVmdDocuments,
                            out var selectedElement,
                            out reason))
                    {
                        foreach (var generatedVmdPath in
                                 state.CrossRigidGeneratedVmdPaths
                                     .Where(path =>
                                         !generatedVmdPathsBefore.Contains(
                                             path))
                                     .ToArray())
                        {
                            state.CrossRigidGeneratedVmdPaths.Remove(
                                generatedVmdPath);
                            state.ModifiedVmdDocuments.Remove(
                                generatedVmdPath);
                        }

                        return false;
                    }

                    selectedElementsByDimensionKey[
                        dimension.DimensionKey] =
                        selectedElement;
                }

                jointSlot.AppendChild(wrapper);
                combinations[combinationKey] =
                    combination;
            }

            var firstCarrierSlot =
                descriptor.SlotIndices
                    .OrderBy(index => index)
                    .Select(index =>
                        carrierSlots[index])
                    .First();
            parentElement.InsertBefore(
                jointSlot,
                firstCarrierSlot);
            foreach (var carrierSlotIndex in
                     descriptor.SlotIndices)
            {
                parentElement.RemoveChild(
                    carrierSlots[
                        carrierSlotIndex]);
            }

            context =
                new CrossRigidJointRewriteContext(
                    contextKey,
                    parentLocationKey,
                    combinations);
            return true;
        }

        private static bool
            TryMaterializeCrossRigidCommonAncestorDimension(
                BatchState state,
                string contextKey,
                string combinationKey,
                CrossRigidJointCombinationRewriteState combination,
                CrossRigidJointAlwaysPresentRewriteDescriptor descriptor,
                CrossRigidJointSelectionDimension dimension,
                CrossRigidJointDimensionAlternative alternative,
                Dictionary<string, XmlDocument> sourceVmdDocuments,
                out XmlElement selectedElement,
                out string reason)
        {
            selectedElement = null!;
            reason = string.Empty;
            if (!combination.SelectedElementsBySlotIndex.TryGetValue(
                    dimension.CarrierSlotIndex,
                    out var carrierSlotElement))
            {
                reason =
                    "Common-ancestor cloned carrier slot could not be located";
                return false;
            }

            if (dimension.ReferenceChainFromAnchor.Length == 0)
            {
                var localDimensionSlotElement =
                    carrierSlotElement;
                if (!string.IsNullOrWhiteSpace(
                        dimension.LocalDimensionSlotRelativeXmlPath))
                {
                    if (carrierSlotElement.SelectSingleNode(
                            dimension.LocalDimensionSlotRelativeXmlPath) is
                        not XmlElement nestedDimensionSlotElement ||
                        !nestedDimensionSlotElement.Name.Equals(
                            "SLOT",
                            StringComparison.Ordinal))
                    {
                        reason =
                            "Common-ancestor nested local dimension slot could not be located";
                        return false;
                    }

                    localDimensionSlotElement =
                        nestedDimensionSlotElement;
                }

                if (alternative.AlternativeIndex == 0)
                {
                    if (!IsSupportedCrossRigidOptionalJointSlot(
                            localDimensionSlotElement))
                    {
                        reason =
                            "Synthetic absent common-ancestor alternative belongs to a non-supported optional slot";
                        return false;
                    }

                    var optionalParent =
                        localDimensionSlotElement.ParentNode;
                    if (optionalParent == null)
                    {
                        reason =
                            "Synthetic absent common-ancestor slot has no parent";
                        return false;
                    }

                    optionalParent.RemoveChild(
                        localDimensionSlotElement);
                    selectedElement =
                        carrierSlotElement;
                    return true;
                }

                if (ParseVmdSlotProbability(
                        localDimensionSlotElement.GetAttribute(
                            "probability")) <
                    1.0 - AtlasValueGateExpectedDrawEpsilon)
                {
                    localDimensionSlotElement.SetAttribute(
                        "probability",
                        "1");
                }

                return TryReduceCrossRigidJointSlotToAlternative(
                    localDimensionSlotElement,
                    new CrossRigidJointAlternative(
                        dimension.SlotIndex,
                        alternative.IsReference,
                        alternative.AlternativeIndex,
                        alternative.Multiplicity),
                    out selectedElement,
                    out reason);
            }

            var carrierSlotXmlPath =
                $"{descriptor.ParentXmlPath}/" +
                $"SLOT[{dimension.CarrierSlotIndex}]";
            var firstHop =
                dimension.ReferenceChainFromAnchor[0];
            if (!TryGetCrossRigidRelativeXmlPath(
                    carrierSlotXmlPath,
                    firstHop.ReferenceXmlPath,
                    out var firstReferenceRelativeXmlPath) ||
                carrierSlotElement.SelectSingleNode(
                    firstReferenceRelativeXmlPath) is
                not XmlElement currentReferenceElement ||
                currentReferenceElement.Name !=
                    "VARIANT_MESH_REFERENCE")
            {
                reason =
                    "Common-ancestor carrier reference could not be located in cloned slot";
                return false;
            }

            XmlDocument? currentDocument = null;
            var localPrefix =
                new List<CrossRigidVmdReferenceHop>();
            foreach (var hop in
                     dimension.ReferenceChainFromAnchor)
            {
                localPrefix.Add(hop);
                var branchKey =
                    string.Join(
                        "\u001f",
                        contextKey,
                        combinationKey,
                        "common-ancestor",
                        dimension.CarrierSlotIndex.ToString(
                            CultureInfo.InvariantCulture),
                        BuildCrossRigidReferenceChainSignature(
                            localPrefix));
                if (!combination.GeneratedVmdPathByBranchKey.TryGetValue(
                        branchKey,
                        out var generatedVmdPath))
                {
                    generatedVmdPath =
                        BuildCrossRigidGeneratedJointVmdPath(
                            branchKey);
                    if (state.Source.ContainsFile(
                            generatedVmdPath) ||
                        state.Output.ContainsFile(
                            generatedVmdPath))
                    {
                        reason =
                            "Deterministic generated common-ancestor VMD path already exists";
                        return false;
                    }

                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            hop.ReferencedVmdPath,
                            sourceVmdDocuments,
                            out var sourceChildDocument,
                            out reason))
                    {
                        return false;
                    }

                    var generatedDocument =
                        CloneXmlDocument(
                            sourceChildDocument);
                    state.ModifiedVmdDocuments[
                        generatedVmdPath] =
                        generatedDocument;
                    state.CrossRigidGeneratedVmdPaths.Add(
                        generatedVmdPath);
                    combination.GeneratedVmdPathByBranchKey[
                        branchKey] =
                        generatedVmdPath;
                }

                currentReferenceElement.SetAttribute(
                    "definition",
                    generatedVmdPath);
                currentDocument =
                    state.ModifiedVmdDocuments[
                        generatedVmdPath];

                if (state.Source.ContainsFile(
                        Normalize(hop.OwnerVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.OwnerVmdPath));
                }

                if (state.Source.ContainsFile(
                        Normalize(hop.ReferencedVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.ReferencedVmdPath));
                }

                var hopIndex =
                    localPrefix.Count - 1;
                if (hopIndex + 1 <
                    dimension.ReferenceChainFromAnchor.Length)
                {
                    var nextHop =
                        dimension.ReferenceChainFromAnchor[
                            hopIndex + 1];
                    if (currentDocument.SelectSingleNode(
                            nextHop.ReferenceXmlPath) is
                        not XmlElement nextReferenceElement ||
                        nextReferenceElement.Name !=
                            "VARIANT_MESH_REFERENCE")
                    {
                        reason =
                            "Common-ancestor nested fixed reference could not be located";
                        return false;
                    }

                    currentReferenceElement =
                        nextReferenceElement;
                }
            }

            if (currentDocument == null ||
                currentDocument.SelectSingleNode(
                    $"{dimension.ParentXmlPath}/" +
                    $"SLOT[{dimension.SlotIndex}]") is
                not XmlElement dimensionSlotElement)
            {
                reason =
                    "Common-ancestor terminal selection slot could not be located: " +
                    $"{dimension.OwnerVmdPath} / {dimension.ParentXmlPath}/" +
                    $"SLOT[{dimension.SlotIndex}], " +
                    $"combination={combinationKey}, " +
                    $"referenceHops={dimension.ReferenceChainFromAnchor.Length}";
                return false;
            }

            if (alternative.AlternativeIndex == 0)
            {
                if (!IsSupportedCrossRigidOptionalJointSlot(
                        dimensionSlotElement))
                {
                    reason =
                        "Synthetic absent referenced common-ancestor alternative belongs to a non-supported optional slot";
                    return false;
                }

                var optionalParent =
                    dimensionSlotElement.ParentNode;
                if (optionalParent == null)
                {
                    reason =
                        "Synthetic absent referenced common-ancestor slot has no parent";
                    return false;
                }

                optionalParent.RemoveChild(
                    dimensionSlotElement);
                selectedElement =
                    currentDocument.DocumentElement!;
                return true;
            }

            if (ParseVmdSlotProbability(
                    dimensionSlotElement.GetAttribute(
                        "probability")) <
                1.0 - AtlasValueGateExpectedDrawEpsilon)
            {
                dimensionSlotElement.SetAttribute(
                    "probability",
                    "1");
            }

            return TryReduceCrossRigidJointSlotToAlternative(
                dimensionSlotElement,
                new CrossRigidJointAlternative(
                    dimension.SlotIndex,
                    alternative.IsReference,
                    alternative.AlternativeIndex,
                    alternative.Multiplicity),
                out selectedElement,
                out reason);
        }

        private static CrossRigidJointAlternative[]
            GetCrossRigidJointAlternatives(
                XmlElement slotElement,
                int slotIndex)
        {
            var alternatives =
                new List<CrossRigidJointAlternative>();
            var optional =
                TryGetCrossRigidOptionalJointMultiplicities(
                    slotElement,
                    out var absentMultiplicity,
                    out var presentMultiplicity);
            if (optional)
            {
                // AlternativeIndex 0 is the synthetic "slot absent" state.
                // Integer multiplicities reproduce the authored optional
                // probability exactly once the finished wrappers are cloned.
                alternatives.Add(
                    new CrossRigidJointAlternative(
                        slotIndex,
                        false,
                        0,
                        absentMultiplicity));
            }

            var meshCount =
                slotElement.SelectNodes(
                    "VARIANT_MESH")?.Count ?? 0;
            for (var meshIndex = 1;
                 meshIndex <= meshCount;
                 meshIndex++)
            {
                alternatives.Add(
                    new CrossRigidJointAlternative(
                        slotIndex,
                        false,
                        meshIndex,
                        optional
                            ? presentMultiplicity
                            : 1));
            }

            var referenceCount =
                slotElement.SelectNodes(
                    "VARIANT_MESH_REFERENCE")?.Count ?? 0;
            for (var referenceIndex = 1;
                 referenceIndex <= referenceCount;
                 referenceIndex++)
            {
                alternatives.Add(
                    new CrossRigidJointAlternative(
                        slotIndex,
                        true,
                        referenceIndex,
                        optional
                            ? presentMultiplicity
                            : 1));
            }

            return alternatives.ToArray();
        }

        private static int GetCrossRigidJointCombinationMultiplicity(
            IEnumerable<CrossRigidJointAlternative> alternatives)
            => alternatives.Aggregate(
                1,
                (product, alternative) =>
                    checked(
                        product *
                        Math.Max(
                            1,
                            alternative.Multiplicity)));

        private static int GetCrossRigidJointCombinationMultiplicity(
            IEnumerable<CrossRigidJointDimensionAlternative> alternatives)
            => alternatives.Aggregate(
                1,
                (product, alternative) =>
                    checked(
                        product *
                        Math.Max(
                            1,
                            alternative.Multiplicity)));

        private static bool TryReduceCrossRigidJointSlotToAlternative(
            XmlElement slotElement,
            CrossRigidJointAlternative alternative,
            out XmlElement selectedElement,
            out string reason)
        {
            selectedElement = null!;
            reason = string.Empty;
            var meshElements =
                slotElement.SelectNodes(
                        "VARIANT_MESH")
                    ?.Cast<XmlElement>()
                    .ToArray() ?? [];
            var referenceElements =
                slotElement.SelectNodes(
                        "VARIANT_MESH_REFERENCE")
                    ?.Cast<XmlElement>()
                    .ToArray() ?? [];

            XmlElement? selected;
            if (alternative.IsReference)
            {
                selected =
                    alternative.AlternativeIndex <=
                    referenceElements.Length
                        ? referenceElements[
                            alternative.AlternativeIndex - 1]
                        : null;
            }
            else
            {
                selected =
                    alternative.AlternativeIndex <=
                    meshElements.Length
                        ? meshElements[
                            alternative.AlternativeIndex - 1]
                        : null;
            }

            if (selected == null)
            {
                reason =
                    "Joint selected alternative no longer exists";
                return false;
            }

            foreach (var element in meshElements)
            {
                if (!ReferenceEquals(
                        element,
                        selected))
                {
                    slotElement.RemoveChild(element);
                }
            }

            foreach (var element in referenceElements)
            {
                if (!ReferenceEquals(
                        element,
                        selected))
                {
                    slotElement.RemoveChild(element);
                }
            }

            selectedElement = selected;
            return true;
        }

        private static bool TryResolveCrossRigidJointSelectionModelElement(
            BatchState state,
            string contextKey,
            string combinationKey,
            CrossRigidJointCombinationRewriteState combination,
            CrossRigidJointSourceSelection selection,
            Dictionary<string, XmlDocument> sourceVmdDocuments,
            out XmlElement modelElement,
            out string reason)
        {
            modelElement = null!;
            reason = string.Empty;
            var dimensionKey =
                BuildCrossRigidJointSourceSelectionDimensionKey(
                    selection);
            if (!combination.SelectedElementsByDimensionKey.TryGetValue(
                    dimensionKey,
                    out var selectedElement) &&
                !combination.SelectedElementsBySlotIndex.TryGetValue(
                    selection.SlotIndex,
                    out selectedElement))
            {
                reason =
                    "Joint selected structural alternative could not be located";
                return false;
            }

            if (selectedElement.Name == "SLOT")
            {
                var selectedNodeName =
                    selection.IsReference
                        ? "VARIANT_MESH_REFERENCE"
                        : "VARIANT_MESH";
                if (selectedElement.SelectSingleNode(
                        $"{selectedNodeName}[{selection.AlternativeIndex}]") is
                    not XmlElement fixedSelectedElement)
                {
                    reason =
                        "Joint fixed carrier alternative could not be located";
                    return false;
                }

                selectedElement =
                    fixedSelectedElement;
            }

            var instance = selection.Instance;
            XmlElement currentReferenceElement;
            if (!selection.IsReference)
            {
                if (selectedElement.Name != "VARIANT_MESH")
                {
                    reason =
                        "Joint direct selection is no longer a VARIANT_MESH";
                    return false;
                }

                if (selection.AnchorReferenceHopIndex < 0)
                {
                    if (string.IsNullOrWhiteSpace(
                            selection.DirectModelRelativeXmlPath))
                    {
                        modelElement = selectedElement;
                        return true;
                    }

                    if (selectedElement.SelectSingleNode(
                            selection.DirectModelRelativeXmlPath) is
                        not XmlElement nestedModelElement)
                    {
                        reason =
                            "Joint direct model subtree occurrence could not be located";
                        return false;
                    }

                    modelElement = nestedModelElement;
                    return true;
                }

                if (selection.AnchorReferenceHopIndex >=
                        instance.ReferenceChain.Length ||
                    string.IsNullOrWhiteSpace(
                        selection.DirectFirstReferenceRelativeXmlPath) ||
                    selectedElement.SelectSingleNode(
                        selection.DirectFirstReferenceRelativeXmlPath) is
                    not XmlElement nestedReferenceElement ||
                    nestedReferenceElement.Name !=
                        "VARIANT_MESH_REFERENCE")
                {
                    reason =
                        "Joint direct-selection child-VMD provenance is invalid";
                    return false;
                }

                currentReferenceElement =
                    nestedReferenceElement;
            }
            else
            {
                if (selection.AnchorReferenceHopIndex < 0 ||
                    selection.AnchorReferenceHopIndex >=
                        instance.ReferenceChain.Length ||
                    selectedElement.Name !=
                        "VARIANT_MESH_REFERENCE")
                {
                    reason =
                        "Joint reference selection provenance is invalid";
                    return false;
                }

                currentReferenceElement =
                    selectedElement;
            }

            XmlDocument? currentDocument = null;
            var localPrefix =
                new List<CrossRigidVmdReferenceHop>();
            for (var hopIndex =
                     selection.AnchorReferenceHopIndex;
                 hopIndex < instance.ReferenceChain.Length;
                 hopIndex++)
            {
                var hop = instance.ReferenceChain[hopIndex];
                localPrefix.Add(hop);
                var branchKey = string.Join(
                    "\u001f",
                    contextKey,
                    combinationKey,
                    dimensionKey,
                    BuildCrossRigidReferenceChainSignature(
                        localPrefix));
                if (!combination.GeneratedVmdPathByBranchKey.TryGetValue(
                        branchKey,
                        out var generatedVmdPath))
                {
                    generatedVmdPath =
                        BuildCrossRigidGeneratedJointVmdPath(
                            branchKey);
                    if (state.Source.ContainsFile(generatedVmdPath) ||
                        state.Output.ContainsFile(generatedVmdPath))
                    {
                        reason =
                            "Deterministic generated joint VMD path already exists";
                        return false;
                    }

                    if (!TryGetCrossRigidSourceVmdDocument(
                            state,
                            hop.ReferencedVmdPath,
                            sourceVmdDocuments,
                            out var sourceChildDocument,
                            out reason))
                    {
                        return false;
                    }

                    var generatedDocument =
                        CloneXmlDocument(
                            sourceChildDocument);
                    state.ModifiedVmdDocuments[
                        generatedVmdPath] =
                        generatedDocument;
                    state.CrossRigidGeneratedVmdPaths.Add(
                        generatedVmdPath);
                    combination.GeneratedVmdPathByBranchKey[
                        branchKey] =
                        generatedVmdPath;
                }

                currentReferenceElement.SetAttribute(
                    "definition",
                    generatedVmdPath);
                currentDocument =
                    state.ModifiedVmdDocuments[
                        generatedVmdPath];

                if (state.Source.ContainsFile(
                        Normalize(hop.OwnerVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.OwnerVmdPath));
                }

                if (state.Source.ContainsFile(
                        Normalize(hop.ReferencedVmdPath)))
                {
                    state.CrossRigidRetainedSourceAssetPaths.Add(
                        Normalize(hop.ReferencedVmdPath));
                }

                if (hopIndex + 1 <
                    instance.ReferenceChain.Length)
                {
                    var nextHop =
                        instance.ReferenceChain[hopIndex + 1];
                    if (currentDocument.SelectSingleNode(
                            nextHop.ReferenceXmlPath) is
                        not XmlElement nextReferenceElement)
                    {
                        reason =
                            $"Could not locate joint child VMD reference at " +
                            nextHop.ReferenceXmlPath;
                        return false;
                    }

                    currentReferenceElement =
                        nextReferenceElement;
                }
            }

            if (currentDocument == null ||
                currentDocument.SelectSingleNode(
                    instance.ModelXmlPath) is
                not XmlElement resolvedModelElement)
            {
                reason =
                    $"Could not locate joint model occurrence at " +
                    instance.ModelXmlPath;
                return false;
            }

            modelElement = resolvedModelElement;
            return true;
        }

        private static string BuildCrossRigidGeneratedJointVmdPath(
            string branchKey)
            => Normalize(
                $"variantmeshes\\variantmeshdefinitions\\asset_editor\\cross_rigid\\joint_" +
                $"{ContentHash(branchKey).ToLowerInvariant()}.variantmeshdefinition");

        private static string BuildCrossRigidJointParentLocationKey(
            string rootVmdPath,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
            => string.Join(
                "\u001f",
                Normalize(rootVmdPath),
                BuildCrossRigidReferenceChainSignature(
                    descriptor.AnchorReferenceChain),
                descriptor.AnchorVmdPath,
                descriptor.ParentXmlPath);

        private static string BuildCrossRigidJointContextKey(
            string rootVmdPath,
            CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
            => string.Join(
                "\u001f",
                BuildCrossRigidJointParentLocationKey(
                    rootVmdPath,
                    descriptor),
                descriptor.CommonAncestorDimensions.Length == 0
                    ? string.Join(
                        ",",
                        descriptor.SlotIndices)
                    : string.Join(
                        "\u001e",
                        $"slots={string.Join(",", descriptor.SlotIndices)}",
                        $"dimensions={string.Join(
                            ",",
                            descriptor.CommonAncestorDimensions
                                .Select(dimension =>
                                    dimension.DimensionKey)
                                .OrderBy(
                                    key => key,
                                    StringComparer.Ordinal))}"));

        private static string
            BuildCrossRigidJointSelectedCombinationKey(
                CrossRigidJointAlwaysPresentRewriteDescriptor descriptor)
        {
            if (descriptor.CommonAncestorDimensions.Length == 0)
            {
                return BuildCrossRigidJointCombinationKey(
                    descriptor.SourceSelections
                        .Select(selection =>
                            new CrossRigidJointAlternative(
                                selection.SlotIndex,
                                selection.IsReference,
                                selection.AlternativeIndex))
                        .Distinct());
            }

            var dimensionKeys =
                descriptor.CommonAncestorDimensions
                    .Select(dimension =>
                        dimension.DimensionKey)
                    .ToHashSet(StringComparer.Ordinal);
            return BuildCrossRigidCommonAncestorCombinationKey(
                descriptor.SourceSelections
                    .Where(selection =>
                        dimensionKeys.Contains(
                            BuildCrossRigidJointSourceSelectionDimensionKey(
                                selection)))
                    .Select(selection =>
                        new CrossRigidJointDimensionAlternative(
                            BuildCrossRigidJointSourceSelectionDimensionKey(
                                selection),
                            selection.IsReference,
                            selection.AlternativeIndex))
                    .Distinct());
        }

        private static string BuildCrossRigidJointCombinationKey(
            IEnumerable<CrossRigidJointAlternative> alternatives)
            => string.Join(
                "|",
                alternatives
                    .OrderBy(alternative =>
                        alternative.SlotIndex)
                    .Select(alternative =>
                        $"{alternative.SlotIndex}:" +
                        $"{(alternative.IsReference ? "r" : "m")}" +
                        $"{alternative.AlternativeIndex}"));

        private static string
            BuildCrossRigidCommonAncestorCombinationKey(
                IEnumerable<CrossRigidJointDimensionAlternative>
                    alternatives)
            => string.Join(
                "|",
                alternatives
                    .OrderBy(
                        alternative =>
                            alternative.DimensionKey,
                        StringComparer.Ordinal)
                    .Select(alternative =>
                        $"{alternative.DimensionKey}:" +
                        $"{(alternative.IsReference ? "r" : "m")}" +
                        $"{alternative.AlternativeIndex}"));

        private static bool TryGetCrossRigidSourceVmdDocument(
            BatchState state,
            string vmdPathValue,
            Dictionary<string, XmlDocument> cache,
            out XmlDocument document,
            out string reason)
        {
            var vmdPath = Normalize(vmdPathValue);
            if (cache.TryGetValue(vmdPath, out document!))
            {
                reason = string.Empty;
                return true;
            }

            var container = FindGameplayTraversalContainer(
                state,
                state.Source,
                GetGameplayTraversalContainers(state),
                vmdPath);
            var file = container?.FindFile(vmdPath);
            if (container == null || file == null)
            {
                document = null!;
                reason =
                    $"Referenced VMD could not be resolved: {vmdPath}";
                return false;
            }

            try
            {
                document = LoadXml(file);
                cache[vmdPath] = document;
                reason = string.Empty;
                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or
                XmlException or
                FormatException or
                ArgumentException)
            {
                document = null!;
                reason =
                    $"Referenced VMD could not be parsed: " +
                    $"{vmdPath} ({ex.Message})";
                return false;
            }
        }

        private static XmlDocument CloneXmlDocument(
            XmlDocument source)
        {
            var clone = new XmlDocument();
            clone.LoadXml(source.OuterXml);
            return clone;
        }

        private static string BuildCrossRigidConsumedOccurrenceKey(
            string rootVmdPath,
            CrossRigidVisualInstance instance)
            => string.Join(
                "\u001f",
                Normalize(rootVmdPath),
                BuildCrossRigidOccurrenceProvenanceSignature(
                    [instance]));

        private static string BuildCrossRigidGeneratedVmdBranchKey(
            string rootVmdPath,
            IReadOnlyList<CrossRigidVmdReferenceHop> prefixHops)
            => string.Join(
                "\u001f",
                Normalize(rootVmdPath),
                string.Join(
                    "\u001e",
                    prefixHops.Select(hop => string.Join(
                        "|",
                        Normalize(hop.OwnerVmdPath),
                        hop.ReferenceXmlPath,
                        Normalize(hop.ReferencedVmdPath)))));

        private static string BuildCrossRigidGeneratedVmdPath(
            string branchKey)
            => Normalize(
                $"variantmeshes\\variantmeshdefinitions\\asset_editor\\cross_rigid\\" +
                $"{ContentHash(branchKey).ToLowerInvariant()}.variantmeshdefinition");

        private static bool TryBuildCrossRigidGeneratedPayload(
            BatchState state,
            CrossRigidMergeAnalysisEntry plan,
            IReadOnlyList<IPackFileContainer> traversalContainers,
            Dictionary<string, RmvFile> rigidCache,
            Dictionary<string, CrossRigidAnalysisComponent>
                sourceComponentCache,
            out string reason)
        {
            reason = string.Empty;
            var buildTimer = Stopwatch.GetTimestamp();
            var generatedRigidPath =
                BuildCrossRigidGeneratedRigidPath(
                    plan.GeneratedPayloadId);
            var generatedWsModelPath =
                BuildCrossRigidGeneratedWsModelPath(
                    plan.GeneratedPayloadId);

            if (state.Source.ContainsFile(generatedRigidPath) ||
                state.Source.ContainsFile(generatedWsModelPath) ||
                state.Output.ContainsFile(generatedRigidPath) ||
                state.Output.ContainsFile(generatedWsModelPath))
            {
                reason =
                    "deterministic generated asset path already exists in the input/output pack";
                return false;
            }

            try
            {
                var componentsByWsModel =
                    new Dictionary<string, CrossRigidAnalysisComponent>(
                        StringComparer.OrdinalIgnoreCase);
                foreach (var wsModelPathValue in plan.SourceInstances
                             .Select(instance => instance.WsModelPath)
                             .Distinct(StringComparer.OrdinalIgnoreCase))
                {
                    var wsModelPath = Normalize(wsModelPathValue);
                    if (!sourceComponentCache.TryGetValue(
                            wsModelPath,
                            out var component))
                    {
                        if (!TryBuildCrossRigidAnalysisComponent(
                                state,
                                plan.VmdPath,
                                wsModelPath,
                                traversalContainers,
                                rigidCache,
                                out component,
                                out var componentReason))
                        {
                            reason =
                                $"{wsModelPath}: {componentReason}";
                            return false;
                        }

                        sourceComponentCache[wsModelPath] = component;
                    }

                    componentsByWsModel[wsModelPath] =
                        component;
                }

                AddCrossRigidTimingDuration(
                    state,
                    "Emit payload: resolve source components",
                    Stopwatch.GetElapsedTime(buildTimer));
                buildTimer = Stopwatch.GetTimestamp();
                var components = componentsByWsModel.Values
                    .OrderBy(
                        component => component.WsModelPath,
                        StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                if (components.Length < 2)
                {
                    reason =
                        "fewer than two distinct source WSModels remain";
                    return false;
                }

                if (components
                        .Select(component =>
                            component.TopologyIdentity)
                        .Distinct(StringComparer.Ordinal)
                        .Count() != 1)
                {
                    reason =
                        "source WSModel non-material topology is no longer identical";
                    return false;
                }

                if (!AreCrossRigidRigidHeadersCompatible(
                        components,
                        out reason))
                {
                    return false;
                }

                var representative = components[0];
                var generatedLodCount = plan.Lods.Length;
                var generatedModels = new RmvModel[generatedLodCount][];
                var generatedAssignments = new string[generatedLodCount][];

                for (var generatedLodIndex = 0;
                     generatedLodIndex < generatedLodCount;
                     generatedLodIndex++)
                {
                    var lodPlan = plan.Lods[generatedLodIndex];
                    if (lodPlan.LodIndex != generatedLodIndex)
                    {
                        reason =
                            $"generated LOD plan index mismatch: expected {generatedLodIndex}, " +
                            $"found {lodPlan.LodIndex}";
                        return false;
                    }

                    var sourceLodByWsModel =
                        lodPlan.SourceLodSelections.ToDictionary(
                            selection => Normalize(selection.WsModelPath),
                            selection => selection.SourceLodIndex,
                            StringComparer.OrdinalIgnoreCase);
                    var sourceParts =
                        new List<CrossRigidGeneratedSourcePart>();
                    for (var instanceIndex = 0;
                         instanceIndex < plan.SourceInstances.Length;
                         instanceIndex++)
                    {
                        var instance =
                            plan.SourceInstances[instanceIndex];
                        var wsModelPath =
                            Normalize(instance.WsModelPath);
                        if (!sourceLodByWsModel.TryGetValue(
                                wsModelPath,
                                out var sourceLodIndex))
                        {
                            continue;
                        }

                        var component =
                            componentsByWsModel[wsModelPath];
                        if (sourceLodIndex < 0 ||
                            sourceLodIndex >=
                            component.Rigid.ModelList.Length)
                        {
                            reason =
                                $"generated LOD {generatedLodIndex} has invalid source LOD " +
                                $"{sourceLodIndex} for {wsModelPath}";
                            return false;
                        }

                        var models =
                            component.Rigid.ModelList[sourceLodIndex];
                        var assignments =
                            component.MaterialAssignments[sourceLodIndex];

                        for (var partIndex = 0;
                             partIndex < models.Length;
                             partIndex++)
                        {
                            var mergeIdentity =
                                GetCrossRigidSourcePartMergeIdentity(
                                    state,
                                    component.RigidPath,
                                    sourceLodIndex,
                                    partIndex,
                                    models[partIndex],
                                    assignments[partIndex]);

                            sourceParts.Add(
                                new CrossRigidGeneratedSourcePart(
                                    instanceIndex,
                                    component.WsModelPath,
                                    component.RigidPath,
                                    partIndex,
                                    models[partIndex],
                                    assignments[partIndex],
                                    mergeIdentity));
                        }
                    }

                    var outputModels = new List<RmvModel>();
                    var outputMaterials = new List<string>();
                    foreach (var identityGroup in sourceParts
                                 .GroupBy(
                                     part => part.MergeIdentity,
                                     StringComparer.Ordinal)
                                 .OrderBy(
                                     group => group.Key,
                                     StringComparer.Ordinal))
                    {
                        foreach (var bin in
                                 PartitionCrossRigidGeneratedParts(
                                     identityGroup.ToArray()))
                        {
                            var orderedBin = bin
                                .OrderBy(part =>
                                    part.InstanceIndex)
                                .ThenBy(
                                    part => part.WsModelPath,
                                    StringComparer.OrdinalIgnoreCase)
                                .ThenBy(part =>
                                    part.PartIndex)
                                .ToArray();
                            outputModels.Add(
                                MergeRmvModels(
                                    orderedBin
                                        .Select(part => part.Model)
                                        .ToArray()));
                            outputMaterials.Add(
                                orderedBin
                                    .OrderBy(
                                        part => Normalize(
                                            part.MaterialPath),
                                        StringComparer.OrdinalIgnoreCase)
                                    .ThenBy(part =>
                                        part.InstanceIndex)
                                    .First()
                                    .MaterialPath);
                        }
                    }

                    if (outputModels.Count !=
                        lodPlan.OutputDrawsAfterCrossRigidMerge)
                    {
                        reason =
                            $"LOD {generatedLodIndex} emitted {outputModels.Count} draw(s), " +
                            $"but analysis selected {lodPlan.OutputDrawsAfterCrossRigidMerge}";
                        return false;
                    }

                    generatedModels[generatedLodIndex] =
                        outputModels.ToArray();
                    generatedAssignments[generatedLodIndex] =
                        outputMaterials.ToArray();
                }

                var generatedVersion =
                    components
                        .Select(component =>
                            component.Rigid.Header.Version)
                        .Max();
                var header = representative.Rigid.Header;
                header.Version = generatedVersion;
                header.LodCount = (uint)generatedLodCount;
                var lodHeaderFactory =
                    LodHeaderFactory.Create();
                var generatedRigid = new RmvFile
                {
                    Header = header,
                    LodHeaders = plan.Lods
                        .Select((lod, generatedLodIndex) =>
                        {
                            var representativeSelection =
                                lod.SourceLodSelections.FirstOrDefault(
                                    selection =>
                                        selection.WsModelPath.Equals(
                                            representative.WsModelPath,
                                            StringComparison.OrdinalIgnoreCase));
                            var sourceHeaderIndex =
                                representativeSelection?.SourceLodIndex ??
                                Math.Min(
                                    lod.ScenarioLodIndex,
                                    representative.Rigid.LodHeaders.Length - 1);
                            var generatedLodHeader =
                                lodHeaderFactory.CreateFromBase(
                                    generatedVersion,
                                    representative.Rigid.LodHeaders[
                                        sourceHeaderIndex],
                                    (uint)generatedLodIndex);
                            generatedLodHeader.QualityLvl =
                                lod.QualityLevel;
                            generatedLodHeader.LodCameraDistance =
                                lod.CameraDistance;
                            return generatedLodHeader;
                        })
                        .ToArray(),
                    ModelList = generatedModels,
                };
                generatedRigid.RecalculateOffsets();
                AddCrossRigidTimingDuration(
                    state,
                    "Emit payload: assemble and merge LOD geometry",
                    Stopwatch.GetElapsedTime(buildTimer));
                buildTimer = Stopwatch.GetTimestamp();

                // Round-trip once before storing the generated RMV so the new asset owns
                // independent model/material/vertex objects. The source rigids remain
                // untouched by later geometry optimization.
                var factory = ModelFactory.Create();
                generatedRigid = factory.Load(
                    factory.Save(
                        generatedRigid,
                        validateByReloading: false,
                        logProgress: false));
                AddCrossRigidTimingDuration(
                    state,
                    "Emit payload: RMV ownership round-trip",
                    Stopwatch.GetElapsedTime(buildTimer));
                buildTimer = Stopwatch.GetTimestamp();

                var generatedWsDocument = new XmlDocument();
                generatedWsDocument.LoadXml(
                    representative.WsDocument.OuterXml);
                var geometryNode =
                    generatedWsDocument.SelectSingleNode(
                        "/model/geometry");
                if (geometryNode == null)
                {
                    reason =
                        "representative WSModel has no geometry node";
                    return false;
                }

                geometryNode.InnerText = generatedRigidPath;
                RewriteWsMaterialAssignments(
                    generatedWsDocument,
                    generatedAssignments);
                if (!TryReadWsMaterialAssignments(
                        generatedWsDocument,
                        generatedRigid,
                        out _,
                        out var assignmentReason))
                {
                    reason =
                        $"generated WSModel material table is invalid ({assignmentReason})";
                    return false;
                }

                state.RigidModels[generatedRigidPath] =
                    generatedRigid;
                state.WsDocuments[generatedWsModelPath] =
                    generatedWsDocument;
                state.ModifiedRigids.Add(
                    generatedRigidPath);
                state.ModifiedWsModels.Add(
                    generatedWsModelPath);
                state.CrossRigidGeneratedPayloadIds.Add(
                    plan.GeneratedPayloadId);
                state.CrossRigidGeneratedRigidPaths.Add(
                    generatedRigidPath);
                state.CrossRigidGeneratedWsModelPaths.Add(
                    generatedWsModelPath);
                AddCrossRigidTimingDuration(
                    state,
                    "Emit payload: generate and validate WSModel",
                    Stopwatch.GetElapsedTime(buildTimer));
                return true;
            }
            catch (Exception ex) when (
                ex is InvalidDataException or
                InvalidOperationException or
                ArgumentException or
                FormatException or
                OverflowException)
            {
                reason = ex.Message;
                return false;
            }
        }

        private static bool AreCrossRigidRigidHeadersCompatible(
            IReadOnlyList<CrossRigidAnalysisComponent> components,
            out string reason)
        {
            reason = string.Empty;
            if (components.Count == 0)
            {
                reason = "no rigid components were supplied";
                return false;
            }

            var baseline = components[0].Rigid;
            var baselineSkeleton =
                baseline.Header.SkeletonName;
            foreach (var component in components)
            {
                var rigid = component.Rigid;
                if (!string.Equals(
                        rigid.Header.SkeletonName,
                        baselineSkeleton,
                        StringComparison.OrdinalIgnoreCase))
                {
                    reason =
                        "source rigid skeletons differ";
                    return false;
                }

                if (rigid.ModelList.Length == 0 ||
                    rigid.LodHeaders.Length == 0 ||
                    rigid.ModelList.Length !=
                        rigid.LodHeaders.Length)
                {
                    reason =
                        "source rigid LOD model/header counts are inconsistent";
                    return false;
                }
            }

            return true;
        }

        private static IReadOnlyList<
                IReadOnlyList<CrossRigidGeneratedSourcePart>>
            PartitionCrossRigidGeneratedParts(
                IReadOnlyList<CrossRigidGeneratedSourcePart> parts)
        {
            var bins =
                new List<List<CrossRigidGeneratedSourcePart>>();
            var vertexCounts = new List<int>();

            foreach (var part in parts
                         .OrderByDescending(item =>
                             item.Model.Mesh.VertexList.Length)
                         .ThenBy(
                             item => item.WsModelPath,
                             StringComparer.OrdinalIgnoreCase)
                         .ThenBy(item =>
                             item.InstanceIndex)
                         .ThenBy(item =>
                             item.PartIndex))
            {
                var vertexCount =
                    part.Model.Mesh.VertexList.Length;
                if (vertexCount > ushort.MaxValue)
                {
                    bins.Add([part]);
                    vertexCounts.Add(vertexCount);
                    continue;
                }

                var placed = false;
                for (var binIndex = 0;
                     binIndex < bins.Count;
                     binIndex++)
                {
                    if (vertexCounts[binIndex] >
                            ushort.MaxValue ||
                        vertexCounts[binIndex] +
                            vertexCount >
                            ushort.MaxValue)
                    {
                        continue;
                    }

                    bins[binIndex].Add(part);
                    vertexCounts[binIndex] +=
                        vertexCount;
                    placed = true;
                    break;
                }

                if (!placed)
                {
                    bins.Add([part]);
                    vertexCounts.Add(vertexCount);
                }
            }

            return bins;
        }


        private static string BuildCrossRigidGeneratedRigidPath(
            string payloadId)
            => Normalize(
                $"variantmeshes\\wh_variantmodels\\asset_editor\\cross_rigid\\{payloadId.ToLowerInvariant()}.rigid_model_v2");

        private static string BuildCrossRigidGeneratedWsModelPath(
            string payloadId)
            => Normalize(
                $"variantmeshes\\wh_variantmodels\\asset_editor\\cross_rigid\\{payloadId.ToLowerInvariant()}.wsmodel");

        private static void RecordCrossRigidEmissionSkip(
            BatchState state,
            string reason,
            string example)
        {
            state.CrossRigidEmissionSkipCounts[reason] =
                state.CrossRigidEmissionSkipCounts
                    .GetValueOrDefault(reason) + 1;
            if (!state.CrossRigidEmissionSkipExamples.TryGetValue(
                    reason,
                    out var examples))
            {
                examples = [];
                state.CrossRigidEmissionSkipExamples[reason] =
                    examples;
            }

            if (examples.Count < 12 &&
                !examples.Contains(
                    example,
                    StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private static Dictionary<
                CrossRigidWsModelOccurrenceKey,
                double>
            BuildCrossRigidRewriteCoverageByOccurrence(
                BatchState state)
        {
            var coverage = new Dictionary<
                CrossRigidWsModelOccurrenceKey,
                double>();
            foreach (var plan in state.CrossRigidMergeAnalysisEntries)
            {
                foreach (var instance in plan.SourceInstances.Distinct())
                {
                    var key = new CrossRigidWsModelOccurrenceKey(
                        plan.VmdPath,
                        instance.AttachmentIdentity,
                        instance.WsModelPath);
                    coverage[key] = Math.Clamp(
                        coverage.GetValueOrDefault(key) +
                        plan.AggregatedConfigurationProbability,
                        0.0,
                        1.0);
                }
            }

            return coverage;
        }

        private static bool IsCrossRigidSourceRigidFullyCovered(
            BatchState state,
            GameplayMeshDependencyIndex dependencyIndex,
            string rigidPath,
            IReadOnlyDictionary<
                CrossRigidWsModelOccurrenceKey,
                double> rewriteCoverage,
            out string[] wsConsumers)
        {
            wsConsumers = dependencyIndex.WsModelConsumersByRigid
                .GetValueOrDefault(rigidPath)?
                .OrderBy(
                    path => path,
                    StringComparer.OrdinalIgnoreCase)
                .ToArray() ?? [];
            if (wsConsumers.Length == 0 ||
                dependencyIndex.IsAssetAffectedByIncompleteRoot(rigidPath))
            {
                return false;
            }

            if (dependencyIndex.DirectConsumersByRigid.TryGetValue(
                    rigidPath,
                    out var directConsumers) &&
                directConsumers.Count != 0)
            {
                return false;
            }

            return wsConsumers.All(wsModelPath =>
                IsCrossRigidWsModelFullyCovered(
                    state,
                    dependencyIndex,
                    wsModelPath,
                    rewriteCoverage));
        }

        private static bool IsCrossRigidWsModelFullyCovered(
            BatchState state,
            GameplayMeshDependencyIndex dependencyIndex,
            string wsModelPathValue,
            IReadOnlyDictionary<
                CrossRigidWsModelOccurrenceKey,
                double> rewriteCoverage)
        {
            var wsModelPath = Normalize(wsModelPathValue);
            if (wsModelPath.Length == 0 ||
                dependencyIndex.IsAssetAffectedByIncompleteRoot(
                    wsModelPath))
            {
                return false;
            }

            var occurrences =
                state.CrossRigidWsModelOccurrenceProbabilities
                    .Where(entry =>
                        entry.Key.WsModelPath.Equals(
                            wsModelPath,
                            StringComparison.OrdinalIgnoreCase))
                    .ToArray();
            if (occurrences.Length == 0)
                return false;

            var occurrenceRoots = occurrences
                .Select(entry => entry.Key.VmdPath)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            if (dependencyIndex.GetRootsForAsset(wsModelPath)
                .Any(root => !occurrenceRoots.Contains(root)))
            {
                return false;
            }

            return occurrences.All(entry =>
                rewriteCoverage.GetValueOrDefault(entry.Key) >=
                entry.Value - AtlasValueGateExpectedDrawEpsilon);
        }

        private static double
            CalculateExpectedCrossRigidPayloadResidentProbability(
                BatchState state,
                IReadOnlyList<CrossRigidMergeAnalysisEntry> rewritePlans)
        {
            var model = state.ArmyResidencyModel;
            if (model == null || rewritePlans.Count == 0)
                return 0;

            var probabilityByVmd = rewritePlans
                .GroupBy(
                    plan => plan.VmdPath,
                    StringComparer.OrdinalIgnoreCase)
                .ToDictionary(
                    group => group.Key,
                    group => Math.Clamp(
                        group.Sum(plan =>
                            plan.AggregatedConfigurationProbability),
                        0.0,
                        1.0),
                    StringComparer.OrdinalIgnoreCase);
            var roots = probabilityByVmd.Keys.ToArray();
            var relevantUnitIds = GetRelevantArmyUnitIds(
                model,
                Array.Empty<string>(),
                roots);
            var relevantCultures = GetRelevantArmyCultures(
                model,
                Array.Empty<string>(),
                roots,
                relevantUnitIds);
            if (relevantUnitIds.Count == 0 ||
                relevantCultures.Count == 0)
            {
                return 0;
            }

            var probabilitiesByCulture =
                new Dictionary<string, double>(
                    StringComparer.OrdinalIgnoreCase);
            foreach (var culture in relevantCultures)
            {
                if (!model.UnitsByCultureAndCategory.TryGetValue(
                        culture,
                        out var unitsByCategory))
                {
                    continue;
                }

                var notResidentProbability = 1.0;
                foreach (var (category, slotCount) in
                         model.Scenario.ArmySlotTemplate)
                {
                    if (!unitsByCategory.TryGetValue(
                            category,
                            out var cultureUnits) ||
                        cultureUnits.Count == 0)
                    {
                        continue;
                    }

                    double perSlotPresenceProbability = 0;
                    foreach (var unitId in
                             EnumerateRelevantArmyUnitIds(
                                 cultureUnits,
                                 relevantUnitIds))
                    {
                        if (!model.DirectVmdsByUnitAndRole.TryGetValue(
                                unitId,
                                out var vmdsByRole))
                        {
                            continue;
                        }

                        var notPresentAcrossRoles = 1.0;
                        foreach (var (role, directVmds) in vmdsByRole)
                        {
                            if (directVmds.Count == 0)
                                continue;

                            double perEntityPresenceProbability = 0;
                            foreach (var vmdPath in directVmds)
                            {
                                if (!probabilityByVmd.TryGetValue(
                                        vmdPath,
                                        out var configurationProbability))
                                {
                                    continue;
                                }

                                perEntityPresenceProbability +=
                                    configurationProbability /
                                    directVmds.Count;
                            }

                            perEntityPresenceProbability = Math.Clamp(
                                perEntityPresenceProbability,
                                0.0,
                                1.0);
                            if (perEntityPresenceProbability <= 0)
                                continue;

                            var entityCount = Math.Max(
                                1,
                                model.EntityCountByUnitAndRole
                                    .GetValueOrDefault(unitId)?
                                    .GetValueOrDefault(role, 1) ?? 1);
                            notPresentAcrossRoles *= Math.Pow(
                                1.0 - perEntityPresenceProbability,
                                entityCount);
                        }

                        var unitCardPresenceProbability =
                            1.0 - notPresentAcrossRoles;
                        if (unitCardPresenceProbability <= 0)
                            continue;

                        perSlotPresenceProbability +=
                            unitCardPresenceProbability /
                            cultureUnits.Count;
                    }

                    perSlotPresenceProbability = Math.Clamp(
                        perSlotPresenceProbability,
                        0.0,
                        1.0);
                    notResidentProbability *= Math.Pow(
                        1.0 - perSlotPresenceProbability,
                        slotCount);
                }

                probabilitiesByCulture[culture] = Math.Clamp(
                    1.0 - notResidentProbability,
                    0.0,
                    1.0);
            }

            return CombineBattleResidentProbabilities(
                probabilitiesByCulture,
                model.PlayerCultureWeights,
                model.OpponentCultureWeights);
        }

        private static CrossRigidAttachmentLocalExpansionResult
            GetCrossRigidAttachmentLocalConfigurationsForVmd(
                BatchState state,
                string vmdPathValue,
                Dictionary<
                    string,
                    CrossRigidAttachmentLocalExpansionResult> cache,
                HashSet<string> visiting)
        {
            var vmdPath = Normalize(vmdPathValue);
            if (cache.TryGetValue(vmdPath, out var cached))
                return cached;
            if (!visiting.Add(vmdPath))
            {
                return CrossRigidAttachmentLocalExpansionResult.Failed(
                    $"Cross-rigid VMD reference cycle detected ({vmdPath})");
            }

            try
            {
                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    vmdPath);
                var file = container?.FindFile(vmdPath);
                if (container == null ||
                    file == null ||
                    !TryGetVmdForTraversal(
                        state,
                        container,
                        vmdPath,
                        file,
                        out var vmd))
                {
                    var failure =
                        CrossRigidAttachmentLocalExpansionResult.Failed(
                            "Cross-rigid VMD could not be resolved");
                    cache[vmdPath] = failure;
                    return failure;
                }

                var result =
                    ExpandCrossRigidAttachmentLocalConfigurations(
                        state,
                        vmd,
                        vmdPath,
                        "<root>",
                        "<always>",
                        "/VARIANT_MESH",
                        cache,
                        visiting);
                cache[vmdPath] = result;
                return result;
            }
            finally
            {
                visiting.Remove(vmdPath);
            }
        }

        private static CrossRigidAttachmentLocalExpansionResult
            ExpandCrossRigidAttachmentLocalConfigurations(
                BatchState state,
                VariantMesh mesh,
                string currentVmdPath,
                string attachmentIdentity,
                string activationSignature,
                string xmlPath,
                Dictionary<
                    string,
                    CrossRigidAttachmentLocalExpansionResult> cache,
                HashSet<string> visiting)
        {
            var result = new Dictionary<
                string,
                List<CrossRigidVisualConfiguration>>(
                StringComparer.Ordinal);

            if (!string.IsNullOrWhiteSpace(mesh.ModelReference))
            {
                var modelPath = Normalize(mesh.ModelReference);
                if (Path.GetExtension(modelPath)
                        .Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) &&
                    FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        GetGameplayTraversalContainers(state),
                        modelPath) != null)
                {
                    var instance = new CrossRigidVisualInstance(
                        modelPath,
                        attachmentIdentity,
                        Normalize(currentVmdPath),
                        xmlPath,
                        activationSignature,
                        [],
                        string.IsNullOrWhiteSpace(mesh.ImposterModel)
                            ? string.Empty
                            : Normalize(mesh.ImposterModel),
                        !string.IsNullOrWhiteSpace(mesh.DecalDiffuse),
                        !string.IsNullOrWhiteSpace(mesh.DecalNormal),
                        (mesh.MetaDataList?.Count ?? 0) != 0);
                    result[attachmentIdentity] =
                    [
                        new CrossRigidVisualConfiguration(
                            1.0,
                            attachmentIdentity,
                            [instance],
                            [
                                new CrossRigidVisualOccurrenceSet(
                                    1.0,
                                    [instance]),
                            ]),
                    ];
                }
            }

            var slots = mesh.ChildSlots ?? [];
            for (var slotIndex = 0;
                 slotIndex < slots.Count;
                 slotIndex++)
            {
                var slot = slots[slotIndex];
                var slotProbability =
                    ParseVmdSlotProbability(slot.Probability);
                var childMeshes = slot.ChildMeshes ?? [];
                var childReferences = slot.ChildReferences ?? [];
                var alternativeCount =
                    childMeshes.Count + childReferences.Count;
                if (alternativeCount == 0 ||
                    slotProbability <= 0)
                {
                    continue;
                }

                var childAttachmentIdentity =
                    BuildCrossRigidAttachmentIdentity(
                        attachmentIdentity,
                        mesh.use_different_attach_point_parts,
                        slot);
                var isBranching =
                    slotProbability <
                        1.0 -
                        AtlasValueGateExpectedDrawEpsilon ||
                    alternativeCount > 1;
                var alternativeMaps = new List<
                    IReadOnlyDictionary<
                        string,
                        IReadOnlyList<CrossRigidVisualConfiguration>>>();

                for (var childIndex = 0;
                     childIndex < childMeshes.Count;
                     childIndex++)
                {
                    var childXmlPath =
                        $"{xmlPath}/SLOT[{slotIndex + 1}]/VARIANT_MESH[{childIndex + 1}]";
                    var childActivationSignature =
                        isBranching
                            ? AppendCrossRigidActivationToken(
                                activationSignature,
                                $"{currentVmdPath}:{xmlPath}/slot={slotIndex + 1}/mesh={childIndex + 1}")
                            : activationSignature;
                    var childExpansion =
                        ExpandCrossRigidAttachmentLocalConfigurations(
                            state,
                            childMeshes[childIndex],
                            currentVmdPath,
                            childAttachmentIdentity,
                            childActivationSignature,
                            childXmlPath,
                            cache,
                            visiting);
                    if (childExpansion.FailureReason != null)
                        return childExpansion;
                    alternativeMaps.Add(
                        childExpansion.ConfigurationsByAttachment);
                }

                for (var referenceIndex = 0;
                     referenceIndex < childReferences.Count;
                     referenceIndex++)
                {
                    var reference = childReferences[referenceIndex];
                    if (string.IsNullOrWhiteSpace(reference.Reference))
                    {
                        return CrossRigidAttachmentLocalExpansionResult.Failed(
                            "Cross-rigid child VMD reference is empty");
                    }

                    var referencedVmdPath =
                        Normalize(reference.Reference);
                    var referenceXmlPath =
                        $"{xmlPath}/SLOT[{slotIndex + 1}]/VARIANT_MESH_REFERENCE[{referenceIndex + 1}]";
                    var childActivationSignature =
                        isBranching
                            ? AppendCrossRigidActivationToken(
                                activationSignature,
                                $"{currentVmdPath}:{xmlPath}/slot={slotIndex + 1}/ref={referenceIndex + 1}")
                            : activationSignature;
                    var childExpansion =
                        GetCrossRigidAttachmentLocalConfigurationsForVmd(
                            state,
                            referencedVmdPath,
                            cache,
                            visiting);
                    if (childExpansion.FailureReason != null)
                        return childExpansion;

                    alternativeMaps.Add(
                        RebaseCrossRigidAttachmentLocalConfigurations(
                            childExpansion.ConfigurationsByAttachment,
                            childAttachmentIdentity,
                            childActivationSignature,
                            new CrossRigidVmdReferenceHop(
                                Normalize(currentVmdPath),
                                referenceXmlPath,
                                referencedVmdPath)));
                }

                var affectedAttachments = alternativeMaps
                    .SelectMany(map => map.Keys)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray();
                foreach (var affectedAttachment in
                         affectedAttachments)
                {
                    var slotConfigurations =
                        new List<CrossRigidVisualConfiguration>();
                    if (slotProbability < 1.0)
                    {
                        var absentProbability =
                            1.0 - slotProbability;
                        slotConfigurations.Add(
                            new CrossRigidVisualConfiguration(
                                absentProbability,
                                affectedAttachment,
                                [],
                                [
                                    new CrossRigidVisualOccurrenceSet(
                                        absentProbability,
                                        []),
                                ]));
                    }

                    var alternativeWeight =
                        slotProbability / alternativeCount;
                    foreach (var alternativeMap in alternativeMaps)
                    {
                        if (alternativeMap.TryGetValue(
                                affectedAttachment,
                                out var alternativeConfigurations))
                        {
                            slotConfigurations.AddRange(
                                alternativeConfigurations.Select(
                                    configuration =>
                                        ScaleCrossRigidVisualConfiguration(
                                            configuration,
                                            alternativeWeight)));
                        }
                        else
                        {
                            slotConfigurations.Add(
                                new CrossRigidVisualConfiguration(
                                    alternativeWeight,
                                    affectedAttachment,
                                    [],
                                    [
                                        new CrossRigidVisualOccurrenceSet(
                                            alternativeWeight,
                                            []),
                                    ]));
                        }
                    }

                    slotConfigurations =
                        MergeEquivalentCrossRigidVisualConfigurations(
                            slotConfigurations);
                    List<CrossRigidVisualConfiguration>
                        currentConfigurations =
                            result.TryGetValue(
                                affectedAttachment,
                                out var existing)
                                ? existing
                                :
                                [
                                    new CrossRigidVisualConfiguration(
                                        1.0,
                                        affectedAttachment,
                                        [],
                                        [
                                            new CrossRigidVisualOccurrenceSet(
                                                1.0,
                                                []),
                                        ]),
                                ];
                    var combined =
                        CombineCrossRigidAttachmentLocalConfigurations(
                            currentConfigurations,
                            slotConfigurations,
                            affectedAttachment,
                            out var limitExceeded);
                    if (limitExceeded)
                    {
                        return CrossRigidAttachmentLocalExpansionResult.Failed(
                            $"Cross-rigid attachment-local configuration limit exceeded " +
                            $"({MaxExactVisualConfigurations:N0} unique configurations at " +
                            $"{affectedAttachment})");
                    }

                    result[affectedAttachment] = combined;
                }
            }

            return new CrossRigidAttachmentLocalExpansionResult(
                result.ToDictionary(
                    entry => entry.Key,
                    entry => (IReadOnlyList<CrossRigidVisualConfiguration>)
                        entry.Value,
                    StringComparer.Ordinal),
                null);
        }

        private static IReadOnlyDictionary<
                string,
                IReadOnlyList<CrossRigidVisualConfiguration>>
            RebaseCrossRigidAttachmentLocalConfigurations(
                IReadOnlyDictionary<
                    string,
                    IReadOnlyList<CrossRigidVisualConfiguration>>
                    configurationsByAttachment,
                string attachmentIdentity,
                string activationSignaturePrefix,
                CrossRigidVmdReferenceHop referenceHop)
        {
            var rebased = new Dictionary<
                string,
                IReadOnlyList<CrossRigidVisualConfiguration>>(
                StringComparer.Ordinal);
            foreach (var (relativeAttachment, configurations) in
                     configurationsByAttachment)
            {
                var rebasedAttachment =
                    RebaseCrossRigidAttachmentIdentity(
                        relativeAttachment,
                        attachmentIdentity);
                rebased[rebasedAttachment] = configurations
                    .Select(configuration =>
                    {
                        var instances = configuration.Instances
                            .Select(instance =>
                                RebaseCrossRigidVisualInstance(
                                    instance,
                                    attachmentIdentity,
                                    activationSignaturePrefix,
                                    referenceHop))
                            .ToArray();
                        var occurrenceSets = configuration.OccurrenceSets
                            .Select(set =>
                                new CrossRigidVisualOccurrenceSet(
                                    set.Probability,
                                    set.Instances
                                        .Select(instance =>
                                            RebaseCrossRigidVisualInstance(
                                                instance,
                                                attachmentIdentity,
                                                activationSignaturePrefix,
                                                referenceHop))
                                        .ToArray()))
                            .ToArray();
                        return new CrossRigidVisualConfiguration(
                            configuration.Probability,
                            rebasedAttachment,
                            instances,
                            occurrenceSets);
                    })
                    .ToArray();
            }

            return rebased;
        }

        private static List<CrossRigidVisualConfiguration>
            CombineCrossRigidAttachmentLocalConfigurations(
                IReadOnlyList<CrossRigidVisualConfiguration> leftConfigurations,
                IReadOnlyList<CrossRigidVisualConfiguration> rightConfigurations,
                string attachmentIdentity,
                out bool uniqueConfigurationLimitExceeded)
        {
            uniqueConfigurationLimitExceeded = false;
            var merged = new Dictionary<
                string,
                CrossRigidVisualConfiguration>(
                StringComparer.Ordinal);

            foreach (var left in leftConfigurations)
            {
                foreach (var right in rightConfigurations)
                {
                    var probability =
                        left.Probability * right.Probability;
                    if (probability <= 0)
                        continue;

                    var instances = left.Instances
                        .Concat(right.Instances)
                        .ToArray();
                    var occurrenceSets = new List<
                        CrossRigidVisualOccurrenceSet>();
                    foreach (var leftSet in left.OccurrenceSets)
                    {
                        foreach (var rightSet in right.OccurrenceSets)
                        {
                            var occurrenceProbability =
                                leftSet.Probability *
                                rightSet.Probability;
                            if (occurrenceProbability <= 0)
                                continue;

                            occurrenceSets.Add(
                                new CrossRigidVisualOccurrenceSet(
                                    occurrenceProbability,
                                    leftSet.Instances
                                        .Concat(rightSet.Instances)
                                        .ToArray()));
                        }
                    }

                    var key =
                        BuildCrossRigidRenderedConfigurationSignature(
                            instances);
                    if (merged.TryGetValue(key, out var existing))
                    {
                        merged[key] = existing with
                        {
                            Probability =
                                existing.Probability + probability,
                            OccurrenceSets =
                                MergeCrossRigidVisualOccurrenceSets(
                                    existing.OccurrenceSets
                                        .Concat(occurrenceSets)),
                        };
                    }
                    else
                    {
                        merged[key] =
                            new CrossRigidVisualConfiguration(
                                probability,
                                attachmentIdentity,
                                instances,
                                MergeCrossRigidVisualOccurrenceSets(
                                    occurrenceSets));
                        if (merged.Count >
                            MaxExactVisualConfigurations)
                        {
                            uniqueConfigurationLimitExceeded = true;
                            return [];
                        }
                    }
                }
            }

            return merged.Values
                .Where(configuration => configuration.Probability > 0)
                .ToList();
        }

        private static List<CrossRigidVisualConfiguration>
            MergeEquivalentCrossRigidVisualConfigurations(
                IEnumerable<CrossRigidVisualConfiguration> configurations)
        {
            var merged = new Dictionary<
                string,
                CrossRigidVisualConfiguration>(
                StringComparer.Ordinal);
            foreach (var configuration in configurations)
            {
                if (configuration.Probability <= 0)
                    continue;

                var key = BuildCrossRigidRenderedConfigurationSignature(
                    configuration.Instances);
                if (merged.TryGetValue(key, out var existing))
                {
                    merged[key] = existing with
                    {
                        Probability =
                            existing.Probability +
                            configuration.Probability,
                        OccurrenceSets =
                            MergeCrossRigidVisualOccurrenceSets(
                                existing.OccurrenceSets.Concat(
                                    configuration.OccurrenceSets)),
                    };
                }
                else
                {
                    merged[key] = configuration with
                    {
                        OccurrenceSets =
                            MergeCrossRigidVisualOccurrenceSets(
                                configuration.OccurrenceSets),
                    };
                }
            }

            return merged.Values.ToList();
        }

        private static CrossRigidVisualConfiguration
            ScaleCrossRigidVisualConfiguration(
                CrossRigidVisualConfiguration configuration,
                double factor)
            => new(
                configuration.Probability * factor,
                configuration.AttachmentIdentity,
                configuration.Instances,
                configuration.OccurrenceSets
                    .Select(set =>
                        new CrossRigidVisualOccurrenceSet(
                            set.Probability * factor,
                            set.Instances))
                    .ToArray());

        private static CrossRigidVisualInstance
            RebaseCrossRigidVisualInstance(
                CrossRigidVisualInstance instance,
                string attachmentIdentity,
                string activationSignaturePrefix,
                CrossRigidVmdReferenceHop referenceHop)
            => instance with
            {
                AttachmentIdentity =
                    RebaseCrossRigidAttachmentIdentity(
                        instance.AttachmentIdentity,
                        attachmentIdentity),
                ActivationSignature =
                    RebaseCrossRigidActivationSignature(
                        instance.ActivationSignature,
                        activationSignaturePrefix),
                ReferenceChain =
                    new[] { referenceHop }
                        .Concat(instance.ReferenceChain)
                        .ToArray(),
            };

        private static string AppendCrossRigidActivationToken(
            string activationSignature,
            string token)
            => activationSignature.Equals(
                    "<always>",
                    StringComparison.Ordinal)
                ? token
                : string.Join(
                    "\u001f",
                    activationSignature,
                    token);

        private static string RebaseCrossRigidActivationSignature(
            string relativeSignature,
            string activationSignaturePrefix)
        {
            if (relativeSignature.Equals(
                    "<always>",
                    StringComparison.Ordinal))
            {
                return activationSignaturePrefix;
            }

            if (activationSignaturePrefix.Equals(
                    "<always>",
                    StringComparison.Ordinal))
            {
                return relativeSignature;
            }

            return string.Join(
                "\u001f",
                activationSignaturePrefix,
                relativeSignature);
        }

        private static IReadOnlyList<CrossRigidVisualOccurrenceSet>
            MergeCrossRigidVisualOccurrenceSets(
                IEnumerable<CrossRigidVisualOccurrenceSet> occurrenceSets)
        {
            var merged = new Dictionary<
                string,
                CrossRigidVisualOccurrenceSet>(
                StringComparer.Ordinal);
            foreach (var occurrenceSet in occurrenceSets)
            {
                if (occurrenceSet.Probability <= 0)
                    continue;

                var key =
                    BuildCrossRigidOccurrenceProvenanceSignature(
                        occurrenceSet.Instances);
                if (merged.TryGetValue(key, out var existing))
                {
                    merged[key] = existing with
                    {
                        Probability =
                            existing.Probability +
                            occurrenceSet.Probability,
                    };
                }
                else
                {
                    merged[key] = occurrenceSet;
                }
            }

            return merged.Values
                .OrderBy(
                    set =>
                        BuildCrossRigidOccurrenceProvenanceSignature(
                            set.Instances),
                    StringComparer.Ordinal)
                .ToArray();
        }

        private static string BuildCrossRigidOccurrenceProvenanceSignature(
            IEnumerable<CrossRigidVisualInstance> instances)
            => string.Join(
                "\u001e",
                instances
                    .Select(instance => string.Join(
                        "\u001f",
                        instance.WsModelPath,
                        instance.DefiningVmdPath,
                        instance.ModelXmlPath,
                        instance.ActivationSignature,
                        string.Join(
                            "\u001d",
                            instance.ReferenceChain.Select(hop =>
                                $"{hop.OwnerVmdPath}|{hop.ReferenceXmlPath}|{hop.ReferencedVmdPath}"))))
                    .OrderBy(value => value, StringComparer.Ordinal));

        private static string BuildCrossRigidRenderedConfigurationSignature(
            IEnumerable<CrossRigidVisualInstance> instances)
            => string.Join(
                "\u001f",
                instances
                    .Select(instance => instance.WsModelPath)
                    .OrderBy(
                        path => path,
                        StringComparer.OrdinalIgnoreCase));

        private static string RebaseCrossRigidAttachmentIdentity(
            string relativeIdentity,
            string attachmentIdentity)
        {
            const string rootIdentity = "<root>";
            if (relativeIdentity.Equals(
                    rootIdentity,
                    StringComparison.Ordinal))
            {
                return attachmentIdentity;
            }

            if (relativeIdentity.StartsWith(
                    rootIdentity + "/",
                    StringComparison.Ordinal))
            {
                return attachmentIdentity +
                       relativeIdentity[rootIdentity.Length..];
            }

            return string.Join(
                "/",
                attachmentIdentity,
                relativeIdentity);
        }

        private static string BuildCrossRigidAttachmentIdentity(
            string parentIdentity,
            string? meshUsesDifferentAttachPointParts,
            SLOT slot)
        {
            var attachmentPoint = string.IsNullOrWhiteSpace(slot.AttachmentPoint)
                ? "<inherit>"
                : slot.AttachmentPoint.Trim().ToLowerInvariant();
            var meshPartsMode = string.IsNullOrWhiteSpace(
                    meshUsesDifferentAttachPointParts)
                ? "<default>"
                : meshUsesDifferentAttachPointParts.Trim().ToLowerInvariant();
            var slotPartsMode = string.IsNullOrWhiteSpace(
                    slot.use_different_attach_point_parts)
                ? "<default>"
                : slot.use_different_attach_point_parts.Trim().ToLowerInvariant();
            return string.Join(
                "/",
                parentIdentity,
                $"attach={attachmentPoint}",
                $"mesh_parts={meshPartsMode}",
                $"slot_parts={slotPartsMode}");
        }

        private static bool TryBuildCrossRigidAnalysisComponent(
            BatchState state,
            string vmdPath,
            string wsModelPathValue,
            IReadOnlyList<IPackFileContainer> traversalContainers,
            Dictionary<string, RmvFile> rigidCache,
            out CrossRigidAnalysisComponent component,
            out string reason)
        {
            component = null!;
            reason = string.Empty;
            var wsModelPath = Normalize(wsModelPathValue);
            var wsContainer = FindGameplayTraversalContainer(
                state,
                state.Source,
                traversalContainers,
                wsModelPath);
            var wsFile = wsContainer?.FindFile(wsModelPath);
            if (wsContainer == null || wsFile == null)
            {
                reason = "WSModel could not be resolved";
                return false;
            }

            XmlDocument wsDocument;
            if (!state.WsDocuments.TryGetValue(wsModelPath, out wsDocument!))
            {
                if (!TryGetWsDocumentForTraversal(
                        state,
                        wsContainer,
                        wsModelPath,
                        wsFile,
                        out wsDocument))
                {
                    reason = "WSModel could not be parsed";
                    return false;
                }
            }

            var rigidPath = Normalize(
                wsDocument.SelectSingleNode("/model/geometry")?.InnerText);
            if (rigidPath.Length == 0 ||
                !Path.GetExtension(rigidPath).Equals(
                    ".rigid_model_v2",
                    StringComparison.OrdinalIgnoreCase))
            {
                reason = "WSModel has no supported rigid geometry path";
                return false;
            }

            if (!rigidCache.TryGetValue(rigidPath, out var rigid))
            {
                var rigidContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    traversalContainers,
                    rigidPath);
                var rigidFile = rigidContainer?.FindFile(rigidPath);
                if (rigidContainer == null || rigidFile == null)
                {
                    reason = "Rigid geometry could not be resolved";
                    return false;
                }

                try
                {
                    rigid = ModelFactory.Create().Load(rigidFile.DataSource.ReadData());
                    rigidCache[rigidPath] = rigid;
                }
                catch (Exception ex) when (
                    ex is InvalidDataException or
                    InvalidOperationException or
                    ArgumentException or
                    FormatException)
                {
                    reason = $"Rigid geometry could not be parsed ({ex.Message})";
                    return false;
                }
            }

            if (!TryReadWsMaterialAssignments(
                    wsDocument,
                    rigid,
                    out var assignments,
                    out var assignmentReason,
                    allowUnreferencedMaterialEntries: true))
            {
                reason = $"WSModel material table is not structurally usable ({assignmentReason})";
                return false;
            }

            // A few modded WSModels retain obsolete LOD/part material rows
            // after the rigid's mesh topology was reduced. Those rows cannot
            // be sampled by the current rigid. Accept only this surplus in
            // cross-rigid source analysis: missing, blank, duplicate, or
            // malformed assignments still fail, and generated WSModels are
            // rewritten and validated with the exact active part count.
            var referencedMaterialCount =
                rigid.ModelList.Sum(lod => lod.Length);
            var authoredMaterialCount =
                wsDocument.SelectNodes("/model/materials/material")?.Count ?? 0;
            if (authoredMaterialCount > referencedMaterialCount)
            {
                RecordCrossRigidAnalysisDiagnostic(
                    state,
                    "Unused source WSModel material entries ignored",
                    $"{wsModelPath}: authored={authoredMaterialCount}, " +
                    $"active={referencedMaterialCount}, " +
                    $"unused={authoredMaterialCount - referencedMaterialCount}");
            }

            component = new CrossRigidAnalysisComponent(
                vmdPath,
                wsModelPath,
                rigidPath,
                wsDocument,
                rigid,
                assignments,
                GetCrossRigidWsModelTopologyIdentity(wsDocument),
                state.Source.ContainsFile(wsModelPath),
                state.Source.ContainsFile(rigidPath));
            return true;
        }

        private static List<CrossRigidLodAnalysis>
            BuildCrossRigidLodAnalyses(
                BatchState state,
                IReadOnlyList<CrossRigidAnalysisInstanceComponent> instances,
                CancellationToken cancellationToken)
        {
            var components = instances
                .Select(item => item.Component)
                .GroupBy(
                    component => component.WsModelPath,
                    StringComparer.OrdinalIgnoreCase)
                .Select(group => group.First())
                .OrderBy(
                    component => component.WsModelPath,
                    StringComparer.OrdinalIgnoreCase)
                .ToArray();
            if (components.Length == 0)
                return [];

            var sourceLodCount = components[0].Rigid.ModelList.Length;
            var qualityProfilesDiffer =
                components
                    .Select(component =>
                        BuildCrossRigidQualityProfile(component.Rigid))
                    .Distinct(StringComparer.Ordinal)
                    .Skip(1)
                    .Any();
            var distanceProfilesDiffer =
                components
                    .Select(component =>
                        BuildCrossRigidDistanceProfile(component.Rigid))
                    .Distinct(StringComparer.Ordinal)
                    .Skip(1)
                    .Any();

            IReadOnlyList<CrossRigidGeneratedLodScheduleEntry> schedule;
            if (!distanceProfilesDiffer &&
                sourceLodCount <= 5)
            {
                schedule = Enumerable
                    .Range(0, sourceLodCount)
                    .Select(lodIndex =>
                        new CrossRigidGeneratedLodScheduleEntry(
                            components[0].Rigid.LodHeaders[lodIndex]
                                .LodCameraDistance,
                            components
                                .Select(component =>
                                    new CrossRigidSourceLodSelection(
                                        component.WsModelPath,
                                        lodIndex))
                                .ToArray()))
                    .ToArray();
            }
            else
            {
                schedule =
                    BuildBoundedCrossRigidUnionLodSchedule(
                        components);
            }

            var result =
                new List<CrossRigidLodAnalysis>(schedule.Count);
            for (var generatedLodIndex = 0;
                 generatedLodIndex < schedule.Count;
                 generatedLodIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var scheduleEntry = schedule[generatedLodIndex];
                var qualityLevel = qualityProfilesDiffer
                    ? GetCrossRigidDefaultLodQualityLevel(
                        generatedLodIndex)
                    : GetCrossRigidReconciledLodQualityLevel(
                        components,
                        scheduleEntry.SourceLodSelections,
                        generatedLodIndex);

                result.Add(
                    AnalyzeCrossRigidLodState(
                        state,
                        instances,
                        generatedLodIndex,
                        generatedLodIndex,
                        qualityLevel,
                        scheduleEntry.CameraDistance,
                        scheduleEntry.SourceLodSelections,
                        isScenarioRepresentativeState: true));
            }

            return result;
        }

        private static IReadOnlyList<CrossRigidGeneratedLodScheduleEntry>
            BuildBoundedCrossRigidUnionLodSchedule(
                IReadOnlyList<CrossRigidAnalysisComponent> components)
        {
            var targetLodCount = Math.Clamp(
                components.Max(component =>
                    component.Rigid.LodHeaders.Length),
                1,
                MaxCrossRigidGeneratedLodCount);
            var rawBoundaries =
                new List<CrossRigidLodBoundaryCandidate>();
            foreach (var component in components)
            {
                for (var lodIndex = 0;
                     lodIndex < component.Rigid.LodHeaders.Length;
                     lodIndex++)
                {
                    var distance =
                        component.Rigid.LodHeaders[lodIndex]
                            .LodCameraDistance;
                    if (!float.IsFinite(distance) ||
                        distance <= 0)
                    {
                        continue;
                    }

                    rawBoundaries.Add(
                        new CrossRigidLodBoundaryCandidate(
                            distance,
                            GetCrossRigidLodTransitionWeight(
                                component,
                                lodIndex)));
                }
            }

            var unionBoundaries =
                MergeCrossRigidLodBoundaryCandidates(
                    rawBoundaries);
            if (unionBoundaries.Count == 0)
            {
                return Enumerable
                    .Range(0, targetLodCount)
                    .Select(lodIndex =>
                        new CrossRigidGeneratedLodScheduleEntry(
                            lodIndex switch
                            {
                                0 => 20.0f,
                                1 => 80.0f,
                                2 => 100.0f,
                                _ => 10000.0f,
                            },
                            components
                                .Select(component =>
                                    new CrossRigidSourceLodSelection(
                                        component.WsModelPath,
                                        Math.Min(
                                            lodIndex,
                                            component.Rigid.ModelList.Length -
                                            1)))
                                .ToArray()))
                    .ToArray();
            }

            var selectedBoundaries =
                SelectBoundedCrossRigidLodBoundaries(
                    unionBoundaries,
                    Math.Min(
                        targetLodCount,
                        unionBoundaries.Count));
            var schedule =
                new List<CrossRigidGeneratedLodScheduleEntry>(
                    selectedBoundaries.Count);
            var previousDistance = 0.0f;
            foreach (var boundary in selectedBoundaries)
            {
                var sampleDistance =
                    previousDistance +
                    ((boundary.Distance - previousDistance) * 0.5f);
                var selections = components
                    .Select(component =>
                    {
                        var sourceLodIndex =
                            FindCrossRigidSourceLodAtDistance(
                                component.Rigid,
                                sampleDistance);
                        return sourceLodIndex >= 0
                            ? new CrossRigidSourceLodSelection(
                                component.WsModelPath,
                                sourceLodIndex)
                            : null;
                    })
                    .Where(selection => selection != null)
                    .Cast<CrossRigidSourceLodSelection>()
                    .OrderBy(
                        selection => selection.WsModelPath,
                        StringComparer.OrdinalIgnoreCase)
                    .ToArray();

                if (selections.Length != 0)
                {
                    schedule.Add(
                        new CrossRigidGeneratedLodScheduleEntry(
                            boundary.Distance,
                            selections));
                }

                previousDistance = boundary.Distance;
            }

            return schedule;
        }

        private static List<CrossRigidLodBoundaryCandidate>
            MergeCrossRigidLodBoundaryCandidates(
                IReadOnlyList<CrossRigidLodBoundaryCandidate> candidates)
        {
            var output =
                new List<CrossRigidLodBoundaryCandidate>();
            foreach (var candidate in candidates
                         .OrderBy(candidate => candidate.Distance))
            {
                if (output.Count != 0 &&
                    Math.Abs(
                        output[^1].Distance -
                        candidate.Distance) <=
                    CrossRigidLodDistanceEpsilon)
                {
                    var previous = output[^1];
                    output[^1] = previous with
                    {
                        Distance = Math.Max(
                            previous.Distance,
                            candidate.Distance),
                        Weight =
                            previous.Weight +
                            candidate.Weight,
                    };
                    continue;
                }

                output.Add(candidate);
            }

            return output;
        }

        private static IReadOnlyList<CrossRigidLodBoundaryCandidate>
            SelectBoundedCrossRigidLodBoundaries(
                IReadOnlyList<CrossRigidLodBoundaryCandidate> candidates,
                int targetCount)
        {
            if (targetCount <= 0 ||
                candidates.Count == 0)
            {
                return [];
            }

            if (candidates.Count <= targetCount)
                return candidates.ToArray();

            if (targetCount == 1)
                return [candidates[^1]];

            var finalBoundary = candidates[^1];
            var pool = candidates
                .Take(candidates.Count - 1)
                .ToArray();
            var preFinalTargetCount = targetCount - 1;
            if (pool.Length <= preFinalTargetCount)
            {
                return pool
                    .Append(finalBoundary)
                    .ToArray();
            }

            var selected =
                new HashSet<int>();
            var totalWeight = pool.Sum(candidate =>
                Math.Max(1.0, candidate.Weight));
            if (totalWeight > 0)
            {
                var cumulativeCenters =
                    new double[pool.Length];
                double cumulativeWeight = 0;
                for (var index = 0;
                     index < pool.Length;
                     index++)
                {
                    var weight =
                        Math.Max(1.0, pool[index].Weight);
                    cumulativeCenters[index] =
                        cumulativeWeight +
                        (weight * 0.5);
                    cumulativeWeight += weight;
                }

                for (var slot = 0;
                     slot < preFinalTargetCount;
                     slot++)
                {
                    var targetWeight =
                        totalWeight *
                        ((slot + 0.5) /
                         preFinalTargetCount);
                    var bestIndex = Enumerable
                        .Range(0, pool.Length)
                        .Where(index =>
                            !selected.Contains(index))
                        .OrderBy(index =>
                            Math.Abs(
                                cumulativeCenters[index] -
                                targetWeight))
                        .ThenByDescending(index =>
                            pool[index].Weight)
                        .ThenBy(index =>
                            pool[index].Distance)
                        .First();
                    selected.Add(bestIndex);
                }
            }

            if (selected.Count <
                preFinalTargetCount)
            {
                foreach (var index in Enumerable
                             .Range(0, pool.Length)
                             .Where(index =>
                                 !selected.Contains(index))
                             .OrderByDescending(index =>
                                 pool[index].Weight)
                             .ThenBy(index =>
                                 pool[index].Distance))
                {
                    selected.Add(index);
                    if (selected.Count ==
                        preFinalTargetCount)
                    {
                        break;
                    }
                }
            }

            return selected
                .Select(index => pool[index])
                .Append(finalBoundary)
                .OrderBy(candidate => candidate.Distance)
                .ToArray();
        }

        private static double GetCrossRigidLodTransitionWeight(
            CrossRigidAnalysisComponent component,
            int lodIndex)
        {
            var currentWeight =
                GetCrossRigidLodGeometryWeight(
                    component.Rigid,
                    lodIndex);
            if (lodIndex + 1 >=
                component.Rigid.ModelList.Length)
            {
                return Math.Max(1.0, currentWeight);
            }

            var nextWeight =
                GetCrossRigidLodGeometryWeight(
                    component.Rigid,
                    lodIndex + 1);
            return Math.Max(
                1.0,
                Math.Max(currentWeight, nextWeight));
        }

        private static long GetCrossRigidLodGeometryWeight(
            RmvFile rigid,
            int lodIndex)
        {
            if (lodIndex < 0 ||
                lodIndex >= rigid.ModelList.Length)
            {
                return 0;
            }

            return rigid.ModelList[lodIndex].Sum(model =>
                (long)model.Mesh.VertexList.Length +
                (model.Mesh.IndexList.Length / 3L));
        }

        private static int FindCrossRigidSourceLodAtDistance(
            RmvFile rigid,
            float distance)
        {
            for (var lodIndex = 0;
                 lodIndex < rigid.LodHeaders.Length;
                 lodIndex++)
            {
                if (distance <=
                    rigid.LodHeaders[lodIndex]
                        .LodCameraDistance +
                    CrossRigidLodDistanceEpsilon)
                {
                    return lodIndex;
                }
            }

            return -1;
        }

        private static byte GetCrossRigidReconciledLodQualityLevel(
            IReadOnlyList<CrossRigidAnalysisComponent> components,
            IReadOnlyList<CrossRigidSourceLodSelection> selections,
            int generatedLodIndex)
        {
            var qualityLevels = selections
                .Select(selection =>
                {
                    var component = components.First(item =>
                        item.WsModelPath.Equals(
                            selection.WsModelPath,
                            StringComparison.OrdinalIgnoreCase));
                    return component.Rigid.LodHeaders[
                        selection.SourceLodIndex].QualityLvl;
                })
                .ToArray();
            if (qualityLevels.Length == 0)
            {
                return GetCrossRigidDefaultLodQualityLevel(
                    generatedLodIndex);
            }

            return qualityLevels.Max();
        }

        private static byte GetCrossRigidDefaultLodQualityLevel(
            int lodIndex)
            => lodIndex == 0 ? (byte)2 : (byte)0;

        private static CrossRigidLodAnalysis AnalyzeCrossRigidLodState(
            BatchState state,
            IReadOnlyList<CrossRigidAnalysisInstanceComponent> instances,
            int generatedLodIndex,
            int scenarioLodIndex,
            byte qualityLevel,
            float cameraDistance,
            IReadOnlyList<CrossRigidSourceLodSelection> sourceLodSelections,
            bool isScenarioRepresentativeState)
        {
            var sourceLodByWsModel =
                sourceLodSelections.ToDictionary(
                    selection => Normalize(selection.WsModelPath),
                    selection => selection.SourceLodIndex,
                    StringComparer.OrdinalIgnoreCase);
            var activeInstances = instances
                .Where(item =>
                    sourceLodByWsModel.ContainsKey(
                        Normalize(item.Component.WsModelPath)))
                .ToArray();
            var activeRigidCount = activeInstances
                .Select(item => item.Component.RigidPath)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Count();

            var partsByIdentity =
                new Dictionary<
                    string,
                    List<CrossRigidAnalysisMeshPart>>(
                    StringComparer.Ordinal);
            var vertexFactory = VertexFactory.Create();
            long generatedVertices = 0;
            long generatedGeometryBytes = 0;

            for (var instanceIndex = 0;
                 instanceIndex < activeInstances.Length;
                 instanceIndex++)
            {
                var item = activeInstances[instanceIndex];
                var component = item.Component;
                var sourceLodIndex =
                    sourceLodByWsModel[
                        Normalize(component.WsModelPath)];
                var models =
                    component.Rigid.ModelList[sourceLodIndex];
                var materialAssignments =
                    component.MaterialAssignments[sourceLodIndex];
                var instanceKey =
                    $"{instanceIndex}\u001f" +
                    $"{item.Instance.AttachmentIdentity}\u001f" +
                    $"{component.WsModelPath}";

                for (var partIndex = 0;
                     partIndex < models.Length;
                     partIndex++)
                {
                    var model = models[partIndex];
                    generatedVertices +=
                        model.Mesh.VertexList.Length;
                    generatedGeometryBytes +=
                        checked(
                            (long)vertexFactory.GetVertexSize(
                                model.Material.BinaryVertexFormat,
                                component.Rigid.Header.Version) *
                            model.Mesh.VertexList.Length);
                    generatedGeometryBytes +=
                        checked(
                            (long)sizeof(ushort) *
                            model.Mesh.IndexList.Length);

                    var identity =
                        GetCrossRigidSourcePartMergeIdentity(
                            state,
                            component.RigidPath,
                            sourceLodIndex,
                            partIndex,
                            model,
                            materialAssignments[partIndex]);
                    if (!partsByIdentity.TryGetValue(
                            identity,
                            out var parts))
                    {
                        parts = [];
                        partsByIdentity[identity] = parts;
                    }

                    parts.Add(
                        new CrossRigidAnalysisMeshPart(
                            instanceKey,
                            component.WsModelPath,
                            component.RigidPath,
                            model.Mesh.VertexList.Length));
                }
            }

            var inputDraws = 0;
            var outputDraws = 0;
            var outputLayoutParts = new List<string>();
            foreach (var (identity, parts) in partsByIdentity
                         .OrderBy(entry => entry.Key, StringComparer.Ordinal))
            {
                inputDraws += parts
                    .GroupBy(
                        part => part.InstanceKey,
                        StringComparer.Ordinal)
                    .Sum(group =>
                        CountCrossRigidVertexLimitedMergeBins(
                            group.Select(part => part.VertexCount)));
                var outputBins =
                    CountCrossRigidVertexLimitedMergeBins(
                        parts.Select(part => part.VertexCount));
                outputDraws += outputBins;
                outputLayoutParts.Add(string.Join(
                    ":",
                    ContentHash(identity),
                    outputBins,
                    string.Join(
                        ",",
                        parts.Select(part => part.VertexCount)
                            .OrderBy(count => count))));
            }

            return new CrossRigidLodAnalysis(
                generatedLodIndex,
                scenarioLodIndex,
                qualityLevel,
                cameraDistance,
                sourceLodSelections.ToArray(),
                isScenarioRepresentativeState,
                activeInstances.Length,
                activeRigidCount,
                inputDraws,
                outputDraws,
                Math.Max(0, inputDraws - outputDraws),
                isScenarioRepresentativeState
                    ? state.ArmyResidencyModel?.Scenario
                        .GetLodProbability(scenarioLodIndex) ?? 0
                    : 0,
                generatedVertices,
                generatedGeometryBytes,
                ContentHash(string.Join("\u001e", outputLayoutParts)));
        }

        private static int CountCrossRigidVertexLimitedMergeBins(
            IEnumerable<int> vertexCounts)
        {
            var bins = new List<int>();
            foreach (var vertexCount in vertexCounts.OrderByDescending(count => count))
            {
                if (vertexCount > ushort.MaxValue)
                {
                    bins.Add(vertexCount);
                    continue;
                }

                var placed = false;
                for (var index = 0; index < bins.Count; index++)
                {
                    if (bins[index] > ushort.MaxValue ||
                        bins[index] + vertexCount > ushort.MaxValue)
                    {
                        continue;
                    }

                    bins[index] += vertexCount;
                    placed = true;
                    break;
                }

                if (!placed)
                    bins.Add(vertexCount);
            }

            return bins.Count;
        }

        private static double CalculateExpectedCrossRigidArmyDrawSavings(
            BatchState state,
            string vmdPath,
            double visualConfigurationProbability,
            IReadOnlyList<CrossRigidLodAnalysis> lodAnalyses)
        {
            var model = state.ArmyResidencyModel;
            if (model == null ||
                visualConfigurationProbability <= 0 ||
                lodAnalyses.Count == 0)
            {
                return 0;
            }

            var relevantUnitIds = GetRelevantArmyUnitIds(
                model,
                Array.Empty<string>(),
                [vmdPath]);
            var relevantCultures = GetRelevantArmyCultures(
                model,
                Array.Empty<string>(),
                [vmdPath],
                relevantUnitIds);
            if (relevantUnitIds.Count == 0 || relevantCultures.Count == 0)
                return 0;

            var drawsByCulture = model.UnitsByCultureAndCategory.Keys.ToDictionary(
                culture => culture,
                _ => 0.0,
                StringComparer.OrdinalIgnoreCase);

            foreach (var culture in relevantCultures)
            {
                if (!model.UnitsByCultureAndCategory.TryGetValue(
                        culture,
                        out var unitsByCategory))
                {
                    continue;
                }

                foreach (var (category, slotCount) in model.Scenario.ArmySlotTemplate)
                {
                    if (!unitsByCategory.TryGetValue(
                            category,
                            out var cultureUnits) ||
                        cultureUnits.Count == 0)
                    {
                        continue;
                    }

                    foreach (var lod in lodAnalyses.Where(lod => lod.DrawsSaved > 0))
                    {
                        double eliminatedDrawsAcrossResolvedUnits = 0;
                        foreach (var unitId in EnumerateRelevantArmyUnitIds(
                                     cultureUnits,
                                     relevantUnitIds))
                        {
                            if (!model.DirectVmdsByUnitAndRole.TryGetValue(
                                    unitId,
                                    out var vmdsByRole))
                            {
                                continue;
                            }

                            foreach (var (role, directVmds) in vmdsByRole)
                            {
                                if (directVmds.Count == 0 ||
                                    !directVmds.Contains(vmdPath))
                                {
                                    continue;
                                }

                                var entityCount = Math.Max(
                                    1,
                                    model.EntityCountByUnitAndRole
                                        .GetValueOrDefault(unitId)?
                                        .GetValueOrDefault(role, 1) ?? 1);
                                var directVmdProbability =
                                    1.0 / directVmds.Count;
                                eliminatedDrawsAcrossResolvedUnits +=
                                    visualConfigurationProbability *
                                    directVmdProbability *
                                    entityCount *
                                    lod.DrawsSaved;
                            }
                        }

                        if (eliminatedDrawsAcrossResolvedUnits <= 0)
                            continue;

                        drawsByCulture[culture] +=
                            lod.LodProbability *
                            slotCount *
                            (eliminatedDrawsAcrossResolvedUnits /
                             cultureUnits.Count);
                    }
                }
            }

            return CombineBattleDrawSavings(
                drawsByCulture,
                model.PlayerCultureWeights,
                model.OpponentCultureWeights);
        }

        private static string GetCrossRigidWsModelTopologyIdentity(XmlDocument document)
        {
            var clone = new XmlDocument();
            clone.LoadXml(document.OuterXml);

            var geometryNode = clone.SelectSingleNode("/model/geometry");
            geometryNode?.ParentNode?.RemoveChild(geometryNode);

            var materialNodes = clone.SelectNodes("/model/materials/material");
            if (materialNodes != null)
            {
                foreach (XmlNode materialNode in materialNodes.Cast<XmlNode>().ToList())
                    materialNode.ParentNode?.RemoveChild(materialNode);
            }

            return clone.OuterXml;
        }

        private static void RecordCrossRigidAnalysisBlocker(
            BatchState state,
            string reason,
            string example)
        {
            state.CrossRigidAnalysisBlockerCounts[reason] =
                state.CrossRigidAnalysisBlockerCounts
                    .GetValueOrDefault(reason) + 1;
            if (!state.CrossRigidAnalysisBlockerExamples.TryGetValue(
                    reason,
                    out var examples))
            {
                examples = [];
                state.CrossRigidAnalysisBlockerExamples[reason] =
                    examples;
            }

            const int maxExamplesPerReason = 8;
            if (examples.Count < maxExamplesPerReason &&
                !examples.Contains(example, StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private static void RecordCrossRigidRigidHeaderBlocker(
            BatchState state,
            string vmdPath,
            string attachmentIdentity,
            IReadOnlyList<CrossRigidAnalysisComponent> components,
            string reason)
        {
            const string blocker =
                "Cross-rigid source rigid headers are not merge-compatible";
            RecordCrossRigidAnalysisBlocker(
                state,
                blocker,
                $"{vmdPath} [{attachmentIdentity}]: {reason}");

            state.CrossRigidRigidHeaderBlockerCounts[reason] =
                state.CrossRigidRigidHeaderBlockerCounts
                    .GetValueOrDefault(reason) + 1;

            if (!state.CrossRigidRigidHeaderBlockerRigidCombinations.TryGetValue(
                    reason,
                    out var rigidCombinations))
            {
                rigidCombinations =
                    new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                state.CrossRigidRigidHeaderBlockerRigidCombinations[reason] =
                    rigidCombinations;
            }

            var rigidCombination = string.Join(
                "\u001e",
                components
                    .Select(component => Normalize(component.RigidPath))
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase));
            if (rigidCombination.Length != 0)
                rigidCombinations.Add(rigidCombination);

            if (!state.CrossRigidRigidHeaderBlockerVmdRoots.TryGetValue(
                    reason,
                    out var vmdRoots))
            {
                vmdRoots =
                    new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                state.CrossRigidRigidHeaderBlockerVmdRoots[reason] =
                    vmdRoots;
            }

            var normalizedVmdPath = Normalize(vmdPath);
            if (normalizedVmdPath.Length != 0)
                vmdRoots.Add(normalizedVmdPath);

            var qualityProfiles = components
                .Select(component =>
                    BuildCrossRigidQualityProfile(component.Rigid))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(profile => profile, StringComparer.Ordinal)
                .ToArray();
            if (qualityProfiles.Length > 1)
            {
                RecordCrossRigidHeaderProfileAggregate(
                    state.CrossRigidRigidHeaderQualityProfiles,
                    string.Join(" <> ", qualityProfiles),
                    rigidCombination,
                    normalizedVmdPath);
            }

            var fullLodProfiles = components
                .Select(component =>
                    BuildCrossRigidFullLodProfile(component.Rigid))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(profile => profile, StringComparer.Ordinal)
                .ToArray();
            if (fullLodProfiles.Length > 1)
            {
                RecordCrossRigidHeaderProfileAggregate(
                    state.CrossRigidRigidHeaderFullLodProfiles,
                    string.Join(" <> ", fullLodProfiles),
                    rigidCombination,
                    normalizedVmdPath);
            }
        }

        private static string BuildCrossRigidQualityProfile(RmvFile rigid)
            => $"Q=[{string.Join(
                ",",
                rigid.LodHeaders.Select(header =>
                    Convert.ToString(
                        header.QualityLvl,
                        CultureInfo.InvariantCulture)))}]";

        private static string BuildCrossRigidDistanceProfile(RmvFile rigid)
            => $"D=[{string.Join(
                ",",
                rigid.LodHeaders.Select(header =>
                    header.LodCameraDistance.ToString(
                        "0.###",
                        CultureInfo.InvariantCulture)))}]";

        private static string BuildCrossRigidFullLodProfile(RmvFile rigid)
        {
            var qualityProfile = BuildCrossRigidQualityProfile(rigid);
            var distanceProfile = string.Join(
                ",",
                rigid.LodHeaders.Select(header =>
                    header.LodCameraDistance.ToString(
                        "0.###",
                        CultureInfo.InvariantCulture)));
            return $"{qualityProfile} D=[{distanceProfile}]";
        }

        private static void RecordCrossRigidHeaderProfileAggregate(
            Dictionary<string, CrossRigidHeaderProfileAggregate> aggregates,
            string profilePattern,
            string rigidCombination,
            string vmdPath)
        {
            if (!aggregates.TryGetValue(
                    profilePattern,
                    out var aggregate))
            {
                aggregate = new CrossRigidHeaderProfileAggregate();
                aggregates[profilePattern] = aggregate;
            }

            aggregate.ObservationCount++;
            if (rigidCombination.Length != 0)
                aggregate.RigidCombinations.Add(rigidCombination);
            if (vmdPath.Length != 0)
                aggregate.VmdRoots.Add(vmdPath);
        }

        private static void RecordCrossRigidAnalysisDiagnostic(
            BatchState state,
            string reason,
            string example)
        {
            state.CrossRigidAnalysisDiagnosticCounts[reason] =
                state.CrossRigidAnalysisDiagnosticCounts
                    .GetValueOrDefault(reason) + 1;
            if (!state.CrossRigidAnalysisDiagnosticExamples.TryGetValue(
                    reason,
                    out var examples))
            {
                examples = [];
                state.CrossRigidAnalysisDiagnosticExamples[reason] =
                    examples;
            }

            const int maxExamplesPerReason = 8;
            if (examples.Count < maxExamplesPerReason &&
                !examples.Contains(example, StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private void AnalyzeCompatibleMeshMergesForRigid(
            BatchState state,
            string rigidPath,
            CancellationToken cancellationToken)
        {
            if (!state.RigidModels.TryGetValue(rigidPath, out var rmv))
                return;

            var wsModels = GetWritableWsModelsForRigid(state, rigidPath);
            if (wsModels.Count == 0)
            {
                for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var groups = BuildDirectMeshMergeGroups(
                        rmv.ModelList[lodIndex],
                        lodIndex,
                        rigidPath);
                    RecordPreAtlasStructuralMergeGroups(
                        state,
                        rigidPath,
                        lodIndex,
                        groups);
                }

                return;
            }

            var assignmentsByWsModel = new Dictionary<string, string[][]>(
                StringComparer.OrdinalIgnoreCase);
            foreach (var (wsPath, wsDocument) in wsModels)
            {
                if (!TryReadWsMaterialAssignments(
                        wsDocument,
                        rmv,
                        out var assignments,
                        out var reason))
                {
                    RecordStructuralMergeSkip(state, rigidPath, $"{wsPath}: {reason}");
                    return;
                }

                assignmentsByWsModel[wsPath] = assignments;
            }

            var wsModelPaths = wsModels
                .Select(x => x.Key)
                .ToList();
            for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var models = rmv.ModelList[lodIndex];
                if (models.Length < 2)
                    continue;

                var groups = BuildMeshMergeGroups(
                    state,
                    models,
                    lodIndex,
                    rigidPath,
                    wsModelPaths,
                    assignmentsByWsModel,
                    recordDiagnostics: false,
                    includeEmbeddedMaterialIdentity:
                        HasDirectGameplayRigidConsumer(state, rigidPath));

                RecordPreAtlasStructuralMergeGroups(
                    state,
                    rigidPath,
                    lodIndex,
                    groups);
            }
        }

        private static void RecordPreAtlasStructuralMergeGroups(
            BatchState state,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<MeshMergeGroup> groups)
        {
            foreach (var group in groups.Where(x => x.PartIndices.Count > 1))
            {
                state.PreAtlasStructuralMergeGroupCount++;
                var componentMembers = group.PartIndices
                    .Select(partIndex => new MeshKey(rigidPath, lodIndex, partIndex))
                    .ToHashSet();
                var componentSignature = string.Join(
                    "\u001f",
                    componentMembers
                        .OrderBy(member => member.PartIndex)
                        .Select(member =>
                            BuildStructuralMergePairKey(
                                member.GeometryPath,
                                member.LodIndex,
                                member.PartIndex,
                                member.PartIndex)));
                if (state.PreAtlasStructuralMergeComponentSignatures.Add(componentSignature))
                    state.PreAtlasStructuralMergeComponents.Add(componentMembers);

                foreach (var partIndex in group.PartIndices)
                {
                    state.PreAtlasStructuralMergeMeshes.Add(
                        new MeshKey(rigidPath, lodIndex, partIndex));
                }

                for (var left = 0; left < group.PartIndices.Count; left++)
                {
                    for (var right = left + 1;
                         right < group.PartIndices.Count;
                         right++)
                    {
                        state.PreAtlasStructuralMergePairs.Add(
                            BuildStructuralMergePairKey(
                                rigidPath,
                                lodIndex,
                                group.PartIndices[left],
                                group.PartIndices[right]));
                    }
                }
            }
        }

        private static List<KeyValuePair<string, XmlDocument>> GetWritableWsModelsForRigid(
            BatchState state,
            string rigidPath)
            => state.WsDocuments
                .Where(x =>
                    Normalize(x.Value.SelectSingleNode("/model/geometry")?.InnerText)
                        .Equals(rigidPath, StringComparison.OrdinalIgnoreCase))
                .OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase)
                .ToList();

        private static bool TryGetStructuralMergeBlockReason(
            BatchState state,
            string rigidPath,
            out string reason)
        {
            if (!IsGameplayConsumerDiscoverySafeForAsset(state, rigidPath))
            {
                reason = "complete gameplay consumer discovery was not available; structural merge is blocked conservatively.";
                RecordGameplayMeshDiscoveryBlock(
                    state,
                    "StructuralMerge",
                    [rigidPath]);
                RecordStructuralMergeSkip(state, rigidPath, reason);
                return true;
            }

            var immutableConsumers =
                GetImmutableGameplayWsModelConsumersForRigid(state, rigidPath);
            if (immutableConsumers.Count != 0)
            {
                reason =
                    $"immutable gameplay WSModel consumer(s) would require part remapping: " +
                    $"{string.Join(", ", immutableConsumers.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))}";
                RecordStructuralMergeSkip(state, rigidPath, reason);
                return true;
            }

            reason = string.Empty;
            return false;
        }

        private static void RecordStructuralMergeSkip(
            BatchState state,
            string rigidPath,
            string reason)
        {
            var message = $"{rigidPath}: {reason}";
            if (state.MeshMergeSkipMessages.Contains(message, StringComparer.Ordinal))
                return;

            state.MeshMergeSkipMessages.Add(message);
        }

        private static void IndexTaintedGameplayWsModels(
            BatchState state,
            CancellationToken cancellationToken)
        {
            state.TaintedGameplayWsModels.Clear();
            var resolution = state.UnitCategoryResolution;
            if (state.AtlasAllVmdsEnabled ||
                resolution == null ||
                resolution.UnresolvedConsumersByVmd.Count == 0)
            {
                return;
            }

            foreach (var rootValue in resolution.UnresolvedConsumersByVmd.Keys)
            {
                cancellationToken.ThrowIfCancellationRequested();
                foreach (var wsModel in CollectReachableGameplayWsModels(
                             state,
                             rootValue,
                             cancellationToken))
                {
                    state.TaintedGameplayWsModels.Add(Normalize(wsModel));
                }
            }
        }

        // Kept as a small compatibility entry point for existing reflection-based tests and
        // callers. Production traversal uses the BatchState overload below so repeated path
        // resolution is memoized for the duration of a batch.
        private static IPackFileContainer? FindGameplayTraversalContainer(
            IPackFileContainer source,
            IReadOnlyList<IPackFileContainer> loadedContainers,
            string pathValue)
            => ResolveGameplayTraversalContainer(
                source,
                loadedContainers,
                Normalize(pathValue));

        private static IPackFileContainer? FindGameplayTraversalContainer(
            BatchState state,
            IPackFileContainer source,
            IReadOnlyList<IPackFileContainer> loadedContainers,
            string pathValue)
        {
            var path = Normalize(pathValue);
            if (path.Length == 0)
                return null;

            if (state.GameplayTraversalContainerResolutions.TryGetValue(
                    path,
                    out var cachedResolution))
            {
                state.GameplayTraversalContainerResolutionCacheHits++;
                return cachedResolution.Container;
            }

            state.GameplayTraversalContainerResolutionScans++;

            var resolvedContainer = ResolveGameplayTraversalContainer(
                source,
                loadedContainers,
                path);
            if (resolvedContainer != null)
            {
                state.GameplayTraversalContainerResolutions[path] =
                    new GameplayTraversalContainerResolution(resolvedContainer);
                return resolvedContainer;
            }

            // Cache negative results too. The source and loaded CA containers are stable for
            // the duration of a batch, so an unresolved path cannot become resolvable later.
            state.GameplayTraversalContainerResolutions[path] =
                GameplayTraversalContainerResolution.Missing;
            return null;
        }

        private static IPackFileContainer? ResolveGameplayTraversalContainer(
            IPackFileContainer source,
            IReadOnlyList<IPackFileContainer> loadedContainers,
            string path)
        {
            if (path.Length == 0)
                return null;

            // The selected source pack is the effective override for this batch.
            if (source.ContainsFile(path))
                return source;

            // Resolver semantics are CA game data + selected source only. Search CA
            // containers in reverse load order to preserve normal pack-file override
            // precedence without allowing unrelated open mods into gameplay resolution.
            for (var index = loadedContainers.Count - 1; index >= 0; index--)
            {
                var container = loadedContainers[index];
                if (!container.IsCaPackFile || ReferenceEquals(container, source))
                    continue;
                if (container.ContainsFile(path))
                    return container;
            }

            return null;
        }

        private static IReadOnlyList<IPackFileContainer> GetGameplayTraversalContainers(
            BatchState state)
        {
            state.GameplayTraversalContainers ??=
                state.PackFileService.GetAllPackfileContainers().ToList();
            return state.GameplayTraversalContainers;
        }

        private static HashSet<string> CollectReachableGameplayWsModels(
            BatchState state,
            string rootVmdPath,
            CancellationToken cancellationToken)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var queue = new Queue<string>();
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var loadedContainers = GetGameplayTraversalContainers(state);
            queue.Enqueue(Normalize(rootVmdPath));

            while (queue.Count != 0)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var vmdPath = queue.Dequeue();
                if (vmdPath.Length == 0 || !visited.Add(vmdPath))
                    continue;

                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    loadedContainers,
                    vmdPath);
                var file = container?.FindFile(vmdPath);
                if (container == null ||
                    file == null ||
                    !TryGetVmdForTraversal(
                        state,
                        container,
                        vmdPath,
                        file,
                        out var vmd))
                {
                    continue;
                }

                var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var children = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                CollectVmdReferences(vmd, models, children, textures);

                foreach (var modelValue in models)
                {
                    var model = Normalize(modelValue);
                    if (!Path.GetExtension(model).Equals(
                            ".wsmodel",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }

                    if (FindGameplayTraversalContainer(
                            state,
                            state.Source,
                            loadedContainers,
                            model) != null)
                    {
                        // Keep the logical path. A source-pack override of this path is the
                        // exact asset that the atlas rewrite would modify.
                        result.Add(model);
                    }
                }

                foreach (var childValue in children)
                {
                    var child = Normalize(childValue);
                    if (FindGameplayTraversalContainer(
                            state,
                            state.Source,
                            loadedContainers,
                            child) != null)
                    {
                        queue.Enqueue(child);
                    }
                }
            }

            return result;
        }

        private static bool IsSharedMeshSafeForGameplay(
            bool atlasAllVmdsEnabled,
            IEnumerable<string> affectedWsModels,
            IReadOnlySet<string> taintedGameplayWsModels)
            => atlasAllVmdsEnabled ||
               !affectedWsModels
                   .Select(Normalize)
                   .Any(taintedGameplayWsModels.Contains);

        private static bool IsCandidateSharedMeshSafeForGameplay(
            BatchState state,
            MeshKey key,
            IReadOnlyCollection<WsUsage> candidateUsages)
        {
            if (state.AtlasAllVmdsEnabled ||
                state.TaintedGameplayWsModels.Count == 0)
            {
                return true;
            }

            var affectedUsages = state.Usages.TryGetValue(key, out var allUsages)
                ? allUsages
                : candidateUsages;
            return IsSharedMeshSafeForGameplay(
                state.AtlasAllVmdsEnabled,
                affectedUsages
                    .Select(usage => usage.WsModelPath)
                    .Where(path => !string.IsNullOrWhiteSpace(path)),
                state.TaintedGameplayWsModels);
        }

        private List<MissingTextureDependency> FindMissingTextureDependencies(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var reachableWsModels = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var vmdPath in vmdRoots)
            {
                cancellationToken.ThrowIfCancellationRequested();
                reachableWsModels.UnionWith(
                    GetReachableWsModels(state, vmdPath, cancellationToken));
            }

            var result = new List<MissingTextureDependency>();
            var usagesList = state.Usages.ToList();

            for (var usageIndex = 0; usageIndex < usagesList.Count; usageIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var (key, usages) = usagesList[usageIndex];
                if (usageIndex == 0 || usageIndex == usagesList.Count - 1 || usageIndex % 10 == 0)
                {
                    ReportProgress(
                        progress,
                        "Checking texture dependencies",
                        usageIndex + 1,
                        usagesList.Count,
                        key.ToString());
                }
                var reachableUsages = usages
                    .Where(x => reachableWsModels.Contains(x.WsModelPath))
                    .ToList();
                if (reachableUsages.Count == 0)
                    continue;

                var materialPaths = usages
                    .Select(x => x.MaterialPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
                if (materialPaths.Count != 1)
                    continue;

                var materialFile = FindForRead(state, materialPaths[0]);
                if (materialFile == null)
                    continue;

                XmlDocument materialDoc;
                try
                {
                    materialDoc = GetMaterialDocument(state, materialPaths[0], materialFile);
                }
                catch
                {
                    continue;
                }

                var shaderPath = materialDoc.SelectSingleNode("/material/shader")?.InnerText ?? string.Empty;
                if (shaderPath.Contains("emissive", StringComparison.OrdinalIgnoreCase))
                    continue;

                if (materialDoc.SelectNodes("/material/textures/texture")?
                        .Cast<XmlNode>()
                        .Any(x => GetTextureSlot(x).Contains("emissive", StringComparison.OrdinalIgnoreCase)) == true)
                {
                    continue;
                }

                var primaryPath = GetTexturePath(materialDoc, "t_xml_base_colour");
                if (string.IsNullOrWhiteSpace(primaryPath) || FindForRead(state, primaryPath) == null)
                    continue;

                foreach (var channel in AtlasChannels.Skip(1))
                {
                    var texturePath = GetTexturePath(materialDoc, channel.Slot);
                    if (string.IsNullOrWhiteSpace(texturePath) || IsTexturePlaceholder(texturePath))
                        continue;

                    if (FindForRead(state, texturePath) == null)
                    {
                        if (IsIgnorableUnresolvedAtlasTexture(channel.Slot, texturePath))
                            continue;

                        result.Add(new MissingTextureDependency(
                            key,
                            channel.Slot,
                            texturePath));
                    }
                }
            }

            return result
                .Distinct()
                .OrderBy(x => x.TexturePath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(x => x.Key.LodIndex)
                .ThenBy(x => x.Key.PartIndex)
                .ThenBy(x => x.Slot, StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static string BuildMissingTextureDetails(
            IReadOnlyList<MissingTextureDependency> missingTextures)
        {
            var sb = new StringBuilder();

            foreach (var group in missingTextures.GroupBy(
                         x => x.TexturePath,
                         StringComparer.OrdinalIgnoreCase))
            {
                sb.AppendLine(group.Key);
                foreach (var dependency in group)
                {
                    sb.AppendLine(
                        $"  {dependency.Key.GeometryPath} [lod {dependency.Key.LodIndex}, part {dependency.Key.PartIndex}] " +
                        $"({dependency.Slot})");
                }

                sb.AppendLine();
            }

            return sb.ToString();
        }

        private CandidateDiscoveryResult DiscoverAtlasCandidates(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            bool packWide,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var candidates = new List<AtlasCandidate>();
            var missingTextures = new List<MissingTextureDependency>();
            var inspectedKeys = packWide ? new HashSet<MeshKey>() : null;

            for (var vmdIndex = 0; vmdIndex < vmdRoots.Count; vmdIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                candidates.AddRange(CollectVmdCandidates(
                    state,
                    vmdRoots[vmdIndex],
                    vmdIndex + 1,
                    vmdRoots.Count,
                    cancellationToken,
                    progress,
                    inspectedKeys,
                    missingTextures));
            }

            var directAssetPaths = state.UnitCategoryResolution?
                .DirectAssetUsagesByPath.Keys
                .Where(path => state.Source.ContainsFile(path))
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToList()
                ?? [];
            candidates.AddRange(CollectDirectAssetCandidates(
                state,
                directAssetPaths,
                cancellationToken,
                progress,
                inspectedKeys,
                missingTextures));

            candidates = FilterAtlasCandidatesWithUnrewritableMaterialConsumers(
                state,
                candidates);

            if (state.ExistingAtlasOutputDetected)
            {
                var existingAtlasCandidates = candidates
                    .Where(candidate => IsAlreadyGeneratedAtlasCandidate(candidate))
                    .ToList();
                foreach (var candidate in existingAtlasCandidates)
                {
                    RecordSkip(
                        state,
                        candidate.RootVmdPath,
                        candidate.Key,
                        candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        "Existing generated atlas material/texture was preserved; only newly un-atlased candidates remain eligible.");
                }

                state.ExistingGeneratedAtlasCandidateCount =
                    existingAtlasCandidates
                        .Select(candidate => candidate.Key)
                        .Distinct()
                        .Count();
                candidates = candidates
                    .Where(candidate => !IsAlreadyGeneratedAtlasCandidate(candidate))
                    .ToList();
            }

            return new CandidateDiscoveryResult(
                candidates,
                missingTextures
                    .Distinct()
                    .OrderBy(x => x.TexturePath, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(x => x.Key.LodIndex)
                    .ThenBy(x => x.Key.PartIndex)
                    .ThenBy(x => x.Slot, StringComparer.OrdinalIgnoreCase)
                    .ToList());
        }

        private static List<AtlasCandidate> FilterAtlasCandidatesWithUnrewritableMaterialConsumers(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates)
        {
            var discoverySafeCandidates = new List<AtlasCandidate>(candidates.Count);
            foreach (var candidate in candidates)
            {
                if (IsAtlasCandidateGameplayDiscoverySafe(state, candidate))
                {
                    discoverySafeCandidates.Add(candidate);
                    continue;
                }

                var discoveryPaths = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase)
                {
                    candidate.RootVmdPath,
                    candidate.Key.GeometryPath,
                };
                foreach (var usage in candidate.Usages)
                {
                    if (!string.IsNullOrWhiteSpace(usage.WsModelPath))
                        discoveryPaths.Add(usage.WsModelPath);
                }

                RecordGameplayMeshDiscoveryBlock(
                    state,
                    "AtlasRewrite",
                    discoveryPaths);

                RecordSkip(
                    state,
                    candidate.RootVmdPath,
                    candidate.Key,
                    candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                    "Gameplay mesh-consumer discovery was incomplete; atlas rewriting was skipped because every rigid material consumer could not be proven safe.");
            }
            candidates = discoverySafeCandidates;

            // A rigid owns UV0, so every material consumer must be rewritten together with
            // it. Direct embedded materials are safe only when there is no WSModel material
            // consumer for the same key; immutable CA WSModels are never safe because their
            // material nodes cannot be rewritten at all. Reject the whole key so discovery
            // ordering cannot let another candidate slip through after the first one.
            var blockedKeys = candidates
                .Where(candidate => HasUnrewritableMaterialConsumerAtlasConflict(state, candidate))
                .Select(candidate => candidate.Key)
                .ToHashSet();
            if (blockedKeys.Count == 0)
                return candidates.ToList();

            foreach (var candidate in candidates.Where(candidate => blockedKeys.Contains(candidate.Key)))
            {
                RecordSkip(
                    state,
                    candidate.RootVmdPath,
                    candidate.Key,
                    candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                    "Rigid mesh has a non-rewritable material consumer (direct/embedded or immutable CA WSModel); atlas rewriting would change shared UV0 without rewriting every consumer.");
            }

            return candidates
                .Where(candidate => !blockedKeys.Contains(candidate.Key))
                .ToList();
        }

        private static void RecordGameplayMeshDiscoveryBlock(
            BatchState state,
            string blockKind,
            IEnumerable<string> assetPaths)
        {
            var index = state.GameplayMeshDependencyIndex;
            var globalDiscoveryFailure = index == null ||
                                         state.UnitCategoryResolution == null ||
                                         !state.UnitCategoryResolution.IsGameplayResolutionHealthy;
            foreach (var assetPathValue in assetPaths)
            {
                var assetPath = Normalize(assetPathValue);
                if (assetPath.Length == 0)
                    continue;

                var incompleteRoots = index?.GetIncompleteRootsForAsset(assetPath)
                    ?? Array.Empty<string>();
                if (incompleteRoots.Count == 0)
                {
                    if (globalDiscoveryFailure ||
                        index?.IsAssetAffectedByIncompleteRoot(assetPath) == true)
                    {
                        state.ConsumerDiscoveryBlocks.Add(
                            new GameplayMeshDiscoveryBlock(
                                assetPath,
                                blockKind,
                                globalDiscoveryFailure
                                    ? "<global>"
                                    : "<unattributed>"));
                    }

                    continue;
                }

                foreach (var incompleteRoot in incompleteRoots)
                {
                    state.ConsumerDiscoveryBlocks.Add(
                        new GameplayMeshDiscoveryBlock(
                            assetPath,
                            blockKind,
                            incompleteRoot));
                }
            }
        }

        private static bool HasUnrewritableMaterialConsumerAtlasConflict(
            BatchState state,
            AtlasCandidate candidate)
        {
            var geometryPath = Normalize(candidate.Key.GeometryPath);
            if (GetImmutableGameplayWsModelConsumersForRigid(
                    state,
                    geometryPath).Count != 0)
            {
                return true;
            }

            var hasWsModelMaterialConsumer = candidate.Usages.Any(
                usage => string.IsNullOrWhiteSpace(usage.EmbeddedRigidPath));
            if (!hasWsModelMaterialConsumer &&
                state.Usages.TryGetValue(candidate.Key, out var usages))
            {
                hasWsModelMaterialConsumer = usages.Any(
                    usage => string.IsNullOrWhiteSpace(usage.EmbeddedRigidPath));
            }

            return HasDirectRigidConsumerAtlasConflict(
                state,
                geometryPath,
                hasWsModelMaterialConsumer);
        }

        private static bool HasDirectRigidConsumerAtlasConflict(
            BatchState state,
            string geometryPath,
            bool hasWsModelMaterialConsumer)
            => hasWsModelMaterialConsumer &&
               HasDirectGameplayRigidConsumer(state, geometryPath);

        private static List<AtlasCandidate> ApplyMissingTextureDecision(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates)
        {
            var result = new List<AtlasCandidate>(candidates.Count);

            foreach (var candidate in candidates)
            {
                if (candidate.MissingTextures.Count == 0)
                {
                    result.Add(candidate);
                    continue;
                }

                var firstMissing = candidate.MissingTextures[0];
                RecordSkip(
                    state,
                    candidate.RootVmdPath,
                    candidate.Key,
                    candidate.Usages[0].AssetPath,
                    $"{firstMissing.Slot} texture could not be resolved; mesh cannot be safely atlased because UV0 is shared across channels: {firstMissing.TexturePath}");
            }

            return result;
        }

        private void ProcessVmd(
            BatchState state,
            string rootVmdPath,
            List<AtlasCandidate> candidates,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            candidates = candidates
                .Where(x => !state.ProcessedMeshes.Contains(x.Key))
                .ToList();
            candidates = ApplyTexelDensityScaling(state, candidates);
            candidates = AlignSharedUvIslandCuts(state, candidates);

            var batches = CreateBatches(
                state,
                candidates,
                packWide: false,
                cancellationToken: cancellationToken,
                progress: progress);

            ProcessAtlasBatches(
                state,
                rootVmdPath,
                rootVmdPath,
                batches,
                cancellationToken,
                progress);
        }

        private void ProcessDirectAssetAtlases(
            BatchState state,
            List<AtlasCandidate> candidates,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            candidates = candidates
                .Where(candidate => !state.ProcessedMeshes.Contains(candidate.Key))
                .ToList();
            if (candidates.Count == 0)
                return;

            candidates = ApplyTexelDensityScaling(state, candidates);
            candidates = AlignSharedUvIslandCuts(state, candidates);
            var batches = CreateBatches(
                state,
                candidates,
                packWide: false,
                cancellationToken: cancellationToken,
                progress: progress);
            ProcessAtlasBatches(
                state,
                "direct-engine-assets",
                "Direct engine assets",
                batches,
                cancellationToken,
                progress);
        }

        private static bool IsDirectAssetCandidate(AtlasCandidate candidate)
            => candidate.Usages.Any(usage => !string.IsNullOrWhiteSpace(usage.EmbeddedRigidPath)) ||
               candidate.Usages.Any(usage =>
                   !string.IsNullOrWhiteSpace(usage.WsModelPath) &&
                   Path.GetExtension(usage.WsModelPath)
                       .Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) &&
                   usage.WsModelPath.Equals(
                       candidate.RootVmdPath,
                       StringComparison.OrdinalIgnoreCase));

        private void ProcessPackWideAtlases(
            BatchState state,
            List<AtlasCandidate> candidates,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            state.PackWideCandidateCount = candidates.Count;
            candidates = ApplyTexelDensityScaling(state, candidates);
            candidates = AlignSharedUvIslandCuts(state, candidates);

            var stopwatch = Stopwatch.StartNew();
            var batches = CreateBatches(
                state,
                candidates,
                packWide: true,
                cancellationToken: cancellationToken,
                progress: progress);
            AddPhaseDuration(state, "Plan atlas batches", stopwatch.Elapsed);

            stopwatch.Restart();
            var packName = Path.GetFileNameWithoutExtension(state.SourcePath);
            ProcessAtlasBatches(
                state,
                $"pack:{packName}",
                "Pack-wide",
                batches,
                cancellationToken,
                progress);
            AddPhaseDuration(state, "Execute atlas batches", stopwatch.Elapsed);
        }

        private void ProcessAtlasBatches(
            BatchState state,
            string atlasScopeKey,
            string progressScope,
            IReadOnlyList<List<AtlasCandidate>> batches,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var pageGroups = BuildSharedAtlasPageGroups(
                state,
                batches,
                cancellationToken,
                progress);
            var pageGroupByBatchIndex = new SharedAtlasPageGroup[batches.Count];
            foreach (var pageGroup in pageGroups)
            {
                foreach (var batchIndex in pageGroup.BatchIndices)
                    pageGroupByBatchIndex[batchIndex] = pageGroup;
            }

            var generatedPages = new Dictionary<SharedAtlasPageGroup, SharedAtlasPage>();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var pageGroup = pageGroupByBatchIndex[batchIndex]
                    ?? throw new InvalidOperationException(
                        $"Atlas batch {batchIndex} was not assigned to a shared atlas page group.");
                if (!generatedPages.TryGetValue(pageGroup, out var sharedPage))
                {
                    sharedPage = GenerateSharedAtlasPage(
                        state,
                        atlasScopeKey,
                        progressScope,
                        pageGroup,
                        cancellationToken,
                        progress);
                    generatedPages.Add(pageGroup, sharedPage);
                }

                ReportProgress(
                    progress,
                    "Building texture atlases",
                    batchIndex + 1,
                    batches.Count,
                    $"{progressScope} — batch {batchIndex + 1} ({sharedPage.AtlasStem})");

                ProcessBatch(
                    state,
                    atlasScopeKey,
                    progressScope,
                    batches[batchIndex],
                    cancellationToken,
                    progress,
                    sharedPage);
            }
        }

        private static List<SharedAtlasPageGroup> BuildSharedAtlasPageGroups(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var pageGroups = new List<SharedAtlasPageGroup>();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var batch = batches[batchIndex];
                ReportProgress(
                    progress,
                    "Planning shared atlas pages",
                    batchIndex + 1,
                    batches.Count,
                    $"Checking batch {batchIndex + 1}");

                var canShare = TryGetSharedAtlasPageCompatibilityKey(
                    batch,
                    out var compatibilityKey);
                var hasSinglePagePlan = TryCreateSharedAtlasPagePlan(
                    state,
                    batch,
                    out var singlePagePlan);
                SharedAtlasPageGroup? selectedGroup = null;

                if (canShare && hasSinglePagePlan)
                {
                    foreach (var pageGroup in pageGroups)
                    {
                        if (!pageGroup.CompatibilityKey.HasValue ||
                            pageGroup.CompatibilityKey.Value != compatibilityKey ||
                            pageGroup.PagePlan == null)
                        {
                            continue;
                        }

                        state.SharedAtlasPageSharingEvaluations++;
                        var combinedCandidates = pageGroup.Candidates
                            .Concat(batch)
                            .ToList();
                        if (!TryCreateSharedAtlasPagePlan(
                                state,
                                combinedCandidates,
                                out var combinedPagePlan) ||
                            !FitsWithinReplacedPageBudget(
                                pageGroup.OriginalPageFootprints
                                    .Append(singlePagePlan.Footprint)
                                    .ToArray(),
                                combinedPagePlan.Footprint))
                        {
                            continue;
                        }

                        selectedGroup = pageGroup;
                        pageGroup.BatchIndices.Add(batchIndex);
                        pageGroup.Batches.Add(batch);
                        pageGroup.Candidates.AddRange(batch);
                        pageGroup.OriginalPageFootprints.Add(singlePagePlan.Footprint);
                        pageGroup.PagePlan = combinedPagePlan;
                        break;
                    }
                }

                if (selectedGroup != null)
                    continue;

                pageGroups.Add(
                    new SharedAtlasPageGroup(
                        canShare ? compatibilityKey : null,
                        new List<int> { batchIndex },
                        new List<List<AtlasCandidate>> { batch },
                        batch.ToList(),
                        hasSinglePagePlan ? singlePagePlan : null,
                        hasSinglePagePlan
                            ? new List<AtlasPageFootprint> { singlePagePlan.Footprint }
                            : []));
            }

            foreach (var pageGroup in pageGroups.Where(x => x.BatchIndices.Count > 1))
            {
                state.SharedAtlasPageCoalescesAccepted++;
                state.SharedAtlasPageParticipatingBatches += pageGroup.BatchIndices.Count;
                var originalPixels = pageGroup.OriginalPageFootprints.Sum(x => x.PixelCost);
                var sharedPixels = pageGroup.PagePlan?.Footprint.PixelCost ?? originalPixels;
                state.SharedAtlasPagePixelsSaved = checked(
                    state.SharedAtlasPagePixelsSaved +
                    Math.Max(0, originalPixels - sharedPixels));
            }

            return pageGroups;
        }

        private static bool TryGetSharedAtlasPageCompatibilityKey(
            IReadOnlyList<AtlasCandidate> batch,
            out SharedAtlasPageCompatibilityKey compatibilityKey)
        {
            compatibilityKey = default;
            if (batch.Count == 0)
                return false;

            var roots = batch
                .Select(candidate => Normalize(candidate.RootVmdPath))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
            if (roots.Length != 1 || string.IsNullOrWhiteSpace(roots[0]))
                return false;

            // Source identities, channel modes, resolution scales, and material shaders do
            // not need to match: each material is rewritten independently against the shared
            // placement. The combined plan and page budget are the physical safety checks.
            compatibilityKey = new SharedAtlasPageCompatibilityKey(
                roots[0],
                BuildSharedAtlasPageOutputPolicySignature());
            return true;
        }

        private static string BuildSharedAtlasPageOutputPolicySignature()
            => string.Join(
                "\u001f",
                "raw-bgra-mip-chain-v1",
                PackAtlasMaxSize,
                TextureAtlasBuilder.DefaultPadding,
                string.Join(
                    "\u001d",
                    AtlasChannels.Select(channel =>
                        $"{channel.Slot}:{channel.Type}:{channel.Suffix}")));

        private static bool TryCreateSharedAtlasPagePlan(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out SharedAtlasPagePlan pagePlan)
        {
            try
            {
                var sharedPlan = CreateSharedAtlasPlan(
                    state,
                    candidates,
                    deduplicateByContent: true);
                var footprint = CalculateAtlasPageFootprint(sharedPlan);
                pagePlan = new SharedAtlasPagePlan(
                    sharedPlan.Batch,
                    sharedPlan.Plan,
                    footprint);
                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or ArgumentException or OverflowException)
            {
                pagePlan = null!;
                return false;
            }
        }

        private static AtlasPageFootprint CalculateAtlasPageFootprint(
            (SharedAtlasBatch Batch, TextureAtlasPlan Plan) sharedPlan)
        {
            var outputDimensionsByChannel =
                new Dictionary<string, (int Width, int Height)>(StringComparer.OrdinalIgnoreCase);
            long pixelCost = 0;

            foreach (var channel in AtlasChannels)
            {
                var sourceDimensions = new Dictionary<int, (int Width, int Height)>();
                foreach (var source in sharedPlan.Batch.Sources)
                {
                    var representative = source.Representative;
                    if (representative.ResolvedChannels.Contains(channel.Slot) &&
                        representative.ChannelDimensions.TryGetValue(
                            channel.Slot,
                            out var dimensions))
                    {
                        sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                            representative,
                            dimensions.Width,
                            dimensions.Height);
                    }
                }

                var requiresConstantOnlyAtlas = RequiresConstantOnlyMaskAtlas(
                    channel.Slot,
                    sharedPlan.Batch.Sources);
                if (sourceDimensions.Count == 0 && !requiresConstantOnlyAtlas)
                    continue;

                var outputDimensions = TextureAtlasBuilder.CalculateOutputDimensions(
                    sharedPlan.Plan,
                    sourceDimensions,
                    PackAtlasMaxSize);
                outputDimensionsByChannel[channel.Slot] = outputDimensions;
                pixelCost = checked(
                    pixelCost +
                    (long)outputDimensions.Width * outputDimensions.Height);
            }

            return new AtlasPageFootprint(outputDimensionsByChannel, pixelCost);
        }

        private SharedAtlasPage GenerateSharedAtlasPage(
            BatchState state,
            string atlasScopeKey,
            string progressScope,
            SharedAtlasPageGroup pageGroup,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var pagePlan = pageGroup.PagePlan;
            if (pagePlan == null)
            {
                if (!TryCreateSharedAtlasPagePlan(
                        state,
                        pageGroup.Candidates,
                        out pagePlan))
                {
                    throw new InvalidOperationException(
                        "Could not create the shared atlas page plan for an accepted atlas batch.");
                }

                pageGroup.PagePlan = pagePlan;
            }

            var sharedBatch = pagePlan.Batch;
            var plan = pagePlan.Plan;
            var candidates = pageGroup.Candidates;
            state.AtlasPlacementsGenerated += sharedBatch.Sources.Count;
            state.AtlasPlacementsReused += candidates.Count - sharedBatch.Sources.Count;
            state.WrappedUvPlacementsCanonicalized += sharedBatch.MappingByMesh.Values.Count(
                x => x.WrappedUvCanonicalized);
            state.ContentDeduplicatedAtlasPlacements += sharedBatch.ContentPlacementsReused;
            state.ContentCanonicalizedMeshReferences += sharedBatch.MappingByMesh.Values.Count(
                x => x.ContentCanonicalized);

            var atlasStem = BuildAtlasStem(atlasScopeKey, state.AtlasPageIndex++);
            var generatedPaths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            for (var channelIndex = 0; channelIndex < AtlasChannels.Length; channelIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var channel = AtlasChannels[channelIndex];
                ReportProgress(
                    progress,
                    "Building texture atlases",
                    channelIndex + 1,
                    AtlasChannels.Length,
                    $"{progressScope} — {channel.Suffix}");
                var textureBytes = new Dictionary<int, byte[]>();
                var textureBytesByPath = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);
                var constantSources = new Dictionary<int, TextureAtlasConstantColor>();
                var omitted = new HashSet<int>();

                foreach (var source in sharedBatch.Sources)
                {
                    var representative = source.Representative;
                    if (representative.ResolvedChannels.Contains(channel.Slot))
                    {
                        var sourcePath = GetTexturePath(representative.MaterialDocument, channel.Slot);
                        if (string.IsNullOrWhiteSpace(sourcePath))
                        {
                            throw new InvalidOperationException(
                                $"Resolved atlas channel {channel.Slot} has no texture path for {representative.Key}.");
                        }

                        sourcePath = Normalize(sourcePath);
                        if (!textureBytesByPath.TryGetValue(sourcePath, out var bytes))
                        {
                            var file = FindForRead(state, sourcePath)
                                ?? throw new InvalidOperationException(
                                    $"Resolved atlas texture no longer exists: {sourcePath}");
                            bytes = file.DataSource.ReadData();
                            textureBytesByPath[sourcePath] = bytes;
                        }

                        textureBytes[source.Id] = bytes;
                    }
                    else if (representative.ConstantChannels.TryGetValue(
                                 channel.Slot,
                                 out var constantColor))
                    {
                        constantSources[source.Id] = constantColor;
                    }
                    else
                    {
                        omitted.Add(source.Id);
                    }
                }

                var requiresConstantOnlyAtlas = RequiresConstantOnlyMaskAtlas(
                    channel.Slot,
                    sharedBatch.Sources);
                if (textureBytes.Count == 0 && !requiresConstantOnlyAtlas)
                {
                    // UV remapping cannot change a uniform texture. If every present source
                    // for this channel is constant, keep each material's original shared
                    // constant texture path instead of allocating/compressing an atlas.
                    if (constantSources.Count != 0)
                        state.ConstantOnlyAtlasChannelsSkipped++;
                    continue;
                }

                var sourceDimensions = new Dictionary<int, (int Width, int Height)>();
                foreach (var source in sharedBatch.Sources)
                {
                    if (textureBytes.ContainsKey(source.Id) &&
                        source.Representative.ChannelDimensions.TryGetValue(
                            channel.Slot,
                            out var dimensions))
                    {
                        sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                            source.Representative,
                            dimensions.Width,
                            dimensions.Height);
                    }
                }

                var outputDimensions = TextureAtlasBuilder.CalculateOutputDimensions(
                    plan,
                    sourceDimensions,
                    PackAtlasMaxSize);

                var fileName = $"{atlasStem}_{channel.Suffix}.dds";
                using var mipWriter = PngToDdsImporter.CreateRawBgraMipChainWriter(
                    outputDimensions.Width,
                    outputDimensions.Height,
                    TextureAtlasBuilder.CalculateMipLevelCount(
                        outputDimensions.Width,
                        outputDimensions.Height),
                    channel.Type,
                    GameTypeEnum.Warhammer3,
                    collectCompressionStatistics: AtlasProfilingEnabled);

                var rasterStatistics = AtlasProfilingEnabled
                    ? new TextureAtlasBuildStatistics()
                    : null;
                var rasterStopwatch = Stopwatch.StartNew();
                var clearBlueSourceIds = channel.Slot.Equals(
                        "t_xml_mask",
                        StringComparison.OrdinalIgnoreCase)
                    ? sharedBatch.Sources
                        .Where(source => source.Representative.ClearMaskBlueChannel)
                        .Select(source => source.Id)
                        .ToHashSet()
                    : null;
                _ = TextureAtlasBuilder.BuildMipPixels(
                    plan,
                    textureBytes,
                    forceOpaqueAlphaSourceIds: null,
                    omittedSourceIds: omitted,
                    cancellationToken: cancellationToken,
                    heartbeat: () =>
                    {
                        ReportProgress(
                            progress,
                            "Building texture atlases",
                            channelIndex + 1,
                            AtlasChannels.Length,
                            $"{progressScope} — {channel.Suffix}");
                        cancellationToken.ThrowIfCancellationRequested();
                    },
                    constantSources: constantSources,
                    outputWidth: outputDimensions.Width,
                    outputHeight: outputDimensions.Height,
                    mipConsumer: (mipLevel, mipWidth, mipHeight, pixels) =>
                        mipWriter.WriteMip(mipLevel, pixels),
                    retainMipPixels: false,
                    statistics: rasterStatistics,
                    clearBlueSourceIds: clearBlueSourceIds);
                rasterStopwatch.Stop();
                var rasterElapsed = rasterStopwatch.Elapsed;
                AddPhaseDuration(state, "Rasterize atlas pixels", rasterElapsed);

                var usesLargeBcSplitCompression = mipWriter.UsesLargeBcSplitCompression;
                if (usesLargeBcSplitCompression)
                    state.LargeBcSplitCompressionChannels++;

                var compressionStopwatch = Stopwatch.StartNew();
                var atlasPackFile = mipWriter.Complete(fileName);
                compressionStopwatch.Stop();
                var compressionElapsed = compressionStopwatch.Elapsed;
                var compressionStatistics = mipWriter.LastCompressionStatistics;
                AddPhaseDuration(state, "Compress atlas DDS", compressionElapsed);
                var atlasPath = Normalize($@"{AtlasDirectory}\{fileName}");

                if (AtlasProfilingEnabled && rasterStatistics != null)
                {
                    state.GeneratedTextureTimings.Add(new GeneratedTextureTimingEntry(
                        atlasPath,
                        outputDimensions.Width,
                        outputDimensions.Height,
                        channel.Type,
                        DDSFormatHelper.GetDDSFormat(GameTypeEnum.Warhammer3, channel.Type),
                        rasterElapsed,
                        compressionElapsed,
                        usesLargeBcSplitCompression,
                        rasterStatistics,
                        compressionStatistics));
                }

                WriteFile(state.Output, atlasPath, atlasPackFile.DataSource.ReadData());
                generatedPaths[channel.Slot] = atlasPath;
                state.GeneratedTexturePaths.Add(atlasPath);
                state.GeneratedTextureDimensions[atlasPath] = outputDimensions;
            }

            RecordAtlasPhysicalPageResidency(state, candidates, generatedPaths);
            state.AtlasPlacementDiagnostics.Add(
                BuildAtlasPlacementDiagnosticSnapshot(
                    atlasStem,
                    plan,
                    sharedBatch,
                    candidates,
                    generatedPaths));

            return new SharedAtlasPage(
                sharedBatch,
                plan,
                atlasStem,
                generatedPaths);
        }

        private static void RecordAtlasPhysicalPageResidency(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyDictionary<string, string> generatedPaths)
        {
            long pixelCost = 0;
            foreach (var atlasPath in generatedPaths.Values.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                if (!state.GeneratedTextureDimensions.TryGetValue(atlasPath, out var dimensions))
                    continue;

                pixelCost = checked(
                    pixelCost +
                    (long)dimensions.Width * dimensions.Height);
            }

            state.AtlasPhysicalPageDiagnostics.Add(
                new AtlasPhysicalPageDiagnostic(candidates.ToList(), pixelCost));
        }

        // A shared page may trade rectangular shape for area: two 1024x2048 pages can
        // legitimately become one 2048x2048 page. Keep both the raw-pixel guard and a
        // per-channel BCn mip-chain budget, but do not require the result to fit inside
        // one of the replaced rectangles.
        private static bool FitsWithinReplacedPageBudget(
            IReadOnlyList<AtlasPageFootprint> originalPages,
            AtlasPageFootprint combinedPage)
        {
            if (originalPages.Count == 0)
                return false;

            var originalPixelCost = originalPages.Sum(page => page.PixelCost);
            if (combinedPage.PixelCost > originalPixelCost)
                return false;

            foreach (var (channel, combinedDimensions) in combinedPage.OutputDimensionsByChannel)
            {
                var combinedBcnBytes = CalculateAtlasChannelBcnMipChainBytes(
                    channel,
                    combinedDimensions);
                var originalBcnBytes = originalPages.Sum(originalPage =>
                    originalPage.OutputDimensionsByChannel.TryGetValue(
                        channel,
                        out var originalDimensions)
                        ? CalculateAtlasChannelBcnMipChainBytes(channel, originalDimensions)
                        : 0L);

                if (combinedBcnBytes > originalBcnBytes)
                {
                    return false;
                }
            }

            return true;
        }

        private static long CalculateAtlasChannelBcnMipChainBytes(
            string channelSlot,
            (int Width, int Height) dimensions)
        {
            var channel = AtlasChannels.Single(candidate =>
                candidate.Slot.Equals(channelSlot, StringComparison.OrdinalIgnoreCase));
            var bytesPerBlock = channel.Type is TextureType.BaseColour or TextureType.MaterialMap
                ? 8
                : 16;
            return CalculateBcnMipChainBytes(
                dimensions.Width,
                dimensions.Height,
                bytesPerBlock);
        }

        private List<AtlasCandidate> CollectVmdCandidates(
            BatchState state,
            string rootVmdPath,
            int vmdIndex,
            int vmdCount,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress,
            HashSet<MeshKey>? inspectedKeys = null,
            List<MissingTextureDependency>? missingTextureDependencies = null)
        {
            ReportProgress(progress, "Discovering atlas candidates", vmdIndex, vmdCount, rootVmdPath);
            var wsModels = GetReachableWsModels(state, rootVmdPath, cancellationToken);
            var candidates = new List<AtlasCandidate>();
            var localInspectedKeys = inspectedKeys ?? new HashSet<MeshKey>();

            foreach (var wsPath in wsModels)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var wsFile = state.Source.FindFile(wsPath);
                if (wsFile == null ||
                    !TryGetWsDocumentForTraversal(
                        state,
                        state.Source,
                        wsPath,
                        wsFile,
                        out var doc))
                {
                    continue;
                }

                var geometryPath = Normalize(doc.SelectSingleNode("/model/geometry")?.InnerText);
                if (string.IsNullOrWhiteSpace(geometryPath))
                    continue;

                var rmv = GetRmv(state, geometryPath);
                if (rmv == null)
                    continue;

                var materialNodes = doc.SelectNodes("/model/materials/material");
                if (materialNodes == null)
                    continue;

                foreach (XmlNode node in materialNodes)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!TryParseIndex(node, "lod_index", out var lodIndex) ||
                        !TryParseIndex(node, "part_index", out var partIndex) ||
                        lodIndex < 0 || lodIndex >= rmv.ModelList.Length ||
                        partIndex < 0 || partIndex >= rmv.ModelList[lodIndex].Length)
                    {
                        continue;
                    }

                    var key = new MeshKey(geometryPath, lodIndex, partIndex);
                    ReportProgress(
                        progress,
                        "Discovering atlas candidates",
                        vmdIndex,
                        vmdCount,
                        $"{rootVmdPath} — {key}");

                    if (state.ProcessedMeshes.Contains(key) || !localInspectedKeys.Add(key))
                        continue;

                    if (!state.Usages.TryGetValue(key, out var usages) || usages.Count == 0)
                        continue;

                    var materialPaths = usages
                        .Select(x => x.MaterialPath)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList();

                    // The rigid owns UV0, not the WSModel. If the same rigid mesh is used with
                    // different materials, rewriting its UVs would require atlasing every one of
                    // those material variants with the same placement. Keep that uncommon case
                    // untouched rather than silently breaking one of the users.
                    if (materialPaths.Count != 1)
                    {
                        RecordSkip(
                            state,
                            rootVmdPath,
                            key,
                            wsPath,
                            $"Rigid mesh is shared by WSModels using {materialPaths.Count} different materials.");
                        continue;
                    }

                    var candidate = TryCreateCandidate(
                        state,
                        rootVmdPath,
                        key,
                        rmv.ModelList[lodIndex][partIndex],
                        usages,
                        missingTextureDependencies,
                        out var skipReason);
                    if (candidate == null)
                    {
                        RecordSkip(state, rootVmdPath, key, wsPath, skipReason);
                        continue;
                    }

                    candidates.Add(candidate);
                }
            }

            return candidates;
        }

        private List<AtlasCandidate> CollectDirectAssetCandidates(
            BatchState state,
            IReadOnlyList<string> assetPaths,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress,
            HashSet<MeshKey>? inspectedKeys,
            List<MissingTextureDependency>? missingTextureDependencies)
        {
            var candidates = new List<AtlasCandidate>();
            var localInspectedKeys = inspectedKeys ?? new HashSet<MeshKey>();

            for (var assetIndex = 0; assetIndex < assetPaths.Count; assetIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var assetPath = Normalize(assetPaths[assetIndex]);
                ReportProgress(
                    progress,
                    "Discovering direct engine assets",
                    assetIndex + 1,
                    assetPaths.Count,
                    assetPath);

                var extension = Path.GetExtension(assetPath);
                if (extension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase))
                {
                    var file = state.Source.FindFile(assetPath);
                    if (file == null)
                        continue;

                    RmvFile rmv;
                    try
                    {
                        rmv = GetRmv(state, assetPath) ??
                            throw new InvalidDataException("Rigid model could not be loaded.");
                    }
                    catch (Exception ex)
                    {
                        RecordDirectAssetSkip(
                            state,
                            assetPath,
                            $"Rigid engine asset could not be loaded: {ex.Message}");
                        continue;
                    }

                    for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
                    {
                        for (var partIndex = 0;
                             partIndex < rmv.ModelList[lodIndex].Length;
                             partIndex++)
                        {
                            cancellationToken.ThrowIfCancellationRequested();
                            var key = new MeshKey(assetPath, lodIndex, partIndex);
                            if (state.ProcessedMeshes.Contains(key) || !localInspectedKeys.Add(key))
                                continue;

                            var model = rmv.ModelList[lodIndex][partIndex];
                            var usage = new WsUsage(
                                string.Empty,
                                null,
                                null,
                                BuildEmbeddedMaterialPath(assetPath, lodIndex, partIndex),
                                assetPath);
                            var candidate = TryCreateCandidate(
                                state,
                                assetPath,
                                key,
                                model,
                                [usage],
                                missingTextureDependencies,
                                out var skipReason,
                                BuildEmbeddedMaterialDocument(model.Material));
                            if (candidate == null)
                            {
                                RecordSkip(state, assetPath, key, string.Empty, skipReason);
                                continue;
                            }

                            candidates.Add(candidate);
                        }
                    }

                    continue;
                }

                if (!extension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase))
                    continue;

                XmlDocument document;
                try
                {
                    document = GetWsDocument(state, assetPath)
                        ?? throw new InvalidDataException("WSModel could not be loaded.");
                }
                catch (Exception ex)
                {
                    RecordDirectAssetSkip(
                        state,
                        assetPath,
                        $"WSModel engine asset could not be loaded: {ex.Message}");
                    continue;
                }

                var geometryPath = Normalize(
                    document.SelectSingleNode("/model/geometry")?.InnerText);
                if (geometryPath.Length == 0)
                    continue;

                var rmvForWsModel = GetRmv(state, geometryPath);
                var materialNodes = document.SelectNodes("/model/materials/material");
                if (rmvForWsModel == null || materialNodes == null)
                    continue;

                foreach (XmlNode materialNode in materialNodes)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!TryParseIndex(materialNode, "lod_index", out var lodIndex) ||
                        !TryParseIndex(materialNode, "part_index", out var partIndex) ||
                        lodIndex < 0 ||
                        lodIndex >= rmvForWsModel.ModelList.Length ||
                        partIndex < 0 ||
                        partIndex >= rmvForWsModel.ModelList[lodIndex].Length)
                    {
                        continue;
                    }

                    var key = new MeshKey(geometryPath, lodIndex, partIndex);
                    if (state.ProcessedMeshes.Contains(key) || !localInspectedKeys.Add(key))
                        continue;

                    var materialPath = Normalize(materialNode.InnerText);
                    if (materialPath.Length == 0)
                        continue;

                    var usage = new WsUsage(assetPath, document, materialNode, materialPath);
                    var candidate = TryCreateCandidate(
                        state,
                        assetPath,
                        key,
                        rmvForWsModel.ModelList[lodIndex][partIndex],
                        [usage],
                        missingTextureDependencies,
                        out var skipReason);
                    if (candidate == null)
                    {
                        RecordSkip(state, assetPath, key, assetPath, skipReason);
                        continue;
                    }

                    candidates.Add(candidate);
                }
            }

            return candidates;
        }

        private AtlasCandidate? TryCreateCandidate(
            BatchState state,
            string rootVmdPath,
            MeshKey key,
            RmvModel model,
            List<WsUsage> usages,
            List<MissingTextureDependency>? missingTextureDependencies,
            out string skipReason,
            XmlDocument? materialDocumentOverride = null)
        {
            skipReason = string.Empty;
            if (!IsCandidateSharedMeshSafeForGameplay(state, key, usages))
            {
                skipReason =
                    "Rigid mesh is shared with a WSModel reachable from an unresolved " +
                    "gameplay consumer; gameplay-used mode leaves the shared asset unchanged.";
                return null;
            }

            var materialPath = usages[0].MaterialPath;
            XmlDocument materialDoc;
            if (materialDocumentOverride != null)
            {
                if (TryGetUnsafeEmbeddedUvTexture(model.Material, out var unsafeTexture))
                {
                    skipReason =
                        $"Embedded rigid material contains UV0-dependent texture type " +
                        $"{unsafeTexture.TexureType} that is not rewritten by the atlas path: " +
                        $"{unsafeTexture.Path}";
                    return null;
                }

                materialDoc = materialDocumentOverride;
            }
            else
            {
                var materialFile = FindForRead(state, materialPath);
                if (materialFile == null)
                {
                    skipReason = $"Material file could not be resolved: {materialPath}";
                    return null;
                }

                try
                {
                    materialDoc = GetMaterialDocument(state, materialPath, materialFile);
                }
                catch (Exception ex)
                {
                    skipReason = $"Material XML could not be parsed: {materialPath} ({ex.Message})";
                    return null;
                }
            }

            // GetMaterialDocument returns the cached source XML. Canonical mask rewriting is
            // candidate-local, so never mutate that shared document while preparing a batch.
            if (materialDocumentOverride == null)
            {
                var sourceMaterial = materialDoc;
                materialDoc = new XmlDocument();
                materialDoc.LoadXml(sourceMaterial.OuterXml);
            }

            var shaderPath = materialDoc.SelectSingleNode("/material/shader")?.InnerText ?? string.Empty;
            if (shaderPath.Contains("emissive", StringComparison.OrdinalIgnoreCase))
            {
                skipReason = $"Emissive shader is intentionally not atlased: {shaderPath}";
                return null;
            }

            if (materialDoc.SelectNodes("/material/textures/texture")?
                    .Cast<XmlNode>()
                    .Any(x => GetTextureSlot(x).Contains("emissive", StringComparison.OrdinalIgnoreCase)) == true)
            {
                skipReason = "Material contains an emissive texture slot and must retain its original UV0 mapping.";
                return null;
            }

            var primaryPath = GetTexturePath(materialDoc, "t_xml_base_colour");
            if (string.IsNullOrWhiteSpace(primaryPath))
            {
                skipReason = "Material has no t_xml_base_colour texture.";
                return null;
            }

            var faction3MaskCanonicalization = materialDocumentOverride == null
                ? CanonicalizeFaction3MaskParameter(materialDoc)
                : Faction3MaskCanonicalization.None;
            var canonicalMaskWasAdded = false;
            var clearMaskBlueChannel = false;
            var requiresMaskAtlas = false;
            if (faction3MaskCanonicalization != Faction3MaskCanonicalization.None)
            {
                var maskPath = GetTexturePath(materialDoc, "t_xml_mask");
                var maskIsAbsent = string.IsNullOrWhiteSpace(maskPath) ||
                    IsTexturePlaceholder(maskPath) ||
                    (IsIgnorableUnresolvedAtlasTexture("t_xml_mask", maskPath) &&
                     FindForRead(state, maskPath) == null);
                if (maskIsAbsent)
                {
                    EnsureTexturePath(
                        materialDoc,
                        "t_xml_mask",
                        CanonicalBlackMaskTexturePath);
                    canonicalMaskWasAdded = true;
                    requiresMaskAtlas = true;
                }
                else if (faction3MaskCanonicalization == Faction3MaskCanonicalization.ZeroSelector)
                {
                    // The old selector ignored this texture completely. Preserve that exact
                    // result after switching to the common blue-channel selector by clearing
                    // only blue in the source region; green, red and alpha remain untouched
                    // for the other mask consumers.
                    clearMaskBlueChannel = true;
                    requiresMaskAtlas = true;
                }
            }

            var candidateMissingTextures = new List<MissingTextureDependency>();
            var resolvedChannels = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var constantChannels = new Dictionary<string, TextureAtlasConstantColor>(
                StringComparer.OrdinalIgnoreCase);
            var channelDimensions = new Dictionary<string, (int Width, int Height)>(
                StringComparer.OrdinalIgnoreCase);

            int? primaryWidth = null;
            int? primaryHeight = null;

            foreach (var channel in AtlasChannels)
            {
                var path = GetTexturePath(materialDoc, channel.Slot);
                if (string.IsNullOrWhiteSpace(path))
                {
                    if (channel.Slot.Equals("t_xml_base_colour", StringComparison.OrdinalIgnoreCase))
                    {
                        skipReason = "Material has no t_xml_base_colour texture.";
                        return null;
                    }

                    continue;
                }

                if (IsTexturePlaceholder(path))
                    continue;

                var file = FindForRead(state, path);
                if (canonicalMaskWasAdded &&
                    channel.Slot.Equals("t_xml_mask", StringComparison.OrdinalIgnoreCase) &&
                    path.Equals(CanonicalBlackMaskTexturePath, StringComparison.OrdinalIgnoreCase))
                {
                    constantChannels[channel.Slot] = ZeroMaskColor;
                    RegisterUniformConstantTextureCanonicalPath(
                        state,
                        channel.Slot,
                        ZeroMaskColor,
                        CanonicalBlackMaskTexturePath);
                    continue;
                }

                if (file == null)
                {
                    if (channel.Slot.Equals("t_xml_base_colour", StringComparison.OrdinalIgnoreCase))
                    {
                        skipReason = $"Base-colour texture could not be resolved: {path}";
                        return null;
                    }

                    if (IsIgnorableUnresolvedAtlasTexture(channel.Slot, path))
                        continue;

                    var missing = new MissingTextureDependency(
                        key,
                        channel.Slot,
                        path);
                    candidateMissingTextures.Add(missing);
                    missingTextureDependencies?.Add(missing);
                    continue;
                }

                try
                {
                    var inspection = GetTextureInspection(state, path, file);

                    if (channel.Slot.Equals("t_xml_base_colour", StringComparison.OrdinalIgnoreCase))
                    {
                        primaryWidth = inspection.Width;
                        primaryHeight = inspection.Height;
                    }

                    if (inspection.IsUniformConstant)
                    {
                        var sourceConstantColor = inspection.ConstantColor;
                        var constantColor = sourceConstantColor;
                        if (channel.Slot.Equals(
                                "t_xml_mask",
                                StringComparison.OrdinalIgnoreCase) &&
                            faction3MaskCanonicalization == Faction3MaskCanonicalization.ZeroSelector)
                        {
                            // constantChannels describes the future atlas bytes. The
                            // canonical source-path map must still use the bytes in the
                            // original texture, otherwise a B=255 source can be advertised
                            // globally as a B=0 source.
                            constantColor = constantColor with { B = 0 };
                        }

                        constantChannels[channel.Slot] = constantColor;
                        RegisterUniformConstantTextureCanonicalPath(
                            state,
                            channel.Slot,
                            sourceConstantColor,
                            path);
                        continue;
                    }

                    // The shared placement is expressed in primary BaseColour pixels. Record
                    // each secondary channel's native resolution separately so its physical
                    // atlas can be sized independently without changing the normalized UVs.
                    channelDimensions[channel.Slot] = (inspection.Width, inspection.Height);
                    resolvedChannels.Add(channel.Slot);
                }
                catch (Exception ex)
                {
                    skipReason = $"{channel.Slot} is not a usable DDS: {path} ({ex.Message})";
                    return null;
                }
            }

            if (!resolvedChannels.Contains("t_xml_base_colour") &&
                !constantChannels.ContainsKey("t_xml_base_colour"))
            {
                skipReason = $"Base-colour texture could not be prepared: {primaryPath}";
                return null;
            }

            var width = primaryWidth
                ?? throw new InvalidOperationException("Base-colour dimensions were not resolved.");
            var height = primaryHeight
                ?? throw new InvalidOperationException("Base-colour dimensions were not resolved.");

            UvBounds bounds;
            TextureAtlasUvIslandNormalization uvIslandAnalysis;
            UvIslandNormalization? uvIslandNormalization;
            try
            {
                var originalBounds = GetUvBounds(model);
                var uvs = model.Mesh.VertexList
                    .Select(vertex => (U: vertex.Uv.X, V: vertex.Uv.Y))
                    .ToArray();
                uvIslandAnalysis = TextureAtlasBuilder.CalculateDisconnectedUvIslandNormalization(
                    uvs,
                    model.Mesh.IndexList);
                uvIslandNormalization = BuildUvIslandNormalization(
                    width,
                    height,
                    originalBounds,
                    uvIslandAnalysis,
                    allowEqualCrop: false);
                bounds = uvIslandNormalization?.NormalizedBounds ?? originalBounds;
            }
            catch (Exception ex)
            {
                skipReason = $"UV0 could not be prepared safely: {ex.Message}";
                return null;
            }

            return new AtlasCandidate(
                rootVmdPath,
                key,
                model,
                usages,
                materialPath,
                materialDoc,
                width,
                height,
                bounds,
                resolvedChannels,
                constantChannels,
                channelDimensions,
                candidateMissingTextures,
                uvIslandAnalysis,
                uvIslandNormalization,
                AtlasResolutionScale: 1.0,
                RequiresMaskAtlas: requiresMaskAtlas,
                ClearMaskBlueChannel: clearMaskBlueChannel);
        }

        private static bool IsEmbeddedAtlasTextureTypeSafe(TextureType textureType)
            => textureType is
                TextureType.BaseColour or
                TextureType.Diffuse or
                TextureType.MaterialMap or
                TextureType.Normal or
                TextureType.Mask;

        private static bool TryGetUnsafeEmbeddedUvTexture(
            IRmvMaterial material,
            out RmvTexture unsafeTexture)
        {
            foreach (var texture in material.GetAllTextures())
            {
                if (string.IsNullOrWhiteSpace(texture.Path))
                    continue;
                if (IsEmbeddedAtlasTextureTypeSafe(texture.TexureType))
                    continue;

                unsafeTexture = texture;
                return true;
            }

            unsafeTexture = default;
            return false;
        }

        private static XmlDocument BuildEmbeddedMaterialDocument(IRmvMaterial material)
        {
            var document = new XmlDocument();
            document.LoadXml(
                $"<material><name>embedded_{material.MaterialId}</name>" +
                $"<shader>embedded/{material.MaterialId}</shader><textures /></material>");
            var texturesNode = document.SelectSingleNode("/material/textures")!;
            var writtenSlots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var texture in material.GetAllTextures())
            {
                if (!TryGetEmbeddedAtlasSlot(texture.TexureType, out var slot) ||
                    string.IsNullOrWhiteSpace(texture.Path) ||
                    !writtenSlots.Add(slot))
                {
                    continue;
                }

                var textureNode = document.CreateElement("texture");
                var slotNode = document.CreateElement("slot");
                slotNode.InnerText = slot;
                textureNode.AppendChild(slotNode);
                var sourceNode = document.CreateElement("source");
                sourceNode.InnerText = texture.Path;
                textureNode.AppendChild(sourceNode);
                texturesNode.AppendChild(textureNode);
            }

            return document;
        }

        private static bool TryGetEmbeddedAtlasSlot(TextureType textureType, out string slot)
        {
            slot = textureType switch
            {
                TextureType.BaseColour or TextureType.Diffuse => "t_xml_base_colour",
                TextureType.MaterialMap => "t_xml_material_map",
                TextureType.Normal => "t_xml_normal",
                TextureType.Mask => "t_xml_mask",
                _ => string.Empty,
            };
            return slot.Length != 0;
        }

        private static void ApplyEmbeddedMaterialTexture(
            IRmvMaterial material,
            string slot,
            string path)
        {
            var textureTypes = slot switch
            {
                "t_xml_base_colour" => new[] { TextureType.BaseColour, TextureType.Diffuse },
                "t_xml_material_map" => new[] { TextureType.MaterialMap },
                "t_xml_normal" => new[] { TextureType.Normal },
                "t_xml_mask" => new[] { TextureType.Mask },
                _ => [],
            };

            foreach (var textureType in textureTypes)
            {
                if (material.GetTexture(textureType).HasValue)
                {
                    material.SetTexture(textureType, path);
                    return;
                }
            }
        }

        private static string BuildEmbeddedMaterialPath(
            string assetPath,
            int lodIndex,
            int partIndex)
            => $"embedded:{assetPath}:lod:{lodIndex}:part:{partIndex}";

        private static void RecordDirectAssetSkip(
            BatchState state,
            string assetPath,
            string reason)
        {
            state.DirectAssetSkipMessages.Add($"{assetPath}: {reason}");
        }

        private static TextureInspection GetTextureInspection(
            BatchState state,
            string texturePath,
            PackFile file)
        {
            texturePath = Normalize(texturePath);
            if (state.TextureInspections.TryGetValue(texturePath, out var cached))
                return cached;

            var dimensions = TextureAtlasBuilder.GetDimensions(file.DataSource.PeekData(20));
            var constantColor = default(TextureAtlasConstantColor);
            var isUniformConstant = false;
            if (ShouldProbeUniformTexture(texturePath, dimensions.Width, dimensions.Height))
            {
                try
                {
                    var bytes = file.DataSource.ReadData();
                    isUniformConstant = TextureAtlasBuilder.TryGetUniformColor(bytes, out constantColor);
                }
                catch
                {
                    // Uniform probing is only an optimization. Unsupported/odd DDS variants
                    // must fall back to the normal atlas path rather than making the mesh ineligible.
                    isUniformConstant = false;
                    constantColor = default;
                }
            }

            if (isUniformConstant)
                state.UniformConstantTexturePaths.Add(texturePath);

            var inspection = new TextureInspection(
                dimensions.Width,
                dimensions.Height,
                isUniformConstant,
                constantColor);
            state.TextureInspections[texturePath] = inspection;
            return inspection;
        }

        private static void RegisterUniformConstantTextureCanonicalPath(
            BatchState state,
            string slot,
            TextureAtlasConstantColor sourceColor,
            string texturePath)
        {
            var key = BuildUniformConstantTextureKey(slot, sourceColor);
            var normalizedPath = Normalize(texturePath);
            if (normalizedPath.Length == 0)
                return;

            if (!state.UniformConstantTextureCanonicalPaths.TryGetValue(key, out var existing) ||
                string.Compare(normalizedPath, existing, StringComparison.OrdinalIgnoreCase) < 0)
            {
                // The key is content-derived, so replacing the path with the stable
                // lexicographically-first source is safe. It lets generated materials with
                // equivalent uniform channels share an identity without treating arbitrary
                // non-uniform textures as interchangeable.
                state.UniformConstantTextureCanonicalPaths[key] = normalizedPath;
            }
        }

        private static void CanonicalizeUniformConstantTexturePaths(
            BatchState state,
            XmlDocument material,
            IReadOnlyDictionary<string, TextureAtlasConstantColor> constantChannels,
            bool recordAssignment = true)
        {
            foreach (var (slot, color) in constantChannels)
            {
                var currentPath = GetTexturePath(material, slot);
                if (currentPath.Length == 0 ||
                    state.GeneratedTexturePaths.Contains(currentPath))
                    continue;

                var key = BuildUniformConstantTextureKey(slot, color);
                if (!state.UniformConstantTextureCanonicalPaths.TryGetValue(
                        key,
                        out var canonicalPath) ||
                    currentPath.Equals(canonicalPath, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                SetTexturePath(material, slot, canonicalPath);
                if (recordAssignment)
                    state.UniformConstantTextureAssignmentsCanonicalized++;
            }
        }

        private static string BuildUniformConstantTextureKey(
            string slot,
            TextureAtlasConstantColor color)
            => string.Join(
                ":",
                Normalize(slot),
                color.B,
                color.G,
                color.R,
                color.A);

        private static List<AtlasCandidate> ApplyTexelDensityScaling(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates)
        {
            if (candidates.Count == 0)
                return [];

            var densities = new Dictionary<MeshKey, double>();
            foreach (var candidate in candidates)
            {
                if (TryCalculateTexelDensity(candidate, out var density))
                    densities[candidate.Key] = density;
            }

            if (densities.Count < 2)
                return candidates.ToList();

            var globalReference = Percentile(
                densities.Values.OrderBy(value => value).ToArray(),
                TexelDensityReferencePercentile);
            var densitiesByRoot = candidates
                .Where(candidate => densities.ContainsKey(candidate.Key))
                .GroupBy(candidate => Normalize(candidate.RootVmdPath))
                .ToDictionary(
                    group => group.Key,
                    group => group
                        .Select(candidate => densities[candidate.Key])
                        .OrderBy(value => value)
                        .ToArray(),
                    StringComparer.OrdinalIgnoreCase);

            var result = new List<AtlasCandidate>(candidates.Count);
            foreach (var candidate in candidates)
            {
                if (!densities.TryGetValue(candidate.Key, out var density))
                {
                    result.Add(candidate);
                    continue;
                }

                var rootKey = Normalize(candidate.RootVmdPath);
                var rootValues = densitiesByRoot.GetValueOrDefault(rootKey);
                var reference = rootValues is { Length: >= 4 }
                    ? Percentile(rootValues, TexelDensityReferencePercentile)
                    : globalReference;
                var maximumDensity = Math.Max(
                    double.Epsilon,
                    reference * TexelDensityOutlierMultiplier);
                var requestedScale = Math.Min(1.0, maximumDensity / density);
                var maxDimension = Math.Max(candidate.Width, candidate.Height);
                var minimumScaleForSize = maxDimension <= 0
                    ? 1.0
                    : Math.Min(
                        1.0,
                        MinAtlasResolutionScaleDimension / (double)maxDimension);
                requestedScale = Math.Clamp(
                    requestedScale,
                    Math.Max(MinAtlasResolutionScale, minimumScaleForSize),
                    1.0);

                // Keep physical atlas sizes mip-friendly. A scale bucket also prevents tiny
                // density differences from producing unstable output dimensions across runs.
                var scale = requestedScale <= 0.375
                    ? 0.25
                    : requestedScale <= 0.75
                        ? 0.5
                        : 1.0;

                if (scale >= 1.0)
                {
                    result.Add(candidate);
                    continue;
                }

                state.TexelDensityScaledMeshes++;
                state.TexelDensityOriginalPixelArea = checked(
                    state.TexelDensityOriginalPixelArea +
                    (long)candidate.Width * candidate.Height);
                state.TexelDensityScaledPixelArea = checked(
                    state.TexelDensityScaledPixelArea +
                    (long)Math.Max(1, (int)Math.Ceiling(candidate.Width * scale)) *
                    Math.Max(1, (int)Math.Ceiling(candidate.Height * scale)));
                state.TexelDensityScaleCounts[scale] =
                    state.TexelDensityScaleCounts.GetValueOrDefault(scale) + 1;

                result.Add(candidate with { AtlasResolutionScale = scale });
            }

            return result;
        }

        private static bool TryCalculateTexelDensity(
            AtlasCandidate candidate,
            out double density)
        {
            density = 0;
            var vertices = candidate.Model.Mesh.VertexList;
            var indices = candidate.Model.Mesh.IndexList;
            if (indices.Length < 3 || indices.Length % 3 != 0)
                return false;

            double worldArea = 0;
            double uvPixelArea = 0;
            for (var index = 0; index < indices.Length; index += 3)
            {
                var ia = indices[index];
                var ib = indices[index + 1];
                var ic = indices[index + 2];
                if (ia >= vertices.Length || ib >= vertices.Length || ic >= vertices.Length)
                    return false;

                var a = vertices[ia];
                var b = vertices[ib];
                var c = vertices[ic];
                var ab = b.GetPosistionAsVec3() - a.GetPosistionAsVec3();
                var ac = c.GetPosistionAsVec3() - a.GetPosistionAsVec3();
                var triangleWorldArea =
                    Microsoft.Xna.Framework.Vector3.Cross(ab, ac).Length() * 0.5;
                if (triangleWorldArea <= 0)
                    continue;

                var auv = a.Uv;
                var buv = b.Uv;
                var cuv = c.Uv;
                var triangleUvArea = Math.Abs(
                    (buv.X - auv.X) * (cuv.Y - auv.Y) -
                    (buv.Y - auv.Y) * (cuv.X - auv.X)) * 0.5;
                if (triangleUvArea <= 0)
                    continue;

                worldArea += triangleWorldArea;
                uvPixelArea += triangleUvArea * candidate.Width * (double)candidate.Height;
            }

            if (worldArea <= double.Epsilon || uvPixelArea <= double.Epsilon)
                return false;

            density = Math.Sqrt(uvPixelArea / worldArea);
            return double.IsFinite(density) && density > 0;
        }

        private static double Percentile(
            IReadOnlyList<double> sortedValues,
            double percentile)
        {
            if (sortedValues.Count == 0)
                return 0;
            if (sortedValues.Count == 1)
                return sortedValues[0];

            var position = Math.Clamp(percentile, 0, 1) * (sortedValues.Count - 1);
            var lower = (int)Math.Floor(position);
            var upper = (int)Math.Ceiling(position);
            if (lower == upper)
                return sortedValues[lower];

            var fraction = position - lower;
            return sortedValues[lower] * (1 - fraction) +
                   sortedValues[upper] * fraction;
        }

        private static (int Width, int Height) GetScaledAtlasDimensions(
            AtlasCandidate candidate,
            int width,
            int height)
        {
            if (width <= 0)
                throw new ArgumentOutOfRangeException(nameof(width));
            if (height <= 0)
                throw new ArgumentOutOfRangeException(nameof(height));

            var scale = candidate.AtlasResolutionScale;
            if (!double.IsFinite(scale) || scale <= 0 || scale > 1.0)
            {
                throw new InvalidOperationException(
                    $"Invalid atlas resolution scale {scale} for {candidate.Key}.");
            }

            return (
                Math.Max(1, checked((int)Math.Ceiling(width * scale))),
                Math.Max(1, checked((int)Math.Ceiling(height * scale))));
        }

        private static List<List<AtlasCandidate>> CreateBatches(
            BatchState state,
            List<AtlasCandidate> candidates,
            bool packWide,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            List<AtlasCandidate> planningCandidates;
            if (packWide)
            {
                var rootsByMesh = BuildCandidateRootVmdPaths(state, candidates);
                var localitySignatureBySource = candidates
                    .GroupBy(GetAtlasPlanningSourceIdentity)
                    .ToDictionary(
                        group => group.Key,
                        group =>
                        {
                            var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                            foreach (var candidate in group)
                            {
                                if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                                    roots.UnionWith(candidateRoots);
                                else
                                    roots.Add(Normalize(candidate.RootVmdPath));
                            }

                            return string.Join(
                                "\u001f",
                                roots.OrderBy(root => root, StringComparer.OrdinalIgnoreCase));
                        });

                planningCandidates = candidates
                    .OrderBy(
                        candidate => localitySignatureBySource[
                            GetAtlasPlanningSourceIdentity(candidate)],
                        StringComparer.OrdinalIgnoreCase)
                    .ThenBy(BuildAtlasPlanningOrderKey, StringComparer.Ordinal)
                    .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(x => x.Key.LodIndex)
                    .ThenBy(x => x.Key.PartIndex)
                    .ToList();
            }
            else
            {
                planningCandidates = candidates;
            }

            var batches = new List<List<AtlasCandidate>>();
            var current = new List<AtlasCandidate>();
            var currentPlanningRepresentatives = new List<AtlasCandidate>();
            var currentPlanningIdentities = new HashSet<AtlasPlanningSourceIdentity>();

            for (var candidateIndex = 0; candidateIndex < planningCandidates.Count; candidateIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var candidate = planningCandidates[candidateIndex];
                ReportProgress(
                    progress,
                    "Planning atlas batches",
                    candidateIndex + 1,
                    planningCandidates.Count,
                    candidate.Key.ToString());

                if (!CanCreatePlan(state, [candidate], out var singleError))
                {
                    RecordSkip(
                        state,
                        candidate.RootVmdPath,
                        candidate.Key,
                        candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        $"Atlas planner rejected this mesh: {singleError}");
                    continue;
                }

                var planningIdentity = GetAtlasPlanningSourceIdentity(candidate);

                if (current.Count == 0)
                {
                    current.Add(candidate);
                    currentPlanningRepresentatives.Add(candidate);
                    currentPlanningIdentities.Add(planningIdentity);
                    continue;
                }

                // Exact source/crop duplicates consume no additional atlas space. Keep every
                // candidate in the execution batch, but only one representative in fit checks.
                if (currentPlanningIdentities.Contains(planningIdentity))
                {
                    current.Add(candidate);
                    continue;
                }

                var trialPlanningRepresentatives =
                    currentPlanningRepresentatives.Concat([candidate]).ToList();
                if (CanCreatePlan(state, trialPlanningRepresentatives, out _))
                {
                    current.Add(candidate);
                    currentPlanningRepresentatives.Add(candidate);
                    currentPlanningIdentities.Add(planningIdentity);
                    continue;
                }

                if (current.Count >= 2)
                {
                    batches.Add(current);
                }
                else
                {
                    var orphan = current[0];
                    RecordSkip(
                        state,
                        orphan.RootVmdPath,
                        orphan.Key,
                        orphan.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        "Could not form a compatible multi-mesh atlas before the atlas size/layout limit was reached.");
                }

                current = [candidate];
                currentPlanningRepresentatives = [candidate];
                currentPlanningIdentities = new HashSet<AtlasPlanningSourceIdentity>
                {
                    planningIdentity
                };
            }

            if (current.Count >= 2)
            {
                batches.Add(current);
            }
            else if (current.Count == 1)
            {
                var orphan = current[0];
                RecordSkip(
                    state,
                    orphan.RootVmdPath,
                    orphan.Key,
                    orphan.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                    packWide
                        ? "No second compatible mesh was available in the pack-wide atlas candidate set."
                        : "No second compatible mesh was available in this VMD dependency set.");
            }

            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Optimizing atlas batches",
                item: "Checking atlas size limits");
            var pixelOptimized = OptimizeMaxSizeBatchesForPixelArea(state, batches);
            if (packWide)
            {
                state.ExpectedArmyResidentPixelsBeforeLocality =
                    CalculateExpectedArmyResidentPixels(state, pixelOptimized);
            }

            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Optimizing atlas batches",
                item: "Optimizing VMD locality");
            var localityOptimized = packWide
                ? OptimizeBatchesForVmdLocality(state, pixelOptimized)
                : pixelOptimized;

            if (packWide)
            {
                state.ExpectedArmyResidentPixelsAfterLocality =
                    CalculateExpectedArmyResidentPixels(state, localityOptimized);
            }

            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Optimizing atlas batches",
                item: "Evaluating compatible mesh merges");
            var mergeOptimized = OptimizeBatchesForMergeAffinity(state, localityOptimized);
            var familyClosed = state.LodAwareAtlasPlanningEnabled
                ? CloseLodAtlasFamilies(state, mergeOptimized)
                : mergeOptimized;
            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Evaluating atlas value",
                item: "Applying residency and draw-value gates");
            var valueOptimized = state.MergeCompatibleMeshesEnabled
                ? FilterBatchesForMergeValue(state, familyClosed)
                : familyClosed;
            if (state.MergeCompatibleMeshesEnabled)
            {
                // The value gate runs after merge-aware repartitioning and can admit
                // texture-only groups that become real atlas-assisted mesh merges later in
                // the pipeline. Recompute the final scenario draw estimate from the batches
                // that actually survived the value gate; the merge-aware pass's intermediate
                // total must not be reported as the final total.
                state.ExpectedArmyDrawCallsEliminatedAfterValueGate +=
                    CalculateExpectedArmyDrawCallsEliminatedForBatches(
                        state,
                        valueOptimized);
            }
            if (packWide)
            {
                state.ExpectedArmyResidentPixelsAfterMergeAware =
                    CalculateExpectedArmyResidentPixels(state, valueOptimized);
            }

            return valueOptimized;
        }

        private static List<List<AtlasCandidate>> CloseLodAtlasFamilies(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            state.LodAwareAtlasFamilies.Clear();
            var working = batches
                .Select(batch => batch
                    .GroupBy(candidate => candidate.Key)
                    .Select(group => group.First())
                    .ToList())
                .ToList();
            if (!state.LodAwareAtlasPlanningEnabled || working.Count == 0)
                return working;

            var candidateByKey = working
                .SelectMany(batch => batch)
                .GroupBy(candidate => candidate.Key)
                .ToDictionary(group => group.Key, group => group.First());
            var structuralComponents = BuildAtlasStructuralMergeComponents(
                state,
                candidateByKey.Values);
            var mergeAffinityGroups = BuildMergeAffinityGroups(
                state,
                candidateByKey.Values,
                recordDiagnostics: false);

            // Structural components are the atomic unit of family attachment. Do this before
            // exact-placement closure so a candidate cannot be moved to a host atlas while its
            // pre-atlas merge partner is left behind in another batch.
            foreach (var component in structuralComponents
                         .OrderBy(component => component.GeometryPath, StringComparer.OrdinalIgnoreCase)
                         .ThenBy(component => component.LodIndex)
                         .ThenBy(component => component.Members.Min(member => member.PartIndex)))
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var members = component.Members
                    .Where(candidateByKey.ContainsKey)
                    .Select(member => candidateByKey[member])
                    .ToList();
                if (members.Count == 0)
                    continue;

                // A missing member is not safe to rewrite: the rigid material/UV state is
                // shared by every structural part, even when one part was not in the selected
                // atlas population.
                if (members.Count != component.Members.Length ||
                    !CanRewriteStructuralComponentAsOneMaterial(state, members))
                {
                    RemoveAtlasFamilyMembers(
                        state,
                        working,
                        members,
                        "LOD-aware atlas planning left a structural component unchanged because " +
                        "the complete component or one compatible post-atlas material variant " +
                        "was not available.");
                    state.LodAwareAtlasStructuralComponentsRejected++;
                    continue;
                }

                var occupiedBatchIds = GetBatchIdsForKeys(working, members.Select(x => x.Key));
                if (occupiedBatchIds.Count <= 1)
                    continue;

                if (TryMoveAtlasFamilyMembersToBestHost(
                        state,
                        working,
                        members,
                        mergeAffinityGroups,
                        out _))
                {
                    state.LodAwareAtlasStructuralComponentsReplanned++;
                    state.LodAwareAtlasFamilyClosureCandidates += members.Count;
                    if (members.Select(member => member.Key.LodIndex).Distinct().Count() > 1)
                        state.LodAwareAtlasFamiliesSpanningMultipleLods++;
                }
                else
                {
                    RemoveAtlasFamilyMembers(
                        state,
                        working,
                        members,
                        "LOD-aware atlas planning rejected a structural component because it " +
                        "could not be hosted by one atlas page without splitting the component.");
                    state.LodAwareAtlasStructuralComponentsRejected++;
                }
            }

            // Close exact placement families after structural components are atomic. The
            // planning identity intentionally excludes LOD and material shader/parameters;
            // the family key adds the rigid geometry path and requires at least two LODs so
            // unrelated VMDs that happen to share a texture region remain under the normal
            // locality planner. ProcessBatch will still generate separate material variants
            // from each original material document while the shared atlas placement is emitted
            // once.
            var identityGroups = working
                .SelectMany(batch => batch)
                .GroupBy(candidate => (
                    candidate.Key.GeometryPath,
                    Identity: GetAtlasPlanningSourceIdentity(candidate)))
                .Where(group => group
                    .Select(candidate => candidate.Key.LodIndex)
                    .Distinct()
                    .Count() >= 2)
                .OrderBy(group => BuildAtlasPlanningOrderKey(group.First()), StringComparer.Ordinal)
                .ToList();
            foreach (var identityGroup in identityGroups)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var members = identityGroup
                    .GroupBy(candidate => candidate.Key)
                    .Select(group => group.First())
                    .ToList();
                var occupiedBatchIds = GetBatchIdsForKeys(working, members.Select(x => x.Key));
                if (occupiedBatchIds.Count <= 1)
                    continue;

                var structuralComponentByKey = structuralComponents
                    .SelectMany(component => component.Members.Select(member =>
                        (member, component)))
                    .ToDictionary(entry => entry.member, entry => entry.component);
                var handledStructuralComponents = new HashSet<string>(StringComparer.Ordinal);
                foreach (var member in members
                             .OrderBy(candidate => candidate.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                             .ThenBy(candidate => candidate.Key.LodIndex)
                             .ThenBy(candidate => candidate.Key.PartIndex))
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (!structuralComponentByKey.TryGetValue(member.Key, out var component))
                        continue;

                    var componentKey = string.Join(
                        "\u001f",
                        component.Members.Select(candidate => candidate.ToString()));
                    if (!handledStructuralComponents.Add(componentKey))
                        continue;

                    var moveMembers = component.Members
                        .Where(candidateByKey.ContainsKey)
                        .Select(candidateKey => candidateByKey[candidateKey])
                        .ToList();

                    var memberBatchIds = GetBatchIdsForKeys(
                        working,
                        moveMembers.Select(candidate => candidate.Key));
                    if (memberBatchIds.Count <= 1)
                        continue;

                    if (TryMoveAtlasFamilyMembersToBestHost(
                            state,
                            working,
                            moveMembers,
                            mergeAffinityGroups,
                            out _))
                    {
                        state.LodAwareAtlasFamilyClosureCandidates += moveMembers.Count;
                        if (moveMembers.Select(candidate => candidate.Key.LodIndex).Distinct().Count() > 1)
                            state.LodAwareAtlasFamiliesSpanningMultipleLods++;
                    }
                    else if (component != null)
                    {
                        RemoveAtlasFamilyMembers(
                            state,
                            working,
                            moveMembers,
                            "LOD-aware atlas planning rejected a cross-batch family attachment " +
                            "because its structural component could not share one host atlas page.");
                        state.LodAwareAtlasStructuralComponentsRejected++;
                    }
                }

                var nonStructuralMembers = members
                    .Where(member => !structuralComponentByKey.ContainsKey(member.Key))
                    .ToList();
                if (nonStructuralMembers.Count != 0 &&
                    GetBatchIdsForKeys(
                        working,
                        nonStructuralMembers.Select(candidate => candidate.Key)).Count > 1)
                {
                    if (TryMoveAtlasFamilyMembersToBestHost(
                            state,
                            working,
                            nonStructuralMembers,
                            mergeAffinityGroups,
                            out _))
                    {
                        state.LodAwareAtlasFamilyClosureCandidates += nonStructuralMembers.Count;
                        if (nonStructuralMembers.Select(candidate => candidate.Key.LodIndex).Distinct().Count() > 1)
                            state.LodAwareAtlasFamiliesSpanningMultipleLods++;
                    }
                }

                var remainingBatchIds = GetBatchIdsForKeys(
                    working,
                    members.Select(candidate => candidate.Key));
                if (remainingBatchIds.Count == 1 && members.Count > 1)
                {
                    state.LodAwareAtlasFamilyClosures++;
                    state.LodAwareAtlasFamilyClosureCandidates += members.Count;
                }
            }

            foreach (var component in structuralComponents)
            {
                var members = component.Members
                    .Where(candidateByKey.ContainsKey)
                    .Select(candidate => candidateByKey[candidate])
                    .ToList();
                if (members.Count == component.Members.Length &&
                    GetBatchIdsForKeys(working, members.Select(candidate => candidate.Key)).Count == 1)
                {
                    RegisterLodAtlasFamily(state, members.Select(candidate => candidate.Key));
                }
            }

            foreach (var identityGroup in working
                         .SelectMany(batch => batch)
                         .GroupBy(candidate => (
                             candidate.Key.GeometryPath,
                             Identity: GetAtlasPlanningSourceIdentity(candidate)))
                         .Where(group => group
                             .Select(candidate => candidate.Key.LodIndex)
                             .Distinct()
                             .Count() >= 2))
            {
                var members = identityGroup
                    .Select(candidate => candidate.Key)
                    .Distinct()
                    .ToArray();
                if (members.Length >= 2 &&
                    GetBatchIdsForKeys(working, members).Count == 1)
                {
                    RegisterLodAtlasFamily(state, members);
                }
            }

            return working
                .Where(batch => batch.Count != 0)
                .ToList();
        }

        private static bool TryMoveAtlasFamilyMembersToBestHost(
            BatchState state,
            List<List<AtlasCandidate>> batches,
            IReadOnlyList<AtlasCandidate> members,
            IReadOnlyList<MergeAffinityGroup> mergeAffinityGroups,
            out int hostBatchIndex)
        {
            hostBatchIndex = -1;
            var memberKeys = members.Select(candidate => candidate.Key).ToHashSet();
            var occupiedBatchIds = GetBatchIdsForKeys(batches, memberKeys);
            if (occupiedBatchIds.Count <= 1)
            {
                hostBatchIndex = occupiedBatchIds.FirstOrDefault(-1);
                return hostBatchIndex >= 0;
            }

            var baselineMergeAffinity = CalculateMergeAffinityScore(
                batches,
                mergeAffinityGroups);
            var bestMergeAffinity = int.MinValue;
            long bestIncrementalPixels = long.MaxValue;
            foreach (var candidateHost in occupiedBatchIds.OrderBy(index => index))
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var proposed = batches[candidateHost]
                    .Concat(members)
                    .GroupBy(candidate => candidate.Key)
                    .Select(group => group.First())
                    .ToList();
                if (!CanCreatePlan(state, proposed, out _))
                    continue;

                var baselinePixels = TryGetGeneratedAtlasPixelCost(
                    state,
                    batches[candidateHost],
                    out var baselineCost,
                    out _,
                    deduplicateByContent: true)
                    ? baselineCost
                    : long.MaxValue;
                var proposedPixels = TryGetGeneratedAtlasPixelCost(
                    state,
                    proposed,
                    out var proposedCost,
                    out _,
                    deduplicateByContent: true)
                    ? proposedCost
                    : long.MaxValue;
                if (baselinePixels == long.MaxValue || proposedPixels == long.MaxValue)
                    continue;

                var incrementalPixels = Math.Max(0, proposedPixels - baselinePixels);
                var proposedBatches = batches
                    .Select((batch, batchIndex) => batchIndex == candidateHost
                        ? proposed
                        : batch
                            .Where(candidate => !memberKeys.Contains(candidate.Key))
                            .ToList())
                    .ToList();
                if (!PreservesMergeAffinityContributions(
                        batches,
                        proposedBatches,
                        mergeAffinityGroups))
                {
                    continue;
                }

                var mergeAffinity = CalculateMergeAffinityScore(
                    proposedBatches,
                    mergeAffinityGroups);
                if (mergeAffinity > bestMergeAffinity ||
                    (mergeAffinity == bestMergeAffinity &&
                     (incrementalPixels < bestIncrementalPixels ||
                      (incrementalPixels == bestIncrementalPixels &&
                       (hostBatchIndex < 0 || candidateHost < hostBatchIndex)))))
                {
                    bestMergeAffinity = mergeAffinity;
                    bestIncrementalPixels = incrementalPixels;
                    hostBatchIndex = candidateHost;
                }
            }

            if (hostBatchIndex < 0)
            {
                // Every single-host proposal either lost an existing merge contribution or
                // could not be represented as one atlas. Try the stronger combined-host plan
                // before giving up, then leave the original layout untouched if it is not
                // safe either.
                return TryCombineAtlasFamilyHostBatches(
                    state,
                    batches,
                    occupiedBatchIds,
                    mergeAffinityGroups,
                    baselineMergeAffinity,
                    out hostBatchIndex);
            }

            // A family closure is only allowed to preserve or improve the merge layout. If
            // every single-host proposal would split a valid same-LOD merge, try the stronger
            // but still safe alternative of combining the connected host batches as one atlas
            // plan. If that is not feasible, leave the original batches untouched.
            if (bestMergeAffinity < baselineMergeAffinity)
            {
                return TryCombineAtlasFamilyHostBatches(
                    state,
                    batches,
                    occupiedBatchIds,
                    mergeAffinityGroups,
                    baselineMergeAffinity,
                    out hostBatchIndex);
            }

            var hostMembers = batches[hostBatchIndex]
                .Concat(members)
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .OrderBy(candidate => BuildAtlasPlanningOrderKey(candidate), StringComparer.Ordinal)
                .ThenBy(candidate => candidate.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(candidate => candidate.Key.LodIndex)
                .ThenBy(candidate => candidate.Key.PartIndex)
                .ToList();
            var memberKeySet = members.Select(candidate => candidate.Key).ToHashSet();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                if (batchIndex == hostBatchIndex)
                    continue;

                batches[batchIndex].RemoveAll(candidate => memberKeySet.Contains(candidate.Key));
            }

            batches[hostBatchIndex] = hostMembers;
            return true;
        }

        private static bool TryCombineAtlasFamilyHostBatches(
            BatchState state,
            List<List<AtlasCandidate>> batches,
            IReadOnlyCollection<int> occupiedBatchIds,
            IReadOnlyList<MergeAffinityGroup> mergeAffinityGroups,
            int baselineMergeAffinity,
            out int hostBatchIndex)
        {
            var selectedHostBatchIndex = occupiedBatchIds
                .OrderBy(index => index)
                .FirstOrDefault(-1);
            hostBatchIndex = selectedHostBatchIndex;
            if (selectedHostBatchIndex < 0)
                return false;

            var occupied = occupiedBatchIds.ToHashSet();
            var combined = occupied
                .OrderBy(index => index)
                .SelectMany(index => batches[index])
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .OrderBy(candidate => BuildAtlasPlanningOrderKey(candidate), StringComparer.Ordinal)
                .ThenBy(candidate => candidate.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(candidate => candidate.Key.LodIndex)
                .ThenBy(candidate => candidate.Key.PartIndex)
                .ToList();
            if (!CanCreatePlan(state, combined, out _))
                return false;

            var proposedBatches = batches
                .Select((batch, batchIndex) => occupied.Contains(batchIndex)
                    ? batchIndex == selectedHostBatchIndex
                        ? combined
                        : []
                    : batch)
                .ToList();
            if (CalculateMergeAffinityScore(proposedBatches, mergeAffinityGroups) <
                baselineMergeAffinity)
            {
                return false;
            }
            if (!PreservesMergeAffinityContributions(
                    batches,
                    proposedBatches,
                    mergeAffinityGroups))
            {
                return false;
            }

            foreach (var batchIndex in occupied)
            {
                if (batchIndex != selectedHostBatchIndex)
                    batches[batchIndex].Clear();
            }

            batches[selectedHostBatchIndex] = combined;
            return true;
        }

        private static bool PreservesMergeAffinityContributions(
            IReadOnlyList<List<AtlasCandidate>> baselineBatches,
            IReadOnlyList<List<AtlasCandidate>> proposedBatches,
            IReadOnlyList<MergeAffinityGroup> mergeAffinityGroups)
        {
            var baselineBatchByMesh = BuildBatchIndexByMesh(baselineBatches);
            var proposedBatchByMesh = BuildBatchIndexByMesh(proposedBatches);
            return mergeAffinityGroups.All(group =>
                CalculateMergeAffinityContribution(group, proposedBatchByMesh) >=
                CalculateMergeAffinityContribution(group, baselineBatchByMesh) &&
                PreservesMergeAffinityComponentCoLocation(
                    group,
                    baselineBatchByMesh,
                    proposedBatchByMesh));
        }

        private static bool PreservesMergeAffinityComponentCoLocation(
            MergeAffinityGroup group,
            IReadOnlyDictionary<MeshKey, int> baselineBatchByMesh,
            IReadOnlyDictionary<MeshKey, int> proposedBatchByMesh)
        {
            var componentLabels = BuildStructuralMergeComponentLabels(
                group.Meshes,
                group.PreExistingStructuralMergePairs);
            var componentIds = componentLabels
                .Distinct()
                .ToArray();
            var baselineBatchesByComponent = BuildAffinityComponentBatchSets(
                group.Meshes,
                componentLabels,
                baselineBatchByMesh);
            var proposedBatchesByComponent = BuildAffinityComponentBatchSets(
                group.Meshes,
                componentLabels,
                proposedBatchByMesh);

            for (var leftIndex = 0; leftIndex < componentIds.Length; leftIndex++)
            {
                for (var rightIndex = leftIndex + 1;
                     rightIndex < componentIds.Length;
                     rightIndex++)
                {
                    var leftComponent = componentIds[leftIndex];
                    var rightComponent = componentIds[rightIndex];
                    if (!baselineBatchesByComponent.TryGetValue(
                            leftComponent,
                            out var baselineLeftBatches) ||
                        !baselineBatchesByComponent.TryGetValue(
                            rightComponent,
                            out var baselineRightBatches) ||
                        !baselineLeftBatches.Overlaps(baselineRightBatches))
                    {
                        continue;
                    }

                    if (!proposedBatchesByComponent.TryGetValue(
                            leftComponent,
                            out var proposedLeftBatches) ||
                        !proposedBatchesByComponent.TryGetValue(
                            rightComponent,
                            out var proposedRightBatches) ||
                        !proposedLeftBatches.Overlaps(proposedRightBatches))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        private static Dictionary<int, HashSet<int>> BuildAffinityComponentBatchSets(
            IReadOnlyList<MeshKey> meshes,
            IReadOnlyList<int> componentLabels,
            IReadOnlyDictionary<MeshKey, int> batchByMesh)
        {
            var result = new Dictionary<int, HashSet<int>>();
            for (var index = 0; index < meshes.Count; index++)
            {
                if (!batchByMesh.TryGetValue(meshes[index], out var batchIndex))
                    continue;

                if (!result.TryGetValue(componentLabels[index], out var batchIndexes))
                {
                    batchIndexes = [];
                    result[componentLabels[index]] = batchIndexes;
                }

                batchIndexes.Add(batchIndex);
            }

            return result;
        }

        private static void RegisterLodAtlasFamily(
            BatchState state,
            IEnumerable<MeshKey> memberKeys)
        {
            var family = memberKeys.ToHashSet();
            if (family.Count < 2)
                return;

            var overlappingFamilies = state.LodAwareAtlasFamilies
                .Where(existing => existing.Overlaps(family))
                .ToList();
            foreach (var overlappingFamily in overlappingFamilies)
            {
                family.UnionWith(overlappingFamily);
                state.LodAwareAtlasFamilies.Remove(overlappingFamily);
            }

            state.LodAwareAtlasFamilies.Add(family);
        }

        private static HashSet<int> GetBatchIdsForKeys(
            IReadOnlyList<List<AtlasCandidate>> batches,
            IEnumerable<MeshKey> keys)
        {
            var keySet = keys.ToHashSet();
            var result = new HashSet<int>();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                if (batches[batchIndex].Any(candidate => keySet.Contains(candidate.Key)))
                    result.Add(batchIndex);
            }

            return result;
        }

        private static void RemoveAtlasFamilyMembers(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches,
            IReadOnlyList<AtlasCandidate> members,
            string reason)
        {
            var memberKeys = members.Select(candidate => candidate.Key).ToHashSet();
            foreach (var batch in batches)
            {
                foreach (var candidate in batch
                             .Where(candidate => memberKeys.Contains(candidate.Key))
                             .ToList())
                {
                    batch.Remove(candidate);
                    RecordSkip(
                        state,
                        candidate.RootVmdPath,
                        candidate.Key,
                        candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        reason);
                }
            }
        }

        private static bool CanRewriteStructuralComponentAsOneMaterial(
            BatchState state,
            IReadOnlyList<AtlasCandidate> members)
        {
            if (members.Count < 2)
                return false;

            var first = members[0];
            var rmvIdentity = GetRmvMergeIdentity(first.Model);
            var materialIdentity = BuildMergeAffinityMaterialIdentity(state, first);
            return members.Skip(1).All(member =>
                GetRmvMergeIdentity(member.Model).Equals(rmvIdentity, StringComparison.Ordinal) &&
                BuildMergeAffinityMaterialIdentity(state, member)
                    .Equals(materialIdentity, StringComparison.Ordinal));
        }

        private static List<AtlasStructuralMergeComponent> BuildAtlasStructuralMergeComponents(
            BatchState state,
            IEnumerable<AtlasCandidate> candidates)
        {
            var candidateKeys = candidates
                .Select(candidate => candidate.Key)
                .ToHashSet();
            var result = new List<AtlasStructuralMergeComponent>();
            var recordedComponents = state.PreAtlasStructuralMergeComponents.Count != 0
                ? state.PreAtlasStructuralMergeComponents
                : BuildFallbackAtlasStructuralMergeComponents(state);
            foreach (var component in recordedComponents)
            {
                var members = component
                    .OrderBy(member => member.GeometryPath, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(member => member.LodIndex)
                    .ThenBy(member => member.PartIndex)
                    .ToArray();
                if (members.Length >= 2 && members.Any(candidateKeys.Contains))
                {
                    result.Add(
                        new AtlasStructuralMergeComponent(
                            members[0].GeometryPath,
                            members[0].LodIndex,
                            members));
                }
            }

            return result;
        }

        private static List<HashSet<MeshKey>> BuildFallbackAtlasStructuralMergeComponents(
            BatchState state)
        {
            var result = new List<HashSet<MeshKey>>();
            foreach (var rigidLod in state.PreAtlasStructuralMergeMeshes
                         .GroupBy(mesh => (mesh.GeometryPath, mesh.LodIndex)))
            {
                var meshes = rigidLod
                    .OrderBy(mesh => mesh.PartIndex)
                    .ToArray();
                if (meshes.Length < 2)
                    continue;

                var labels = BuildStructuralMergeComponentLabels(
                    meshes,
                    state.PreAtlasStructuralMergePairs);
                foreach (var component in labels
                             .Distinct()
                             .Select(label => meshes
                                 .Where((_, index) => labels[index] == label)
                                 .ToHashSet())
                             .Where(component => component.Count >= 2))
                {
                    result.Add(component);
                }
            }

            return result;
        }

        private static HashSet<MeshKey> GetNonAtomicStructuralCandidateKeys(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            var candidateByKey = batches
                .SelectMany(batch => batch)
                .GroupBy(candidate => candidate.Key)
                .ToDictionary(group => group.Key, group => group.First());
            var result = new HashSet<MeshKey>();
            foreach (var component in BuildAtlasStructuralMergeComponents(
                         state,
                         candidateByKey.Values))
            {
                var members = component.Members
                    .Where(candidateByKey.ContainsKey)
                    .Select(member => candidateByKey[member])
                    .ToList();
                var batchIds = GetBatchIdsForKeys(
                    batches,
                    members.Select(candidate => candidate.Key));
                if (members.Count != component.Members.Length ||
                    batchIds.Count != 1 ||
                    !CanRewriteStructuralComponentAsOneMaterial(state, members))
                {
                    foreach (var member in members)
                        result.Add(member.Key);
                }
            }

            return result;
        }

        private static List<List<AtlasCandidate>> OptimizeMaxSizeBatchesForPixelArea(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            var optimized = new List<List<AtlasCandidate>>();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportProgress(
                    state.Progress,
                    "Optimizing atlas batches",
                    batchIndex + 1,
                    batches.Count,
                    $"Size optimization batch {batchIndex + 1}");
                var batch = batches[batchIndex];
                OptimizeMaxSizeBatchForPixelArea(state, batch, optimized);
            }

            return optimized;
        }

        private static void OptimizeMaxSizeBatchForPixelArea(
            BatchState state,
            List<AtlasCandidate> batch,
            List<List<AtlasCandidate>> output)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            if (batch.Count < 4 ||
                !TryGetGeneratedAtlasPixelCost(
                    state,
                    batch,
                    out var parentPixelCost,
                    out var parentTouchesMaxSize) ||
                !parentTouchesMaxSize)
            {
                output.Add(batch);
                return;
            }

            List<AtlasCandidate>? bestLeft = null;
            List<AtlasCandidate>? bestRight = null;
            var bestCombinedPixelCost = parentPixelCost;
            var bestSplitWasNonContiguous = false;
            var validSplitIndices = new List<int>();

            for (var splitIndex = 2; splitIndex <= batch.Count - 2; splitIndex++)
            {
                // Keep identical source/crop identities together. Splitting inside one of these
                // groups only duplicates an atlas placement and cannot improve packing.
                if (GetAtlasPlanningSourceIdentity(batch[splitIndex - 1]) !=
                    GetAtlasPlanningSourceIdentity(batch[splitIndex]))
                {
                    validSplitIndices.Add(splitIndex);
                }
            }

            const int maxOrderedSplitEvaluations = 32;
            IEnumerable<int> splitIndices = validSplitIndices;
            if (validSplitIndices.Count > maxOrderedSplitEvaluations)
            {
                // This is only an optional size optimization. Exhaustively rebuilding two atlas
                // plans for every possible boundary becomes quadratic on very large packs, so
                // sample the ordered boundary set evenly and keep conversion time bounded.
                splitIndices = Enumerable.Range(0, maxOrderedSplitEvaluations)
                    .Select(i => validSplitIndices[
                        i * (validSplitIndices.Count - 1) / (maxOrderedSplitEvaluations - 1)])
                    .Distinct();
            }

            foreach (var splitIndex in splitIndices)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                state.AtlasPixelAreaSplitEvaluations++;

                var left = batch.Take(splitIndex).ToList();
                var right = batch.Skip(splitIndex).ToList();

                if (!TryGetGeneratedAtlasPixelCost(state, left, out var leftCost, out _) ||
                    !TryGetGeneratedAtlasPixelCost(state, right, out var rightCost, out _))
                {
                    continue;
                }

                var combinedCost = checked(leftCost + rightCost);
                if (combinedCost >= bestCombinedPixelCost)
                    continue;

                bestCombinedPixelCost = combinedCost;
                bestLeft = left;
                bestRight = right;
                bestSplitWasNonContiguous = false;
            }

            foreach (var proposal in CreateNonContiguousSplitProposals(batch))
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                state.AtlasPixelAreaSplitEvaluations++;
                state.AtlasNonContiguousSplitEvaluations++;

                if (!TryGetGeneratedAtlasPixelCost(state, proposal.Left, out var leftCost, out _) ||
                    !TryGetGeneratedAtlasPixelCost(state, proposal.Right, out var rightCost, out _))
                {
                    continue;
                }

                var combinedCost = checked(leftCost + rightCost);
                if (combinedCost >= bestCombinedPixelCost)
                    continue;

                bestCombinedPixelCost = combinedCost;
                bestLeft = proposal.Left;
                bestRight = proposal.Right;
                bestSplitWasNonContiguous = true;
            }

            if (bestLeft == null || bestRight == null)
            {
                output.Add(batch);
                return;
            }

            state.AtlasPixelAreaOptimizedSplits++;
            var savedPixels = checked(parentPixelCost - bestCombinedPixelCost);
            state.AtlasPixelAreaSavedByOptimizedSplits = checked(
                state.AtlasPixelAreaSavedByOptimizedSplits + savedPixels);
            if (bestSplitWasNonContiguous)
            {
                state.AtlasNonContiguousOptimizedSplits++;
                state.AtlasPixelAreaSavedByNonContiguousSplits = checked(
                    state.AtlasPixelAreaSavedByNonContiguousSplits + savedPixels);
            }

            OptimizeMaxSizeBatchForPixelArea(state, bestLeft, output);
            OptimizeMaxSizeBatchForPixelArea(state, bestRight, output);
        }

        private static List<List<AtlasCandidate>> OptimizeBatchesForVmdLocality(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            var working = batches.Select(batch => batch.ToList()).ToList();
            if (!state.ShareAtlasesAcrossVmdsEnabled || working.Count == 0)
                return working;

            var allCandidates = working.SelectMany(batch => batch).ToList();
            var rootsByMesh = BuildCandidateRootVmdPaths(state, allCandidates);
            var affinityGroups = BuildMergeAffinityGroups(state, allCandidates);
            var optimized = new List<List<AtlasCandidate>>();

            for (var batchIndex = 0; batchIndex < working.Count; batchIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportProgress(
                    state.Progress,
                    "Optimizing atlas batches",
                    batchIndex + 1,
                    working.Count,
                    $"VMD locality batch {batchIndex + 1}");
                OptimizeBatchForVmdLocality(
                    state,
                    working[batchIndex],
                    rootsByMesh,
                    affinityGroups,
                    optimized);
            }

            return optimized;
        }

        private static Dictionary<MeshKey, HashSet<string>> BuildCandidateRootVmdPaths(
            BatchState state,
            IEnumerable<AtlasCandidate> candidates)
        {
            if (state.AtlasValueGateRootsByWsModelCache == null ||
                state.AtlasValueGateRootsByWsModelCacheVersion !=
                state.ReachableWsModelsByRootVersion)
            {
                var rootsByWsModel = new Dictionary<string, HashSet<string>>(
                    StringComparer.OrdinalIgnoreCase);
                foreach (var (rootVmdPath, reachableWsModels) in state.ReachableWsModelsByRoot)
                {
                    var normalizedRoot = Normalize(rootVmdPath);
                    foreach (var reachableWsModel in reachableWsModels)
                    {
                        var wsModelPath = Normalize(reachableWsModel);
                        if (!rootsByWsModel.TryGetValue(wsModelPath, out var roots))
                        {
                            roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                            rootsByWsModel[wsModelPath] = roots;
                        }

                        roots.Add(normalizedRoot);
                    }
                }

                state.AtlasValueGateRootsByWsModelCache = rootsByWsModel;
                state.AtlasValueGateRootsByWsModelCacheVersion =
                    state.ReachableWsModelsByRootVersion;
                state.AtlasValueGateRootsByMesh.Clear();
            }

            var cachedRootsByWsModel = state.AtlasValueGateRootsByWsModelCache
                ?? throw new InvalidOperationException(
                    "Atlas root cache was not initialized.");
            var result = new Dictionary<MeshKey, HashSet<string>>();
            foreach (var candidate in candidates)
            {
                if (!state.AtlasValueGateRootsByMesh.TryGetValue(
                        candidate.Key,
                        out var cachedRoots))
                {
                    cachedRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var usage in candidate.Usages)
                    {
                        if (cachedRootsByWsModel.TryGetValue(
                                Normalize(usage.AssetPath),
                                out var usageRoots))
                        {
                            cachedRoots.UnionWith(usageRoots);
                        }
                    }

                    if (cachedRoots.Count == 0)
                        cachedRoots.Add(Normalize(candidate.RootVmdPath));

                    state.AtlasValueGateRootsByMesh[candidate.Key] = cachedRoots;
                }

                // Return a private set so callers cannot mutate the per-run cache.
                result[candidate.Key] = new HashSet<string>(
                    cachedRoots,
                    StringComparer.OrdinalIgnoreCase);
            }

            return result;
        }

        private static int GetBatchRootCount(
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh)
        {
            var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var candidate in candidates)
            {
                if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                    roots.UnionWith(candidateRoots);
                else
                    roots.Add(Normalize(candidate.RootVmdPath));
            }

            return Math.Max(1, roots.Count);
        }

        private static long GetAtlasResidencyProxy(
            long atlasPixels,
            int rootCount)
            => checked(atlasPixels * Math.Max(1, rootCount));

        private static void SetMaximumEntityCount(
            Dictionary<Wh3UnitVisualRole, int> countsByRole,
            Wh3UnitVisualRole role,
            int count)
        {
            if (count <= 0)
                return;

            countsByRole[role] = Math.Max(
                countsByRole.GetValueOrDefault(role),
                count);
        }

        private static bool UsageMatchesScenarioRosterScope(
            Wh3UnitCategoryUsage usage,
            Wh3ResolvedUnitVisual rosterUnit,
            Wh3ArmyVisualScenario scenario)
        {
            if (rosterUnit.HasUnknownFactionScope)
                return true;

            var scopeKey = scenario.RosterScopeKey?.Trim() ?? string.Empty;
            if (scopeKey.Length == 0)
                return true;

            if (scenario.RosterScope == Wh3RosterScope.SelectedFaction)
            {
                return usage.Provenance.Count == 0 ||
                       usage.Provenance.Any(provenance =>
                           string.IsNullOrWhiteSpace(provenance.FactionKey) ||
                           provenance.FactionKey.Equals(
                               scopeKey,
                               StringComparison.OrdinalIgnoreCase));
            }

            if (scenario.RosterScope == Wh3RosterScope.SelectedCulture)
            {
                return usage.Provenance.Count == 0 ||
                       usage.Provenance.Any(provenance =>
                       {
                           var hasCultureScope =
                               !string.IsNullOrWhiteSpace(provenance.CultureKey) ||
                               !string.IsNullOrWhiteSpace(provenance.SubcultureKey);
                           return !hasCultureScope ||
                                  provenance.CultureKey.Equals(
                                      scopeKey,
                                      StringComparison.OrdinalIgnoreCase) ||
                                  provenance.SubcultureKey.Equals(
                                      scopeKey,
                                      StringComparison.OrdinalIgnoreCase);
                       });
            }

            return true;
        }

        private static ArmyResidencyModel? BuildArmyResidencyModel(
            BatchState state,
            Wh3UnitCategoryResolution? resolution,
            bool includeAllGameCultures)
        {
            if (resolution == null)
                return null;

            var rosterByUnitId = resolution.RosterUnits
                .Select(unit => (Identity: GetArmyUnitIdentity(unit), Unit: unit))
                .Where(entry => entry.Identity.Length != 0)
                .ToDictionary(
                    entry => entry.Identity,
                    entry => entry.Unit,
                    StringComparer.OrdinalIgnoreCase);
            if (rosterByUnitId.Count == 0)
                return null;

            var packAffectedUnitIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var usage in resolution.UsagesByVmd.Values.SelectMany(usages => usages))
            {
                var identity = GetArmyUnitIdentity(usage);
                if (identity.Length != 0)
                    packAffectedUnitIds.Add(identity);
            }

            foreach (var (assetPathValue, usages) in resolution.DirectAssetUsagesByPath)
            {
                var assetPath = Normalize(assetPathValue);
                if (!state.Source.ContainsFile(assetPath))
                    continue;

                foreach (var usage in usages)
                {
                    var identity = GetArmyUnitIdentity(usage);
                    if (identity.Length != 0)
                        packAffectedUnitIds.Add(identity);
                }
            }

            var allKnownCultures = resolution.RosterUnits
                .SelectMany(unit => unit.CultureKeys)
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Select(value => value.Trim().ToLowerInvariant())
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            var modelCultures = new HashSet<string>(
                allKnownCultures,
                StringComparer.OrdinalIgnoreCase);
            if (modelCultures.Count == 0)
                modelCultures.Add("__unknown__");

            // Player scoring stays pack-scoped by default, but every resolved culture is
            // retained in the model as a possible opponent/read-only consumer. This avoids a
            // full culture-pair matrix: unrelated cultures have zero presence for a culture-
            // local asset and therefore cancel naturally, while mirror battles and genuine
            // cross-culture asset sharing still contribute.
            var playerCultures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (includeAllGameCultures)
            {
                playerCultures.UnionWith(modelCultures);
            }
            else
            {
                foreach (var unitId in packAffectedUnitIds)
                {
                    if (!rosterByUnitId.TryGetValue(unitId, out var unit))
                        continue;

                    playerCultures.UnionWith(
                        unit.CultureKeys
                            .Where(value => !string.IsNullOrWhiteSpace(value))
                            .Select(value => value.Trim().ToLowerInvariant())
                            .Where(modelCultures.Contains));
                }
            }

            // If the affected culture cannot be resolved, fall back to all modeled cultures
            // rather than silently assigning zero value to the pack.
            if (playerCultures.Count == 0)
                playerCultures.UnionWith(modelCultures);

            var unitsByCategory = resolution.Scenario.ArmySlotTemplate.Keys.ToDictionary(
                category => category,
                _ => new HashSet<string>(StringComparer.OrdinalIgnoreCase));
            var unitsByCultureAndCategory = modelCultures.ToDictionary(
                culture => culture,
                _ => resolution.Scenario.ArmySlotTemplate.Keys.ToDictionary(
                    category => category,
                    _ => new HashSet<string>(StringComparer.OrdinalIgnoreCase)),
                StringComparer.OrdinalIgnoreCase);
            var unitsByVmd = new Dictionary<
                string,
                Dictionary<Wh3ArmyUnitCategory, HashSet<string>>>(
                StringComparer.OrdinalIgnoreCase);
            var culturesByUnit = new Dictionary<string, IReadOnlySet<string>>(
                StringComparer.OrdinalIgnoreCase);
            var entityCountByUnit = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var entityCountByUnitAndRole = new Dictionary<
                string,
                Dictionary<Wh3UnitVisualRole, int>>(StringComparer.OrdinalIgnoreCase);
            var categoryByUnit = new Dictionary<string, Wh3ArmyUnitCategory>(
                StringComparer.OrdinalIgnoreCase);
            var directVmdsByUnitAndRole = new Dictionary<
                string,
                Dictionary<Wh3UnitVisualRole, HashSet<string>>>(
                StringComparer.OrdinalIgnoreCase);
            var directAssetsByUnitAndRole = new Dictionary<
                string,
                Dictionary<
                    Wh3UnitVisualRole,
                    Dictionary<string, double>>>(
                StringComparer.OrdinalIgnoreCase);

            foreach (var unit in resolution.RosterUnits)
            {
                if (!resolution.Scenario.ArmySlotTemplate.ContainsKey(unit.Category))
                    continue;

                var identity = GetArmyUnitIdentity(unit);
                if (identity.Length == 0)
                    continue;

                var unitCultures = unit.CultureKeys
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .Select(value => value.Trim().ToLowerInvariant())
                    .Where(modelCultures.Contains)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

                // Unknown culture/faction scope is a wildcard, not "matches nothing". This
                // keeps unresolved generic units available in each culture without ever mixing
                // known units from unrelated cultures into the same army population.
                if (unitCultures.Count == 0 &&
                    (unit.HasUnknownFactionScope || unit.CultureKeys.Count == 0))
                {
                    unitCultures.UnionWith(modelCultures);
                }

                if (unitCultures.Count == 0)
                    continue;

                culturesByUnit[identity] = unitCultures;
                unitsByCategory[unit.Category].Add(identity);
                foreach (var culture in unitCultures)
                    unitsByCultureAndCategory[culture][unit.Category].Add(identity);

                categoryByUnit[identity] = unit.Category;
                var countsByRole = new Dictionary<Wh3UnitVisualRole, int>();
                SetMaximumEntityCount(countsByRole, Wh3UnitVisualRole.Men, unit.VisualCounts.Riders);
                SetMaximumEntityCount(countsByRole, Wh3UnitVisualRole.Mount, unit.VisualCounts.Mounts);
                SetMaximumEntityCount(countsByRole, Wh3UnitVisualRole.Engine, unit.VisualCounts.Engines);
                SetMaximumEntityCount(countsByRole, Wh3UnitVisualRole.Crew, unit.VisualCounts.Crew);
                entityCountByUnitAndRole[identity] = countsByRole;
                entityCountByUnit[identity] = Math.Max(
                    1,
                    countsByRole.Values.DefaultIfEmpty(1).Max());

                foreach (var component in unit.Components)
                {
                    if (component.ScenarioPresenceProbability <= 0)
                        continue;

                    var assetPath = Normalize(component.AssetPath);
                    if (assetPath.Length == 0)
                        continue;

                    if (!unitsByVmd.TryGetValue(assetPath, out var byCategory))
                    {
                        byCategory = new Dictionary<Wh3ArmyUnitCategory, HashSet<string>>();
                        unitsByVmd[assetPath] = byCategory;
                    }

                    if (!byCategory.TryGetValue(unit.Category, out var unitIds))
                    {
                        unitIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        byCategory[unit.Category] = unitIds;
                    }

                    unitIds.Add(identity);

                    if (component.IsVariantMeshDefinition)
                    {
                        if (!directVmdsByUnitAndRole.TryGetValue(identity, out var byRole))
                        {
                            byRole = new Dictionary<Wh3UnitVisualRole, HashSet<string>>();
                            directVmdsByUnitAndRole[identity] = byRole;
                        }

                        if (!byRole.TryGetValue(component.Role, out var vmds))
                        {
                            vmds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                            byRole[component.Role] = vmds;
                        }

                        vmds.Add(assetPath);
                        continue;
                    }

                    if (!directAssetsByUnitAndRole.TryGetValue(identity, out var directAssetsByRole))
                    {
                        directAssetsByRole = new Dictionary<
                            Wh3UnitVisualRole,
                            Dictionary<string, double>>();
                        directAssetsByUnitAndRole[identity] = directAssetsByRole;
                    }

                    if (!directAssetsByRole.TryGetValue(component.Role, out var directAssets))
                    {
                        directAssets = new Dictionary<string, double>(
                            StringComparer.OrdinalIgnoreCase);
                        directAssetsByRole[component.Role] = directAssets;
                    }

                    directAssets[assetPath] = Math.Clamp(
                        directAssets.GetValueOrDefault(assetPath) +
                        component.ScenarioPresenceProbability,
                        0.0,
                        1.0);
                }
            }

            var populatedCultures = unitsByCultureAndCategory
                .Where(entry => entry.Value.Values.Any(units => units.Count != 0))
                .Select(entry => entry.Key)
                .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            if (populatedCultures.Length == 0)
                return null;

            var scoredPlayerCultures = populatedCultures
                .Where(playerCultures.Contains)
                .ToArray();
            if (scoredPlayerCultures.Length == 0)
                scoredPlayerCultures = populatedCultures;

            var playerCultureWeight = 1.0 / scoredPlayerCultures.Length;
            var cultureWeights = scoredPlayerCultures.ToDictionary(
                culture => culture,
                _ => playerCultureWeight,
                StringComparer.OrdinalIgnoreCase);

            // Opponent cultures are uniformly distributed across the complete resolved game
            // roster. For culture-local assets this only adds the same-culture mirror chance.
            // If the dependency graph proves an asset is shared across cultures, those cultures
            // automatically contribute without needing an explicit culture-pair matrix.
            var opponentCultureWeight = 1.0 / populatedCultures.Length;
            var opponentCultureWeights = populatedCultures.ToDictionary(
                culture => culture,
                _ => opponentCultureWeight,
                StringComparer.OrdinalIgnoreCase);

            var occurrenceCache = new Dictionary<string, IReadOnlyDictionary<string, double>>(
                StringComparer.OrdinalIgnoreCase);
            var configurationCache = new Dictionary<string, IReadOnlyList<UnitVisualConfiguration>>(
                StringComparer.OrdinalIgnoreCase);
            var expectedWsModelOccurrencesByUnit =
                new Dictionary<string, ExpectedWsModelOccurrences>(
                    StringComparer.OrdinalIgnoreCase);
            var visualConfigurationsByUnitAndRole = new Dictionary<
                string,
                Dictionary<Wh3UnitVisualRole, IReadOnlyList<UnitVisualConfiguration>>>(
                StringComparer.OrdinalIgnoreCase);

            foreach (var (unitId, directVmdsByRole) in directVmdsByUnitAndRole)
            {
                if (directVmdsByRole.Count == 0)
                    continue;

                var accumulatedByWsModel = new Dictionary<
                    string,
                    Dictionary<Wh3UnitVisualRole, double>>(
                    StringComparer.OrdinalIgnoreCase);
                foreach (var (role, directVmds) in directVmdsByRole)
                {
                    if (directVmds.Count == 0)
                        continue;

                    var accumulated = new Dictionary<string, double>(
                        StringComparer.OrdinalIgnoreCase);
                    var configurations = new List<UnitVisualConfiguration>();
                    foreach (var vmdPath in directVmds)
                    {
                        var occurrences = GetExpectedWsModelOccurrencesForVmd(
                            state,
                            vmdPath,
                            occurrenceCache,
                            new HashSet<string>(StringComparer.OrdinalIgnoreCase));
                        foreach (var (wsModelPath, expectedOccurrences) in occurrences)
                        {
                            accumulated[wsModelPath] =
                                accumulated.GetValueOrDefault(wsModelPath) + expectedOccurrences;
                        }

                        configurations.AddRange(GetWsModelConfigurationsForVmd(
                            state,
                            vmdPath,
                            configurationCache,
                            new HashSet<string>(StringComparer.OrdinalIgnoreCase)));
                    }

                    if (accumulated.Count == 0)
                        continue;

                    // A unit can have faction-specific direct VMDs for one component. Without
                    // a faction context, treat those visual definitions as equally likely
                    // alternatives, independently for each visual role.
                    var directVariantCount = directVmds.Count;
                    if (configurations.Count != 0)
                    {
                        if (!visualConfigurationsByUnitAndRole.TryGetValue(unitId, out var byRole))
                        {
                            byRole = new Dictionary<Wh3UnitVisualRole, IReadOnlyList<UnitVisualConfiguration>>();
                            visualConfigurationsByUnitAndRole[unitId] = byRole;
                        }

                        byRole[role] = configurations
                            .Select(configuration => configuration with
                            {
                                Probability = configuration.Probability / directVariantCount,
                            })
                            .Where(configuration => configuration.Probability > 0)
                            .ToArray();
                    }
                    foreach (var (wsModelPath, expectedOccurrences) in accumulated)
                    {
                        if (!accumulatedByWsModel.TryGetValue(wsModelPath, out var byRole))
                        {
                            byRole = new Dictionary<Wh3UnitVisualRole, double>();
                            accumulatedByWsModel[wsModelPath] = byRole;
                        }

                        byRole[role] = expectedOccurrences / directVariantCount;
                    }
                }

                if (accumulatedByWsModel.Count != 0)
                {
                    expectedWsModelOccurrencesByUnit[unitId] = new ExpectedWsModelOccurrences(
                        accumulatedByWsModel.ToDictionary(
                            entry => entry.Key,
                            entry => (IReadOnlyDictionary<Wh3UnitVisualRole, double>)entry.Value,
                            StringComparer.OrdinalIgnoreCase));
                }
            }

            foreach (var (unitId, directAssetsByRole) in directAssetsByUnitAndRole)
            {
                if (!expectedWsModelOccurrencesByUnit.TryGetValue(
                        unitId,
                        out var existingOccurrences))
                {
                    existingOccurrences = new ExpectedWsModelOccurrences(
                        new Dictionary<string, IReadOnlyDictionary<Wh3UnitVisualRole, double>>(
                            StringComparer.OrdinalIgnoreCase));
                    expectedWsModelOccurrencesByUnit[unitId] = existingOccurrences;
                }

                var mergedOccurrences = existingOccurrences.ByWsModel.ToDictionary(
                    entry => entry.Key,
                    entry => entry.Value.ToDictionary(
                        roleEntry => roleEntry.Key,
                        roleEntry => roleEntry.Value),
                    StringComparer.OrdinalIgnoreCase);
                foreach (var (role, directAssets) in directAssetsByRole)
                {
                    if (directAssets.Count == 0)
                        continue;

                    // Preserve scenario state/LOD probabilities exactly. Do not
                    // renormalize them: doing so would turn e.g. a 25% destroyed state back
                    // into 100% presence and defeat scenario-driven lifecycle modelling.
                    foreach (var (assetPath, scenarioPresence) in directAssets)
                    {
                        if (scenarioPresence <= 0)
                            continue;

                        if (!mergedOccurrences.TryGetValue(assetPath, out var byRole))
                        {
                            byRole = new Dictionary<Wh3UnitVisualRole, double>();
                            mergedOccurrences[assetPath] = byRole;
                        }

                        byRole[role] = Math.Clamp(
                            byRole.GetValueOrDefault(role) + scenarioPresence,
                            0.0,
                            1.0);
                    }
                }

                expectedWsModelOccurrencesByUnit[unitId] = new ExpectedWsModelOccurrences(
                    mergedOccurrences.ToDictionary(
                        entry => entry.Key,
                        entry => (IReadOnlyDictionary<Wh3UnitVisualRole, double>)entry.Value,
                        StringComparer.OrdinalIgnoreCase));
            }

            // Index the resolved asset closure in the direction used by the planner. The
            // residency and draw-value calculations are called once per proposed merge, so
            // walking every unit in every culture for every proposal is prohibitively costly.
            // Keep both directions: asset -> units lets a proposal identify its consumers,
            // while asset -> cultures lets it skip cultures that cannot reference it at all.
            var unitIdsByAssetPath = new Dictionary<string, HashSet<string>>(
                StringComparer.OrdinalIgnoreCase);

            void AddUnitAssetReference(string assetPathValue, string unitId)
            {
                var assetPath = Normalize(assetPathValue);
                if (assetPath.Length == 0)
                    return;

                if (!unitIdsByAssetPath.TryGetValue(assetPath, out var unitIds))
                {
                    unitIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    unitIdsByAssetPath[assetPath] = unitIds;
                }

                unitIds.Add(unitId);
            }

            foreach (var (assetPath, unitsForVmd) in unitsByVmd)
            {
                foreach (var unitId in unitsForVmd.Values.SelectMany(unitIds => unitIds))
                    AddUnitAssetReference(assetPath, unitId);
            }

            foreach (var (unitId, expectedOccurrences) in expectedWsModelOccurrencesByUnit)
            {
                foreach (var assetPath in expectedOccurrences.ByWsModel.Keys)
                    AddUnitAssetReference(assetPath, unitId);
            }

            var culturesByAssetPath = new Dictionary<
                string,
                IReadOnlySet<string>>(StringComparer.OrdinalIgnoreCase);
            foreach (var (assetPath, unitIds) in unitIdsByAssetPath)
            {
                var cultures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var unitId in unitIds)
                {
                    if (culturesByUnit.TryGetValue(unitId, out var unitCultures))
                        cultures.UnionWith(unitCultures);
                }

                if (cultures.Count != 0)
                    culturesByAssetPath[assetPath] = cultures;
            }

            var readOnlyUnitIdsByAssetPath = unitIdsByAssetPath.ToDictionary(
                entry => entry.Key,
                entry => (IReadOnlySet<string>)entry.Value,
                StringComparer.OrdinalIgnoreCase);

            return new ArmyResidencyModel(
                unitsByCategory,
                unitsByCultureAndCategory,
                unitsByVmd,
                culturesByUnit,
                readOnlyUnitIdsByAssetPath,
                culturesByAssetPath,
                cultureWeights,
                opponentCultureWeights,
                entityCountByUnit,
                entityCountByUnitAndRole,
                categoryByUnit,
                directVmdsByUnitAndRole,
                expectedWsModelOccurrencesByUnit,
                visualConfigurationsByUnitAndRole,
                resolution.Scenario,
                includeAllGameCultures);
        }

        private static IReadOnlyDictionary<string, double> GetExpectedWsModelOccurrencesForVmd(
            BatchState state,
            string vmdPathValue,
            Dictionary<string, IReadOnlyDictionary<string, double>> cache,
            HashSet<string> visiting)
        {
            var vmdPath = Normalize(vmdPathValue);
            if (cache.TryGetValue(vmdPath, out var cached))
                return cached;
            if (!visiting.Add(vmdPath))
                return new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

            try
            {
                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    vmdPath);
                var file = container?.FindFile(vmdPath);
                if (container == null || file == null)
                {
                    var empty = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    cache[vmdPath] = empty;
                    return empty;
                }

                if (!TryGetVmdForTraversal(
                        state,
                        container,
                        vmdPath,
                        file,
                        out var vmd))
                {
                    var empty = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                    cache[vmdPath] = empty;
                    return empty;
                }

                var result = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
                AccumulateExpectedWsModelOccurrences(
                    state,
                    vmd,
                    1.0,
                    result,
                    cache,
                    visiting);
                cache[vmdPath] = result;
                return result;
            }
            finally
            {
                visiting.Remove(vmdPath);
            }
        }

        private const int MaxExactVisualConfigurations = 16384;

        private static IReadOnlyList<UnitVisualConfiguration> GetWsModelConfigurationsForVmd(
            BatchState state,
            string vmdPathValue,
            Dictionary<string, IReadOnlyList<UnitVisualConfiguration>> cache,
            HashSet<string> visiting)
        {
            var vmdPath = Normalize(vmdPathValue);
            if (cache.TryGetValue(vmdPath, out var cached))
                return cached;
            if (!visiting.Add(vmdPath))
                return [];

            try
            {
                var container = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    GetGameplayTraversalContainers(state),
                    vmdPath);
                var file = container?.FindFile(vmdPath);
                if (container == null ||
                    file == null ||
                    !TryGetVmdForTraversal(state, container, vmdPath, file, out var vmd))
                {
                    cache[vmdPath] = [];
                    return [];
                }

                var configurations = ExpandVisualConfigurations(
                    state,
                    vmd,
                    cache,
                    visiting);
                cache[vmdPath] = configurations;
                return configurations;
            }
            finally
            {
                visiting.Remove(vmdPath);
            }
        }

        private static IReadOnlyList<UnitVisualConfiguration> ExpandVisualConfigurations(
            BatchState state,
            VariantMesh mesh,
            Dictionary<string, IReadOnlyList<UnitVisualConfiguration>> cache,
            HashSet<string> visiting)
        {
            var baseModels = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            if (!string.IsNullOrWhiteSpace(mesh.ModelReference))
            {
                var modelPath = Normalize(mesh.ModelReference);
                if (Path.GetExtension(modelPath)
                        .Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) &&
                    FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        GetGameplayTraversalContainers(state),
                        modelPath) != null)
                {
                    baseModels[modelPath] = 1;
                }
            }

            var current = new List<UnitVisualConfiguration>
            {
                new(1.0, baseModels),
            };

            foreach (var slot in mesh.ChildSlots ?? [])
            {
                var slotProbability = ParseVmdSlotProbability(slot.Probability);
                var childMeshCount = slot.ChildMeshes?.Count ?? 0;
                var childReferenceCount = slot.ChildReferences?.Count ?? 0;
                var alternativeCount = childMeshCount + childReferenceCount;
                if (alternativeCount == 0 || slotProbability <= 0)
                    continue;

                var alternatives = new List<UnitVisualConfiguration>();
                if (slotProbability < 1.0)
                {
                    alternatives.Add(new UnitVisualConfiguration(
                        1.0 - slotProbability,
                        new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase)));
                }

                var alternativeWeight = slotProbability / alternativeCount;
                foreach (var child in slot.ChildMeshes ?? [])
                {
                    var childConfigurations = ExpandVisualConfigurations(
                        state,
                        child,
                        cache,
                        visiting);
                    if (childConfigurations.Count == 0)
                        return [];

                    alternatives.AddRange(childConfigurations.Select(configuration => configuration with
                    {
                        Probability = configuration.Probability * alternativeWeight,
                    }));
                }

                foreach (var reference in slot.ChildReferences ?? [])
                {
                    if (string.IsNullOrWhiteSpace(reference.Reference))
                        return [];

                    var childConfigurations = GetWsModelConfigurationsForVmd(
                        state,
                        reference.Reference,
                        cache,
                        visiting);
                    if (childConfigurations.Count == 0)
                        return [];

                    alternatives.AddRange(childConfigurations.Select(configuration => configuration with
                    {
                        Probability = configuration.Probability * alternativeWeight,
                    }));
                }

                if (alternatives.Count == 0)
                    return [];

                var combined = new List<UnitVisualConfiguration>();
                foreach (var left in current)
                {
                    foreach (var right in alternatives)
                    {
                        var probability = left.Probability * right.Probability;
                        if (probability <= 0)
                            continue;

                        var models = left.WsModelOccurrences.ToDictionary(
                            entry => entry.Key,
                            entry => entry.Value,
                            StringComparer.OrdinalIgnoreCase);
                        foreach (var (path, count) in right.WsModelOccurrences)
                            models[path] = models.GetValueOrDefault(path) + count;

                        combined.Add(new UnitVisualConfiguration(probability, models));
                        if (combined.Count > MaxExactVisualConfigurations)
                            return [];
                    }
                }

                current = MergeEquivalentVisualConfigurations(combined);
                if (current.Count > MaxExactVisualConfigurations)
                    return [];
            }

            return current;
        }

        private static List<UnitVisualConfiguration> MergeEquivalentVisualConfigurations(
            IEnumerable<UnitVisualConfiguration> configurations)
        {
            var merged = new Dictionary<string, UnitVisualConfiguration>(StringComparer.Ordinal);
            foreach (var configuration in configurations)
            {
                var key = string.Join(
                    "\u001f",
                    configuration.WsModelOccurrences
                        .Where(entry => entry.Value > 0)
                        .OrderBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase)
                        .Select(entry => $"{entry.Key}\u001e{entry.Value}"));
                if (merged.TryGetValue(key, out var existing))
                {
                    merged[key] = existing with
                    {
                        Probability = existing.Probability + configuration.Probability,
                    };
                }
                else
                {
                    merged[key] = configuration;
                }
            }

            return merged.Values
                .Where(configuration => configuration.Probability > 0)
                .ToList();
        }

        private static void AccumulateExpectedWsModelOccurrences(
            BatchState state,
            VariantMesh mesh,
            double parentProbability,
            Dictionary<string, double> result,
            Dictionary<string, IReadOnlyDictionary<string, double>> cache,
            HashSet<string> visiting)
        {
            if (parentProbability <= 0)
                return;

            if (!string.IsNullOrWhiteSpace(mesh.ModelReference))
            {
                var modelPath = Normalize(mesh.ModelReference);
                if (Path.GetExtension(modelPath)
                        .Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) &&
                    FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        GetGameplayTraversalContainers(state),
                        modelPath) != null)
                {
                    result[modelPath] =
                        result.GetValueOrDefault(modelPath) + parentProbability;
                }
            }

            foreach (var slot in mesh.ChildSlots ?? [])
            {
                var slotProbability = ParseVmdSlotProbability(slot.Probability);
                if (slotProbability <= 0)
                    continue;

                var childMeshCount = slot.ChildMeshes?.Count ?? 0;
                var childReferenceCount = slot.ChildReferences?.Count ?? 0;
                var alternativeCount = childMeshCount + childReferenceCount;
                if (alternativeCount == 0)
                    continue;

                // VMD does not expose a per-child weight. Treat the entries in an active slot as
                // equally likely alternatives, while the slot probability controls whether the
                // slot is populated at all.
                var alternativeProbability =
                    parentProbability * slotProbability / alternativeCount;

                foreach (var child in slot.ChildMeshes ?? [])
                {
                    AccumulateExpectedWsModelOccurrences(
                        state,
                        child,
                        alternativeProbability,
                        result,
                        cache,
                        visiting);
                }

                foreach (var reference in slot.ChildReferences ?? [])
                {
                    if (string.IsNullOrWhiteSpace(reference.Reference))
                        continue;

                    var childOccurrences = GetExpectedWsModelOccurrencesForVmd(
                        state,
                        reference.Reference,
                        cache,
                        visiting);
                    foreach (var (wsModelPath, expectedOccurrences) in childOccurrences)
                    {
                        result[wsModelPath] =
                            result.GetValueOrDefault(wsModelPath) +
                            alternativeProbability * expectedOccurrences;
                    }
                }
            }
        }

        private static double ParseVmdSlotProbability(string? value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return 1.0;

            if (!double.TryParse(
                    value.Trim(),
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out var probability))
            {
                return 1.0;
            }

            // Most VMDs use 0..1. Be tolerant of hand-authored percentage-style values.
            if (probability > 1.0 && probability <= 100.0)
                probability /= 100.0;

            return Math.Clamp(probability, 0.0, 1.0);
        }

        private static string GetArmyUnitIdentity(Wh3ResolvedUnitVisual unit)
            => unit.Identity.Trim().ToLowerInvariant();

        private static string GetArmyUnitIdentity(Wh3UnitCategoryUsage usage)
        {
            if (!string.IsNullOrWhiteSpace(usage.MainUnitKey))
                return $"main:{usage.MainUnitKey.Trim().ToLowerInvariant()}";
            if (!string.IsNullOrWhiteSpace(usage.LandUnitKey))
                return $"land:{usage.LandUnitKey.Trim().ToLowerInvariant()}";
            return string.Empty;
        }

        private static string GetArmyUnitIdentity(Wh3UnitDirectAssetUsage usage)
        {
            if (!string.IsNullOrWhiteSpace(usage.MainUnitKey))
                return $"main:{usage.MainUnitKey.Trim().ToLowerInvariant()}";
            if (!string.IsNullOrWhiteSpace(usage.LandUnitKey))
                return $"land:{usage.LandUnitKey.Trim().ToLowerInvariant()}";
            return string.Empty;
        }

        private static HashSet<string> GetBatchRoots(
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh)
        {
            var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var candidate in candidates)
            {
                if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                    roots.UnionWith(candidateRoots);
                else
                    roots.Add(Normalize(candidate.RootVmdPath));
            }

            return roots;
        }

        private static double GetExpectedArmyResidentPixels(
            BatchState state,
            long atlasPixels,
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh)
        {
            if (atlasPixels <= 0)
                return 0;

            var targetWsModels = candidates
                .SelectMany(candidate => candidate.Usages)
                .Select(usage => Normalize(usage.AssetPath))
                .Where(path => path.Length != 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
            var roots = GetBatchRoots(candidates, rootsByMesh);

            return atlasPixels * GetExpectedArmyResidentProbability(
                state,
                targetWsModels,
                roots);
        }

        private static double GetExpectedArmyResidentProbability(
            BatchState state,
            IReadOnlyCollection<string> targetAssetPaths,
            IEnumerable<string> fallbackRoots)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            var cacheKey = new ArmyResidencyProbabilityCacheKey(
                BuildCanonicalPathSetKey(targetAssetPaths),
                BuildCanonicalPathSetKey(fallbackRoots));
            if (state.AtlasValueGateArmyResidentProbabilityCache.TryGetValue(
                    cacheKey,
                    out var cachedProbability))
            {
                state.AtlasValueGateArmyResidentProbabilityCacheHits++;
                return cachedProbability;
            }

            state.AtlasValueGateArmyResidentProbabilityCacheMisses++;
            var probability = GetExpectedArmyResidentProbability(
                state.ArmyResidencyModel,
                targetAssetPaths,
                fallbackRoots,
                state.CancellationToken);
            state.AtlasValueGateArmyResidentProbabilityCache[cacheKey] = probability;
            return probability;
        }

        private static string BuildCanonicalPathSetKey(IEnumerable<string> paths)
            => string.Join(
                '\u001f',
                paths
                    .Select(Normalize)
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase));

        private static double GetExpectedArmyResidentProbability(
            ArmyResidencyModel? model,
            IReadOnlyCollection<string> targetAssetPaths,
            IEnumerable<string> fallbackRoots,
            CancellationToken cancellationToken = default)
        {
            if (model == null || model.PlayerCultureWeights.Count == 0)
                return 0;

            var normalizedTargets = targetAssetPaths
                .Select(Normalize)
                .Where(path => path.Length != 0)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            var normalizedFallbackRoots = fallbackRoots
                .Select(Normalize)
                .Where(path => path.Length != 0)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            var relevantUnitIds = GetRelevantArmyUnitIds(
                model,
                normalizedTargets,
                normalizedFallbackRoots);
            cancellationToken.ThrowIfCancellationRequested();
            var relevantCultures = GetRelevantArmyCultures(
                model,
                normalizedTargets,
                normalizedFallbackRoots,
                relevantUnitIds);
            if (relevantUnitIds.Count == 0 || relevantCultures.Count == 0)
                return 0;

            var fallbackCoveredByCategory = model.Scenario.ArmySlotTemplate.Keys.ToDictionary(
                category => category,
                _ => new HashSet<string>(StringComparer.OrdinalIgnoreCase));
            foreach (var root in normalizedFallbackRoots)
            {
                if (!model.UnitsByVmd.TryGetValue(root, out var unitsForVmd))
                    continue;

                foreach (var (category, unitIds) in unitsForVmd)
                {
                    if (fallbackCoveredByCategory.TryGetValue(category, out var covered))
                        covered.UnionWith(unitIds);
                }
            }

            var probabilitiesByCulture = new Dictionary<string, double>(
                StringComparer.OrdinalIgnoreCase);
            foreach (var culture in relevantCultures)
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (!model.UnitsByCultureAndCategory.TryGetValue(
                        culture,
                        out var unitsByCategory))
                {
                    continue;
                }

                var notResidentProbability = 1.0;
                foreach (var (category, slotCount) in model.Scenario.ArmySlotTemplate)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!unitsByCategory.TryGetValue(category, out var cultureUnits))
                        continue;

                    var population = cultureUnits.Count;
                    if (population == 0)
                        continue;

                    double perSlotPresenceProbability = 0;
                    foreach (var unitId in EnumerateRelevantArmyUnitIds(
                                 cultureUnits,
                                 relevantUnitIds))
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                        double unitCardPresenceProbability = 0;
                        var notPresentAcrossRoles = 1.0;
                        var exactRoles = new HashSet<Wh3UnitVisualRole>();

                        if (model.VisualConfigurationsByUnitAndRole.TryGetValue(
                                unitId,
                                out var configurationsByRole))
                        {
                            foreach (var (role, configurations) in configurationsByRole)
                            {
                                if (configurations.Count == 0)
                                    continue;

                                exactRoles.Add(role);
                                var perEntityPresenceProbability = configurations
                                    .Where(configuration =>
                                        configuration.WsModelOccurrences.Any(entry =>
                                            entry.Value > 0 &&
                                            normalizedTargets.Contains(entry.Key)))
                                    .Sum(configuration => configuration.Probability);
                                perEntityPresenceProbability = Math.Clamp(
                                    perEntityPresenceProbability,
                                    0.0,
                                    1.0);
                                if (perEntityPresenceProbability <= 0)
                                    continue;

                                var entityCount = Math.Max(
                                    1,
                                    model.EntityCountByUnitAndRole
                                        .GetValueOrDefault(unitId)?
                                        .GetValueOrDefault(role, 1) ?? 1);
                                notPresentAcrossRoles *= Math.Pow(
                                    1.0 - perEntityPresenceProbability,
                                    entityCount);
                            }
                        }

                        if (model.ExpectedWsModelOccurrencesByUnit.TryGetValue(
                                unitId,
                                out var expectedOccurrences))
                        {
                            var expectedPresenceByRole =
                                new Dictionary<Wh3UnitVisualRole, double>();
                            foreach (var wsModelPath in normalizedTargets)
                            {
                                if (!expectedOccurrences.ByWsModel.TryGetValue(
                                        wsModelPath,
                                        out var occurrencesByRole))
                                {
                                    continue;
                                }

                                foreach (var (role, expectedOccurrencesPerEntity) in occurrencesByRole)
                                {
                                    if (exactRoles.Contains(role))
                                        continue;

                                    expectedPresenceByRole[role] =
                                        expectedPresenceByRole.GetValueOrDefault(role) +
                                        expectedOccurrencesPerEntity;
                                }
                            }

                            foreach (var (role, expectedOccurrencesPerEntity) in expectedPresenceByRole)
                            {
                                if (expectedOccurrencesPerEntity <= 0)
                                    continue;

                                var entityCount = Math.Max(
                                    1,
                                    model.EntityCountByUnitAndRole
                                        .GetValueOrDefault(unitId)?
                                        .GetValueOrDefault(role, 1) ?? 1);
                                notPresentAcrossRoles *= Math.Pow(
                                    1.0 - Math.Clamp(expectedOccurrencesPerEntity, 0.0, 1.0),
                                    entityCount);
                            }

                            unitCardPresenceProbability = 1.0 - notPresentAcrossRoles;
                        }
                        else if (exactRoles.Count != 0)
                        {
                            unitCardPresenceProbability = 1.0 - notPresentAcrossRoles;
                        }

                        // A fallback VMD root is a category-level consumer. It is a union
                        // with any exact WSModel/direct-asset evidence, not an alternate
                        // branch that is ignored whenever the unit happens to have another
                        // expected visual occurrence.
                        if (fallbackCoveredByCategory[category].Contains(unitId))
                        {
                            unitCardPresenceProbability = Math.Max(
                                unitCardPresenceProbability,
                                1.0);
                        }

                        if (unitCardPresenceProbability <= 0)
                            continue;

                        perSlotPresenceProbability +=
                            unitCardPresenceProbability / population;
                    }

                    perSlotPresenceProbability = Math.Clamp(
                        perSlotPresenceProbability,
                        0.0,
                        1.0);
                    notResidentProbability *= Math.Pow(
                        1.0 - perSlotPresenceProbability,
                        slotCount);
                }

                probabilitiesByCulture[culture] = Math.Clamp(
                    1.0 - notResidentProbability,
                    0.0,
                    1.0);
            }

            return CombineBattleResidentProbabilities(
                probabilitiesByCulture,
                model.PlayerCultureWeights,
                model.OpponentCultureWeights);
        }

        private static double GetWeightedCultureAverage(
            IReadOnlyDictionary<string, double> valuesByCulture,
            IReadOnlyDictionary<string, double> cultureWeights)
        {
            var totalWeight = cultureWeights.Values
                .Where(weight => weight > 0)
                .Sum();
            if (totalWeight <= 0)
                return 0;

            double total = 0;
            foreach (var (culture, weight) in cultureWeights)
            {
                if (weight <= 0)
                    continue;

                total += weight * valuesByCulture.GetValueOrDefault(culture);
            }

            return total / totalWeight;
        }

        private static double CombineBattleResidentProbabilities(
            IReadOnlyDictionary<string, double> probabilitiesByCulture,
            IReadOnlyDictionary<string, double> playerCultureWeights,
            IReadOnlyDictionary<string, double> opponentCultureWeights)
        {
            var playerProbability = Math.Clamp(
                GetWeightedCultureAverage(
                    probabilitiesByCulture,
                    playerCultureWeights),
                0.0,
                1.0);
            var opponentProbability = Math.Clamp(
                GetWeightedCultureAverage(
                    probabilitiesByCulture,
                    opponentCultureWeights),
                0.0,
                1.0);

            // The two armies are independent samples. For an asset used by only one culture,
            // unrelated opponents contribute zero and this reduces to a mirror-battle
            // adjustment. Genuine cross-culture sharing is handled automatically.
            return Math.Clamp(
                1.0 - (1.0 - playerProbability) * (1.0 - opponentProbability),
                0.0,
                1.0);
        }

        private static double CalculateExpectedArmyResidentPixels(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            if (state.ArmyResidencyModel == null || batches.Count == 0)
                return 0;

            var rootsByMesh = BuildCandidateRootVmdPaths(
                state,
                batches.SelectMany(batch => batch));
            double total = 0;
            foreach (var batch in batches)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                if (!TryGetGeneratedAtlasPixelCost(
                        state,
                        batch,
                        out var pixels,
                        out _))
                {
                    continue;
                }

                total += GetExpectedArmyResidentPixels(
                    state,
                    pixels,
                    batch,
                    rootsByMesh);
            }

            return total;
        }

        private static HashSet<string> GetArmyCulturesForRoots(
            ArmyResidencyModel? model,
            IEnumerable<string> roots)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (model == null)
                return result;

            foreach (var rootValue in roots)
            {
                var root = Normalize(rootValue);
                if (!model.UnitsByVmd.TryGetValue(root, out var byCategory))
                    continue;

                foreach (var unitId in byCategory.Values.SelectMany(unitIds => unitIds))
                {
                    if (model.CulturesByUnit.TryGetValue(unitId, out var cultures))
                        result.UnionWith(cultures);
                }
            }

            return result;
        }

        private static HashSet<string> GetRelevantArmyUnitIds(
            ArmyResidencyModel model,
            IEnumerable<string> assetPaths,
            IEnumerable<string> fallbackRoots)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var assetPathValue in assetPaths)
            {
                var assetPath = Normalize(assetPathValue);
                if (assetPath.Length == 0 ||
                    !model.UnitIdsByAssetPath.TryGetValue(assetPath, out var unitIds))
                {
                    continue;
                }

                result.UnionWith(unitIds);
            }

            // VMD roots are a separate residency channel. They intentionally do not
            // depend on UnitIdsByAssetPath: a fallback root is resolved through the
            // scenario's VMD-to-unit mapping, even when the asset index did not retain a
            // direct asset entry for that root.
            foreach (var rootValue in fallbackRoots)
            {
                var root = Normalize(rootValue);
                if (root.Length == 0 ||
                    !model.UnitsByVmd.TryGetValue(root, out var unitsByCategory))
                {
                    continue;
                }

                result.UnionWith(
                    unitsByCategory.Values.SelectMany(unitIds => unitIds));
            }

            return result;
        }

        private static IEnumerable<string> EnumerateRelevantArmyUnitIds(
            IReadOnlySet<string> cultureUnits,
            IReadOnlySet<string> relevantUnitIds)
        {
            // Most mesh groups touch a small subset of a culture's roster. Iterate the
            // smaller side of the intersection so relevance filtering does not merely move
            // the full-roster scan behind a Contains call.
            if (relevantUnitIds.Count < cultureUnits.Count)
            {
                foreach (var unitId in relevantUnitIds)
                {
                    if (cultureUnits.Contains(unitId))
                        yield return unitId;
                }

                yield break;
            }

            foreach (var unitId in cultureUnits)
            {
                if (relevantUnitIds.Contains(unitId))
                    yield return unitId;
            }
        }

        private static HashSet<string> GetRelevantArmyCultures(
            ArmyResidencyModel model,
            IEnumerable<string> assetPaths,
            IEnumerable<string> fallbackRoots,
            IEnumerable<string> relevantUnitIds)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var assetPathValue in assetPaths)
            {
                var assetPath = Normalize(assetPathValue);
                if (assetPath.Length == 0 ||
                    !model.CulturesByAssetPath.TryGetValue(assetPath, out var cultures))
                {
                    continue;
                }

                result.UnionWith(cultures);
            }

            foreach (var rootValue in fallbackRoots)
            {
                var root = Normalize(rootValue);
                if (root.Length == 0 ||
                    !model.UnitsByVmd.TryGetValue(root, out var unitsByCategory))
                {
                    continue;
                }

                foreach (var unitId in unitsByCategory.Values.SelectMany(unitIds => unitIds))
                {
                    if (model.CulturesByUnit.TryGetValue(unitId, out var cultures))
                        result.UnionWith(cultures);
                }
            }

            // expectedEntitiesByMesh can provide a conservative unit fallback for an asset
            // whose dependency path was not indexed. Include those units' cultures too.
            foreach (var unitId in relevantUnitIds)
            {
                if (model.CulturesByUnit.TryGetValue(unitId, out var cultures))
                    result.UnionWith(cultures);
            }

            return result;
        }

        private static HashSet<Wh3ArmyUnitCategory> GetArmyCategoriesForRoots(
            ArmyResidencyModel? model,
            IEnumerable<string> roots)
        {
            var result = new HashSet<Wh3ArmyUnitCategory>();
            if (model == null)
                return result;

            foreach (var root in roots)
            {
                if (!model.UnitsByVmd.TryGetValue(root, out var byCategory))
                    continue;

                foreach (var category in byCategory.Keys)
                    result.Add(category);
            }

            return result;
        }

        private static void OptimizeBatchForVmdLocality(
            BatchState state,
            List<AtlasCandidate> batch,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            List<List<AtlasCandidate>> output)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            const int maxAcceptedLocalitySplits = 32;
            const int maxGlobalPixelIncreasePercent = 25;
            const int minimumResidentPixelSavingPercent = 10;
            const double comparisonEpsilon = 0.5;

            if (batch.Count < 4 ||
                state.VmdLocalitySplitsAccepted >= maxAcceptedLocalitySplits ||
                !TryGetGeneratedAtlasPixelCost(
                    state,
                    batch,
                    out var baselinePixels,
                    out _))
            {
                output.Add(batch);
                return;
            }

            var baselineRootCount = GetBatchRootCount(batch, rootsByMesh);
            if (baselineRootCount <= 1)
            {
                output.Add(batch);
                return;
            }

            var baselineVmdResidentPixels = GetAtlasResidencyProxy(
                baselinePixels,
                baselineRootCount);
            var baselineArmyResidentPixels = GetExpectedArmyResidentPixels(
                state,
                baselinePixels,
                batch,
                rootsByMesh);
            var useArmyMetric =
                state.ArmyResidencyModel != null &&
                baselineArmyResidentPixels > comparisonEpsilon;
            var baselineAffinity = CalculateMergeAffinityScore(
                [batch],
                affinityGroups);

            AtlasBatchSplitProposal? bestProposal = null;
            var bestVmdResidentPixels = baselineVmdResidentPixels;
            var bestArmyResidentPixels = baselineArmyResidentPixels;
            var bestGlobalPixels = baselinePixels;
            var bestAffinity = baselineAffinity;
            var evaluations = new List<(
                AtlasBatchSplitProposal Proposal,
                ArmyLocalitySplitEvaluationReportEntry Entry)>();

            foreach (var proposal in CreateVmdLocalitySplitProposals(
                         batch,
                         rootsByMesh,
                         state.ArmyResidencyModel,
                         state.CancellationToken))
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                state.VmdLocalitySplitEvaluations++;

                if (!TryGetGeneratedAtlasPixelCost(
                        state,
                        proposal.Left,
                        out var leftPixels,
                        out _) ||
                    !TryGetGeneratedAtlasPixelCost(
                        state,
                        proposal.Right,
                        out var rightPixels,
                        out _))
                {
                    continue;
                }

                var combinedPixels = checked(leftPixels + rightPixels);
                var leftRootCount = GetBatchRootCount(proposal.Left, rootsByMesh);
                var rightRootCount = GetBatchRootCount(proposal.Right, rootsByMesh);
                var combinedVmdResidentPixels = checked(
                    GetAtlasResidencyProxy(leftPixels, leftRootCount) +
                    GetAtlasResidencyProxy(rightPixels, rightRootCount));
                var combinedArmyResidentPixels =
                    GetExpectedArmyResidentPixels(
                        state,
                        leftPixels,
                        proposal.Left,
                        rootsByMesh) +
                    GetExpectedArmyResidentPixels(
                        state,
                        rightPixels,
                        proposal.Right,
                        rootsByMesh);

                string? rejectionReason = null;
                if (combinedPixels * 100 >
                    baselinePixels * (100L + maxGlobalPixelIncreasePercent))
                {
                    rejectionReason = "global-pixel-cap";
                }
                else if (useArmyMetric &&
                         combinedArmyResidentPixels * 100.0 >
                         baselineArmyResidentPixels *
                         (100.0 - minimumResidentPixelSavingPercent))
                {
                    rejectionReason = "insufficient-expected-army-saving";
                }
                else if (useArmyMetric &&
                         combinedVmdResidentPixels > baselineVmdResidentPixels)
                {
                    rejectionReason = "VMD-residency-regression";
                }
                else if (!useArmyMetric &&
                         combinedVmdResidentPixels * 100 >
                         baselineVmdResidentPixels *
                         (100L - minimumResidentPixelSavingPercent))
                {
                    rejectionReason = "insufficient-VMD-residency-saving";
                }

                if (rejectionReason != null)
                {
                    evaluations.Add((
                        proposal,
                        new ArmyLocalitySplitEvaluationReportEntry(
                            false,
                            rejectionReason,
                            baselinePixels,
                            combinedPixels,
                            baselineVmdResidentPixels,
                            combinedVmdResidentPixels,
                            baselineArmyResidentPixels,
                            combinedArmyResidentPixels)));
                    continue;
                }

                var proposedAffinity = CalculateMergeAffinityScore(
                    [proposal.Left, proposal.Right],
                    affinityGroups);
                if (proposedAffinity < baselineAffinity)
                {
                    evaluations.Add((
                        proposal,
                        new ArmyLocalitySplitEvaluationReportEntry(
                            false,
                            "merge-affinity-regression",
                            baselinePixels,
                            combinedPixels,
                            baselineVmdResidentPixels,
                            combinedVmdResidentPixels,
                            baselineArmyResidentPixels,
                            combinedArmyResidentPixels)));
                    continue;
                }

                evaluations.Add((
                    proposal,
                    new ArmyLocalitySplitEvaluationReportEntry(
                        false,
                        string.Empty,
                        baselinePixels,
                        combinedPixels,
                        baselineVmdResidentPixels,
                        combinedVmdResidentPixels,
                        baselineArmyResidentPixels,
                        combinedArmyResidentPixels)));

                var better = useArmyMetric
                    ? combinedArmyResidentPixels < bestArmyResidentPixels - comparisonEpsilon ||
                      (Math.Abs(combinedArmyResidentPixels - bestArmyResidentPixels) <= comparisonEpsilon &&
                       combinedVmdResidentPixels < bestVmdResidentPixels) ||
                      (Math.Abs(combinedArmyResidentPixels - bestArmyResidentPixels) <= comparisonEpsilon &&
                       combinedVmdResidentPixels == bestVmdResidentPixels &&
                       combinedPixels < bestGlobalPixels) ||
                      (Math.Abs(combinedArmyResidentPixels - bestArmyResidentPixels) <= comparisonEpsilon &&
                       combinedVmdResidentPixels == bestVmdResidentPixels &&
                       combinedPixels == bestGlobalPixels &&
                       proposedAffinity > bestAffinity)
                    : combinedVmdResidentPixels < bestVmdResidentPixels ||
                      (combinedVmdResidentPixels == bestVmdResidentPixels &&
                       combinedPixels < bestGlobalPixels) ||
                      (combinedVmdResidentPixels == bestVmdResidentPixels &&
                       combinedPixels == bestGlobalPixels &&
                       proposedAffinity > bestAffinity);

                if (!better)
                    continue;

                bestProposal = proposal;
                bestVmdResidentPixels = combinedVmdResidentPixels;
                bestArmyResidentPixels = combinedArmyResidentPixels;
                bestGlobalPixels = combinedPixels;
                bestAffinity = proposedAffinity;
            }

            foreach (var (proposal, entry) in evaluations)
            {
                var accepted = bestProposal != null && ReferenceEquals(proposal, bestProposal);
                state.ArmyLocalitySplitEvaluations.Add(
                    entry with
                    {
                        Accepted = accepted,
                        Decision = accepted
                            ? "accepted"
                            : string.IsNullOrEmpty(entry.Decision)
                                ? "eligible-not-selected"
                                : entry.Decision,
                    });
            }

            if (bestProposal == null)
            {
                output.Add(batch);
                return;
            }

            state.VmdLocalitySplitsAccepted++;
            state.VmdLocalityResidentPixelsSaved = checked(
                state.VmdLocalityResidentPixelsSaved +
                baselineVmdResidentPixels -
                bestVmdResidentPixels);
            state.ExpectedArmyResidentPixelsSavedByLocality += Math.Max(
                0,
                baselineArmyResidentPixels - bestArmyResidentPixels);
            state.VmdLocalityGlobalPixelsAdded = checked(
                state.VmdLocalityGlobalPixelsAdded +
                Math.Max(0, bestGlobalPixels - baselinePixels));

            OptimizeBatchForVmdLocality(
                state,
                bestProposal.Left,
                rootsByMesh,
                affinityGroups,
                output);
            OptimizeBatchForVmdLocality(
                state,
                bestProposal.Right,
                rootsByMesh,
                affinityGroups,
                output);
        }

        private static IReadOnlyList<AtlasBatchSplitProposal> CreateVmdLocalitySplitProposals(
            IReadOnlyList<AtlasCandidate> batch,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh,
            ArmyResidencyModel? armyModel,
            CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var groups = batch
                .GroupBy(GetAtlasPlanningSourceIdentity)
                .Select(group =>
                {
                    var candidates = group
                        .OrderBy(x => x.RootVmdPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.LodIndex)
                        .ThenBy(x => x.Key.PartIndex)
                        .ToList();
                    return new AtlasPlanningCandidateGroup(
                        group.Key,
                        candidates,
                        candidates[0],
                        GetCanonicalCrop(candidates[0]).Crop);
                })
                .ToList();

            if (groups.Count < 2)
                return [];

            var rootsByGroup = groups.ToDictionary(
                group => group.Identity,
                group =>
                {
                    var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var candidate in group.Candidates)
                    {
                        if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                            roots.UnionWith(candidateRoots);
                        else
                            roots.Add(Normalize(candidate.RootVmdPath));
                    }

                    return roots;
                });

            var distinctRoots = rootsByGroup.Values
                .SelectMany(roots => roots)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (distinctRoots.Count <= 1)
                return [];

            var proposals = new List<AtlasBatchSplitProposal>();
            var seen = new HashSet<string>(StringComparer.Ordinal);

            void AddProposal(IEnumerable<AtlasPlanningCandidateGroup> leftGroups)
            {
                var leftGroupList = leftGroups.ToList();
                if (leftGroupList.Count == 0 || leftGroupList.Count == groups.Count)
                    return;

                var leftIdentities = leftGroupList
                    .Select(group => group.Identity)
                    .ToHashSet();
                var rightGroupList = groups
                    .Where(group => !leftIdentities.Contains(group.Identity))
                    .ToList();
                var left = leftGroupList.SelectMany(group => group.Candidates).ToList();
                var right = rightGroupList.SelectMany(group => group.Candidates).ToList();
                if (left.Count < 2 || right.Count < 2)
                    return;

                var signature = string.Join(
                    "\n",
                    left
                        .Select(candidate => candidate.Key.ToString())
                        .OrderBy(value => value, StringComparer.Ordinal));
                if (!seen.Add(signature))
                    return;

                proposals.Add(new AtlasBatchSplitProposal(left, right));
            }

            // Culture is the primary residency boundary. Consider every modeled culture
            // here, not only player-scored cultures, so proven opponent/shared-asset consumers
            // can still keep unrelated placements out of the same atlas.
            if (armyModel != null)
            {
                foreach (var culture in armyModel.UnitsByCultureAndCategory.Keys)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    AddProposal(groups.Where(group =>
                        GetArmyCulturesForRoots(
                            armyModel,
                            rootsByGroup[group.Identity])
                        .Contains(culture)));
                }

                foreach (var category in armyModel.Scenario.ArmySlotTemplate.Keys)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    AddProposal(groups.Where(group =>
                        GetArmyCategoriesForRoots(
                            armyModel,
                            rootsByGroup[group.Identity])
                        .Contains(category)));
                }
            }

            // Then try isolating the assets reachable from each root. Shared source/crop
            // identities stay indivisible, so genuinely reused placements remain shared.
            foreach (var root in distinctRoots
                         .OrderByDescending(root =>
                             groups.Count(group => rootsByGroup[group.Identity].Contains(root)))
                         .ThenBy(root => root, StringComparer.OrdinalIgnoreCase)
                         .Take(12))
            {
                cancellationToken.ThrowIfCancellationRequested();
                AddProposal(groups.Where(group =>
                    rootsByGroup[group.Identity].Contains(root)));
            }

            // Then cluster equal/similar root signatures. This catches unrelated VMD families
            // that happened to pack efficiently together under the old texture-first ordering.
            string RootSignature(AtlasPlanningCandidateGroup group)
                => string.Join(
                    "\u001f",
                    rootsByGroup[group.Identity]
                        .OrderBy(root => root, StringComparer.OrdinalIgnoreCase));

            var ordered = groups
                .OrderBy(RootSignature, StringComparer.OrdinalIgnoreCase)
                .ThenBy(group => BuildAtlasPlanningOrderKey(group.Representative), StringComparer.Ordinal)
                .ToList();
            var boundaries = new List<int>();
            for (var index = 1; index < ordered.Count; index++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                if (!RootSignature(ordered[index - 1]).Equals(
                        RootSignature(ordered[index]),
                        StringComparison.OrdinalIgnoreCase))
                {
                    boundaries.Add(index);
                }
            }

            const int maxOrderedLocalitySplitEvaluations = 12;
            IEnumerable<int> selectedBoundaries = boundaries;
            if (boundaries.Count > maxOrderedLocalitySplitEvaluations)
            {
                selectedBoundaries = Enumerable.Range(0, maxOrderedLocalitySplitEvaluations)
                    .Select(index => boundaries[
                        index * (boundaries.Count - 1) /
                        (maxOrderedLocalitySplitEvaluations - 1)])
                    .Distinct();
            }

            foreach (var boundary in selectedBoundaries)
            {
                cancellationToken.ThrowIfCancellationRequested();
                AddProposal(ordered.Take(boundary));
            }

            const int maxLocalitySplitProposals = 24;
            return proposals.Count <= maxLocalitySplitProposals
                ? proposals
                : proposals.Take(maxLocalitySplitProposals).ToList();
        }

        private static List<List<AtlasCandidate>> OptimizeBatchesForMergeAffinity(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            var working = batches.Select(batch => batch.ToList()).ToList();
            if (!state.MergeCompatibleMeshesEnabled || working.Count < 2)
                return working;

            var affinityGroups = BuildMergeAffinityGroups(
                state,
                working.SelectMany(batch => batch));
            if (affinityGroups.Count == 0)
                return working;

            var rootsByMesh = BuildCandidateRootVmdPaths(
                state,
                working.SelectMany(batch => batch));
            var expectedArmyEntitiesByMesh = BuildExpectedArmyEntitiesByMesh(
                state.ArmyResidencyModel,
                working.SelectMany(batch => batch),
                rootsByMesh,
                state.CancellationToken);
            var currentExpectedArmyDrawCallsEliminated =
                CalculateExpectedArmyDrawCallsEliminated(
                    state,
                    BuildBatchIndexByMesh(working),
                    affinityGroups,
                    expectedArmyEntitiesByMesh);

            state.MergeAwareAffinityPotentialBefore +=
                CalculateMergeAffinityScore(working, affinityGroups);
            state.ExpectedArmyDrawCallsEliminatedBeforeMergeAware +=
                currentExpectedArmyDrawCallsEliminated;

            const int maxPasses = 2;
            for (var pass = 0; pass < maxPasses; pass++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var changed = false;
                var batchByMesh = BuildBatchIndexByMesh(working);
                var candidatePairWeights = new Dictionary<AtlasBatchPair, int>();

                foreach (var group in affinityGroups)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var occupiedBatches = group.Meshes
                        .Where(batchByMesh.ContainsKey)
                        .Select(mesh => batchByMesh[mesh])
                        .Distinct()
                        .OrderBy(x => x)
                        .ToArray();

                    for (var left = 0; left < occupiedBatches.Length; left++)
                    {
                        for (var right = left + 1; right < occupiedBatches.Length; right++)
                        {
                            var pair = new AtlasBatchPair(
                                occupiedBatches[left],
                                occupiedBatches[right]);
                            candidatePairWeights[pair] =
                                candidatePairWeights.GetValueOrDefault(pair) + 1;
                        }
                    }
                }

                // Replanning a pair invokes the real atlas packer repeatedly. Bound the search
                // for pathological packs while prioritizing pairs that can reunite the largest
                // number of otherwise-mergeable groups.
                const int maxMergeAwareBatchPairsPerPass = 64;
                var candidatePairs = candidatePairWeights
                    .OrderByDescending(x => x.Value)
                    .ThenBy(x => x.Key.FirstBatchId)
                    .ThenBy(x => x.Key.SecondBatchId)
                    .Take(maxMergeAwareBatchPairsPerPass)
                    .Select(x => x.Key)
                    .ToList();

                state.MergeAwareBatchPairsConsidered += candidatePairs.Count;

                for (var pairIndex = 0; pairIndex < candidatePairs.Count; pairIndex++)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    ReportProgress(
                        state.Progress,
                        "Optimizing atlas batches",
                        pairIndex + 1,
                        candidatePairs.Count,
                        $"Merge-affinity pass {pass + 1}: pair {pairIndex + 1}");
                    var pair = candidatePairs[pairIndex];
                    var leftIndex = pair.FirstBatchId;
                    var rightIndex = pair.SecondBatchId;
                    var currentLeft = working[leftIndex];
                    var currentRight = working[rightIndex];

                    if (!TryGetGeneratedAtlasPixelCost(
                            state,
                            currentLeft,
                            out var leftBaselinePixels,
                            out _) ||
                        !TryGetGeneratedAtlasPixelCost(
                            state,
                            currentRight,
                            out var rightBaselinePixels,
                            out _))
                    {
                        continue;
                    }

                    var baselinePixels = checked(leftBaselinePixels + rightBaselinePixels);
                    var baselineResidentPixels = checked(
                        GetAtlasResidencyProxy(
                            leftBaselinePixels,
                            GetBatchRootCount(currentLeft, rootsByMesh)) +
                        GetAtlasResidencyProxy(
                            rightBaselinePixels,
                            GetBatchRootCount(currentRight, rootsByMesh)));
                    var baselineArmyResidentPixels =
                        GetExpectedArmyResidentPixels(
                            state,
                            leftBaselinePixels,
                            currentLeft,
                            rootsByMesh) +
                        GetExpectedArmyResidentPixels(
                            state,
                            rightBaselinePixels,
                            currentRight,
                            rootsByMesh);
                    var baselineAffinity = CalculateMergeAffinityScore(working, affinityGroups);
                    var baselineExpectedArmyDrawCallsEliminated =
                        currentExpectedArmyDrawCallsEliminated;
                    AtlasBatchSplitProposal? bestProposal = null;
                    var bestPixels = baselinePixels;
                    var bestResidentPixels = baselineResidentPixels;
                    var bestArmyResidentPixels = baselineArmyResidentPixels;
                    var bestExpectedArmyDrawCallsEliminated =
                        baselineExpectedArmyDrawCallsEliminated;
                    var bestAffinity = baselineAffinity;

                    foreach (var proposal in CreateMergeAwareRepartitionProposals(
                                 currentLeft,
                                 currentRight,
                                 affinityGroups))
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        state.MergeAwareRepartitionEvaluations++;

                        if (!TryGetGeneratedAtlasPixelCost(
                                state,
                                proposal.Left,
                                out var leftPixels,
                                out _) ||
                            !TryGetGeneratedAtlasPixelCost(
                                state,
                                proposal.Right,
                                out var rightPixels,
                                out _))
                        {
                            continue;
                        }

                        var combinedPixels = checked(leftPixels + rightPixels);
                        if (combinedPixels > baselinePixels)
                            continue;

                        var proposedResidentPixels = checked(
                            GetAtlasResidencyProxy(
                                leftPixels,
                                GetBatchRootCount(proposal.Left, rootsByMesh)) +
                            GetAtlasResidencyProxy(
                                rightPixels,
                                GetBatchRootCount(proposal.Right, rootsByMesh)));
                        var proposedArmyResidentPixels =
                            GetExpectedArmyResidentPixels(
                                state,
                                leftPixels,
                                proposal.Left,
                                rootsByMesh) +
                            GetExpectedArmyResidentPixels(
                                state,
                                rightPixels,
                                proposal.Right,
                                rootsByMesh);
                        if ((state.ArmyResidencyModel != null &&
                             proposedArmyResidentPixels > baselineArmyResidentPixels + 0.5) ||
                            proposedResidentPixels > baselineResidentPixels)
                        {
                            state.MergeAwareLocalityRegressionsRejected++;
                            continue;
                        }

                        var proposedAffinity = CalculateMergeAffinityScoreWithReplacement(
                            working,
                            leftIndex,
                            rightIndex,
                            proposal,
                            affinityGroups);

                        // Keep the old unweighted merge count as a hard safety guard. The
                        // army-weighted score decides which non-regressing merge opportunity is
                        // actually more valuable in a representative battle.
                        if (proposedAffinity < baselineAffinity)
                            continue;

                        var proposedBatchByMesh = BuildBatchIndexByMesh(working);
                        foreach (var candidate in proposal.Left)
                            proposedBatchByMesh[candidate.Key] = leftIndex;
                        foreach (var candidate in proposal.Right)
                            proposedBatchByMesh[candidate.Key] = rightIndex;
                        var proposedExpectedArmyDrawCallsEliminated =
                            CalculateExpectedArmyDrawCallsEliminated(
                                state,
                                proposedBatchByMesh,
                                affinityGroups,
                                expectedArmyEntitiesByMesh);

                        const double expectedDrawComparisonEpsilon = 0.000001;
                        const double expectedResidencyComparisonEpsilon = 0.5;
                        var isBetter =
                            proposedArmyResidentPixels <
                                bestArmyResidentPixels - expectedResidencyComparisonEpsilon ||
                            (Math.Abs(
                                 proposedArmyResidentPixels -
                                 bestArmyResidentPixels) <= expectedResidencyComparisonEpsilon &&
                             proposedExpectedArmyDrawCallsEliminated >
                                 bestExpectedArmyDrawCallsEliminated +
                                 expectedDrawComparisonEpsilon) ||
                            (Math.Abs(
                                 proposedArmyResidentPixels -
                                 bestArmyResidentPixels) <= expectedResidencyComparisonEpsilon &&
                             Math.Abs(
                                 proposedExpectedArmyDrawCallsEliminated -
                                 bestExpectedArmyDrawCallsEliminated) <=
                                 expectedDrawComparisonEpsilon &&
                             combinedPixels < bestPixels) ||
                            (Math.Abs(
                                 proposedArmyResidentPixels -
                                 bestArmyResidentPixels) <= expectedResidencyComparisonEpsilon &&
                             Math.Abs(
                                 proposedExpectedArmyDrawCallsEliminated -
                                 bestExpectedArmyDrawCallsEliminated) <=
                                 expectedDrawComparisonEpsilon &&
                             combinedPixels == bestPixels &&
                             proposedResidentPixels < bestResidentPixels) ||
                            (Math.Abs(
                                 proposedArmyResidentPixels -
                                 bestArmyResidentPixels) <= expectedResidencyComparisonEpsilon &&
                             Math.Abs(
                                 proposedExpectedArmyDrawCallsEliminated -
                                 bestExpectedArmyDrawCallsEliminated) <=
                                 expectedDrawComparisonEpsilon &&
                             combinedPixels == bestPixels &&
                             proposedResidentPixels == bestResidentPixels &&
                             proposedAffinity > bestAffinity);

                        if (isBetter)
                        {
                            bestProposal = proposal;
                            bestPixels = combinedPixels;
                            bestResidentPixels = proposedResidentPixels;
                            bestArmyResidentPixels = proposedArmyResidentPixels;
                            bestExpectedArmyDrawCallsEliminated =
                                proposedExpectedArmyDrawCallsEliminated;
                            bestAffinity = proposedAffinity;
                        }
                    }

                    if (bestProposal == null)
                        continue;

                    working[leftIndex] = bestProposal.Left;
                    working[rightIndex] = bestProposal.Right;
                    state.MergeAwareRepartitionsAccepted++;
                    state.MergeAwareRepartitionPixelsSaved = checked(
                        state.MergeAwareRepartitionPixelsSaved +
                        baselinePixels -
                        bestPixels);
                    state.MergeAwareAffinityEliminationsGained +=
                        bestAffinity - baselineAffinity;
                    currentExpectedArmyDrawCallsEliminated =
                        bestExpectedArmyDrawCallsEliminated;
                    state.MergeAwareRepartitionEntries.Add(
                        new MergeAwareRepartitionReportEntry(
                            state.BatchIndex + leftIndex,
                            state.BatchIndex + rightIndex,
                            baselinePixels,
                            bestPixels,
                            baselineAffinity,
                            bestAffinity,
                            baselineExpectedArmyDrawCallsEliminated,
                            bestExpectedArmyDrawCallsEliminated));
                    changed = true;
                }

                if (!changed)
                    break;
            }

            CoalesceMergeAwareBatchesWithoutPixelIncrease(
                state,
                working,
                affinityGroups,
                rootsByMesh,
                expectedArmyEntitiesByMesh,
                ref currentExpectedArmyDrawCallsEliminated);

            state.MergeAwareAffinityPotentialAfter +=
                CalculateMergeAffinityScore(working, affinityGroups);
            return working;
        }

        private static void CoalesceMergeAwareBatchesWithoutPixelIncrease(
            BatchState state,
            List<List<AtlasCandidate>> working,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>> expectedArmyEntitiesByMesh,
            ref double currentExpectedArmyDrawCallsEliminated)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            const int maxCoalesces = 16;
            const int maxPairEvaluationsPerPass = 64;

            for (var pass = 0; pass < maxCoalesces && working.Count >= 2; pass++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportProgress(
                    state.Progress,
                    "Optimizing atlas batches",
                    pass + 1,
                    maxCoalesces,
                    $"Coalescing merge batches, pass {pass + 1}");
                var batchByMesh = BuildBatchIndexByMesh(working);
                var candidatePairWeights = new Dictionary<AtlasBatchPair, int>();

                foreach (var group in affinityGroups)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var occupiedBatches = group.Meshes
                        .Where(batchByMesh.ContainsKey)
                        .Select(mesh => batchByMesh[mesh])
                        .Distinct()
                        .OrderBy(x => x)
                        .ToArray();

                    for (var left = 0; left < occupiedBatches.Length; left++)
                    {
                        for (var right = left + 1; right < occupiedBatches.Length; right++)
                        {
                            var pair = new AtlasBatchPair(
                                occupiedBatches[left],
                                occupiedBatches[right]);
                            candidatePairWeights[pair] =
                                candidatePairWeights.GetValueOrDefault(pair) + 1;
                        }
                    }
                }

                if (candidatePairWeights.Count == 0)
                    break;

                var baselineAffinity = CalculateMergeAffinityScore(working, affinityGroups);
                AtlasBatchPair? bestPair = null;
                List<AtlasCandidate>? bestCombined = null;
                var bestAffinity = baselineAffinity;
                var bestArmyResidentPixelsSaved = double.NegativeInfinity;
                var bestExpectedArmyDrawCallsEliminated =
                    currentExpectedArmyDrawCallsEliminated;
                long bestPixelsSaved = long.MinValue;
                var bestPairWeight = -1;

                var candidatePairs = candidatePairWeights
                    .OrderByDescending(x => x.Value)
                    .ThenBy(x => x.Key.FirstBatchId)
                    .ThenBy(x => x.Key.SecondBatchId)
                    .Take(maxPairEvaluationsPerPass)
                    .ToArray();
                for (var pairIndex = 0; pairIndex < candidatePairs.Length; pairIndex++)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    ReportProgress(
                        state.Progress,
                        "Optimizing atlas batches",
                        pairIndex + 1,
                        candidatePairs.Length,
                        $"Coalescing pass {pass + 1}: pair {pairIndex + 1}");
                    var entry = candidatePairs[pairIndex];
                    var pair = entry.Key;
                    var leftBatch = working[pair.FirstBatchId];
                    var rightBatch = working[pair.SecondBatchId];

                    if (!TryGetGeneratedAtlasPixelCost(
                            state,
                            leftBatch,
                            out var leftPixels,
                            out _) ||
                        !TryGetGeneratedAtlasPixelCost(
                            state,
                            rightBatch,
                            out var rightPixels,
                            out _))
                    {
                        continue;
                    }

                    var baselinePixels = checked(leftPixels + rightPixels);
                    var baselineResidentPixels = checked(
                        GetAtlasResidencyProxy(
                            leftPixels,
                            GetBatchRootCount(leftBatch, rootsByMesh)) +
                        GetAtlasResidencyProxy(
                            rightPixels,
                            GetBatchRootCount(rightBatch, rootsByMesh)));
                    var baselineArmyResidentPixels =
                        GetExpectedArmyResidentPixels(
                            state,
                            leftPixels,
                            leftBatch,
                            rootsByMesh) +
                        GetExpectedArmyResidentPixels(
                            state,
                            rightPixels,
                            rightBatch,
                            rootsByMesh);
                    var combined = leftBatch.Concat(rightBatch).ToList();
                    state.MergeAwareBatchCoalesceEvaluations++;
                    if (!TryGetGeneratedAtlasPixelCost(
                            state,
                            combined,
                            out var combinedPixels,
                            out _) ||
                        combinedPixels > baselinePixels)
                    {
                        continue;
                    }

                    var combinedResidentPixels = GetAtlasResidencyProxy(
                        combinedPixels,
                        GetBatchRootCount(combined, rootsByMesh));
                    var combinedArmyResidentPixels = GetExpectedArmyResidentPixels(
                        state,
                        combinedPixels,
                        combined,
                        rootsByMesh);
                    if ((state.ArmyResidencyModel != null &&
                         combinedArmyResidentPixels > baselineArmyResidentPixels + 0.5) ||
                        combinedResidentPixels > baselineResidentPixels)
                    {
                        state.MergeAwareLocalityRegressionsRejected++;
                        continue;
                    }

                    var proposedAffinity = CalculateMergeAffinityScoreWithMerge(
                        working,
                        pair.FirstBatchId,
                        pair.SecondBatchId,
                        affinityGroups);
                    if (proposedAffinity <= baselineAffinity)
                        continue;

                    var proposedBatchByMesh = BuildBatchIndexByMesh(working);
                    foreach (var candidate in rightBatch)
                        proposedBatchByMesh[candidate.Key] = pair.FirstBatchId;
                    var proposedExpectedArmyDrawCallsEliminated =
                        CalculateExpectedArmyDrawCallsEliminated(
                            state,
                            proposedBatchByMesh,
                            affinityGroups,
                            expectedArmyEntitiesByMesh);

                    var pixelsSaved = baselinePixels - combinedPixels;
                    var armyResidentPixelsSaved =
                        baselineArmyResidentPixels - combinedArmyResidentPixels;
                    const double expectedDrawComparisonEpsilon = 0.000001;
                    const double expectedResidencyComparisonEpsilon = 0.5;
                    var isBetter =
                        armyResidentPixelsSaved >
                            bestArmyResidentPixelsSaved + expectedResidencyComparisonEpsilon ||
                        (Math.Abs(
                             armyResidentPixelsSaved -
                             bestArmyResidentPixelsSaved) <= expectedResidencyComparisonEpsilon &&
                         proposedExpectedArmyDrawCallsEliminated >
                             bestExpectedArmyDrawCallsEliminated +
                             expectedDrawComparisonEpsilon) ||
                        (Math.Abs(
                             armyResidentPixelsSaved -
                             bestArmyResidentPixelsSaved) <= expectedResidencyComparisonEpsilon &&
                         Math.Abs(
                             proposedExpectedArmyDrawCallsEliminated -
                             bestExpectedArmyDrawCallsEliminated) <=
                             expectedDrawComparisonEpsilon &&
                         pixelsSaved > bestPixelsSaved) ||
                        (Math.Abs(
                             armyResidentPixelsSaved -
                             bestArmyResidentPixelsSaved) <= expectedResidencyComparisonEpsilon &&
                         Math.Abs(
                             proposedExpectedArmyDrawCallsEliminated -
                             bestExpectedArmyDrawCallsEliminated) <=
                             expectedDrawComparisonEpsilon &&
                         pixelsSaved == bestPixelsSaved &&
                         proposedAffinity > bestAffinity) ||
                        (Math.Abs(
                             armyResidentPixelsSaved -
                             bestArmyResidentPixelsSaved) <= expectedResidencyComparisonEpsilon &&
                         Math.Abs(
                             proposedExpectedArmyDrawCallsEliminated -
                             bestExpectedArmyDrawCallsEliminated) <=
                             expectedDrawComparisonEpsilon &&
                         pixelsSaved == bestPixelsSaved &&
                         proposedAffinity == bestAffinity &&
                         entry.Value > bestPairWeight);
                    if (!isBetter)
                        continue;

                    bestPair = pair;
                    bestCombined = combined;
                    bestAffinity = proposedAffinity;
                    bestArmyResidentPixelsSaved = armyResidentPixelsSaved;
                    bestExpectedArmyDrawCallsEliminated =
                        proposedExpectedArmyDrawCallsEliminated;
                    bestPixelsSaved = pixelsSaved;
                    bestPairWeight = entry.Value;
                }

                if (bestPair == null || bestCombined == null)
                    break;

                var selected = bestPair.Value;
                working[selected.FirstBatchId] = bestCombined;
                working.RemoveAt(selected.SecondBatchId);
                state.MergeAwareBatchCoalescesAccepted++;
                state.MergeAwareBatchCoalescePixelsSaved = checked(
                    state.MergeAwareBatchCoalescePixelsSaved +
                    Math.Max(0, bestPixelsSaved));
                state.MergeAwareAffinityEliminationsGained +=
                    bestAffinity - baselineAffinity;
                currentExpectedArmyDrawCallsEliminated =
                    bestExpectedArmyDrawCallsEliminated;
            }
        }

        private static int CalculateMergeAffinityScoreWithMerge(
            IReadOnlyList<List<AtlasCandidate>> batches,
            int leftIndex,
            int rightIndex,
            IReadOnlyList<MergeAffinityGroup> affinityGroups)
        {
            var batchByMesh = BuildBatchIndexByMesh(batches);
            foreach (var candidate in batches[rightIndex])
                batchByMesh[candidate.Key] = leftIndex;

            var score = 0;
            foreach (var group in affinityGroups)
                score += CalculateMergeAffinityContribution(group, batchByMesh);

            return score;
        }

        private static bool CanEarnMergeDrawCredit(string? embeddedRigidPath)
            => string.IsNullOrWhiteSpace(embeddedRigidPath);

        private static bool CanEarnMergeDrawCredit(AtlasCandidate candidate)
            => candidate.Usages.All(usage =>
                CanEarnMergeDrawCredit(usage.EmbeddedRigidPath));

        private static MergeAffinityIdentity BuildMergeAffinityIdentity(
            string geometryPath,
            int lodIndex,
            string rmvIdentity,
            string materialIdentity)
            => new(
                geometryPath,
                lodIndex,
                rmvIdentity,
                materialIdentity);

        private static MergeAffinityIdentity BuildMergeAffinityIdentity(
            BatchState state,
            AtlasCandidate candidate)
            => BuildMergeAffinityIdentity(
                candidate.Key.GeometryPath,
                candidate.Key.LodIndex,
                GetRmvMergeIdentity(candidate.Model),
                BuildMergeAffinityMaterialIdentity(state, candidate));

        private static List<MergeAffinityGroup> BuildMergeAffinityGroups(
            BatchState state,
            IEnumerable<AtlasCandidate> candidates)
            => BuildMergeAffinityGroups(state, candidates, recordDiagnostics: true);

        private static List<MergeAffinityGroup> BuildMergeAffinityGroups(
            BatchState state,
            IEnumerable<AtlasCandidate> candidates,
            bool recordDiagnostics = true)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            var result = new List<MergeAffinityGroup>();

            // Group by the material state that would remain after a safe texture rewrite.
            // This deliberately admits only texture-only counterfactuals; shader and parameter
            // differences remain separate. The value gate still decides whether the resulting
            // atlas residency is worth accepting.
            var prepared = candidates
                .Where(CanEarnMergeDrawCredit)
                .Where(candidate => !HasUnrewritableMaterialConsumerAtlasConflict(state, candidate))
                .Select(candidate => new MergeAffinityCandidateInfo(
                    candidate,
                    GetRmvMergeIdentity(candidate.Model),
                    BuildMergeAffinityMaterialIdentity(state, candidate),
                    GetMaterialMergeDiagnosticSnapshot(
                        state,
                        candidate.MaterialPath,
                        candidate.MaterialDocument)))
                .ToList();

            var buckets = prepared
                .GroupBy(info => new MergeAffinityBucketIdentity(
                    info.Candidate.Key.GeometryPath,
                    info.Candidate.Key.LodIndex,
                    info.RmvIdentity,
                    info.MaterialSnapshot?.Shader ?? string.Empty,
                    info.MaterialSnapshot?.NonTextureIdentity ??
                        $"strict:{info.StrictMaterialIdentity}",
                    info.MaterialSnapshot != null));

            foreach (var bucket in buckets)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var current = new List<MergeAffinityCandidateInfo>();
                var currentVertexCount = 0;

                foreach (var info in bucket
                             .OrderBy(x => x.Candidate.Key.PartIndex)
                             .ThenBy(x => x.Candidate.RootVmdPath, StringComparer.OrdinalIgnoreCase))
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var candidate = info.Candidate;
                    var vertexCount = candidate.Model.Mesh.VertexList.Length;
                    if (vertexCount > ushort.MaxValue)
                        continue;

                    var canJoinCurrent = current.Count == 0;
                    var joinsProspectivePair = false;
                    if (!canJoinCurrent)
                    {
                        canJoinCurrent = true;
                        foreach (var existing in current)
                        {
                            state.CancellationToken.ThrowIfCancellationRequested();
                            // StrictMaterialIdentity is the material identity after the
                            // atlas rewrite modeled by BuildMergeAffinityMaterialIdentity.
                            // It must match exactly before a group can be admitted. The old
                            // logic grouped by pre-rewrite non-texture fields and then allowed
                            // a texture-only pair even when constant-vs-resolved channels (or
                            // XML texture-node structure) still produced different generated
                            // materials at execution time.
                            if (!existing.StrictMaterialIdentity.Equals(
                                    info.StrictMaterialIdentity,
                                    StringComparison.Ordinal))
                            {
                                canJoinCurrent = false;
                                break;
                            }

                            if (existing.MaterialSnapshot == null ||
                                info.MaterialSnapshot == null ||
                                existing.MaterialSnapshot.RenderingIdentity.Equals(
                                    info.MaterialSnapshot.RenderingIdentity,
                                    StringComparison.Ordinal))
                            {
                                continue;
                            }

                            if (!AreCounterfactuallyMergeCompatible(
                                    state,
                                    existing,
                                    info))
                            {
                                canJoinCurrent = false;
                                break;
                            }

                            joinsProspectivePair = true;
                        }
                    }

                    if (current.Count != 0 &&
                        (!canJoinCurrent ||
                         currentVertexCount + vertexCount > ushort.MaxValue))
                    {
                        if (current.Count > 1)
                        {
                            var group = CreateMergeAffinityGroup(state, current);
                            result.Add(group);
                            if (recordDiagnostics && group.ProspectiveTextureMergeDraws > 0)
                                state.ProspectiveMergeAffinityGroupsAdded++;
                        }

                        current = [];
                        currentVertexCount = 0;
                    }

                    current.Add(info);
                    currentVertexCount += vertexCount;
                    if (recordDiagnostics && joinsProspectivePair)
                    {
                        state.ProspectiveMergeAffinityPairs++;
                    }
                }

                if (current.Count > 1)
                {
                    var group = CreateMergeAffinityGroup(state, current);
                    result.Add(group);
                    if (recordDiagnostics && group.ProspectiveTextureMergeDraws > 0)
                        state.ProspectiveMergeAffinityGroupsAdded++;
                }
            }

            return result;
        }

        private static MergeAffinityGroup CreateMergeAffinityGroup(
            BatchState state,
            IReadOnlyList<MergeAffinityCandidateInfo> candidates)
        {
            var meshes = candidates
                .Select(info => info.Candidate.Key)
                .ToArray();
            var preAtlasMaterialIdentities = candidates
                .Select(GetPreAtlasMaterialIdentity)
                .ToArray();

            return new MergeAffinityGroup(
                meshes,
                CalculateProspectiveTextureMergeDraws(preAtlasMaterialIdentities),
                GetPreExistingStructuralMergePairs(state, meshes),
                preAtlasMaterialIdentities);
        }

        private static MergeAffinityGroup FilterMergeAffinityGroup(
            MergeAffinityGroup group,
            IReadOnlySet<MeshKey> candidateKeys)
        {
            var selected = group.Meshes
                .Select((mesh, index) => (mesh, index))
                .Where(entry => candidateKeys.Contains(entry.mesh))
                .ToArray();
            var meshes = selected
                .Select(entry => entry.mesh)
                .ToArray();
            var preAtlasMaterialIdentities = selected
                .Select(entry => group.PreAtlasMaterialIdentities[entry.index])
                .ToArray();

            return new MergeAffinityGroup(
                meshes,
                CalculateProspectiveTextureMergeDraws(preAtlasMaterialIdentities),
                FilterPreExistingStructuralMergePairs(group, meshes),
                preAtlasMaterialIdentities);
        }

        private static List<AtlasValueGateGroupPlan> BuildAtlasValueGateGroupPlans(
            BatchState state,
            IReadOnlyList<MergeAffinityGroup> contributingGroups,
            IReadOnlyDictionary<MeshKey, AtlasCandidate> candidateByKey,
            IReadOnlySet<MeshKey> batchKeys)
        {
            var plans = new List<AtlasValueGateGroupPlan>();
            var atomicFamilies = state.LodAwareAtlasFamilies
                .Where(family =>
                    family.Count >= 2 &&
                    family.IsSubsetOf(batchKeys) &&
                    family.All(candidateByKey.ContainsKey))
                .Select(family => family.ToHashSet())
                .OrderBy(
                    family => family.Min(key => key.ToString()),
                    StringComparer.Ordinal)
                .ToList();
            var remainingGroupIndexes = new HashSet<int>(
                Enumerable.Range(0, contributingGroups.Count));

            while (remainingGroupIndexes.Count != 0)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var firstGroupIndex = remainingGroupIndexes
                    .OrderBy(index => index)
                    .First();
                remainingGroupIndexes.Remove(firstGroupIndex);

                var componentGroupIndexes = new List<int> { firstGroupIndex };
                var componentKeys = contributingGroups[firstGroupIndex].Meshes
                    .Where(batchKeys.Contains)
                    .ToHashSet();
                var componentFamilyIndexes = new HashSet<int>();
                var changed = true;
                while (changed)
                {
                    changed = false;
                    for (var familyIndex = 0;
                         familyIndex < atomicFamilies.Count;
                         familyIndex++)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        if (componentFamilyIndexes.Contains(familyIndex) ||
                            !atomicFamilies[familyIndex].Overlaps(componentKeys))
                        {
                            continue;
                        }

                        componentFamilyIndexes.Add(familyIndex);
                        componentKeys.UnionWith(atomicFamilies[familyIndex]);
                        changed = true;
                    }

                    foreach (var groupIndex in remainingGroupIndexes.ToArray())
                    {
                        if (!contributingGroups[groupIndex].Meshes
                                .Any(componentKeys.Contains))
                        {
                            continue;
                        }

                        remainingGroupIndexes.Remove(groupIndex);
                        componentGroupIndexes.Add(groupIndex);
                        componentKeys.UnionWith(contributingGroups[groupIndex].Meshes);
                        changed = true;
                    }
                }

                var planGroups = componentGroupIndexes
                    .Select(index => FilterMergeAffinityGroup(
                        contributingGroups[index],
                        componentKeys))
                    .Where(group => group.Meshes.Length >= 2)
                    .ToList();
                var candidates = componentKeys
                    .Where(candidateByKey.ContainsKey)
                    .Select(key => candidateByKey[key])
                    .OrderBy(candidate => BuildAtlasPlanningOrderKey(candidate), StringComparer.Ordinal)
                    .ThenBy(candidate => candidate.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                    .ThenBy(candidate => candidate.Key.LodIndex)
                    .ThenBy(candidate => candidate.Key.PartIndex)
                    .ToList();
                if (candidates.Count < 2)
                    continue;

                var componentAtomicFamilies = componentFamilyIndexes
                    .OrderBy(index => index)
                    .Select(index => atomicFamilies[index]
                        .OrderBy(key => key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(key => key.LodIndex)
                        .ThenBy(key => key.PartIndex)
                        .ToArray())
                    .ToArray();
                plans.Add(
                    new AtlasValueGateGroupPlan(
                        planGroups[0],
                        candidates,
                        componentAtomicFamilies,
                        planGroups));
            }

            return plans;
        }

        private static int GetAtlasValueGatePlanProspectiveTextureMergeDraws(
            AtlasValueGateGroupPlan plan)
            => CalculateProspectiveTextureMergeDraws(plan.AffinityGroups);

        private static List<MergeAffinityGroup> FilterAtlasValueGatePlanGroups(
            AtlasValueGateGroupPlan plan,
            IReadOnlySet<MeshKey> candidateKeys)
            => plan.AffinityGroups
                .Select(group => FilterMergeAffinityGroup(group, candidateKeys))
                .Where(group => group.Meshes.Length >= 2)
                .ToList();

        private static AtlasValueGateGroupPlan CreateAtlasValueGateSubPlan(
            AtlasValueGateGroupPlan source,
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlySet<MeshKey> candidateKeys,
            IReadOnlyList<MeshKey[]>? atomicFamilies = null)
        {
            var groups = FilterAtlasValueGatePlanGroups(source, candidateKeys);
            var representative = groups.FirstOrDefault() ??
                FilterMergeAffinityGroup(source.Group, candidateKeys);
            return new AtlasValueGateGroupPlan(
                representative,
                candidates.ToList(),
                atomicFamilies ??
                GetCompleteAtlasFamilySubsets(source.AtomicFamilies, candidateKeys),
                groups);
        }

        private static string GetPreAtlasMaterialIdentity(
            MergeAffinityCandidateInfo info)
            => info.MaterialSnapshot?.RenderingIdentity ??
               $"strict:{info.StrictMaterialIdentity}";

        private static int CalculateProspectiveTextureMergeDraws(
            IReadOnlyList<string> preAtlasMaterialIdentities)
        {
            if (preAtlasMaterialIdentities.Count < 2)
                return 0;

            // Every MergeAffinityGroup shares one strict post-atlas material identity. The
            // delta is therefore the number of strict pre-atlas material groups that the
            // texture-compatible grouping collapses beyond the first group.
            var strictPreAtlasGroupCount = preAtlasMaterialIdentities
                .Distinct(StringComparer.Ordinal)
                .Count();
            return Math.Max(0, strictPreAtlasGroupCount - 1);
        }

        private static int CalculateProspectiveTextureMergeDraws(
            IReadOnlyList<MergeAffinityGroup> groups)
            => groups.Sum(group => group.ProspectiveTextureMergeDraws);

        private static bool AreCounterfactuallyMergeCompatible(
            BatchState state,
            MergeAffinityCandidateInfo left,
            MergeAffinityCandidateInfo right)
        {
            if (left.MaterialSnapshot == null ||
                right.MaterialSnapshot == null ||
                !left.MaterialSnapshot.Shader.Equals(
                    right.MaterialSnapshot.Shader,
                    StringComparison.OrdinalIgnoreCase) ||
                !left.MaterialSnapshot.NonTextureIdentity.Equals(
                    right.MaterialSnapshot.NonTextureIdentity,
                    StringComparison.Ordinal))
            {
                return false;
            }

            var differingSlots = GetDifferingMaterialTextureSlots(
                    state,
                    left.MaterialSnapshot,
                    right.MaterialSnapshot).ToList();
            if (differingSlots.Count == 0)
                return true;

            var classification = ClassifyCounterfactualTexturePair(
                state,
                left.MaterialSnapshot,
                right.MaterialSnapshot,
                differingSlots,
                out _,
                allowDifferentUniformMaskConstants:
                    (left.Candidate.RequiresMaskAtlas || right.Candidate.RequiresMaskAtlas));
            return classification.Equals(
                       "Atlasable differing texture channels",
                       StringComparison.Ordinal) ||
                   classification.Equals(
                       "Uniform-constant equivalence",
                       StringComparison.Ordinal);
        }

        private static string BuildMergeAffinityMaterialIdentity(
            BatchState state,
            AtlasCandidate candidate)
        {
            var material = new XmlDocument();
            material.LoadXml(candidate.MaterialDocument.OuterXml);

            foreach (var channel in AtlasChannels)
            {
                if (IsCandidateIgnoredTextureSlot(candidate, channel.Slot))
                {
                    RemoveTextureSlot(material, channel.Slot);
                    continue;
                }

                // Both resolved and uniform-constant channels can receive the same final
                // atlas path when this candidate shares a batch with a resolved source.
                // Treating constants as preserved here admits a false prospective merge:
                // the planner sees a shared material identity, but ProcessBatch gives the
                // two candidates different generated-material identities. Constant-only
                // batches are safe as well because ProcessBatch canonicalizes equal
                // uniform constants to the same source path.
                if (candidate.ResolvedChannels.Contains(channel.Slot) ||
                    candidate.ConstantChannels.ContainsKey(channel.Slot))
                {
                    SetTexturePath(
                        material,
                        channel.Slot,
                        $"__asset_editor_shared_atlas_{channel.Slot}__");
                }
            }

            return GetMaterialRenderingIdentity(material);
        }

        private static Dictionary<MeshKey, int> BuildBatchIndexByMesh(
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            var result = new Dictionary<MeshKey, int>();
            for (var batchIndex = 0; batchIndex < batches.Count; batchIndex++)
            {
                foreach (var candidate in batches[batchIndex])
                    result[candidate.Key] = batchIndex;
            }
            return result;
        }

        private static int CalculateMergeAffinityContribution(
            MergeAffinityGroup group,
            IReadOnlyDictionary<MeshKey, int> batchByMesh)
        {
            var score = 0;
            foreach (var batch in group.Meshes
                         .Where(batchByMesh.ContainsKey)
                         .GroupBy(mesh => batchByMesh[mesh]))
            {
                var meshes = batch.ToArray();
                if (meshes.Length < 2)
                    continue;

                // Structural merges already collapse each connected pre-atlas component.
                // Only the remaining component-to-component savings are attributable to
                // atlas placement.
                score += Math.Max(
                    0,
                    CountStructuralMergeComponents(
                        meshes,
                        group.PreExistingStructuralMergePairs) - 1);
            }

            return score;
        }

        private static int CountStructuralMergeComponents(
            IReadOnlyList<MeshKey> meshes,
            IReadOnlyCollection<string> preExistingPairs)
        {
            if (meshes.Count == 0)
                return 0;

            var labels = BuildStructuralMergeComponentLabels(meshes, preExistingPairs);
            return labels.Distinct().Count();
        }

        private static int[] BuildStructuralMergeComponentLabels(
            IReadOnlyList<MeshKey> meshes,
            IReadOnlyCollection<string> preExistingPairs)
        {
            var parent = Enumerable.Range(0, meshes.Count).ToArray();

            int Find(int index)
            {
                while (parent[index] != index)
                {
                    parent[index] = parent[parent[index]];
                    index = parent[index];
                }

                return index;
            }

            void Union(int left, int right)
            {
                var leftRoot = Find(left);
                var rightRoot = Find(right);
                if (leftRoot != rightRoot)
                    parent[rightRoot] = leftRoot;
            }

            for (var left = 0; left < meshes.Count; left++)
            {
                for (var right = left + 1; right < meshes.Count; right++)
                {
                    if (preExistingPairs.Contains(
                            BuildStructuralMergePairKey(
                                meshes[left].GeometryPath,
                                meshes[left].LodIndex,
                                meshes[left].PartIndex,
                                meshes[right].PartIndex)))
                    {
                        Union(left, right);
                    }
                }
            }

            var componentByRoot = new Dictionary<int, int>();
            var labels = new int[meshes.Count];
            for (var index = 0; index < meshes.Count; index++)
            {
                var root = Find(index);
                if (!componentByRoot.TryGetValue(root, out var component))
                {
                    component = componentByRoot.Count;
                    componentByRoot[root] = component;
                }

                labels[index] = component;
            }

            return labels;
        }

        private static int[] CollapseStructuralMergeCounts(
            IReadOnlyList<MeshKey> meshes,
            IReadOnlyList<int> counts,
            IReadOnlyCollection<string> preExistingPairs)
        {
            var labels = BuildStructuralMergeComponentLabels(meshes, preExistingPairs);
            var collapsed = new int[labels.Distinct().Count()];
            for (var index = 0; index < labels.Length; index++)
                collapsed[labels[index]] = Math.Max(collapsed[labels[index]], counts[index]);

            return collapsed;
        }

        private static double[] CollapseStructuralMergeCounts(
            IReadOnlyList<MeshKey> meshes,
            IReadOnlyList<double> counts,
            IReadOnlyCollection<string> preExistingPairs)
        {
            var labels = BuildStructuralMergeComponentLabels(meshes, preExistingPairs);
            var collapsed = new double[labels.Distinct().Count()];
            for (var index = 0; index < labels.Length; index++)
                collapsed[labels[index]] = Math.Max(collapsed[labels[index]], counts[index]);

            return collapsed;
        }

        private static int CalculateMergeAffinityScore(
            IReadOnlyList<List<AtlasCandidate>> batches,
            IReadOnlyList<MergeAffinityGroup> affinityGroups)
        {
            var batchByMesh = BuildBatchIndexByMesh(batches);
            var score = 0;

            foreach (var group in affinityGroups)
                score += CalculateMergeAffinityContribution(group, batchByMesh);

            return score;
        }

        private static Dictionary<
            MeshKey,
            Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
            BuildExpectedArmyEntitiesByMesh(
                ArmyResidencyModel? model,
                IEnumerable<AtlasCandidate> candidates,
                IReadOnlyDictionary<MeshKey, HashSet<string>> rootsByMesh,
                CancellationToken cancellationToken = default)
        {
            var result = new Dictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>();
            if (model == null)
                return result;

            foreach (var candidate in candidates
                         .GroupBy(candidate => candidate.Key)
                         .Select(group => group.First()))
            {
                cancellationToken.ThrowIfCancellationRequested();
                var wsModels = candidate.Usages
                    .Select(usage => Normalize(usage.AssetPath))
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                if (wsModels.Length == 0)
                    continue;

                var fallbackRoots = rootsByMesh.TryGetValue(
                        candidate.Key,
                        out var candidateRoots)
                    ? candidateRoots
                        .Select(Normalize)
                        .Where(path => path.Length != 0)
                        .ToArray()
                    : Array.Empty<string>();
                var relevantUnitIds = GetRelevantArmyUnitIds(
                    model,
                    wsModels,
                    fallbackRoots);
                if (relevantUnitIds.Count == 0)
                    continue;

                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>? byCategory = null;
                foreach (var unitId in relevantUnitIds)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    if (!model.CategoryByUnit.TryGetValue(unitId, out var category))
                        continue;

                    double expectedRenderedEntities = 0;
                    if (model.ExpectedWsModelOccurrencesByUnit.TryGetValue(
                            unitId,
                            out var expectedOccurrences))
                    {
                        foreach (var wsModelPath in wsModels)
                        {
                            if (!expectedOccurrences.ByWsModel.TryGetValue(
                                    wsModelPath,
                                    out var occurrencesByRole))
                            {
                                continue;
                            }

                            foreach (var (role, expectedOccurrencesPerEntity) in occurrencesByRole)
                            {
                                var entityCount = Math.Max(
                                    1,
                                    model.EntityCountByUnitAndRole
                                        .GetValueOrDefault(unitId)?
                                        .GetValueOrDefault(role, 1) ?? 1);
                                expectedRenderedEntities +=
                                    Math.Clamp(expectedOccurrencesPerEntity, 0.0, 1.0) *
                                    entityCount;
                            }
                        }
                    }
                    else
                    {
                        // Preserve the old conservative behavior when probability data could
                        // not be built for a resolved unit.
                        foreach (var root in fallbackRoots)
                        {
                            if (model.UnitsByVmd.TryGetValue(root, out var unitsForVmd) &&
                                unitsForVmd.TryGetValue(category, out var fallbackUnits) &&
                                fallbackUnits.Contains(unitId))
                            {
                                expectedRenderedEntities = Math.Max(
                                    1,
                                    model.EntityCountByUnit.GetValueOrDefault(unitId, 1));
                                break;
                            }
                        }
                    }

                    if (expectedRenderedEntities <= 0)
                        continue;

                    byCategory ??=
                        new Dictionary<
                            Wh3ArmyUnitCategory,
                            Dictionary<string, double>>();
                    if (!byCategory.TryGetValue(category, out var expectedByUnit))
                    {
                        expectedByUnit =
                            new Dictionary<string, double>(
                                StringComparer.OrdinalIgnoreCase);
                        byCategory[category] = expectedByUnit;
                    }

                    expectedByUnit[unitId] = expectedRenderedEntities;
                }

                if (byCategory != null)
                    result[candidate.Key] = byCategory;
            }

            return result;
        }

        private static double CalculateExpectedConfigurationMergeDrawSavings(
            double[] probabilities,
            int[][] coRenderedCountsByConfiguration,
            int entityCount)
        {
            if (entityCount <= 0 ||
                probabilities.Length == 0 ||
                coRenderedCountsByConfiguration.Length == 0)
            {
                return 0;
            }

            var configurationCount = Math.Min(
                probabilities.Length,
                coRenderedCountsByConfiguration.Length);
            double total = 0;
            for (var index = 0; index < configurationCount; index++)
            {
                var probability = probabilities[index];
                if (probability <= 0)
                    continue;

                var positiveCounts = coRenderedCountsByConfiguration[index]
                    .Where(count => count > 0)
                    .ToArray();
                if (positiveCounts.Length < 2)
                    continue;

                total += probability *
                    entityCount *
                    positiveCounts.Min() *
                    (positiveCounts.Length - 1);
            }

            return total;
        }

        private static double CalculateExpectedArmyDrawCallsEliminated(
            BatchState state,
            IReadOnlyDictionary<MeshKey, int> batchByMesh,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh)
        {
            var model = state.ArmyResidencyModel;
            if (model == null)
                return 0;

            state.CancellationToken.ThrowIfCancellationRequested();

            var drawsByCulture = model.UnitsByCultureAndCategory.Keys.ToDictionary(
                culture => culture,
                _ => 0.0,
                StringComparer.OrdinalIgnoreCase);

            foreach (var group in affinityGroups)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                foreach (var colocatedMeshes in group.Meshes
                             .Where(batchByMesh.ContainsKey)
                             .GroupBy(mesh => batchByMesh[mesh]))
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var meshes = colocatedMeshes.ToArray();
                    if (meshes.Length < 2)
                        continue;

                    var structuralComponentCount =
                        CountStructuralMergeComponents(
                            meshes,
                            group.PreExistingStructuralMergePairs);
                    if (structuralComponentCount < 2)
                        continue;

                    var lodIndex = meshes[0].LodIndex;
                    if (model.Scenario.GetLodProbability(lodIndex) <= 0)
                        continue;

                    var assetPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var mesh in meshes)
                    {
                        if (!state.Usages.TryGetValue(mesh, out var usages))
                            continue;

                        foreach (var assetPath in usages
                                     .Select(usage => Normalize(usage.AssetPath))
                                     .Where(path => path.Length != 0))
                        {
                            assetPaths.Add(assetPath);
                        }
                    }

                    var relevantUnitIds = GetRelevantArmyUnitIds(
                        model,
                        assetPaths,
                        Array.Empty<string>());
                    // Keep the expected-entity fallback conservative if a candidate's asset
                    // path was not present in the resolved dependency index.
                    foreach (var mesh in meshes)
                    {
                        if (!expectedEntitiesByMesh.TryGetValue(mesh, out var byCategory))
                            continue;

                        foreach (var expectedByUnit in byCategory.Values)
                            relevantUnitIds.UnionWith(expectedByUnit.Keys);
                    }

                    var relevantCultures = GetRelevantArmyCultures(
                        model,
                        assetPaths,
                        Array.Empty<string>(),
                        relevantUnitIds);
                    if (relevantUnitIds.Count == 0 || relevantCultures.Count == 0)
                        continue;

                    foreach (var culture in relevantCultures)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        if (!model.UnitsByCultureAndCategory.TryGetValue(
                                culture,
                                out var unitsByCategory))
                        {
                            continue;
                        }

                        foreach (var (category, slotCount) in model.Scenario.ArmySlotTemplate)
                        {
                            state.CancellationToken.ThrowIfCancellationRequested();
                            if (!unitsByCategory.TryGetValue(category, out var cultureUnits))
                                continue;

                            var population = cultureUnits.Count;
                            if (population == 0)
                                continue;

                            double eliminatedDrawsAcrossResolvedUnits = 0;
                            foreach (var unitId in EnumerateRelevantArmyUnitIds(
                                         cultureUnits,
                                         relevantUnitIds))
                            {
                                state.CancellationToken.ThrowIfCancellationRequested();
                                var usedExactConfigurations = false;
                                if (model.VisualConfigurationsByUnitAndRole.TryGetValue(
                                        unitId,
                                        out var configurationsByRole) &&
                                    configurationsByRole.Count != 0)
                                {
                                    usedExactConfigurations = true;
                                    foreach (var (role, configurations) in configurationsByRole)
                                    {
                                        state.CancellationToken.ThrowIfCancellationRequested();
                                        var entityCount = Math.Max(
                                            1,
                                            model.EntityCountByUnitAndRole
                                                .GetValueOrDefault(unitId)?
                                                .GetValueOrDefault(role, 1) ?? 1);

                                        var configurationProbabilities = new List<double>();
                                        var coRenderedCountsByConfiguration = new List<int[]>();
                                        foreach (var configuration in configurations)
                                        {
                                            state.CancellationToken.ThrowIfCancellationRequested();
                                            if (configuration.Probability <= 0)
                                                continue;

                                            var coRenderedCounts = new int[meshes.Length];
                                            for (var meshIndex = 0; meshIndex < meshes.Length; meshIndex++)
                                            {
                                                var mesh = meshes[meshIndex];
                                                if (!state.Usages.TryGetValue(mesh, out var usages))
                                                    continue;

                                                coRenderedCounts[meshIndex] = usages
                                                    .Select(usage => Normalize(usage.AssetPath))
                                                    .Where(path => path.Length != 0)
                                                    .Distinct(StringComparer.OrdinalIgnoreCase)
                                                    .Sum(path => configuration.WsModelOccurrences
                                                        .GetValueOrDefault(path));
                                            }

                                            var componentCounts =
                                                CollapseStructuralMergeCounts(
                                                    meshes,
                                                    coRenderedCounts,
                                                    group.PreExistingStructuralMergePairs);

                                            configurationProbabilities.Add(configuration.Probability);
                                            coRenderedCountsByConfiguration.Add(componentCounts);
                                        }

                                        eliminatedDrawsAcrossResolvedUnits +=
                                            CalculateExpectedConfigurationMergeDrawSavings(
                                                configurationProbabilities.ToArray(),
                                                coRenderedCountsByConfiguration.ToArray(),
                                                entityCount);
                                    }
                                }

                                if (usedExactConfigurations)
                                    continue;

                                var expectedCountsByMesh = new double[meshes.Length];
                                for (var meshIndex = 0; meshIndex < meshes.Length; meshIndex++)
                                {
                                    var mesh = meshes[meshIndex];
                                    if (!expectedEntitiesByMesh.TryGetValue(mesh, out var meshUnits) ||
                                        !meshUnits.TryGetValue(category, out var expectedByUnit) ||
                                        !expectedByUnit.TryGetValue(unitId, out var expectedEntities) ||
                                        expectedEntities <= 0)
                                    {
                                        continue;
                                    }

                                    expectedCountsByMesh[meshIndex] = expectedEntities;
                                }

                                var expectedCounts = CollapseStructuralMergeCounts(
                                    meshes,
                                    expectedCountsByMesh,
                                    group.PreExistingStructuralMergePairs)
                                    .Where(count => count > 0)
                                    .ToList();

                                if (expectedCounts.Count >= 2)
                                {
                                    eliminatedDrawsAcrossResolvedUnits +=
                                        expectedCounts.Min() * (expectedCounts.Count - 1);
                                }
                            }

                            if (eliminatedDrawsAcrossResolvedUnits <= 0)
                                continue;

                            drawsByCulture[culture] +=
                                model.Scenario.GetLodWeightedDrawSavings(
                                    lodIndex,
                                    slotCount *
                                    (eliminatedDrawsAcrossResolvedUnits / population));
                        }
                    }
                }
            }

            // Draw savings are additive across the two sides. Unrelated opponent cultures have
            // zero savings for culture-local pack assets; mirror/shared-asset opponents add only
            // when their own culture actually uses the affected meshes.
            return CombineBattleDrawSavings(
                drawsByCulture,
                model.PlayerCultureWeights,
                model.OpponentCultureWeights);
        }

        private static double CalculateExpectedArmyDrawCallsEliminatedForBatches(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            if (!state.MergeCompatibleMeshesEnabled ||
                state.ArmyResidencyModel == null ||
                batches.Count == 0)
            {
                return 0;
            }

            var candidates = batches
                .SelectMany(batch => batch)
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .ToList();
            if (candidates.Count == 0)
                return 0;

            // This is a final accounting pass, not another planning pass. Suppress the
            // prospective-affinity diagnostics so the report does not count the same groups
            // a second time merely because the post-value-gate total is being measured.
            var affinityGroups = BuildMergeAffinityGroups(
                state,
                candidates,
                recordDiagnostics: false);
            if (affinityGroups.Count == 0)
                return 0;

            var rootsByMesh = BuildCandidateRootVmdPaths(state, candidates);
            var expectedArmyEntitiesByMesh = BuildExpectedArmyEntitiesByMesh(
                state.ArmyResidencyModel,
                candidates,
                rootsByMesh,
                state.CancellationToken);
            return CalculateExpectedArmyDrawCallsEliminated(
                state,
                BuildBatchIndexByMesh(batches),
                affinityGroups,
                expectedArmyEntitiesByMesh);
        }

        private static double CombineBattleDrawSavings(
            IReadOnlyDictionary<string, double> drawsByCulture,
            IReadOnlyDictionary<string, double> playerCultureWeights,
            IReadOnlyDictionary<string, double> opponentCultureWeights)
            => GetWeightedCultureAverage(drawsByCulture, playerCultureWeights) +
               GetWeightedCultureAverage(drawsByCulture, opponentCultureWeights);

        private static AtlasBatchCoverage CalculateAtlasBatchCoverage(
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh)
        {
            var affectedUnits = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            double expectedRenderedEntities = 0;

            foreach (var candidate in candidates
                         .GroupBy(candidate => candidate.Key)
                         .Select(group => group.First()))
            {
                if (!expectedEntitiesByMesh.TryGetValue(
                        candidate.Key,
                        out var expectedByCategory))
                {
                    continue;
                }

                foreach (var (category, expectedByUnit) in expectedByCategory)
                {
                    foreach (var (unitId, expectedEntities) in expectedByUnit)
                    {
                        if (expectedEntities <= 0)
                            continue;

                        // Include the category in the identity. The same DB unit key can
                        // legitimately appear in more than one visual slot in malformed or
                        // synthetic data, and those are separate residency consumers.
                        affectedUnits.Add($"{category}\u001f{unitId}");
                        expectedRenderedEntities += expectedEntities;
                    }
                }
            }

            return new AtlasBatchCoverage(
                affectedUnits,
                expectedRenderedEntities);
        }

        private static List<List<AtlasCandidate>> OrderBatchesByCoverageEfficiency(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            return batches
                .Select((batch, originalIndex) =>
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var coverage = CalculateAtlasBatchCoverage(
                        batch,
                        expectedEntitiesByMesh);
                    var affinity = CalculateMergeAffinityScore(
                        [batch],
                        affinityGroups);
                    var scenarioResolved = IsAtlasValueBatchScenarioResolved(state, batch);
                    var scenarioAllowed = IsAtlasValueCandidateAllowedForMode(
                        state.AtlasAllVmdsEnabled,
                        scenarioResolved);
                    var expectedNetBcnBytes = double.PositiveInfinity;
                    if (scenarioAllowed &&
                        TryEstimateIncrementalAtlasResidency(
                            state,
                            batch,
                            out var residency))
                    {
                        expectedNetBcnBytes = residency.ExpectedArmyNetBcnBytes;
                    }

                    var coveragePerScenarioMiB =
                        GetAffectedUnitsPerScenarioMiB(
                            coverage.AffectedUnitCount,
                            expectedNetBcnBytes);
                    var stableKey = string.Join(
                        "\u001f",
                        batch
                            .Select(candidate => candidate.Key.ToString())
                            .OrderBy(key => key, StringComparer.OrdinalIgnoreCase));
                    return (
                        Batch: batch,
                        Coverage: coverage,
                        ScenarioAllowed: scenarioAllowed,
                        CoveragePerScenarioMiB: coveragePerScenarioMiB,
                        Affinity: affinity,
                        StableKey: stableKey,
                        OriginalIndex: originalIndex);
                })
                // Greedily spend the value-gate budget on the widest safe unit coverage per
                // scenario-estimated net BCn MiB. This is intentionally a priority heuristic,
                // not a relaxed acceptance rule: every selected batch still passes the full
                // draw/value/memory gate below.
                .OrderByDescending(entry => entry.ScenarioAllowed)
                .ThenByDescending(entry => entry.CoveragePerScenarioMiB)
                .ThenByDescending(entry => entry.Coverage.AffectedUnitCount)
                .ThenByDescending(entry => entry.Coverage.ExpectedRenderedEntities)
                .ThenByDescending(entry => entry.Affinity)
                .ThenBy(entry => entry.StableKey, StringComparer.OrdinalIgnoreCase)
                .ThenBy(entry => entry.OriginalIndex)
                .Select(entry => entry.Batch)
                .ToList();
        }

        private static double GetAffectedUnitsPerScenarioMiB(
            int affectedUnitCount,
            double expectedNetBcnBytes)
        {
            if (affectedUnitCount <= 0 ||
                double.IsPositiveInfinity(expectedNetBcnBytes) ||
                double.IsNaN(expectedNetBcnBytes))
            {
                return 0;
            }

            var expectedNetMiB = Math.Max(
                0.0,
                expectedNetBcnBytes / (1024.0 * 1024.0));
            return expectedNetMiB <= AtlasValueGateExpectedDrawEpsilon
                ? double.MaxValue
                : affectedUnitCount / expectedNetMiB;
        }

        private static string FormatAffectedUnitsPerScenarioMiB(
            int affectedUnitCount,
            double expectedNetBcnBytes)
        {
            if (affectedUnitCount <= 0)
                return "0";

            if (double.IsPositiveInfinity(expectedNetBcnBytes) ||
                double.IsNaN(expectedNetBcnBytes))
            {
                return "N/A";
            }

            var expectedNetMiB = expectedNetBcnBytes / (1024.0 * 1024.0);
            return expectedNetMiB <= AtlasValueGateExpectedDrawEpsilon
                ? "retiring"
                : $"{affectedUnitCount / expectedNetMiB:N3}";
        }

        private static HashSet<string> GetAtlasValueGateCandidateTexturePaths(
            IEnumerable<AtlasCandidate> candidates)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var candidate in candidates)
            {
                foreach (var channel in AtlasChannels)
                {
                    if (!candidate.ResolvedChannels.Contains(channel.Slot) &&
                        !candidate.ConstantChannels.ContainsKey(channel.Slot))
                    {
                        continue;
                    }

                    var texturePath = Normalize(
                        GetTexturePath(candidate.MaterialDocument, channel.Slot));
                    if (texturePath.Length != 0 && !IsTexturePlaceholder(texturePath))
                        result.Add(texturePath);
                }
            }

            return result;
        }

        private static List<List<AtlasCandidate>> FilterBatchesForMergeValue(
            BatchState state,
            IReadOnlyList<List<AtlasCandidate>> batches)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            if (batches.Count == 0)
                return [];

            var allCandidates = batches
                .SelectMany(batch => batch)
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .ToList();
            var candidateTexturePaths = state.AtlasValueGateCandidateTexturePathsInitialized
                ? state.AtlasValueGateCandidateTexturePaths
                : GetAtlasValueGateCandidateTexturePaths(allCandidates);

            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                item: "Indexing source texture consumers");
            state.AtlasValueGateSourceTextureIndex ??=
                BuildAtlasValueGateSourceTextureIndex(state, candidateTexturePaths);

            HashSet<MeshKey> nonAtomicStructuralCandidates;
            if (state.LodAwareAtlasPlanningEnabled)
            {
                nonAtomicStructuralCandidates =
                    GetNonAtomicStructuralCandidateKeys(state, batches);
                foreach (var candidate in allCandidates
                             .Where(candidate => nonAtomicStructuralCandidates.Contains(candidate.Key)))
                {
                    RecordSkip(
                        state,
                        candidate.RootVmdPath,
                        candidate.Key,
                        candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        "LOD-aware atlas planning left a structural merge component unchanged " +
                        "because its complete component was not present in one atlas family or " +
                        "its post-atlas material variant was not atomic.");
                }
            }
            else
            {
                // Preserve the pre-existing opt-out behavior for callers that explicitly use
                // lodAwareAtlasPlanning=false: structural candidates remain untouched and are
                // merged later by the structural pass.
                var protectedStructuralCandidates = allCandidates
                    .Where(candidate => state.PreAtlasStructuralMergeMeshes.Contains(candidate.Key))
                    .ToList();
                foreach (var candidate in protectedStructuralCandidates)
                {
                    RecordSkip(
                        state,
                        candidate.RootVmdPath,
                        candidate.Key,
                        candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                        "Pre-atlas structural merge opportunity protected from atlas rewriting.");
                }

                state.AtlasProtectedStructuralMeshCount +=
                    protectedStructuralCandidates.Count;
                nonAtomicStructuralCandidates = protectedStructuralCandidates
                    .Select(candidate => candidate.Key)
                    .ToHashSet();
            }

            var eligibleBatches = batches
                .Select(batch => batch
                    .Where(candidate =>
                        !nonAtomicStructuralCandidates.Contains(candidate.Key))
                    .ToList())
                .Where(batch => batch.Count != 0)
                .ToList();
            allCandidates = eligibleBatches
                .SelectMany(batch => batch)
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .ToList();
            var candidateByKey = allCandidates.ToDictionary(candidate => candidate.Key);
            var affinityGroups = BuildMergeAffinityGroups(state, allCandidates);

            var rootsByMesh = BuildCandidateRootVmdPaths(state, allCandidates);
            var expectedEntitiesByMesh = BuildExpectedArmyEntitiesByMesh(
                state.ArmyResidencyModel,
                allCandidates,
                rootsByMesh,
                state.CancellationToken);
            var candidateCoverage = CalculateAtlasBatchCoverage(
                allCandidates,
                expectedEntitiesByMesh);
            state.AtlasValueGateCandidateAffectedUnitCount =
                candidateCoverage.AffectedUnitCount;
            var orderedBatches = OrderBatchesByCoverageEfficiency(
                state,
                eligibleBatches,
                affinityGroups,
                expectedEntitiesByMesh);
            state.AtlasValueGateCoverageOrderedBatchCount = orderedBatches.Count;
            var result = new List<List<AtlasCandidate>>();
            var pendingTextureMergeAttachments =
                new List<AtlasValueGatePendingTextureMergeAttachment>();
            var acceptedEconomicsStartIndex =
                state.AtlasValueGateAcceptedBatchEconomics.Count;

            for (var orderedBatchIndex = 0;
                 orderedBatchIndex < orderedBatches.Count;
                 orderedBatchIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    orderedBatchIndex + 1,
                    orderedBatches.Count,
                    $"Value gate batch {orderedBatchIndex + 1}");
                var originalBatch = orderedBatches[orderedBatchIndex];
                var batch = new List<AtlasCandidate>(originalBatch.Count);
                foreach (var candidate in originalBatch)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var scenarioResolved =
                        IsAtlasValueCandidateScenarioResolved(state, candidate);
                    if (!IsAtlasValueCandidateAllowedForMode(
                            state.AtlasAllVmdsEnabled,
                            scenarioResolved))
                    {
                        RecordSkip(
                            state,
                            candidate.RootVmdPath,
                            candidate.Key,
                            candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                            "Atlas value gate: gameplay/scenario relevance could not be " +
                            "resolved safely; gameplay-used mode leaves this asset unchanged.");
                        state.AtlasValueGateCandidatesRejected++;
                        state.AtlasValueGateUnresolvedCandidatesSkipped++;
                        continue;
                    }

                    batch.Add(candidate);
                }

                if (batch.Count < 2)
                    continue;

                var batchKeys = batch.Select(candidate => candidate.Key).ToHashSet();
                var contributingGroups = affinityGroups
                    .Select(group => FilterMergeAffinityGroup(group, batchKeys))
                    .Where(group => group.Meshes.Length >= 2)
                    .ToList();
                // A closed LOD family is one execution unit. In particular, a member that
                // contributes no same-LOD draw merge must not fall into the texture-only path
                // and be emitted as a second physical atlas batch. Expand the merge host plan
                // with all complete family members before any value-gate split occurs.
                var groupPlans = BuildAtlasValueGateGroupPlans(
                    state,
                    contributingGroups,
                    candidateByKey,
                    batchKeys);
                var contributingKeys = groupPlans
                    .SelectMany(plan => plan.Candidates)
                    .Select(candidate => candidate.Key)
                    .ToHashSet();

                var textureOnlyCandidates = batch
                    .Where(candidate => !contributingKeys.Contains(candidate.Key))
                    .ToList();
                if (TryAcceptTextureOnlyAtlasBatch(
                        state,
                        textureOnlyCandidates,
                        out var textureOnlyResidency,
                        out var textureOnlyRejectionReason))
                {
                    result.Add(textureOnlyCandidates);
                    RecordAtlasValueGateAccepted(
                        state,
                        textureOnlyCandidates,
                        textureOnlyResidency,
                        rawDrawsEliminated: 0,
                        expectedArmyDrawsEliminated: 0,
                        expectedEntitiesByMesh,
                        acceptanceKind: AtlasValueGateAcceptanceKind.TextureOnlyRetirement);
                }
                else
                {
                    var textureConsolidationAcceptances =
                        SelectTextureConsolidationCohorts(
                            state,
                            textureOnlyCandidates,
                            expectedEntitiesByMesh,
                            out var textureConsolidationRejectionReasons);
                    foreach (var acceptance in textureConsolidationAcceptances)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        result.Add(acceptance.Candidates);
                    }

                    var acceptedTextureConsolidationKeys =
                        textureConsolidationAcceptances
                            .SelectMany(acceptance => acceptance.Candidates)
                            .Select(candidate => candidate.Key)
                            .ToHashSet();
                    foreach (var candidate in textureOnlyCandidates)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        if (acceptedTextureConsolidationKeys.Contains(candidate.Key))
                            continue;

                        var rejectionReason =
                            textureConsolidationRejectionReasons.GetValueOrDefault(
                                candidate.Key,
                                "no viable texture-consolidation cohort remained.");
                        RecordSkip(
                            state,
                            candidate.RootVmdPath,
                            candidate.Key,
                            candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                            "Atlas value gate: this mesh does not contribute to a compatible " +
                            $"mesh merge; texture-only fallback rejected: {textureOnlyRejectionReason}; " +
                            $"texture-consolidation fallback rejected: {rejectionReason}");
                        state.AtlasValueGateCandidatesRejected++;
                    }
                }

                var trimmed = batch
                    .Where(candidate => contributingKeys.Contains(candidate.Key))
                    .ToList();
                if (trimmed.Count < 2)
                    continue;

                if (groupPlans.Count == 0)
                    continue;

                var standaloneAccepted = new List<AtlasValueGateAcceptedGroup>();
                var standaloneRejected = new List<AtlasValueGateRejectedGroup>();

                foreach (var plan in groupPlans)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (TryAcceptAtlasValueBatch(
                            state,
                            plan.Candidates,
                            plan.AffinityGroups,
                            expectedEntitiesByMesh,
                            out var residency,
                            out var rawDraws,
                            out var expectedDraws,
                            out var rejectionReason))
                    {
                        standaloneAccepted.Add(
                            new AtlasValueGateAcceptedGroup(
                                plan,
                                residency,
                                rawDraws,
                                expectedDraws,
                                WasMarginalOnly: false,
                                AcceptanceKind: AtlasValueGateAcceptanceKind.DrawMerge));
                    }
                    else
                    {
                        var candidateResidency = residency;
                        var candidateRejectionReason = rejectionReason;
                        if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(plan) > 0)
                        {
                            var textureMergeAccepted =
                                TryAcceptTextureOnlyMergeAtlasBatch(
                                    state,
                                    plan,
                                    expectedEntitiesByMesh,
                                    out var textureMergeResidency,
                                    out var textureMergeRawDraws,
                                    out var textureMergeExpectedDraws,
                                    out var textureMergeRejectionReason);
                            if (textureMergeAccepted)
                            {
                                standaloneAccepted.Add(
                                    new AtlasValueGateAcceptedGroup(
                                        plan,
                                        textureMergeResidency,
                                        textureMergeRawDraws,
                                        textureMergeExpectedDraws,
                                        WasMarginalOnly: false,
                                        AcceptanceKind:
                                            AtlasValueGateAcceptanceKind.TextureOnlyMerge));
                                continue;
                            }

                            candidateResidency = textureMergeResidency;
                            candidateRejectionReason =
                                $"{rejectionReason}; texture-only merge credit rejected: " +
                                textureMergeRejectionReason;
                        }

                        standaloneRejected.Add(
                            new AtlasValueGateRejectedGroup(
                                plan,
                                candidateResidency,
                                candidateRejectionReason));
                    }
                }

                if (standaloneAccepted.Count == 0)
                {
                    if (groupPlans.Count > 1)
                        state.AtlasValueGateBroadBatchesSplit++;

                    foreach (var rejected in standaloneRejected)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                    if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(rejected.Plan) > 0)
                        {
                            pendingTextureMergeAttachments.Add(
                                new AtlasValueGatePendingTextureMergeAttachment(
                                    rejected.Plan,
                                    rejected.Residency,
                                    rejected.RejectionReason));
                        }
                        else
                        {
                            RejectAtlasValueGateGroup(
                                state,
                                rejected.Plan,
                                rejected.Residency,
                                rejected.RejectionReason);
                        }
                    }

                    continue;
                }

                // A standalone texture-only merge has a deliberately separate budget because
                // its source textures may remain reachable through unrelated materials. Keep
                // standalone texture-merge groups isolated from normal groups; marginal
                // attachments are handled later against the already accepted atlas cost.
                if (standaloneAccepted.Any(group =>
                        group.AcceptanceKind == AtlasValueGateAcceptanceKind.TextureOnlyMerge))
                {
                    if (groupPlans.Count > 1)
                        state.AtlasValueGateBroadBatchesSplit++;

                    foreach (var accepted in standaloneAccepted)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        if (TryRecheckStandaloneAcceptedAtlasValueGateGroup(
                                state,
                                accepted,
                                expectedEntitiesByMesh,
                                out var sequentialResidency,
                                out var sequentialRawDraws,
                                out var sequentialExpectedDraws,
                                out var sequentialRejectionReason))
                        {
                            result.Add(accepted.Plan.Candidates);
                            RecordAtlasValueGateAccepted(
                                state,
                                accepted.Plan.Candidates,
                                sequentialResidency,
                                sequentialRawDraws,
                                sequentialExpectedDraws,
                                expectedEntitiesByMesh,
                                accepted.AcceptanceKind);
                            continue;
                        }

                        // The initial standalone estimates were all made against the same
                        // pre-acceptance reference set. Rechecking here makes a later group
                        // pay for the consumer union left after earlier groups were accepted.
                        // A failed texture-only recheck remains eligible for the normal
                        // cross-batch attachment pass; a draw merge is rejected outright.
                        if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(accepted.Plan) > 0)
                        {
                            pendingTextureMergeAttachments.Add(
                                new AtlasValueGatePendingTextureMergeAttachment(
                                    accepted.Plan,
                                    sequentialResidency,
                                    "sequential standalone recheck: " +
                                    sequentialRejectionReason));
                        }
                        else
                        {
                            RejectAtlasValueGateGroup(
                                state,
                                accepted.Plan,
                                sequentialResidency,
                                "sequential standalone recheck: " +
                                sequentialRejectionReason);
                        }
                    }

                    foreach (var rejected in standaloneRejected)
                    {
                        if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(rejected.Plan) > 0)
                        {
                            pendingTextureMergeAttachments.Add(
                                new AtlasValueGatePendingTextureMergeAttachment(
                                    rejected.Plan,
                                    rejected.Residency,
                                    rejected.RejectionReason));
                        }
                        else
                        {
                            RejectAtlasValueGateGroup(
                                state,
                                rejected.Plan,
                                rejected.Residency,
                                rejected.RejectionReason);
                        }
                    }

                    continue;
                }

                var workingAccepted = new List<AtlasValueGateAcceptedGroup>(
                    standaloneAccepted);
                var workingCandidates = standaloneAccepted
                    .SelectMany(group => group.Plan.Candidates)
                    .DistinctBy(candidate => candidate.Key)
                    .ToList();
                var workingGroups = standaloneAccepted
                    .SelectMany(group => group.Plan.AffinityGroups)
                    .ToList();

                foreach (var rejected in standaloneRejected)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    var marginalRawDraws = 0;
                    var marginalExpectedDraws = 0.0;
                    string marginalReason;
                    AtlasValueGateAcceptanceKind marginalAcceptanceKind;
                    var marginalAccepted = false;
                    if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(rejected.Plan) > 0)
                    {
                        marginalAcceptanceKind =
                            AtlasValueGateAcceptanceKind.TextureOnlyMerge;
                        marginalAccepted = TryAcceptTextureOnlyMergeMarginalAddition(
                            state,
                            workingCandidates,
                            rejected.Plan.Candidates,
                            workingGroups,
                            rejected.Plan.AffinityGroups,
                            expectedEntitiesByMesh,
                            out marginalRawDraws,
                            out marginalExpectedDraws,
                            out marginalReason);
                    }
                    else
                    {
                        marginalAcceptanceKind =
                            AtlasValueGateAcceptanceKind.DrawMerge;
                        marginalAccepted = TryAcceptAtlasValueMarginalAddition(
                            state,
                            workingCandidates,
                            rejected.Plan.Candidates,
                            workingGroups,
                            rejected.Plan.AffinityGroups,
                            expectedEntitiesByMesh,
                            out marginalReason);
                    }

                    if (marginalAccepted)
                    {
                        workingAccepted.Add(
                            new AtlasValueGateAcceptedGroup(
                                rejected.Plan,
                                rejected.Residency,
                                marginalRawDraws,
                                marginalExpectedDraws,
                                WasMarginalOnly: true,
                                AcceptanceKind: marginalAcceptanceKind));
                        workingCandidates.AddRange(
                            rejected.Plan.Candidates.Where(candidate =>
                                workingCandidates.All(existing =>
                                    existing.Key != candidate.Key)));
                        workingGroups.AddRange(rejected.Plan.AffinityGroups);
                        state.AtlasValueGateMarginalGroupsAccepted++;
                    }
                    else
                    {
                        if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(rejected.Plan) > 0)
                        {
                            pendingTextureMergeAttachments.Add(
                                new AtlasValueGatePendingTextureMergeAttachment(
                                    rejected.Plan,
                                    rejected.Residency,
                                    $"mixed-batch marginal check: {marginalReason}"));
                        }
                        else
                        {
                            RejectAtlasValueGateGroup(
                                state,
                                rejected.Plan,
                                rejected.Residency,
                                $"mixed-batch marginal check: {marginalReason}");
                            state.AtlasValueGateMixedGroupsRejected++;
                        }
                    }
                }

                if (workingAccepted.Count == 1)
                {
                    var accepted = workingAccepted[0];
                    result.Add(accepted.Plan.Candidates);
                    RecordAtlasValueGateAccepted(
                        state,
                        accepted.Plan.Candidates,
                        accepted.Residency,
                        accepted.RawDrawsEliminated,
                        accepted.ExpectedArmyDrawsEliminated,
                        expectedEntitiesByMesh,
                        accepted.AcceptanceKind);
                    continue;
                }

                if (TryAcceptAtlasValueBatch(
                        state,
                        workingCandidates,
                        workingGroups,
                        expectedEntitiesByMesh,
                        out var combinedResidency,
                        out var combinedRawDraws,
                        out var combinedExpectedDraws,
                        out var combinedRejectionReason))
                {
                    result.Add(workingCandidates);
                    RecordAtlasValueGateAccepted(
                        state,
                        workingCandidates,
                        combinedResidency,
                        combinedRawDraws,
                        combinedExpectedDraws,
                        expectedEntitiesByMesh);
                    continue;
                }

                var textureOnlyMarginalGroupCount = workingAccepted.Count(
                    group => group.WasMarginalOnly &&
                             group.AcceptanceKind ==
                             AtlasValueGateAcceptanceKind.TextureOnlyMerge);
                var combinedScenarioResolved =
                    IsAtlasValueBatchScenarioResolved(state, workingCandidates);
                var combinedGrowthWithinCap = true;
                if (textureOnlyMarginalGroupCount > 0)
                {
                    var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
                    if (sourceBcnBytes > 0)
                    {
                        var projectedNetGrowth =
                            state.AtlasValueGateNetBcnBytesAccepted +
                            (double)combinedResidency.NetBcnBytes;
                        combinedGrowthWithinCap = projectedNetGrowth <=
                            sourceBcnBytes * MaxReachableBcnGrowthRatio;
                    }
                }

                // A texture-only marginal attachment has already been checked against the
                // incremental cost of the current accepted atlas. The ordinary aggregate gate
                // can still reject the mixed batch because it prices the entire batch as a
                // standalone draw-merge decision. Preserve the sequential marginal decisions
                // when the combined plan is valid, has real draw benefit, and remains under the
                // cumulative growth cap.
                if (textureOnlyMarginalGroupCount > 0 &&
                    combinedScenarioResolved &&
                    combinedRawDraws > 0 &&
                    combinedExpectedDraws > AtlasValueGateExpectedDrawEpsilon &&
                    combinedGrowthWithinCap)
                {
                    result.Add(workingCandidates);
                    state.AtlasValueGateTextureOnlyMergeMarginalGroupsAccepted +=
                        textureOnlyMarginalGroupCount;
                    RecordAtlasValueGateAccepted(
                        state,
                        workingCandidates,
                        combinedResidency,
                        combinedRawDraws,
                        combinedExpectedDraws,
                        expectedEntitiesByMesh);
                    continue;
                }

                // Even economically sound groups can make a combined atlas worse because of
                // packing/layout effects. Fall back to the groups that passed standalone.
                state.AtlasValueGateBroadBatchesSplit++;
                foreach (var accepted in standaloneAccepted)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (TryAcceptAtlasValueBatch(
                            state,
                            accepted.Plan.Candidates,
                            accepted.Plan.AffinityGroups,
                            expectedEntitiesByMesh,
                            out var standaloneResidency,
                            out var standaloneRawDraws,
                            out var standaloneExpectedDraws,
                            out var standaloneRejectionReason))
                    {
                        result.Add(accepted.Plan.Candidates);
                        RecordAtlasValueGateAccepted(
                            state,
                            accepted.Plan.Candidates,
                            standaloneResidency,
                            standaloneRawDraws,
                            standaloneExpectedDraws,
                            expectedEntitiesByMesh,
                            accepted.AcceptanceKind);
                    }
                    else
                    {
                        RejectAtlasValueGateGroup(
                            state,
                            accepted.Plan,
                            standaloneResidency,
                            $"standalone recheck after broad-batch rejection: " +
                            standaloneRejectionReason);
                    }
                }

                foreach (var marginalOnly in workingAccepted.Where(
                             group => group.WasMarginalOnly))
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (marginalOnly.AcceptanceKind ==
                        AtlasValueGateAcceptanceKind.TextureOnlyMerge)
                    {
                        pendingTextureMergeAttachments.Add(
                            new AtlasValueGatePendingTextureMergeAttachment(
                                marginalOnly.Plan,
                                marginalOnly.Residency,
                                "marginal sharing required a broad batch that was rejected: " +
                                combinedRejectionReason));
                    }
                    else
                    {
                        RejectAtlasValueGateGroup(
                            state,
                            marginalOnly.Plan,
                            marginalOnly.Residency,
                            $"marginal sharing required a broad batch that was rejected: " +
                            combinedRejectionReason);
                        state.AtlasValueGateMixedGroupsRejected++;
                    }
                }
            }

            AttachPendingTextureOnlyMergeGroups(
                state,
                result,
                affinityGroups,
                expectedEntitiesByMesh,
                pendingTextureMergeAttachments,
                acceptedEconomicsStartIndex);

            return result;
        }

        private static bool TryRecheckStandaloneAcceptedAtlasValueGateGroup(
            BatchState state,
            AtlasValueGateAcceptedGroup accepted,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            out AtlasValueGateResidencyEstimate residency,
            out int rawDrawsEliminated,
            out double expectedArmyDrawsEliminated,
            out string rejectionReason)
        {
            if (accepted.AcceptanceKind == AtlasValueGateAcceptanceKind.TextureOnlyMerge)
            {
                return TryAcceptTextureOnlyMergeAtlasBatch(
                    state,
                    accepted.Plan,
                    expectedEntitiesByMesh,
                    out residency,
                    out rawDrawsEliminated,
                    out expectedArmyDrawsEliminated,
                    out rejectionReason);
            }

            return TryAcceptAtlasValueBatch(
                state,
                accepted.Plan.Candidates,
                accepted.Plan.AffinityGroups,
                expectedEntitiesByMesh,
                out residency,
                out rawDrawsEliminated,
                out expectedArmyDrawsEliminated,
                out rejectionReason);
        }

        private static void RejectAtlasValueGateGroup(
            BatchState state,
            AtlasValueGateGroupPlan plan,
            AtlasValueGateResidencyEstimate residency,
            string rejectionReason)
        {
            state.AtlasValueGateBatchesRejected++;
            state.AtlasValueGateCandidatesRejected += plan.Candidates.Count;
            RecordAtlasValueGateRejected(state, residency);

            foreach (var candidate in plan.Candidates)
            {
                RecordSkip(
                    state,
                    candidate.RootVmdPath,
                    candidate.Key,
                    candidate.Usages.FirstOrDefault()?.AssetPath ?? string.Empty,
                    $"Atlas value gate: {rejectionReason}");
            }
        }

        private static void RecordAtlasValueGateSourceTextureResidencyDiagnostics(
            BatchState state,
            IReadOnlyList<AtlasValueGateSourceTextureResidencyDiagnostic> diagnostics)
        {
            foreach (var diagnostic in diagnostics)
            {
                var texturePath = Normalize(diagnostic.TexturePath);
                if (texturePath.Length == 0)
                    continue;

                if (!state.AtlasValueGateSourceTextureResidencyDiagnostics.TryGetValue(
                        texturePath,
                        out var existing))
                {
                    state.AtlasValueGateSourceTextureResidencyDiagnostics[texturePath] =
                        diagnostic with { TexturePath = texturePath };
                    continue;
                }

                // A texture can participate in multiple accepted batches. Preserve the
                // first accepted evaluation as Pbefore and advance only the post-rewrite
                // side, while accumulating only the actual incremental credit from each
                // accepted transition. This keeps an earlier conservative/unresolved
                // transition from being reconstructed as credit by a later resolved one.
                var accumulatedExpectedRetirement =
                    AccumulateAtlasValueGateScenarioRetirement(
                        existing.BcnBytes,
                        existing.ExpectedRetiredBcnBytes,
                        diagnostic.ExpectedRetiredBcnBytes);
                state.AtlasValueGateSourceTextureResidencyDiagnostics[texturePath] =
                    existing with
                    {
                        RewrittenReferenceCountAfter =
                            diagnostic.RewrittenReferenceCountAfter,
                        ConsumerMappingResolved =
                            existing.ConsumerMappingResolved &&
                            diagnostic.ConsumerMappingResolved,
                        ProposedResidentProbability =
                            diagnostic.ProposedResidentProbability,
                        ProposedExpectedResidentBcnBytes =
                            diagnostic.ProposedExpectedResidentBcnBytes,
                        ExpectedRetiredBcnBytes =
                            accumulatedExpectedRetirement,
                        ProposedConsumerWsModels =
                            diagnostic.ProposedConsumerWsModels,
                        ProposedScenarioProjection =
                            diagnostic.ProposedScenarioProjection,
                    };
            }
        }

        private static double AccumulateAtlasValueGateScenarioRetirement(
            long bcnBytes,
            double accumulatedRetiredBytes,
            double incrementalRetiredBytes)
        {
            if (bcnBytes <= 0)
                return 0;

            var accumulated = double.IsFinite(accumulatedRetiredBytes)
                ? Math.Max(0.0, accumulatedRetiredBytes)
                : 0.0;
            var incremental = double.IsFinite(incrementalRetiredBytes)
                ? Math.Max(0.0, incrementalRetiredBytes)
                : 0.0;
            return Math.Min((double)bcnBytes, accumulated + incremental);
        }

        private static void RecordAtlasValueGateAccepted(
            BatchState state,
            IReadOnlyList<AtlasCandidate> batch,
            AtlasValueGateResidencyEstimate residency,
            int rawDrawsEliminated,
            double expectedArmyDrawsEliminated,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            AtlasValueGateAcceptanceKind acceptanceKind = AtlasValueGateAcceptanceKind.DrawMerge,
            int consolidatedTextureAssignments = 0)
        {
            state.AtlasValueGateBatchesAccepted++;
            state.AtlasValueGateCandidatesAccepted += batch.Count;
            state.AtlasValueGateGeneratedBcnBytesAccepted = checked(
                state.AtlasValueGateGeneratedBcnBytesAccepted + residency.GeneratedBcnBytes);
            state.AtlasValueGateRetiredBcnBytesAccepted = checked(
                state.AtlasValueGateRetiredBcnBytesAccepted + residency.RetiredSourceBcnBytes);
            state.AtlasValueGateNetBcnBytesAccepted = checked(
                state.AtlasValueGateNetBcnBytesAccepted + residency.NetBcnBytes);
            state.AtlasValueGateExpectedArmyGeneratedBcnBytesAccepted +=
                residency.ExpectedArmyGeneratedBcnBytes;
            state.AtlasValueGateExpectedArmyRetiredBcnBytesAccepted +=
                residency.ExpectedArmyRetiredSourceBcnBytes;
            state.AtlasValueGateExpectedArmyNetBcnBytesAccepted +=
                residency.ExpectedArmyNetBcnBytes;
            state.AtlasValueGateExpectedDrawsAccepted += expectedArmyDrawsEliminated;
            RecordAtlasValueGateSourceTextureResidencyDiagnostics(
                state,
                residency.SourceTextureResidencyDiagnostics);
            if (acceptanceKind == AtlasValueGateAcceptanceKind.TextureOnlyMerge)
            {
                state.AtlasValueGateTextureOnlyMergeBatchesAccepted++;
                state.AtlasValueGateTextureOnlyMergeCandidatesAccepted += batch.Count;
            }
            else if (acceptanceKind == AtlasValueGateAcceptanceKind.TextureOnlyRetirement)
            {
                state.AtlasValueGateTextureOnlyBatchesAccepted++;
                state.AtlasValueGateTextureOnlyCandidatesAccepted += batch.Count;
                state.AtlasValueGateTextureOnlyPackReferenceRetiredSourceTextureCount +=
                    residency.PackReferenceRetiredSourceTextureCount;
                state.AtlasValueGateTextureOnlyRetiredSourceTextureCount +=
                    residency.RetiredSourceTextureCount;
                state.AtlasValueGateTextureOnlyScenarioDisplacedSourceTextureCount +=
                    residency.ScenarioDisplacedSourceTextureCount;
                state.AtlasValueGateTextureOnlyExpectedRetiredSourceTextureCount +=
                    residency.ExpectedArmyRetiredSourceTextureCount;
                state.AtlasValueGateTextureOnlyRetiredBcnBytesAccepted = checked(
                    state.AtlasValueGateTextureOnlyRetiredBcnBytesAccepted +
                    residency.RetiredSourceBcnBytes);
                state.AtlasValueGateTextureOnlyExpectedRetiredBcnBytesAccepted +=
                    residency.ExpectedArmyRetiredSourceBcnBytes;
            }
            else if (acceptanceKind == AtlasValueGateAcceptanceKind.TextureConsolidation)
            {
                state.AtlasValueGateTextureConsolidationBatchesAccepted++;
                state.AtlasValueGateTextureConsolidationCandidatesAccepted += batch.Count;
                state.AtlasValueGateTextureConsolidatedAssignments = checked(
                    state.AtlasValueGateTextureConsolidatedAssignments +
                    consolidatedTextureAssignments);
            }

            var coverage = CalculateAtlasBatchCoverage(batch, expectedEntitiesByMesh);
            state.AtlasValueGateAcceptedAffectedUnits.UnionWith(
                coverage.AffectedUnits);

            var roots = batch
                .Select(candidate => Normalize(candidate.RootVmdPath))
                .Where(path => path.Length != 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            state.AtlasValueGateAcceptedBatchEconomics.Add(
                new AtlasValueGateBatchEconomics(
                    state.AtlasValueGateBatchesAccepted,
                    batch.Count,
                    roots,
                    acceptanceKind,
                    coverage.AffectedUnitCount,
                    coverage.ExpectedRenderedEntities,
                    residency.GeneratedBcnBytes,
                    residency.RetiredSourceBcnBytes,
                    residency.NetBcnBytes,
                    residency.ExpectedArmyGeneratedBcnBytes,
                    residency.ExpectedArmyRetiredSourceBcnBytes,
                    residency.ExpectedArmyNetBcnBytes,
                    rawDrawsEliminated,
                    expectedArmyDrawsEliminated));

            AddAtlasValueGateRewrittenReferences(
                state,
                residency.RewrittenReferences);
        }

        private static void RecordAtlasValueGateRejected(
            BatchState state,
            AtlasValueGateResidencyEstimate residency)
        {
            state.AtlasValueGateGeneratedBcnBytesRejected = checked(
                state.AtlasValueGateGeneratedBcnBytesRejected + residency.GeneratedBcnBytes);
            state.AtlasValueGateRetiredBcnBytesRejected = checked(
                state.AtlasValueGateRetiredBcnBytesRejected + residency.RetiredSourceBcnBytes);
            state.AtlasValueGateNetBcnBytesRejected = checked(
                state.AtlasValueGateNetBcnBytesRejected + residency.NetBcnBytes);
            state.AtlasValueGateExpectedArmyGeneratedBcnBytesRejected +=
                residency.ExpectedArmyGeneratedBcnBytes;
            state.AtlasValueGateExpectedArmyRetiredBcnBytesRejected +=
                residency.ExpectedArmyRetiredSourceBcnBytes;
            state.AtlasValueGateExpectedArmyNetBcnBytesRejected +=
                residency.ExpectedArmyNetBcnBytes;
        }

        private enum AtlasValueGateAcceptanceKind
        {
            DrawMerge,
            TextureOnlyMerge,
            TextureOnlyRetirement,
            TextureConsolidation,
        }

        private enum AtlasValueGateBudgetDecision
        {
            Accept,
            ScenarioResolvedZeroBenefit,
            FallbackBudgetExceeded,
            ScenarioBudgetExceeded,
            TextureOnlyMergeBudgetExceeded,
            GlobalGrowthCapExceeded,
        }

        private static AtlasValueGateBudgetDecision EvaluateAtlasValueGateBudget(
            bool scenarioResolved,
            int rawDrawsEliminated,
            double expectedArmyDrawsEliminated,
            double globalCostBytes,
            double expectedCostBytes,
            double acceptedNetBcnBytes,
            double proposedNetBcnBytes,
            double sourceBcnBytes)
        {
            if (scenarioResolved)
            {
                if (expectedArmyDrawsEliminated <= AtlasValueGateExpectedDrawEpsilon)
                {
                    if (globalCostBytes > 0)
                        return AtlasValueGateBudgetDecision.ScenarioResolvedZeroBenefit;
                }
                else
                {
                    var expectedBudget =
                        expectedArmyDrawsEliminated * MaxNetBcnBytesPerExpectedArmyDraw;
                    if (expectedCostBytes > expectedBudget)
                        return AtlasValueGateBudgetDecision.ScenarioBudgetExceeded;
                }
            }
            else
            {
                var fallbackBudget =
                    Math.Max(rawDrawsEliminated, 0) *
                    (double)MaxNetBcnBytesPerFallbackDraw;
                if (globalCostBytes > fallbackBudget)
                    return AtlasValueGateBudgetDecision.FallbackBudgetExceeded;
            }

            if (sourceBcnBytes > 0)
            {
                var projectedNetGrowth = acceptedNetBcnBytes + proposedNetBcnBytes;
                var globalGrowthCap = sourceBcnBytes * MaxReachableBcnGrowthRatio;
                if (projectedNetGrowth > globalGrowthCap)
                    return AtlasValueGateBudgetDecision.GlobalGrowthCapExceeded;
            }

            return AtlasValueGateBudgetDecision.Accept;
        }

        private static AtlasValueGateBudgetDecision
            EvaluateTextureOnlyMergeAtlasValueGateBudget(
                bool scenarioResolved,
                int prospectiveTextureMergeDraws,
                double expectedArmyDrawsEliminated,
                double globalCostBytes,
                double expectedCostBytes,
                double packLocalRetirementCreditBytes,
                double acceptedNetBcnBytes,
                double proposedNetBcnBytes,
                double sourceBcnBytes)
        {
            if (!scenarioResolved ||
                prospectiveTextureMergeDraws <= 0 ||
                expectedArmyDrawsEliminated <= AtlasValueGateExpectedDrawEpsilon)
            {
                return AtlasValueGateBudgetDecision.ScenarioResolvedZeroBenefit;
            }

            var structuralBudget = prospectiveTextureMergeDraws *
                                    (double)MaxNetBcnBytesPerTextureOnlyMergeDraw;
            var scenarioDrawBudget = expectedArmyDrawsEliminated *
                                     MaxNetBcnBytesPerTextureOnlyMergeExpectedArmyDraw;
            // Pack-local retirement of an external/vanilla source texture is not physical
            // pack-byte retirement, so it must not increase the global growth budget.
            // It does remove this pack's demand for that source texture, however, and the
            // ordinary texture-only gate already treats that as a bounded value signal.
            // Reuse the same per-retired-texture allowance here, while excluding physically
            // retired textures because their bytes are already subtracted from the costs.
            var effectiveScenarioBudget =
                scenarioDrawBudget + Math.Max(0.0, packLocalRetirementCreditBytes);
            var effectiveGlobalBudget = Math.Max(structuralBudget, scenarioDrawBudget);
            if (globalCostBytes > effectiveGlobalBudget ||
                expectedCostBytes > effectiveScenarioBudget)
            {
                return AtlasValueGateBudgetDecision.TextureOnlyMergeBudgetExceeded;
            }

            if (sourceBcnBytes > 0)
            {
                var projectedNetGrowth = acceptedNetBcnBytes + proposedNetBcnBytes;
                var globalGrowthCap = sourceBcnBytes * MaxReachableBcnGrowthRatio;
                if (projectedNetGrowth > globalGrowthCap)
                    return AtlasValueGateBudgetDecision.GlobalGrowthCapExceeded;
            }

            return AtlasValueGateBudgetDecision.Accept;
        }

        private static double GetPackLocalOnlyRetirementCreditBytes(
            int packReferenceRetiredSourceTextureCount,
            int physicallyRetiredSourceTextureCount)
        {
            var packLocalOnlyRetirements = Math.Max(
                0,
                packReferenceRetiredSourceTextureCount -
                physicallyRetiredSourceTextureCount);
            return packLocalOnlyRetirements *
                   (double)MaxNetBcnBytesPerRetiredSourceTexture;
        }

        private static bool IsAtlasValueCandidateAllowedForMode(
            bool atlasAllVmdsEnabled,
            bool scenarioResolved)
            => atlasAllVmdsEnabled || scenarioResolved;

        private static bool IsAtlasValueCandidateScenarioResolved(
            BatchState state,
            AtlasCandidate candidate)
        {
            var resolution = state.UnitCategoryResolution;
            if (state.ArmyResidencyModel == null ||
                resolution == null ||
                !resolution.IsGameplayResolutionHealthy)
            {
                return false;
            }

            var root = Normalize(candidate.RootVmdPath);
            if (root.Length != 0)
            {
                if (!resolution.IsVmdUsageComplete(root))
                    return false;

                if (resolution.UsagesByVmd.TryGetValue(root, out var usages) &&
                    usages.Count != 0)
                {
                    return true;
                }
            }

            foreach (var usage in candidate.Usages)
            {
                var assetPath = Normalize(usage.AssetPath);
                if (assetPath.Length != 0 &&
                    resolution.DirectAssetUsagesByPath.TryGetValue(
                        assetPath,
                        out var directUsages) &&
                    directUsages.Count != 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static bool IsAtlasValueBatchScenarioResolved(
            BatchState state,
            IReadOnlyList<AtlasCandidate> batch)
            => batch.All(candidate =>
                IsAtlasValueCandidateScenarioResolved(state, candidate));


        private static AtlasValueGateBudgetDecision EvaluateMarginalAtlasValueGateBudget(
            bool scenarioResolved,
            int baseRawDrawsEliminated,
            int combinedRawDrawsEliminated,
            double baseExpectedArmyDrawsEliminated,
            double combinedExpectedArmyDrawsEliminated,
            double baseGeneratedBcnBytes,
            double baseRetiredSourceBcnBytes,
            double combinedGeneratedBcnBytes,
            double combinedRetiredSourceBcnBytes,
            double baseExpectedGeneratedBcnBytes,
            double baseExpectedRetiredSourceBcnBytes,
            double combinedExpectedGeneratedBcnBytes,
            double combinedExpectedRetiredSourceBcnBytes,
            double acceptedNetBcnBytes,
            double sourceBcnBytes)
        {
            var marginalRawDraws = Math.Max(
                0,
                combinedRawDrawsEliminated - baseRawDrawsEliminated);
            var marginalExpectedDraws = Math.Max(
                0,
                combinedExpectedArmyDrawsEliminated -
                baseExpectedArmyDrawsEliminated);
            var marginalGenerated = combinedGeneratedBcnBytes - baseGeneratedBcnBytes;
            var marginalRetired =
                combinedRetiredSourceBcnBytes - baseRetiredSourceBcnBytes;
            var marginalExpectedGenerated =
                combinedExpectedGeneratedBcnBytes - baseExpectedGeneratedBcnBytes;
            var marginalExpectedRetired =
                combinedExpectedRetiredSourceBcnBytes -
                baseExpectedRetiredSourceBcnBytes;
            var marginalGlobalCost = GetChargeableAtlasValueGateBytes(
                marginalGenerated,
                marginalRetired);
            var marginalExpectedCost = GetChargeableAtlasValueGateBytes(
                marginalExpectedGenerated,
                marginalExpectedRetired);
            var baseNet = baseGeneratedBcnBytes - baseRetiredSourceBcnBytes;
            var combinedNet =
                combinedGeneratedBcnBytes - combinedRetiredSourceBcnBytes;
            var marginalNet = combinedNet - baseNet;

            return EvaluateAtlasValueGateBudget(
                scenarioResolved,
                marginalRawDraws,
                marginalExpectedDraws,
                marginalGlobalCost,
                marginalExpectedCost,
                acceptedNetBcnBytes + baseNet,
                marginalNet,
                sourceBcnBytes);
        }

        private static (int Raw, double Expected) CalculateAtlasBatchDrawSavings(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh)
        {
            var batches = new List<List<AtlasCandidate>>
            {
                candidates.ToList(),
            };
            var batchByMesh = BuildBatchIndexByMesh(batches);
            return (
                CalculateMergeAffinityScore(batches, affinityGroups),
                CalculateExpectedArmyDrawCallsEliminated(
                    state,
                    batchByMesh,
                    affinityGroups,
                    expectedEntitiesByMesh));
        }

        private static List<MergeAffinityGroup> GetMergeAffinityGroupsForCandidates(
            IReadOnlyList<AtlasCandidate> candidates,
            IReadOnlyList<MergeAffinityGroup> affinityGroups)
        {
            var candidateKeys = candidates
                .Select(candidate => candidate.Key)
                .ToHashSet();
            return affinityGroups
                .Select(group => FilterMergeAffinityGroup(group, candidateKeys))
                .Where(group => group.Meshes.Length >= 2)
                .ToList();
        }

        private static bool TryAcceptTextureOnlyMergeMarginalAddition(
            BatchState state,
            IReadOnlyList<AtlasCandidate> baseCandidates,
            IReadOnlyList<AtlasCandidate> addedCandidates,
            IReadOnlyList<MergeAffinityGroup> baseGroups,
            IReadOnlyList<MergeAffinityGroup> addedGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            out int marginalRawDrawsEliminated,
            out double marginalExpectedArmyDrawsEliminated,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            if (CalculateProspectiveTextureMergeDraws(addedGroups) <= 0)
            {
                marginalRawDrawsEliminated = 0;
                marginalExpectedArmyDrawsEliminated = 0;
                rejectionReason =
                    "marginal texture-only attachment requires a prospective texture merge.";
                return false;
            }

            var combinedGroups = baseGroups
                .Concat(addedGroups)
                .ToList();
            var accepted = TryEvaluateTextureOnlyMergeMarginalAddition(
                state,
                baseCandidates,
                addedCandidates,
                baseGroups,
                combinedGroups,
                expectedEntitiesByMesh,
                baseAlreadyAccepted: false,
                out var evaluation,
                out rejectionReason);
            marginalRawDrawsEliminated =
                evaluation?.MarginalRawDrawsEliminated ?? 0;
            marginalExpectedArmyDrawsEliminated =
                evaluation?.MarginalExpectedArmyDrawsEliminated ?? 0;
            return accepted;
        }

        private static bool TryEvaluateTextureOnlyMergeMarginalAddition(
            BatchState state,
            IReadOnlyList<AtlasCandidate> baseCandidates,
            IReadOnlyList<AtlasCandidate> addedCandidates,
            IReadOnlyList<MergeAffinityGroup> baseGroups,
            IReadOnlyList<MergeAffinityGroup> combinedGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            bool baseAlreadyAccepted,
            out TextureOnlyMergeMarginalEvaluation? evaluation,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            evaluation = null;
            rejectionReason = string.Empty;

            if (baseCandidates.Count == 0 || addedCandidates.Count < 2)
            {
                rejectionReason =
                    "marginal texture-only attachment requires an accepted atlas and " +
                    "at least two added candidates.";
                return false;
            }

            var combinedCandidates = baseCandidates
                .Concat(addedCandidates)
                .DistinctBy(candidate => candidate.Key)
                .ToList();
            if (!TryEstimateIncrementalAtlasResidency(
                    state,
                    baseCandidates,
                    out var baseResidency) ||
                !TryEstimateIncrementalAtlasResidency(
                    state,
                    combinedCandidates,
                    out var combinedResidency))
            {
                rejectionReason =
                    "incremental BCn residency could not be estimated safely.";
                return false;
            }

            var baseSavings = CalculateAtlasBatchDrawSavings(
                state,
                baseCandidates,
                baseGroups,
                expectedEntitiesByMesh);
            var combinedSavings = CalculateAtlasBatchDrawSavings(
                state,
                combinedCandidates,
                combinedGroups,
                expectedEntitiesByMesh);
            var marginalRawDraws = Math.Max(
                0,
                combinedSavings.Raw - baseSavings.Raw);
            var marginalExpectedDraws = Math.Max(
                0,
                combinedSavings.Expected - baseSavings.Expected);
            var marginalProspectiveTextureMergeDraws = Math.Max(
                0,
                CalculateProspectiveTextureMergeDraws(combinedGroups) -
                CalculateProspectiveTextureMergeDraws(baseGroups));
            var marginalGenerated =
                combinedResidency.GeneratedBcnBytes - baseResidency.GeneratedBcnBytes;
            var marginalRetired =
                combinedResidency.RetiredSourceBcnBytes -
                baseResidency.RetiredSourceBcnBytes;
            var marginalExpectedGenerated =
                combinedResidency.ExpectedArmyGeneratedBcnBytes -
                baseResidency.ExpectedArmyGeneratedBcnBytes;
            var marginalExpectedRetired =
                combinedResidency.ExpectedArmyRetiredSourceBcnBytes -
                baseResidency.ExpectedArmyRetiredSourceBcnBytes;
            var marginalGlobalCost = GetChargeableAtlasValueGateBytes(
                marginalGenerated,
                marginalRetired);
            var marginalExpectedCost = GetChargeableAtlasValueGateBytes(
                marginalExpectedGenerated,
                marginalExpectedRetired);
            var marginalNet =
                combinedResidency.NetBcnBytes - baseResidency.NetBcnBytes;
            var marginalPackReferenceRetiredSourceTextureCount = Math.Max(
                0,
                combinedResidency.PackReferenceRetiredSourceTextureCount -
                baseResidency.PackReferenceRetiredSourceTextureCount);
            var marginalPhysicallyRetiredSourceTextureCount = Math.Max(
                0,
                combinedResidency.RetiredSourceTextureCount -
                baseResidency.RetiredSourceTextureCount);
            var marginalPackLocalRetirementCreditBytes =
                GetPackLocalOnlyRetirementCreditBytes(
                    marginalPackReferenceRetiredSourceTextureCount,
                    marginalPhysicallyRetiredSourceTextureCount);

            evaluation = new TextureOnlyMergeMarginalEvaluation(
                combinedCandidates,
                baseResidency,
                combinedResidency,
                baseSavings.Raw,
                combinedSavings.Raw,
                baseSavings.Expected,
                combinedSavings.Expected,
                marginalProspectiveTextureMergeDraws,
                marginalRawDraws,
                marginalExpectedDraws,
                marginalGlobalCost,
                marginalExpectedCost,
                marginalPackLocalRetirementCreditBytes,
                marginalNet);

            var scenarioResolved = IsAtlasValueBatchScenarioResolved(
                state,
                addedCandidates);
            if (!IsAtlasValueCandidateAllowedForMode(
                    state.AtlasAllVmdsEnabled,
                    scenarioResolved))
            {
                rejectionReason =
                    "gameplay/scenario relevance could not be resolved safely.";
                return false;
            }

            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            var acceptedNetBcnBytes = state.AtlasValueGateNetBcnBytesAccepted;
            if (!baseAlreadyAccepted)
                acceptedNetBcnBytes += baseResidency.NetBcnBytes;

            var budgetDecision = EvaluateTextureOnlyMergeAtlasValueGateBudget(
                scenarioResolved,
                marginalProspectiveTextureMergeDraws,
                marginalExpectedDraws,
                marginalGlobalCost,
                marginalExpectedCost,
                marginalPackLocalRetirementCreditBytes,
                acceptedNetBcnBytes,
                marginalNet,
                sourceBcnBytes);
            if (budgetDecision == AtlasValueGateBudgetDecision.Accept)
                return true;

            rejectionReason =
                $"marginal texture-only economics rejected ({budgetDecision}); " +
                $"incremental global cost {FormatMiB(marginalGlobalCost)}, " +
                $"scenario cost {FormatMiB(marginalExpectedCost)}, pack-local retirement " +
                $"credit {FormatMiB(marginalPackLocalRetirementCreditBytes)}, raw draws " +
                $"+{marginalRawDraws:N0}, scenario draws +{marginalExpectedDraws:N3}.";
            return false;
        }

        private static void AttachPendingTextureOnlyMergeGroups(
            BatchState state,
            List<List<AtlasCandidate>> acceptedBatches,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            IReadOnlyList<AtlasValueGatePendingTextureMergeAttachment> pendingAttachments,
            int acceptedEconomicsStartIndex)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            if (pendingAttachments.Count == 0)
                return;

            var orderedAttachments = pendingAttachments
                .OrderByDescending(attachment => attachment.Plan.Candidates.Count)
                .ThenBy(
                    attachment => string.Join(
                        "\u001f",
                        attachment.Plan.Candidates
                            .Select(candidate => candidate.Key.ToString())
                            .OrderBy(key => key, StringComparer.OrdinalIgnoreCase)),
                    StringComparer.OrdinalIgnoreCase)
                .ToList();

            foreach (var pending in orderedAttachments)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                state.AtlasValueGateTextureOnlyMergeCrossBatchGroupsEvaluated++;
                state.AtlasValueGateTextureOnlyMergeSubsetGroupsConsidered++;
                var subsetPlans = BuildTextureOnlyMergeSubsetPlans(pending.Plan);
                var pendingCandidateCount = pending.Plan.Candidates
                    .DistinctBy(candidate => candidate.Key)
                    .Count();
                state.AtlasValueGateTextureOnlyMergeMaximumSubsetGroupCandidateCount =
                    Math.Max(
                        state.AtlasValueGateTextureOnlyMergeMaximumSubsetGroupCandidateCount,
                        pendingCandidateCount);
                state.AtlasValueGateTextureOnlyMergeFourWayOptionsGenerated +=
                    subsetPlans.Count(plan => plan.Candidates.Count == 4);
                if (subsetPlans.Count >= TextureOnlyMergeSubsetOptionLimit)
                    state.AtlasValueGateTextureOnlyMergeSubsetOptionGroupsTruncated++;
                var attachedKeys = new HashSet<MeshKey>();
                var bestRejectionReason = string.Empty;

                while (true)
                {
                    var availableCandidates = pending.Plan.Candidates
                        .Where(candidate => !attachedKeys.Contains(candidate.Key))
                        .ToList();
                    if (availableCandidates.Count < 2)
                        break;

                    var availableKeys = availableCandidates
                        .Select(candidate => candidate.Key)
                        .ToHashSet();
                    AtlasValueGateGroupPlan? bestPlan = null;
                    TextureOnlyMergeMarginalEvaluation? bestEvaluation = null;
                    var bestHostIndex = -1;

                    foreach (var subsetPlan in subsetPlans)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        var subsetKeys = subsetPlan.Candidates
                            .Select(candidate => candidate.Key)
                            .ToHashSet();
                        if (subsetPlan.Candidates.Count < 2 ||
                            !subsetKeys.IsSubsetOf(availableKeys))
                        {
                            continue;
                        }

                        state.AtlasValueGateTextureOnlyMergeSubsetOptionsEvaluated++;
                        if (subsetPlan.Candidates.Count == 4)
                            state.AtlasValueGateTextureOnlyMergeFourWayOptionsEvaluated++;
                        for (var hostIndex = 0;
                             hostIndex < acceptedBatches.Count;
                             hostIndex++)
                        {
                            var host = acceptedBatches[hostIndex];
                            if (host.Any(candidate => subsetKeys.Contains(candidate.Key)))
                                continue;

                            var baseGroups = GetMergeAffinityGroupsForCandidates(
                                host,
                                affinityGroups);
                            var combinedCandidates = host
                                .Concat(subsetPlan.Candidates)
                                .DistinctBy(candidate => candidate.Key)
                                .ToList();
                            var combinedGroups = GetMergeAffinityGroupsForCandidates(
                                combinedCandidates,
                                affinityGroups);
                            foreach (var subsetGroup in GetMergeAffinityGroupsForCandidates(
                                         subsetPlan.Candidates,
                                         subsetPlan.AffinityGroups))
                            {
                                if (!combinedGroups.Any(group =>
                                        group.Meshes.SequenceEqual(subsetGroup.Meshes)))
                                {
                                    combinedGroups.Add(subsetGroup);
                                }
                            }

                            if (!TryEvaluateTextureOnlyMergeMarginalAddition(
                                    state,
                                    host,
                                    subsetPlan.Candidates,
                                    baseGroups,
                                    combinedGroups,
                                    expectedEntitiesByMesh,
                                    baseAlreadyAccepted: true,
                                    out var evaluation,
                                    out var rejectionReason))
                            {
                                if (evaluation != null)
                                {
                                    RecordTextureOnlyMergeNearMiss(
                                        state,
                                        subsetPlan,
                                        host,
                                        evaluation,
                                        rejectionReason);
                                }

                                if (bestRejectionReason.Length == 0)
                                    bestRejectionReason = rejectionReason;
                                continue;
                            }

                            if (evaluation == null)
                                continue;

                            if (bestEvaluation == null ||
                                IsBetterTextureOnlyMergeAttachment(
                                    evaluation,
                                    bestEvaluation))
                            {
                                bestPlan = subsetPlan;
                                bestEvaluation = evaluation;
                                bestHostIndex = hostIndex;
                            }
                        }
                    }

                    if (bestPlan == null ||
                        bestEvaluation == null ||
                        bestHostIndex < 0)
                    {
                        break;
                    }

                    var economicsIndex = acceptedEconomicsStartIndex + bestHostIndex;
                    if (economicsIndex < 0 ||
                        economicsIndex >= state.AtlasValueGateAcceptedBatchEconomics.Count)
                    {
                        bestRejectionReason =
                            "accepted atlas economics bookkeeping was not aligned with " +
                            "the planned batches.";
                        break;
                    }

                    acceptedBatches[bestHostIndex] = bestEvaluation.CombinedCandidates;
                    ApplyTextureOnlyMergeAttachmentAccounting(
                        state,
                        acceptedBatches[bestHostIndex],
                        bestEvaluation,
                        expectedEntitiesByMesh,
                        economicsIndex);
                    foreach (var candidate in bestPlan.Candidates)
                        attachedKeys.Add(candidate.Key);
                    if (bestPlan.Candidates.Count == 4)
                        state.AtlasValueGateTextureOnlyMergeFourWayGroupsAccepted++;
                    state.AtlasValueGateMarginalGroupsAccepted++;
                    state.AtlasValueGateTextureOnlyMergeMarginalGroupsAccepted++;
                    state.AtlasValueGateTextureOnlyMergeCrossBatchGroupsAccepted++;
                }

                var remainderCandidates = pending.Plan.Candidates
                    .Where(candidate => !attachedKeys.Contains(candidate.Key))
                    .ToList();
                if (remainderCandidates.Count == 0)
                    continue;

                var remainderKeys = remainderCandidates
                    .Select(candidate => candidate.Key)
                    .ToHashSet();
                var remainderPlan = CreateAtlasValueGateSubPlan(
                    pending.Plan,
                    remainderCandidates,
                    remainderKeys,
                    GetCompleteAtlasFamilySubsets(
                        pending.Plan.AtomicFamilies,
                        remainderKeys));
                var rejectionResidency = pending.Residency;
                if (TryEstimateIncrementalAtlasResidency(
                        state,
                        remainderCandidates,
                        out var remainderResidency))
                {
                    rejectionResidency = remainderResidency;
                }

                RejectAtlasValueGateGroup(
                    state,
                    remainderPlan,
                    rejectionResidency,
                    "cross-batch texture-only attachment rejected: " +
                    (bestRejectionReason.Length == 0
                        ? "no compatible accepted atlas batch passed the incremental gate."
                        : bestRejectionReason) +
                    $" Original rejection: {pending.RejectionReason}");
            }
        }

        private static List<AtlasValueGateGroupPlan> BuildTextureOnlyMergeSubsetPlans(
            AtlasValueGateGroupPlan plan)
        {
            var candidates = plan.Candidates
                .DistinctBy(candidate => candidate.Key)
                .OrderBy(BuildAtlasPlanningOrderKey, StringComparer.Ordinal)
                .ThenBy(candidate => candidate.Key.ToString(), StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (candidates.Count <= 2)
            {
                var candidateKeys = candidates
                    .Select(candidate => candidate.Key)
                    .ToHashSet();
                var candidatePlan = CreateAtlasValueGateSubPlan(
                    plan,
                    candidates,
                    candidateKeys,
                    GetCompleteAtlasFamilySubsets(plan.AtomicFamilies, candidateKeys));
                return GetAtlasValueGatePlanProspectiveTextureMergeDraws(candidatePlan) > 0 &&
                       IsCompleteAtlasFamilySubset(plan.AtomicFamilies, candidateKeys)
                    ? [candidatePlan]
                    : [];
            }

            var pool = candidates
                .Take(TextureOnlyMergeSubsetCandidateLimit)
                .ToList();
            var subsetPlans = new List<AtlasValueGateGroupPlan>();
            var subsetOptionLimit = Math.Max(1, TextureOnlyMergeSubsetOptionLimit - 1);
            var fourWayOptionReserve = pool.Count > 4
                ? Math.Min(TextureOnlyMergeFourWaySubsetOptionReserve, subsetOptionLimit)
                : 0;
            var activeSubsetOptionLimit = subsetOptionLimit - fourWayOptionReserve;

            void AddSubset(IReadOnlyList<AtlasCandidate> subset)
            {
                if (subsetPlans.Count >= activeSubsetOptionLimit)
                    return;

                var subsetKeys = subset
                    .Select(candidate => candidate.Key)
                    .ToHashSet();
                if (!IsCompleteAtlasFamilySubset(plan.AtomicFamilies, subsetKeys))
                    return;
                var subsetPlan = CreateAtlasValueGateSubPlan(
                    plan,
                    subset,
                    subsetKeys,
                    GetCompleteAtlasFamilySubsets(plan.AtomicFamilies, subsetKeys));
                if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(subsetPlan) <= 0)
                    return;

                subsetPlans.Add(subsetPlan);
            }

            for (var left = 0;
                 left < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                 left++)
            {
                for (var right = left + 1;
                     right < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                     right++)
                {
                    AddSubset([pool[left], pool[right]]);
                }
            }

            if (pool.Count > 3)
            {
                for (var left = 0;
                     left < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                     left++)
                {
                    for (var middle = left + 1;
                         middle < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                         middle++)
                    {
                        for (var right = middle + 1;
                             right < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                             right++)
                        {
                            AddSubset([pool[left], pool[middle], pool[right]]);
                        }
                    }
                }
            }

            // Four-way subsets are intentionally searched only after the pair/triple pass,
            // and only from the bounded planning pool. The reserved option budget prevents
            // the much larger triple search from consuming every slot before four-way
            // combinations get a chance. A group containing exactly four candidates is
            // already covered by the original full-group option below.
            if (pool.Count > 4)
            {
                activeSubsetOptionLimit = subsetOptionLimit;
                for (var first = 0;
                     first < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                     first++)
                {
                    for (var second = first + 1;
                         second < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                         second++)
                    {
                        for (var third = second + 1;
                             third < pool.Count && subsetPlans.Count < activeSubsetOptionLimit;
                             third++)
                        {
                            for (var fourth = third + 1;
                                 fourth < pool.Count &&
                                 subsetPlans.Count < activeSubsetOptionLimit;
                                 fourth++)
                            {
                                AddSubset(
                                    [
                                        pool[first],
                                        pool[second],
                                        pool[third],
                                        pool[fourth],
                                    ]);
                            }
                        }
                    }
                }
            }

            // Retain the original group as a final option. This preserves a full-group win
            // when the combined atlas happens to be cheaper than its smaller alternatives.
            if (GetAtlasValueGatePlanProspectiveTextureMergeDraws(plan) > 0)
                subsetPlans.Add(plan);
            return subsetPlans;
        }

        private static bool IsCompleteAtlasFamilySubset(
            IReadOnlyList<MeshKey[]>? atomicFamilies,
            IReadOnlySet<MeshKey> candidateKeys)
            => atomicFamilies == null || atomicFamilies.All(family =>
                !family.Any(candidateKeys.Contains) ||
                family.All(candidateKeys.Contains));

        private static IReadOnlyList<MeshKey[]> GetCompleteAtlasFamilySubsets(
            IReadOnlyList<MeshKey[]>? atomicFamilies,
            IReadOnlySet<MeshKey> candidateKeys)
            => atomicFamilies == null
                ? Array.Empty<MeshKey[]>()
                : atomicFamilies
                    .Where(family => family.All(candidateKeys.Contains))
                    .ToArray();

        private static void RecordTextureOnlyMergeNearMiss(
            BatchState state,
            AtlasValueGateGroupPlan plan,
            IReadOnlyList<AtlasCandidate> host,
            TextureOnlyMergeMarginalEvaluation evaluation,
            string rejectionReason)
        {
            if (evaluation.MarginalExpectedArmyDrawsEliminated <=
                AtlasValueGateExpectedDrawEpsilon)
            {
                return;
            }

            var structuralBudget = evaluation.MarginalProspectiveTextureMergeDraws *
                (double)MaxNetBcnBytesPerTextureOnlyMergeDraw;
            var scenarioDrawBudget = evaluation.MarginalExpectedArmyDrawsEliminated *
                                     MaxNetBcnBytesPerTextureOnlyMergeExpectedArmyDraw;
            var effectiveScenarioBudget =
                scenarioDrawBudget + evaluation.MarginalPackLocalRetirementCreditBytes;
            var effectiveGlobalBudget = Math.Max(structuralBudget, scenarioDrawBudget);
            var globalPressure = effectiveGlobalBudget > 0
                ? evaluation.MarginalGlobalCostBytes / effectiveGlobalBudget
                : double.PositiveInfinity;
            var scenarioPressure = effectiveScenarioBudget > 0
                ? evaluation.MarginalExpectedCostBytes / effectiveScenarioBudget
                : double.PositiveInfinity;
            var budgetPressure = Math.Max(globalPressure, scenarioPressure);
            if (double.IsNaN(budgetPressure))
                return;

            var candidateGroup = string.Join(
                ", ",
                plan.Candidates
                    .Select(candidate => candidate.Key.ToString())
                    .OrderBy(key => key, StringComparer.OrdinalIgnoreCase));
            var hostBatch = string.Join(
                ", ",
                host
                    .Select(candidate => Normalize(candidate.RootVmdPath))
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Take(4));
            state.AtlasValueGateTextureOnlyMergeNearMisses.Add(
                new AtlasValueGateTextureOnlyMergeNearMiss(
                    candidateGroup,
                    hostBatch.Length == 0 ? "<none>" : hostBatch,
                    plan.Candidates.Count,
                    evaluation.MarginalGlobalCostBytes,
                    evaluation.MarginalExpectedCostBytes,
                    evaluation.MarginalRawDrawsEliminated,
                    evaluation.MarginalExpectedArmyDrawsEliminated,
                    budgetPressure,
                    rejectionReason));

            while (state.AtlasValueGateTextureOnlyMergeNearMisses.Count >
                   TextureOnlyMergeNearMissLimit)
            {
                var worst = state.AtlasValueGateTextureOnlyMergeNearMisses
                    .OrderByDescending(entry => entry.BudgetPressure)
                    .ThenByDescending(entry => entry.ExpectedArmyDrawsEliminated)
                    .First();
                state.AtlasValueGateTextureOnlyMergeNearMisses.Remove(worst);
            }
        }

        private static bool IsBetterTextureOnlyMergeAttachment(
            TextureOnlyMergeMarginalEvaluation candidate,
            TextureOnlyMergeMarginalEvaluation incumbent)
        {
            var candidateExpectedCostPerDraw = GetAtlasValueGateMiBPerDraw(
                Math.Max(
                    0.0,
                    candidate.MarginalExpectedCostBytes -
                    candidate.MarginalPackLocalRetirementCreditBytes),
                candidate.MarginalExpectedArmyDrawsEliminated);
            var incumbentExpectedCostPerDraw = GetAtlasValueGateMiBPerDraw(
                Math.Max(
                    0.0,
                    incumbent.MarginalExpectedCostBytes -
                    incumbent.MarginalPackLocalRetirementCreditBytes),
                incumbent.MarginalExpectedArmyDrawsEliminated);
            const double epsilon = 0.000001;
            if (candidateExpectedCostPerDraw <
                incumbentExpectedCostPerDraw - epsilon)
            {
                return true;
            }

            if (Math.Abs(
                    candidateExpectedCostPerDraw - incumbentExpectedCostPerDraw) >
                epsilon)
            {
                return false;
            }

            if (candidate.MarginalExpectedArmyDrawsEliminated >
                incumbent.MarginalExpectedArmyDrawsEliminated + epsilon)
            {
                return true;
            }

            if (Math.Abs(
                    candidate.MarginalExpectedArmyDrawsEliminated -
                    incumbent.MarginalExpectedArmyDrawsEliminated) > epsilon)
            {
                return false;
            }

            var candidateGlobalCostPerDraw = GetAtlasValueGateMiBPerDraw(
                candidate.MarginalGlobalCostBytes,
                candidate.MarginalRawDrawsEliminated);
            var incumbentGlobalCostPerDraw = GetAtlasValueGateMiBPerDraw(
                incumbent.MarginalGlobalCostBytes,
                incumbent.MarginalRawDrawsEliminated);
            return candidateGlobalCostPerDraw <
                   incumbentGlobalCostPerDraw - epsilon;
        }

        private static void ApplyTextureOnlyMergeAttachmentAccounting(
            BatchState state,
            IReadOnlyList<AtlasCandidate> combinedBatch,
            TextureOnlyMergeMarginalEvaluation evaluation,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            int economicsIndex)
        {
            var generatedDelta = evaluation.CombinedResidency.GeneratedBcnBytes -
                                  evaluation.BaseResidency.GeneratedBcnBytes;
            var retiredDelta = evaluation.CombinedResidency.RetiredSourceBcnBytes -
                               evaluation.BaseResidency.RetiredSourceBcnBytes;
            var netDelta = evaluation.CombinedResidency.NetBcnBytes -
                           evaluation.BaseResidency.NetBcnBytes;
            var expectedGeneratedDelta =
                evaluation.CombinedResidency.ExpectedArmyGeneratedBcnBytes -
                evaluation.BaseResidency.ExpectedArmyGeneratedBcnBytes;
            var expectedRetiredDelta =
                evaluation.CombinedResidency.ExpectedArmyRetiredSourceBcnBytes -
                evaluation.BaseResidency.ExpectedArmyRetiredSourceBcnBytes;
            var expectedNetDelta =
                evaluation.CombinedResidency.ExpectedArmyNetBcnBytes -
                evaluation.BaseResidency.ExpectedArmyNetBcnBytes;

            state.AtlasValueGateCandidatesAccepted = checked(
                state.AtlasValueGateCandidatesAccepted +
                combinedBatch.Count -
                state.AtlasValueGateAcceptedBatchEconomics[economicsIndex].CandidateCount);
            state.AtlasValueGateGeneratedBcnBytesAccepted = checked(
                state.AtlasValueGateGeneratedBcnBytesAccepted + generatedDelta);
            state.AtlasValueGateRetiredBcnBytesAccepted = checked(
                state.AtlasValueGateRetiredBcnBytesAccepted + retiredDelta);
            state.AtlasValueGateNetBcnBytesAccepted = checked(
                state.AtlasValueGateNetBcnBytesAccepted + netDelta);
            state.AtlasValueGateExpectedArmyGeneratedBcnBytesAccepted +=
                expectedGeneratedDelta;
            state.AtlasValueGateExpectedArmyRetiredBcnBytesAccepted +=
                expectedRetiredDelta;
            state.AtlasValueGateExpectedArmyNetBcnBytesAccepted +=
                expectedNetDelta;
            state.AtlasValueGateExpectedDrawsAccepted +=
                evaluation.CombinedExpectedArmyDrawsEliminated -
                evaluation.BaseExpectedArmyDrawsEliminated;
            RecordAtlasValueGateSourceTextureResidencyDiagnostics(
                state,
                evaluation.CombinedResidency.SourceTextureResidencyDiagnostics);
            state.AtlasValueGateAcceptedAffectedUnits.UnionWith(
                CalculateAtlasBatchCoverage(combinedBatch, expectedEntitiesByMesh)
                    .AffectedUnits);
            AddAtlasValueGateRewrittenReferences(
                state,
                evaluation.CombinedResidency.RewrittenReferences);

            var entry = state.AtlasValueGateAcceptedBatchEconomics[economicsIndex];
            var coverage = CalculateAtlasBatchCoverage(
                combinedBatch,
                expectedEntitiesByMesh);
            var roots = combinedBatch
                .Select(candidate => Normalize(candidate.RootVmdPath))
                .Where(path => path.Length != 0)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            state.AtlasValueGateAcceptedBatchEconomics[economicsIndex] = entry with
            {
                CandidateCount = combinedBatch.Count,
                RootVmdPaths = roots,
                AffectedUnitCount = coverage.AffectedUnitCount,
                ExpectedRenderedEntities = coverage.ExpectedRenderedEntities,
                GeneratedBcnBytes = evaluation.CombinedResidency.GeneratedBcnBytes,
                RetiredSourceBcnBytes = evaluation.CombinedResidency.RetiredSourceBcnBytes,
                NetBcnBytes = evaluation.CombinedResidency.NetBcnBytes,
                ExpectedArmyGeneratedBcnBytes =
                    evaluation.CombinedResidency.ExpectedArmyGeneratedBcnBytes,
                ExpectedArmyRetiredSourceBcnBytes =
                    evaluation.CombinedResidency.ExpectedArmyRetiredSourceBcnBytes,
                ExpectedArmyNetBcnBytes =
                    evaluation.CombinedResidency.ExpectedArmyNetBcnBytes,
                RawDrawsEliminated = evaluation.CombinedRawDrawsEliminated,
                ExpectedArmyDrawsEliminated =
                    evaluation.CombinedExpectedArmyDrawsEliminated,
            };
        }

        private static bool TryAcceptAtlasValueMarginalAddition(
            BatchState state,
            IReadOnlyList<AtlasCandidate> baseCandidates,
            IReadOnlyList<AtlasCandidate> addedCandidates,
            IReadOnlyList<MergeAffinityGroup> baseGroups,
            IReadOnlyList<MergeAffinityGroup> addedGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            rejectionReason = string.Empty;
            if (baseCandidates.Count == 0 || addedCandidates.Count == 0)
            {
                rejectionReason = "marginal comparison requires a non-empty base and addition.";
                return false;
            }

            var combinedCandidates = baseCandidates
                .Concat(addedCandidates)
                .DistinctBy(candidate => candidate.Key)
                .ToList();
            var combinedGroups = baseGroups
                .Concat(addedGroups)
                .ToList();

            if (!TryEstimateIncrementalAtlasResidency(
                    state,
                    baseCandidates,
                    out var baseResidency) ||
                !TryEstimateIncrementalAtlasResidency(
                    state,
                    combinedCandidates,
                    out var combinedResidency))
            {
                rejectionReason =
                    "incremental BCn residency could not be estimated safely.";
                return false;
            }

            var baseSavings = CalculateAtlasBatchDrawSavings(
                state,
                baseCandidates,
                baseGroups,
                expectedEntitiesByMesh);
            var combinedSavings = CalculateAtlasBatchDrawSavings(
                state,
                combinedCandidates,
                combinedGroups,
                expectedEntitiesByMesh);
            var scenarioResolved =
                IsAtlasValueBatchScenarioResolved(state, addedCandidates);
            if (!IsAtlasValueCandidateAllowedForMode(
                    state.AtlasAllVmdsEnabled,
                    scenarioResolved))
            {
                rejectionReason =
                    "gameplay/scenario relevance could not be resolved safely.";
                return false;
            }

            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            var decision = EvaluateMarginalAtlasValueGateBudget(
                scenarioResolved,
                baseSavings.Raw,
                combinedSavings.Raw,
                baseSavings.Expected,
                combinedSavings.Expected,
                baseResidency.GeneratedBcnBytes,
                baseResidency.RetiredSourceBcnBytes,
                combinedResidency.GeneratedBcnBytes,
                combinedResidency.RetiredSourceBcnBytes,
                baseResidency.ExpectedArmyGeneratedBcnBytes,
                baseResidency.ExpectedArmyRetiredSourceBcnBytes,
                combinedResidency.ExpectedArmyGeneratedBcnBytes,
                combinedResidency.ExpectedArmyRetiredSourceBcnBytes,
                state.AtlasValueGateNetBcnBytesAccepted,
                sourceBcnBytes);

            if (decision == AtlasValueGateBudgetDecision.Accept)
                return true;

            rejectionReason =
                $"marginal economics rejected the group ({decision}); " +
                $"draws raw {baseSavings.Raw:N0}->{combinedSavings.Raw:N0}, " +
                $"scenario {baseSavings.Expected:N3}->{combinedSavings.Expected:N3}.";
            return false;
        }

        private static bool TryAcceptAtlasValueBatch(
            BatchState state,
            IReadOnlyList<AtlasCandidate> batch,
            IReadOnlyList<MergeAffinityGroup> affinityGroups,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            out AtlasValueGateResidencyEstimate residency,
            out int rawDrawsEliminated,
            out double expectedArmyDrawsEliminated,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            residency = AtlasValueGateResidencyEstimate.Empty;
            rawDrawsEliminated = 0;
            expectedArmyDrawsEliminated = 0;
            rejectionReason = string.Empty;

            if (!TryEstimateIncrementalAtlasResidency(
                    state,
                    batch,
                    out residency))
            {
                rejectionReason = "incremental BCn residency could not be estimated safely.";
                return false;
            }

            var singletonBatches = new List<List<AtlasCandidate>>
            {
                batch.ToList()
            };
            var batchByMesh = BuildBatchIndexByMesh(singletonBatches);
            rawDrawsEliminated = CalculateMergeAffinityScore(
                singletonBatches,
                affinityGroups);
            if (rawDrawsEliminated <= 0)
            {
                rejectionReason = "no compatible mesh draw would be eliminated.";
                return false;
            }

            expectedArmyDrawsEliminated = CalculateExpectedArmyDrawCallsEliminated(
                state,
                batchByMesh,
                affinityGroups,
                expectedEntitiesByMesh);

            // Scenario-resolved batches must justify their BCn cost using scenario draw
            // savings. The much looser raw-draw fallback is reserved for assets whose
            // scenario relevance genuinely could not be resolved. A cumulative growth cap
            // prevents either path from quietly bloating the pack's total reachable BCn.
            var scenarioResolved = IsAtlasValueBatchScenarioResolved(state, batch);
            var globalCost = GetChargeableAtlasValueGateBytes(
                residency.GeneratedBcnBytes,
                residency.RetiredSourceBcnBytes);
            var expectedCost = GetChargeableAtlasValueGateBytes(
                residency.ExpectedArmyGeneratedBcnBytes,
                residency.ExpectedArmyRetiredSourceBcnBytes);
            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            var budgetDecision = EvaluateAtlasValueGateBudget(
                scenarioResolved,
                rawDrawsEliminated,
                expectedArmyDrawsEliminated,
                globalCost,
                expectedCost,
                state.AtlasValueGateNetBcnBytesAccepted,
                residency.NetBcnBytes,
                sourceBcnBytes);

            switch (budgetDecision)
            {
                case AtlasValueGateBudgetDecision.ScenarioResolvedZeroBenefit:
                    rejectionReason =
                        $"scenario-resolved batch has no modeled draw benefit but adds " +
                        $"{FormatMiB(globalCost)} chargeable BCn; the raw-draw fallback is " +
                        $"reserved for scenario-unresolved assets.";
                    return false;

                case AtlasValueGateBudgetDecision.FallbackBudgetExceeded:
                    var fallbackBytesPerDraw =
                        globalCost / Math.Max(rawDrawsEliminated, 1);
                    rejectionReason =
                        $"scenario relevance is unresolved; estimated incremental BCn generated " +
                        $"{FormatMiB(residency.GeneratedBcnBytes)}, retires " +
                        $"{FormatMiB(residency.RetiredSourceBcnBytes)}, net " +
                        $"{FormatMiB(residency.NetBcnBytes)}; net cost is " +
                        $"{FormatMiB(fallbackBytesPerDraw)} per raw draw eliminated, above the " +
                        $"{FormatMiB(MaxNetBcnBytesPerFallbackDraw, 2)} fallback budget.";
                    return false;

                case AtlasValueGateBudgetDecision.ScenarioBudgetExceeded:
                    var scenarioBytesPerDraw =
                        expectedCost /
                        Math.Max(
                            expectedArmyDrawsEliminated,
                            AtlasValueGateExpectedDrawEpsilon);
                    rejectionReason =
                        $"scenario-estimated incremental BCn resource payload generated " +
                        $"{FormatMiB(residency.ExpectedArmyGeneratedBcnBytes)}, retires " +
                        $"{FormatMiB(residency.ExpectedArmyRetiredSourceBcnBytes)}, net " +
                        $"{FormatMiB(residency.ExpectedArmyNetBcnBytes)}; net cost is " +
                        $"{FormatMiB(scenarioBytesPerDraw)} per scenario-estimated draw eliminated, above the " +
                        $"{FormatMiB(MaxNetBcnBytesPerExpectedArmyDraw, 2)} budget.";
                    return false;

                case AtlasValueGateBudgetDecision.GlobalGrowthCapExceeded:
                    var projectedNetGrowth =
                        state.AtlasValueGateNetBcnBytesAccepted +
                        (double)residency.NetBcnBytes;
                    var globalGrowthCap =
                        sourceBcnBytes * MaxReachableBcnGrowthRatio;
                    rejectionReason =
                        $"projected accepted net BCn growth {FormatMiB(projectedNetGrowth)} " +
                        $"would exceed the {MaxReachableBcnGrowthRatio:P0} source-payload cap " +
                        $"({FormatMiB(globalGrowthCap)}).";
                    return false;
            }

            return true;
        }

        private static bool TryAcceptTextureOnlyMergeAtlasBatch(
            BatchState state,
            AtlasValueGateGroupPlan plan,
            IReadOnlyDictionary<
                MeshKey,
                Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                expectedEntitiesByMesh,
            out AtlasValueGateResidencyEstimate residency,
            out int rawDrawsEliminated,
            out double expectedArmyDrawsEliminated,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            residency = AtlasValueGateResidencyEstimate.Empty;
            rawDrawsEliminated = 0;
            expectedArmyDrawsEliminated = 0;
            rejectionReason = string.Empty;
            var prospectiveTextureMergeDraws =
                GetAtlasValueGatePlanProspectiveTextureMergeDraws(plan);

            if (prospectiveTextureMergeDraws <= 0)
            {
                rejectionReason = "the merge group has no prospective texture-only compatibility.";
                return false;
            }

            var batch = plan.Candidates;
            if (batch.Count < 2 ||
                !TryEstimateIncrementalAtlasResidency(
                    state,
                    batch,
                    out residency))
            {
                rejectionReason =
                    batch.Count < 2
                        ? "fewer than two texture-compatible mesh candidates were available."
                        : "incremental BCn residency could not be estimated safely.";
                return false;
            }

            var singletonBatches = new List<List<AtlasCandidate>>
            {
                batch.ToList()
            };
            var batchByMesh = BuildBatchIndexByMesh(singletonBatches);
            var affinityGroups = plan.AffinityGroups;
            rawDrawsEliminated = CalculateMergeAffinityScore(
                singletonBatches,
                affinityGroups);
            expectedArmyDrawsEliminated = CalculateExpectedArmyDrawCallsEliminated(
                state,
                batchByMesh,
                affinityGroups,
                expectedEntitiesByMesh);

            var scenarioResolved = IsAtlasValueBatchScenarioResolved(state, batch);
            if (!IsAtlasValueCandidateAllowedForMode(
                    state.AtlasAllVmdsEnabled,
                    scenarioResolved))
            {
                rejectionReason =
                    "gameplay/scenario relevance could not be resolved safely.";
                return false;
            }

            var globalCost = GetChargeableAtlasValueGateBytes(
                residency.GeneratedBcnBytes,
                residency.RetiredSourceBcnBytes);
            var expectedCost = GetChargeableAtlasValueGateBytes(
                residency.ExpectedArmyGeneratedBcnBytes,
                residency.ExpectedArmyRetiredSourceBcnBytes);
            var packLocalRetirementCreditBytes =
                GetPackLocalOnlyRetirementCreditBytes(
                    residency.PackReferenceRetiredSourceTextureCount,
                    residency.RetiredSourceTextureCount);
            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            var budgetDecision = EvaluateTextureOnlyMergeAtlasValueGateBudget(
                scenarioResolved,
                prospectiveTextureMergeDraws,
                expectedArmyDrawsEliminated,
                globalCost,
                expectedCost,
                packLocalRetirementCreditBytes,
                state.AtlasValueGateNetBcnBytesAccepted,
                residency.NetBcnBytes,
                sourceBcnBytes);

            switch (budgetDecision)
            {
                case AtlasValueGateBudgetDecision.ScenarioResolvedZeroBenefit:
                    rejectionReason =
                        "texture-only merge has no modeled scenario draw benefit.";
                    return false;

                case AtlasValueGateBudgetDecision.TextureOnlyMergeBudgetExceeded:
                    var structuralBudgetBytes = prospectiveTextureMergeDraws *
                                                (double)MaxNetBcnBytesPerTextureOnlyMergeDraw;
                    var scenarioDrawBudgetBytes = expectedArmyDrawsEliminated *
                                                  MaxNetBcnBytesPerTextureOnlyMergeExpectedArmyDraw;
                    var effectiveScenarioBudgetBytes =
                        scenarioDrawBudgetBytes + packLocalRetirementCreditBytes;
                    var effectiveGlobalBudgetBytes = Math.Max(
                        structuralBudgetBytes,
                        scenarioDrawBudgetBytes);
                    rejectionReason =
                        $"texture-only merge credit exceeded: generated " +
                        $"{FormatMiB(residency.GeneratedBcnBytes)}, retires " +
                        $"{FormatMiB(residency.RetiredSourceBcnBytes)}, net " +
                        $"{FormatMiB(residency.NetBcnBytes)}; global chargeable cost is " +
                        $"{FormatMiB(globalCost)}, scenario chargeable cost is " +
                        $"{FormatMiB(expectedCost)}; structural credit is " +
                        $"{FormatMiB(structuralBudgetBytes, 2)}, scenario draw credit is " +
                        $"{FormatMiB(scenarioDrawBudgetBytes, 2)}, pack-local retirement " +
                        $"credit is {FormatMiB(packLocalRetirementCreditBytes, 2)}, effective " +
                        $"scenario credit is {FormatMiB(effectiveScenarioBudgetBytes, 2)}, and " +
                        $"the effective global credit is {FormatMiB(effectiveGlobalBudgetBytes, 2)}.";
                    return false;

                case AtlasValueGateBudgetDecision.GlobalGrowthCapExceeded:
                    var projectedNetGrowth =
                        state.AtlasValueGateNetBcnBytesAccepted +
                        (double)residency.NetBcnBytes;
                    var globalGrowthCap =
                        sourceBcnBytes * MaxReachableBcnGrowthRatio;
                    rejectionReason =
                        $"projected accepted net BCn growth {FormatMiB(projectedNetGrowth)} " +
                        $"would exceed the {MaxReachableBcnGrowthRatio:P0} source-payload cap " +
                        $"({FormatMiB(globalGrowthCap)}).";
                    return false;
            }

            return true;
        }

        private static bool TryAcceptTextureOnlyAtlasBatch(
            BatchState state,
            IReadOnlyList<AtlasCandidate> batch,
            out AtlasValueGateResidencyEstimate residency,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            residency = AtlasValueGateResidencyEstimate.Empty;
            rejectionReason = string.Empty;

            if (batch.Count < 2)
            {
                rejectionReason = "fewer than two non-merge candidates were available.";
                return false;
            }

            if (state.ArmyResidencyModel == null ||
                !IsAtlasValueBatchScenarioResolved(state, batch))
            {
                rejectionReason =
                    "texture-only retirement requires resolved gameplay/scenario relevance.";
                return false;
            }

            if (!TryEstimateIncrementalAtlasResidency(
                    state,
                    batch,
                    out residency))
            {
                rejectionReason =
                    "incremental BCn residency could not be estimated safely.";
                return false;
            }

            if (!HasSufficientTextureOnlyRetirement(
                    residency.PackReferenceRetiredSourceTextureCount,
                    residency.RetiredSourceTextureCount,
                    residency.RetiredSourceBcnBytes,
                    residency.ScenarioDisplacedSourceTextureCount,
                    residency.ExpectedArmyRetiredSourceTextureCount,
                    residency.ExpectedArmyRetiredSourceBcnBytes))
            {
                rejectionReason =
                    $"fewer than {MinimumRetiredSourceTexturesForTextureOnlyAtlas} " +
                    "source textures would have all source-pack references retired or be " +
                    "displaced from modeled battle residency.";
                return false;
            }

            var globalCost = GetChargeableAtlasValueGateBytes(
                residency.GeneratedBcnBytes,
                residency.RetiredSourceBcnBytes);
            var expectedCost = GetChargeableAtlasValueGateBytes(
                residency.ExpectedArmyGeneratedBcnBytes,
                residency.ExpectedArmyRetiredSourceBcnBytes);
            var globalBudgetTextureEquivalent = Math.Max(
                residency.PackReferenceRetiredSourceTextureCount,
                residency.ExpectedArmyRetiredSourceTextureCount);
            var globalBudget =
                globalBudgetTextureEquivalent *
                MaxNetBcnBytesPerRetiredSourceTexture;
            var packLocalRetirementCreditBytes =
                GetPackLocalOnlyRetirementCreditBytes(
                    residency.PackReferenceRetiredSourceTextureCount,
                    residency.RetiredSourceTextureCount);
            var expectedBudget =
                residency.ExpectedArmyRetiredSourceTextureCount *
                    MaxNetBcnBytesPerRetiredSourceTexture +
                packLocalRetirementCreditBytes;

            if (globalCost > globalBudget)
            {
                rejectionReason =
                    $"texture-only net cost {FormatMiB(globalCost)} exceeds " +
                    $"{FormatMiB(MaxNetBcnBytesPerRetiredSourceTexture, 2)} per " +
                    "retired source texture.";
                return false;
            }

            if (expectedCost > expectedBudget)
            {
                rejectionReason =
                    $"scenario-estimated texture-only net cost {FormatMiB(expectedCost)} " +
                    $"exceeds the effective retirement budget {FormatMiB(expectedBudget)} " +
                    $"(runtime displacement plus {FormatMiB(packLocalRetirementCreditBytes)} " +
                    "pack-local-only retirement credit).";
                return false;
            }

            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            if (sourceBcnBytes > 0)
            {
                var projectedNetGrowth =
                    state.AtlasValueGateNetBcnBytesAccepted +
                    (double)residency.NetBcnBytes;
                var globalGrowthCap = sourceBcnBytes * MaxReachableBcnGrowthRatio;
                if (projectedNetGrowth > globalGrowthCap)
                {
                    rejectionReason =
                        $"projected accepted net BCn growth {FormatMiB(projectedNetGrowth)} " +
                        $"would exceed the {MaxReachableBcnGrowthRatio:P0} source-payload cap " +
                        $"({FormatMiB(globalGrowthCap)}).";
                    return false;
                }
            }

            return true;
        }

        private static bool HasSufficientTextureOnlyRetirement(
            int packReferenceRetiredTextureCount,
            int physicallyRetiredTextureCount,
            long physicallyRetiredBcnBytes,
            int scenarioDisplacedTextureCount,
            double expectedRetiredTextureEquivalents,
            double expectedRetiredBcnBytes)
        {
            var hasPackReferenceRetirement =
                packReferenceRetiredTextureCount >=
                MinimumRetiredSourceTexturesForTextureOnlyAtlas;
            var hasPhysicalRetirement =
                physicallyRetiredTextureCount >=
                    MinimumRetiredSourceTexturesForTextureOnlyAtlas &&
                physicallyRetiredBcnBytes > 0;
            var hasScenarioDisplacement =
                scenarioDisplacedTextureCount >=
                    MinimumRetiredSourceTexturesForTextureOnlyAtlas &&
                expectedRetiredTextureEquivalents >= 1.0 &&
                expectedRetiredBcnBytes > 0;
            return hasPackReferenceRetirement ||
                   hasPhysicalRetirement ||
                   hasScenarioDisplacement;
        }

        private static List<TextureConsolidationCohortAcceptance>
            SelectTextureConsolidationCohorts(
                BatchState state,
                IReadOnlyList<AtlasCandidate> candidates,
                IReadOnlyDictionary<
                    MeshKey,
                    Dictionary<Wh3ArmyUnitCategory, Dictionary<string, double>>>
                    expectedEntitiesByMesh,
                out Dictionary<MeshKey, string> rejectionReasons)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            rejectionReasons = new Dictionary<MeshKey, string>();
            if (candidates.Count == 0)
                return [];

            var orderedCandidates = candidates
                .OrderBy(candidate => (long)candidate.Width * candidate.Height)
                .ThenBy(candidate => candidate.AtlasResolutionScale)
                .ThenBy(
                    candidate => BuildAtlasPlanningOrderKey(candidate),
                    StringComparer.OrdinalIgnoreCase)
                .ThenBy(
                    candidate => candidate.Key.ToString(),
                    StringComparer.OrdinalIgnoreCase)
                .ToList();
            var pending = new Queue<List<AtlasCandidate>>();
            for (var offset = 0;
                 offset < orderedCandidates.Count;
                 offset += TextureConsolidationInitialCohortCandidateLimit)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                pending.Enqueue(
                    orderedCandidates
                        .Skip(offset)
                        .Take(TextureConsolidationInitialCohortCandidateLimit)
                        .ToList());
            }

            var accepted = new List<TextureConsolidationCohortAcceptance>();
            while (pending.Count != 0)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var cohort = pending.Dequeue();
                state.AtlasValueGateTextureConsolidationCohortsEvaluated++;
                if (TryAcceptTextureConsolidationAtlasBatch(
                        state,
                        cohort,
                        out var residency,
                        out var consolidatedTextureAssignments,
                        out var rejectionReason))
                {
                    var acceptance = new TextureConsolidationCohortAcceptance(
                        cohort,
                        residency,
                        consolidatedTextureAssignments);
                    accepted.Add(acceptance);

                    // Commit each winning cohort before evaluating the next one. The
                    // consolidation gate depends on the accumulated generated BCn cost and
                    // rewritten source references, so evaluating all cohorts first can let
                    // independent cohorts jointly exceed the global growth cap or claim the
                    // same source-texture retirement.
                    RecordAtlasValueGateAccepted(
                        state,
                        acceptance.Candidates,
                        acceptance.Residency,
                        rawDrawsEliminated: 0,
                        expectedArmyDrawsEliminated: 0,
                        expectedEntitiesByMesh,
                        acceptanceKind: AtlasValueGateAcceptanceKind.TextureConsolidation,
                        consolidatedTextureAssignments:
                            acceptance.ConsolidatedTextureAssignments);
                    continue;
                }

                if (ShouldSplitTextureConsolidationCohort(
                        cohort,
                        rejectionReason))
                {
                    var splitIndex = cohort.Count / 2;
                    pending.Enqueue(cohort.Take(splitIndex).ToList());
                    pending.Enqueue(cohort.Skip(splitIndex).ToList());
                    state.AtlasValueGateTextureConsolidationCohortsSplit++;
                    continue;
                }

                foreach (var candidate in cohort)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    rejectionReasons[candidate.Key] = rejectionReason;
                }
            }

            return accepted;
        }

        private static bool ShouldSplitTextureConsolidationCohort(
            IReadOnlyList<AtlasCandidate> cohort,
            string rejectionReason)
        {
            if (cohort.Count <= 2)
                return false;

            return rejectionReason.Contains(
                       "net cost",
                       StringComparison.OrdinalIgnoreCase) ||
                   rejectionReason.Contains(
                       "source-payload cap",
                       StringComparison.OrdinalIgnoreCase) ||
                   rejectionReason.Contains(
                       "residency",
                       StringComparison.OrdinalIgnoreCase);
        }

        private static bool TryAcceptTextureConsolidationAtlasBatch(
            BatchState state,
            IReadOnlyList<AtlasCandidate> batch,
            out AtlasValueGateResidencyEstimate residency,
            out int consolidatedTextureAssignments,
            out string rejectionReason)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            residency = AtlasValueGateResidencyEstimate.Empty;
            consolidatedTextureAssignments = 0;
            rejectionReason = string.Empty;

            if (batch.Count < 2)
            {
                rejectionReason = "fewer than two non-merge candidates were available.";
                return false;
            }

            if (state.ArmyResidencyModel == null ||
                !IsAtlasValueBatchScenarioResolved(state, batch))
            {
                rejectionReason =
                    "texture consolidation requires resolved gameplay/scenario relevance.";
                return false;
            }

            if (!TryGetGeneratedAtlasBcnCost(
                    state,
                    batch,
                    out var generatedBcnBytes,
                    out var generatedBcnBytesBySlot) ||
                !TryEstimateIncrementalAtlasResidency(
                    state,
                    batch,
                    generatedBcnBytes,
                    generatedBcnBytesBySlot,
                    out residency))
            {
                rejectionReason =
                    "incremental BCn residency could not be estimated safely.";
                return false;
            }

            foreach (var channel in AtlasChannels)
            {
                if (!generatedBcnBytesBySlot.ContainsKey(channel.Slot))
                    continue;

                var distinctSourceAssignments = batch
                    .Where(candidate => candidate.ResolvedChannels.Contains(channel.Slot))
                    .Select(candidate => Normalize(
                        GetTexturePath(candidate.MaterialDocument, channel.Slot)))
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count();
                consolidatedTextureAssignments +=
                    Math.Max(0, distinctSourceAssignments - 1);
            }

            if (consolidatedTextureAssignments <
                MinimumConsolidatedTextureAssignmentsForAtlas)
            {
                rejectionReason =
                    "fewer than " +
                    MinimumConsolidatedTextureAssignmentsForAtlas +
                    " distinct texture assignments would be consolidated.";
                return false;
            }

            var globalCost = GetChargeableAtlasValueGateBytes(
                residency.GeneratedBcnBytes,
                residency.RetiredSourceBcnBytes);
            var expectedCost = GetChargeableAtlasValueGateBytes(
                residency.ExpectedArmyGeneratedBcnBytes,
                residency.ExpectedArmyRetiredSourceBcnBytes);
            var consolidationBudget =
                consolidatedTextureAssignments *
                (double)MaxNetBcnBytesPerConsolidatedTextureAssignment;

            if (globalCost > consolidationBudget)
            {
                rejectionReason =
                    "texture-consolidation net cost " +
                    FormatMiB(globalCost) +
                    " exceeds " +
                    FormatMiB(
                        MaxNetBcnBytesPerConsolidatedTextureAssignment,
                        2) +
                    " per consolidated texture assignment.";
                return false;
            }

            if (expectedCost > consolidationBudget)
            {
                rejectionReason =
                    "scenario-estimated texture-consolidation net cost " +
                    FormatMiB(expectedCost) +
                    " exceeds the per-assignment budget.";
                return false;
            }

            var sourceBcnBytes = state.SourceBcnResidency?.BcnBytes ?? 0;
            if (sourceBcnBytes > 0)
            {
                var projectedNetGrowth =
                    state.AtlasValueGateNetBcnBytesAccepted +
                    (double)residency.NetBcnBytes;
                var globalGrowthCap = sourceBcnBytes * MaxReachableBcnGrowthRatio;
                if (projectedNetGrowth > globalGrowthCap)
                {
                    rejectionReason =
                        "projected accepted net BCn growth " +
                        FormatMiB(projectedNetGrowth) +
                        " would exceed the " +
                        MaxReachableBcnGrowthRatio.ToString("P0") +
                        " source-payload cap (" +
                        FormatMiB(globalGrowthCap) +
                        ").";
                    return false;
                }
            }

            return true;
        }

        private static double GetChargeableAtlasValueGateBytes(
            double generatedBytes,
            double retiredSourceBytes)
            => Math.Max(0.0, generatedBytes - retiredSourceBytes);

        private static bool TryEstimateIncrementalAtlasResidency(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out AtlasValueGateResidencyEstimate estimate)
        {
            estimate = AtlasValueGateResidencyEstimate.Empty;
            if (!TryGetGeneratedAtlasBcnCost(
                    state,
                    candidates,
                    out var generatedBcnBytes,
                    out var generatedBcnBytesBySlot))
            {
                return false;
            }

            return TryEstimateIncrementalAtlasResidency(
                state,
                candidates,
                generatedBcnBytes,
                generatedBcnBytesBySlot,
                out estimate);
        }

        private static bool TryEstimateIncrementalAtlasResidency(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            long generatedBcnBytes,
            IReadOnlyDictionary<string, long> generatedBcnBytesBySlot,
            out AtlasValueGateResidencyEstimate estimate)
        {
            estimate = AtlasValueGateResidencyEstimate.Empty;
            state.CancellationToken.ThrowIfCancellationRequested();
            var sourceIndex = state.AtlasValueGateSourceTextureIndex ??
                BuildAtlasValueGateSourceTextureIndex(
                    state,
                    GetAtlasValueGateCandidateTexturePaths(candidates));
            state.AtlasValueGateSourceTextureIndex = sourceIndex;
            if (state.AtlasValueGateSourceTexturesByReference == null)
            {
                BuildAtlasValueGateSourceTextureReverseIndex(state, sourceIndex);
            }

            var proposedRewrites = new HashSet<AtlasValueGateSourceReference>();
            foreach (var candidate in candidates)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                foreach (var slot in generatedBcnBytesBySlot.Keys)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (!candidate.ResolvedChannels.Contains(slot) &&
                        !candidate.ConstantChannels.ContainsKey(slot))
                    {
                        continue;
                    }

                    var sourcePath = GetTexturePath(candidate.MaterialDocument, slot);
                    if (string.IsNullOrWhiteSpace(sourcePath))
                        continue;

                    sourcePath = Normalize(sourcePath);
                    if (!sourceIndex.TryGetValue(sourcePath, out var sourceTexture))
                        continue;

                    foreach (var usage in candidate.Usages)
                    {
                        var reference = new AtlasValueGateSourceReference(
                            candidate.Key,
                            Normalize(usage.AssetPath).ToLowerInvariant(),
                            slot.ToLowerInvariant(),
                            0,
                            string.IsNullOrWhiteSpace(usage.EmbeddedRigidPath)
                                ? AtlasValueGateSourceReferenceKind.WsModelMaterial
                                : AtlasValueGateSourceReferenceKind.RigidEmbedded);
                        if (sourceTexture.References.Contains(reference))
                            proposedRewrites.Add(reference);
                    }
                }
            }

            long retiredSourceBcnBytes = 0;
            var retiredSourceTextureCount = 0;
            var packReferenceRetiredSourceTextureCount = 0;
            double expectedArmyRetiredSourceBcnBytes = 0;
            double expectedArmyRetiredSourceTextureCount = 0;
            var scenarioDisplacedSourceTextureCount = 0;
            var sourceTextureResidencyDiagnostics =
                new List<AtlasValueGateSourceTextureResidencyDiagnostic>();
            IReadOnlyList<(string Path, AtlasValueGateSourceTexture Texture)> affectedSourceTextures;
            if (state.AtlasValueGateSourceTexturesByReference != null)
            {
                var affectedTexturePaths = new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase);
                foreach (var proposedReference in proposedRewrites)
                {
                    if (state.AtlasValueGateSourceTexturesByReference.TryGetValue(
                            proposedReference,
                            out var texturePaths))
                    {
                        affectedTexturePaths.UnionWith(texturePaths);
                    }
                }

                affectedSourceTextures = affectedTexturePaths
                    .Where(sourceIndex.ContainsKey)
                    .OrderBy(path => state.AtlasValueGateSourceTextureOrder.TryGetValue(
                        path,
                        out var order)
                        ? order
                        : int.MaxValue)
                    .ThenBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .Select(path => (Path: path, Texture: sourceIndex[path]))
                    .ToArray();
            }
            else
            {
                // Keep a conservative fallback for callers that provide a prebuilt source
                // index without its reverse index.
                affectedSourceTextures = sourceIndex
                    .Where(entry => entry.Value.References.Any(proposedRewrites.Contains))
                    .Select(entry => (Path: entry.Key, Texture: entry.Value))
                    .ToArray();
            }
            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                0,
                affectedSourceTextures.Count,
                "Evaluating affected source textures");
            for (var sourceTextureIndex = 0;
                 sourceTextureIndex < affectedSourceTextures.Count;
                 sourceTextureIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    sourceTextureIndex + 1,
                    affectedSourceTextures.Count,
                    "Evaluating affected source textures");
                var (sourceTexturePath, sourceTexture) =
                    affectedSourceTextures[sourceTextureIndex];

                var currentlyRewrittenReferenceCount =
                    GetAtlasValueGateRewrittenReferenceCount(
                        state,
                        sourceTexturePath,
                        sourceTexture);
                var newlyProposedReferenceCount = sourceTexture.References.Count(reference =>
                    !state.AtlasValueGateRewrittenSourceReferences.Contains(reference) &&
                    proposedRewrites.Contains(reference));
                var rewrittenReferenceCountAfterProposal = checked(
                    currentlyRewrittenReferenceCount + newlyProposedReferenceCount);
                var currentlyRewrittenPackReferenceCount =
                    GetAtlasValueGateRewrittenPackReferenceCount(
                        state,
                        sourceTexturePath,
                        sourceTexture);
                var newlyProposedPackReferenceCount = sourceTexture.PackReferences.Count(
                    reference =>
                        !state.AtlasValueGateRewrittenSourceReferences.Contains(reference) &&
                        proposedRewrites.Contains(reference));
                var rewrittenPackReferenceCountAfterProposal = checked(
                    currentlyRewrittenPackReferenceCount + newlyProposedPackReferenceCount);
                var currentlyPackReferencesRetired =
                    IsAtlasValueGatePackReferenceRetired(
                        sourceTexture.HasDirectSourcePackVmdReference,
                        sourceTexture.PackReferences.Count,
                        currentlyRewrittenPackReferenceCount);
                var packReferencesRetiredAfterProposal =
                    IsAtlasValueGatePackReferenceRetired(
                        sourceTexture.HasDirectSourcePackVmdReference,
                        sourceTexture.PackReferences.Count,
                        rewrittenPackReferenceCountAfterProposal);
                if (!currentlyPackReferencesRetired && packReferencesRetiredAfterProposal)
                    packReferenceRetiredSourceTextureCount++;
                var currentlyRetired = IsAtlasValueGateSourceTextureRetired(
                    sourceTexture.IsOwnedBySourcePack,
                    sourceTexture.HasDirectVmdReference,
                    sourceTexture.References.Count,
                    currentlyRewrittenReferenceCount);
                var retiredAfterProposal = IsAtlasValueGateSourceTextureRetired(
                    sourceTexture.IsOwnedBySourcePack,
                    sourceTexture.HasDirectVmdReference,
                    sourceTexture.References.Count,
                    rewrittenReferenceCountAfterProposal);
                if (!currentlyRetired && retiredAfterProposal)
                {
                    retiredSourceBcnBytes = checked(
                        retiredSourceBcnBytes + sourceTexture.BcnBytes);
                    retiredSourceTextureCount++;
                }

                var sourceTextureResidency = EvaluateAtlasValueGateSourceTextureResidency(
                    state,
                    sourceTexturePath,
                    sourceTexture,
                    state.AtlasValueGateRewrittenSourceReferences,
                    proposedRewrites,
                    currentlyRewrittenReferenceCount,
                    rewrittenReferenceCountAfterProposal);
                sourceTextureResidencyDiagnostics.Add(sourceTextureResidency);
                var expectedRetirement = sourceTextureResidency.ExpectedRetiredBcnBytes;
                expectedArmyRetiredSourceBcnBytes += expectedRetirement;
                if (expectedRetirement > AtlasValueGateExpectedDrawEpsilon)
                {
                    scenarioDisplacedSourceTextureCount++;
                    expectedArmyRetiredSourceTextureCount += Math.Clamp(
                        expectedRetirement / sourceTexture.BcnBytes,
                        0.0,
                        1.0);
                }
            }

            double expectedArmyGeneratedBcnBytes = 0;
            var rootsByMesh = BuildCandidateRootVmdPaths(state, candidates);
            foreach (var (slot, channelBytes) in generatedBcnBytesBySlot)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                var channelCandidates = candidates
                    .Where(candidate =>
                        candidate.ResolvedChannels.Contains(slot) ||
                        candidate.ConstantChannels.ContainsKey(slot))
                    .ToList();
                if (channelCandidates.Count == 0)
                    continue;

                var targetWsModels = channelCandidates
                    .SelectMany(candidate => candidate.Usages)
                    .Select(usage => Normalize(usage.AssetPath))
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                var roots = GetBatchRoots(channelCandidates, rootsByMesh);
                var residentProbability = GetExpectedArmyResidentProbability(
                    state,
                    targetWsModels,
                    roots);
                expectedArmyGeneratedBcnBytes +=
                    channelBytes * residentProbability;
            }

            estimate = new AtlasValueGateResidencyEstimate(
                generatedBcnBytes,
                retiredSourceBcnBytes,
                checked(generatedBcnBytes - retiredSourceBcnBytes),
                retiredSourceTextureCount,
                packReferenceRetiredSourceTextureCount,
                scenarioDisplacedSourceTextureCount,
                expectedArmyRetiredSourceTextureCount,
                expectedArmyGeneratedBcnBytes,
                expectedArmyRetiredSourceBcnBytes,
                expectedArmyGeneratedBcnBytes - expectedArmyRetiredSourceBcnBytes,
                proposedRewrites,
                sourceTextureResidencyDiagnostics);
            return true;
        }

        private static bool IsAtlasValueGatePackReferenceRetired(
            bool hasDirectSourcePackVmdReference,
            int packReferenceCount,
            int rewrittenPackReferenceCount)
            => !hasDirectSourcePackVmdReference &&
               packReferenceCount > 0 &&
               rewrittenPackReferenceCount >= packReferenceCount;

        private static bool IsAtlasValueGateSourceTextureRetired(
            bool isOwnedBySourcePack,
            bool hasDirectVmdReference,
            int referenceCount,
            int rewrittenReferenceCount)
            => isOwnedBySourcePack &&
               !hasDirectVmdReference &&
               referenceCount > 0 &&
               rewrittenReferenceCount >= referenceCount;

        private static int GetAtlasValueGateRewrittenReferenceCount(
            BatchState state,
            string texturePath,
            AtlasValueGateSourceTexture sourceTexture)
        {
            texturePath = Normalize(texturePath);
            if (state.AtlasValueGateRewrittenReferenceCountByTexture.TryGetValue(
                    texturePath,
                    out var cachedCount))
            {
                return cachedCount;
            }

            var count = sourceTexture.References.Count(
                state.AtlasValueGateRewrittenSourceReferences.Contains);
            state.AtlasValueGateRewrittenReferenceCountByTexture[texturePath] = count;
            return count;
        }

        private static int GetAtlasValueGateRewrittenPackReferenceCount(
            BatchState state,
            string texturePath,
            AtlasValueGateSourceTexture sourceTexture)
        {
            texturePath = Normalize(texturePath);
            if (state.AtlasValueGateRewrittenPackReferenceCountByTexture.TryGetValue(
                    texturePath,
                    out var cachedCount))
            {
                return cachedCount;
            }

            var count = sourceTexture.PackReferences.Count(
                state.AtlasValueGateRewrittenSourceReferences.Contains);
            state.AtlasValueGateRewrittenPackReferenceCountByTexture[texturePath] = count;
            return count;
        }

        private static void AddAtlasValueGateRewrittenReferences(
            BatchState state,
            IEnumerable<AtlasValueGateSourceReference> references)
        {
            var countBefore = state.AtlasValueGateRewrittenSourceReferences.Count;
            state.AtlasValueGateRewrittenSourceReferences.UnionWith(references);
            if (state.AtlasValueGateRewrittenSourceReferences.Count != countBefore)
            {
                state.AtlasValueGateRewrittenReferenceCountByTexture.Clear();
                state.AtlasValueGateRewrittenPackReferenceCountByTexture.Clear();
            }
        }

        private static AtlasValueGateSourceTextureResidencyDiagnostic
            EvaluateAtlasValueGateSourceTextureResidency(
                BatchState state,
                string texturePath,
                AtlasValueGateSourceTexture sourceTexture,
                IReadOnlySet<AtlasValueGateSourceReference> existingRewrites,
                IReadOnlySet<AtlasValueGateSourceReference>? proposedRewrites,
                int currentlyRewrittenReferenceCount,
                int rewrittenReferenceCountAfterProposal)
        {
            var currentProjection =
                BuildAtlasValueGateScenarioConsumerProjection(
                    state,
                    sourceTexture.References,
                    existingRewrites,
                    proposedRewrites: null);
            var proposedProjection =
                BuildAtlasValueGateScenarioConsumerProjection(
                    state,
                    sourceTexture.References,
                    existingRewrites,
                    proposedRewrites);
            var currentConsumerPaths =
                GetAtlasValueGateScenarioConsumerDisplayPaths(currentProjection);
            var proposedConsumerPaths =
                GetAtlasValueGateScenarioConsumerDisplayPaths(proposedProjection);
            var currentProjectionSummary =
                FormatAtlasValueGateScenarioConsumerProjection(currentProjection);
            var proposedProjectionSummary =
                FormatAtlasValueGateScenarioConsumerProjection(proposedProjection);

            if (sourceTexture.BcnBytes <= 0)
            {
                return new AtlasValueGateSourceTextureResidencyDiagnostic(
                    texturePath,
                    sourceTexture.BcnBytes,
                    sourceTexture.IsOwnedBySourcePack,
                    sourceTexture.HasDirectVmdReference,
                    sourceTexture.HasDirectSourcePackVmdReference,
                    sourceTexture.References.Count,
                    currentlyRewrittenReferenceCount,
                    rewrittenReferenceCountAfterProposal,
                    true,
                    0,
                    0,
                    0,
                    0,
                    0,
                    currentConsumerPaths,
                    proposedConsumerPaths)
                {
                    CurrentScenarioProjection = currentProjectionSummary,
                    ProposedScenarioProjection = proposedProjectionSummary,
                };
            }

            // Direct VMD texture references (for example decal diffuse/normal) are not
            // rewritten by material atlasing. We do not currently model their exact army
            // probability separately, so conservatively keep the full source texture
            // resident in both the current and proposed estimates. This guarantees that
            // such a reference can never create false scenario-estimated retirement credit.
            if (sourceTexture.HasDirectVmdReference)
            {
                return new AtlasValueGateSourceTextureResidencyDiagnostic(
                    texturePath,
                    sourceTexture.BcnBytes,
                    sourceTexture.IsOwnedBySourcePack,
                    sourceTexture.HasDirectVmdReference,
                    sourceTexture.HasDirectSourcePackVmdReference,
                    sourceTexture.References.Count,
                    currentlyRewrittenReferenceCount,
                    rewrittenReferenceCountAfterProposal,
                    true,
                    1.0,
                    1.0,
                    sourceTexture.BcnBytes,
                    sourceTexture.BcnBytes,
                    0,
                    currentConsumerPaths,
                    proposedConsumerPaths)
                {
                    CurrentScenarioProjection = currentProjectionSummary,
                    ProposedScenarioProjection = proposedProjectionSummary,
                };
            }

            var currentProbability =
                GetExpectedArmySourceTextureConsumerProbability(
                    state,
                    currentProjection);
            var proposedProbability =
                GetExpectedArmySourceTextureConsumerProbability(
                    state,
                    proposedProjection);
            var consumerMappingResolved =
                currentProbability.IsResolved && proposedProbability.IsResolved;
            if (!consumerMappingResolved)
            {
                // If either side contains an unresolved consumer/culture mapping, do not
                // infer that removing that reference retires any scenario residency. Keep
                // both sides at full BCn residency until the complete mapping is known.
                currentProbability = new AtlasValueGateSourceTextureConsumerProbability(
                    1.0,
                    false);
                proposedProbability = new AtlasValueGateSourceTextureConsumerProbability(
                    1.0,
                    false);
            }
            var currentExpectedResidency =
                sourceTexture.BcnBytes * currentProbability.Probability;
            var proposedExpectedResidency =
                sourceTexture.BcnBytes * proposedProbability.Probability;
            var expectedRetirement = CalculateAtlasValueGateScenarioRetirement(
                sourceTexture.BcnBytes,
                currentProbability.Probability,
                proposedProbability.Probability);

            return new AtlasValueGateSourceTextureResidencyDiagnostic(
                texturePath,
                sourceTexture.BcnBytes,
                sourceTexture.IsOwnedBySourcePack,
                sourceTexture.HasDirectVmdReference,
                sourceTexture.HasDirectSourcePackVmdReference,
                sourceTexture.References.Count,
                currentlyRewrittenReferenceCount,
                rewrittenReferenceCountAfterProposal,
                consumerMappingResolved,
                currentProbability.Probability,
                proposedProbability.Probability,
                currentExpectedResidency,
                proposedExpectedResidency,
                expectedRetirement,
                currentConsumerPaths,
                proposedConsumerPaths)
            {
                CurrentScenarioProjection = currentProjectionSummary,
                ProposedScenarioProjection = proposedProjectionSummary,
            };
        }

        private static AtlasValueGateScenarioConsumerProjection
            BuildAtlasValueGateScenarioConsumerProjection(
                BatchState state,
                IEnumerable<AtlasValueGateSourceReference> references,
                IReadOnlySet<AtlasValueGateSourceReference> existingRewrites,
                IReadOnlySet<AtlasValueGateSourceReference>? proposedRewrites)
        {
            var targetAssetPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var fallbackVmdRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var geometryOnlyRigidPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var directRigidPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var unresolvedConsumers = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var unresolvedReasons = new HashSet<string>(StringComparer.Ordinal);

            foreach (var reference in references)
            {
                if (existingRewrites.Contains(reference) ||
                    (proposedRewrites != null && proposedRewrites.Contains(reference)))
                {
                    continue;
                }

                var consumerPath = Normalize(reference.ConsumerAssetPath);
                if (consumerPath.Length == 0)
                {
                    unresolvedConsumers.Add("<empty>");
                    unresolvedReasons.Add("EmptyConsumerAssetPath");
                    continue;
                }

                if (reference.Kind == AtlasValueGateSourceReferenceKind.WsModelMaterial)
                {
                    targetAssetPaths.Add(consumerPath);
                    continue;
                }

                if (reference.Kind != AtlasValueGateSourceReferenceKind.RigidEmbedded)
                {
                    unresolvedConsumers.Add(consumerPath);
                    unresolvedReasons.Add(
                        $"UnknownReferenceKind:{reference.Kind}:{consumerPath}");
                    continue;
                }

                var classification = ClassifyAtlasValueGateRigidConsumer(
                    state,
                    consumerPath,
                    out var classificationReason);
                switch (classification)
                {
                    case AtlasValueGateRigidConsumerClassification.GeometryOnlyProven:
                        geometryOnlyRigidPaths.Add(consumerPath);
                        break;

                    case AtlasValueGateRigidConsumerClassification.DirectRigid:
                        directRigidPaths.Add(consumerPath);
                        if (state.GameplayMeshDependencyIndex == null ||
                            !state.GameplayMeshDependencyIndex.DirectConsumersByRigid.TryGetValue(
                                consumerPath,
                                out var directRoots) ||
                            directRoots.Count == 0)
                        {
                            unresolvedConsumers.Add(consumerPath);
                            unresolvedReasons.Add(
                                $"DirectConsumerRootsUnavailable:{consumerPath}");
                            break;
                        }

                        foreach (var root in directRoots.OrderBy(
                                     value => value,
                                     StringComparer.OrdinalIgnoreCase))
                        {
                            var normalizedRoot = Normalize(root);
                            var extension = Path.GetExtension(normalizedRoot);
                            if (extension.Equals(
                                    ".variantmeshdefinition",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                fallbackVmdRoots.Add(normalizedRoot);
                            }
                            else if (extension.Equals(
                                         ".wsmodel",
                                         StringComparison.OrdinalIgnoreCase) ||
                                     extension.Equals(
                                         ".rigid_model_v2",
                                         StringComparison.OrdinalIgnoreCase))
                            {
                                targetAssetPaths.Add(normalizedRoot);
                            }
                            else
                            {
                                unresolvedConsumers.Add(consumerPath);
                                unresolvedReasons.Add(
                                    $"UnsupportedDirectConsumerRoot:{consumerPath}->{normalizedRoot}");
                            }
                        }

                        break;

                    default:
                        unresolvedConsumers.Add(consumerPath);
                        unresolvedReasons.Add(
                            classificationReason.Length == 0
                                ? $"UnknownRigidConsumer:{consumerPath}"
                                : classificationReason);
                        break;
                }
            }

            return new AtlasValueGateScenarioConsumerProjection(
                targetAssetPaths
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                fallbackVmdRoots
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                geometryOnlyRigidPaths
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                directRigidPaths
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                unresolvedConsumers
                    .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                unresolvedReasons
                    .OrderBy(reason => reason, StringComparer.Ordinal)
                    .ToArray());
        }

        private static AtlasValueGateRigidConsumerClassification
            ClassifyAtlasValueGateRigidConsumer(
                BatchState state,
                string rigidPathValue,
                out string reason)
        {
            var rigidPath = Normalize(rigidPathValue);
            reason = string.Empty;
            var dependencyIndex = state.GameplayMeshDependencyIndex;
            if (dependencyIndex == null)
            {
                reason = $"GameplayDependencyIndexUnavailable:{rigidPath}";
                return AtlasValueGateRigidConsumerClassification.Unknown;
            }

            if (state.UnitCategoryResolution?.IsGameplayResolutionHealthy != true)
            {
                reason = $"GameplayResolutionUnhealthy:{rigidPath}";
                return AtlasValueGateRigidConsumerClassification.Unknown;
            }

            if (dependencyIndex.IsAssetAffectedByIncompleteRoot(rigidPath))
            {
                var incompleteRoots = dependencyIndex
                    .GetIncompleteRootsForAsset(rigidPath);
                reason = incompleteRoots.Count == 0
                    ? $"ConsumerTopologyUnobserved:{rigidPath}"
                    : $"DiscoveryIncomplete:{rigidPath}<-" +
                      string.Join(",", incompleteRoots);
                return AtlasValueGateRigidConsumerClassification.Unknown;
            }

            if (dependencyIndex.DirectConsumersByRigid.TryGetValue(
                    rigidPath,
                    out var directConsumers) &&
                directConsumers.Count != 0)
            {
                return AtlasValueGateRigidConsumerClassification.DirectRigid;
            }

            return AtlasValueGateRigidConsumerClassification.GeometryOnlyProven;
        }

        private static string[] GetAtlasValueGateScenarioConsumerDisplayPaths(
            AtlasValueGateScenarioConsumerProjection projection)
            => projection.TargetAssetPaths
                .Select(path => $"target:{path}")
                .Concat(projection.FallbackVmdRoots.Select(path => $"fallback-vmd:{path}"))
                .Concat(projection.GeometryOnlyRigidPaths.Select(
                    path => $"geometry-only-excluded:{path}"))
                .Concat(projection.DirectRigidPaths.Select(path => $"direct-rigid:{path}"))
                .Concat(projection.UnresolvedConsumers.Select(path => $"unknown:{path}"))
                .ToArray();

        private static string FormatAtlasValueGateScenarioConsumerProjection(
            AtlasValueGateScenarioConsumerProjection projection)
        {
            var summary =
                $"targets={projection.TargetAssetPaths.Count}, " +
                $"fallback-vmd-roots={projection.FallbackVmdRoots.Count}, " +
                $"geometry-only-excluded={projection.GeometryOnlyRigidPaths.Count}, " +
                $"direct-rigid={projection.DirectRigidPaths.Count}, " +
                $"unknown={projection.UnresolvedConsumers.Count}";
            if (projection.UnresolvedReasons.Count != 0)
            {
                summary += "; reasons=" + string.Join(
                    " | ",
                    projection.UnresolvedReasons.Take(4));
                if (projection.UnresolvedReasons.Count > 4)
                    summary += $" | ... (+{projection.UnresolvedReasons.Count - 4:N0})";
            }

            return summary;
        }

        private static AtlasValueGateSourceTextureConsumerProbability
            GetExpectedArmySourceTextureConsumerProbability(
                BatchState state,
                AtlasValueGateScenarioConsumerProjection projection)
        {
            if (!projection.IsResolved)
            {
                return new AtlasValueGateSourceTextureConsumerProbability(
                    1.0,
                    false);
            }

            if (projection.TargetAssetPaths.Count == 0 &&
                projection.FallbackVmdRoots.Count == 0)
            {
                return new AtlasValueGateSourceTextureConsumerProbability(0, true);
            }

            var model = state.ArmyResidencyModel;
            if (model == null || model.PlayerCultureWeights.Count == 0)
            {
                return new AtlasValueGateSourceTextureConsumerProbability(
                    1.0,
                    false);
            }

            foreach (var targetAssetPath in projection.TargetAssetPaths)
            {
                if (!model.UnitIdsByAssetPath.TryGetValue(
                        Normalize(targetAssetPath),
                        out var unitIds) ||
                    unitIds.Count == 0 ||
                    !unitIds.Any(unitId =>
                        model.CulturesByUnit.TryGetValue(unitId, out var cultures) &&
                        cultures.Count != 0))
                {
                    return new AtlasValueGateSourceTextureConsumerProbability(
                        1.0,
                        false);
                }
            }

            foreach (var fallbackRoot in projection.FallbackVmdRoots)
            {
                if (!model.UnitsByVmd.TryGetValue(
                        Normalize(fallbackRoot),
                        out var unitsByCategory) ||
                    unitsByCategory.Count == 0 ||
                    !unitsByCategory.Values
                        .SelectMany(unitIds => unitIds)
                        .Any(unitId =>
                            model.CulturesByUnit.TryGetValue(
                                unitId,
                                out var cultures) &&
                            cultures.Count != 0))
                {
                    return new AtlasValueGateSourceTextureConsumerProbability(
                        1.0,
                        false);
                }
            }

            var probability = GetExpectedArmyResidentProbability(
                state,
                projection.TargetAssetPaths,
                projection.FallbackVmdRoots);
            return new AtlasValueGateSourceTextureConsumerProbability(
                Math.Clamp(probability, 0.0, 1.0),
                true);
        }

        private static double CalculateAtlasValueGateScenarioRetirement(
            double bcnBytes,
            double currentResidentProbability,
            double proposedResidentProbability)
        {
            if (bcnBytes <= 0 ||
                !double.IsFinite(bcnBytes) ||
                !double.IsFinite(currentResidentProbability) ||
                !double.IsFinite(proposedResidentProbability))
            {
                return 0;
            }

            return bcnBytes * Math.Max(
                0.0,
                Math.Clamp(currentResidentProbability, 0.0, 1.0) -
                Math.Clamp(proposedResidentProbability, 0.0, 1.0));
        }

        private static bool TryGetWsModelConsumerEntry(
            BatchState state,
            IPackFileContainer container,
            string wsModelPath,
            PackFile file,
            out VanillaWsModelConsumerEntry entry)
        {
            wsModelPath = Normalize(wsModelPath);
            if (state.WsModelConsumerEntries.TryGetValue(wsModelPath, out entry!))
            {
                state.WsModelConsumerCacheHits++;
                state.WsModelConsumerMemoryCacheHits++;
                ReplayXmlCompatibilityRepairs(
                    state,
                    wsModelPath,
                    entry.CompatibilityRepairs);
                return true;
            }

            var cache = state.VanillaAtlasConsumerCache;
            if (IsVanillaAtlasCacheContainer(state, container) &&
                cache?.TryGetWsModel(container, wsModelPath, out entry) == true)
            {
                state.WsModelConsumerCacheHits++;
                state.WsModelConsumerVanillaCacheHits++;
                state.WsModelConsumerEntries[wsModelPath] = entry;
                ReplayXmlCompatibilityRepairs(
                    state,
                    wsModelPath,
                    entry.CompatibilityRepairs);
                return true;
            }

            state.WsModelConsumerCacheMisses++;
            if (!TryGetWsDocumentForTraversal(
                    state,
                    container,
                    wsModelPath,
                    file,
                    out var document))
            {
                entry = null!;
                return false;
            }

            entry = BuildWsModelConsumerEntry(document);
            state.WsModelConsumerEntryBuilds++;
            entry.CompatibilityRepairs =
                GetRecordedXmlCompatibilityRepairs(state, wsModelPath);
            state.WsModelConsumerEntries[wsModelPath] = entry;
            if (IsVanillaAtlasCacheContainer(state, container))
                cache?.SetWsModel(container, wsModelPath, entry);
            return true;
        }

        private static bool TryGetMaterialConsumerEntry(
            BatchState state,
            IPackFileContainer container,
            string materialPath,
            PackFile file,
            out VanillaMaterialConsumerEntry entry)
        {
            materialPath = Normalize(materialPath);
            if (state.MaterialConsumerEntries.TryGetValue(materialPath, out entry!))
            {
                state.MaterialConsumerCacheHits++;
                state.MaterialConsumerMemoryCacheHits++;
                ReplayXmlCompatibilityRepairs(
                    state,
                    materialPath,
                    entry.CompatibilityRepairs);
                return true;
            }

            var cache = state.VanillaAtlasConsumerCache;
            if (IsVanillaAtlasCacheContainer(state, container) &&
                cache?.TryGetMaterial(container, materialPath, out entry) == true)
            {
                state.MaterialConsumerCacheHits++;
                state.MaterialConsumerVanillaCacheHits++;
                state.MaterialConsumerEntries[materialPath] = entry;
                ReplayXmlCompatibilityRepairs(
                    state,
                    materialPath,
                    entry.CompatibilityRepairs);
                return true;
            }

            state.MaterialConsumerCacheMisses++;
            if (!TryGetMaterialDocumentForTraversal(
                    state,
                    container,
                    materialPath,
                    file,
                    out var document))
            {
                entry = null!;
                return false;
            }

            entry = BuildMaterialConsumerEntry(document);
            state.MaterialConsumerEntryBuilds++;
            entry.CompatibilityRepairs =
                GetRecordedXmlCompatibilityRepairs(state, materialPath);
            state.MaterialConsumerEntries[materialPath] = entry;
            if (IsVanillaAtlasCacheContainer(state, container))
                cache?.SetMaterial(container, materialPath, entry);
            return true;
        }

        private static bool TryGetVanillaCachedWsModelConsumerEntry(
            BatchState state,
            IPackFileContainer container,
            string wsModelPath,
            out VanillaWsModelConsumerEntry entry)
        {
            entry = null!;
            if (!IsVanillaAtlasCacheContainer(state, container) ||
                state.VanillaAtlasConsumerCache?.TryGetWsModel(
                    container,
                    wsModelPath,
                    out entry) != true)
            {
                return false;
            }

            state.WsModelConsumerCacheHits++;
            state.WsModelConsumerVanillaCacheHits++;
            state.WsModelConsumerEntries[Normalize(wsModelPath)] = entry;
            ReplayXmlCompatibilityRepairs(
                state,
                wsModelPath,
                entry.CompatibilityRepairs);
            return true;
        }

        private static bool TryGetVanillaCachedMaterialConsumerEntry(
            BatchState state,
            IPackFileContainer container,
            string materialPath,
            out VanillaMaterialConsumerEntry entry)
        {
            entry = null!;
            if (!IsVanillaAtlasCacheContainer(state, container) ||
                state.VanillaAtlasConsumerCache?.TryGetMaterial(
                    container,
                    materialPath,
                    out entry) != true)
            {
                return false;
            }

            state.MaterialConsumerCacheHits++;
            state.MaterialConsumerVanillaCacheHits++;
            state.MaterialConsumerEntries[Normalize(materialPath)] = entry;
            ReplayXmlCompatibilityRepairs(
                state,
                materialPath,
                entry.CompatibilityRepairs);
            return true;
        }

        private static bool TryGetRigidConsumerEntry(
            BatchState state,
            IPackFileContainer container,
            string rigidPath,
            PackFile file,
            out VanillaRigidConsumerEntry entry)
        {
            rigidPath = Normalize(rigidPath);
            var cache = state.VanillaAtlasConsumerCache;
            if (IsVanillaAtlasCacheContainer(state, container) &&
                cache?.TryGetRigid(container, rigidPath, out entry) == true)
            {
                return true;
            }

            try
            {
                var rigid = ModelFactory.Create().Load(file.DataSource.ReadData());
                entry = BuildRigidConsumerEntry(rigid);
                if (IsVanillaAtlasCacheContainer(state, container))
                    cache?.SetRigid(container, rigidPath, entry);
                return true;
            }
            catch
            {
                entry = null!;
                return false;
            }
        }

        private static bool IsVanillaAtlasCacheContainer(
            BatchState state,
            IPackFileContainer container)
            => container.IsCaPackFile && !ReferenceEquals(container, state.Source);

        private static List<string> GetRecordedXmlCompatibilityRepairs(
            BatchState state,
            string pathValue)
        {
            var path = Normalize(pathValue);
            return state.XmlCompatibilityRepairs.TryGetValue(path, out var repairs)
                ? repairs.OrderBy(repair => repair, StringComparer.Ordinal).ToList()
                : [];
        }

        private static void ReplayXmlCompatibilityRepairs(
            BatchState state,
            string pathValue,
            IReadOnlyList<string> repairs)
        {
            if (repairs.Count == 0)
                return;

            RecordXmlCompatibilityRepairs(state, pathValue, repairs);
        }

        private static VanillaWsModelConsumerEntry BuildWsModelConsumerEntry(
            XmlDocument document)
        {
            var entry = new VanillaWsModelConsumerEntry
            {
                GeometryPath = Normalize(
                    document.SelectSingleNode("/model/geometry")?.InnerText),
            };
            var materialNodes = document.SelectNodes("/model/materials/material");
            if (materialNodes == null)
                return entry;

            foreach (XmlNode materialNode in materialNodes)
            {
                var materialPath = Normalize(materialNode.InnerText);
                if (materialPath.Length == 0)
                    continue;

                entry.Materials.Add(new VanillaWsModelMaterialBinding
                {
                    MaterialPath = materialPath,
                    LodIndex = TryParseIndex(materialNode, "lod_index", out var lodIndex)
                        ? lodIndex
                        : null,
                    PartIndex = TryParseIndex(materialNode, "part_index", out var partIndex)
                        ? partIndex
                        : null,
                });
            }

            return entry;
        }

        private static VanillaMaterialConsumerEntry BuildMaterialConsumerEntry(
            XmlDocument document)
        {
            var entry = new VanillaMaterialConsumerEntry();
            var textureNodes = document.SelectNodes("/material/textures/texture");
            if (textureNodes == null)
                return entry;

            var occurrenceBySlot = new Dictionary<string, int>(
                StringComparer.OrdinalIgnoreCase);
            foreach (XmlNode textureNode in textureNodes)
            {
                var slot = GetTextureSlot(textureNode);
                var normalizedSlot = string.IsNullOrWhiteSpace(slot)
                    ? "__unslotted__"
                    : slot.ToLowerInvariant();
                var slotOccurrence = occurrenceBySlot.GetValueOrDefault(normalizedSlot);
                occurrenceBySlot[normalizedSlot] = slotOccurrence + 1;

                var texturePath = Normalize(
                    textureNode.SelectSingleNode("source")?.InnerText ??
                    textureNode.InnerText);
                if (texturePath.Length == 0)
                    continue;

                entry.Textures.Add(new VanillaMaterialTextureReference
                {
                    TexturePath = texturePath,
                    Slot = normalizedSlot,
                    SlotOccurrence = slotOccurrence,
                });
            }

            return entry;
        }

        private static VanillaRigidConsumerEntry BuildRigidConsumerEntry(
            RmvFile rigid)
        {
            var entry = new VanillaRigidConsumerEntry();
            for (var lodIndex = 0; lodIndex < rigid.ModelList.Length; lodIndex++)
            {
                for (var partIndex = 0;
                     partIndex < rigid.ModelList[lodIndex].Length;
                     partIndex++)
                {
                    var material = BuildEmbeddedMaterialDocument(
                        rigid.ModelList[lodIndex][partIndex].Material);
                    var materialEntry = BuildMaterialConsumerEntry(material);
                    foreach (var texture in materialEntry.Textures)
                    {
                        entry.Textures.Add(new VanillaRigidTextureReference
                        {
                            TexturePath = texture.TexturePath,
                            LodIndex = lodIndex,
                            PartIndex = partIndex,
                            Slot = texture.Slot,
                            SlotOccurrence = texture.SlotOccurrence,
                        });
                    }
                }
            }

            return entry;
        }

        private static bool IsAtlasValueGateSourcePackReference(
            BatchState state,
            AtlasValueGateSourceReference reference)
        {
            var consumerPath = Normalize(reference.ConsumerAssetPath);
            return consumerPath.Length != 0 && state.Source.ContainsFile(consumerPath);
        }

        private static Dictionary<string, AtlasValueGateSourceTexture>
            BuildAtlasValueGateSourceTextureIndex(
                BatchState state,
                IReadOnlySet<string>? targetTexturePaths = null)
        {
            state.CancellationToken.ThrowIfCancellationRequested();
            var containerResolutionScansBefore =
                state.GameplayTraversalContainerResolutionScans;
            var containerResolutionCacheHitsBefore =
                state.GameplayTraversalContainerResolutionCacheHits;
            var wsModelConsumerCacheHitsBefore = state.WsModelConsumerCacheHits;
            var wsModelConsumerMemoryCacheHitsBefore = state.WsModelConsumerMemoryCacheHits;
            var wsModelConsumerVanillaCacheHitsBefore = state.WsModelConsumerVanillaCacheHits;
            var wsModelConsumerCacheMissesBefore = state.WsModelConsumerCacheMisses;
            var wsModelConsumerEntryBuildsBefore = state.WsModelConsumerEntryBuilds;
            var materialConsumerCacheHitsBefore = state.MaterialConsumerCacheHits;
            var materialConsumerMemoryCacheHitsBefore = state.MaterialConsumerMemoryCacheHits;
            var materialConsumerVanillaCacheHitsBefore = state.MaterialConsumerVanillaCacheHits;
            var materialConsumerCacheMissesBefore = state.MaterialConsumerCacheMisses;
            var materialConsumerEntryBuildsBefore = state.MaterialConsumerEntryBuilds;
            var wsModelXmlParseCountBefore = state.GameplayTraversalWsModelXmlParseCount;
            var materialXmlParseCountBefore = state.GameplayTraversalMaterialXmlParseCount;
            var wsModelIndexStopwatch = Stopwatch.StartNew();
            var loadedContainers = GetGameplayTraversalContainers(state);
            var referencesByTexture =
                new Dictionary<string, HashSet<AtlasValueGateSourceReference>>(
                    StringComparer.OrdinalIgnoreCase);
            var packReferencesByTexture =
                new Dictionary<string, HashSet<AtlasValueGateSourceReference>>(
                    StringComparer.OrdinalIgnoreCase);
            var textureFiles = new Dictionary<
                string,
                (PackFile File, bool IsOwnedBySourcePack)>(
                StringComparer.OrdinalIgnoreCase);

            bool TryResolveTexture(
                string texturePathValue,
                out string texturePath,
                out PackFile textureFile,
                out bool isOwnedBySourcePack)
            {
                texturePath = Normalize(texturePathValue);
                textureFile = null!;
                isOwnedBySourcePack = false;
                if (texturePath.Length == 0 ||
                    IsTexturePlaceholder(texturePath) ||
                    (targetTexturePaths != null &&
                     !targetTexturePaths.Contains(texturePath)))
                {
                    return false;
                }

                var textureContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    loadedContainers,
                    texturePath);
                var resolvedFile = textureContainer?.FindFile(texturePath);
                if (textureContainer == null || resolvedFile == null)
                    return false;

                textureFile = resolvedFile;
                isOwnedBySourcePack = ReferenceEquals(textureContainer, state.Source);
                textureFiles[texturePath] = (textureFile, isOwnedBySourcePack);
                return true;
            }

            void AddReference(
                string texturePath,
                AtlasValueGateSourceReference reference)
            {
                if (!referencesByTexture.TryGetValue(texturePath, out var references))
                {
                    references = [];
                    referencesByTexture[texturePath] = references;
                }

                references.Add(reference);
                if (IsAtlasValueGateSourcePackReference(state, reference))
                {
                    if (!packReferencesByTexture.TryGetValue(
                            texturePath,
                            out var packReferences))
                    {
                        packReferences = [];
                        packReferencesByTexture[texturePath] = packReferences;
                    }

                    packReferences.Add(reference);
                }
            }

            // Start with the selected-pack closure, then add every WSModel/rigid that can be
            // reached by a unit in the culture-local army model. CA assets are read-only
            // consumers: they can keep a DDS resident, but are never proposed rewrites.
            var reachableWsModels = state.SourceReachableAssetFiles
                .Where(path => Path.GetExtension(path).Equals(
                    ".wsmodel",
                    StringComparison.OrdinalIgnoreCase))
                .Select(Normalize)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            reachableWsModels.UnionWith(state.ReachableWsModelsByRoot.Values
                .SelectMany(paths => paths)
                .Select(Normalize));
            if (state.ArmyResidencyModel != null)
            {
                reachableWsModels.UnionWith(
                    state.ArmyResidencyModel.ExpectedWsModelOccurrencesByUnit.Values
                        .SelectMany(occurrences => occurrences.ByWsModel.Keys)
                        .Where(path => Path.GetExtension(path).Equals(
                            ".wsmodel",
                            StringComparison.OrdinalIgnoreCase))
                        .Select(Normalize));
            }

            var reachableWsModelPaths = reachableWsModels
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            state.AtlasValueGateReachableWsModelCount = reachableWsModelPaths.Length;
            var sourceWsModelCount = 0;
            var caWsModelCount = 0;
            var unresolvedWsModelCount = 0;
            var resolvedWsModels = new List<
                (string Path, IPackFileContainer Container, PackFile File)>();
            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                0,
                reachableWsModelPaths.Length,
                "Indexing WSModel texture consumers");
            for (var wsModelIndex = 0;
                 wsModelIndex < reachableWsModelPaths.Length;
                 wsModelIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    wsModelIndex + 1,
                    reachableWsModelPaths.Length,
                    "Indexing WSModel texture consumers");
                var wsModelPath = reachableWsModelPaths[wsModelIndex];
                var wsContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    loadedContainers,
                    wsModelPath);
                var wsFile = wsContainer?.FindFile(wsModelPath);
                if (wsContainer == null || wsFile == null)
                {
                    unresolvedWsModelCount++;
                    continue;
                }

                if (ReferenceEquals(wsContainer, state.Source))
                    sourceWsModelCount++;
                else if (wsContainer.IsCaPackFile)
                    caWsModelCount++;
                else
                    unresolvedWsModelCount++;

                resolvedWsModels.Add((wsModelPath, wsContainer, wsFile));
            }

            void AddWsModelTextureReferences(
                string wsModelPath,
                VanillaWsModelConsumerEntry wsModelEntry,
                bool sourceMaterialOnly)
            {
                foreach (var materialBinding in wsModelEntry.Materials)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    MeshKey? mesh = wsModelEntry.GeometryPath.Length != 0 &&
                                    materialBinding.LodIndex.HasValue &&
                                    materialBinding.PartIndex.HasValue
                        ? new MeshKey(
                            wsModelEntry.GeometryPath,
                            materialBinding.LodIndex.Value,
                            materialBinding.PartIndex.Value)
                        : null;

                    var materialPath = materialBinding.MaterialPath;
                    if (materialPath.Length == 0)
                        continue;

                    var materialContainer = FindGameplayTraversalContainer(
                        state,
                        state.Source,
                        loadedContainers,
                        materialPath);
                    var materialFile = materialContainer?.FindFile(materialPath);
                    if (sourceMaterialOnly &&
                        !ReferenceEquals(materialContainer, state.Source))
                    {
                        continue;
                    }

                    if (materialContainer == null ||
                        materialFile == null ||
                        !TryGetMaterialConsumerEntry(
                            state,
                            materialContainer,
                            materialPath,
                            materialFile,
                            out var materialEntry))
                    {
                        continue;
                    }

                    foreach (var texture in materialEntry.Textures)
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        if (!TryResolveTexture(
                                texture.TexturePath,
                                out var texturePath,
                                out _,
                                out _))
                        {
                            continue;
                        }

                        AddReference(
                            texturePath,
                            new AtlasValueGateSourceReference(
                                mesh,
                                wsModelPath.ToLowerInvariant(),
                                texture.Slot,
                                texture.SlotOccurrence,
                                AtlasValueGateSourceReferenceKind.WsModelMaterial));
                    }
                }
            }

            var cachedCaWsModels = new List<
                (string Path, IPackFileContainer Container, VanillaWsModelConsumerEntry Entry)>();
            var useVanillaTextureReverseIndex =
                targetTexturePaths != null &&
                state.VanillaAtlasConsumerCache != null &&
                resolvedWsModels.All(resolved =>
                    ReferenceEquals(resolved.Container, state.Source) ||
                    resolved.Container.IsCaPackFile);
            var vanillaCache = state.VanillaAtlasConsumerCache;
            if (useVanillaTextureReverseIndex)
            {
                foreach (var resolved in resolvedWsModels)
                {
                    if (ReferenceEquals(resolved.Container, state.Source))
                        continue;

                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (TryGetVanillaCachedWsModelConsumerEntry(
                            state,
                            resolved.Container,
                            resolved.Path,
                            out var wsModelEntry))
                    {
                        var entryIsComplete = true;
                        foreach (var materialBinding in wsModelEntry.Materials)
                        {
                            state.CancellationToken.ThrowIfCancellationRequested();
                            var materialPath = Normalize(materialBinding.MaterialPath);
                            if (materialPath.Length == 0)
                                continue;

                            var materialContainer = FindGameplayTraversalContainer(
                                state,
                                state.Source,
                                loadedContainers,
                                materialPath);
                            var materialFile = materialContainer?.FindFile(materialPath);
                            if (materialContainer == null || materialFile == null)
                            {
                                entryIsComplete = false;
                                break;
                            }

                            // A source-pack material is intentionally handled below. It is
                            // mutable and therefore cannot be represented by the vanilla
                            // reverse index.
                            if (ReferenceEquals(materialContainer, state.Source))
                                continue;

                            if (!materialContainer.IsCaPackFile ||
                                !TryGetVanillaCachedMaterialConsumerEntry(
                                    state,
                                    materialContainer,
                                    materialPath,
                                    out _))
                            {
                                entryIsComplete = false;
                                break;
                            }
                        }

                        if (entryIsComplete)
                        {
                            cachedCaWsModels.Add((
                                resolved.Path,
                                resolved.Container,
                                wsModelEntry));
                            continue;
                        }
                    }

                    useVanillaTextureReverseIndex = false;
                    break;
                }
            }

            if (useVanillaTextureReverseIndex)
            {
                var sourceWsModels = resolvedWsModels
                    .Where(resolved => ReferenceEquals(resolved.Container, state.Source))
                    .ToArray();
                ReportProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    0,
                    sourceWsModels.Length,
                    "Indexing source WSModel texture consumers");
                for (var sourceIndex = 0; sourceIndex < sourceWsModels.Length; sourceIndex++)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    ReportPeriodicProgress(
                        state.Progress,
                        "Evaluating atlas value",
                        sourceIndex + 1,
                        sourceWsModels.Length,
                        "Indexing source WSModel texture consumers");
                    var resolved = sourceWsModels[sourceIndex];
                    if (TryGetWsModelConsumerEntry(
                            state,
                            resolved.Container,
                            resolved.Path,
                            resolved.File,
                            out var wsModelEntry))
                    {
                        AddWsModelTextureReferences(
                            resolved.Path,
                            wsModelEntry,
                            sourceMaterialOnly: false);
                    }
                }

                // CA WSModels are immutable, but a selected source pack may override one of
                // their material paths. Those bindings still need the source material's
                // current texture relationships; only the unaffected CA relationships can
                // use the reverse index below.
                foreach (var cached in cachedCaWsModels)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    AddWsModelTextureReferences(
                        cached.Path,
                        cached.Entry,
                        sourceMaterialOnly: true);
                }

                foreach (var targetTexturePath in targetTexturePaths!)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (!TryResolveTexture(
                            targetTexturePath,
                            out var resolvedTargetTexturePath,
                            out _,
                            out _))
                    {
                        continue;
                    }

                    foreach (var consumer in vanillaCache!.FindTextureConsumers(
                                 resolvedTargetTexturePath,
                                 reachableWsModels))
                    {
                        state.CancellationToken.ThrowIfCancellationRequested();
                        var wsContainer = FindGameplayTraversalContainer(
                            state,
                            state.Source,
                            loadedContainers,
                            consumer.WsModelPath);
                        var materialContainer = FindGameplayTraversalContainer(
                            state,
                            state.Source,
                            loadedContainers,
                            consumer.MaterialPath);
                        var wsFile = wsContainer?.FindFile(consumer.WsModelPath);
                        var materialFile = materialContainer?.FindFile(consumer.MaterialPath);
                        if (wsContainer == null ||
                            materialContainer == null ||
                            wsFile == null ||
                            materialFile == null ||
                            !string.Equals(
                                vanillaCache.GetContainerScope(wsContainer),
                                consumer.WsModelContainerScope,
                                StringComparison.Ordinal) ||
                            !string.Equals(
                                vanillaCache.GetContainerScope(materialContainer),
                                consumer.MaterialContainerScope,
                                StringComparison.Ordinal))
                        {
                            continue;
                        }

                        MeshKey? mesh = consumer.GeometryPath.Length != 0 &&
                                        consumer.LodIndex.HasValue &&
                                        consumer.PartIndex.HasValue
                            ? new MeshKey(
                                consumer.GeometryPath,
                                consumer.LodIndex.Value,
                                consumer.PartIndex.Value)
                            : null;
                        AddReference(
                            resolvedTargetTexturePath,
                            new AtlasValueGateSourceReference(
                                mesh,
                                consumer.WsModelPath.ToLowerInvariant(),
                                consumer.Slot,
                                consumer.SlotOccurrence,
                                AtlasValueGateSourceReferenceKind.WsModelMaterial));
                    }
                }
            }
            else
            {
                ReportProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    0,
                    resolvedWsModels.Count,
                    "Parsing WSModel texture consumers");
                for (var resolvedIndex = 0;
                     resolvedIndex < resolvedWsModels.Count;
                     resolvedIndex++)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    ReportPeriodicProgress(
                        state.Progress,
                        "Evaluating atlas value",
                        resolvedIndex + 1,
                        resolvedWsModels.Count,
                        "Parsing WSModel texture consumers");
                    var resolved = resolvedWsModels[resolvedIndex];
                    if (!TryGetWsModelConsumerEntry(
                            state,
                            resolved.Container,
                            resolved.Path,
                            resolved.File,
                            out var wsModelEntry))
                    {
                        continue;
                    }

                    AddWsModelTextureReferences(
                        resolved.Path,
                        wsModelEntry,
                        sourceMaterialOnly: false);
                }
            }

            state.AtlasValueGateSourceWsModelCount = sourceWsModelCount;
            state.AtlasValueGateCaWsModelCount = caWsModelCount;
            state.AtlasValueGateUnresolvedWsModelCount = unresolvedWsModelCount;
            AddPhaseDuration(
                state,
                "Index WSModel texture consumers",
                wsModelIndexStopwatch.Elapsed);

            var directRigidIndexStopwatch = Stopwatch.StartNew();
            var directRigidPaths = state.SourceReachableAssetFiles
                .Where(path => Path.GetExtension(path).Equals(
                    ".rigid_model_v2",
                    StringComparison.OrdinalIgnoreCase))
                .Select(Normalize)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            if (state.ArmyResidencyModel != null)
            {
                directRigidPaths.UnionWith(
                    state.ArmyResidencyModel.ExpectedWsModelOccurrencesByUnit.Values
                        .SelectMany(occurrences => occurrences.ByWsModel.Keys)
                        .Where(path => Path.GetExtension(path).Equals(
                            ".rigid_model_v2",
                            StringComparison.OrdinalIgnoreCase))
                        .Select(Normalize));
            }

            var directRigidPathValues = directRigidPaths
                .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            state.AtlasValueGateDirectRigidPathCount = directRigidPathValues.Length;
            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                0,
                directRigidPathValues.Length,
                "Indexing direct rigid texture consumers");
            for (var rigidIndex = 0;
                 rigidIndex < directRigidPathValues.Length;
                 rigidIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    rigidIndex + 1,
                    directRigidPathValues.Length,
                    "Indexing direct rigid texture consumers");
                var rigidPath = directRigidPathValues[rigidIndex];
                var rigidContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    loadedContainers,
                    rigidPath);
                var rigidFile = rigidContainer?.FindFile(rigidPath);
                if (rigidContainer == null ||
                    rigidFile == null ||
                    !TryGetRigidConsumerEntry(
                        state,
                        rigidContainer,
                        rigidPath,
                        rigidFile,
                        out var rigidEntry))
                {
                    continue;
                }

                foreach (var texture in rigidEntry.Textures)
                {
                    state.CancellationToken.ThrowIfCancellationRequested();
                    if (!TryResolveTexture(
                            texture.TexturePath,
                            out var texturePath,
                            out _,
                            out _))
                    {
                        continue;
                    }

                    AddReference(
                        texturePath,
                        new AtlasValueGateSourceReference(
                            new MeshKey(
                                rigidPath,
                                texture.LodIndex,
                                texture.PartIndex),
                            rigidPath.ToLowerInvariant(),
                            texture.Slot,
                            texture.SlotOccurrence,
                            AtlasValueGateSourceReferenceKind.RigidEmbedded));
                }
            }

            AddPhaseDuration(
                state,
                "Index direct rigid texture consumers",
                directRigidIndexStopwatch.Elapsed);

            var directVmdIndexStopwatch = Stopwatch.StartNew();
            var directVmdTextures = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);
            var directSourcePackVmdTextures = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);
            var vmdDocuments = state.VmdDocuments.ToArray();
            state.AtlasValueGateDirectVmdPathCount = vmdDocuments.Length;
            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                0,
                vmdDocuments.Length,
                "Indexing direct VMD texture consumers");
            for (var vmdIndex = 0; vmdIndex < vmdDocuments.Length; vmdIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    vmdIndex + 1,
                    vmdDocuments.Length,
                    "Indexing direct VMD texture consumers");
                var vmdPath = Normalize(vmdDocuments[vmdIndex].Key);
                var vmd = vmdDocuments[vmdIndex].Value;
                var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var childVmds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                CollectVmdReferences(vmd, models, childVmds, textures);
                var normalizedTextures = textures
                    .Select(Normalize)
                    .ToArray();
                directVmdTextures.UnionWith(normalizedTextures);

                // Direct VMD references are not rewritten by atlas processing. Keep the
                // source-pack subset separate: CA VMDs must continue to affect residency and
                // physical-retirement safety, but must not veto pack-local retirement credit.
                var vmdContainer = FindGameplayTraversalContainer(
                    state,
                    state.Source,
                    loadedContainers,
                    vmdPath);
                if (ReferenceEquals(vmdContainer, state.Source))
                    directSourcePackVmdTextures.UnionWith(normalizedTextures);
            }

            AddPhaseDuration(
                state,
                "Index direct VMD texture consumers",
                directVmdIndexStopwatch.Elapsed);

            state.AtlasValueGateRootsByWsModel ??=
                BuildArmyRootsByWsModel(
                    state,
                    state.CancellationToken,
                    state.Progress);

            var result = new Dictionary<string, AtlasValueGateSourceTexture>(
                StringComparer.OrdinalIgnoreCase);
            var textureReferences = referencesByTexture.ToArray();
            ReportProgress(
                state.Progress,
                "Evaluating atlas value",
                0,
                textureReferences.Length,
                "Estimating source texture residency");
            for (var textureIndex = 0;
                 textureIndex < textureReferences.Length;
                 textureIndex++)
            {
                state.CancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    state.Progress,
                    "Evaluating atlas value",
                    textureIndex + 1,
                    textureReferences.Length,
                    "Estimating source texture residency");
                var (texturePath, references) = textureReferences[textureIndex];
                if (!textureFiles.TryGetValue(texturePath, out var source))
                    continue;
                var packReferences = packReferencesByTexture.TryGetValue(
                    texturePath,
                    out var existingPackReferences)
                    ? existingPackReferences
                    : [];

                DdsBcnResidencyEstimate bcn;
                try
                {
                    if (!DdsBcnResidencyEstimator.TryEstimate(
                            source.File.DataSource.PeekData(148),
                            out bcn))
                    {
                        continue;
                    }
                }
                catch
                {
                    continue;
                }

                result[texturePath] = new AtlasValueGateSourceTexture(
                    bcn.Bytes,
                    source.IsOwnedBySourcePack,
                    directVmdTextures.Contains(texturePath),
                    directSourcePackVmdTextures.Contains(texturePath),
                    references,
                    packReferences);
            }

            state.AtlasValueGateContainerResolutionScans =
                state.GameplayTraversalContainerResolutionScans -
                containerResolutionScansBefore;
            state.AtlasValueGateContainerResolutionCacheHits =
                state.GameplayTraversalContainerResolutionCacheHits -
                containerResolutionCacheHitsBefore;
            state.AtlasValueGateWsModelConsumerCacheHits =
                state.WsModelConsumerCacheHits - wsModelConsumerCacheHitsBefore;
            state.AtlasValueGateWsModelConsumerMemoryCacheHits =
                state.WsModelConsumerMemoryCacheHits - wsModelConsumerMemoryCacheHitsBefore;
            state.AtlasValueGateWsModelConsumerVanillaCacheHits =
                state.WsModelConsumerVanillaCacheHits - wsModelConsumerVanillaCacheHitsBefore;
            state.AtlasValueGateWsModelConsumerCacheMisses =
                state.WsModelConsumerCacheMisses - wsModelConsumerCacheMissesBefore;
            state.AtlasValueGateWsModelConsumerEntryBuilds =
                state.WsModelConsumerEntryBuilds - wsModelConsumerEntryBuildsBefore;
            state.AtlasValueGateMaterialConsumerCacheHits =
                state.MaterialConsumerCacheHits - materialConsumerCacheHitsBefore;
            state.AtlasValueGateMaterialConsumerMemoryCacheHits =
                state.MaterialConsumerMemoryCacheHits - materialConsumerMemoryCacheHitsBefore;
            state.AtlasValueGateMaterialConsumerVanillaCacheHits =
                state.MaterialConsumerVanillaCacheHits - materialConsumerVanillaCacheHitsBefore;
            state.AtlasValueGateMaterialConsumerCacheMisses =
                state.MaterialConsumerCacheMisses - materialConsumerCacheMissesBefore;
            state.AtlasValueGateMaterialConsumerEntryBuilds =
                state.MaterialConsumerEntryBuilds - materialConsumerEntryBuildsBefore;
            state.AtlasValueGateGameplayTraversalWsModelXmlParseCount =
                state.GameplayTraversalWsModelXmlParseCount - wsModelXmlParseCountBefore;
            state.AtlasValueGateGameplayTraversalMaterialXmlParseCount =
                state.GameplayTraversalMaterialXmlParseCount - materialXmlParseCountBefore;

            BuildAtlasValueGateSourceTextureReverseIndex(state, result);
            state.VanillaAtlasConsumerCache?.Save();
            return result;
        }

        private static void BuildAtlasValueGateSourceTextureReverseIndex(
            BatchState state,
            IReadOnlyDictionary<string, AtlasValueGateSourceTexture> sourceIndex)
        {
            var texturesByReference =
                new Dictionary<AtlasValueGateSourceReference, List<string>>();
            state.AtlasValueGateSourceTextureOrder.Clear();

            var textureOrder = 0;
            foreach (var (texturePath, sourceTexture) in sourceIndex)
            {
                var normalizedTexturePath = Normalize(texturePath);
                state.AtlasValueGateSourceTextureOrder[normalizedTexturePath] =
                    textureOrder++;
                foreach (var reference in sourceTexture.References)
                {
                    if (!texturesByReference.TryGetValue(
                            reference,
                            out var texturePaths))
                    {
                        texturePaths = [];
                        texturesByReference[reference] = texturePaths;
                    }

                    texturePaths.Add(normalizedTexturePath);
                }
            }

            state.AtlasValueGateSourceTexturesByReference = texturesByReference;
        }

        private static bool TryGetGeneratedAtlasBcnCost(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out long bytes)
            => TryGetGeneratedAtlasBcnCost(
                state,
                candidates,
                out bytes,
                out _);

        private static bool TryGetGeneratedAtlasBcnCost(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out long bytes,
            out Dictionary<string, long> bytesBySlot)
        {
            bytes = 0;
            bytesBySlot = new Dictionary<string, long>(
                StringComparer.OrdinalIgnoreCase);
            try
            {
                // The value gate only needs a conservative residency estimate. Avoid
                // cropped-content hashing here; execution may deduplicate later and therefore
                // use the same or less BCn memory than this estimate.
                var sharedPlan = CreateSharedAtlasPlan(
                    state,
                    candidates,
                    deduplicateByContent: false);
                foreach (var channel in AtlasChannels)
                {
                    var sourceDimensions = new Dictionary<int, (int Width, int Height)>();
                    foreach (var source in sharedPlan.Batch.Sources)
                    {
                        var representative = source.Representative;
                        if (representative.ResolvedChannels.Contains(channel.Slot) &&
                            representative.ChannelDimensions.TryGetValue(
                                channel.Slot,
                                out var dimensions))
                        {
                            sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                                source.Representative,
                                dimensions.Width,
                                dimensions.Height);
                        }
                    }

                    var requiresConstantOnlyAtlas =
                        RequiresConstantOnlyMaskAtlas(
                            channel.Slot,
                            sharedPlan.Batch.Sources);
                    if (sourceDimensions.Count == 0 && !requiresConstantOnlyAtlas)
                        continue;

                    var outputDimensions = TextureAtlasBuilder.CalculateOutputDimensions(
                        sharedPlan.Plan,
                        sourceDimensions,
                        PackAtlasMaxSize);
                    var bytesPerBlock = channel.Type is TextureType.BaseColour or TextureType.MaterialMap
                        ? 8
                        : 16;
                    var channelBytes = CalculateBcnMipChainBytes(
                        outputDimensions.Width,
                        outputDimensions.Height,
                        bytesPerBlock);
                    bytesBySlot[channel.Slot] = channelBytes;
                    bytes = checked(bytes + channelBytes);
                }

                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or ArgumentException or OverflowException)
            {
                bytes = 0;
                bytesBySlot.Clear();
                return false;
            }
        }

        private static long CalculateBcnMipChainBytes(
            int width,
            int height,
            int bytesPerBlock)
        {
            long total = 0;
            var mipWidth = Math.Max(1, width);
            var mipHeight = Math.Max(1, height);
            while (true)
            {
                var blocksWide = Math.Max(1L, (mipWidth + 3L) / 4L);
                var blocksHigh = Math.Max(1L, (mipHeight + 3L) / 4L);
                total = checked(total + checked(blocksWide * blocksHigh * bytesPerBlock));

                if (mipWidth == 1 && mipHeight == 1)
                    break;
                mipWidth = Math.Max(1, mipWidth / 2);
                mipHeight = Math.Max(1, mipHeight / 2);
            }

            return total;
        }

        private static int CalculateMergeAffinityScoreWithReplacement(
            IReadOnlyList<List<AtlasCandidate>> batches,
            int leftIndex,
            int rightIndex,
            AtlasBatchSplitProposal proposal,
            IReadOnlyList<MergeAffinityGroup> affinityGroups)
        {
            var batchByMesh = BuildBatchIndexByMesh(batches);
            foreach (var candidate in proposal.Left)
                batchByMesh[candidate.Key] = leftIndex;
            foreach (var candidate in proposal.Right)
                batchByMesh[candidate.Key] = rightIndex;

            var score = 0;
            foreach (var group in affinityGroups)
                score += CalculateMergeAffinityContribution(group, batchByMesh);

            return score;
        }

        private static IReadOnlyList<AtlasBatchSplitProposal> CreateMergeAwareRepartitionProposals(
            IReadOnlyList<AtlasCandidate> currentLeft,
            IReadOnlyList<AtlasCandidate> currentRight,
            IReadOnlyList<MergeAffinityGroup> affinityGroups)
        {
            var combined = currentLeft
                .Concat(currentRight)
                .GroupBy(x => x.Key)
                .Select(group => group.First())
                .ToList();

            var planningGroups = combined
                .GroupBy(GetAtlasPlanningSourceIdentity)
                .Select(group =>
                {
                    var candidates = group
                        .OrderBy(x => x.RootVmdPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.LodIndex)
                        .ThenBy(x => x.Key.PartIndex)
                        .ToList();
                    return new AtlasPlanningCandidateGroup(
                        group.Key,
                        candidates,
                        candidates[0],
                        GetCanonicalCrop(candidates[0]).Crop);
                })
                .ToList();

            if (planningGroups.Count < 2)
                return [];

            var proposals = new List<AtlasBatchSplitProposal>();
            var seen = new HashSet<string>(StringComparer.Ordinal);

            void AddProposal(
                IEnumerable<AtlasPlanningCandidateGroup> leftGroups,
                IEnumerable<AtlasPlanningCandidateGroup> rightGroups)
            {
                var leftGroupList = leftGroups.ToList();
                var rightGroupList = rightGroups.ToList();
                var left = leftGroupList.SelectMany(x => x.Candidates).ToList();
                var right = rightGroupList.SelectMany(x => x.Candidates).ToList();

                if (left.Count < 2 || right.Count < 2)
                    return;

                var signature = string.Join(
                    "\n",
                    left.Select(x => x.Key.ToString())
                        .OrderBy(x => x, StringComparer.Ordinal));
                if (!seen.Add(signature))
                    return;

                proposals.Add(new AtlasBatchSplitProposal(left, right));
            }

            var planningGroupByMesh = new Dictionary<MeshKey, int>();
            for (var groupIndex = 0; groupIndex < planningGroups.Count; groupIndex++)
            {
                foreach (var candidate in planningGroups[groupIndex].Candidates)
                    planningGroupByMesh[candidate.Key] = groupIndex;
            }

            var parent = Enumerable.Range(0, planningGroups.Count).ToArray();

            int Find(int index)
            {
                while (parent[index] != index)
                {
                    parent[index] = parent[parent[index]];
                    index = parent[index];
                }
                return index;
            }

            void Union(int left, int right)
            {
                var leftRoot = Find(left);
                var rightRoot = Find(right);
                if (leftRoot != rightRoot)
                    parent[rightRoot] = leftRoot;
            }

            foreach (var affinity in affinityGroups)
            {
                var groupIndices = affinity.Meshes
                    .Where(planningGroupByMesh.ContainsKey)
                    .Select(mesh => planningGroupByMesh[mesh])
                    .Distinct()
                    .ToArray();

                for (var index = 1; index < groupIndices.Length; index++)
                    Union(groupIndices[0], groupIndices[index]);
            }

            var components = Enumerable.Range(0, planningGroups.Count)
                .GroupBy(Find)
                .Select(component => component
                    .Select(index => planningGroups[index])
                    .ToList())
                .ToList();

            long ComponentArea(IReadOnlyList<AtlasPlanningCandidateGroup> component)
                => component.Sum(group => GetPaddedCropArea(group.Crop));

            int ComponentAffinity(IReadOnlyList<AtlasPlanningCandidateGroup> component)
            {
                var meshes = component
                    .SelectMany(group => group.Candidates)
                    .Select(candidate => candidate.Key)
                    .ToHashSet();
                var batchByMesh = meshes.ToDictionary(mesh => mesh, _ => 0);
                return affinityGroups.Sum(group =>
                    CalculateMergeAffinityContribution(group, batchByMesh));
            }

            void AddBalancedComponentProposal(
                IEnumerable<List<AtlasPlanningCandidateGroup>> orderedComponents)
            {
                var leftComponents = new List<List<AtlasPlanningCandidateGroup>>();
                var rightComponents = new List<List<AtlasPlanningCandidateGroup>>();
                long leftArea = 0;
                long rightArea = 0;

                foreach (var component in orderedComponents)
                {
                    var area = ComponentArea(component);
                    if (leftComponents.Count == 0)
                    {
                        leftComponents.Add(component);
                        leftArea += area;
                    }
                    else if (rightComponents.Count == 0)
                    {
                        rightComponents.Add(component);
                        rightArea += area;
                    }
                    else if (leftArea <= rightArea)
                    {
                        leftComponents.Add(component);
                        leftArea += area;
                    }
                    else
                    {
                        rightComponents.Add(component);
                        rightArea += area;
                    }
                }

                AddProposal(
                    leftComponents.SelectMany(x => x),
                    rightComponents.SelectMany(x => x));
            }

            AddBalancedComponentProposal(
                components
                    .OrderByDescending(ComponentAffinity)
                    .ThenByDescending(ComponentArea));
            AddBalancedComponentProposal(
                components
                    .OrderByDescending(ComponentArea)
                    .ThenByDescending(ComponentAffinity));

            // Also try moving each currently split affinity group wholesale to either side.
            // Move whole planning identities, never individual duplicate source/crop users.
            var currentLeftKeys = currentLeft.Select(x => x.Key).ToHashSet();
            var currentRightKeys = currentRight.Select(x => x.Key).ToHashSet();
            var currentLeftGroupIds = planningGroups
                .Select((group, index) => (group, index))
                .Where(x => x.group.Candidates.Any(candidate => currentLeftKeys.Contains(candidate.Key)))
                .Select(x => x.index)
                .ToHashSet();

            foreach (var affinity in affinityGroups)
            {
                var affinityGroupIds = affinity.Meshes
                    .Where(planningGroupByMesh.ContainsKey)
                    .Select(mesh => planningGroupByMesh[mesh])
                    .Distinct()
                    .ToHashSet();

                if (affinityGroupIds.Count < 2 ||
                    !affinity.Meshes.Any(currentLeftKeys.Contains) ||
                    !affinity.Meshes.Any(currentRightKeys.Contains))
                {
                    continue;
                }

                var moveToLeft = currentLeftGroupIds
                    .Union(affinityGroupIds)
                    .ToHashSet();
                AddProposal(
                    planningGroups.Where((_, index) => moveToLeft.Contains(index)),
                    planningGroups.Where((_, index) => !moveToLeft.Contains(index)));

                var moveToRight = currentLeftGroupIds
                    .Except(affinityGroupIds)
                    .ToHashSet();
                AddProposal(
                    planningGroups.Where((_, index) => moveToRight.Contains(index)),
                    planningGroups.Where((_, index) => !moveToRight.Contains(index)));
            }

            // Reuse the existing physical-layout heuristics as additional candidates. The
            // acceptance rule below rejects any proposal that loses merge affinity.
            foreach (var proposal in CreateNonContiguousSplitProposals(combined))
                AddProposal(
                    proposal.Left
                        .GroupBy(GetAtlasPlanningSourceIdentity)
                        .Select(group => planningGroups.First(
                            planning => planning.Identity == group.Key)),
                    proposal.Right
                        .GroupBy(GetAtlasPlanningSourceIdentity)
                        .Select(group => planningGroups.First(
                            planning => planning.Identity == group.Key)));

            const int maxMergeAwareProposals = 48;
            return proposals.Count <= maxMergeAwareProposals
                ? proposals
                : proposals.Take(maxMergeAwareProposals).ToList();
        }

        private static IReadOnlyList<AtlasBatchSplitProposal> CreateNonContiguousSplitProposals(
            IReadOnlyList<AtlasCandidate> batch)
        {
            var groups = batch
                .GroupBy(GetAtlasPlanningSourceIdentity)
                .Select(group =>
                {
                    var candidates = group
                        .OrderBy(x => x.RootVmdPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.GeometryPath, StringComparer.OrdinalIgnoreCase)
                        .ThenBy(x => x.Key.LodIndex)
                        .ThenBy(x => x.Key.PartIndex)
                        .ToList();
                    return new AtlasPlanningCandidateGroup(
                        group.Key,
                        candidates,
                        candidates[0],
                        GetCanonicalCrop(candidates[0]).Crop);
                })
                .ToList();

            if (groups.Count < 4)
                return [];

            var proposals = new List<AtlasBatchSplitProposal>();
            var seen = new HashSet<string>(StringComparer.Ordinal);

            void AddProposals(
                IEnumerable<AtlasPlanningCandidateGroup> orderedGroups,
                IReadOnlyList<int> requestedSplitIndices)
            {
                var ordered = orderedGroups.ToList();
                foreach (var requestedIndex in requestedSplitIndices)
                {
                    var splitIndex = Math.Clamp(requestedIndex, 1, ordered.Count - 1);
                    var leftGroups = ordered.Take(splitIndex).ToList();
                    var rightGroups = ordered.Skip(splitIndex).ToList();
                    var left = leftGroups.SelectMany(x => x.Candidates).ToList();
                    var right = rightGroups.SelectMany(x => x.Candidates).ToList();

                    // A one-candidate atlas has no consolidation benefit and the normal planner
                    // deliberately avoids creating it.
                    if (left.Count < 2 || right.Count < 2)
                        continue;

                    var signature = string.Join(
                        "",
                        leftGroups
                            .Select(x => BuildAtlasPlanningOrderKey(x.Representative))
                            .OrderBy(x => x, StringComparer.Ordinal));
                    if (!seen.Add(signature))
                        continue;

                    proposals.Add(new AtlasBatchSplitProposal(left, right));
                }
            }

            var groupCount = groups.Count;
            var broadSplitIndices = new[]
            {
                1,
                2,
                Math.Max(1, groupCount / 3),
                Math.Max(1, groupCount / 2),
                Math.Min(groupCount - 1, (groupCount * 2) / 3),
                Math.Max(1, groupCount - 2)
            };

            // First separate sources with very different per-channel resolution pressure. A
            // small number of 4x masks/normals can otherwise force the physical size of that
            // entire channel up for every placement in the batch.
            foreach (var channel in AtlasChannels)
            {
                var orderedByChannelPressure = groups
                    .OrderByDescending(x => GetChannelScalePressure(x.Representative, channel.Slot))
                    .ThenByDescending(x => (long)x.Crop.Width * x.Crop.Height)
                    .ThenBy(x => BuildAtlasPlanningOrderKey(x.Representative), StringComparer.Ordinal);
                AddProposals(
                    orderedByChannelPressure,
                    [1, 2, Math.Max(1, groupCount / 2), Math.Max(1, groupCount - 2)]);
            }

            // Wide and tall crops frequently combine into a max-size square atlas. Separating them can
            // turn one expensive 4096x4096 batch into two substantially cheaper rectangular atlases.
            AddProposals(
                groups
                    .OrderBy(x => GetCropAspectScore(x.Crop))
                    .ThenByDescending(x => (long)x.Crop.Width * x.Crop.Height)
                    .ThenBy(x => BuildAtlasPlanningOrderKey(x.Representative), StringComparer.Ordinal),
                broadSplitIndices);

            // Also try isolating the largest placements regardless of aspect. This catches mixed
            // size-class batches where a few large sources force a power-of-two jump.
            AddProposals(
                groups
                    .OrderByDescending(x => (long)x.Crop.Width * x.Crop.Height)
                    .ThenByDescending(x => Math.Max(x.Crop.Width, x.Crop.Height))
                    .ThenBy(x => BuildAtlasPlanningOrderKey(x.Representative), StringComparer.Ordinal),
                broadSplitIndices);

            const int maxNonContiguousSplitEvaluations = 32;
            return proposals.Count <= maxNonContiguousSplitEvaluations
                ? proposals
                : proposals.Take(maxNonContiguousSplitEvaluations).ToList();
        }

        private static double GetChannelScalePressure(AtlasCandidate candidate, string slot)
        {
            if (candidate.ConstantChannels.ContainsKey(slot))
                return 0;

            if (!candidate.ResolvedChannels.Contains(slot) ||
                !candidate.ChannelDimensions.TryGetValue(slot, out var dimensions))
            {
                return 0;
            }

            return Math.Max(
                dimensions.Width / (double)Math.Max(1, candidate.Width),
                dimensions.Height / (double)Math.Max(1, candidate.Height));
        }

        private static double GetCropAspectScore(AtlasCrop crop)
            => Math.Log2(
                Math.Max(1, crop.Width) /
                (double)Math.Max(1, crop.Height));

        private static bool TryGetGeneratedAtlasPixelCost(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out long pixelCost,
            out bool touchesMaxSize,
            bool deduplicateByContent = false)
        {
            pixelCost = 0;
            touchesMaxSize = false;

            try
            {
                var sharedPlan = CreateSharedAtlasPlan(
                    state,
                    candidates,
                    deduplicateByContent);
                foreach (var channel in AtlasChannels)
                {
                    var sourceDimensions = new Dictionary<int, (int Width, int Height)>();

                    foreach (var source in sharedPlan.Batch.Sources)
                    {
                        var representative = source.Representative;
                        if (representative.ResolvedChannels.Contains(channel.Slot) &&
                            representative.ChannelDimensions.TryGetValue(
                                channel.Slot,
                                out var dimensions))
                        {
                            sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                                source.Representative,
                                dimensions.Width,
                                dimensions.Height);
                        }
                    }

                    var requiresConstantOnlyAtlas =
                        RequiresConstantOnlyMaskAtlas(
                            channel.Slot,
                            sharedPlan.Batch.Sources);
                    // ProcessBatch deliberately emits no texture when every present source
                    // for a channel is uniform/constant, except for a mask channel forced
                    // into an atlas to preserve canonicalized blue-mask semantics.
                    if (sourceDimensions.Count == 0 && !requiresConstantOnlyAtlas)
                        continue;

                    var outputDimensions = TextureAtlasBuilder.CalculateOutputDimensions(
                        sharedPlan.Plan,
                        sourceDimensions,
                        PackAtlasMaxSize);

                    pixelCost = checked(
                        pixelCost +
                        (long)outputDimensions.Width * outputDimensions.Height);

                    if (outputDimensions.Width == PackAtlasMaxSize ||
                        outputDimensions.Height == PackAtlasMaxSize)
                    {
                        touchesMaxSize = true;
                    }
                }

                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or ArgumentException or OverflowException)
            {
                pixelCost = 0;
                touchesMaxSize = false;
                return false;
            }
        }

        private static AtlasPlanningSourceIdentity GetAtlasPlanningSourceIdentity(AtlasCandidate candidate)
            => new(
                BuildAtlasTextureSetIdentity(candidate),
                GetCanonicalCrop(candidate).Crop,
                candidate.AtlasResolutionScale);

        private static string BuildAtlasPlanningOrderKey(AtlasCandidate candidate)
        {
            var identity = BuildAtlasTextureSetIdentity(candidate);
            var prefix = string.Join(
                "\u001f",
                identity.SourceWidth,
                identity.SourceHeight,
                identity.BaseColour,
                identity.MaterialMap,
                identity.Normal,
                identity.Mask);

            try
            {
                var crop = GetCanonicalCrop(candidate).Crop;
                return string.Join(
                    "\u001f",
                    prefix,
                    crop.X,
                    crop.Y,
                    crop.Width,
                    crop.Height,
                    candidate.AtlasResolutionScale);
            }
            catch (OverflowException)
            {
                // CanCreatePlan records the real per-mesh error. Sorting must never turn a
                // safely-skippable bad candidate into a failure for the whole pack.
                return $"{prefix}\u001finvalid\u001f{candidate.Key}";
            }
        }

        private static bool CanCreatePlan(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            out string error)
        {
            try
            {
                _ = CreateSharedAtlasPlan(state, candidates);
                error = string.Empty;
                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or ArgumentException or OverflowException)
            {
                error = ex.Message;
                return false;
            }
        }

        private static bool RequiresConstantOnlyMaskAtlas(
            string slot,
            IReadOnlyList<SharedAtlasSource> sources)
            => slot.Equals("t_xml_mask", StringComparison.OrdinalIgnoreCase) &&
                sources.Any(source => source.Representative.RequiresMaskAtlas);

        private static (SharedAtlasBatch Batch, TextureAtlasPlan Plan) CreateSharedAtlasPlan(
            BatchState state,
            IReadOnlyList<AtlasCandidate> candidates,
            bool deduplicateByContent = false)
        {
            var mergedBatch = BuildSharedAtlasBatch(
                state,
                candidates,
                mergeCompatibleCrops: true,
                deduplicateByContent);
            try
            {
                var mergedPlan = TextureAtlasBuilder.CreatePlan(
                    ToAtlasLayoutSources(mergedBatch.Sources),
                    TextureAtlasBuilder.DefaultPadding,
                    PackAtlasMaxSize);
                ValidateChannelAtlasDimensions(mergedBatch, mergedPlan);
                return (mergedBatch, mergedPlan);
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or ArgumentException or OverflowException)
            {
                var exactBatch = BuildSharedAtlasBatch(
                    state,
                    candidates,
                    mergeCompatibleCrops: false,
                    deduplicateByContent);
                var exactPlan = TextureAtlasBuilder.CreatePlan(
                    ToAtlasLayoutSources(exactBatch.Sources),
                    TextureAtlasBuilder.DefaultPadding,
                    PackAtlasMaxSize);
                ValidateChannelAtlasDimensions(exactBatch, exactPlan);
                return (exactBatch, exactPlan);
            }
        }

        private static void ValidateChannelAtlasDimensions(
            SharedAtlasBatch batch,
            TextureAtlasPlan plan)
        {
            foreach (var channel in AtlasChannels)
            {
                var sourceDimensions = new Dictionary<int, (int Width, int Height)>();
                foreach (var source in batch.Sources)
                {
                    if (source.Representative.ChannelDimensions.TryGetValue(
                            channel.Slot,
                            out var dimensions))
                    {
                        sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                            source.Representative,
                            dimensions.Width,
                            dimensions.Height);
                    }
                }

                if (sourceDimensions.Count > 0)
                    _ = TextureAtlasBuilder.CalculateOutputDimensions(
                        plan,
                        sourceDimensions,
                        PackAtlasMaxSize);
            }
        }

        private void ProcessBatch(
            BatchState state,
            string atlasScopeKey,
            string progressScope,
            List<AtlasCandidate> candidates,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress,
            SharedAtlasPage? sharedPage)
        {
            cancellationToken.ThrowIfCancellationRequested();
            SharedAtlasBatch sharedBatch;
            TextureAtlasPlan plan;
            Dictionary<string, string> generatedPaths;
            if (sharedPage != null)
            {
                sharedBatch = sharedPage.Batch;
                plan = sharedPage.Plan;
                generatedPaths = sharedPage.GeneratedPaths;
            }
            else
            {
                var sharedPlan = CreateSharedAtlasPlan(
                    state,
                    candidates,
                    deduplicateByContent: true);
                sharedBatch = sharedPlan.Batch;
                plan = sharedPlan.Plan;
                state.AtlasPlacementsGenerated += sharedBatch.Sources.Count;
                state.AtlasPlacementsReused += candidates.Count - sharedBatch.Sources.Count;
                state.WrappedUvPlacementsCanonicalized += sharedBatch.MappingByMesh.Values.Count(
                    x => x.WrappedUvCanonicalized);
                state.ContentDeduplicatedAtlasPlacements += sharedBatch.ContentPlacementsReused;
                state.ContentCanonicalizedMeshReferences += sharedBatch.MappingByMesh.Values.Count(
                    x => x.ContentCanonicalized);
                generatedPaths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            }

            foreach (var candidate in candidates)
            {
                if (candidate.UvIslandNormalization == null)
                    continue;

                var normalization = candidate.UvIslandNormalization;
                state.UvIslandNormalizedMeshes++;
                state.UvIslandsShifted += normalization.ShiftedIslandCount;
                state.UvIslandCropPixelsSaved = checked(
                    state.UvIslandCropPixelsSaved +
                    (long)normalization.OriginalCrop.Width * normalization.OriginalCrop.Height -
                    (long)normalization.NormalizedCrop.Width * normalization.NormalizedCrop.Height);
                state.UvIslandNormalizationEntries.Add(new UvIslandNormalizationReportEntry(
                    candidate.Key,
                    normalization.IslandCount,
                    normalization.ShiftedIslandCount,
                    normalization.OriginalCrop,
                    normalization.NormalizedCrop));
            }

            var atlasBatchId = state.BatchIndex++;
            if (!TryGetGeneratedAtlasPixelCost(
                    state,
                    candidates,
                    out var atlasBatchPixelCost,
                    out _,
                    deduplicateByContent: true))
                atlasBatchPixelCost = 0;

            state.AtlasBatchDiagnostics[atlasBatchId] = new AtlasBatchDiagnosticSnapshot(
                candidates.ToList(),
                atlasBatchPixelCost);
            foreach (var candidate in candidates)
            {
                state.AtlasBatchByMesh[candidate.Key] = atlasBatchId;
            }

            state.AtlasBatchCount++;
            var rootsByMesh = BuildCandidateRootVmdPaths(state, candidates);
            if (state.ShareAtlasesAcrossVmdsEnabled &&
                GetBatchRootCount(candidates, rootsByMesh) > 1)
            {
                state.CrossVmdSharedAtlasBatches++;
            }

            foreach (var sourceGroup in candidates.GroupBy(x => sharedBatch.MappingByMesh[x.Key].SourceId))
            {
                var sourceRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var candidate in sourceGroup)
                {
                    if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                        sourceRoots.UnionWith(candidateRoots);
                    else
                        sourceRoots.Add(Normalize(candidate.RootVmdPath));
                }

                if (sourceRoots.Count > 1)
                    state.CrossVmdSharedAtlasPlacements++;
            }

            if (sharedPage == null)
            {
                var atlasStem = BuildAtlasStem(atlasScopeKey, state.AtlasPageIndex++);

                for (var channelIndex = 0; channelIndex < AtlasChannels.Length; channelIndex++)
                {
                cancellationToken.ThrowIfCancellationRequested();
                var channel = AtlasChannels[channelIndex];
                ReportProgress(
                    progress,
                    "Building texture atlases",
                    channelIndex + 1,
                    AtlasChannels.Length,
                    $"{progressScope} — {channel.Suffix}");
                var textureBytes = new Dictionary<int, byte[]>();
                var textureBytesByPath = new Dictionary<string, byte[]>(StringComparer.OrdinalIgnoreCase);
                var constantSources = new Dictionary<int, TextureAtlasConstantColor>();
                var omitted = new HashSet<int>();

                foreach (var source in sharedBatch.Sources)
                {
                    var representative = source.Representative;
                    if (representative.ResolvedChannels.Contains(channel.Slot))
                    {
                        var sourcePath = GetTexturePath(representative.MaterialDocument, channel.Slot);
                        if (string.IsNullOrWhiteSpace(sourcePath))
                        {
                            throw new InvalidOperationException(
                                $"Resolved atlas channel {channel.Slot} has no texture path for {representative.Key}.");
                        }

                        sourcePath = Normalize(sourcePath);
                        if (!textureBytesByPath.TryGetValue(sourcePath, out var bytes))
                        {
                            var file = FindForRead(state, sourcePath)
                                ?? throw new InvalidOperationException(
                                    $"Resolved atlas texture no longer exists: {sourcePath}");
                            bytes = file.DataSource.ReadData();
                            textureBytesByPath[sourcePath] = bytes;
                        }

                        textureBytes[source.Id] = bytes;
                    }
                    else if (representative.ConstantChannels.TryGetValue(
                                 channel.Slot,
                                 out var constantColor))
                    {
                        constantSources[source.Id] = constantColor;
                    }
                    else
                    {
                        omitted.Add(source.Id);
                    }
                }

                var requiresConstantOnlyAtlas =
                    RequiresConstantOnlyMaskAtlas(channel.Slot, sharedBatch.Sources);
                if (textureBytes.Count == 0 && !requiresConstantOnlyAtlas)
                {
                    // UV remapping cannot change a uniform texture. If every present source
                    // for this channel is constant, keep each material's original shared
                    // constant texture path instead of allocating/compressing an atlas.
                    if (constantSources.Count != 0)
                        state.ConstantOnlyAtlasChannelsSkipped++;
                    continue;
                }

                var sourceDimensions = new Dictionary<int, (int Width, int Height)>();
                foreach (var source in sharedBatch.Sources)
                {
                    if (textureBytes.ContainsKey(source.Id) &&
                        source.Representative.ChannelDimensions.TryGetValue(
                            channel.Slot,
                            out var dimensions))
                    {
                        sourceDimensions[source.Id] = GetScaledAtlasDimensions(
                            source.Representative,
                            dimensions.Width,
                            dimensions.Height);
                    }
                }

                var outputDimensions = TextureAtlasBuilder.CalculateOutputDimensions(
                    plan,
                    sourceDimensions,
                    PackAtlasMaxSize);

                var fileName = $"{atlasStem}_{channel.Suffix}.dds";
                using var mipWriter = PngToDdsImporter.CreateRawBgraMipChainWriter(
                    outputDimensions.Width,
                    outputDimensions.Height,
                    TextureAtlasBuilder.CalculateMipLevelCount(
                        outputDimensions.Width,
                        outputDimensions.Height),
                    channel.Type,
                    GameTypeEnum.Warhammer3,
                    collectCompressionStatistics: AtlasProfilingEnabled);

                var rasterStatistics = AtlasProfilingEnabled
                    ? new TextureAtlasBuildStatistics()
                    : null;
                var rasterStopwatch = Stopwatch.StartNew();
                var clearBlueSourceIds = channel.Slot.Equals(
                        "t_xml_mask",
                        StringComparison.OrdinalIgnoreCase)
                    ? sharedBatch.Sources
                        .Where(source => source.Representative.ClearMaskBlueChannel)
                        .Select(source => source.Id)
                        .ToHashSet()
                    : null;
                _ = TextureAtlasBuilder.BuildMipPixels(
                    plan,
                    textureBytes,
                    forceOpaqueAlphaSourceIds: null,
                    omittedSourceIds: omitted,
                    cancellationToken: cancellationToken,
                    heartbeat: () =>
                    {
                        ReportProgress(
                            progress,
                            "Building texture atlases",
                            channelIndex + 1,
                            AtlasChannels.Length,
                            $"{progressScope} — {channel.Suffix}");
                        cancellationToken.ThrowIfCancellationRequested();
                    },
                    constantSources: constantSources,
                    outputWidth: outputDimensions.Width,
                    outputHeight: outputDimensions.Height,
                    mipConsumer: (mipLevel, mipWidth, mipHeight, pixels) =>
                        mipWriter.WriteMip(mipLevel, pixels),
                    retainMipPixels: false,
                    statistics: rasterStatistics,
                    clearBlueSourceIds: clearBlueSourceIds);
                rasterStopwatch.Stop();
                var rasterElapsed = rasterStopwatch.Elapsed;
                AddPhaseDuration(state, "Rasterize atlas pixels", rasterElapsed);

                var usesLargeBcSplitCompression = mipWriter.UsesLargeBcSplitCompression;
                if (usesLargeBcSplitCompression)
                    state.LargeBcSplitCompressionChannels++;

                var compressionStopwatch = Stopwatch.StartNew();
                var atlasPackFile = mipWriter.Complete(fileName);
                compressionStopwatch.Stop();
                var compressionElapsed = compressionStopwatch.Elapsed;
                var compressionStatistics = mipWriter.LastCompressionStatistics;
                AddPhaseDuration(state, "Compress atlas DDS", compressionElapsed);
                var atlasPath = Normalize($@"{AtlasDirectory}\{fileName}");

                if (AtlasProfilingEnabled && rasterStatistics != null)
                {
                    state.GeneratedTextureTimings.Add(new GeneratedTextureTimingEntry(
                        atlasPath,
                        outputDimensions.Width,
                        outputDimensions.Height,
                        channel.Type,
                        DDSFormatHelper.GetDDSFormat(GameTypeEnum.Warhammer3, channel.Type),
                        rasterElapsed,
                        compressionElapsed,
                        usesLargeBcSplitCompression,
                        rasterStatistics,
                        compressionStatistics));
                }

                WriteFile(state.Output, atlasPath, atlasPackFile.DataSource.ReadData());
                generatedPaths[channel.Slot] = atlasPath;
                state.GeneratedTexturePaths.Add(atlasPath);
                state.GeneratedTextureDimensions[atlasPath] = outputDimensions;
            }

            RecordAtlasPhysicalPageResidency(state, candidates, generatedPaths);
            state.AtlasPlacementDiagnostics.Add(
                BuildAtlasPlacementDiagnosticSnapshot(
                    atlasStem,
                    plan,
                    sharedBatch,
                    candidates,
                    generatedPaths));
            }

            var rewriteStopwatch = Stopwatch.StartNew();
            for (var candidateIndex = 0; candidateIndex < candidates.Count; candidateIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var candidate = candidates[candidateIndex];
                ReportProgress(
                    progress,
                    "Rewriting mesh UVs and materials",
                    candidateIndex + 1,
                    candidates.Count,
                    candidate.Key.ToString());
                var mapping = sharedBatch.MappingByMesh[candidate.Key];
                var placement = plan.Placements.Single(x => x.Id == mapping.SourceId);

                foreach (var vertexIndex in candidate.Model.Mesh.IndexList.Distinct())
                {
                    if (vertexIndex >= candidate.Model.Mesh.VertexList.Length)
                        throw new InvalidOperationException(
                            $"Mesh {candidate.Key} contains invalid vertex index {vertexIndex}.");

                    var uv = candidate.Model.Mesh.VertexList[vertexIndex].Uv;
                    var islandOffsetU = candidate.UvIslandNormalization?.TileOffsetUByVertex[vertexIndex] ?? 0;
                    var islandOffsetV = candidate.UvIslandNormalization?.TileOffsetVByVertex[vertexIndex] ?? 0;
                    var remapped = placement.TransformUv(
                        uv.X + islandOffsetU - mapping.UvOffsetU,
                        uv.Y + islandOffsetV - mapping.UvOffsetV,
                        plan.Width,
                        plan.Height);
                    candidate.Model.Mesh.VertexList[vertexIndex].Uv = new Microsoft.Xna.Framework.Vector2(remapped.U, remapped.V);
                }

                var clonedMaterial = new XmlDocument();
                clonedMaterial.LoadXml(candidate.MaterialDocument.OuterXml);

                var unresolvedMaskPath = GetTexturePath(
                    clonedMaterial,
                    "t_xml_mask");
                if (IsIgnorableUnresolvedAtlasTexture(
                        "t_xml_mask",
                        unresolvedMaskPath) &&
                    FindForRead(state, unresolvedMaskPath) == null)
                {
                    RemoveTextureSlot(clonedMaterial, "t_xml_mask");
                }

                foreach (var channel in AtlasChannels)
                {
                    if (!candidate.ResolvedChannels.Contains(channel.Slot) &&
                        !candidate.ConstantChannels.ContainsKey(channel.Slot))
                        continue;
                    if (generatedPaths.TryGetValue(channel.Slot, out var atlasPath))
                        SetTexturePath(clonedMaterial, channel.Slot, atlasPath);
                }

                // Only canonicalize constant channels that remain source-backed. If another
                // candidate caused this channel to receive an atlas, the generated atlas path
                // is already the stronger sharing identity.
                CanonicalizeUniformConstantTexturePaths(
                    state,
                    clonedMaterial,
                    candidate.ConstantChannels);

                var isEmbeddedMaterial = candidate.Usages.Any(
                    usage => !string.IsNullOrWhiteSpace(usage.EmbeddedRigidPath));
                string resolvedMaterialPath;
                if (isEmbeddedMaterial)
                {
                    foreach (var channel in AtlasChannels)
                    {
                        if (generatedPaths.TryGetValue(channel.Slot, out var atlasPath))
                        {
                            ApplyEmbeddedMaterialTexture(
                                candidate.Model.Material,
                                channel.Slot,
                                atlasPath);
                        }
                    }

                    resolvedMaterialPath = "<embedded-rigid-material>";
                }
                else
                {
                    var materialXml = clonedMaterial.OuterXml;
                    var renderingIdentity = GetMaterialRenderingIdentity(clonedMaterial);
                    var materialContentHash = ContentHash(renderingIdentity);
                    if (!state.GeneratedMaterialByContentHash.TryGetValue(
                            materialContentHash,
                            out var generatedMaterial))
                    {
                        var newMaterialPath = BuildMaterialPath(candidate.MaterialPath, candidate.Key);
                        WriteFile(state.Output, newMaterialPath, Encoding.UTF8.GetBytes(materialXml));
                        state.GeneratedMaterialPaths.Add(newMaterialPath);
                        generatedMaterial = new GeneratedMaterialEntry(
                            newMaterialPath,
                            renderingIdentity,
                            new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                            {
                                candidate.RootVmdPath
                            });
                        state.GeneratedMaterialByContentHash.Add(materialContentHash, generatedMaterial);
                    }
                    else if (!generatedMaterial.RenderingIdentity.Equals(renderingIdentity, StringComparison.Ordinal))
                    {
                        // The hash is only an index. Exact rendering-identity equality remains
                        // the final guard so even a theoretical SHA-256 collision cannot share materials.
                        var newMaterialPath = BuildMaterialPath(candidate.MaterialPath, candidate.Key);
                        WriteFile(state.Output, newMaterialPath, Encoding.UTF8.GetBytes(materialXml));
                        state.GeneratedMaterialPaths.Add(newMaterialPath);
                        generatedMaterial = new GeneratedMaterialEntry(
                            newMaterialPath,
                            renderingIdentity,
                            new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                            {
                                candidate.RootVmdPath
                            });
                    }
                    else
                    {
                        state.GeneratedMaterialReuses++;
                        if (!generatedMaterial.RootVmdPaths.Contains(candidate.RootVmdPath) &&
                            generatedMaterial.RootVmdPaths.Count != 0)
                        {
                            state.CrossVmdMaterialReuses++;
                        }

                        generatedMaterial.RootVmdPaths.Add(candidate.RootVmdPath);
                    }

                    resolvedMaterialPath = generatedMaterial.Path;
                }

                state.AtlasedMeshes.Add(new AtlasedMeshReportEntry(
                    candidate.RootVmdPath,
                    candidate.Key,
                    candidate.Usages.Select(x => x.AssetPath).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),
                    candidate.MaterialPath,
                    resolvedMaterialPath,
                    generatedPaths.Values.Distinct(StringComparer.OrdinalIgnoreCase).ToArray()));

                foreach (var usage in candidate.Usages)
                {
                    if (usage.MaterialNode != null &&
                        !string.IsNullOrWhiteSpace(usage.WsModelPath))
                    {
                        usage.MaterialNode.InnerText = resolvedMaterialPath;
                        state.ModifiedWsModels.Add(usage.WsModelPath);
                    }
                }

                state.ModifiedRigids.Add(candidate.Key.GeometryPath);
                state.ProcessedMeshes.Add(candidate.Key);
            }
            AddPhaseDuration(state, "Rewrite mesh UVs and materials", rewriteStopwatch.Elapsed);
        }

        private void MergeDirectRigidModels(
            BatchState state,
            string rigidPath,
            RmvFile rmv,
            CancellationToken cancellationToken)
        {
            var rigidBefore = rmv.ModelList.Sum(x => x.Length);
            var rigidAfter = rigidBefore;
            var rigidChanged = false;

            for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var originalModels = rmv.ModelList[lodIndex];
                if (originalModels.Length < 2)
                    continue;

                var groups = BuildDirectMeshMergeGroups(
                    originalModels,
                    lodIndex,
                    rigidPath,
                    state);
                if (groups.All(group => group.PartIndices.Count == 1))
                    continue;

                var lodInvariant = CaptureLodGeometryInvariant(
                    originalModels,
                    rigidPath,
                    lodIndex);
                var mergedModels = new List<RmvModel>(groups.Count);
                for (var newPartIndex = 0; newPartIndex < groups.Count; newPartIndex++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var group = groups[newPartIndex];
                    var models = group.PartIndices
                        .Select(partIndex => originalModels[partIndex])
                        .ToList();
                    MergeGeometryInvariantSnapshot? groupInvariant = null;
                    if (models.Count > 1)
                    {
                        groupInvariant = CaptureMergeGroupInvariant(
                            models,
                            rigidPath,
                            lodIndex,
                            group.PartIndices);
                    }

                    var merged = models.Count == 1
                        ? models[0]
                        : MergeRmvModels(models);
                    if (groupInvariant != null)
                    {
                        ValidateMergedGroupGeometry(
                            groupInvariant,
                            merged,
                            rigidPath,
                            lodIndex,
                            group.PartIndices);
                        state.MeshMergeInvariantGroupCount++;
                    }

                    mergedModels.Add(merged);
                    if (models.Count > 1)
                    {
                        var mergeOrigin = GetMeshMergeOrigin(
                            state,
                            rigidPath,
                            lodIndex,
                            group.PartIndices);
                        RecordMeshMergeOrigin(state, mergeOrigin);

                        state.MeshMergeEntries.Add(new MeshMergeReportEntry(
                            rigidPath,
                            lodIndex,
                            group.PartIndices.ToArray(),
                            newPartIndex,
                            merged.Mesh.VertexList.Length,
                            BuildEmbeddedMaterialPath(
                                rigidPath,
                                lodIndex,
                                group.PartIndices[0]),
                            mergeOrigin));
                    }
                }

                ValidateLodGeometryInvariant(
                    lodInvariant,
                    mergedModels,
                    rigidPath,
                    lodIndex);
                state.MeshMergeInvariantLodCount++;
                rmv.ModelList[lodIndex] = mergedModels.ToArray();
                rigidAfter -= originalModels.Length - mergedModels.Count;
                rigidChanged = true;
            }

            state.MeshPartsBeforeMerging += rigidBefore;
            state.MeshPartsAfterMerging += rigidAfter;
            if (rigidChanged)
                state.ModifiedRigids.Add(rigidPath);
        }

        private static List<MeshMergeGroup> BuildDirectMeshMergeGroups(
            IReadOnlyList<RmvModel> models,
            int lodIndex,
            string rigidPath,
            BatchState? state = null)
        {
            var buckets = new Dictionary<string, List<int>>(StringComparer.Ordinal);
            for (var partIndex = 0; partIndex < models.Count; partIndex++)
            {
                var identity = string.Join(
                    "\u001e",
                    GetAtlasBatchMergeBoundaryIdentity(
                        state,
                        new MeshKey(rigidPath, lodIndex, partIndex)),
                    GetDirectRmvMergeIdentity(models[partIndex]));
                if (!buckets.TryGetValue(identity, out var parts))
                {
                    parts = [];
                    buckets.Add(identity, parts);
                }

                parts.Add(partIndex);
            }

            var groups = new List<MeshMergeGroup>();
            foreach (var parts in buckets.Values)
            {
                var current = new List<int>();
                var currentVertexCount = 0;
                foreach (var partIndex in parts.OrderBy(x => x))
                {
                    var vertexCount = models[partIndex].Mesh.VertexList.Length;
                    if (vertexCount > ushort.MaxValue)
                    {
                        if (current.Count != 0)
                        {
                            groups.Add(CreateDirectMeshMergeGroup(
                                current,
                                rigidPath,
                                lodIndex));
                            current = [];
                            currentVertexCount = 0;
                        }

                        groups.Add(CreateDirectMeshMergeGroup(
                            [partIndex],
                            rigidPath,
                            lodIndex));
                        continue;
                    }

                    if (current.Count != 0 &&
                        currentVertexCount + vertexCount > ushort.MaxValue)
                    {
                        groups.Add(CreateDirectMeshMergeGroup(
                            current,
                            rigidPath,
                            lodIndex));
                        current = [];
                        currentVertexCount = 0;
                    }

                    current.Add(partIndex);
                    currentVertexCount += vertexCount;
                }

                if (current.Count != 0)
                {
                    groups.Add(CreateDirectMeshMergeGroup(
                        current,
                        rigidPath,
                        lodIndex));
                }
            }

            return groups
                .OrderBy(group => group.PartIndices.Min())
                .ToList();
        }

        private static MeshMergeGroup CreateDirectMeshMergeGroup(
            IReadOnlyList<int> partIndices,
            string rigidPath,
            int lodIndex)
            => new(
                partIndices.ToList(),
                [BuildEmbeddedMaterialPath(rigidPath, lodIndex, partIndices[0])]);

        private static string GetDirectRmvMergeIdentity(RmvModel model)
        {
            var materialBytes = MaterialFactory.Create().Save(
                model.CommonHeader.ModelTypeFlag,
                model.Material);
            var identity = string.Join(
                "|",
                model.CommonHeader.ModelTypeFlag,
                model.CommonHeader.RenderFlag,
                model.Material.BinaryVertexFormat,
                model.CommonHeader.ShaderParams.ShaderName,
                Convert.ToHexString(materialBytes));
            return ContentHash(identity);
        }

        private void MergeCompatibleMeshes(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var rigidPaths = LoadStructuralMergeRigidModels(state, cancellationToken)
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();

            for (var rigidIndex = 0; rigidIndex < rigidPaths.Count; rigidIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var rigidPath = rigidPaths[rigidIndex];
                ReportProgress(
                    progress,
                    "Merging compatible mesh parts",
                    rigidIndex + 1,
                    rigidPaths.Count,
                    rigidPath);

                if (TryGetStructuralMergeBlockReason(state, rigidPath, out _))
                    continue;

                if (!state.RigidModels.TryGetValue(rigidPath, out var rmv))
                    continue;

                var wsModels = GetWritableWsModelsForRigid(state, rigidPath);

                if (wsModels.Count == 0)
                {
                    MergeDirectRigidModels(
                        state,
                        rigidPath,
                        rmv,
                        cancellationToken);
                    continue;
                }

                var wsStructureBeforeMerge = wsModels.ToDictionary(
                    x => x.Key,
                    x => GetWsModelNonMaterialIdentity(x.Value),
                    StringComparer.OrdinalIgnoreCase);
                var assignmentsByWsModel = new Dictionary<string, string[][]>(StringComparer.OrdinalIgnoreCase);
                var wsModelIndexByPath = wsModels
                    .Select((entry, index) => (entry.Key, index))
                    .ToDictionary(x => x.Key, x => x.index, StringComparer.OrdinalIgnoreCase);
                var assignmentsValid = true;
                foreach (var (wsPath, wsDocument) in wsModels)
                {
                    if (!TryReadWsMaterialAssignments(wsDocument, rmv, out var assignments, out var reason))
                    {
                        state.MeshMergeSkipMessages.Add($"{rigidPath}: {wsPath}: {reason}");
                        assignmentsValid = false;
                        break;
                    }

                    assignmentsByWsModel[wsPath] = assignments;
                }

                if (!assignmentsValid)
                    continue;

                var rigidBefore = rmv.ModelList.Sum(x => x.Length);
                var rigidAfter = rigidBefore;
                var rigidChanged = false;

                for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    var originalModels = rmv.ModelList[lodIndex];
                    if (originalModels.Length < 2)
                        continue;

                    var lodInvariant = CaptureLodGeometryInvariant(originalModels, rigidPath, lodIndex);

                    AnalyzeMeshMergeBlockers(
                        state,
                        rigidPath,
                        lodIndex,
                        originalModels,
                        wsModels.Select(x => x.Key).ToList(),
                        assignmentsByWsModel,
                        includeEmbeddedMaterialIdentity:
                            HasDirectGameplayRigidConsumer(state, rigidPath));

                    var groups = BuildMeshMergeGroups(
                        state,
                        originalModels,
                        lodIndex,
                        rigidPath,
                        wsModels.Select(x => x.Key).ToList(),
                        assignmentsByWsModel,
                        includeEmbeddedMaterialIdentity:
                            HasDirectGameplayRigidConsumer(state, rigidPath));

                    if (groups.All(x => x.PartIndices.Count == 1))
                        continue;

                    var mergedModels = new List<RmvModel>(groups.Count);
                    for (var newPartIndex = 0; newPartIndex < groups.Count; newPartIndex++)
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                        var group = groups[newPartIndex];
                        var models = group.PartIndices.Select(x => originalModels[x]).ToList();
                        MergeGeometryInvariantSnapshot? groupInvariant = null;
                        if (models.Count > 1)
                            groupInvariant = CaptureMergeGroupInvariant(models, rigidPath, lodIndex, group.PartIndices);

                        var merged = models.Count == 1
                            ? models[0]
                            : MergeRmvModels(models);

                        if (groupInvariant != null)
                        {
                            ValidateMergedGroupGeometry(
                                groupInvariant,
                                merged,
                                rigidPath,
                                lodIndex,
                                group.PartIndices);
                            state.MeshMergeInvariantGroupCount++;
                        }

                        mergedModels.Add(merged);

                        if (models.Count > 1)
                        {
                            var mergeOrigin = GetMeshMergeOrigin(
                                state,
                                rigidPath,
                                lodIndex,
                                group.PartIndices);
                            RecordMeshMergeOrigin(state, mergeOrigin);

                            state.MeshMergeEntries.Add(new MeshMergeReportEntry(
                                rigidPath,
                                lodIndex,
                                group.PartIndices.ToArray(),
                                newPartIndex,
                                merged.Mesh.VertexList.Length,
                                group.MaterialPathsByWsModel[0],
                                mergeOrigin));
                        }
                    }

                    foreach (var (wsPath, _) in wsModels)
                    {
                        var assignments = assignmentsByWsModel[wsPath];
                        var wsModelIndex = wsModelIndexByPath[wsPath];
                        assignments[lodIndex] = groups
                            .Select(group => group.MaterialPathsByWsModel[wsModelIndex])
                            .ToArray();
                    }

                    ValidateLodGeometryInvariant(
                        lodInvariant,
                        mergedModels,
                        rigidPath,
                        lodIndex);
                    state.MeshMergeInvariantLodCount++;

                    rmv.ModelList[lodIndex] = mergedModels.ToArray();
                    rigidAfter -= originalModels.Length - mergedModels.Count;
                    rigidChanged = true;
                }

                state.MeshPartsBeforeMerging += rigidBefore;
                state.MeshPartsAfterMerging += rigidAfter;

                if (!rigidChanged)
                    continue;

                state.ModifiedRigids.Add(rigidPath);
                foreach (var (wsPath, wsDocument) in wsModels)
                {
                    RewriteWsMaterialAssignments(
                        wsDocument,
                        assignmentsByWsModel[wsPath]);

                    var nonMaterialIdentity = GetWsModelNonMaterialIdentity(wsDocument);
                    if (!wsStructureBeforeMerge[wsPath].Equals(nonMaterialIdentity, StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            $"Mesh merge changed non-material WSModel structure: {wsPath}");
                    }

                    state.MeshMergeInvariantWsModelCount++;
                    state.ModifiedWsModels.Add(wsPath);
                }
            }
        }

        private static void OptimizeGeometry(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var rigidPaths = state.ModifiedRigids
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();

            for (var rigidIndex = 0; rigidIndex < rigidPaths.Count; rigidIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var rigidPath = rigidPaths[rigidIndex];
                ReportProgress(
                    progress,
                    "Optimizing geometry",
                    rigidIndex + 1,
                    rigidPaths.Count,
                    rigidPath);

                if (!state.RigidModels.TryGetValue(rigidPath, out var rmv))
                    continue;

                foreach (var lod in rmv.ModelList)
                {
                    foreach (var model in lod)
                    {
                        cancellationToken.ThrowIfCancellationRequested();
                        var statistics = RigidGeometryOptimizer.Optimize(model);
                        state.GeometryMeshesOptimized++;
                        state.GeometryVerticesBefore += statistics.VerticesBefore;
                        state.GeometryVerticesAfter += statistics.VerticesAfter;
                        state.GeometryUnreferencedVerticesRemoved += statistics.UnreferencedVerticesRemoved;
                        state.GeometryDuplicateVerticesRemoved += statistics.DuplicateVerticesRemoved;
                    }
                }
            }
        }

        private static void AnalyzeMeshMergeBlockers(
            BatchState state,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<RmvModel> models,
            IReadOnlyList<string> wsModelPaths,
            IReadOnlyDictionary<string, string[][]> assignmentsByWsModel,
            bool includeEmbeddedMaterialIdentity)
        {
            var rmvComponents = models
                .Select(model => GetRmvMergeDiagnosticComponents(
                    model,
                    includeEmbeddedMaterialIdentity))
                .ToArray();

            var exactBuckets = Enumerable.Range(0, models.Count)
                .GroupBy(partIndex => string.Join(
                    "\u001e",
                    GetRmvMergeIdentityForMerge(
                        models[partIndex],
                        includeEmbeddedMaterialIdentity),
                    string.Join(
                        "\u001f",
                        wsModelPaths.Select(
                            wsPath => Normalize(assignmentsByWsModel[wsPath][lodIndex][partIndex])))))
                .Where(group => group.Count() > 1);

            foreach (var bucket in exactBuckets)
            {
                var partIndices = bucket.OrderBy(x => x).ToList();
                var totalVertices = partIndices.Sum(x => models[x].Mesh.VertexList.Length);
                if (totalVertices <= ushort.MaxValue)
                    continue;

                var chunkCount = 1;
                var chunkVertices = 0;
                foreach (var partIndex in partIndices)
                {
                    var vertexCount = models[partIndex].Mesh.VertexList.Length;
                    if (chunkVertices != 0 &&
                        chunkVertices + vertexCount > ushort.MaxValue)
                    {
                        chunkCount++;
                        chunkVertices = 0;
                    }

                    chunkVertices += vertexCount;
                }

                RecordMeshMergeBlocker(
                    state,
                    "16-bit vertex limit",
                    $"{rigidPath} [lod {lodIndex}] parts [{string.Join(", ", partIndices)}]: " +
                    $"{totalVertices:N0} vertices require {chunkCount} merge groups.",
                    Math.Max(1, chunkCount - 1));
            }

            for (var leftIndex = 0; leftIndex < models.Count; leftIndex++)
            {
                for (var rightIndex = leftIndex + 1; rightIndex < models.Count; rightIndex++)
                {
                    var materialComparison = CompareWsMaterialAssignmentsForDiagnostics(
                        state,
                        lodIndex,
                        leftIndex,
                        rightIndex,
                        wsModelPaths,
                        assignmentsByWsModel);

                    var rmvDifferences = GetRmvMergeDiagnosticDifferences(
                        rmvComponents[leftIndex],
                        rmvComponents[rightIndex]);

                    if (rmvDifferences.Count == 0 &&
                        materialComparison.SemanticallyEquivalent &&
                        TryGetLogicalAtlasBatchBoundary(
                            state,
                            rigidPath,
                            lodIndex,
                            leftIndex,
                            rightIndex,
                            out var atlasBatchBoundaryDetail))
                    {
                        RecordMeshMergeBlocker(
                            state,
                            "Logical atlas batch boundary",
                            BuildMeshMergeBlockerExample(
                                rigidPath,
                                lodIndex,
                                leftIndex,
                                rightIndex,
                                atlasBatchBoundaryDetail));
                        continue;
                    }

                    if (rmvDifferences.Count == 0)
                    {
                        if (materialComparison.PathsEqual)
                            continue;

                        var reason = materialComparison.SemanticallyEquivalent
                            ? "WSModel material paths differ but rendering identity is identical"
                            : materialComparison.Reason;

                        RecordMaterialMergeBlockerBreakdown(
                            state,
                            materialComparison);

                        RecordMeshMergeBlocker(
                            state,
                            reason,
                            BuildMeshMergeBlockerExample(
                                rigidPath,
                                lodIndex,
                                leftIndex,
                                rightIndex,
                                materialComparison.Detail));

                        if (reason.Equals(
                                "WSModel texture assignments differ",
                                StringComparison.Ordinal))
                        {
                            AnalyzeCounterfactualTexturePair(
                                state,
                                rigidPath,
                                lodIndex,
                                leftIndex,
                                rightIndex,
                                materialComparison);
                            AnalyzeTextureBlockedMergeOpportunity(
                                state,
                                rigidPath,
                                lodIndex,
                                leftIndex,
                                rightIndex,
                                models,
                                materialComparison);
                        }

                        continue;
                    }

                    // If the WSModel materials are already equivalent, the RMV side is the only
                    // thing preventing a merge. Report one- or two-field RMV near misses and
                    // intentionally ignore pairs that are different in many unrelated ways.
                    if (!materialComparison.SemanticallyEquivalent || rmvDifferences.Count > 2)
                        continue;

                    var rmvReason = rmvDifferences.Count == 1
                        ? rmvDifferences[0]
                        : "Multiple RMV compatibility fields differ";

                    RecordMeshMergeBlocker(
                        state,
                        rmvReason,
                        BuildMeshMergeBlockerExample(
                            rigidPath,
                            lodIndex,
                            leftIndex,
                            rightIndex,
                            string.Join("; ", rmvDifferences)));
                }
            }
        }

        private static void AnalyzeCounterfactualTexturePair(
            BatchState state,
            string rigidPath,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex,
            MaterialMergeDiagnosticComparison materialComparison)
        {
            var left = GetMaterialMergeDiagnosticSnapshot(
                state,
                materialComparison.LeftMaterialPath);
            var right = GetMaterialMergeDiagnosticSnapshot(
                state,
                materialComparison.RightMaterialPath);
            if (left == null || right == null)
                return;

            var differingSlots = GetDifferingMaterialTextureSlots(
                    state,
                    left,
                    right)
                .ToList();
            if (differingSlots.Count == 0)
                return;

            state.CounterfactualTextureOnlyPairsEvaluated++;
            var classification = ClassifyCounterfactualTexturePair(
                state,
                left,
                right,
                differingSlots,
                out var eligibilityDetail);

            if (classification.Equals(
                    "Atlasable differing texture channels",
                    StringComparison.Ordinal))
            {
                state.CounterfactualTextureOnlyPairsAtlasable++;
            }
            else if (classification.Equals(
                         "Uniform-constant equivalence",
                         StringComparison.Ordinal))
            {
                state.CounterfactualTextureOnlyPairsCanonicalizable++;
            }

            IncrementDiagnosticCount(
                state.CounterfactualTexturePairCounts,
                classification);

            var example = BuildMeshMergeBlockerExample(
                rigidPath,
                lodIndex,
                leftPartIndex,
                rightPartIndex,
                $"slots [{string.Join(", ", differingSlots.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))}]; " +
                $"materials {materialComparison.LeftMaterialPath} <> " +
                $"{materialComparison.RightMaterialPath}; {eligibilityDetail}");
            AddDiagnosticExample(
                state.CounterfactualTexturePairExamples,
                classification,
                example);
        }

        private static string ClassifyCounterfactualTexturePair(
            BatchState state,
            MaterialMergeDiagnosticSnapshot left,
            MaterialMergeDiagnosticSnapshot right,
            IReadOnlyList<string> differingSlots,
            out string detail,
            bool allowDifferentUniformMaskConstants = false)
        {
            detail = string.Empty;

            if (left.Shader.Contains("emissive", StringComparison.OrdinalIgnoreCase) ||
                right.Shader.Contains("emissive", StringComparison.OrdinalIgnoreCase) ||
                left.TextureAssignments.Keys.Any(slot =>
                    slot.Contains("emissive", StringComparison.OrdinalIgnoreCase)) ||
                right.TextureAssignments.Keys.Any(slot =>
                    slot.Contains("emissive", StringComparison.OrdinalIgnoreCase)))
            {
                detail = "emissive or UV0-dependent material content";
                return "Material is not safely atlasable";
            }

            if (differingSlots.Any(slot => !IsAtlasChannelSlot(slot)))
            {
                detail = "at least one differing texture slot is outside the atlas channel set";
                return "Non-atlas texture slot";
            }

            if (!TryValidateCounterfactualMaterialTextureSet(
                    state,
                    left,
                    out var materialLeftFailure))
            {
                detail = materialLeftFailure ??
                    "one material has an unusable texture source";
                return "Material has an unresolved or unusable texture source";
            }

            if (!TryValidateCounterfactualMaterialTextureSet(
                    state,
                    right,
                    out var materialRightFailure))
            {
                detail = materialRightFailure ??
                    "one material has an unusable texture source";
                return "Material has an unresolved or unusable texture source";
            }

            var onlyUniformConstants = true;
            foreach (var slot in differingSlots)
            {
                left.TextureAssignments.TryGetValue(slot, out var leftPathValue);
                right.TextureAssignments.TryGetValue(slot, out var rightPathValue);
                var leftPath = NormalizeCounterfactualTextureAssignment(
                    state,
                    slot,
                    leftPathValue);
                var rightPath = NormalizeCounterfactualTextureAssignment(
                    state,
                    slot,
                    rightPathValue);

                // An unresolved test mask is removed by the real atlas rewrite. If one
                // side has that ignored mask and the other side has a real source, the
                // materials still have different effective channel sets and cannot be
                // treated as a texture-only merge.
                if (leftPath.Length == 0 || rightPath.Length == 0)
                {
                    detail =
                        $"{slot} has an ignored unresolved source on one material and a real source on the other";
                    return "Differing texture source is not atlasable";
                }

                if (!TryGetCounterfactualTextureSource(
                        state,
                        leftPath,
                        out var leftSource,
                        out var textureLeftFailure))
                {
                    detail = textureLeftFailure ??
                        $"{slot} has an unusable texture source";
                    return "Differing texture source is not atlasable";
                }

                if (!TryGetCounterfactualTextureSource(
                        state,
                        rightPath,
                        out var rightSource,
                        out var textureRightFailure))
                {
                    detail = textureRightFailure ??
                        $"{slot} has an unusable texture source";
                    return "Differing texture source is not atlasable";
                }

                var leftIsUniform = leftSource.IsUniformConstant;
                var rightIsUniform = rightSource.IsUniformConstant;
                if (leftIsUniform && rightIsUniform)
                {
                    if (!leftSource.ConstantColor.Equals(rightSource.ConstantColor))
                    {
                        if (allowDifferentUniformMaskConstants &&
                            slot.Equals("t_xml_mask", StringComparison.OrdinalIgnoreCase))
                        {
                            // Canonical faction-3 masks are deliberately packed as regions,
                            // even when both source regions happen to be uniform. A black
                            // synthesized region and a non-black uniform region therefore
                            // remain mergeable without forcing either source path to change.
                            onlyUniformConstants = false;
                            continue;
                        }

                        detail =
                            $"{slot} contains different uniform colors and cannot share one source path";
                        return "Different uniform constants";
                    }

                    continue;
                }

                onlyUniformConstants = false;
            }

            if (onlyUniformConstants)
            {
                detail = "all differing channels have the same uniform color; path canonicalization is sufficient";
                return "Uniform-constant equivalence";
            }

            detail = "all differing slots are atlas channels with readable source textures";
            return "Atlasable differing texture channels";
        }

        private static bool TryValidateCounterfactualMaterialTextureSet(
            BatchState state,
            MaterialMergeDiagnosticSnapshot material,
            out string? failure)
        {
            failure = null;
            foreach (var channel in AtlasChannels)
            {
                var hasPath = material.TextureAssignments.TryGetValue(
                    channel.Slot,
                    out var path);
                if (!hasPath || string.IsNullOrWhiteSpace(path))
                {
                    if (channel.Slot.Equals(
                            "t_xml_base_colour",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        failure = "base-colour texture assignment is missing";
                        return false;
                    }

                    continue;
                }

                if (IsTexturePlaceholder(path))
                {
                    if (channel.Slot.Equals(
                            "t_xml_base_colour",
                            StringComparison.OrdinalIgnoreCase))
                    {
                        failure = "base-colour texture assignment is a placeholder";
                        return false;
                    }

                    continue;
                }

                if (!TryGetCounterfactualTextureSource(
                        state,
                        path,
                        out _,
                        out var sourceFailure))
                {
                    if (channel.Slot.Equals(
                            "t_xml_mask",
                            StringComparison.OrdinalIgnoreCase) &&
                        IsIgnorableUnresolvedAtlasTexture(channel.Slot, path))
                    {
                        continue;
                    }

                    failure = $"{channel.Slot}: {sourceFailure}";
                    return false;
                }
            }

            return true;
        }

        private static bool TryGetCounterfactualTextureSource(
            BatchState state,
            string? texturePath,
            out TextureInspection source,
            out string failure)
        {
            source = default;
            failure = string.Empty;
            var normalizedPath = Normalize(texturePath);
            if (normalizedPath.Length == 0)
            {
                failure = "texture assignment is missing";
                return false;
            }

            if (IsTexturePlaceholder(normalizedPath))
            {
                failure = "texture assignment is a placeholder";
                return false;
            }

            // A synthesized mask slot intentionally uses the game-independent black
            // semantic. It remains a valid uniform source even when the common texture is
            // not present in the pack containers currently loaded by the planner.
            if (normalizedPath.Equals(
                    CanonicalBlackMaskTexturePath,
                    StringComparison.OrdinalIgnoreCase))
            {
                source = new TextureInspection(1, 1, true, ZeroMaskColor);
                return true;
            }

            if (state.GeneratedTexturePaths.Contains(normalizedPath))
            {
                // Generated atlases have already passed the atlas writer and can be treated as
                // non-uniform sources for this diagnostic. Their precise source composition is
                // irrelevant to the counterfactual classification.
                source = new TextureInspection(0, 0, false, default);
                return true;
            }

            var file = FindForReadStatic(state, normalizedPath);
            if (file == null)
            {
                failure = $"source texture could not be resolved: {normalizedPath}";
                return false;
            }

            try
            {
                source = GetTextureInspection(state, normalizedPath, file);
                return true;
            }
            catch (Exception ex)
            {
                failure = $"source texture could not be inspected: {normalizedPath} ({ex.Message})";
                return false;
            }
        }

        private static bool IsAtlasChannelSlot(string slot)
            => AtlasChannels.Any(channel =>
                channel.Slot.Equals(slot, StringComparison.OrdinalIgnoreCase));

        private static IEnumerable<string> GetDifferingMaterialTextureSlots(
            BatchState state,
            MaterialMergeDiagnosticSnapshot left,
            MaterialMergeDiagnosticSnapshot right)
            => left.TextureAssignments.Keys
                .Union(right.TextureAssignments.Keys, StringComparer.OrdinalIgnoreCase)
                .Where(slot =>
                {
                    left.TextureAssignments.TryGetValue(slot, out var leftPath);
                    right.TextureAssignments.TryGetValue(slot, out var rightPath);
                    return !NormalizeCounterfactualTextureAssignment(
                            state,
                            slot,
                            leftPath)
                        .Equals(
                        NormalizeCounterfactualTextureAssignment(
                            state,
                            slot,
                            rightPath),
                        StringComparison.OrdinalIgnoreCase);
                });

        private static string NormalizeCounterfactualTextureAssignment(
            BatchState state,
            string slot,
            string? path)
        {
            var normalized = Normalize(path);
            if (normalized.Length != 0 &&
                IsIgnorableUnresolvedAtlasTexture(slot, normalized) &&
                FindForReadStatic(state, normalized) == null)
            {
                // This matches candidate discovery and ProcessBatch: unresolved test_mask
                // is an absent channel, not a texture source that needs to be atlas-packed.
                return string.Empty;
            }

            return normalized;
        }

        private static void AddDiagnosticExample(
            Dictionary<string, List<string>> examplesByCategory,
            string category,
            string example)
        {
            if (!examplesByCategory.TryGetValue(category, out var examples))
            {
                examples = [];
                examplesByCategory[category] = examples;
            }

            const int maxExamplesPerCategory = 8;
            if (examples.Count < maxExamplesPerCategory &&
                !examples.Contains(example, StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private static void AnalyzeTextureBlockedMergeOpportunity(
            BatchState state,
            string rigidPath,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex,
            IReadOnlyList<RmvModel> models,
            MaterialMergeDiagnosticComparison materialComparison)
        {
            var leftKey = new MeshKey(rigidPath, lodIndex, leftPartIndex);
            var rightKey = new MeshKey(rigidPath, lodIndex, rightPartIndex);

            if (!state.AtlasBatchByMesh.TryGetValue(leftKey, out var leftBatchId) ||
                !state.AtlasBatchByMesh.TryGetValue(rightKey, out var rightBatchId) ||
                leftBatchId == rightBatchId)
            {
                return;
            }

            if (!TryGetAtlasOnlyTextureDifference(
                    state,
                    materialComparison.LeftMaterialPath,
                    materialComparison.RightMaterialPath,
                    out var textureDifferenceDetail))
            {
                return;
            }

            var leftVertices = models[leftPartIndex].Mesh.VertexList.Length;
            var rightVertices = models[rightPartIndex].Mesh.VertexList.Length;
            if ((long)leftVertices + rightVertices > ushort.MaxValue)
                return;

            var firstBatchId = Math.Min(leftBatchId, rightBatchId);
            var secondBatchId = Math.Max(leftBatchId, rightBatchId);
            var batchPair = new AtlasBatchPair(firstBatchId, secondBatchId);

            if (!state.AtlasBatchCombinationDiagnostics.TryGetValue(batchPair, out var combination))
            {
                combination = BuildAtlasBatchCombinationDiagnostic(state, batchPair);
                state.AtlasBatchCombinationDiagnostics[batchPair] = combination;
            }

            var leftMaterial = GetMaterialMergeDiagnosticSnapshot(
                state,
                materialComparison.LeftMaterialPath);
            if (leftMaterial == null)
                return;

            var opportunityKey = new TextureMergeOpportunityKey(
                rigidPath,
                lodIndex,
                GetRmvMergeIdentity(models[leftPartIndex]),
                ContentHash(leftMaterial.NonTextureIdentity),
                firstBatchId,
                secondBatchId);

            if (!state.TextureMergeOpportunities.TryGetValue(opportunityKey, out var opportunity))
            {
                opportunity = new TextureMergeOpportunityAccumulator(
                    rigidPath,
                    lodIndex,
                    firstBatchId,
                    secondBatchId,
                    combination);
                state.TextureMergeOpportunities[opportunityKey] = opportunity;
            }

            opportunity.PartIndices.Add(leftPartIndex);
            opportunity.PartIndices.Add(rightPartIndex);
            if (opportunity.Examples.Count < 4)
            {
                var example =
                    $"parts {leftPartIndex}/{rightPartIndex}: {textureDifferenceDetail}";
                if (!opportunity.Examples.Contains(example, StringComparer.Ordinal))
                    opportunity.Examples.Add(example);
            }
        }

        private static AtlasBatchCombinationDiagnostic BuildAtlasBatchCombinationDiagnostic(
            BatchState state,
            AtlasBatchPair batchPair)
        {
            if (!state.AtlasBatchDiagnostics.TryGetValue(batchPair.FirstBatchId, out var first) ||
                !state.AtlasBatchDiagnostics.TryGetValue(batchPair.SecondBatchId, out var second))
            {
                return new AtlasBatchCombinationDiagnostic(
                    false,
                    0,
                    0,
                    0,
                    0,
                    "Atlas batch metadata was unavailable.");
            }

            var baselinePixelCost = checked(first.PixelCost + second.PixelCost);
            var combinedCandidates = first.Candidates
                .Concat(second.Candidates)
                .GroupBy(x => x.Key)
                .Select(group => group.First())
                .ToList();

            if (!TryGetGeneratedAtlasPixelCost(
                    state,
                    combinedCandidates,
                    out var combinedPixelCost,
                    out _))
            {
                return new AtlasBatchCombinationDiagnostic(
                    false,
                    baselinePixelCost,
                    0,
                    0,
                    0,
                    "The combined batch exceeds the atlas size/layout limit.");
            }

            var additionalPixels = combinedPixelCost - baselinePixelCost;
            var additionalPercent = baselinePixelCost > 0
                ? additionalPixels * 100.0 / baselinePixelCost
                : 0;

            return new AtlasBatchCombinationDiagnostic(
                true,
                baselinePixelCost,
                combinedPixelCost,
                additionalPixels,
                additionalPercent,
                string.Empty);
        }

        private static bool TryGetAtlasOnlyTextureDifference(
            BatchState state,
            string leftMaterialPath,
            string rightMaterialPath,
            out string detail)
        {
            detail = string.Empty;
            var left = GetMaterialMergeDiagnosticSnapshot(state, leftMaterialPath);
            var right = GetMaterialMergeDiagnosticSnapshot(state, rightMaterialPath);
            if (left == null || right == null)
                return false;

            var differingSlots = left.TextureAssignments.Keys
                .Union(right.TextureAssignments.Keys, StringComparer.OrdinalIgnoreCase)
                .Where(slot =>
                {
                    left.TextureAssignments.TryGetValue(slot, out var leftPath);
                    right.TextureAssignments.TryGetValue(slot, out var rightPath);
                    return !Normalize(leftPath).Equals(
                        Normalize(rightPath),
                        StringComparison.OrdinalIgnoreCase);
                })
                .ToList();

            if (differingSlots.Count == 0)
                return false;

            foreach (var slot in differingSlots)
            {
                left.TextureAssignments.TryGetValue(slot, out var leftPath);
                right.TextureAssignments.TryGetValue(slot, out var rightPath);
                leftPath = Normalize(leftPath);
                rightPath = Normalize(rightPath);

                // Co-locating batches can only resolve a difference caused by generated atlas
                // paths. Missing channels, constants, vanilla textures, and other preserved
                // sources are semantic differences and are intentionally not counted here.
                if (string.IsNullOrWhiteSpace(leftPath) ||
                    string.IsNullOrWhiteSpace(rightPath) ||
                    !state.GeneratedTexturePaths.Contains(leftPath) ||
                    !state.GeneratedTexturePaths.Contains(rightPath))
                {
                    return false;
                }
            }

            detail = string.Join(
                ", ",
                differingSlots.OrderBy(x => x, StringComparer.OrdinalIgnoreCase));
            return true;
        }

        private static MaterialMergeDiagnosticComparison CompareWsMaterialAssignmentsForDiagnostics(
            BatchState state,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex,
            IReadOnlyList<string> wsModelPaths,
            IReadOnlyDictionary<string, string[][]> assignmentsByWsModel)
        {
            var pathsEqual = true;
            var semanticallyEquivalent = true;
            var reasons = new HashSet<string>(StringComparer.Ordinal);
            string? firstDetail = null;
            string? firstLeftMaterialPath = null;
            string? firstRightMaterialPath = null;

            foreach (var wsPath in wsModelPaths)
            {
                var leftPath = Normalize(assignmentsByWsModel[wsPath][lodIndex][leftPartIndex]);
                var rightPath = Normalize(assignmentsByWsModel[wsPath][lodIndex][rightPartIndex]);
                if (leftPath.Equals(rightPath, StringComparison.OrdinalIgnoreCase))
                    continue;

                pathsEqual = false;
                firstDetail ??= $"{Path.GetFileName(wsPath)}: {leftPath} <> {rightPath}";
                firstLeftMaterialPath ??= leftPath;
                firstRightMaterialPath ??= rightPath;

                var left = GetMaterialMergeDiagnosticSnapshot(state, leftPath);
                var right = GetMaterialMergeDiagnosticSnapshot(state, rightPath);
                if (left == null || right == null)
                {
                    semanticallyEquivalent = false;
                    reasons.Add("WSModel material could not be inspected");
                    continue;
                }

                if (left.RenderingIdentity.Equals(right.RenderingIdentity, StringComparison.Ordinal))
                    continue;

                semanticallyEquivalent = false;
                if (!left.Shader.Equals(right.Shader, StringComparison.OrdinalIgnoreCase))
                {
                    reasons.Add("WSModel material shader differs");
                }
                else if (!left.TextureIdentity.Equals(right.TextureIdentity, StringComparison.Ordinal) &&
                         left.NonTextureIdentity.Equals(right.NonTextureIdentity, StringComparison.Ordinal))
                {
                    reasons.Add("WSModel texture assignments differ");
                }
                else if (!left.NonTextureIdentity.Equals(right.NonTextureIdentity, StringComparison.Ordinal))
                {
                    reasons.Add("WSModel material parameters differ");
                }
                else
                {
                    reasons.Add("WSModel material rendering state differs");
                }
            }

            if (pathsEqual)
            {
                return new MaterialMergeDiagnosticComparison(
                    true,
                    true,
                    string.Empty,
                    "Material assignments are identical.",
                    string.Empty,
                    string.Empty);
            }

            if (semanticallyEquivalent)
            {
                return new MaterialMergeDiagnosticComparison(
                    false,
                    true,
                    "WSModel material paths differ but rendering identity is identical",
                    firstDetail ?? "Material paths differ.",
                    firstLeftMaterialPath ?? string.Empty,
                    firstRightMaterialPath ?? string.Empty);
            }

            var reason = reasons.Count == 1
                ? reasons.Single()
                : "Multiple WSModel material differences";
            return new MaterialMergeDiagnosticComparison(
                false,
                false,
                reason,
                firstDetail ?? reason,
                firstLeftMaterialPath ?? string.Empty,
                firstRightMaterialPath ?? string.Empty);
        }

        private static MaterialMergeDiagnosticSnapshot? GetMaterialMergeDiagnosticSnapshot(
            BatchState state,
            string materialPath,
            XmlDocument? materialOverride = null)
        {
            materialPath = Normalize(materialPath);
            if (materialOverride == null &&
                state.MeshMergeMaterialDiagnostics.TryGetValue(materialPath, out var cached))
                return cached;

            try
            {
                XmlDocument material;
                if (materialOverride != null)
                {
                    material = materialOverride;
                }
                else
                {
                    var file = FindForReadStatic(state, materialPath);
                    if (file == null)
                    {
                        state.MeshMergeMaterialDiagnostics[materialPath] = null;
                        return null;
                    }

                    material = GetMaterialDocument(state, materialPath, file);
                }

                var shader = Normalize(material.SelectSingleNode("/material/shader")?.InnerText);

                var textureAssignments = material.SelectNodes("/material/textures/texture")?
                    .Cast<XmlNode>()
                    .Select(node => new
                    {
                        Slot = GetTextureSlot(node),
                        Source = Normalize(
                            node.SelectSingleNode("source")?.InnerText ?? node.InnerText)
                    })
                    .Where(x => !string.IsNullOrWhiteSpace(x.Slot))
                    .GroupBy(x => x.Slot, StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(
                        group => group.Key,
                        group => group.First().Source,
                        StringComparer.OrdinalIgnoreCase)
                    ?? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                var textureIdentity = string.Join(
                    "\u001f",
                    textureAssignments
                        .OrderBy(x => x.Key, StringComparer.Ordinal)
                        .Select(x => $"{x.Key}={x.Value}"));

                var nonTexture = new XmlDocument();
                nonTexture.LoadXml(material.OuterXml);
                var nameNode = nonTexture.SelectSingleNode("/material/name");
                nameNode?.ParentNode?.RemoveChild(nameNode);
                var texturesNode = nonTexture.SelectSingleNode("/material/textures");
                texturesNode?.ParentNode?.RemoveChild(texturesNode);
                NormalizeMaterialResourcePaths(nonTexture);

                var snapshot = new MaterialMergeDiagnosticSnapshot(
                    GetMaterialRenderingIdentity(material),
                    shader,
                    textureIdentity,
                    nonTexture.OuterXml,
                    textureAssignments,
                    BuildMaterialLeafFieldMap(nonTexture));
                if (materialOverride == null)
                    state.MeshMergeMaterialDiagnostics[materialPath] = snapshot;
                return snapshot;
            }
            catch
            {
                if (materialOverride == null)
                    state.MeshMergeMaterialDiagnostics[materialPath] = null;
                return null;
            }
        }

        private static void RecordMaterialMergeBlockerBreakdown(
            BatchState state,
            MaterialMergeDiagnosticComparison comparison)
        {
            var left = GetMaterialMergeDiagnosticSnapshot(state, comparison.LeftMaterialPath);
            var right = GetMaterialMergeDiagnosticSnapshot(state, comparison.RightMaterialPath);
            if (left == null || right == null)
                return;

            if (!left.Shader.Equals(right.Shader, StringComparison.OrdinalIgnoreCase))
            {
                var shaders = new[] { left.Shader, right.Shader }
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                IncrementDiagnosticCount(
                    state.MaterialShaderPairBlockerCounts,
                    $"{FormatDiagnosticValue(shaders[0])} <> {FormatDiagnosticValue(shaders[1])}");
                return;
            }

            if (!left.TextureIdentity.Equals(right.TextureIdentity, StringComparison.Ordinal) &&
                left.NonTextureIdentity.Equals(right.NonTextureIdentity, StringComparison.Ordinal))
            {
                var differingSlots = left.TextureAssignments.Keys
                    .Union(right.TextureAssignments.Keys, StringComparer.OrdinalIgnoreCase)
                    .Where(slot =>
                    {
                        left.TextureAssignments.TryGetValue(slot, out var leftPath);
                        right.TextureAssignments.TryGetValue(slot, out var rightPath);
                        return !Normalize(leftPath).Equals(
                            Normalize(rightPath),
                            StringComparison.OrdinalIgnoreCase);
                    });

                foreach (var slot in differingSlots)
                {
                    left.TextureAssignments.TryGetValue(slot, out var leftPath);
                    right.TextureAssignments.TryGetValue(slot, out var rightPath);

                    var texturePair = new[]
                    {
                        (
                            Class: ClassifyMaterialTexturePath(state, leftPath),
                            Path: Normalize(leftPath)),
                        (
                            Class: ClassifyMaterialTexturePath(state, rightPath),
                            Path: Normalize(rightPath))
                    }.OrderBy(
                        x => $"{x.Class}\0{x.Path}",
                        StringComparer.OrdinalIgnoreCase).ToArray();

                    var blockerKey =
                        $"{slot} [{texturePair[0].Class} <> {texturePair[1].Class}]";
                    if (texturePair.Any(x =>
                            x.Class.Equals("preserved", StringComparison.Ordinal)))
                    {
                        blockerKey +=
                            $": {FormatDiagnosticValue(texturePair[0].Path)} <> " +
                            $"{FormatDiagnosticValue(texturePair[1].Path)}";
                    }

                    IncrementDiagnosticCount(
                        state.MaterialTextureSlotBlockerCounts,
                        blockerKey);
                }

                return;
            }

            if (!left.NonTextureIdentity.Equals(right.NonTextureIdentity, StringComparison.Ordinal))
            {
                foreach (var field in left.NonTextureFields.Keys
                             .Union(right.NonTextureFields.Keys, StringComparer.Ordinal)
                             .Where(field =>
                             {
                                 left.NonTextureFields.TryGetValue(field, out var leftValue);
                                 right.NonTextureFields.TryGetValue(field, out var rightValue);
                                 return !string.Equals(leftValue, rightValue, StringComparison.Ordinal);
                             }))
                {
                    var hasLeftValue = left.NonTextureFields.TryGetValue(field, out var leftValue);
                    var hasRightValue = right.NonTextureFields.TryGetValue(field, out var rightValue);
                    var values = new[]
                    {
                        hasLeftValue ? FormatDiagnosticValue(leftValue!) : "<missing>",
                        hasRightValue ? FormatDiagnosticValue(rightValue!) : "<missing>"
                    }.OrderBy(x => x, StringComparer.Ordinal).ToArray();

                    var fieldLabel = field.StartsWith("param:", StringComparison.Ordinal)
                        ? field["param:".Length..]
                        : field.StartsWith("param-type:", StringComparison.Ordinal)
                            ? $"{field["param-type:".Length..]} (type)"
                            : field;

                    IncrementDiagnosticCount(
                        state.MaterialParameterFieldBlockerCounts,
                        $"{fieldLabel}: {values[0]} <> {values[1]}");
                }
            }
        }

        private static string ClassifyMaterialTexturePath(
            BatchState state,
            string? texturePath)
        {
            var normalized = Normalize(texturePath);
            if (string.IsNullOrWhiteSpace(normalized))
                return "missing";
            if (state.GeneratedTexturePaths.Contains(normalized))
                return "generated-atlas";
            if (state.UniformConstantTexturePaths.Contains(normalized) ||
                IsKnownConstantTexturePath(normalized))
            {
                return "uniform-constant";
            }
            if (IsTexturePlaceholder(normalized))
                return "placeholder";
            return "preserved";
        }

        private static string FormatDiagnosticValue(string value)
            => string.IsNullOrWhiteSpace(value) ? "<none>" : value;

        private static void IncrementDiagnosticCount(
            Dictionary<string, int> counts,
            string key)
        {
            counts[key] = counts.GetValueOrDefault(key) + 1;
        }

        private static IReadOnlyDictionary<string, string> BuildMaterialLeafFieldMap(
            XmlDocument material)
        {
            var result = new Dictionary<string, string>(StringComparer.Ordinal);
            var root = material.DocumentElement;
            if (root == null)
                return result;

            void Visit(XmlNode node, string path)
            {
                if (node.Name.Equals("param", StringComparison.Ordinal) &&
                    node.ParentNode?.Name.Equals("params", StringComparison.Ordinal) == true)
                {
                    var parameterName = node.SelectSingleNode("name")?.InnerText.Trim();
                    var parameterType = node.SelectSingleNode("type")?.InnerText.Trim();
                    var values = node.SelectNodes("value")?.Cast<XmlNode>().ToList() ?? [];

                    if (!string.IsNullOrWhiteSpace(parameterName))
                    {
                        if (!string.IsNullOrWhiteSpace(parameterType))
                            result[$"param-type:{parameterName}"] = parameterType;

                        for (var valueIndex = 0; valueIndex < values.Count; valueIndex++)
                        {
                            var key = values.Count == 1
                                ? $"param:{parameterName}"
                                : $"param:{parameterName}[{valueIndex}]";
                            result[key] = values[valueIndex].InnerText.Trim();
                        }

                        if (values.Count != 0)
                            return;
                    }
                }

                if (node.Attributes != null)
                {
                    foreach (XmlAttribute attribute in node.Attributes
                                 .Cast<XmlAttribute>()
                                 .OrderBy(x => x.Name, StringComparer.Ordinal))
                    {
                        result[$"{path}/@{attribute.Name}"] = attribute.Value;
                    }
                }

                var elementChildren = node.ChildNodes
                    .Cast<XmlNode>()
                    .Where(x => x.NodeType == XmlNodeType.Element)
                    .ToList();
                if (elementChildren.Count == 0)
                {
                    result[path] = node.InnerText.Trim();
                    return;
                }

                var siblingCounts = new Dictionary<string, int>(StringComparer.Ordinal);
                foreach (var child in elementChildren)
                {
                    var childIndex = siblingCounts.GetValueOrDefault(child.Name);
                    siblingCounts[child.Name] = childIndex + 1;
                    Visit(child, $"{path}/{child.Name}[{childIndex}]");
                }
            }

            Visit(root, $"/{root.Name}");
            return result;
        }

        private static RmvMergeDiagnosticComponents GetRmvMergeDiagnosticComponents(
            RmvModel model,
            bool includeEmbeddedMaterialIdentity = false)
        {
            var material = model.Material.Clone();
            if (!includeEmbeddedMaterialIdentity && material is WeightedMaterial weighted)
            {
                weighted.ModelName = string.Empty;
                weighted.TextureDirectory = string.Empty;
                weighted.TexturesParams = [];
            }

            var materialBytes = MaterialFactory.Create().Save(
                model.CommonHeader.ModelTypeFlag,
                material);

            return new RmvMergeDiagnosticComponents(
                model.CommonHeader.ModelTypeFlag.ToString(),
                model.CommonHeader.RenderFlag.ToString(),
                model.Material.BinaryVertexFormat.ToString(),
                model.CommonHeader.ShaderParams.ShaderName ?? string.Empty,
                ContentHash(Convert.ToHexString(materialBytes)));
        }

        private static string GetCrossRigidSourcePartMergeIdentity(
            BatchState state,
            string rigidPath,
            int lodIndex,
            int partIndex,
            RmvModel model,
            string materialPath)
        {
            // The same source part is inspected repeatedly across attachment
            // alternatives, LOD states and VMD roots. RMV identity serializes
            // embedded material metadata; material identity may parse XML.
            // Both depend only on the source part / material during the
            // cross-rigid analysis and emission stages.
            var meshKey = new MeshKey(
                Normalize(rigidPath),
                lodIndex,
                partIndex);
            if (!state.CrossRigidSourceMeshMergeIdentityCache.TryGetValue(
                    meshKey,
                    out var modelIdentity))
            {
                modelIdentity = GetRmvMergeIdentityForMerge(
                    model,
                    includeEmbeddedMaterialIdentity: false);
                state.CrossRigidSourceMeshMergeIdentityCache[meshKey] =
                    modelIdentity;
            }

            var normalizedMaterialPath = Normalize(materialPath);
            if (!state.CrossRigidMaterialMergeIdentityCache.TryGetValue(
                    normalizedMaterialPath,
                    out var materialIdentity))
            {
                materialIdentity = GetMeshMergeMaterialIdentity(
                    state,
                    normalizedMaterialPath);
                state.CrossRigidMaterialMergeIdentityCache[
                    normalizedMaterialPath] = materialIdentity;
            }

            // Evaluate the logical atlas boundary on each use: it may vary
            // between physical mesh states and is not covered by either cache.
            return string.Join(
                "\u001e",
                GetAtlasBatchMergeBoundaryIdentity(
                    state,
                    meshKey),
                modelIdentity,
                materialIdentity);
        }

        private static string GetRmvMergeIdentityForMerge(
            RmvModel model,
            bool includeEmbeddedMaterialIdentity)
            => includeEmbeddedMaterialIdentity
                ? GetDirectRmvMergeIdentity(model)
                : GetRmvMergeIdentity(model);

        private static List<string> GetRmvMergeDiagnosticDifferences(
            RmvMergeDiagnosticComponents left,
            RmvMergeDiagnosticComponents right)
        {
            var differences = new List<string>(5);

            if (!left.ModelTypeFlag.Equals(right.ModelTypeFlag, StringComparison.Ordinal))
                differences.Add("RMV model type differs");
            if (!left.RenderFlag.Equals(right.RenderFlag, StringComparison.Ordinal))
                differences.Add("RMV render flag differs");
            if (!left.VertexFormat.Equals(right.VertexFormat, StringComparison.Ordinal))
                differences.Add("RMV vertex format differs");
            if (!left.ShaderName.Equals(right.ShaderName, StringComparison.Ordinal))
                differences.Add("RMV shader name differs");
            if (!left.MaterialPayloadHash.Equals(right.MaterialPayloadHash, StringComparison.Ordinal))
                differences.Add("RMV embedded material payload differs");

            return differences;
        }

        private static void RecordMeshMergeBlocker(
            BatchState state,
            string reason,
            string example,
            int occurrences = 1)
        {
            if (state.MeshMergeBlockerCounts.TryGetValue(reason, out var existing))
                state.MeshMergeBlockerCounts[reason] = existing + occurrences;
            else
                state.MeshMergeBlockerCounts[reason] = occurrences;

            if (!state.MeshMergeBlockerExamples.TryGetValue(reason, out var examples))
            {
                examples = [];
                state.MeshMergeBlockerExamples[reason] = examples;
            }

            const int maxExamplesPerReason = 8;
            if (examples.Count < maxExamplesPerReason &&
                !examples.Contains(example, StringComparer.Ordinal))
            {
                examples.Add(example);
            }
        }

        private static string BuildMeshMergeBlockerExample(
            string rigidPath,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex,
            string detail)
            => $"{rigidPath} [lod {lodIndex}, parts {leftPartIndex}/{rightPartIndex}]: {detail}";

        private static string BuildStructuralMergePairKey(
            string rigidPath,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex)
        {
            var first = Math.Min(leftPartIndex, rightPartIndex);
            var second = Math.Max(leftPartIndex, rightPartIndex);
            return $"{Normalize(rigidPath)}|{lodIndex}|{first}|{second}";
        }

        private static bool IsPreAtlasStructuralMergeGroup(
            BatchState state,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<int> partIndices)
        {
            if (partIndices.Count < 2)
                return false;

            for (var left = 0; left < partIndices.Count; left++)
            {
                for (var right = left + 1;
                     right < partIndices.Count;
                     right++)
                {
                    if (!state.PreAtlasStructuralMergePairs.Contains(
                            BuildStructuralMergePairKey(
                                rigidPath,
                                lodIndex,
                                partIndices[left],
                                partIndices[right])))
                    {
                        return false;
                    }
                }
            }

            return true;
        }

        private static string GetMeshMergeOrigin(
            BatchState state,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<int> partIndices)
        {
            if (IsPreAtlasStructuralMergeGroup(
                    state,
                    rigidPath,
                    lodIndex,
                    partIndices))
            {
                return "structural-only";
            }

            var hasPreExistingPair = false;
            for (var left = 0; left < partIndices.Count && !hasPreExistingPair; left++)
            {
                for (var right = left + 1;
                     right < partIndices.Count;
                     right++)
                {
                    if (state.PreAtlasStructuralMergePairs.Contains(
                            BuildStructuralMergePairKey(
                                rigidPath,
                                lodIndex,
                                partIndices[left],
                                partIndices[right])))
                    {
                        hasPreExistingPair = true;
                        break;
                    }
                }
            }

            return hasPreExistingPair
                ? "structural+atlas-assisted"
                : "atlas-assisted";
        }

        private static void RecordMeshMergeOrigin(
            BatchState state,
            string mergeOrigin)
        {
            if (mergeOrigin.Equals("structural-only", StringComparison.Ordinal))
                state.StructuralOnlyMergeGroupCount++;
            else if (mergeOrigin.Equals(
                         "structural+atlas-assisted",
                         StringComparison.Ordinal))
                state.StructuralAndAtlasAssistedMergeGroupCount++;
            else
                state.AtlasAssistedMergeGroupCount++;
        }

        private static string[] GetPreExistingStructuralMergePairs(
            BatchState state,
            IReadOnlyList<MeshKey> meshes)
        {
            if (meshes.Count < 2)
                return [];

            var pairs = new List<string>();
            for (var left = 0; left < meshes.Count; left++)
            {
                for (var right = left + 1; right < meshes.Count; right++)
                {
                    var pair = BuildStructuralMergePairKey(
                        meshes[left].GeometryPath,
                        meshes[left].LodIndex,
                        meshes[left].PartIndex,
                        meshes[right].PartIndex);
                    if (state.PreAtlasStructuralMergePairs.Contains(pair))
                        pairs.Add(pair);
                }
            }

            return pairs.ToArray();
        }

        private static string[] FilterPreExistingStructuralMergePairs(
            MergeAffinityGroup group,
            IReadOnlyList<MeshKey> meshes)
        {
            if (meshes.Count < 2 || group.PreExistingStructuralMergePairs.Length == 0)
                return [];

            var existingPairs = group.PreExistingStructuralMergePairs
                .ToHashSet(StringComparer.Ordinal);
            var pairs = new List<string>();
            for (var left = 0; left < meshes.Count; left++)
            {
                for (var right = left + 1; right < meshes.Count; right++)
                {
                    var pair = BuildStructuralMergePairKey(
                        meshes[left].GeometryPath,
                        meshes[left].LodIndex,
                        meshes[left].PartIndex,
                        meshes[right].PartIndex);
                    if (existingPairs.Contains(pair))
                        pairs.Add(pair);
                }
            }

            return pairs.ToArray();
        }

        private static List<MeshMergeGroup> BuildMeshMergeGroups(
            BatchState state,
            IReadOnlyList<RmvModel> models,
            int lodIndex,
            string rigidPath,
            IReadOnlyList<string> wsModelPaths,
            IReadOnlyDictionary<string, string[][]> assignmentsByWsModel,
            bool recordDiagnostics = true,
            bool includeEmbeddedMaterialIdentity = false)
        {
            var buckets = new Dictionary<string, List<int>>(StringComparer.Ordinal);

            for (var partIndex = 0; partIndex < models.Count; partIndex++)
            {
                var materialPaths = wsModelPaths
                    .Select(wsPath => assignmentsByWsModel[wsPath][lodIndex][partIndex])
                    .ToArray();

                var materialIdentities = materialPaths
                    .Select(path => GetMeshMergeMaterialIdentity(state, path))
                    .ToArray();

                var identity = string.Join(
                    "\u001e",
                    GetAtlasBatchMergeBoundaryIdentity(
                        state,
                        new MeshKey(rigidPath, lodIndex, partIndex)),
                    GetRmvMergeIdentityForMerge(
                        models[partIndex],
                        includeEmbeddedMaterialIdentity),
                    string.Join("\u001f", materialIdentities));

                if (!buckets.TryGetValue(identity, out var parts))
                {
                    parts = [];
                    buckets.Add(identity, parts);
                }

                parts.Add(partIndex);
            }

            var groups = new List<MeshMergeGroup>();
            foreach (var parts in buckets.Values)
            {
                var current = new List<int>();
                var currentVertexCount = 0;

                foreach (var partIndex in parts.OrderBy(x => x))
                {
                    var vertexCount = models[partIndex].Mesh.VertexList.Length;
                    if (vertexCount > ushort.MaxValue)
                    {
                        if (current.Count != 0)
                        {
                            groups.Add(CreateMeshMergeGroup(
                                current,
                                lodIndex,
                                wsModelPaths,
                                assignmentsByWsModel));
                            current = [];
                            currentVertexCount = 0;
                        }

                        groups.Add(CreateMeshMergeGroup(
                            [partIndex],
                            lodIndex,
                            wsModelPaths,
                            assignmentsByWsModel));
                        continue;
                    }

                    if (current.Count != 0 &&
                        currentVertexCount + vertexCount > ushort.MaxValue)
                    {
                        groups.Add(CreateMeshMergeGroup(
                            current,
                            lodIndex,
                            wsModelPaths,
                            assignmentsByWsModel));
                        current = [];
                        currentVertexCount = 0;
                    }

                    current.Add(partIndex);
                    currentVertexCount += vertexCount;
                }

                if (current.Count != 0)
                {
                    groups.Add(CreateMeshMergeGroup(
                        current,
                        lodIndex,
                        wsModelPaths,
                        assignmentsByWsModel));
                }
            }

            foreach (var group in groups.Where(x => x.PartIndices.Count > 1))
            {
                if (recordDiagnostics)
                {
                    var mergedAcrossEquivalentPaths = wsModelPaths.Any(wsPath =>
                        group.PartIndices
                            .Select(partIndex => Normalize(assignmentsByWsModel[wsPath][lodIndex][partIndex]))
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .Skip(1)
                            .Any());

                    if (mergedAcrossEquivalentPaths)
                        state.SemanticMaterialPathMergeParts += group.PartIndices.Count - 1;
                }
            }

            return groups
                .OrderBy(x => x.PartIndices.Min())
                .ToList();
        }

        private static string GetMeshMergeMaterialIdentity(
            BatchState state,
            string materialPath)
        {
            var normalizedPath = Normalize(materialPath);
            var snapshot = GetMaterialMergeDiagnosticSnapshot(state, normalizedPath);
            return snapshot == null
                ? $"path:{normalizedPath}"
                : $"render:{snapshot.RenderingIdentity}";
        }

        private static MeshMergeGroup CreateMeshMergeGroup(
            List<int> partIndices,
            int lodIndex,
            IReadOnlyList<string> wsModelPaths,
            IReadOnlyDictionary<string, string[][]> assignmentsByWsModel)
        {
            var representativePart = partIndices[0];
            var materialPaths = wsModelPaths
                .Select(wsPath => assignmentsByWsModel[wsPath][lodIndex][representativePart])
                .ToArray();

            return new MeshMergeGroup(partIndices.ToList(), materialPaths);
        }

        private static string GetRmvMergeIdentity(RmvModel model)
        {
            var material = model.Material.Clone();
            if (material is WeightedMaterial weighted)
            {
                // WSModel materials own texture/shader selection in this workflow. Keep all
                // transform/bone/parameter state strict, but ignore redundant embedded texture
                // paths and descriptive names that do not affect the merged geometry.
                weighted.ModelName = string.Empty;
                weighted.TextureDirectory = string.Empty;
                weighted.TexturesParams = [];
            }

            var materialBytes = MaterialFactory.Create().Save(
                model.CommonHeader.ModelTypeFlag,
                material);

            var shaderParams = model.CommonHeader.ShaderParams;

            var identity = string.Join(
                "|",
                model.CommonHeader.ModelTypeFlag,
                model.CommonHeader.RenderFlag,
                model.Material.BinaryVertexFormat,
                shaderParams.ShaderName,
                // UnknownValues and AllZeroValues are preserved from the representative RMV
                // header when meshes are merged, but intentionally excluded from compatibility.
                // Asset Editor has no known semantics for either field, and Morrigan contains
                // otherwise-identical render groups fragmented only by non-zero garbage bytes.
                Convert.ToHexString(materialBytes));

            return ContentHash(identity);
        }

        private static string GetAtlasBatchMergeBoundaryIdentity(
            BatchState? state,
            MeshKey meshKey)
        {
            if (state != null &&
                state.AtlasBatchByMesh.TryGetValue(meshKey, out var atlasBatchId))
            {
                return $"atlas-batch:{atlasBatchId}";
            }

            return "atlas-batch:none";
        }

        private static bool TryGetLogicalAtlasBatchBoundary(
            BatchState state,
            string rigidPath,
            int lodIndex,
            int leftPartIndex,
            int rightPartIndex,
            out string detail)
        {
            detail = string.Empty;
            if (!state.AtlasBatchByMesh.TryGetValue(
                    new MeshKey(rigidPath, lodIndex, leftPartIndex),
                    out var leftBatchId) ||
                !state.AtlasBatchByMesh.TryGetValue(
                    new MeshKey(rigidPath, lodIndex, rightPartIndex),
                    out var rightBatchId) ||
                leftBatchId == rightBatchId)
            {
                return false;
            }

            detail =
                $"logical atlas batches {leftBatchId} and {rightBatchId} remain separate";
            return true;
        }

        private static MergeGeometryInvariantSnapshot CaptureMergeGroupInvariant(
            IReadOnlyList<RmvModel> models,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<int> partIndices)
        {
            var vertexCount = models.Sum(x => x.Mesh.VertexList.Length);
            var indexCount = models.Sum(x => x.Mesh.IndexList.Length);
            if (indexCount % 3 != 0)
            {
                throw new InvalidOperationException(
                    $"Cannot merge {rigidPath} LOD {lodIndex} parts " +
                    $"[{string.Join(", ", partIndices)}]: index count {indexCount} is not divisible by 3.");
            }

            var expectedIndices = new ushort[indexCount];
            var indexOffset = 0;
            var vertexOffset = 0;
            foreach (var model in models)
            {
                for (var i = 0; i < model.Mesh.IndexList.Length; i++)
                {
                    var sourceIndex = model.Mesh.IndexList[i];
                    if (sourceIndex >= model.Mesh.VertexList.Length)
                    {
                        throw new InvalidOperationException(
                            $"Cannot merge {rigidPath} LOD {lodIndex}: source mesh contains " +
                            $"invalid vertex index {sourceIndex} for {model.Mesh.VertexList.Length} vertices.");
                    }

                    var mergedIndex = checked(sourceIndex + vertexOffset);
                    if (mergedIndex > ushort.MaxValue)
                    {
                        throw new InvalidOperationException(
                            $"Cannot merge {rigidPath} LOD {lodIndex}: merged index exceeds 16-bit range.");
                    }

                    expectedIndices[indexOffset++] = (ushort)mergedIndex;
                }

                vertexOffset += model.Mesh.VertexList.Length;
            }

            return new MergeGeometryInvariantSnapshot(
                vertexCount,
                indexCount,
                indexCount / 3,
                ComputeVertexSequenceHash(models.SelectMany(x => x.Mesh.VertexList)),
                expectedIndices,
                models.Min(x => x.CommonHeader.BoundingBox.MinimumX),
                models.Min(x => x.CommonHeader.BoundingBox.MinimumY),
                models.Min(x => x.CommonHeader.BoundingBox.MinimumZ),
                models.Max(x => x.CommonHeader.BoundingBox.MaximumX),
                models.Max(x => x.CommonHeader.BoundingBox.MaximumY),
                models.Max(x => x.CommonHeader.BoundingBox.MaximumZ));
        }

        private static void ValidateMergedGroupGeometry(
            MergeGeometryInvariantSnapshot expected,
            RmvModel merged,
            string rigidPath,
            int lodIndex,
            IReadOnlyList<int> partIndices)
        {
            var label = $"{rigidPath} LOD {lodIndex} parts [{string.Join(", ", partIndices)}]";

            if (merged.Mesh.VertexList.Length != expected.VertexCount)
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: vertex count changed " +
                    $"from {expected.VertexCount} to {merged.Mesh.VertexList.Length}.");
            }

            if (merged.Mesh.IndexList.Length != expected.IndexCount)
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: index count changed " +
                    $"from {expected.IndexCount} to {merged.Mesh.IndexList.Length}.");
            }

            if (merged.Mesh.IndexList.Length % 3 != 0 ||
                merged.Mesh.IndexList.Length / 3 != expected.TriangleCount)
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: triangle count changed.");
            }

            var mergedVertexHash = ComputeVertexSequenceHash(merged.Mesh.VertexList);
            if (!expected.VertexHash.Equals(mergedVertexHash, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: vertex data/order changed.");
            }

            if (!merged.Mesh.IndexList.SequenceEqual(expected.ExpectedIndices))
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: triangle/index mapping changed.");
            }

            var bounds = merged.CommonHeader.BoundingBox;
            if (!bounds.MinimumX.Equals(expected.MinimumX) ||
                !bounds.MinimumY.Equals(expected.MinimumY) ||
                !bounds.MinimumZ.Equals(expected.MinimumZ) ||
                !bounds.MaximumX.Equals(expected.MaximumX) ||
                !bounds.MaximumY.Equals(expected.MaximumY) ||
                !bounds.MaximumZ.Equals(expected.MaximumZ))
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {label}: merged bounds do not equal " +
                    $"the union of source bounds.");
            }
        }

        private static LodGeometryInvariantSnapshot CaptureLodGeometryInvariant(
            IReadOnlyList<RmvModel> models,
            string rigidPath,
            int lodIndex)
        {
            var indexCount = models.Sum(x => x.Mesh.IndexList.Length);
            if (indexCount % 3 != 0)
            {
                throw new InvalidOperationException(
                    $"Cannot merge {rigidPath} LOD {lodIndex}: total index count {indexCount} is not divisible by 3.");
            }

            return new LodGeometryInvariantSnapshot(
                models.Sum(x => x.Mesh.VertexList.Length),
                indexCount,
                indexCount / 3);
        }

        private static void ValidateLodGeometryInvariant(
            LodGeometryInvariantSnapshot expected,
            IReadOnlyList<RmvModel> models,
            string rigidPath,
            int lodIndex)
        {
            var vertexCount = models.Sum(x => x.Mesh.VertexList.Length);
            var indexCount = models.Sum(x => x.Mesh.IndexList.Length);
            if (indexCount % 3 != 0)
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {rigidPath} LOD {lodIndex}: " +
                    $"post-merge index count {indexCount} is not divisible by 3.");
            }

            var triangleCount = indexCount / 3;
            if (vertexCount != expected.VertexCount ||
                indexCount != expected.IndexCount ||
                triangleCount != expected.TriangleCount)
            {
                throw new InvalidOperationException(
                    $"Mesh merge geometry invariant failed for {rigidPath} LOD {lodIndex}: " +
                    $"geometry totals changed from {expected.VertexCount} vertices / " +
                    $"{expected.IndexCount} indices / {expected.TriangleCount} triangles to " +
                    $"{vertexCount} / {indexCount} / {triangleCount}.");
            }
        }

        private static string ComputeVertexSequenceHash(IEnumerable<CommonVertex> vertices)
        {
            using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);

            static void AppendInt32(IncrementalHash hash, int value)
                => hash.AppendData(BitConverter.GetBytes(value));

            static void AppendSingle(IncrementalHash hash, float value)
                => AppendInt32(hash, BitConverter.SingleToInt32Bits(value));

            static void AppendBytes(IncrementalHash hash, byte[]? values)
            {
                if (values == null)
                {
                    AppendInt32(hash, -1);
                    return;
                }

                AppendInt32(hash, values.Length);
                hash.AppendData(values);
            }

            static void AppendSingles(IncrementalHash hash, float[]? values)
            {
                if (values == null)
                {
                    AppendInt32(hash, -1);
                    return;
                }

                AppendInt32(hash, values.Length);
                foreach (var value in values)
                    AppendSingle(hash, value);
            }

            foreach (var vertex in vertices)
            {
                AppendSingle(hash, vertex.Position.X);
                AppendSingle(hash, vertex.Position.Y);
                AppendSingle(hash, vertex.Position.Z);
                AppendSingle(hash, vertex.Position.W);

                AppendSingle(hash, vertex.Normal.X);
                AppendSingle(hash, vertex.Normal.Y);
                AppendSingle(hash, vertex.Normal.Z);
                AppendSingle(hash, vertex.BiNormal.X);
                AppendSingle(hash, vertex.BiNormal.Y);
                AppendSingle(hash, vertex.BiNormal.Z);
                AppendSingle(hash, vertex.Tangent.X);
                AppendSingle(hash, vertex.Tangent.Y);
                AppendSingle(hash, vertex.Tangent.Z);

                AppendSingle(hash, vertex.Uv.X);
                AppendSingle(hash, vertex.Uv.Y);
                AppendSingle(hash, vertex.Uv1.X);
                AppendSingle(hash, vertex.Uv1.Y);

                AppendSingle(hash, vertex.Colour.X);
                AppendSingle(hash, vertex.Colour.Y);
                AppendSingle(hash, vertex.Colour.Z);
                AppendSingle(hash, vertex.Colour.W);

                AppendBytes(hash, vertex.BoneIndex);
                AppendSingles(hash, vertex.BoneWeight);
                AppendInt32(hash, vertex.WeightCount);
            }

            return Convert.ToHexString(hash.GetHashAndReset());
        }

        private static string GetWsModelNonMaterialIdentity(XmlDocument document)
        {
            var clone = new XmlDocument();
            clone.LoadXml(document.OuterXml);

            var materialNodes = clone.SelectNodes("/model/materials/material");
            if (materialNodes != null)
            {
                foreach (XmlNode materialNode in materialNodes.Cast<XmlNode>().ToList())
                    materialNode.ParentNode?.RemoveChild(materialNode);
            }

            return clone.OuterXml;
        }

        private static RmvModel MergeRmvModels(IReadOnlyList<RmvModel> models)
        {
            if (models.Count == 0)
                throw new ArgumentException("At least one RMV model is required.", nameof(models));
            if (models.Count == 1)
                return models[0];

            var totalVertices = models.Sum(x => x.Mesh.VertexList.Length);
            if (totalVertices > ushort.MaxValue)
            {
                throw new InvalidOperationException(
                    $"Merged RMV mesh would contain {totalVertices} vertices, exceeding the 16-bit index limit.");
            }

            var vertices = new List<CommonVertex>(totalVertices);
            var indices = new List<ushort>(models.Sum(x => x.Mesh.IndexList.Length));
            var vertexOffset = 0;

            foreach (var model in models)
            {
                vertices.AddRange(model.Mesh.VertexList);

                foreach (var index in model.Mesh.IndexList)
                {
                    var mergedIndex = checked(index + vertexOffset);
                    if (mergedIndex > ushort.MaxValue)
                        throw new InvalidOperationException("Merged RMV mesh index exceeds 16-bit range.");
                    indices.Add((ushort)mergedIndex);
                }

                vertexOffset += model.Mesh.VertexList.Length;
            }

            var header = models[0].CommonHeader;
            header.BoundingBox.MinimumX = models.Min(x => x.CommonHeader.BoundingBox.MinimumX);
            header.BoundingBox.MinimumY = models.Min(x => x.CommonHeader.BoundingBox.MinimumY);
            header.BoundingBox.MinimumZ = models.Min(x => x.CommonHeader.BoundingBox.MinimumZ);
            header.BoundingBox.MaximumX = models.Max(x => x.CommonHeader.BoundingBox.MaximumX);
            header.BoundingBox.MaximumY = models.Max(x => x.CommonHeader.BoundingBox.MaximumY);
            header.BoundingBox.MaximumZ = models.Max(x => x.CommonHeader.BoundingBox.MaximumZ);

            return new RmvModel
            {
                CommonHeader = header,
                Material = models[0].Material.Clone(),
                Mesh = new RmvMesh
                {
                    VertexList = vertices.ToArray(),
                    IndexList = indices.ToArray()
                }
            };
        }

        private static bool TryReadWsMaterialAssignments(
            XmlDocument document,
            RmvFile rmv,
            out string[][] assignments,
            out string reason,
            bool allowUnreferencedMaterialEntries = false)
        {
            assignments = new string[rmv.ModelList.Length][];
            reason = string.Empty;

            var materialNodes = document.SelectNodes("/model/materials/material");
            if (materialNodes == null)
            {
                reason = "WSModel has no material table.";
                return false;
            }

            var byKey = new Dictionary<(int Lod, int Part), string>();
            foreach (XmlNode node in materialNodes)
            {
                if (!TryParseIndex(node, "lod_index", out var lodIndex) ||
                    !TryParseIndex(node, "part_index", out var partIndex))
                {
                    reason = "WSModel contains a material entry without valid lod_index/part_index.";
                    return false;
                }

                if (!byKey.TryAdd((lodIndex, partIndex), Normalize(node.InnerText)))
                {
                    reason = $"WSModel contains duplicate material entry for LOD {lodIndex}, part {partIndex}.";
                    return false;
                }
            }

            var expectedCount = 0;
            for (var lodIndex = 0; lodIndex < rmv.ModelList.Length; lodIndex++)
            {
                assignments[lodIndex] = new string[rmv.ModelList[lodIndex].Length];
                expectedCount += assignments[lodIndex].Length;

                for (var partIndex = 0; partIndex < assignments[lodIndex].Length; partIndex++)
                {
                    if (!byKey.TryGetValue((lodIndex, partIndex), out var materialPath) ||
                        string.IsNullOrWhiteSpace(materialPath))
                    {
                        reason = $"WSModel is missing material entry for LOD {lodIndex}, part {partIndex}.";
                        return false;
                    }

                    assignments[lodIndex][partIndex] = materialPath;
                }
            }

            // In the cross-rigid copy-on-write path alone, allow obsolete
            // material assignments for LOD/part indices absent from the
            // current rigid. Required assignments were all verified above.
            // The generated WSModel is emitted with an exact replacement
            // table, so no unused source rows are carried forward.
            if (!allowUnreferencedMaterialEntries &&
                byKey.Count != expectedCount)
            {
                reason =
                    $"WSModel material table contains {byKey.Count} entries but rigid expects {expectedCount}.";
                return false;
            }

            return true;
        }

        private static void RewriteWsMaterialAssignments(
            XmlDocument document,
            IReadOnlyList<string[]> assignments)
        {
            var materialsNode = document.SelectSingleNode("/model/materials")
                ?? throw new InvalidOperationException("WSModel has no materials node.");

            var existingNodes = materialsNode.SelectNodes("material");
            if (existingNodes != null)
            {
                foreach (XmlNode node in existingNodes.Cast<XmlNode>().ToList())
                    materialsNode.RemoveChild(node);
            }

            for (var lodIndex = 0; lodIndex < assignments.Count; lodIndex++)
            {
                for (var partIndex = 0; partIndex < assignments[lodIndex].Length; partIndex++)
                {
                    var materialNode = document.CreateElement("material");
                    materialNode.SetAttribute("lod_index", lodIndex.ToString());
                    materialNode.SetAttribute("part_index", partIndex.ToString());
                    materialNode.InnerText = assignments[lodIndex][partIndex];
                    materialsNode.AppendChild(materialNode);
                }
            }
        }

        private void SaveModifiedDocuments(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var total =
                state.ModifiedRigids.Count +
                state.ModifiedWsModels.Count +
                state.ModifiedVmdDocuments.Count;
            var current = 0;
            var replacements = new List<NewPackFileEntry>(total);

            var serializeStopwatch = Stopwatch.StartNew();
            var rigidPaths = state.ModifiedRigids
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToArray();
            var rigidReplacements = new NewPackFileEntry[rigidPaths.Length];
            var serializedRigidCount = 0;
            var rigidSerializationWorkers = Math.Min(4, Math.Max(1, Environment.ProcessorCount));

            ReportProgress(
                progress,
                "Serializing modified rigids",
                current,
                total,
                $"{rigidPaths.Length:N0} rigid(s) — {rigidSerializationWorkers} worker(s)");

            // Run the bounded parallel work away from the UI thread, but keep progress reporting
            // on the caller thread. TextureAtlasProgressWindow's progress implementation pumps
            // the WPF dispatcher and must never be called from Parallel.For worker threads.
            var rigidSerializationTask = Task.Run(
                () => Parallel.For(
                    0,
                    rigidPaths.Length,
                    new ParallelOptions
                    {
                        CancellationToken = cancellationToken,
                        MaxDegreeOfParallelism = rigidSerializationWorkers
                    },
                    rigidIndex =>
                    {
                        var rigidPath = rigidPaths[rigidIndex];
                        var rmv = state.RigidModels[rigidPath];
                        rmv.RecalculateOffsets();

                        // ValidateOutput reloads every rewritten rigid after all replacements are
                        // committed, so doing ModelFactory.Save's immediate round-trip load here would
                        // validate the same bytes twice.
                        var data = ModelFactory.Create().Save(
                            rmv,
                            validateByReloading: false,
                            logProgress: false);
                        rigidReplacements[rigidIndex] = CreateReplacementEntry(rigidPath, data);
                        Interlocked.Increment(ref serializedRigidCount);
                    }),
                CancellationToken.None);

            try
            {
                while (!rigidSerializationTask.IsCompleted)
                {
                    Thread.Sleep(25);
                    ReportProgress(
                        progress,
                        "Serializing modified rigids",
                        current + Volatile.Read(ref serializedRigidCount),
                        total,
                        $"{rigidPaths.Length:N0} rigid(s) — {rigidSerializationWorkers} worker(s)");
                }

                rigidSerializationTask.GetAwaiter().GetResult();
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                // Ensure the serialization workers have observed cancellation before the output
                // pack and its in-memory rigid state are torn down.
                try
                {
                    rigidSerializationTask.GetAwaiter().GetResult();
                }
                catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
                {
                }

                throw;
            }

            ReportProgress(
                progress,
                "Serializing modified rigids",
                current + rigidPaths.Length,
                total,
                $"{rigidPaths.Length:N0} rigid(s) serialized");

            replacements.AddRange(rigidReplacements);
            current += rigidPaths.Length;
            AddPhaseDuration(state, "Serialize modified rigids", serializeStopwatch.Elapsed);

            serializeStopwatch.Restart();
            foreach (var wsPath in state.ModifiedWsModels)
            {
                cancellationToken.ThrowIfCancellationRequested();
                ReportProgress(progress, "Serializing modified WSModels", ++current, total, wsPath);

                var doc = state.WsDocuments[wsPath];
                replacements.Add(CreateReplacementEntry(
                    wsPath,
                    Encoding.UTF8.GetBytes(doc.OuterXml)));
            }
            AddPhaseDuration(state, "Serialize modified WSModels", serializeStopwatch.Elapsed);

            serializeStopwatch.Restart();
            foreach (var (vmdPath, document) in
                     state.ModifiedVmdDocuments
                         .OrderBy(
                             entry => entry.Key,
                             StringComparer.OrdinalIgnoreCase))
            {
                cancellationToken.ThrowIfCancellationRequested();
                ReportProgress(
                    progress,
                    "Serializing modified VMDs",
                    ++current,
                    total,
                    vmdPath);
                replacements.Add(
                    CreateReplacementEntry(
                        vmdPath,
                        Encoding.UTF8.GetBytes(
                            document.OuterXml)));
            }
            AddPhaseDuration(
                state,
                "Serialize modified VMDs",
                serializeStopwatch.Elapsed);

            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Replacing modified assets",
                replacements.Count,
                replacements.Count,
                $"{replacements.Count:N0} files");

            var replaceStopwatch = Stopwatch.StartNew();
            _packFileService.AddFilesToPack(state.Output, replacements);
            AddPhaseDuration(state, "Replace modified assets in pack", replaceStopwatch.Elapsed);
        }

        private static NewPackFileEntry CreateReplacementEntry(string fullPath, byte[] data)
        {
            fullPath = Normalize(fullPath);
            var directory = Path.GetDirectoryName(fullPath) ?? string.Empty;
            var name = Path.GetFileName(fullPath);
            return new NewPackFileEntry(
                directory,
                PackFile.CreateFromBytes(name, data));
        }

        private void PruneUnusedAssetFiles(
            BatchState state,
            HashSet<string> originalReachable,
            HashSet<string> currentReachable,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(progress, "Pruning unused assets");
            var toRemove = new HashSet<string>(
                originalReachable.Except(currentReachable, StringComparer.OrdinalIgnoreCase),
                StringComparer.OrdinalIgnoreCase);

            // The first cross-rigid writer deliberately duplicates source geometry instead
            // of claiming source retirement. Keep every source WSModel/RMV participating in
            // an emitted plan even when the rewritten VMD no longer reaches it.
            toRemove.ExceptWith(
                state.CrossRigidRetainedSourceAssetPaths);

            var outputPaths = state.Output.GetAllFiles().Keys.ToList();
            for (var outputIndex = 0; outputIndex < outputPaths.Count; outputIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var path = outputPaths[outputIndex];
                if (outputIndex == 0 || outputIndex == outputPaths.Count - 1 || outputIndex % 25 == 0)
                {
                    ReportProgress(
                        progress,
                        "Finding unused assets",
                        outputIndex + 1,
                        outputPaths.Count,
                        path);
                }

                var normalized = Normalize(path);
                if (normalized.StartsWith(AtlasDirectory, StringComparison.OrdinalIgnoreCase) &&
                    !currentReachable.Contains(normalized))
                {
                    toRemove.Add(normalized);
                }
            }

            var protectStopwatch = Stopwatch.StartNew();
            ProtectStillReferencedAssets(
                state.Output,
                toRemove,
                cancellationToken,
                progress);
            AddPhaseDuration(state, "Protect referenced assets", protectStopwatch.Elapsed);

            var removePaths = toRemove
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .Where(state.Output.ContainsFile)
                .ToList();

            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(
                progress,
                "Pruning unused assets",
                removePaths.Count,
                removePaths.Count,
                $"{removePaths.Count:N0} files");

            var deleteStopwatch = Stopwatch.StartNew();
            _packFileService.DeleteFiles(state.Output, removePaths);
            AddPhaseDuration(state, "Delete pruned assets", deleteStopwatch.Elapsed);
            state.RemovedFiles.AddRange(removePaths);
        }

        private static void ProtectStillReferencedAssets(
            IPackFileContainer output,
            HashSet<string> toRemove,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            if (toRemove.Count == 0)
                return;

            var reverseReferences = BuildReverseAssetReferences(
                output,
                cancellationToken,
                progress);

            // Removing one candidate can make another candidate unsafe to remove. Iterate until
            // every remaining candidate is referenced only by other files that are also being
            // removed, or has no remaining in-pack referrer at all.
            while (true)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var protectedPaths = toRemove
                    .Where(path =>
                        reverseReferences.TryGetValue(path, out var referrers) &&
                        referrers.Any(referrer => !toRemove.Contains(referrer)))
                    .ToList();

                if (protectedPaths.Count == 0)
                    break;

                foreach (var path in protectedPaths)
                    toRemove.Remove(path);
            }
        }

        private static Dictionary<string, HashSet<string>> BuildReverseAssetReferences(
            IPackFileContainer container,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            var reverse = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);

            void AddReference(string sourcePath, string? targetPath)
            {
                var source = Normalize(sourcePath);
                var target = Normalize(targetPath);
                if (string.IsNullOrWhiteSpace(source) ||
                    string.IsNullOrWhiteSpace(target) ||
                    IsTexturePlaceholder(target))
                {
                    return;
                }

                if (!reverse.TryGetValue(target, out var referrers))
                {
                    referrers = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    reverse[target] = referrers;
                }

                referrers.Add(source);
            }

            var allFiles = container.GetAllFiles().ToList();
            for (var fileIndex = 0; fileIndex < allFiles.Count; fileIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var (path, file) = allFiles[fileIndex];
                if (fileIndex == 0 || fileIndex == allFiles.Count - 1 || fileIndex % 25 == 0)
                {
                    ReportProgress(
                        progress,
                        "Checking retained references",
                        fileIndex + 1,
                        allFiles.Count,
                        path);
                }

                var extension = Path.GetExtension(path);

                try
                {
                    if (path.EndsWith(".xml.material", StringComparison.OrdinalIgnoreCase))
                    {
                        var materialDoc = LoadXml(file);
                        var textureNodes = materialDoc.SelectNodes("/material/textures/texture");
                        if (textureNodes == null)
                            continue;

                        foreach (XmlNode textureNode in textureNodes)
                        {
                            AddReference(
                                path,
                                textureNode.SelectSingleNode("source")?.InnerText ?? textureNode.InnerText);
                        }

                        continue;
                    }

                    if (extension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase))
                    {
                        var wsDoc = LoadXml(file);
                        AddReference(path, wsDoc.SelectSingleNode("/model/geometry")?.InnerText);

                        var materialNodes = wsDoc.SelectNodes("/model/materials/material");
                        if (materialNodes == null)
                            continue;

                        foreach (XmlNode materialNode in materialNodes)
                            AddReference(path, materialNode.InnerText);

                        continue;
                    }

                    if (extension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase))
                    {
                        var rigid = ModelFactory.Create().Load(file.DataSource.ReadData());
                        foreach (var lod in rigid.ModelList)
                        {
                            foreach (var model in lod)
                            {
                                foreach (var texture in model.Material.GetAllTextures())
                                    AddReference(path, texture.Path);
                            }
                        }

                        continue;
                    }

                    if (extension.Equals(".variantmeshdefinition", StringComparison.OrdinalIgnoreCase))
                    {
                        var vmd = VariantMeshDefinitionLoader.Load(file);
                        var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        var childVmds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        CollectVmdReferences(vmd, models, childVmds, textures);

                        foreach (var target in models)
                            AddReference(path, target);
                        foreach (var target in childVmds)
                            AddReference(path, target);
                        foreach (var target in textures)
                            AddReference(path, target);
                    }
                }
                catch
                {
                    // Cleanup is deliberately conservative, but a malformed unrelated asset
                    // should not make the whole atlas conversion fail. Converted dependencies
                    // are validated separately before the pack is written.
                }
            }

            return reverse;
        }

        private static BcnTextureResidencySummary CalculateBcnTextureResidency(
            BatchState state,
            IPackFileContainer container,
            IReadOnlyCollection<string> reachablePaths,
            CancellationToken cancellationToken)
        {
            var reachable = new HashSet<string>(
                reachablePaths.Select(Normalize),
                StringComparer.OrdinalIgnoreCase);
            var textureWsModels = BuildTextureWsModelMap(
                container,
                reachable,
                cancellationToken);
            var rootsByWsModel = BuildArmyRootsByWsModel(
                state,
                cancellationToken);

            var formatCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var formatBytes = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
            var reachableDdsCount = 0;
            var bcnTextureCount = 0;
            var unsupportedDdsCount = 0;
            var armyUnmappedBcnTextureCount = 0;
            long bcnBytes = 0;
            double estimatedScenarioResidentBcnBytes = 0;
            long generatedAtlasBcnBytes = 0;
            double estimatedScenarioResidentGeneratedAtlasBcnBytes = 0;

            foreach (var texturePath in reachable
                         .Where(path => Path.GetExtension(path).Equals(
                             ".dds",
                             StringComparison.OrdinalIgnoreCase))
                         .OrderBy(path => path, StringComparer.OrdinalIgnoreCase))
            {
                cancellationToken.ThrowIfCancellationRequested();
                reachableDdsCount++;

                var file = container.FindFile(texturePath);
                if (file == null)
                    continue;

                DdsBcnResidencyEstimate estimate;
                try
                {
                    if (!DdsBcnResidencyEstimator.TryEstimate(
                            file.DataSource.PeekData(148),
                            out estimate))
                    {
                        unsupportedDdsCount++;
                        continue;
                    }
                }
                catch
                {
                    unsupportedDdsCount++;
                    continue;
                }

                bcnTextureCount++;
                bcnBytes = checked(bcnBytes + estimate.Bytes);
                formatCounts[estimate.Format] = formatCounts.GetValueOrDefault(estimate.Format) + 1;
                formatBytes[estimate.Format] = checked(
                    formatBytes.GetValueOrDefault(estimate.Format) + estimate.Bytes);

                var targetWsModels = textureWsModels.TryGetValue(texturePath, out var wsModels)
                    ? wsModels
                    : new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var fallbackRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var wsModel in targetWsModels)
                {
                    if (rootsByWsModel.TryGetValue(wsModel, out var roots))
                        fallbackRoots.UnionWith(roots);
                }

                if (targetWsModels.Count == 0 && fallbackRoots.Count == 0)
                    armyUnmappedBcnTextureCount++;

                var residentProbability = GetExpectedArmyResidentProbability(
                    state,
                    targetWsModels,
                    fallbackRoots);
                var expectedBytes = estimate.Bytes * residentProbability;
                estimatedScenarioResidentBcnBytes += expectedBytes;

                if (state.GeneratedTexturePaths.Contains(texturePath))
                {
                    generatedAtlasBcnBytes = checked(
                        generatedAtlasBcnBytes + estimate.Bytes);
                    estimatedScenarioResidentGeneratedAtlasBcnBytes += expectedBytes;
                }
            }

            return new BcnTextureResidencySummary(
                reachableDdsCount,
                bcnTextureCount,
                unsupportedDdsCount,
                armyUnmappedBcnTextureCount,
                bcnBytes,
                estimatedScenarioResidentBcnBytes,
                generatedAtlasBcnBytes,
                estimatedScenarioResidentGeneratedAtlasBcnBytes,
                formatCounts,
                formatBytes);
        }

        private static Dictionary<string, HashSet<string>> BuildTextureWsModelMap(
            IPackFileContainer container,
            IReadOnlyCollection<string> reachablePaths,
            CancellationToken cancellationToken)
        {
            var result = new Dictionary<string, HashSet<string>>(
                StringComparer.OrdinalIgnoreCase);
            var materialTextures = new Dictionary<string, string[]>(
                StringComparer.OrdinalIgnoreCase);

            void AddTextureReference(string texturePathValue, string assetPathValue)
            {
                var texturePath = Normalize(texturePathValue);
                var assetPath = Normalize(assetPathValue);
                if (texturePath.Length == 0 ||
                    assetPath.Length == 0 ||
                    !Path.GetExtension(texturePath).Equals(
                        ".dds",
                        StringComparison.OrdinalIgnoreCase) ||
                    !reachablePaths.Contains(texturePath, StringComparer.OrdinalIgnoreCase))
                {
                    return;
                }

                if (!result.TryGetValue(texturePath, out var assets))
                {
                    assets = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    result[texturePath] = assets;
                }

                assets.Add(assetPath);
            }

            foreach (var wsModelPath in reachablePaths
                         .Where(path => Path.GetExtension(path).Equals(
                             ".wsmodel",
                             StringComparison.OrdinalIgnoreCase)))
            {
                cancellationToken.ThrowIfCancellationRequested();
                var wsFile = container.FindFile(wsModelPath);
                if (wsFile == null)
                    continue;

                XmlDocument wsDocument;
                try
                {
                    wsDocument = LoadXml(wsFile);
                }
                catch
                {
                    continue;
                }

                var materialNodes = wsDocument.SelectNodes("/model/materials/material");
                if (materialNodes == null)
                    continue;

                foreach (XmlNode materialNode in materialNodes)
                {
                    var materialPath = Normalize(materialNode.InnerText);
                    if (materialPath.Length == 0)
                        continue;

                    if (!materialTextures.TryGetValue(materialPath, out var texturePaths))
                    {
                        var materialFile = container.FindFile(materialPath);
                        if (materialFile == null)
                        {
                            materialTextures[materialPath] = [];
                            continue;
                        }

                        try
                        {
                            var materialDocument = LoadXml(materialFile);
                            texturePaths = materialDocument
                                .SelectNodes("/material/textures/texture")?
                                .Cast<XmlNode>()
                                .Select(node => Normalize(
                                    node.SelectSingleNode("source")?.InnerText ?? node.InnerText))
                                .Where(path =>
                                    path.Length != 0 &&
                                    Path.GetExtension(path).Equals(
                                        ".dds",
                                        StringComparison.OrdinalIgnoreCase))
                                .Distinct(StringComparer.OrdinalIgnoreCase)
                                .ToArray()
                                ?? [];
                        }
                        catch
                        {
                            texturePaths = [];
                        }

                        materialTextures[materialPath] = texturePaths;
                    }

                    foreach (var texturePath in texturePaths)
                        AddTextureReference(texturePath, wsModelPath);
                }
            }

            foreach (var rigidPath in reachablePaths
                         .Where(path => Path.GetExtension(path).Equals(
                             ".rigid_model_v2",
                             StringComparison.OrdinalIgnoreCase)))
            {
                cancellationToken.ThrowIfCancellationRequested();
                var rigidFile = container.FindFile(rigidPath);
                if (rigidFile == null)
                    continue;

                try
                {
                    var rigid = ModelFactory.Create().Load(rigidFile.DataSource.ReadData());
                    foreach (var lod in rigid.ModelList)
                    {
                        foreach (var model in lod)
                        {
                            foreach (var texture in model.Material.GetAllTextures())
                                AddTextureReference(texture.Path, rigidPath);
                        }
                    }
                }
                catch
                {
                    // Keep residency estimation conservative for malformed unrelated rigids.
                }
            }

            return result;
        }

        private static Dictionary<string, HashSet<string>> BuildArmyRootsByWsModel(
            BatchState state,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress = null)
        {
            var result = new Dictionary<string, HashSet<string>>(
                StringComparer.OrdinalIgnoreCase);
            if (state.ArmyResidencyModel == null)
                return result;

            var rootPaths = state.ArmyResidencyModel.UnitsByVmd.Keys.ToArray();
            ReportProgress(
                progress,
                "Evaluating atlas value",
                0,
                rootPaths.Length,
                "Indexing army asset roots");
            for (var rootIndex = 0; rootIndex < rootPaths.Length; rootIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                ReportPeriodicProgress(
                    progress,
                    "Evaluating atlas value",
                    rootIndex + 1,
                    rootPaths.Length,
                    "Indexing army asset roots");
                var root = rootPaths[rootIndex];

                var rootExtension = Path.GetExtension(root);
                if (!rootExtension.Equals(
                        ".variantmeshdefinition",
                        StringComparison.OrdinalIgnoreCase))
                {
                    // Engine assets with no VMD variant (notably battlefield engines whose
                    // variant column is empty) are themselves the residency key. Treating them
                    // as VMDs would yield no reachable WSModel and lose their army probability.
                    if (rootExtension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) ||
                        rootExtension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!result.TryGetValue(root, out var directRoots))
                        {
                            directRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                            result[root] = directRoots;
                        }

                        directRoots.Add(Normalize(root));
                    }

                    continue;
                }

                foreach (var wsModel in GetReachableWsModels(
                             state,
                             root,
                             cancellationToken))
                {
                    if (!result.TryGetValue(wsModel, out var roots))
                    {
                        roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        result[wsModel] = roots;
                    }

                    roots.Add(Normalize(root));
                }
            }

            return result;
        }

        private static string FormatMiB(double bytes, int decimals = 1)
            => $"{(bytes / (1024.0 * 1024.0)).ToString($"N{decimals}")} MiB";

        private static void AppendAtlasValueGateSourceTextureResidencyDiagnostics(
            StringBuilder sb,
            BatchState state)
        {
            var caOwnedDiagnostics = state
                .AtlasValueGateSourceTextureResidencyDiagnostics
                .Values
                .Where(diagnostic => !diagnostic.IsOwnedBySourcePack)
                .OrderBy(diagnostic => diagnostic.TexturePath, StringComparer.OrdinalIgnoreCase)
                .ToArray();

            sb.AppendLine();
            sb.AppendLine(
                "Atlas value-gate accepted CA-owned source-texture residency diagnostics");
            sb.AppendLine(
                "--------------------------------------------------------------------------");
            if (caOwnedDiagnostics.Length == 0)
            {
                sb.AppendLine("  (none)");
                return;
            }

            sb.AppendLine(
                $"  textures={caOwnedDiagnostics.Length:N0}, " +
                $"current={FormatMiB(caOwnedDiagnostics.Sum(
                    diagnostic => diagnostic.CurrentExpectedResidentBcnBytes), 3)}, " +
                $"after={FormatMiB(caOwnedDiagnostics.Sum(
                    diagnostic => diagnostic.ProposedExpectedResidentBcnBytes), 3)}, " +
                $"scenario-retired={FormatMiB(caOwnedDiagnostics.Sum(
                    diagnostic => diagnostic.ExpectedRetiredBcnBytes), 3)}");
            foreach (var diagnostic in caOwnedDiagnostics)
            {
                sb.AppendLine(
                    $"  {diagnostic.TexturePath}: " +
                    $"BCn={FormatMiB(diagnostic.BcnBytes, 3)}, " +
                    $"refs={diagnostic.ReferenceCount:N0}, " +
                    $"rewritten={diagnostic.RewrittenReferenceCountBefore:N0}->" +
                    $"{diagnostic.RewrittenReferenceCountAfter:N0}, " +
                    $"direct-vmd={(diagnostic.HasDirectVmdReference ? "YES" : "NO")}, " +
                    $"direct-source-vmd={(diagnostic.HasDirectSourcePackVmdReference ? "YES" : "NO")}, " +
                    $"mapping={(diagnostic.ConsumerMappingResolved ? "resolved" : "conservative")}");
                sb.AppendLine(
                    $"    residency: P={diagnostic.CurrentResidentProbability:0.000000}->" +
                    $"{diagnostic.ProposedResidentProbability:0.000000}, " +
                    $"expected={FormatMiB(diagnostic.CurrentExpectedResidentBcnBytes, 3)}->" +
                    $"{FormatMiB(diagnostic.ProposedExpectedResidentBcnBytes, 3)}, " +
                    $"retired={FormatMiB(diagnostic.ExpectedRetiredBcnBytes, 3)}");
                sb.AppendLine(
                    $"    consumers before: " +
                    FormatAtlasValueGateConsumerPaths(diagnostic.CurrentConsumerWsModels));
                sb.AppendLine(
                    $"    consumers after: " +
                    FormatAtlasValueGateConsumerPaths(diagnostic.ProposedConsumerWsModels));
                sb.AppendLine(
                    $"    scenario before: {diagnostic.CurrentScenarioProjection}");
                sb.AppendLine(
                    $"    scenario after: {diagnostic.ProposedScenarioProjection}");
            }
        }

        private static string FormatAtlasValueGateConsumerPaths(
            IReadOnlyList<string> paths)
        {
            if (paths.Count == 0)
                return "<none>";

            const int maxDisplayedPaths = 4;
            var displayed = paths
                .Take(maxDisplayedPaths)
                .ToArray();
            var suffix = paths.Count > maxDisplayedPaths
                ? $", ... (+{paths.Count - maxDisplayedPaths:N0})"
                : string.Empty;
            return string.Join(", ", displayed) + suffix;
        }

        private static double GetAtlasValueGateMiBPerDraw(
            double netBytes,
            double drawsEliminated)
        {
            if (drawsEliminated <= 0.000001)
                return 0;

            return Math.Max(0.0, netBytes) /
                   (1024.0 * 1024.0) /
                   drawsEliminated;
        }

        private static double GetAtlasValueGateWorstMiBPerDraw(
            AtlasValueGateBatchEconomics entry)
        {
            var global = GetAtlasValueGateMiBPerDraw(
                entry.NetBcnBytes,
                entry.RawDrawsEliminated);
            var expected = entry.ExpectedArmyDrawsEliminated > 0.000001
                ? GetAtlasValueGateMiBPerDraw(
                    entry.ExpectedArmyNetBcnBytes,
                    entry.ExpectedArmyDrawsEliminated)
                : 0;
            return Math.Max(global, expected);
        }

        private static string FormatAtlasValueGateMiBPerDraw(
            double netBytes,
            double drawsEliminated)
            => drawsEliminated <= 0.000001
                ? "N/A"
                : $"{GetAtlasValueGateMiBPerDraw(netBytes, drawsEliminated):N3} MiB/draw";

        private static string FormatResidencyDelta(double before, double after)
        {
            var deltaBytes = after - before;
            if (before <= 0)
                return $"{(deltaBytes >= 0 ? "+" : string.Empty)}{FormatMiB(deltaBytes)}";

            var deltaPercent = deltaBytes / before * 100.0;
            return $"{(deltaBytes >= 0 ? "+" : string.Empty)}{FormatMiB(deltaBytes)} " +
                   $"({(deltaPercent >= 0 ? "+" : string.Empty)}{deltaPercent:N1}%)";
        }

        private static string FormatBcnBreakdown(BcnTextureResidencySummary summary)
        {
            if (summary.BytesByFormat.Count == 0)
                return "<none>";

            return string.Join(
                ", ",
                summary.BytesByFormat
                    .OrderBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase)
                    .Select(entry =>
                        $"{entry.Key}={FormatMiB(entry.Value)} " +
                        $"({summary.TextureCountByFormat.GetValueOrDefault(entry.Key):N0})"));
        }

        private HashSet<string> CollectReachableAssetFiles(
            BatchState state,
            IPackFileContainer container,
            IReadOnlyList<string> rootAssetPaths,
            CancellationToken cancellationToken = default,
            IProgress<TextureAtlasPackProgress>? progress = null,
            string phase = "Scanning dependencies")
        {
            var reachable = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var assetQueue = new Queue<string>(rootAssetPaths.Select(Normalize));
            var visitedAssets = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var processedAssetCount = 0;
            void EnqueueExistingAsset(string pathValue)
            {
                var path = Normalize(pathValue);
                if (path.Length == 0 || container.FindFile(path) == null)
                    return;

                reachable.Add(path);
                assetQueue.Enqueue(path);
            }

            void AddMaterialTextures(
                string materialPath,
                PackFile materialFile)
            {
                if (!TryGetMaterialDocumentForTraversal(
                        state,
                        container,
                        materialPath,
                        materialFile,
                        out var materialDocument))
                {
                    return;
                }

                var textureNodes = materialDocument.SelectNodes("/material/textures/texture");
                if (textureNodes == null)
                    return;

                foreach (XmlNode textureNode in textureNodes)
                {
                    EnqueueExistingAsset(
                        textureNode.SelectSingleNode("source")?.InnerText ??
                        textureNode.InnerText);
                }
            }

            void AddRigidTextures(PackFile rigidFile)
            {
                try
                {
                    var rigid = ModelFactory.Create().Load(rigidFile.DataSource.ReadData());
                    foreach (var lod in rigid.ModelList)
                    {
                        foreach (var model in lod)
                        {
                            foreach (var texture in model.Material.GetAllTextures())
                                EnqueueExistingAsset(texture.Path);
                        }
                    }
                }
                catch
                {
                    // A malformed unrelated rigid should not prevent dependency scanning for
                    // the rest of the pack. Rewritten rigids are validated separately.
                }
            }

            while (assetQueue.Count > 0)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var assetPath = assetQueue.Dequeue();
                ReportProgress(progress, phase, ++processedAssetCount, 0, assetPath);
                if (!visitedAssets.Add(assetPath))
                    continue;

                var assetFile = container.FindFile(assetPath);
                if (assetFile == null)
                    continue;

                var extension = Path.GetExtension(assetPath);
                if (extension.Equals(".variantmeshdefinition", StringComparison.OrdinalIgnoreCase))
                {
                    if (!TryGetVmdForTraversal(
                            state,
                            container,
                            assetPath,
                            assetFile,
                            out var vmd))
                    {
                        continue;
                    }

                    var modelRefs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    var childVmdRefs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    var directTextures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    CollectVmdReferences(vmd, modelRefs, childVmdRefs, directTextures);

                    foreach (var texture in directTextures)
                        EnqueueExistingAsset(texture);
                    foreach (var child in childVmdRefs)
                        EnqueueExistingAsset(child);
                    foreach (var model in modelRefs)
                        EnqueueExistingAsset(model);

                    continue;
                }

                if (extension.Equals(".rigid_model_v2", StringComparison.OrdinalIgnoreCase))
                {
                    AddRigidTextures(assetFile);
                    continue;
                }

                if (extension.Equals(".xml.material", StringComparison.OrdinalIgnoreCase))
                {
                    AddMaterialTextures(assetPath, assetFile);
                    continue;
                }

                if (!extension.Equals(".wsmodel", StringComparison.OrdinalIgnoreCase))
                    continue;

                if (!TryGetWsDocumentForTraversal(
                        state,
                        container,
                        assetPath,
                        assetFile,
                        out var wsDocument))
                {
                    continue;
                }

                EnqueueExistingAsset(wsDocument.SelectSingleNode("/model/geometry")?.InnerText ?? string.Empty);

                var materialNodes = wsDocument.SelectNodes("/model/materials/material");
                if (materialNodes == null)
                    continue;

                foreach (XmlNode materialNode in materialNodes)
                {
                    var materialPath = Normalize(materialNode.InnerText);
                    var materialFile = container.FindFile(materialPath);
                    if (materialFile == null)
                        continue;

                    reachable.Add(materialPath);
                    AddMaterialTextures(materialPath, materialFile);
                }
            }

            return reachable;
        }

        private static IReadOnlyDictionary<string, IReadOnlyCollection<string>> BuildChildVmdDependencyMap(
            BatchState state,
            IPackFileContainer container,
            IReadOnlyCollection<string> vmdPaths,
            CancellationToken cancellationToken)
        {
            var result = new Dictionary<string, IReadOnlyCollection<string>>(
                StringComparer.OrdinalIgnoreCase);

            foreach (var pathValue in vmdPaths)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var path = Normalize(pathValue);
                var file = container.FindFile(path);
                if (file == null)
                    continue;

                var vmd = GetVmd(state, container, path, file);
                var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var children = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                CollectVmdReferences(vmd, models, children, textures);

                result[path] = children
                    .Where(container.ContainsFile)
                    .Select(Normalize)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(child => child, StringComparer.OrdinalIgnoreCase)
                    .ToArray();
            }

            return result;
        }

        private static bool TryGetVmdForTraversal(
            BatchState state,
            IPackFileContainer container,
            string vmdPathValue,
            PackFile file,
            out VariantMesh vmd)
        {
            var vmdPath = Normalize(vmdPathValue);
            try
            {
                vmd = GetVmd(state, container, vmdPath, file);
                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or
                XmlException or
                FormatException or
                ArgumentException)
            {
                RecordMalformedReferencedVmd(state, vmdPath, ex);
                vmd = null!;
                return false;
            }
        }

        private static void RecordMalformedReferencedVmd(
            BatchState state,
            string vmdPath,
            Exception exception)
        {
            vmdPath = Normalize(vmdPath);
            if (state.MalformedReferencedVmds.Any(
                    entry => entry.Path.Equals(vmdPath, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            var messages = new List<string>();
            for (Exception? current = exception; current != null; current = current.InnerException)
            {
                var message = current.Message.Replace("\r", " ").Replace("\n", " ").Trim();
                if (message.Length != 0 &&
                    !messages.Contains(message, StringComparer.Ordinal))
                {
                    messages.Add(message);
                }
            }

            state.MalformedReferencedVmds.Add(new MalformedVmdEntry(
                vmdPath,
                messages.Count == 0
                    ? exception.GetType().Name
                    : string.Join(" -> ", messages)));
        }

        private static VariantMesh GetVmd(
            BatchState state,
            IPackFileContainer container,
            string vmdPath,
            PackFile? file = null)
        {
            vmdPath = Normalize(vmdPath);
            if (state.VmdDocuments.TryGetValue(vmdPath, out var cached))
                return cached;

            file ??= container.FindFile(vmdPath)
                ?? throw new FileNotFoundException($"VMD file could not be resolved: {vmdPath}");

            var vmd = VariantMeshDefinitionLoader.Load(
                file,
                out var compatibilityRepairs);
            RecordXmlCompatibilityRepairs(
                state,
                vmdPath,
                compatibilityRepairs);
            state.VmdDocuments[vmdPath] = vmd;
            return vmd;
        }

        private static HashSet<string> GetReachableWsModels(
            BatchState state,
            string rootVmdPath,
            CancellationToken cancellationToken = default)
        {
            rootVmdPath = Normalize(rootVmdPath);
            if (state.ReachableWsModelsByRoot.TryGetValue(rootVmdPath, out var cached))
                return cached;

            var reachable = CollectReachableWsModels(
                state,
                state.Source,
                rootVmdPath,
                cancellationToken);
            state.ReachableWsModelsByRoot[rootVmdPath] = reachable;
            state.ReachableWsModelsByRootVersion++;
            return reachable;
        }

        private static HashSet<string> CollectReachableWsModels(
            BatchState state,
            IPackFileContainer container,
            string rootVmdPath,
            CancellationToken cancellationToken = default)
        {
            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var queue = new Queue<string>();
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            queue.Enqueue(Normalize(rootVmdPath));

            while (queue.Count > 0)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var vmdPath = queue.Dequeue();
                if (!visited.Add(vmdPath))
                    continue;

                var file = container.FindFile(vmdPath);
                if (file == null)
                    continue;

                if (!TryGetVmdForTraversal(
                        state,
                        container,
                        vmdPath,
                        file,
                        out var vmd))
                {
                    continue;
                }

                var models = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var children = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var textures = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                CollectVmdReferences(vmd, models, children, textures);

                foreach (var model in models)
                {
                    if (Path.GetExtension(model).Equals(".wsmodel", StringComparison.OrdinalIgnoreCase) &&
                        container.FindFile(model) != null)
                    {
                        result.Add(model);
                    }
                }

                foreach (var child in children)
                {
                    if (container.FindFile(child) != null)
                        queue.Enqueue(child);
                }
            }

            return result;
        }

        private static void CollectVmdReferences(
            VariantMesh mesh,
            HashSet<string> modelRefs,
            HashSet<string> childVmdRefs,
            HashSet<string> directTextures)
        {
            if (!string.IsNullOrWhiteSpace(mesh.ModelReference))
                modelRefs.Add(Normalize(mesh.ModelReference));
            if (!string.IsNullOrWhiteSpace(mesh.ImposterModel))
                modelRefs.Add(Normalize(mesh.ImposterModel));
            if (!string.IsNullOrWhiteSpace(mesh.DecalDiffuse))
                directTextures.Add(Normalize(mesh.DecalDiffuse));
            if (!string.IsNullOrWhiteSpace(mesh.DecalNormal))
                directTextures.Add(Normalize(mesh.DecalNormal));

            foreach (var slot in mesh.ChildSlots ?? [])
            {
                foreach (var child in slot.ChildMeshes ?? [])
                    CollectVmdReferences(child, modelRefs, childVmdRefs, directTextures);
                foreach (var reference in slot.ChildReferences ?? [])
                {
                    if (!string.IsNullOrWhiteSpace(reference.Reference))
                        childVmdRefs.Add(Normalize(reference.Reference));
                }
            }
        }

        private static bool TryGetMaterialDocumentForTraversal(
            BatchState state,
            IPackFileContainer container,
            string materialPathValue,
            PackFile file,
            out XmlDocument document)
        {
            var materialPath = Normalize(materialPathValue);
            try
            {
                if (ReferenceEquals(container, state.Source))
                {
                    document = GetMaterialDocument(state, materialPath, file);
                }
                else
                {
                    state.GameplayTraversalMaterialXmlParseCount++;
                    document = LoadXml(file, out var compatibilityRepairs);
                    RecordXmlCompatibilityRepairs(
                        state,
                        materialPath,
                        compatibilityRepairs);
                }

                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or
                XmlException or
                FormatException or
                ArgumentException)
            {
                RecordMalformedMaterial(state, materialPath, ex);
                document = null!;
                return false;
            }
        }

        private static void RecordMalformedMaterial(
            BatchState state,
            string materialPath,
            Exception exception)
        {
            materialPath = Normalize(materialPath);
            if (state.MalformedMaterialsIgnored.Any(
                    entry => entry.Path.Equals(materialPath, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            var messages = new List<string>();
            for (Exception? current = exception; current != null; current = current.InnerException)
            {
                var message = current.Message.Replace("\r", " ").Replace("\n", " ").Trim();
                if (message.Length != 0 &&
                    !messages.Contains(message, StringComparer.Ordinal))
                {
                    messages.Add(message);
                }
            }

            state.MalformedMaterialsIgnored.Add(new MalformedXmlAssetEntry(
                materialPath,
                messages.Count == 0
                    ? exception.GetType().Name
                    : string.Join(" -> ", messages)));
        }

        private static XmlDocument GetMaterialDocument(
            BatchState state,
            string materialPath,
            PackFile? materialFile = null)
        {
            materialPath = Normalize(materialPath);
            if (state.MaterialDocuments.TryGetValue(materialPath, out var cached))
                return cached;

            materialFile ??= FindForReadStatic(state, materialPath)
                ?? throw new FileNotFoundException($"Material file could not be resolved: {materialPath}");

            state.GameplayTraversalMaterialXmlParseCount++;
            var doc = LoadXml(
                materialFile,
                out var compatibilityRepairs);
            RecordXmlCompatibilityRepairs(
                state,
                materialPath,
                compatibilityRepairs);
            state.MaterialDocuments[materialPath] = doc;
            return doc;
        }

        private static PackFile? FindForReadStatic(BatchState state, string path)
        {
            path = Normalize(path);
            return state.Output.FindFile(path)
                   ?? state.Source.FindFile(path)
                   ?? state.PackFileService.FindFile(path);
        }

        private static bool TryGetWsDocumentForTraversal(
            BatchState state,
            IPackFileContainer container,
            string wsPathValue,
            PackFile file,
            out XmlDocument document)
        {
            var wsPath = Normalize(wsPathValue);
            try
            {
                if (ReferenceEquals(container, state.Source))
                {
                    var cachedDocument = GetWsDocument(state, wsPath);
                    if (cachedDocument != null)
                    {
                        document = cachedDocument;
                    }
                    else
                    {
                        state.GameplayTraversalWsModelXmlParseCount++;
                        document = LoadXml(file);
                    }
                }
                else
                {
                    state.GameplayTraversalWsModelXmlParseCount++;
                    document = LoadXml(file, out var compatibilityRepairs);
                    RecordXmlCompatibilityRepairs(
                        state,
                        wsPath,
                        compatibilityRepairs);
                }

                return true;
            }
            catch (Exception ex) when (
                ex is InvalidOperationException or
                XmlException or
                FormatException or
                ArgumentException)
            {
                RecordMalformedWsModel(state, wsPath, ex);
                document = null!;
                return false;
            }
        }

        private static void RecordMalformedWsModel(
            BatchState state,
            string wsPath,
            Exception exception)
        {
            wsPath = Normalize(wsPath);
            if (state.MalformedWsModelsIgnored.Any(
                    entry => entry.Path.Equals(wsPath, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            var messages = new List<string>();
            for (Exception? current = exception; current != null; current = current.InnerException)
            {
                var message = current.Message.Replace("\r", " ").Replace("\n", " ").Trim();
                if (message.Length != 0 &&
                    !messages.Contains(message, StringComparer.Ordinal))
                {
                    messages.Add(message);
                }
            }

            state.MalformedWsModelsIgnored.Add(new MalformedXmlAssetEntry(
                wsPath,
                messages.Count == 0
                    ? exception.GetType().Name
                    : string.Join(" -> ", messages)));
        }

        private static XmlDocument? GetWsDocument(BatchState state, string wsPath)
        {
            wsPath = Normalize(wsPath);
            if (state.WsDocuments.TryGetValue(wsPath, out var cached))
                return cached;

            var file = state.Source.FindFile(wsPath);
            if (file == null)
                return null;

            state.GameplayTraversalWsModelXmlParseCount++;
            var doc = LoadXml(
                file,
                out var compatibilityRepairs);
            RecordXmlCompatibilityRepairs(
                state,
                wsPath,
                compatibilityRepairs);
            state.WsDocuments[wsPath] = doc;
            return doc;
        }

        private RmvFile? GetRmv(BatchState state, string geometryPath)
        {
            geometryPath = Normalize(geometryPath);
            if (state.RigidModels.TryGetValue(geometryPath, out var cached))
                return cached;

            var file = state.Source.FindFile(geometryPath);
            if (file == null)
                return null;

            var rmv = ModelFactory.Create().Load(file.DataSource.ReadData());
            state.RigidModels[geometryPath] = rmv;
            return rmv;
        }

        private PackFile? FindForRead(BatchState state, string path)
        {
            path = Normalize(path);
            return state.Output.FindFile(path)
                   ?? state.Source.FindFile(path)
                   ?? _packFileService.FindFile(path);
        }

        private void WriteFile(IPackFileContainer output, string fullPath, byte[] data)
        {
            fullPath = Normalize(fullPath);
            var directory = Path.GetDirectoryName(fullPath) ?? string.Empty;
            var name = Path.GetFileName(fullPath);

            // AddFiles replaces an existing normalized path in-place. Avoid a preceding DeleteFile:
            // deletion performs a linear reverse lookup and emits an extra event/log entry.
            _packFileService.AddFilesToPack(
                output,
                [new NewPackFileEntry(directory, PackFile.CreateFromBytes(name, data))]);
        }

        private static XmlDocument LoadXml(PackFile file)
            => LoadXml(file, out _);

        private static XmlDocument LoadXml(
            PackFile file,
            out IReadOnlyList<string> compatibilityRepairs)
        {
            var content = Encoding.UTF8.GetString(file.DataSource.ReadData());
            return XmlCompatibilityParser.Parse(
                content,
                xml =>
                {
                    var document = new XmlDocument();
                    document.LoadXml(xml);
                    return document;
                },
                out compatibilityRepairs);
        }

        private static void RecordXmlCompatibilityRepairs(
            BatchState state,
            string pathValue,
            IReadOnlyList<string> repairs)
        {
            if (repairs.Count == 0)
                return;

            var path = Normalize(pathValue);
            if (!state.XmlCompatibilityRepairs.TryGetValue(path, out var recorded))
            {
                recorded = new HashSet<string>(StringComparer.Ordinal);
                state.XmlCompatibilityRepairs[path] = recorded;
            }

            foreach (var repair in repairs)
                recorded.Add(repair);
        }

        private static string GetTextureSlot(XmlNode textureNode)
            => textureNode.SelectSingleNode("slot")?.InnerText.Trim() ?? string.Empty;

        private static string GetTexturePath(XmlDocument material, string slot)
        {
            var textureNodes = material.SelectNodes("/material/textures/texture");
            if (textureNodes == null)
                return string.Empty;

            foreach (XmlNode node in textureNodes)
            {
                if (!GetTextureSlot(node).Equals(slot, StringComparison.OrdinalIgnoreCase))
                    continue;

                return Normalize(node.SelectSingleNode("source")?.InnerText ?? node.InnerText);
            }

            return string.Empty;
        }

        private static Faction3MaskCanonicalization CanonicalizeFaction3MaskParameter(
            XmlDocument material)
        {
            var parameter = material.SelectNodes("/material/params/param")?
                .Cast<XmlNode>()
                .FirstOrDefault(node =>
                    node.SelectSingleNode("name")?.InnerText.Trim().Equals(
                        "faction3_mask_channel",
                        StringComparison.OrdinalIgnoreCase) == true);
            if (parameter == null ||
                !string.Equals(
                    parameter.SelectSingleNode("type")?.InnerText.Trim(),
                    "float4",
                    StringComparison.OrdinalIgnoreCase))
            {
                return Faction3MaskCanonicalization.None;
            }

            var valueNode = parameter.SelectSingleNode("value");
            if (valueNode == null)
                return Faction3MaskCanonicalization.None;

            var values = valueNode.InnerText
                .Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)
                .Select(value => double.TryParse(
                    value,
                    NumberStyles.Float,
                    CultureInfo.InvariantCulture,
                    out var parsed)
                        ? (double?)parsed
                        : null)
                .ToArray();
            if (values.Length != 4 || values.Any(value => !value.HasValue))
                return Faction3MaskCanonicalization.None;

            var components = values.Select(value => value!.Value).ToArray();
            const double epsilon = 0.000001;
            var isZero = components.All(value => Math.Abs(value) <= epsilon);
            var isBlue = Math.Abs(components[0]) <= epsilon &&
                         Math.Abs(components[1]) <= epsilon &&
                         Math.Abs(components[2] - 1.0) <= epsilon &&
                         Math.Abs(components[3]) <= epsilon;
            if (isZero)
            {
                valueNode.InnerText = CanonicalFaction3MaskChannelValue;
                return Faction3MaskCanonicalization.ZeroSelector;
            }

            return isBlue
                ? Faction3MaskCanonicalization.BlueSelector
                : Faction3MaskCanonicalization.None;
        }

        private static void EnsureTexturePath(XmlDocument material, string slot, string path)
        {
            if (GetTexturePath(material, slot).Length != 0)
            {
                SetTexturePath(material, slot, path);
                return;
            }

            var textures = material.SelectSingleNode("/material/textures");
            if (textures == null)
            {
                textures = material.CreateElement("textures");
                material.DocumentElement?.AppendChild(textures);
            }

            if (textures == null)
                return;

            var texture = material.CreateElement("texture");
            var slotNode = material.CreateElement("slot");
            slotNode.SetAttribute("version", "2");
            slotNode.InnerText = slot;
            texture.AppendChild(slotNode);

            var sourceNode = material.CreateElement("source");
            sourceNode.InnerText = path;
            texture.AppendChild(sourceNode);

            // Most WH3 material XMLs place mask immediately after base colour and before
            // material-map/normal. Use that stable position for a synthesized mask so the
            // generated material can share identity with an otherwise identical masked one.
            var requestedOrder = GetCanonicalAtlasTextureOrder(slot);
            var insertBefore = textures.ChildNodes
                .Cast<XmlNode>()
                .FirstOrDefault(node =>
                {
                    if (!node.Name.Equals("texture", StringComparison.OrdinalIgnoreCase))
                        return false;

                    var existingOrder = GetCanonicalAtlasTextureOrder(GetTextureSlot(node));
                    return requestedOrder >= 0 &&
                           existingOrder > requestedOrder;
                });
            if (insertBefore != null)
                textures.InsertBefore(texture, insertBefore);
            else
                textures.AppendChild(texture);
        }

        private static int GetCanonicalAtlasTextureOrder(string slot)
        {
            if (slot.Equals("t_xml_base_colour", StringComparison.OrdinalIgnoreCase))
                return 0;
            if (slot.Equals("t_xml_mask", StringComparison.OrdinalIgnoreCase))
                return 1;
            if (slot.Equals("t_xml_material_map", StringComparison.OrdinalIgnoreCase))
                return 2;
            if (slot.Equals("t_xml_normal", StringComparison.OrdinalIgnoreCase))
                return 3;

            return -1;
        }

        private static void SetTexturePath(XmlDocument material, string slot, string path)
        {
            var textureNodes = material.SelectNodes("/material/textures/texture");
            if (textureNodes == null)
                return;

            foreach (XmlNode node in textureNodes)
            {
                if (!GetTextureSlot(node).Equals(slot, StringComparison.OrdinalIgnoreCase))
                    continue;

                var source = node.SelectSingleNode("source");
                if (source != null)
                    source.InnerText = path;
                else
                    node.InnerText = path;
                return;
            }
        }

        private static void RemoveTextureSlot(XmlDocument material, string slot)
        {
            var textureNodes = material.SelectNodes("/material/textures/texture");
            if (textureNodes == null)
                return;

            foreach (var node in textureNodes
                         .Cast<XmlNode>()
                         .Where(node => GetTextureSlot(node).Equals(
                             slot,
                             StringComparison.OrdinalIgnoreCase))
                         .ToList())
            {
                node.ParentNode?.RemoveChild(node);
            }
        }

        private void ValidateOutput(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            CancellationToken cancellationToken,
            IProgress<TextureAtlasPackProgress>? progress)
        {
            cancellationToken.ThrowIfCancellationRequested();
            ReportProgress(progress, "Validating output");
            var errors = new List<string>();

            ValidateUnchangedModelPathSet(
                state,
                ".variantmeshdefinition",
                errors,
                state.CrossRigidGeneratedVmdPaths);
            ValidateUnchangedModelPathSet(
                state,
                ".wsmodel",
                errors,
                state.CrossRigidGeneratedWsModelPaths);
            ValidateUnchangedModelPathSet(
                state,
                ".rigid_model_v2",
                errors,
                state.CrossRigidGeneratedRigidPaths);

            var validationVmds = state.ModifiedVmdDocuments.Keys
                .OrderBy(
                    path => path,
                    StringComparer.OrdinalIgnoreCase)
                .ToList();
            for (var vmdIndex = 0;
                 vmdIndex < validationVmds.Count;
                 vmdIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var vmdPath = validationVmds[vmdIndex];
                ReportProgress(
                    progress,
                    "Validating modified VMDs",
                    vmdIndex + 1,
                    validationVmds.Count,
                    vmdPath);
                var file = state.Output.FindFile(vmdPath);
                if (file == null)
                {
                    errors.Add(
                        $"Modified VMD is missing from output: {vmdPath}");
                    continue;
                }

                try
                {
                    var vmd = VariantMeshDefinitionLoader.Load(file);
                    var modelRefs = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    var childVmdRefs = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    var directTextures = new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase);
                    CollectVmdReferences(
                        vmd,
                        modelRefs,
                        childVmdRefs,
                        directTextures);

                    foreach (var generatedReference in modelRefs
                                 .Select(Normalize)
                                 .Where(path =>
                                     state.CrossRigidGeneratedWsModelPaths
                                         .Contains(path))
                                 .Distinct(
                                     StringComparer.OrdinalIgnoreCase))
                    {
                        if (!CanResolveAfterRewrite(
                                state,
                                generatedReference))
                        {
                            errors.Add(
                                $"Cross-rigid generated WSModel no longer resolves: " +
                                $"{vmdPath} -> {generatedReference}");
                        }
                    }

                    foreach (var generatedChildVmd in childVmdRefs
                                 .Select(Normalize)
                                 .Where(path =>
                                     state.CrossRigidGeneratedVmdPaths
                                         .Contains(path))
                                 .Distinct(
                                     StringComparer.OrdinalIgnoreCase))
                    {
                        if (!CanResolveAfterRewrite(
                                state,
                                generatedChildVmd))
                        {
                            errors.Add(
                                $"Cross-rigid generated child VMD no longer resolves: " +
                                $"{vmdPath} -> {generatedChildVmd}");
                        }
                    }
                }
                catch (Exception ex)
                {
                    errors.Add(
                        $"Modified VMD failed to reload: {vmdPath} ({ex.Message})");
                }
            }

            var validationRigids = state.ModifiedRigids.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
            for (var rigidIndex = 0; rigidIndex < validationRigids.Count; rigidIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var rigidPath = validationRigids[rigidIndex];
                ReportProgress(
                    progress,
                    "Validating modified rigids",
                    rigidIndex + 1,
                    validationRigids.Count,
                    rigidPath);
                var file = state.Output.FindFile(rigidPath);
                if (file == null)
                {
                    errors.Add($"Modified rigid is missing from output: {rigidPath}");
                    continue;
                }

                try
                {
                    _ = ModelFactory.Create().Load(file.DataSource.ReadData());
                }
                catch (Exception ex)
                {
                    errors.Add($"Modified rigid failed to reload: {rigidPath} ({ex.Message})");
                }
            }

            var validationWsModels = state.ModifiedWsModels
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();
            for (var wsIndex = 0; wsIndex < validationWsModels.Count; wsIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var wsPath = validationWsModels[wsIndex];
                ReportProgress(
                    progress,
                    "Validating WSModels",
                    wsIndex + 1,
                    validationWsModels.Count,
                    wsPath);
                var file = state.Output.FindFile(wsPath);
                if (file == null)
                {
                    errors.Add($"Modified WSModel is missing from output: {wsPath}");
                    continue;
                }

                XmlDocument wsDoc;
                try
                {
                    wsDoc = LoadXml(file);
                }
                catch (Exception ex)
                {
                    errors.Add($"Modified WSModel XML is invalid: {wsPath} ({ex.Message})");
                    continue;
                }

                var geometryPath = Normalize(wsDoc.SelectSingleNode("/model/geometry")?.InnerText);
                if (!string.IsNullOrWhiteSpace(geometryPath) &&
                    !CanResolveAfterRewrite(state, geometryPath))
                {
                    if (IsPreservedSourceUnresolvedWsReference(
                            state,
                            wsPath,
                            geometryPath,
                            "/model/geometry"))
                    {
                        AddValidationWarning(
                            state,
                            $"Preserved pre-existing unresolved WSModel geometry: " +
                            $"{wsPath} -> {geometryPath}");
                    }
                    else
                    {
                        errors.Add($"WSModel geometry no longer resolves: {wsPath} -> {geometryPath}");
                    }
                }

                var materialNodes = wsDoc.SelectNodes("/model/materials/material");
                if (materialNodes == null)
                    continue;

                foreach (XmlNode materialNode in materialNodes)
                {
                    var materialPath = Normalize(materialNode.InnerText);
                    if (!string.IsNullOrWhiteSpace(materialPath) &&
                        !CanResolveAfterRewrite(state, materialPath))
                    {
                        if (IsPreservedSourceUnresolvedWsReference(
                                state,
                                wsPath,
                                materialPath,
                                "/model/materials/material"))
                        {
                            AddValidationWarning(
                                state,
                                $"Preserved pre-existing unresolved WSModel material: " +
                                $"{wsPath} -> {materialPath}");
                        }
                        else
                        {
                            errors.Add($"WSModel material no longer resolves: {wsPath} -> {materialPath}");
                        }
                    }
                }

                if (!string.IsNullOrWhiteSpace(geometryPath))
                {
                    var geometryFile = state.Output.FindFile(geometryPath);
                    if (geometryFile != null)
                    {
                        try
                        {
                            var outputRmv = ModelFactory.Create().Load(geometryFile.DataSource.ReadData());
                            if (!TryReadWsMaterialAssignments(
                                    wsDoc,
                                    outputRmv,
                                    out _,
                                    out var assignmentReason))
                            {
                                if (HasSameSourceWsMaterialMismatch(
                                        state,
                                        wsPath,
                                        geometryPath,
                                        assignmentReason))
                                {
                                    state.ValidationMessages.Add(
                                        $"WARNING: Preserved pre-existing WSModel material-table mismatch: " +
                                        $"{wsPath} -> {geometryPath} ({assignmentReason})");
                                }
                                else
                                {
                                    errors.Add(
                                        $"WSModel material table does not match rewritten rigid: " +
                                        $"{wsPath} -> {geometryPath} ({assignmentReason})");
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            errors.Add(
                                $"Could not validate WSModel material table against rigid: " +
                                $"{wsPath} -> {geometryPath} ({ex.Message})");
                        }
                    }
                }
            }

            var validationMaterials = state.GeneratedMaterialPaths
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .ToList();
            for (var materialIndex = 0; materialIndex < validationMaterials.Count; materialIndex++)
            {
                cancellationToken.ThrowIfCancellationRequested();
                var materialPath = validationMaterials[materialIndex];
                ReportProgress(
                    progress,
                    "Validating atlas materials",
                    materialIndex + 1,
                    validationMaterials.Count,
                    materialPath);
                var file = state.Output.FindFile(materialPath);
                if (file == null)
                {
                    errors.Add($"Generated atlas material is missing: {materialPath}");
                    continue;
                }

                XmlDocument materialDoc;
                try
                {
                    materialDoc = LoadXml(file);
                }
                catch (Exception ex)
                {
                    errors.Add($"Generated atlas material XML is invalid: {materialPath} ({ex.Message})");
                    continue;
                }

                var textureNodes = materialDoc.SelectNodes("/material/textures/texture");
                if (textureNodes == null)
                    continue;

                foreach (XmlNode textureNode in textureNodes)
                {
                    var texturePath = Normalize(
                        textureNode.SelectSingleNode("source")?.InnerText ?? textureNode.InnerText);
                    if (string.IsNullOrWhiteSpace(texturePath) || IsTexturePlaceholder(texturePath))
                        continue;

                    if (!CanResolveAfterRewrite(state, texturePath))
                    {
                        errors.Add(
                            $"Generated material texture no longer resolves: {materialPath} -> {texturePath}");
                    }
                }
            }

            foreach (var atlasPath in state.GeneratedTexturePaths)
            {
                if (state.Output.FindFile(atlasPath) == null)
                    errors.Add($"Generated atlas texture is missing from output: {atlasPath}");
            }

            foreach (var vmdPath in vmdRoots)
            {
                if (state.Output.FindFile(vmdPath) == null)
                    errors.Add($"VMD root is missing from output: {vmdPath}");
            }

            if (errors.Count != 0)
            {
                foreach (var error in errors)
                    state.ValidationMessages.Add("ERROR: " + error);

                throw new InvalidOperationException(
                    $"Post-atlas dependency validation failed with {errors.Count} error(s). " +
                    $"See {state.ReportPath} for the full report.\n" +
                    string.Join("\n", errors.Take(10)));
            }

            state.ValidationMessages.Add(
                $"PASS: {state.CrossRigidRewrittenRootVmdPaths.Count} rewritten source VMD(s), " +
                $"{state.CrossRigidGeneratedVmdPaths.Count} generated VMD clone(s), " +
                $"{state.ModifiedRigids.Count} modified/generated rigid(s), " +
                $"{state.ModifiedWsModels.Count} modified/generated WSModel(s), " +
                $"{state.GeneratedMaterialPaths.Count} generated material(s), and " +
                $"{state.GeneratedTexturePaths.Count} atlas texture(s) validated.");
            state.ValidationMessages.Add(
                $"PASS: source VMD/WSModel/RMV2 paths were preserved; " +
                $"{state.CrossRigidGeneratedVmdPaths.Count} generated cross-rigid VMD clone(s), " +
                $"{state.CrossRigidGeneratedWsModelPaths.Count} generated cross-rigid WSModel(s), and " +
                $"{state.CrossRigidGeneratedRigidPaths.Count} generated cross-rigid RMV2 file(s) were validated.");
            if (state.MergeCompatibleMeshesEnabled && state.MeshMergeInvariantGroupCount != 0)
            {
                state.ValidationMessages.Add(
                    $"PASS: merge geometry invariants validated for " +
                    $"{state.MeshMergeInvariantGroupCount} merged group(s) across " +
                    $"{state.MeshMergeInvariantLodCount} LOD(s); " +
                    $"{state.MeshMergeInvariantWsModelCount} WSModel non-material structure check(s) passed.");
            }
        }

        private bool IsPreservedSourceUnresolvedWsReference(
            BatchState state,
            string wsPathValue,
            string referencePathValue,
            string xpath)
        {
            var wsPath = Normalize(wsPathValue);
            var referencePath = Normalize(referencePathValue);
            if (wsPath.Length == 0 || referencePath.Length == 0)
                return false;

            try
            {
                var sourceWsFile = state.Source.FindFile(wsPath);
                if (sourceWsFile == null)
                    return false;

                var sourceWsDocument = LoadXml(sourceWsFile);
                var sourceNodes = sourceWsDocument.SelectNodes(xpath);
                if (sourceNodes == null ||
                    !sourceNodes
                        .Cast<XmlNode>()
                        .Any(node => Normalize(node.InnerText)
                            .Equals(referencePath, StringComparison.OrdinalIgnoreCase)))
                {
                    return false;
                }

                // The exact same reference was already present in the source WSModel.
                // Only downgrade it to a warning when it was unresolved before rewriting.
                if (state.Source.FindFile(referencePath) != null)
                    return false;

                return _packFileService.FindFile(referencePath) == null;
            }
            catch
            {
                // If the source baseline cannot be established reliably, retain strict
                // validation and keep the rewritten-output failure fatal.
                return false;
            }
        }

        private static void AddValidationWarning(BatchState state, string message)
        {
            var fullMessage = "WARNING: " + message;
            if (!state.ValidationMessages.Contains(fullMessage, StringComparer.Ordinal))
                state.ValidationMessages.Add(fullMessage);
        }

        private static bool HasSameSourceWsMaterialMismatch(
            BatchState state,
            string wsPath,
            string geometryPath,
            string outputReason)
        {
            try
            {
                var sourceWsFile = state.Source.FindFile(wsPath);
                var sourceGeometryFile = state.Source.FindFile(geometryPath);
                if (sourceWsFile == null || sourceGeometryFile == null)
                    return false;

                var sourceWsDocument = LoadXml(sourceWsFile);
                var sourceRmv = ModelFactory.Create().Load(sourceGeometryFile.DataSource.ReadData());
                if (TryReadWsMaterialAssignments(
                        sourceWsDocument,
                        sourceRmv,
                        out _,
                        out var sourceReason))
                {
                    return false;
                }

                return string.Equals(
                    sourceReason,
                    outputReason,
                    StringComparison.Ordinal);
            }
            catch
            {
                // If the source baseline cannot be established reliably, retain strict
                // validation and let the rewritten-output mismatch remain fatal.
                return false;
            }
        }

        private static void ValidateUnchangedModelPathSet(
            BatchState state,
            string extension,
            List<string> errors,
            IReadOnlySet<string>? expectedAddedPaths = null)
        {
            var sourcePaths = state.Source.GetAllFiles().Keys
                .Where(x => Path.GetExtension(x).Equals(extension, StringComparison.OrdinalIgnoreCase))
                .Select(Normalize)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            var outputPaths = state.Output.GetAllFiles().Keys
                .Where(x => Path.GetExtension(x).Equals(extension, StringComparison.OrdinalIgnoreCase))
                .Select(Normalize)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            var expectedAdditions = expectedAddedPaths == null
                ? new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                : expectedAddedPaths
                    .Select(Normalize)
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

            foreach (var missing in sourcePaths.Except(outputPaths, StringComparer.OrdinalIgnoreCase))
                errors.Add($"{extension} path was removed instead of rewritten in place: {missing}");

            var actualAdditions = outputPaths
                .Except(sourcePaths, StringComparer.OrdinalIgnoreCase)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            foreach (var added in actualAdditions
                         .Except(expectedAdditions, StringComparer.OrdinalIgnoreCase))
            {
                errors.Add($"Unexpected new {extension} path was created: {added}");
            }

            foreach (var expected in expectedAdditions
                         .Except(actualAdditions, StringComparer.OrdinalIgnoreCase))
            {
                errors.Add($"Expected generated {extension} path is missing: {expected}");
            }
        }

        private bool CanResolveAfterRewrite(BatchState state, string path)
        {
            path = Normalize(path);
            if (string.IsNullOrWhiteSpace(path))
                return true;

            if (state.Output.FindFile(path) != null)
                return true;

            // If the selected source pack owned the path, it must still exist in the output.
            // Do not let another loaded pack with the same path mask an accidental deletion.
            if (state.Source.FindFile(path) != null)
                return false;

            return _packFileService.FindFile(path) != null;
        }

        private static void RecordSkip(
            BatchState state,
            string rootVmdPath,
            MeshKey key,
            string wsModelPath,
            string reason)
        {
            if (!state.SkipDetails.TryGetValue(key, out var details))
            {
                details = [];
                state.SkipDetails[key] = details;
            }

            if (!details.Any(x =>
                    x.RootVmdPath.Equals(rootVmdPath, StringComparison.OrdinalIgnoreCase) &&
                    x.WsModelPath.Equals(wsModelPath, StringComparison.OrdinalIgnoreCase) &&
                    x.Reason.Equals(reason, StringComparison.Ordinal)))
            {
                details.Add(new SkipDetail(rootVmdPath, wsModelPath, reason));
            }
        }

        private static int GetEffectiveSkippedMeshCount(BatchState state)
            => state.SkipDetails.Keys.Count(x => !state.ProcessedMeshes.Contains(x));

        private static void AppendDiagnosticCounts(
            StringBuilder sb,
            string title,
            IReadOnlyDictionary<string, int> counts,
            int maxEntries)
        {
            sb.AppendLine($"  {title}:");
            if (counts.Count == 0)
            {
                sb.AppendLine("    (none)");
                return;
            }

            foreach (var entry in counts
                         .OrderByDescending(x => x.Value)
                         .ThenBy(x => x.Key, StringComparer.Ordinal)
                         .Take(maxEntries))
            {
                sb.AppendLine($"    {entry.Key}: {entry.Value}");
            }

            if (counts.Count > maxEntries)
                sb.AppendLine($"    ... {counts.Count - maxEntries} more");
        }

        private static void AppendGameplayMeshDependencyDiagnostics(
            StringBuilder sb,
            BatchState state)
        {
            sb.AppendLine("Gameplay mesh-consumer discovery diagnostics");
            sb.AppendLine("--------------------------------------------");

            var index = state.GameplayMeshDependencyIndex;
            if (index == null)
            {
                sb.AppendLine("(not available)");
                sb.AppendLine();
                return;
            }

            var containerSnapshot = state.GameplayTraversalContainers;
            var blockingFailures = index.BlockingFailureDetails.ToArray();
            var verifiedMissingFailures = index.VerifiedMissingFailureDetails.ToArray();
            var caContainerCount = containerSnapshot?.Count(container => container.IsCaPackFile) ?? 0;
            sb.AppendLine(
                $"Gameplay container snapshot: {(containerSnapshot == null ? "UNAVAILABLE" : "CAPTURED")} " +
                $"({containerSnapshot?.Count ?? 0:N0} container(s), {caContainerCount:N0} CA container(s))");
            sb.AppendLine(
                $"Verified-missing classification: {(index.VerifiedMissingClassificationEnabled ? "ENABLED" : "DISABLED")}");
            sb.AppendLine($"Discovery roots: {index.GameplayRoots.Count}");
            sb.AppendLine($"Incomplete roots: {index.IncompleteRoots.Count}");
            sb.AppendLine($"Failure details: {index.FailureDetails.Count}");
            sb.AppendLine($"Blocking failure details: {blockingFailures.Length}");
            sb.AppendLine($"Verified-missing dependency details: {verifiedMissingFailures.Length}");
            sb.AppendLine(
                $"Verified-missing dependency paths: " +
                $"{verifiedMissingFailures
                    .Select(failure => failure.AssetPath)
                    .Where(path => path.Length != 0)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count()}");
            sb.AppendLine(
                $"Discovery-blocked assets: " +
                $"{state.ConsumerDiscoveryBlocks.Select(x => x.AssetPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase).Count()}");
            sb.AppendLine(
                $"Discovery-blocked structural assets: " +
                $"{state.ConsumerDiscoveryBlocks
                    .Where(x => x.BlockKind.Equals(
                        "StructuralMerge",
                        StringComparison.Ordinal))
                    .Select(x => x.AssetPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count()}");
            sb.AppendLine(
                $"Discovery-blocked atlas candidates: " +
                $"{state.ConsumerDiscoveryBlocks
                    .Where(x => x.BlockKind.Equals(
                        "AtlasRewrite",
                        StringComparison.Ordinal))
                    .Select(x => x.AssetPath)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .Count()}");

            var rootOriginCounts = index.RootKindsByPath
                .SelectMany(entry => entry.Value.Select(kind =>
                    FormatGameplayMeshDependencyRootKind(kind)))
                .GroupBy(value => value, StringComparer.Ordinal)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
            AppendDiagnosticCounts(
                sb,
                "Root origins",
                rootOriginCounts,
                maxEntries: 16);

            var incompleteRootOriginCounts = index.IncompleteRoots
                .SelectMany(root => index.GetRootKinds(root)
                    .Select(kind => FormatGameplayMeshDependencyRootKind(kind)))
                .GroupBy(value => value, StringComparer.Ordinal)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
            AppendDiagnosticCounts(
                sb,
                "Incomplete root origins",
                incompleteRootOriginCounts,
                maxEntries: 16);

            var failureScopeCounts = index.FailureDetails
                .GroupBy(
                    failure => FormatGameplayMeshDependencyAssetScope(failure.AssetScope),
                    StringComparer.Ordinal)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
            AppendDiagnosticCounts(
                sb,
                "Failure asset ownership",
                failureScopeCounts,
                maxEntries: 8);

            var failureReasonCounts = index.FailureDetails
                .GroupBy(failure => failure.Reason, StringComparer.Ordinal)
                .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
            AppendDiagnosticCounts(
                sb,
                "Failure reasons",
                failureReasonCounts,
                maxEntries: 32);

            AppendGameplayMeshDependencyFailureDetails(
                sb,
                "Blocking failure details",
                index,
                blockingFailures);
            AppendGameplayMeshDependencyFailureDetails(
                sb,
                "Verified-missing dependency details",
                index,
                verifiedMissingFailures);

            sb.AppendLine();
            sb.AppendLine("Discovery-blocked assets");
            sb.AppendLine("------------------------");
            if (state.ConsumerDiscoveryBlocks.Count == 0)
            {
                sb.AppendLine("(none)");
            }
            else
            {
                foreach (var block in state.ConsumerDiscoveryBlocks
                             .OrderBy(entry => entry.BlockKind, StringComparer.Ordinal)
                             .ThenBy(entry => entry.AssetPath, StringComparer.OrdinalIgnoreCase)
                             .ThenBy(entry => entry.IncompleteRootPath, StringComparer.OrdinalIgnoreCase))
                {
                    var rootOrigins = index.GetRootKinds(block.IncompleteRootPath)
                        .Select(FormatGameplayMeshDependencyRootKind)
                        .OrderBy(value => value, StringComparer.Ordinal)
                        .ToArray();
                    sb.AppendLine(
                        $"  kind={block.BlockKind} | " +
                        $"asset={FormatDiagnosticPath(block.AssetPath)} | " +
                        $"incomplete-root={FormatDiagnosticPath(block.IncompleteRootPath)} | " +
                        $"origins={(rootOrigins.Length == 0 ? "Unknown" : string.Join(",", rootOrigins))}");
                }
            }

            sb.AppendLine();
        }

        private static void AppendGameplayMeshDependencyFailureDetails(
            StringBuilder sb,
            string title,
            GameplayMeshDependencyIndex index,
            IEnumerable<GameplayMeshDependencyFailure> failures)
        {
            sb.AppendLine(title);
            sb.AppendLine(new string('-', title.Length));
            var orderedFailures = failures
                .OrderBy(entry => entry.RootPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(entry => entry.AssetPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(entry => entry.Reason, StringComparer.Ordinal)
                .ThenBy(entry => entry.AssetScope)
                .ToArray();
            if (orderedFailures.Length == 0)
            {
                sb.AppendLine("(none)");
                return;
            }

            foreach (var failure in orderedFailures)
            {
                var rootOrigins = index.GetRootKinds(failure.RootPath)
                    .Select(FormatGameplayMeshDependencyRootKind)
                    .OrderBy(value => value, StringComparer.Ordinal)
                    .ToArray();
                sb.AppendLine(
                    $"  root={FormatDiagnosticPath(failure.RootPath)} | " +
                    $"origins={(rootOrigins.Length == 0 ? "Unknown" : string.Join(",", rootOrigins))} | " +
                    $"asset={FormatDiagnosticPath(failure.AssetPath)} | " +
                    $"kind={failure.FailureKind} | " +
                    $"disposition={failure.Disposition} | " +
                    $"owner={FormatGameplayMeshDependencyAssetScope(failure.AssetScope)} | " +
                    $"reason={failure.Reason}");
            }
        }

        private static string FormatGameplayMeshDependencyRootKind(
            GameplayMeshDependencyRootKind rootKind)
            => rootKind switch
            {
                GameplayMeshDependencyRootKind.SourcePackVmd => "SourcePackVmd",
                GameplayMeshDependencyRootKind.ResolvedRosterVmd => "ResolvedRosterVmd",
                GameplayMeshDependencyRootKind.ResidencyAsset => "ResidencyAsset",
                GameplayMeshDependencyRootKind.UnresolvedResolverVmd => "UnresolvedResolverVmd",
                GameplayMeshDependencyRootKind.DirectGameplayAsset => "DirectGameplayAsset",
                _ => rootKind.ToString(),
            };

        private static string FormatGameplayMeshDependencyAssetScope(
            GameplayMeshDependencyAssetScope assetScope)
            => assetScope switch
            {
                GameplayMeshDependencyAssetScope.SourcePack => "SourcePack",
                GameplayMeshDependencyAssetScope.CaPack => "CaPack",
                GameplayMeshDependencyAssetScope.Missing => "Missing",
                _ => assetScope.ToString(),
            };

        private static string FormatGameplayMeshDependencyFailure(
            GameplayMeshDependencyFailure failure)
            => $"{(failure.RootPath.Length == 0 ? "<unknown-root>" : failure.RootPath)} -> " +
               $"{(failure.AssetPath.Length == 0 ? "<unknown-asset>" : failure.AssetPath)}: " +
               $"{failure.Reason} (kind={failure.FailureKind}, " +
               $"disposition={failure.Disposition}, scope={failure.AssetScope})";

        private static string FormatDiagnosticPath(string path)
            => string.IsNullOrWhiteSpace(path) ? "<unknown>" : path;

        private static AtlasComponentReuseAnalysis BuildAtlasComponentReuseAnalysis(
            BatchState state)
        {
            var batchesByWsModel = new Dictionary<string, HashSet<int>>(
                StringComparer.OrdinalIgnoreCase);
            var geometryByWsModel = new Dictionary<string, string>(
                StringComparer.OrdinalIgnoreCase);

            foreach (var (batchId, batch) in state.AtlasBatchDiagnostics)
            {
                foreach (var candidate in batch.Candidates)
                {
                    foreach (var usage in candidate.Usages)
                    {
                        var wsModelPath = Normalize(usage.AssetPath);
                        if (string.IsNullOrWhiteSpace(wsModelPath))
                            continue;

                        if (!batchesByWsModel.TryGetValue(wsModelPath, out var batchIds))
                        {
                            batchIds = [];
                            batchesByWsModel[wsModelPath] = batchIds;
                        }

                        batchIds.Add(batchId);
                        geometryByWsModel.TryAdd(wsModelPath, candidate.Key.GeometryPath);
                    }
                }
            }

            if (batchesByWsModel.Count == 0)
            {
                return new AtlasComponentReuseAnalysis(
                    [],
                    [],
                    0,
                    0);
            }

            var rootsByWsModel = new Dictionary<string, HashSet<string>>(
                StringComparer.OrdinalIgnoreCase);
            foreach (var (rootVmdPath, reachableWsModels) in state.ReachableWsModelsByRoot)
            {
                var root = Normalize(rootVmdPath);
                foreach (var reachableWsModel in reachableWsModels)
                {
                    var wsModelPath = Normalize(reachableWsModel);
                    if (!batchesByWsModel.ContainsKey(wsModelPath))
                        continue;

                    if (!rootsByWsModel.TryGetValue(wsModelPath, out var roots))
                    {
                        roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                        rootsByWsModel[wsModelPath] = roots;
                    }

                    roots.Add(root);
                }
            }

            var rootsByGeometry = new Dictionary<string, HashSet<string>>(
                StringComparer.OrdinalIgnoreCase);
            foreach (var (wsModelPath, roots) in rootsByWsModel)
            {
                if (!geometryByWsModel.TryGetValue(wsModelPath, out var geometryPath))
                    continue;

                if (!rootsByGeometry.TryGetValue(geometryPath, out var geometryRoots))
                {
                    geometryRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    rootsByGeometry[geometryPath] = geometryRoots;
                }

                geometryRoots.UnionWith(roots);
            }

            var components = batchesByWsModel.Keys
                .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                .Select(wsModelPath =>
                {
                    rootsByWsModel.TryGetValue(wsModelPath, out var roots);
                    geometryByWsModel.TryGetValue(wsModelPath, out var geometryPath);
                    return new AtlasComponentReuseEntry(
                        wsModelPath,
                        geometryPath ?? string.Empty,
                        roots?.Count ?? 0,
                        batchesByWsModel[wsModelPath]
                            .OrderBy(x => x)
                            .ToArray());
                })
                .ToList();

            // Count root overlap only for atlased components on different geometry assets and
            // with different atlas-batch membership. This focuses the report on relationships
            // relevant to a future cross-component/pair-specific rebake instead of same-rigid
            // parts that inherently travel together.
            var sharedRootCounts = new Dictionary<(string Left, string Right), int>();
            foreach (var (_, reachableWsModels) in state.ReachableWsModelsByRoot)
            {
                var models = reachableWsModels
                    .Select(Normalize)
                    .Where(batchesByWsModel.ContainsKey)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var reusedModels = models
                    .Where(model =>
                        rootsByWsModel.TryGetValue(model, out var roots) &&
                        roots.Count > 1)
                    .ToList();
                var seenPairsInRoot = new HashSet<(string Left, string Right)>();

                // One-off <> one-off combinations cannot demonstrate lost reuse, so do not
                // spend quadratic work on them. Pair every reusable component with the other
                // atlased components reachable from the same root.
                foreach (var reusable in reusedModels)
                {
                    if (!geometryByWsModel.TryGetValue(reusable, out var reusableGeometry))
                        continue;

                    foreach (var other in models)
                    {
                        if (reusable.Equals(other, StringComparison.OrdinalIgnoreCase) ||
                            !geometryByWsModel.TryGetValue(other, out var otherGeometry) ||
                            reusableGeometry.Equals(otherGeometry, StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        if (batchesByWsModel[reusable].SetEquals(batchesByWsModel[other]))
                            continue;

                        var key = StringComparer.OrdinalIgnoreCase.Compare(reusable, other) <= 0
                            ? (reusable, other)
                            : (other, reusable);
                        if (!seenPairsInRoot.Add(key))
                            continue;

                        sharedRootCounts[key] = sharedRootCounts.GetValueOrDefault(key) + 1;
                    }
                }
            }

            var pairs = new List<AtlasComponentReusePairEntry>();
            foreach (var (key, sharedRootCount) in sharedRootCounts)
            {
                if (!rootsByWsModel.TryGetValue(key.Left, out var leftRoots) ||
                    !rootsByWsModel.TryGetValue(key.Right, out var rightRoots) ||
                    leftRoots.Count == 0 ||
                    rightRoots.Count == 0)
                {
                    continue;
                }

                var leftCoverage = sharedRootCount / (double)leftRoots.Count;
                var rightCoverage = sharedRootCount / (double)rightRoots.Count;
                var stronglyAsymmetric =
                    (leftCoverage >= 0.8 && rightCoverage <= 0.5) ||
                    (rightCoverage >= 0.8 && leftCoverage <= 0.5);
                var highBidirectionalOverlap =
                    leftCoverage >= 0.8 &&
                    rightCoverage >= 0.8;

                pairs.Add(new AtlasComponentReusePairEntry(
                    key.Left,
                    key.Right,
                    geometryByWsModel[key.Left],
                    geometryByWsModel[key.Right],
                    leftRoots.Count,
                    rightRoots.Count,
                    sharedRootCount,
                    leftCoverage,
                    rightCoverage,
                    batchesByWsModel[key.Left].OrderBy(x => x).ToArray(),
                    batchesByWsModel[key.Right].OrderBy(x => x).ToArray(),
                    stronglyAsymmetric,
                    highBidirectionalOverlap));
            }

            return new AtlasComponentReuseAnalysis(
                components,
                pairs,
                rootsByGeometry.Count,
                rootsByGeometry.Values.Count(roots => roots.Count > 1));
        }

        private static AtlasResidencySummary BuildAtlasResidencySummary(
            BatchState state)
        {
            var physicalPages = state.AtlasPhysicalPageDiagnostics;
            var allCandidates = physicalPages
                .SelectMany(page => page.Candidates)
                .GroupBy(candidate => candidate.Key)
                .Select(group => group.First())
                .ToList();
            if (allCandidates.Count == 0)
            {
                return new AtlasResidencySummary(
                    0,
                    0,
                    0,
                    0,
                    string.Empty,
                    0);
            }

            var rootsByMesh = BuildCandidateRootVmdPaths(state, allCandidates);
            var pixelsByRoot = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
            long globalPixels = 0;
            long aggregateResidentPixels = 0;
            var multiRootPages = 0;
            var maxRootsPerPage = 0;

            foreach (var page in physicalPages)
            {
                globalPixels = checked(globalPixels + page.PixelCost);

                var roots = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var candidate in page.Candidates)
                {
                    if (rootsByMesh.TryGetValue(candidate.Key, out var candidateRoots))
                        roots.UnionWith(candidateRoots);
                    else
                        roots.Add(Normalize(candidate.RootVmdPath));
                }

                var rootCount = Math.Max(1, roots.Count);
                maxRootsPerPage = Math.Max(maxRootsPerPage, rootCount);
                if (rootCount > 1)
                    multiRootPages++;

                aggregateResidentPixels = checked(
                    aggregateResidentPixels +
                    GetAtlasResidencyProxy(page.PixelCost, rootCount));

                foreach (var root in roots)
                {
                    pixelsByRoot[root] = checked(
                        pixelsByRoot.GetValueOrDefault(root) +
                        page.PixelCost);
                }
            }

            var worstRoot = pixelsByRoot
                .OrderByDescending(entry => entry.Value)
                .ThenBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase)
                .FirstOrDefault();

            return new AtlasResidencySummary(
                globalPixels,
                aggregateResidentPixels,
                multiRootPages,
                maxRootsPerPage,
                worstRoot.Key ?? string.Empty,
                worstRoot.Value);
        }

        private static void WriteReport(
            BatchState state,
            IReadOnlyList<string> vmdRoots,
            bool succeeded,
            Exception? failure)
        {
            var componentReuse = BuildAtlasComponentReuseAnalysis(state);
            var residency = BuildAtlasResidencySummary(state);
            var sb = new StringBuilder();
            sb.AppendLine("Texture Atlas Pack Report");
            sb.AppendLine("=========================");
            sb.AppendLine($"Status: {(succeeded ? "SUCCESS" : "FAILED")}");
            sb.AppendLine($"Source: {state.SourcePath}");
            sb.AppendLine($"Output: {state.OutputPath}");
            sb.AppendLine($"Report: {state.ReportPath}");
            sb.AppendLine($"Generated: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
            sb.AppendLine();

            sb.AppendLine("Summary");
            sb.AppendLine("-------");
            sb.AppendLine($"Validated source VMD roots: {vmdRoots.Count}");
            sb.AppendLine(
                $"Atlas VMD population: {(state.AtlasAllVmdsEnabled ? "PACK-WIDE" : "GAMEPLAY-USED")}");
            sb.AppendLine($"Atlas VMD roots: {state.AtlasVmdRootCount:N0} / {state.SourceVmdRootCount:N0}");
            if (state.UnitCategoryResolution != null)
            {
                if (state.ArmyResidencyModel != null)
                {
                    sb.AppendLine(
                        $"Atlas value-model roster scope: culture-local " +
                        $"({(state.ArmyResidencyModel.IncludesAllGameCultures ? "all game cultures" : "pack-affected cultures")})");
                    sb.AppendLine(
                        $"Atlas value-model player cultures: {state.ArmyResidencyModel.PlayerCultureWeights.Count:N0} " +
                        $"[{string.Join(", ", state.ArmyResidencyModel.PlayerCultureWeights.Keys.OrderBy(value => value, StringComparer.OrdinalIgnoreCase))}]");
                    sb.AppendLine(
                        $"Atlas value-model opponent cultures: {state.ArmyResidencyModel.OpponentCultureWeights.Count:N0} " +
                        "(uniform across the resolved game roster; unrelated cultures contribute zero for culture-local assets).");
                    sb.AppendLine(
                        "Vanilla-owned visual assets: read-only residency consumers (never rewritten; never physically retired).");
                    sb.AppendLine(
                        "Atlas value-gate pack-local retirement scope: source-pack WSModel/rigid " +
                        "rewrites; source-pack direct VMD references still block retirement, while " +
                        "vanilla-only consumers remain residency-only.");
                }
                var gameplayEligibleVmdCount = state.UnitCategoryResolution.UsagesByVmd.Keys
                    .Count(state.UnitCategoryResolution.IsVmdUsageComplete);
                sb.AppendLine(
                    $"Gameplay-used VMD roots: " +
                    $"{gameplayEligibleVmdCount:N0} / {vmdRoots.Count:N0}");
                sb.AppendLine(
                    $"VMD roots tainted by unresolved gameplay consumers: " +
                    $"{state.UnitCategoryResolution.UnresolvedConsumersByVmd.Count:N0}");
                sb.AppendLine(
                    $"VMD roots excluded from gameplay-used atlasing: " +
                    $"{Math.Max(0, vmdRoots.Count - gameplayEligibleVmdCount):N0}");
                sb.AppendLine(
                    $"Unit-category DB table files read: " +
                    $"{state.UnitCategoryResolution.TableFilesRead}");
                sb.AppendLine(
                    $"Gameplay resolver global health: " +
                    $"{(state.UnitCategoryResolution.IsGameplayResolutionHealthy ? "HEALTHY" : "UNHEALTHY")}");
                if (!string.IsNullOrWhiteSpace(
                        state.UnitCategoryResolution.GameplayResolutionHealthMessage))
                {
                    sb.AppendLine(
                        $"Gameplay resolver health detail: " +
                        state.UnitCategoryResolution.GameplayResolutionHealthMessage);
                }

                var directConsumerCounts = state.UnitCategoryResolution.DirectUsagesByVmd.Values
                    .SelectMany(usages => usages)
                    .SelectMany(usage => usage.Provenance)
                    .GroupBy(provenance => provenance.ConsumerType)
                    .OrderBy(group => group.Key)
                    .Select(group => $"{group.Key}={group.Count():N0}")
                    .ToArray();
                sb.AppendLine(
                    $"Direct gameplay VMD consumer links: " +
                    $"{(directConsumerCounts.Length == 0 ? "(none)" : string.Join(", ", directConsumerCounts))}");
                sb.AppendLine(
                    $"Gameplay VMD roots added through child propagation: " +
                    $"{state.UnitCategoryResolution.PropagatedVmdCount:N0}");
            }
            sb.AppendLine($"XML files repaired for compatibility: {state.XmlCompatibilityRepairs.Count}");
            sb.AppendLine($"Malformed VMD root files ignored: {state.MalformedVmdRoots.Count}");
            sb.AppendLine($"Malformed referenced VMD files ignored: {state.MalformedReferencedVmds.Count}");
            sb.AppendLine($"Malformed WSModels ignored: {state.MalformedWsModelsIgnored.Count}");
            sb.AppendLine($"Malformed material XML files ignored: {state.MalformedMaterialsIgnored.Count}");
            sb.AppendLine(
                $"Gameplay traversal container resolutions: " +
                $"{state.GameplayTraversalContainerResolutions.Count:N0} unique path(s); " +
                $"{state.GameplayTraversalContainerResolutionScans:N0} scan(s), " +
                $"{state.GameplayTraversalContainerResolutionCacheHits:N0} cache hit(s)");
            sb.AppendLine(
                $"Atlas value-gate reachable WSModels: " +
                $"{state.AtlasValueGateReachableWsModelCount:N0} total " +
                $"(source={state.AtlasValueGateSourceWsModelCount:N0}, " +
                $"CA={state.AtlasValueGateCaWsModelCount:N0}, " +
                $"unresolved={state.AtlasValueGateUnresolvedWsModelCount:N0})");
            sb.AppendLine(
                $"Atlas value-gate direct consumer paths: " +
                $"rigid={state.AtlasValueGateDirectRigidPathCount:N0}, " +
                $"VMD={state.AtlasValueGateDirectVmdPathCount:N0}");
            sb.AppendLine(
                $"Atlas value-gate WSModel consumer cache: " +
                $"{state.AtlasValueGateWsModelConsumerCacheHits:N0} hit(s) " +
                $"(memory={state.AtlasValueGateWsModelConsumerMemoryCacheHits:N0}, " +
                $"vanilla={state.AtlasValueGateWsModelConsumerVanillaCacheHits:N0}), " +
                $"{state.AtlasValueGateWsModelConsumerCacheMisses:N0} miss(es), " +
                $"{state.AtlasValueGateWsModelConsumerEntryBuilds:N0} entry build(s)");
            sb.AppendLine(
                $"Atlas value-gate material consumer cache: " +
                $"{state.AtlasValueGateMaterialConsumerCacheHits:N0} hit(s) " +
                $"(memory={state.AtlasValueGateMaterialConsumerMemoryCacheHits:N0}, " +
                $"vanilla={state.AtlasValueGateMaterialConsumerVanillaCacheHits:N0}), " +
                $"{state.AtlasValueGateMaterialConsumerCacheMisses:N0} miss(es), " +
                $"{state.AtlasValueGateMaterialConsumerEntryBuilds:N0} entry build(s)");
            sb.AppendLine(
                $"Atlas value-gate traversal XML parses: " +
                $"WSModel={state.AtlasValueGateGameplayTraversalWsModelXmlParseCount:N0}, " +
                $"material={state.AtlasValueGateGameplayTraversalMaterialXmlParseCount:N0}");
            sb.AppendLine(
                $"Atlas value-gate container resolution activity: " +
                $"{state.AtlasValueGateContainerResolutionScans:N0} scan(s), " +
                $"{state.AtlasValueGateContainerResolutionCacheHits:N0} cache hit(s)");
            var transformedAtlasRoots = state.AtlasedMeshes
                .Select(entry => entry.RootVmdPath)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Count();
            sb.AppendLine($"Mesh parts atlased/remapped: {state.ProcessedMeshes.Count}");
            sb.AppendLine(
                $"Atlas VMD roots with atlased mesh parts: {transformedAtlasRoots:N0} / " +
                $"{state.AtlasVmdRootCount:N0}");
            sb.AppendLine($"Modified rigid meshes: {state.ModifiedRigids.Count:N0}");
            sb.AppendLine($"Modified WSModels: {state.ModifiedWsModels.Count:N0}");
            sb.AppendLine($"Mesh parts skipped: {GetEffectiveSkippedMeshCount(state)}");
            sb.AppendLine(
                $"Existing Asset Editor atlas output detected: " +
                $"{(state.ExistingAtlasOutputDetected
                    ? $"YES ({state.ExistingGeneratedAtlasCandidateCount:N0} existing candidate(s) preserved; new candidates remained eligible)"
                    : "NO")}");
            sb.AppendLine($"Atlas textures generated: {state.GeneratedTexturePaths.Count}");
            sb.AppendLine(
                $"Shared physical atlas-page evaluations: {state.SharedAtlasPageSharingEvaluations}");
            sb.AppendLine(
                $"Shared physical atlas pages accepted: {state.SharedAtlasPageCoalescesAccepted}");
            sb.AppendLine(
                $"Batches participating in shared physical pages: " +
                $"{state.SharedAtlasPageParticipatingBatches}");
            sb.AppendLine(
                $"Pixels saved by shared physical atlas pages: " +
                $"{state.SharedAtlasPagePixelsSaved:N0}");
            sb.AppendLine($"Constant-only atlas channels skipped: {state.ConstantOnlyAtlasChannelsSkipped}");
            sb.AppendLine($"Uniform constant source textures detected: {state.UniformConstantTexturePaths.Count}");
            sb.AppendLine(
                $"Uniform constant material assignments canonicalized: " +
                $"{state.UniformConstantTextureAssignmentsCanonicalized}");
            sb.AppendLine($"Large BC split-compression channels: {state.LargeBcSplitCompressionChannels}");
            sb.AppendLine($"Atlas materials generated: {state.GeneratedMaterialPaths.Count}");
            sb.AppendLine($"Atlas material assignments reused: {state.GeneratedMaterialReuses}");
            sb.AppendLine($"Atlas placements generated: {state.AtlasPlacementsGenerated}");
            sb.AppendLine($"Atlas placements reused: {state.AtlasPlacementsReused}");
            sb.AppendLine($"Wrapped-UV placements canonicalized: {state.WrappedUvPlacementsCanonicalized}");
            sb.AppendLine($"UV-island normalized meshes: {state.UvIslandNormalizedMeshes}");
            sb.AppendLine($"UV islands shifted by integer tiles: {state.UvIslandsShifted}");
            sb.AppendLine($"UV-island source crop pixels saved: {state.UvIslandCropPixelsSaved:N0}");
            sb.AppendLine($"Shared UV-island seam groups aligned: {state.SharedUvIslandCutGroups}");
            sb.AppendLine($"Content-deduplicated atlas placements: {state.ContentDeduplicatedAtlasPlacements}");
            sb.AppendLine($"Mesh references remapped by content dedupe: {state.ContentCanonicalizedMeshReferences}");
